window.WHY = {"6u1q9m":{"w":{"المهارات التي ظهرت أول مرة بعد عام 2000":"كثير منها قديم، كالتفكير والتواصل، والجديد هو تزايد الحاجة إليها.","مهارات المعلمين في هذا القرن":"هي مهارات للمتعلمين عامة، لا للمعلمين وحدهم.","المهارات المشتركة بين المناهج الدراسية":"تتقاطع مع المناهج، لكن معيارها الحاجة في الحياة والعمل."}},"kedp79":{"w":{"يميل ذوو المستويات الأدنى منه إلى أداء أفضل":"هذا عكس ما تشير إليه الدراسات.","لا توجد علاقة بينهما":"الدراسات تشير إلى وجود ارتباط إيجابي.","يظهر الارتباط في مرحلة المراهقة فقط":"الارتباط لا يقتصر على مرحلة عمرية واحدة."}},"d8v201":{"w":{"تكرار قراءة المعلومات حتى تُحفظ":"التكرار الآلي معالجة سطحية.","تقديم حقائق إضافية عن الموضوع":"كثرة الحقائق تزيد الكم، ولا تعني عمق الفهم.","إعطاؤهم معززات متنوعة عند الإجابة":"التعزيز يرفع الدافعية، لكنه لا يعمّق المعالجة بذاته."}},"ye8tq":{"w":{"قانون التدريب":"التدريب يقوي الرابطة بالتكرار، ولا تكرار في الموقف.","قانون الاستعداد":"الاستعداد يخص تهيؤ المتعلم قبل الموقف.","قانون الانتماء":"الانتماء يعني أن الرابطة تقوى حين تبدو الاستجابة منتمية إلى الموقف، ولا يفسر امتداد الأثر إلى مجالات أخرى."}},"l5y7wo":{"w":{"الخوف من فقد الهيبة":"الخائف على هيبته يرد غالباً بانفعال أمام الطلاب.","الجهل بحقوقه":"تأجيل الحديث لا علاقة له بمعرفة الحقوق.","تجاهل السلوك":"لم يتجاهل السلوك، بل عالجه بعد الحصة."}},"1f6dusy":{"w":{"المسؤولية الفردية":"المسؤولية الفردية محاسبة كل طالب على جزئه، لا ربط مصيرهم.","التفاعل المباشر":"التفاعل المباشر هو التشجيع وجهاً لوجه أثناء العمل.","المهارات الاجتماعية":"المهارات الاجتماعية مهارات الحوار والقيادة وحل الخلاف."}},"1b6b53v":{"w":{"الانتقال من الحقائق الجزئية إلى المفاهيم العامة":"هذا اتجاه استقرائي، وأوزوبل يبدأ من العام.","مقارنة المفاهيم لتحديد أوجه الشبه والاختلاف":"المقارنة أقرب إلى التوفيق التكاملي.","دمج المفاهيم المختلفة في كل متكامل":"الدمج هو التوفيق التكاملي، وهو مبدأ آخر عنده."}},"1nd3bc":{"w":{"لأن الأهل يتدخلون فيها بسرعة أكبر":"سرعة تدخل الأهل غير مرتبطة بطبيعته الإلكترونية.","لأنها لا تحدث خلال اليوم الدراسي":"قد يحدث في أي وقت، ومنه اليوم الدراسي.","لأن الطلاب يتجاهلونها بسهولة":"الطلاب لا يتجاهلونه بسهولة، وأثره النفسي كبير."}},"1b7w4s9":{"w":{"تقديم المعلومات كلها دفعة واحدة":"الدفعة الواحدة ترهق الذاكرة العاملة.","التركيز على المفاهيم المجردة دون أمثلة":"غياب الأمثلة يزيد الجهد اللازم للفهم.","الإكثار من الحفظ قبل الفهم":"الحفظ دون فهم يستهلك الذاكرة ولا يبني معنى."}},"5pvtx9":{"w":{"تحديد الأهداف":"تحديد الأهداف مرحلة أساسية من التصميم.","وضع الاستراتيجيات":"اختيار الاستراتيجيات من صلب مرحلة التصميم.","التقويم":"التقويم مرحلة تتخلل التصميم وتختمه."}},"fdcswv":{"w":{"بدء الدرس مباشرة دون ذكر التأخر":"تجاهل التأخر يضعف قدوته في احترام الوقت.","تبرير تأخره بالتفصيل للطلاب":"التفصيل يضيع وقت الطلاب ولا يفيدهم.","تمديد الحصة بعد الجرس لتعويضهم":"التمديد يأخذ من راحتهم أو من الحصة التالية، فيزيد المشكلة."}},"1w0qek9":{"w":{"المعرفي":"المعرفي يركز على عمليات التفكير والمعالجة داخل الفرد.","السلوكي":"السلوكي يعتمد على التعزيز والتكرار.","الإنساني":"الإنساني يعنى بالجوانب الوجدانية والشخصية للمتعلم، والنشاط هنا يقوم على التفاعل بين الطلاب."}},"m6b43g":{"w":{"المعلم وطلابه":"مادة المعلم وطلابه تتناول علاقته المباشرة بطلابه كالعدل بينهم والقدوة، أما الانتماء للوطن والتفاعل مع الثقافات فبُعد مجتمعي أوسع.","المعلم والأسرة":"مادة المعلم والأسرة، كما يدل اسمها، تخص علاقته بأسر طلابه، والبند هنا عن الانتماء للوطن والتفاعل مع الثقافات وهو شأن المجتمع كله.","المعلم والمجتمع المدرسي":"المجتمع المدرسي زملاء المعلم وإدارة مدرسته، والانتماء للدين والوطن والتفاعل مع الثقافات الأخرى يتجاوز المدرسة إلى المجتمع الأوسع."},"e":"هذا البند هو أول بنود مادة «المعلم والمجتمع»."},"1uvto8z":{"w":{"يسبق مرحلة النمو ليسرّعها":"تسريع النمو بالتعليم فكرة تُنسب إلى برونر، وبياجيه يرى أن الطفل لا يتعلم ما يتجاوز بنيته المعرفية، فالتعليم قبل الاستعداد يضيع الجهد.","يعتمد على التكرار والتعزيز":"التكرار والتعزيز أساس النظرية السلوكية عند سكنر، وبياجيه معرفي يرى أن الطفل يبني معرفته بنفسه وفق مرحلته.","يركز على التلقين المباشر":"التلقين يجعل الطالب متلقياً سلبياً، وبياجيه يرى أن الطفل يبني معرفته بنفسه بالخبرة والتفاعل المناسبين لمرحلته."},"e":"بياجيه يرى أن الطفل لا يتعلم ما يتجاوز بنيته المعرفية، فالتعليم يُبنى على المرحلة الحالية."},"elqe2f":{"w":{"إزالة القلق تماماً عند الاثنين":"انعدام القلق هو حال الطالب الأول وسبب ضعفه، فالأداء الأمثل عند استثارة متوسطة لا عند غيابها.","زيادة القلق عند الاثنين":"رفع القلق يناسب الطالب اللامبالي وحده، أما الثاني فقلقه مرتفع أصلاً، وزيادته تبعده أكثر عن المستوى المتوسط الأمثل.","تجاهل عامل القلق":"قانون يركس–دودسون يربط الأداء بمستوى الاستثارة، وتجاهل القلق يُبقي الأول في لامبالاته والثاني في ارتباكه."}},"1hyhn0u":{"w":{"حرمان بيئي في الطفولة":"الحرمان البيئي يؤثر في النمو بعد الولادة، أما متلازمة داون فخلل كروموسومي يولد به الطفل ولا تسببه البيئة.","إصابة في الرأس بعد الولادة":"إصابة الرأس سبب مكتسب لبعض الاضطرابات كالحبسة الكلامية، ومتلازمة داون خلل كروموسومي يولد به الطفل لا إصابة لاحقة.","سوء تغذية الأم فقط":"سوء تغذية الأم يضر بنمو الجنين، لكنه لا يُحدث الخلل الكروموسومي الذي تنشأ عنه متلازمة داون."}},"1zr1n0":{"w":{"برامج التدريب والممارسة":"التدريب والممارسة يثبت مهارة سبق تعلمها بتمارين متكررة، ولا يمثل تجربة خطرة يتعذر إجراؤها في المختبر.","الألعاب التعليمية":"الألعاب التعليمية تقوم على التنافس والتشويق لتعلم مفهوم أو مهارة، والمطلوب هنا تمثيل تجربة خطرة بأمان.","برامج الاستقصاء":"برمجيات الاستقصاء توجه الطالب إلى البحث وجمع المعلومات للوصول إلى إجابة، لا إلى أداء تجربة خطرة في بيئة آمنة."},"e":"المحاكاة تمثل المواقف الخطرة أو المكلفة بأمان."},"cfbv68":{"w":{"التقارب الزماني (تزامن الصوت والصورة)":"التقارب الزماني يعني عرض الصوت مع الصورة المرتبطة به في الوقت نفسه، ومشكلة المعلم هنا إضافة موسيقى وصور لا علاقة لها بالدرس.","الشخصنة (لغة حوارية)":"الشخصنة مخاطبة المتعلم بأسلوب حواري بدل الرسمي، والخلل هنا مواد زائدة لا علاقة لها بالدرس شتتت الطلاب.","الإشارة (إبراز المهم)":"مبدأ الإشارة يبرز المعلومات المهمة بعلامات كالأسهم والتلوين، ومشكلة المعلم هنا ليست غياب الإبراز بل إضافة زخارف وموسيقى غير مرتبطة."},"e":"مبدأ الاتساق يقضي بحذف الكلمات والصور والأصوات غير المرتبطة لأنها تستهلك الذاكرة العاملة."},"shnn6c":{"w":{"التوجيهية":"التهيئة التوجيهية توجه انتباه الطلاب إلى موضوع الدرس في بدايته، وهنا جاء الربط في منتصف الدرس بين جزأيه.","الحافزة":"التهيئة الحافزة تثير الاهتمام بسؤال مشوق أو موقف محير، وما قدمه المعلم ربط بين جزء سابق وجزء لاحق.","التقويمية":"التهيئة التقويمية تتأكد من فهم الطلاب للسابق قبل البناء عليه، والمعلم هنا لم يقس فهمهم بل وضّح علاقة الجزأين."},"e":"التهيئة الانتقالية تُستخدم للانتقال السلس بين أجزاء الدرس."},"124mf6v":{"w":{"أن تكون فورية":"التغذية الراجعة الفعالة تصل في وقتها، وغالباً فوراً أو قريباً من الأداء والعمل حاضر في ذهن الطالب، فهي من خصائصها. أما الثناء العام فلا يفيد الطالب في أي وقت جاء.","أن تكون محددة ووصفية":"التحديد والوصف يبينان للطالب ما أحسنه وما يحتاج تحسينه، وهذا عكس الثناء العام، فهما من خصائص التغذية الفعالة.","أن تركز على المهمة لا على شخص الطالب":"التركيز على العمل لا على ذات الطالب من خصائص التغذية الراجعة الجيدة، لأنه يرشده إلى ما يُصحَّح دون أن يمس شخصه."},"e":"التغذية الراجعة العامة لا تخبر الطالب ماذا أحسن وماذا يحسّن."},"rhz6qu":{"w":{"وصفاً عاماً لما ينبغي أن يتعلمه المتعلم في المجال":"الوصف العام لما ينبغي تعلمه في كل مجال هو تعريف معايير المحتوى، أما معايير الأداء فنواتج التعلم المتوقعة نهاية كل صف.","معايير تقويم أداء المعلم في الفصل":"الأداء هنا أداء المتعلم لا المعلم، فمعايير المناهج تصف ما يتعلمه الطالب، وللمعلم معايير مهنية مستقلة يُقوَّم بها.","الحد الأدنى لدرجة النجاح في المادة":"درجة النجاح تحددها لائحة تقويم الطالب، ومعايير الأداء تصف نواتج تعلم متوقعة في نهاية كل صف لا رقماً للنجاح."}},"187mckq":{"w":{"كف المعلم السلوكيات غير المناسبة في وقت مبكر":"كف السلوك في بدايته تدخل مباشر لإيقافه، أما الانطفاء فلا تدخل فيه بل حجب للانتباه عن السلوك حتى يتلاشى.","تأنيب المعلم للمتعلم الذي أصدر السلوك منفرداً":"التأنيب عقاب موجب يضيف مثيراً مزعجاً ولو كان على انفراد، والانطفاء لا يضيف شيئاً بل يحجب التعزيز عن السلوك.","إبعاد المتعلم الذي أصدر السلوك من الموقف التعليمي":"إبعاد الطالب عن الموقف إقصاء، وهو عقاب سالب يسحب منه النشاط، أما الانطفاء فتجاهل مقصود يبقيه في مكانه."},"e":"الانطفاء حجب التعزيز عن السلوك فيتلاشى، وأبرز صوره التجاهل المقصود."},"8oz9kj":{"w":{"التداخل":"التداخل معالجة أمرين معاً دون إيقاف الدرس، أما متابعة كل الأركان والتدخل عند أول بوادر التشويش فوعي شامل بما يجري.","الزخم":"الزخم أن يسير الدرس بإيقاع مستمر بلا توقف أو بطء، والوصف هنا عن رصد المعلم لما يجري في الصف لا عن سرعة الدرس.","أثر الموجة":"أثر الموجة امتداد أثر تصحيح المعلم لطالب إلى زملائه المشاهدين، والموقف هنا عن رصد بوادر التشويش مبكراً لا عن انتقال أثر التصحيح."},"e":"اليقظة withitness هي إدراك كل ما يحدث وإشعار الطلاب بذلك."},"1qt1csv":{"w":{"عامة ومؤجلة":"العامة لا تحدد للطالب ما أحسنه وما يحسّنه، والمؤجلة يضعف أثرها، فكلتاهما عكس خصائص التغذية الراجعة الفعالة.","مركزة على شخصية الطالب":"التغذية الفعالة تركز على المهمة لا على شخص الطالب، فالحكم على شخصيته لا يرشده إلى ما يحسّنه في عمله.","مقتصرة على الدرجة الرقمية":"الدرجة وحدها تخبر الطالب بمستواه دون أن تبين نقاط قوته وما يحتاج تحسينه، والتغذية الفعالة تعليق محدد ووصفي."},"e":"التغذية الراجعة الفعالة تأتي في وقتها (فورية غالباً) وتتكرر مع التعلم، وتغطي جوانب الأداء المهمة قوةً وضعفاً بعبارة موجزة محددة، وتركز على المهمة لا على شخص الطالب."},"1ij78f9":{"w":{"يطلب منه عدم المقاطعة لأن الدرس ليس للمقارنة بين الوطن والأمة":"إسكات الطالب بحجة المقاطعة يضيّع فرصة حوار تربوي، فسؤاله نفسه يتيح للمعلم أن يبين أن حب الوطن لا يتعارض مع الانتماء للأمة.","يبين له أن مصطلح الأمة غير واقعي ويفرق أكثر مما يجمع":"نفي واقعية الأمة يهدم أحد الانتماءين ويناقض الوسطية، فحب الوطن لا يتعارض مع الانتماء للأمة ولا يُطلب من الطالب الاختيار بينهما.","يوضح له أنه منساق لأفكار لا تنفعه وعليه الصمت":"اتهام الطالب وأمره بالصمت يغلق الحوار ويستخف بسؤاله، وتعزيز الهوية يكون بالحوار الهادئ والشواهد لا بالإسكات."},"e":"تعزيز الهوية يكون بالحوار الهادئ والشواهد التي تجمع لا تفرق."},"95ao9e":{"w":{"يستمر في الشرح حتى لا يضيع وقت الحصة":"الاستمرار في الشرح يضيّع موقفاً تربوياً لنمذجة القيمة، والقدوة هنا أن يرى الطلاب معلمهم يتوقف ويردد الأذان.","يروي لهم قصة قصيرة عن فضل الأذان":"القصة كلام عن القيمة لا فعل لها، والقدوة الحسنة سلوك عملي يراه الطلاب في توقف المعلم وترديده الأذان معهم.","يذكّرهم بواجب المسلم تجاه الأذان ثم يكمل الشرح":"هذا وعظ لفظي يخالفه الفعل حين يعود المعلم إلى الشرح، والقدوة أن يرى الطلاب معلمهم يتوقف ويردد الأذان بنفسه."},"e":"القدوة سلوك عملي يراه الطلاب، فالتوقف عن الشرح وترديد الأذان معهم نمذجة مباشرة للقيمة."},"d8ddqf":{"w":{"التوسط بين الطلاب عند الخلاف":"التوسط عند الخلاف إصلاح بين متخاصمين، أما الوسطية في الميثاق فمنهج اعتدال بين طرفي الغلو والتفريط.","اختيار الرأي الذي يرضي أغلبية الطلاب":"إرضاء الأغلبية ميوعة لا وسطية، فالوسطية اعتدال منضبط بين الزيادة والتقصير، لا اتباع لرأي الأكثرية.","الامتناع عن الحديث في أمور الدين داخل الصف":"ترك الحديث في الدين يناقض رسالة التعليم، فالثوابت تُعلَّم بوضوح، والحياد خاص بالمسائل الخلافية، والوسطية اعتدال لا امتناع."},"e":"الوسطية موقف بين طرفين: الغلو (الزيادة) والتفريط (التقصير)."},"12iyg9v":{"w":{"المشرف التربوي في زياراته":"المشرف التربوي رقابة خارجية تقتصر على أوقات زياراته، والميثاق يقدّم عليها الرقابة الذاتية النابعة من ضمير المعلم اليقظ.","مدير المدرسة ووكيلها":"المدير والوكيل رقابة إدارية خارجية، والميثاق يقدّم عليها الرقابة الذاتية التي تعمل حتى في غياب أي رقيب خارجي.","تقويم الأداء الوظيفي":"تقويم الأداء أداة رقابة خارجية دورية، والميثاق يجعل الرقيب الأول بعد الله ضمير المعلم وحسه الناقد لا أي جهة خارجية."},"e":"الميثاق يقدم الرقابة الذاتية على كل رقابة خارجية مهما تنوعت أساليبها."},"cra8u6":{"w":{"إلقاء موعظة عن واجب حب الوطن":"الموعظة توجيه لفظي مباشر، والهوية تُعزَّز بالشواهد والمنجزات المرتبطة بالدرس لأنها تقنع العقل وتحرك الوجدان.","تكليف الطلاب بحفظ عبارات عن الوطن":"حفظ العبارات تلقين قد يردده الطالب دون اقتناع، أما الشواهد والإحصاءات المرتبطة بالدرس فتبني قناعة حقيقية بالوطن.","تعليق صور الرموز الوطنية في الصف":"تعليق صور الرموز وسيلة شكلية تابعة لا غاية، والأكثر فاعلية شواهد ومنجزات وطنية مرتبطة بموضوع الدرس."},"e":"تعزيز الهوية يكون بالشواهد لا بالوعظ؛ الحقائق والمنجزات تقنع العقل وتحرك الوجدان."},"1f9pz2m":{"w":{"الوعظ المباشر":"الوعظ المباشر نصح وتذكير لفظي، والمعلم هنا لم يعظ بل عرض وثائق ومصادر تثبت المعلومة الصحيحة، وهذا أسلوب الشواهد.","التلقين والتكرار":"التلقين ترديد المعلومة حتى تُحفظ، والمعلم هنا لم يكرر بل صحح المعلومة المغلوطة بعرض الوثائق والمصادر.","الترهيب والتخويف":"الترهيب يعتمد على التخويف من العاقبة، والسؤال يصف معلماً يقنع طالبه بالوثائق والمصادر لا بالتهديد."},"e":"عرض الوثائق شاهد يقنع ويبني الهوية على المعرفة."},"uexhuy":{"w":{"الغلو":"الغلو هو الزيادة حتى التشدد، أما التهاون في تطبيق القيم بحجة التيسير فتقصير، وهو الطرف المقابل أي التفريط.","الوسطية":"الوسطية اعتدال بين الغلو والتفريط، والتهاون في تطبيق القيم ميل إلى طرف التقصير لا اعتدال.","الحياد":"الحياد موقف المعلم في القضايا الخلافية بألا يفرض رأيه، ولا علاقة له بالتهاون في تطبيق القيم."},"e":"التفريط هو التقصير والتهاون، وهو الطرف المقابل للغلو."},"119ec8y":{"w":{"الاستقبال":"الاستقبال أدنى المستويات، وفيه ينتبه الطالب للقيمة ويصغي إليها فقط، والسؤال عن قيمة صارت سلوكاً تلقائياً في شخصيته.","الاستجابة":"الاستجابة ثاني المستويات، وفيها يشارك الطالب ويتفاعل مع القيمة، أما التصرف بها تلقائياً كجزء من شخصيته فأعلى السلّم.","التنظيم القيمي":"التنظيم ترتيب القيم في نسق واحد، وهو يسبق تمثّل القيمة الذي تصبح فيه طابعاً ثابتاً يتصرف به الطالب تلقائياً."},"e":"أعلى مستويات المجال الوجداني أن تصبح القيمة طابعاً للشخصية."},"27zr80":{"w":{"الهدر الإداري":"وصف «الإداري» يحصر الخسارة في الإدارة وإجراءاتها، والسؤال عن خسارة النظام بسبب رسوب الطلاب وتسربهم، وهذا هو الفاقد التعليمي.","التأخر الدراسي":"التأخر الدراسي حالة طالب بعينه يقل تحصيله عن أقرانه، والسؤال عن خسارة النظام كله بسبب الرسوب والتسرب.","الفجوة المعرفية":"الفجوة المعرفية فرق بين ما يعرفه الطالب وما ينبغي أن يعرفه، لا خسارة النظام الناتجة عن الرسوب والتسرب."},"e":"الفاقد التعليمي هو ما يخسره النظام بسبب الرسوب والتسرب وله آثار اجتماعية واقتصادية."},"y67t7y":{"w":{"إجازة مرضية":"الإجازة المرضية تتطلب تقريراً طبياً يثبت المرض، والسؤال لم يذكر مرضاً بل ظرفاً طارئاً ليوم واحد لا يحتمل التأجيل.","إجازة صيفية":"الإجازة الصيفية هي الإجازة السنوية لشاغلي الوظائف التعليمية بعد نهاية العام الدراسي، ولا يتغيب بها المعلم يوماً لظرف طارئ.","إجازة استثنائية":"الإجازة الاستثنائية تكون بلا راتب لظروف خاصة تطول مدتها، أما يوم واحد لظرف طارئ فتكفيه الإجازة الاضطرارية."},"e":"الإجازة الاضطرارية تُمنح للظروف الطارئة بحد لا يتجاوز خمسة أيام في السنة."},"tqz26h":{"w":{"توجيه الرعاية الأكبر للموهوبين والنابغين":"تقديم الموهوبين على غيرهم تفضيل لفئة واحدة، والوثيقة تجعل رعاية ذوي الاحتياجات شاملة بخطة مدروسة لكل فرع دون تفضيل.","إعطاء الأولوية للمعاقين ذهنياً":"الوثيقة تذكر المعوقين جسمياً وعقلياً معاً وتضع خطة مدروسة لكل فرع، فلا أولوية للإعاقة الذهنية على غيرها.","ترك رعايتهم للمؤسسات الأهلية":"الوثيقة تجعل تعليمهم من عناية الدولة بمناهج خاصة، فإسناد رعايتهم إلى القطاع الأهلي وحده يخالف نصها."},"e":"الوثيقة تنص على التربية الخاصة والعناية بالمعوقين جسمياً أو عقلياً (المادة 56)، وتُعنى الدولة بتعليمهم ذهنياً أو جسمياً بمناهج خاصة (المادة 188)، وتضع الجهات المختصة خطة مدروسة لكل فرع (المادة 191): أي رعاية شاملة بلا تفضيل فئة."},"7x9anv":{"w":{"وزارة التعليم":"وزارة التعليم جهة التوظيف التي يعمل فيها المعلم، أما إصدار الرخصة المهنية فتختص به هيئة تقويم التعليم والتدريب.","إدارة التعليم بالمنطقة":"إدارة التعليم بالمنطقة جهة تنفيذية تابعة للوزارة تدير المدارس، ولا تصدر الرخصة المهنية التي تختص بها الهيئة.","المعهد الوطني للتطوير المهني التعليمي":"المعهد الوطني يقدم برامج التدريب والتطوير المهني للمعلمين، ولا يصدر الرخصة التي تختص بها هيئة تقويم التعليم والتدريب."},"e":"اللائحة تعرّف الرخصة بأنها وثيقة تصدرها الهيئة وفق معايير محددة."},"4qkynv":{"w":{"معلم خبير":"رتبة خبير تتطلب 80 في الاختبارين معاً، ودرجة التخصص هنا 74، فلا يبلغها وإن تجاوز 80 في التربوي العام.","معلم ممارس":"الممارس يكفيه 50 في الاختبارين، والدرجة الأدنى هنا 74 تتجاوز حد المتقدم وهو 70، فالممارس ليس أعلى ما يبلغه.","معلم خبير بعد سنة":"مرور سنة لا يغيّر درجة الاختبار، والخبير يشترط 80 في الاختبارين معاً، ودرجة التخصص 74 دون هذا الحد."}},"13072ny":{"w":{"24 حصة":"النصاب 24 حصة للمعلم الممارس، والنصاب يقل بارتفاع الرتبة حتى يصل إلى 18 حصة للخبير.","22 حصة":"النصاب 22 حصة للمعلم المتقدم، والخبير أعلى منه رتبة فنصابه أقل، وهو 18 حصة أسبوعياً.","20 حصة":"الرقم 20 لا يطابق نصاب أي من الرتب الثلاث: 24 للممارس و 22 للمتقدم و 18 للخبير."}},"1lp9erq":{"w":{"الحصص الصفية":"الحصص الصفية هي الحصص التدريسية نفسها التي يُجمع منها النصاب، والتعريف هنا عن مجموعها الواجب أسبوعياً، وهو النصاب التعليمي.","الحصص الزائدة":"الحصص الزائدة ما يُكلَّف به المعلم بعد استيفاء نصابه وبموافقته، فهي فوق الواجب لا مجموع الحصص الواجبة عليه.","الحصص الاحتياطية":"الحصص الاحتياطية تُسند لتغطية غياب معلم آخر، والتعريف المذكور عن مجموع الحصص الواجبة على المعلم أسبوعياً، وهو النصاب التعليمي."},"e":"هذا تعريف «النصاب التعليمي» نصاً في المادة الأولى من لائحة الوظائف التعليمية (بتعديلات 1446)، ويختلف بالرتبة: 24 حصة للممارس، و22 للمتقدم، و18 للخبير (المادة 9). والمشاركة في التخطيط والتقويم وإدارة الأنشطة والتطوير المهني التزام إضافي في المادة 9/4."},"1vqiww6":{"w":{"معلم الفصل منفرداً لأنه الأقرب إلى الطالب":"قرب المعلم من الطالب لا يمنحه الانفراد بالقرار، فمخالفة طالب الدمج تعالجها لجنة التوجيه الطلابي بالتنسيق مع قسم ذوي الإعاقة.","مدير المدرسة مباشرة دون الرجوع إلى اللجنة":"تجاوز اللجنة إلى قرار المدير وحده يخالف القواعد التي تسند مخالفة طالب الدمج إلى اللجنة بالتنسيق مع قسم ذوي الإعاقة بالإدارة.","ولي الأمر وحده في المنزل بعد إبلاغه بالمشكلة":"إبلاغ ولي الأمر لا ينقل المعالجة إليه، فمشكلة الطالب السلوكية في المدرسة تعالجها لجنة التوجيه بالتنسيق مع قسم ذوي الإعاقة مراعاةً لخصائصه."},"e":"تنص قواعد السلوك والمواظبة على أن مخالفة الطالب من ذوي الإعاقة في برامج الدمج تتعامل معها لجنة التوجيه الطلابي في المدرسة بالتنسيق مع قسم ذوي الإعاقة في إدارة التعليم، مراعاةً لخصائصه."},"frw4vy":{"w":{"قدوة لطلابه خاصة وللمجتمع عامة":"بند القدوة يخص سلوك المعلم الذي يحاكيه طلابه ومجتمعه، والمخالفة هنا إضاعة وقت الحصة في قضايا لا تخدم تعليمهم.","شريك الوالدين في التربية والتنشئة":"بند الشراكة مع الوالدين يتناول تعاون المعلم مع الأسرة في التربية، والمشكلة هنا تحويل الحصة إلى منبر لقضايا خارج التعليم.","أمين على كيان الوطن ووحدته":"بند الأمانة على الوطن يتعلق بحفظ وحدته وأمنه، والسؤال لا يذكر مساساً بذلك، بل إهدار وقت الحصة في غير التعليم."}},"12o00as":{"w":{"خيار شخصي مرتبط برغبة المعلم واهتمامه":"الميثاق يجعل النمو المهني واجباً أساسياً على المعلم نفسه، والواجب لا يُترك لرغبة المعلم واهتمامه الشخصي.","مسؤولية إدارة التعليم وحدها لا المعلم":"إدارة التعليم قد تقدم برامج التطوير، لكن الميثاق يجعل النمو المهني واجباً على المعلم نفسه لا على جهة غيره.","مطلوب للترقية فقط عند التقدم لها":"النمو المهني في الميثاق واجب مستمر والثقافة الذاتية منهج حياة، فلا يقتصر على وقت التقدم للترقية."},"e":"المادة الرابعة تجعل النمو المهني واجباً أساسياً على المعلم نفسه."},"1ujkmi1":{"w":{"أن يجتاز اختبار قبول تجريه المدرسة":"قواعد القبول المعلنة لا تذكر اختبار قبول لهذا الاستثناء، فالشرط المعلن إتمام سنة في رياض الأطفال.","موافقة ولي الأمر الكتابية فقط":"موافقة ولي الأمر وحدها لا تكفي للقبول المبكر، فالشرط المعلن أن يكون الطفل قد أتم سنة في رياض الأطفال.","أن يكون له أخ مسجّل في المدرسة نفسها":"وجود أخ في المدرسة لا صلة له بشرط هذا الاستثناء، فالقواعد تربط قبول الأصغر سناً بإتمام سنة في رياض الأطفال."},"e":"أعلنت وزارة التعليم لعام 1448هـ قبول من أكمل ست سنوات حتى 24 أغسطس 2020م، وقبول مواليد 25 أغسطس إلى 22 نوفمبر 2020م (نحو تسعين يوماً أصغر) بشرط إتمام سنة في رياض الأطفال. فالشرط الروضة."},"ecv56p":{"w":{"تسليمها مباشرة لأنها لغرض البحث العلمي":"الغرض البحثي لا يُسقط سرية بيانات الطلاب، فخروجها لأي جهة خارجية يحتاج إذن الإدارة وقنواتها الرسمية.","رفض أي تعاون مع الجهات الخارجية":"الرفض المطلق يعطل التعاون البحثي المشروع، والنظام لا يمنع تسليم البيانات بل يشترط مرورها عبر الإدارة وقنواتها الرسمية.","تسليمها بعد حذف الأسماء دون الرجوع للإدارة":"حذف الأسماء لا يغني عن إذن الإدارة، فقرار إخراج بيانات الطلاب لجهة خارجية ليس من صلاحية المعلم وحده."},"e":"بيانات الطلاب لا تخرج إلا بإذن الإدارة ووفق النظام."},"z40tbj":{"w":{"لا يجوز قبوله بأي حال":"نقص الأربعين يوماً داخل حد الاستثناء وهو 90 يوماً، فالمنع المطلق يتجاهل هذا الاستثناء المعتمد في قواعد القبول.","يُقبل مباشرة مثل أقرانه":"قبوله استثناء لا حق مباشر، فالأولوية لمن أتموا السادسة، ويُشترط له إتمام عام كامل في رياض الأطفال.","يُقبل بعد اجتياز اختبار ذكاء":"قواعد القبول لا تشترط اختبار ذكاء، والاستثناء لمن يصغر بحدود 90 يوماً مشروط بإتمام سنة في رياض الأطفال."},"e":"الأربعون يوماً داخل حد الاستثناء (90 يوماً)، فيجوز قبوله استثناءً لا مباشرةً مثل أقرانه، والأولوية لمن أتموا السادسة. وفي إعلان الوزارة لتسجيل 1448 يُشترط لهذا الاستثناء أن يكون الطفل قد أتم عاماً دراسياً كاملاً في رياض الأطفال."},"15adu2v":{"w":{"الرخصة المهنية":"الرخصة المهنية وثيقة تصدرها الهيئة لمن يستوفي المعايير، أما ما يجب على المعلم معرفته وممارسته فهو المعايير نفسها.","النصاب التعليمي":"النصاب التعليمي مجموع الحصص الواجبة على المعلم أسبوعياً، لا ما يجب أن يعرفه ويمارسه وفق قيم المهنة.","التطوير المهني":"التطوير المهني عملية مستمرة يرتقي بها المعلم نحو المعايير، أما التعريف هنا فيصف المعايير التي يجب معرفتها وممارستها."},"e":"هذا تعريف المعايير المهنية الصادرة عن الهيئة."},"r4l0hh":{"w":{"مجتمعات التعلم المهنية الافتراضية":"مجتمعات التعلم الافتراضية تلتقي عن بعد عبر الشبكة، والزيارات الصفية المتبادلة حضورية داخل الفصول.","أخلاقيات مهنة التعليم":"أخلاقيات المهنة قيم ومبادئ تضبط سلوك المعلم، والزيارات المتبادلة أسلوب عملي لتطوير الأداء لا مبدأ أخلاقي.","تحقيق مفهوم المدرسة المتعلمة":"المدرسة المتعلمة مفهوم أوسع يشمل المؤسسة كلها وثقافتها، والزيارات المتبادلة أسلوب واحد مباشر لتطوير أداء المعلمين."},"e":"الزيارات أسلوب مباشر لتطوير الأداء."},"1amaxa0":{"w":{"الزيارات المتبادلة":"الزيارات المتبادلة أسلوب إشرافي يزور فيه المعلم زميله ويتبادلان الخبرة، فيقوم على طرف آخر وتنظيم من المدرسة، والذاتي يقوم به المعلم وحده كالتعليم المبرمج.","الاجتماعات المهنية":"الاجتماعات المهنية أسلوب جماعي يشترك فيه المعلمون بتنظيم من المدرسة أو المشرف، أما الأسلوب الذاتي فيقوم به المعلم وحده كالتعليم المبرمج.","الدرس النموذجي":"الدرس النموذجي أسلوب إشرافي يعرض فيه معلم متميز أو مشرف طريقة تدريس أمام زملائه، فالمعلم فيه متلقٍّ لا يقود تطوره وحده."},"e":"الأسلوب الذاتي في التطوير المهني يقوم به المعلم وحده وبمبادرته وبحسب سرعته، مثل القراءة الحرة والتعليم المبرمج والحقائب التدريبية. أما الزيارات المتبادلة والاجتماعات المهنية والدروس النموذجية (التطبيقية) فمن الأساليب الإشرافية الجماعية التي تنظمها المدرسة أو المشرف ويشترك فيها أكثر من معلم."},"mqdb9s":{"w":{"تسهم في اعتياده على عملية التقويم وإحساسه بالراحة فيها":"الاعتياد على التقويم والراحة فيه أثر جانبي للزيارات، أما حاجة المعلم الجديد الأساسية فهي الخبرة بأساليب التدريس.","تساعده على تطبيق المبادئ التدريسية بفاعلية في جو الفصل":"تطبيق المبادئ بفاعلية نتيجة تأتي بعد اكتساب الخبرة، وأهم ما ينقص المعلم الجديد ويطلبه من الزيارة المعرفة بالأساليب المتنوعة.","توصل لزملائه رغبته في أن يكون عضواً فاعلاً في الفريق":"إظهار الرغبة في العمل ضمن الفريق فائدة اجتماعية ثانوية، وغاية المعلم من طلب الزيارة والنقد تطوير أساليبه في التدريس."},"e":"سؤال من دليل الهيئة: المعلم الجديد يفتقر إلى الخبرة بالأساليب، وزيارة الخبراء تطلعه على الأساليب الناجحة."},"11a4fh3":{"w":{"رسالة ودية":"الرسالة الودية تناسب التواصل الشخصي بين الزملاء، أما طلب تجهيز المعمل فطلب رسمي يحتاج خطاباً يُوثق وتتابعه الإدارة.","حديث شفهي في الممر":"الحديث العابر في الممر لا يترك أثراً مكتوباً، وطلب تجهيز المعمل يحتاج توثيقاً رسمياً حتى تتابعه الإدارة وترد عليه.","رسالة نصية عبر الجوال":"الرسالة النصية وسيلة سريعة للتنبيه غير الرسمي، ولا تحمل عناصر الخطاب الإداري التي تجعل طلب تجهيز المعمل موثقاً قابلاً للمتابعة."},"e":"مخاطبة الإدارة والجهات الرسمية تكون بخطاب إداري بعناصره الرسمية ليُوثق ويُتابع."},"pe12fw":{"w":{"Microsoft Excel":"برنامج جداول بيانات لتنظيم الأرقام وحسابها كرصد الدرجات، ولا يوفر مساحة مشتركة للنقاش بين المعلم والطلاب وأولياء الأمور.","Microsoft Access":"برنامج لبناء قواعد البيانات وإدارة السجلات، يفيد في تنظيم المعلومات لكنه ليس مساحة تواصل ونقاش بين أطراف العملية التعليمية.","Canva":"أداة لتصميم الملصقات والعروض، غرضها إنتاج المواد البصرية لا توفير مساحة نقاش مخصصة بين المعلم والطلاب وأولياء الأمور."},"e":"School Circle منصة تواصل وتشارك ملفات بين أطراف العملية التعليمية."},"1iv4hvl":{"w":{"تقديم معلومات لولي الأمر عن خدمات تدريس ذوي صعوبات التعلم":"الحديث عن خدمات ذوي صعوبات التعلم سابق لأوانه، فولي الأمر يسأل هل يعاني ابنه صعوبة أصلاً، والحكم في ذلك للمختص بالتشخيص لا للمعلم.","مناقشة التدخلات النظامية ودور ولي الأمر في المتابعة مع المعلم":"مناقشة التدخلات النظامية تفترض أن الصعوبة ثبتت بالتشخيص، وهذا لم يحدث بعد، فالخطوة الأولى إحالة السؤال إلى المختص.","توصية ولي الأمر بمراقبة واجبات ابنه وعاداته السلوكية":"مراقبة الواجبات والسلوك نصيحة عامة لا تجيب عن سؤال ولي الأمر، فوجود صعوبة تعلم يحدده مختص بالتشخيص لا ملاحظة الأسرة."},"e":"السؤال مأخوذ من دليل الاختبار العام للمعلمين (قياس 1436، السؤال 2) ومفتاحه في الدليل: اجتماع يضم ولي الأمر والمختص في صعوبات التعلم بالمدرسة. فتحديد وجود صعوبة تعلم يحتاج تشخيصاً من مختص بعد موافقة ولي الأمر، وليس من صلاحية المعلم أن يجيب بنعم أو لا عبر البريد."},"14wiz9m":{"w":{"مكافأة المعلمين الذين يستخدمون طرقاً فعالة":"مكافأة المعلمين تحفيز إداري، ولقاءات مجتمع التعلم غايتها تحسين تعلم الطلاب المتعثرين في الرياضيات لا تقييم المعلمين ومكافأتهم.","التأكيد على أن بعض المعلمين أفضل من غيرهم":"المفاضلة بين المعلمين تناقض ثقافة التعاون في مجتمع التعلم، فالمعلمون هنا يتشاركون الاستراتيجيات لمساعدة الطلاب لا ليقارنوا بينهم.","تبادل الآراء حول إزالة الشعور بالإحباط لديهم":"إزالة إحباط المعلمين تركز على المعلم نفسه، بينما اللقاء يناقش استراتيجيات لمساعدة الطلاب، فأثره المقصود في تعلم الطالب."},"e":"سؤال من دليل الهيئة (3.1): مجتمع التعلم يركز على تعلم الطلاب."},"qj1oij":{"w":{"اللقاءات الدورية مع أولياء الأمور":"لقاءات أولياء الأمور تخدم الشراكة مع الأسرة في متابعة الطالب، ولا تقوم على تبادل الخبرات التدريسية بين المعلمين لتنمية أدائهم المهني.","التنافس في العطاء بين المعلمين":"التنافس بين المعلمين يناقض ثقافة التعاون، والتكيف مع المواقف المختلفة يأتي من تبادل الخبرات وتجريب الاستراتيجيات معاً باستمرار.","المؤتمرات والورش التربوية":"المؤتمرات والورش تقدم المعرفة في مناسبات متباعدة، أما مجموعات التعلم فلقاءات مستمرة يجرب فيها المعلمون الاستراتيجيات ويتبادلون الخبرة."},"e":"مجتمعات التعلم تتيح تجريب الاستراتيجيات في مواقف مختلفة وتبادل الخبرات باستمرار."},"j2kgpr":{"w":{"خصائص الشراكة المجتمعية بين الأسرة والمدرسة":"خصائص الشراكة تصف طبيعتها كأن تكون تبادلية، أما النص فيعدد أطرافها وشروط نجاحها، وهذه هي مقوماتها.","المسؤولية المجتمعية وعلاقتها بالشراكة المجتمعية":"النص ذكر المسؤولية المتبادلة شرطاً من شروط النجاح ولم يتناول المسؤولية المجتمعية، بل عدّد أطراف الشراكة وشروط نجاحها، وهذه مقوماتها.","متطلبات تفعيل الشراكة بين المدرسة والأسرة":"متطلبات التفعيل إجراءات عملية لتنفيذ الشراكة، والنص لا يذكر إجراءات بل يعدد أطراف الشراكة وأسس نجاحها، وهي مقوماتها."},"e":"الأطراف وشروط النجاح هي مقومات (أركان) الشراكة."},"1lq6jkm":{"w":{"مطبقة داخل المدرسة فقط":"الأنشطة غير الصفية لا تُقصر على داخل المدرسة، فبعضها رحلات وزيارات وخدمة للمجتمع خارج أسوارها.","موحدة للطلاب جميعهم":"توحيد النشاط للجميع يتجاهل الفروق الفردية، والنشاط غير الصفي يقوم على اختيار الطالب ما يناسب ميوله وقدراته.","مقتصرة على محتويات الكتاب المدرسي":"حصر النشاط في محتوى الكتاب يجعله امتداداً للحصة، والنشاط غير الصفي ينطلق من ميول الطلاب واهتماماتهم الأوسع من المقرر."},"e":"فلسفة النشاط غير الصفي تقوم على الميول والطوعية والفروق الفردية."},"4keg3u":{"w":{"استدعاء ولي الأمر عند كل مخالفة يرتكبها ابنه":"ربط الاستدعاء بالمخالفات يجعل ولي الأمر يتجنب المدرسة، وهو معوّق معروف للتواصل، والعلاقة الفاعلة تحتاج رسائل إيجابية دورية.","إرسال تقرير مفصل بأداء الطالب في نهاية العام فقط":"تقرير نهاية العام تواصل متأخر يأتي مرة واحدة، فلا يصنع علاقة مستمرة ولا يتيح لولي الأمر المتابعة أثناء العام.","الاكتفاء بالتواصل مع ولي الأمر عبر الطالب نفسه":"نقل الرسائل عبر الطالب قد يضيعها أو يغيرها، ولا يبني صلة مباشرة بين المدرسة وولي الأمر تقوم عليها الثقة والاستمرار."}},"13j985y":{"w":{"الضمة":"الضمة علامة رفع المضارع المفرد مثل «يرجعُ»، أما المتصل بواو الجماعة فمن الأفعال الخمسة ويُرفع بثبوت النون.","الواو":"الواو هنا ضمير متصل يعود على المخاطبين، أما الواو علامةً للرفع فتكون في جمع المذكر السالم والأسماء الخمسة.","الألف":"الألف علامة رفع المثنى، ولا ألف في «ترجعون» أصلاً، فهو من الأفعال الخمسة يُرفع بثبوت النون."}},"cf7g6z":{"w":{"مفعول به منصوب":"المفعول به يقع عليه فعل الفاعل، و«ابتهج» فعل لازم لا يأخذ مفعولاً به، و«ابتهاجاً» مصدره جاء لتوكيده.","مفعول لأجله منصوب":"المفعول لأجله يبين سبب الفعل وليس من لفظه، و«ابتهاجاً» من لفظ «ابتهجت» جاء لتوكيده.","مفعول معه منصوب":"المفعول معه اسم يأتي بعد واو بمعنى «مع» مثل «سرتُ والنهرَ»، ولا واو معية قبل «ابتهاجاً»."},"e":"«ابتهاجاً» مصدر من لفظ الفعل «ابتهجت» جاء لتوكيده فهو مفعول مطلق."},"oub6ui":{"w":{"توكيد معنوي":"التوكيد المعنوي بلفظ «جميع» يشترط إضافته إلى ضمير يعود على المؤكَّد مثل «جميعُهم»، وهنا جاءت نكرة منصوبة.","مفعول به":"المفعول به يقع عليه الفعل، ولا يقع الحضور هنا على «جميعاً»، بل هي تصف هيئة المعلمين حين حضروا.","نعت":"النعت يتبع منعوته في الإعراب والتعريف، و«المعلمون» مرفوع معرفة و«جميعاً» نكرة منصوبة فلا تكون نعتاً له."}},"1p4uyx8":{"w":{"طالبان":"رفع المثنى بالألف صحيح، لكنه مضاف إلى «العلم»، ونون المثنى تُحذف عند الإضافة.","طالبين":"المثنى يكون بالياء في النصب والجر، وهو هنا فاعل مرفوع فحقه الألف، مع حذف النون للإضافة.","طالبي":"حذف النون للإضافة صحيح، لكن الياء علامة النصب والجر، والفاعل المثنى يُرفع بالألف."},"e":"الفاعل مثنى مرفوع بالألف، ونون المثنى تُحذف عند الإضافة: طالبا العلم."},"7vq39i":{"w":{"100000 ريال":"ربع العشر من هذا المال 2500 ريال فقط لا 5000، فالمال الصحيح 5000 × 40 = 200000 ريال.","300000 ريال":"ربع العشر من هذا المال 7500 ريال لا 5000، فالمال الصحيح 5000 × 40 = 200000 ريال.","400000 ريال":"ربع العشر من هذا المال 10000 ريال، أي ضعف المدفوع؛ والمال الصحيح 5000 × 40 = 200000 ريال."}},"p6427r":{"w":{"عشرات الألوف":"هذه منزلة الرقم 7 نفسه، والرقم 5 على يساره يأخذ المنزلة الأعلى منها: مئات الألوف.","آحاد الملايين":"هذه منزلة الرقم 2 أول العدد من اليسار، والرقم 5 بعده مباشرة في منزلة مئات الألوف.","آحاد الألوف":"هذه منزلة الرقم 1 الرابع من اليمين، أما الرقم 5 المقصود فهو السادس من اليمين."}},"3mhvdo":{"w":{"40 م":"40 م محيط الملعب لدورة واحدة: 2 × (12 + 8)، وخالد مشى دورتين، فالمسافة 40 × 2 = 80 م.","96 م":"96 مساحة الملعب (12 × 8) بالمتر المربع، والمشي حوله يُقاس بالمحيط لا بالمساحة: 2 × 40 = 80 م.","192 م":"192 ضعف مساحة الملعب (96 × 2)، والمشي حوله يحتاج المحيط 40 م، ودورتان 80 م."},"e":"محيط المستطيل = 2 × (12 + 8) = 40 م، ودورتان = 80 م."},"n4yooq":{"w":{"العدوان":"العدوان سلوك يُقصد به إيذاء شخص أو شيء، والطفل هنا يرمي الأشياء ليراقب سقوطها مراراً لا ليؤذي أحداً.","فرط الحركة":"فرط الحركة اضطراب لا يُستدل عليه بسلوك واحد، وتكرار الرمي مع مراقبة السقوط تجريب طبيعي يفعله أطفال الثانية لمعرفة خصائص الأشياء.","الإحيائية":"الإحيائية أن ينسب الطفل الحياة والمشاعر إلى الجمادات، والطفل هنا لا يصف الأشياء بأنها حية بل يجرب سقوطها."},"e":"رمي الأشياء وتجريبها في الطفولة المبكرة استكشاف نمائي طبيعي لخصائص الأشياء."},"1ah7m8l":{"w":{"التعلم شرط للنضج، فالتدريب يسرّع النضج":"العلاقة هنا معكوسة: النضج تغير داخلي لا يسرّعه التدريب، وهو الذي يهيئ للتعلم، والتعليم قبل الاستعداد يضيع الجهد.","كلاهما إرادي ويتأثر بالتدريب والممارسة":"التعلم وحده يحدث بالخبرة والممارسة، أما النضج فتغير داخلي لا إرادي يحدث دون تدريب، فلا يشتركان في هذه الصفة.","لا علاقة بينهما، فكل منهما مستقل عن الآخر":"بينهما علاقة وثيقة، فالنضج شرط للتعلم، ولهذا لا يتعلم الطفل الكتابة قبل نضج عضلاته الدقيقة مهما تدرب."}},"1dpme7l":{"w":{"وظيفياً":"النمو الوظيفي تحسن في أداء الأعضاء والقدرات، أما زيادة الطول والوزن فتغير في الحجم والشكل، وهذا هو النمو التكويني.","انفعالياً":"النمو الانفعالي يخص المشاعر وضبطها والتعبير عنها، وزيادة الطول والوزن تغير جسمي في حجم الجسم لا في الانفعالات.","اجتماعياً":"النمو الاجتماعي يخص علاقات الطالب بالآخرين وتفاعله معهم، أما الطول والوزن فمقاييس جسمية لحجم الجسم وشكله."},"e":"النمو التكويني (البنائي) زيادة في الحجم والشكل."},"1gs2n9a":{"w":{"الهوية مقابل تشتت الهوية":"أزمة الهوية تخص المراهقة من 12 إلى 18، وطالب الصف الخامس في سن الابتدائية وأزمته الإنجاز وتقدير جهده.","المبادرة مقابل الذنب":"المبادرة مقابل الذنب أزمة ما قبل المدرسة من 3 إلى 6 سنوات، والطالب هنا في الصف الخامس ينجز مهامه الدراسية ويُشجَّع عليها.","الاستقلال مقابل الخجل":"الاستقلال مقابل الخجل أزمة الطفولة المبكرة قبل الثالثة تقريباً حين يتعلم الطفل الاعتماد على نفسه، لا أزمة طالب في الصف الخامس."},"e":"سن المدرسة الابتدائية (6–12) أزمتها الاجتهاد/الكفاية مقابل الدونية/النقص."},"dtnwuw":{"w":{"الأقران":"الأقران من مكونات البيئة الاجتماعية التي ذكرها السؤال، ولا تُنسب إليهم «إفرازات»، فالإفرازات المؤثرة في النمو هي هرمونات الغدد الصماء.","المعلم":"المعلم عامل بيئي يدخل ضمن البيئة والتعلم المذكورين في السؤال، أما الإفرازات المؤثرة في النمو فهي هرمونات الغدد الصماء كالنخامية والدرقية.","التقنية":"التقنية من مثيرات البيئة لا من العوامل البيولوجية، وكلمة «إفرازات» في السؤال تشير إلى هرمونات الغدد الصماء المؤثرة في النمو."}},"rl9aod":{"w":{"يفتقرون إلى الانتباه":"مشكلة الأطفال هنا ليست في الانتباه، بل في حكمهم على الكمية من الشكل الظاهري بعد البسط، وهذا غياب لمفهوم الاحتفاظ.","في مرحلة العمليات المحسوسة":"طفل العمليات المحسوسة يدرك أن كمية الصلصال ثابتة مهما تغير شكلها، وأطفال الروضة هنا قالوا إن المبسوطة أكثر.","يعانون صعوبة في الإدراك البصري":"الأطفال لاحظوا تغير الشكل، لكنهم ظنوا أن تغير الشكل يغير الكمية، وهذا قصور في الاحتفاظ لا في الإدراك البصري."},"e":"الحكم على الكمية بالشكل الظاهري يعني غياب الاحتفاظ، وهو سمة ما قبل العمليات."},"1p11qon":{"w":{"اضطراب في التفكير يحتاج إحالة":"إضفاء المشاعر على الجمادات طبيعي في مرحلة ما قبل العمليات، وطفل الصف الأول على حدودها، فلا يُعد اضطراباً يستدعي الإحالة.","خيال إبداعي مرتفع يستحق الإثراء":"وصف الشمس بأنها تغضب وتختبئ تفكير شائع بين أطفال هذه السن، فلا يدل وحده على موهبة إبداعية تستدعي برنامج إثراء.","التفكير الافتراضي المبكر":"التفكير الافتراضي بناء فرضيات واختبارها ذهنياً، وهو من المرحلة المجردة نحو 11 سنة، وطفل الصف الأول لم يبلغها."},"e":"إضفاء الحياة والمشاعر على الجمادات هو الإحيائية، وهي طبيعية في ما قبل العمليات."},"1a0tdkk":{"w":{"ضعف الذاكرة قصيرة المدى":"المهمة لا تطلب تذكر شيء، فالمجسم أمامهم، والمشكلة أنهم لم يستطيعوا تخيل ما تراه زميلتهم من الجهة المقابلة.","عدم فهم التعليمات":"مشكلتهم هنا ليست في فهم المطلوب، فقد وصفوا المجسم فعلاً، بل في وصفه من زاويتهم لعجزهم عن تبني منظور الآخر.","ضعف الإدراك البصري":"الطلاب رأوا المجسم ووصفوه من مكانهم، فالقصور في تخيل ما تراه زميلتهم من جهتها لا في الإدراك البصري."},"e":"العجز عن تبني منظور الآخر هو التمركز حول الذات (تجربة الجبال الثلاثة لبياجيه)."},"jt76dg":{"w":{"أن طلابه في مرحلة العمليات المجردة":"طالب المرحلة المجردة يستطيع البدء بالقاعدة والفرضيات، أما طالب الصف الخامس فما زال في المحسوسة فيحتاج التجربة الملموسة قبل القاعدة.","أزمة الهوية لدى طلابه":"أزمة الهوية عند إريكسون تخص المراهقة وبحث المراهق عن ذاته ودوره، ولا تفسر تقديم التجربة الملموسة على القاعدة لطلاب الخامس.","مرحلة الكمون عند فرويد":"الكمون عند فرويد يصف هدوء الدوافع في سن الابتدائية، فهو تفسير للشخصية لا للتفكير، ولا يحدد أن التجربة الملموسة تسبق القاعدة."},"e":"طالب الخامس الابتدائي (10–11 سنة) في مرحلة المحسوسات، فالتجربة الملموسة قبل القاعدة أنسب."},"w0cktd":{"w":{"إعفاؤه من المهام الصعبة حتى يكبر":"الإعفاء يحرمه من خبرات الإنجاز التي تحل أزمة الاجتهاد مقابل الدونية، فيرسخ إحساسه بالعجز بدل أن يبني ثقته بقدرته.","مقارنته بزميل متفوق ليتحفز":"المقارنة بزميل متفوق تذكّره بعجزه أمام الآخرين، فتزيد شعوره بالدونية بدل أن تحفزه، والمطلوب تقدير تقدمه هو.","توجيهه إلى المرشد الطلابي فوراً":"الإحباط عند الخطأ هنا من مظاهر أزمة الاجتهاد مقابل الدونية، ويعالجه المعلم داخل الصف بخبرات الإنجاز أولاً، فالإحالة الفورية سابقة لأوانها."},"e":"أزمة الابتدائية الاجتهاد مقابل الدونية، ويُحل القطب الإيجابي بخبرات إنجاز وتقدير."},"1sb2nof":{"w":{"مطالبتهم بالجلوس الهادئ طوال الحصة لتعويدهم":"الجلوس الطويل يناقض حاجة طفل الصف الأول إلى الحركة وقصر انتباهه، فهو يتجاهل الخاصية التي يطلب السؤال مراعاتها بدل أن يتكيف معها.","إطالة الشرح مع رفع الصوت":"إطالة الشرح تتجاوز مدة الانتباه القصيرة في الطفولة المتوسطة، ورفع الصوت لا يعالج ذلك، والأنسب تقسيم الحصة إلى أنشطة قصيرة.","تأجيل الأنشطة إلى نهاية الحصة":"تأجيل الأنشطة يترك بداية الحصة ووسطها لشرح متصل يتجاوز مدة انتباههم، والأنسب أن تتوزع الأنشطة القصيرة على الحصة كلها."},"e":"الطفل في الطفولة المتوسطة انتباهه قصير وحاجته للحركة كبيرة، فالتنويع والأنشطة القصيرة أنسب."},"gdtz93":{"w":{"حاجتهم إلى التعلم بالمحسوسات":"التعلم بالمحسوسات حاجة طلاب الابتدائية في العمليات المحسوسة، وطالب الثانوية اكتمل تفكيره المجرد، والإجراء هنا ربط بالمهن وأدوار قيادية.","سن الجماعة وروح العمل الجماعي":"سن الجماعة وصف الطفولة المتأخرة في الصفوف العليا من الابتدائية، والإجراء هنا يخدم تفكير طالب الثانوية في مستقبله المهني واستقلاله.","التمركز حول الذات":"التمركز حول الذات بمعناه عند بياجيه سمة ما قبل العمليات، وربط الدروس بالمهن والأدوار القيادية يخاطب حاجة المراهق إلى الهوية والاستقلال."},"e":"اختيار المهنة والاستعداد لها من مطالب نمو المراهقة (هافجهرست) وتكوين الهوية (إريكسون)."},"ifb5ao":{"w":{"بياجيه في النمو المعرفي":"نظرية بياجيه المعرفية تصف تطور التفكير المنطقي كالاحتفاظ والمعكوسية، أما معضلة يتعارض فيها إنقاذ حياة مع القانون ويُحلَّل تبريرها فأداة كولبرج الأخلاقية.","إريكسون في النمو النفسي الاجتماعي":"إريكسون يفسر النمو بأزمات نفسية اجتماعية كالهوية والاجتهاد، ولا يقيس تبرير الأحكام بقصص فيها تعارض بين قيمتين.","فرويد في النمو النفسي الجنسي":"فرويد يفسر الشخصية بمراحل نفسية جنسية وبمكونات الهو والأنا والأنا الأعلى، ولا يستعمل المعضلات لقياس تبرير الحكم الأخلاقي."},"e":"المعضلات الأخلاقية (قصة هاينز) هي أداة كولبرج لتحديد مرحلة التفكير الأخلاقي من خلال التبرير لا الاختيار."},"5gu4wu":{"w":{"الطاعة وتجنب العقاب":"مرحلة الطاعة وتجنب العقاب يلتزم فيها الطفل خوفاً من العقوبة عليه، والطالب هنا يبرر بحفظ النظام العام من الفوضى لا بخوفه الشخصي.","المنفعة المتبادلة":"المنفعة المتبادلة يلتزم فيها الفرد لمصلحة يتبادلها مع غيره، والطالب هنا لم يذكر مصلحته بل حماية الجميع من الفوضى.","المبادئ الأخلاقية العالمية":"المبادئ العالمية تحتكم إلى العدل والكرامة الإنسانية ولو خالفت القانون، والطالب هنا يحتكم إلى حفظ النظام القائم ومنع الفوضى."},"e":"الحفاظ على النظام الاجتماعي والقانون لذاته هو المرحلة الرابعة (المستوى التقليدي)."},"b5trru":{"w":{"النمو يسير بمعدل ثابت":"معدلات النمو مختلفة، سريعة في الطفولة المبكرة والمراهقة وبطيئة في الطفولة المتوسطة، والمثال هنا عن ترتيب الحركات لا عن سرعتها.","النمو مستقل عن النضج":"النمو مرتبط بالنضج لا مستقل عنه، والمثال يصف انتقال الحركة من القبض بالكف كلها إلى الالتقاط الدقيق بإصبعين.","الفروق الفردية في النمو":"الفروق الفردية تعني اختلاف الأطفال في سرعة النمو، والمثال يصف تسلسلاً يمر به الرضع عموماً من الحركة العامة إلى الدقيقة."},"e":"القبض الكلي ثم الدقيق يجسد مبدأ من العام (الحركات الكلية) إلى الخاص (الحركات الدقيقة)."},"qzs114":{"w":{"ضعف دافعية الأطفال":"مشكلة الأطفال هنا ليست في الدافعية، فالتكرار لم يُجدِ لأن عضلات أصابعهم الدقيقة لم تنضج بعد في الثالثة.","قلة التعزيز المقدم":"زيادة التعزيز لا تعوض نقص النضج، فالكتابة بين السطور تحتاج تحكماً عضلياً دقيقاً لا يكتمل عند طفل الثالثة.","صعوبات تعلم لدى الأطفال":"صعوبات التعلم لا تُشخص في سن الثالثة، وإخفاق الأطفال جميعاً في المهارة نفسها يرجع إلى عمرهم لا إلى اضطراب لدى كل منهم."},"e":"المهارة تحتاج نضجاً في العضلات الدقيقة والتآزر لا يكتمل في هذا العمر؛ التدريب قبل النضج لا يفيد."},"1e0zhme":{"w":{"منع الحديث بين الطلاب داخل الصف":"منع الحديث يتجاهل قوة تأثير الأقران في المراهقة ولا يلغيها، والسؤال يطلب توظيف هذه الخاصية في التعلم لا كبتها.","المقارنة العلنية بين درجات الطلاب لتحفيزهم":"المراهق شديد الحساسية لأحكام أقرانه، فالمقارنة العلنية تجرح المتأخرين وتحبطهم بدل أن تحفزهم، وتحول تأثير الأقران إلى ضغط سلبي.","تجاهل تأثير الأقران لأنه مؤقت":"تأثير الأقران من أبرز خصائص المراهقة، وتجاهله يضيع فرصة توظيفه في التعلم التعاوني، والسؤال يطلب استثمار الخاصية لا انتظار زوالها."},"e":"تأثير الأقران في المراهقة قوي، فتوظيفه بالتعاون والنمذجة الإيجابية يخدم التعلم."},"1k39jvf":{"w":{"التمثل":"التمثل إدخال الخبرة الجديدة في مخطط قائم كما فعل حين سمى كل ذي أربع أرجل قطاً، أما التفريق وتكوين مفهوم جديد فتعديل للمخطط.","الاحتفاظ":"الاحتفاظ إدراك ثبات الكمية مع تغير الشكل في مرحلة العمليات المحسوسة، ولا علاقة له بتعديل المفهوم للتفريق بين القط والكلب.","التعميم":"التعميم مصطلح سلوكي يعني إعطاء الاستجابة نفسها لمثيرات متشابهة، وهو أقرب إلى تسمية كل ذي أربع أرجل قطاً لا إلى التفريق اللاحق."},"e":"تعديل المخطط القائم وإنشاء مفهوم جديد هو المواءمة."},"11aykwv":{"w":{"ما قبل التقليدي":"المستوى ما قبل التقليدي يبرر بتجنب العقاب أو تحقيق المصلحة الشخصية، والطالب هنا يبرر بالحفاظ على ثقة معلمه وحسن ظنه به.","ما بعد التقليدي":"ما بعد التقليدي يحتكم إلى العقد الاجتماعي والمبادئ العالمية كالعدل، أما الحرص على ألا يخيب ظن المعلم فطلب لرضا الآخرين.","الأخلاق الذاتية":"الأخلاق الذاتية تقوم على اقتناع داخلي مستقل عن سلطة الآخرين ورضاهم، والطالب هنا يعمل الواجب حتى لا يخيب ظن معلمه، وهذا من المستوى التقليدي."},"e":"إرضاء الآخرين والحفاظ على صورة الولد الطيب هو المستوى التقليدي (المرحلة 3)."},"8plo0t":{"w":{"منعه من الرياضة حتى يتحسن في القراءة":"المنع يسلبه مجال تفوقه الذي يبني شعوره بالكفاية، فيزيد إحساسه بالنقص بدل أن يجعل قوته جسراً إلى القراءة.","إجباره على القراءة أمام الصف ليتعود عليها":"إجبار طالب يخجل على القراءة أمام زملائه يعرضه للإحراج، فيرسخ شعوره بالدونية في أزمة الاجتهاد بدل أن يبني ثقته.","تجاهل الخجل لأنه سيزول مع تقدم العمر":"التجاهل لا يعالج الخجل ولا يستثمر قوته الظاهرة في القيادة، وهي خاصية سن الجماعة التي يمكن أن تقوده إلى القراءة."},"e":"الطفولة المتأخرة سن الجماعة والقيادة، فتوظيف قوته الاجتماعية جسر لمهارة القراءة."},"19zo4rx":{"w":{"صعوبات التعلم":"صعوبات التعلم تكون مع ذكاء عادي واضطراب في عمليات كالانتباه والإدراك، وهذا الطالب ذكاؤه دون 70 ومعه قصور تكيفي.","بطء التعلم":"بطء التعلم يقع فيه الذكاء في المدى الحدّي بين 70 و 85، أما هنا فالذكاء دون 70 ومعه قصور في العناية بالذات والتواصل.","التأخر الدراسي":"التأخر الدراسي تدنٍّ في التحصيل مع ذكاء عادي لأسباب خارجية كالغياب، ولا يفسر ذكاءً دون 70 مع قصور في العناية بالذات."},"e":"الإعاقة الفكرية (العقلية) تجمع انخفاض الذكاء (دون 70 تقريباً) وقصور السلوك التكيفي قبل سن 18."},"14z3o17":{"w":{"اختبار ستانفورد بينيه":"ستانفورد بينيه اختبار ذكاء يقيس القدرة العقلية العامة، والمطلوب هنا أداة يقدّر بها المعلم سلوك الطالب في الفهم والذاكرة والانتباه.","اختبار الاستعداد المهني":"اختبار الاستعداد المهني يقيس قابلية الفرد للنجاح في مجالات مهنية، لا سلوكه في الفهم والذاكرة والانتباه الذي يكشف صعوبات التعلم.","مقياس ليكرت للاتجاهات":"مقياس ليكرت يقيس الاتجاهات بدرجات الموافقة من موافق بشدة إلى غير موافق بشدة، لا سلوك الطالب في الفهم والذاكرة والانتباه."},"e":"مايكل بست مقياس تقدير سلوكي يملؤه المعلم للكشف الأولي عن صعوبات التعلم."},"1rsz5xj":{"w":{"الموهبة أداء مكتسب والتفوق قدرة فطرية":"هذا عكس نموذج جانييه، فالموهبة عنده هي الاستعداد الفطري، والتفوق هو الأداء المكتسب الذي ينمو بالتدريب والبيئة.","الموهبة والتفوق مترادفان":"جانييه فرّق بين المصطلحين، فالموهبة عنده استعداد فطري والتفوق أداء ينمو بالتدريب، ولذلك كل متفوق موهوب وليس العكس.","التفوق يُقاس بالذكاء والموهبة بالتحصيل":"الفرق عند جانييه في المنشأ لا في أداة القياس، فالموهبة استعداد فطري والتفوق أداء مكتسب، والإنجاز أقرب إلى التفوق لا إلى الموهبة."}},"13ggc0d":{"w":{"صعوبات تعلم":"صعوبات التعلم اضطراب داخلي في العمليات، ومحك الاستبعاد يُخرج من تفسّر حالته ظروف بيئية كالغياب وإهمال الأسرة كهذه الطالبة.","بطء تعلم":"بطء التعلم يقترن بذكاء حدّي بين 70 و 85، وهذه الطالبة ذكاؤها عادي وسبب تدنيها الغياب وإهمال الأسرة وضعف الدافعية.","إعاقة فكرية":"الإعاقة الفكرية ذكاء دون 70 تقريباً مع قصور في السلوك التكيفي، وهذه الطالبة ذكاؤها عادي وتدنيها لأسباب خارجية."},"e":"التأخر الدراسي: ذكاء عادي وتدنٍ ناتج عن عوامل خارجية (إهمال، غياب، دافعية)."},"g4tq59":{"w":{"سمعي":"المتعلم السمعي يفضل الشرح الشفهي والمناقشة والاستماع، أما الرسوم التوضيحية والخرائط فمداخل تعتمد على النظر.","حسي حركي":"الحسي الحركي يتعلم بالتجربة والحركة واللمس، أما الرسوم التوضيحية والخرائط فمدخل بصري يعتمد على النظر.","اجتماعي":"الاجتماعي من ذكاءات جاردنر ويعني فهم الآخرين والعمل معهم، ولا يصف تفضيل تلقي المعلومات بالرسوم والخرائط."},"e":"الرسوم والخرائط مدخل النمط البصري، وفي التقسيم الثلاثي (بصري، سمعي، حسي حركي) تُحسب القراءة معها؛ أما في نموذج VARK فللقراءة نمط مستقل ليس بين الخيارات."},"1woqbxs":{"w":{"أعلى بكثير لأنها ترتفع بالعمر":"نسبة الذكاء تُحسب بمقارنة الطالب بأقران عمره، فإذا نمت قدراته مع نموهم بقيت نسبته قريبة من 110 ولم ترتفع كثيراً.","أقل بكثير لأنها تنخفض بالعمر":"نسبة الذكاء تقارن الطالب بأقران عمره، فتقدّمه في العمر وحده لا يخفضها، وتبقى ثابتة نسبياً مع تغيرات طفيفة.","لا يمكن التنبؤ بها إطلاقاً":"ثبات نسبة الذكاء النسبي هو ما يسمح بالتنبؤ بها، والسمات العقلية من أكثر السمات ثباتاً، فيُتوقع أن تبقى قريبة من 110."}},"cd038i":{"w":{"الأهداف العامة للمقرر":"هدف التعلم واحد لجميع الطلاب في التعليم المتمايز، والذي يتنوع هو المحتوى والعملية والمنتج وبيئة التعلم.","درجات الاختبار النهائي":"درجات الاختبار النهائي نتيجة تقويم تُرصد للطالب لا بُعد يكيّفه المعلم، والبعد الرابع عند توملينسون هو بيئة التعلم.","المنهج الرسمي":"المنهج الرسمي ثابت للجميع، والمعلم يمايز في طريقة الوصول إليه عبر المحتوى والعملية والمنتج والبيئة، لا في المنهج نفسه."},"e":"أبعاد التمايز الأربعة: المحتوى، العملية، المنتج، بيئة التعلم."},"1deppy8":{"w":{"تنويع طرق عرض المحتوى على الطلاب":"تنويع طرق عرض المحتوى تطبيق مباشر لتمايز المحتوى عند توملينسون، فهو من ممارسات التعليم المتمايز لا مما يعارضه.","السماح بمنتجات مختلفة لإثبات التعلم":"تنويع المنتج الذي يثبت به الطالب تعلمه أحد أبعاد التمايز الأربعة، فهو ممارسة متمايزة لا تتعارض مع فلسفته.","تكوين مجموعات مرنة تتغير بحسب المهمة":"المجموعات المرنة التي تتغير بحسب المهمة هي أساس التعليم المتمايز، والمعارض له هو التجميع الثابت الدائم."},"e":"التمايز يقوم على مجموعات مرنة لا تصنيف دائم يوصم الطالب."},"5xcous":{"w":{"الإثراء الرأسي":"الإثراء الرأسي يعمّق المحتوى للطالب وهو باقٍ في صفه، أما نقله من الرابع إلى السادس مباشرة فتغيير لمستواه، وهذا تعجيل.","التجميع":"التجميع ضم الموهوبين في مجموعات أو فصول خاصة بهم، والإجراء هنا نقل الطالب إلى صف أعلى متخطياً الخامس، وهذا تعجيل.","الدمج الجزئي":"الدمج الجزئي يعني دراسة الطالب بعض الوقت في الفصل العادي وبعضه في برنامج خاص، ولا يصف نقل موهوب إلى صف أعلى."},"e":"تخطي الصفوف أحد صور التعجيل مع القبول المبكر وضغط المنهج."},"qizhl2":{"w":{"اختيار أعلى الطلاب في درجات الاختبار النهائي فقط":"التحصيل وحده قد يُخفي موهوباً ذا صعوبات أو أصابه الملل، والتحصيل المرتفع ليس من حلقات رنزولي الثلاث، فلا يكفي محكاً.","اختيار الأكثر هدوءاً والتزاماً بالنظام":"الهدوء والانضباط صفات سلوكية لا تدل على الموهبة، وقد يكون الموهوب كثير الأسئلة والنقاش، فليسا محكاً للترشيح.","اختيار من يطلب أولياء أمورهم ترشيحهم":"طلب ولي الأمر رغبة لا تقيس قدرات الطالب ولا إبداعه، والترشيح يحتاج محكات موضوعية متعددة كالذكاء والإبداع وملاحظة الأداء."},"e":"الكشف عن الموهبة يتطلب محكات متعددة لأن التحصيل وحده قد يخفي موهوباً ذا صعوبات أو ملل."},"139dfiq":{"w":{"بطء تعلم":"بطء التعلم ضعف عام مع ذكاء حدّي، وهذا الطالب ذكاؤه واضح وفهمه السمعي جيد ومشكلته محصورة في القراءة.","إعاقة بصرية":"الإعاقة البصرية تظهر في كل مهام الرؤية، أما قلب الحروف المتشابهة مع ذكاء واضح وفهم سمعي جيد فعلامة عسر القراءة.","تأخر دراسي":"التأخر الدراسي تدنٍّ في التحصيل سببه ظروف خارجية كالغياب، والسؤال لا يذكر ظرفاً كهذا بل قلب حروف وبطء قراءة، وهي علامات عسر القراءة."},"e":"قلب الحروف وبطء القراءة مع ذكاء عادي وفهم سمعي جيد علامات الديسلكسيا (صعوبة أكاديمية)."},"141y0oq":{"w":{"إعفاؤه من كل مهام القراءة":"الإعفاء من القراءة كلها يحرمه من تنمية المهارة التي يحتاجها أكثر من غيرها، والمطلوب تكييف المهام لا إلغاؤها.","نقله إلى معهد للتربية الفكرية":"معاهد التربية الفكرية لذوي الإعاقة الفكرية، وذو صعوبات التعلم ذكاؤه عادي ويبقى في الفصل العادي مع غرفة المصادر.","تكليفه بالقراءة أمام الصف ليتدرب":"القراءة العلنية أمام الصف تحرج ذا صعوبات القراءة وتزيد قلقه، والتدريب المناسب له بتكييف المهام ودعم غرفة المصادر."},"e":"ذو الصعوبات يبقى في صفه مع تكييفات وخدمة غرفة المصادر."},"1dgaujo":{"w":{"فرط الحركة":"فرط الحركة ضعف انتباه ونشاط زائد واندفاعية، ولا يفسر تجنب التواصل البصري وتكرار رصف المكعبات والاضطراب عند تغيير الروتين.","الإعاقة السمعية فقط":"عدم الاستجابة للاسم قد يوحي بضعف السمع، لكن الإعاقة السمعية لا تفسر السلوك النمطي ومقاومة تغيير الروتين.","صعوبات التعلم":"صعوبات التعلم اضطراب في عمليات كالانتباه والإدراك مع ذكاء عادي، ولا تفسر تجنب التواصل البصري وتكرار رصف المكعبات ومقاومة تغيير الروتين."},"e":"قصور التواصل الاجتماعي والسلوك النمطي ومقاومة التغيير هي السمات المميزة للتوحد."},"1oefkxh":{"w":{"إجلاسه في الخلف قرب الباب لتقليل إحراجه أمام زملائه":"الجلوس في الخلف يبعده عن صوت المعلم ووجهه فيصعب عليه السمع وقراءة الشفاه، وضعيف السمع مكانه المقدمة.","رفع الصوت طوال الحصة دون أي تعديل آخر":"رفع الصوت وحده لا يكفي، فضعيف السمع يحتاج أيضاً إلى رؤية وجه المعلم لقراءة الشفاه وإلى وسائل بصرية تعوض ما يفوته.","إعفاؤه من الأنشطة الشفهية ومن المشاركة الصفية":"الإعفاء من المشاركة يحرمه من التعلم والتفاعل، والمطلوب تعويض قصوره السمعي بالجلوس في المقدمة والوسائل البصرية لا إبعاده."},"e":"المقدمة ومواجهة الوجه (لقراءة الشفاه) والوسائل البصرية تعوض القصور السمعي."},"1mk4iui":{"w":{"الطلاب المتوسطون في التحصيل":"المتوسطون يمثلون متوسط الجماعة نفسه، وذوو الاحتياجات الخاصة من ينحرفون عن المتوسط انحرافاً يحتاج خدمات خاصة.","الطلاب كثيرو الغياب":"كثرة الغياب ظرف سلوكي أو أسري قد يسبب تأخراً دراسياً، لكنها لا تجعل الطالب من فئات ذوي الاحتياجات الخاصة.","الطلاب الجدد في المدرسة":"الطالب الجديد يحتاج تهيئة وتعريفاً بالمدرسة، وهذه حاجة مؤقتة عامة لا تجعله من ذوي الاحتياجات الخاصة كالموهوبين."}},"zf21x1":{"w":{"الفروق بين الأفراد":"الفروق بين الأفراد مقارنة طالب بزملائه في سمة ما، أما تفاوت الطالب نفسه بين اللغة والرياضيات ففروق داخل الفرد.","صعوبات التعلم بالضرورة":"صعوبات التعلم لا يُحكم بها إلا بتشخيص يطبق محكي التباين والاستبعاد، والتفاوت بين مادتين وحده مثال على الفروق داخل الفرد.","بطء التعلم":"بطء التعلم ضعف عام في جميع المواد مع ذكاء حدّي، وهذا الطالب متفوق في اللغة العربية فلا ينطبق عليه."},"e":"تفاوت قدرات الطالب نفسه بين مجال وآخر هو الفروق داخل الفرد."},"1vqzxo5":{"w":{"تطبيق جداول التعزيز المتغيرة":"جداول التعزيز المتغيرة مفهوم سلوكي ينظم توقيت تقديم المكافأة بعد الاستجابة، ولا صلة له بتنويع طريقة عرض الدرس.","إشباع الحاجات الفسيولوجية":"الحاجات الفسيولوجية عند ماسلو كالطعام والنوم والراحة، والتنويع هنا في قنوات عرض الدرس السمعية والبصرية واليدوية.","تحقيق الانطفاء التدريجي":"الانطفاء مفهوم سلوكي يعني ضعف الاستجابة عند توقف التعزيز، ولا يرتبط بعرض الدرس شفهياً ثم بخريطة ثم بنشاط يدوي."},"e":"تنويع قنوات العرض يخاطب الأنماط السمعية والبصرية والحسية."},"11423xz":{"w":{"الذاتي (ضمن الشخص نفسه)":"الذكاء الذاتي فهم الإنسان لنفسه ومشاعره وأهدافه، وهذه الطالبة تفهم مشاعر زميلاتها وتقودهن، وهذا فهم للآخرين.","اللغوي (اللفظي)":"الذكاء اللغوي براعة في استعمال الكلمات قراءة وكتابة وتعبيراً، والسؤال يصف فهم مشاعر الزميلات وحل خلافاتهن وقيادتهن.","المنطقي الرياضي":"المنطقي الرياضي يظهر في الأرقام والاستدلال وحل المسائل، أما فهم مشاعر الزميلات وقيادة المجموعة فذكاء اجتماعي."},"e":"فهم الآخرين والتأثير فيهم هو الذكاء الاجتماعي."},"1vly8rn":{"w":{"طالب يدرس في فصل خاص داخل المدرسة ويشارك الزملاء في الفسحة فقط":"المشاركة مع الزملاء في الفسحة وحدها دمج اجتماعي، أما الأكاديمي الكلي فيدرس فيه الطالب كل المواد في الفصل العادي.","طالب يدرس في معهد مستقل خاص بذوي الإعاقة":"المعهد المستقل بيئة منفصلة هي أكثر الأماكن التربوية تقييداً، فلا دمج فيها مع العاديين أصلاً.","طالب يخرج إلى غرفة المصادر معظم اليوم الدراسي":"قضاء معظم اليوم في غرفة المصادر يعني أن جزءاً كبيراً من تعليمه خارج الفصل العادي، وهذا دمج جزئي لا كلي."},"e":"الدمج الكلي يعني تلقي كل التعليم في الفصل العادي مع دعم."},"ee672j":{"w":{"بطء التعلم":"بطء التعلم ضعف عام مع ذكاء حدّي، والطالبة موهوبة، ومشكلتها قسوتها على نفسها وتوترها من الخطأ لا ضعف قدرتها.","ضعف الدافعية":"ضعف الدافعية قلة الرغبة في الإنجاز، وهذه الطالبة على العكس تُجهد نفسها حتى تسلّم عملاً مثالياً.","العجز المتعلم":"العجز المتعلم توقف عن المحاولة بعد تكرار الفشل، والطالبة لا تتوقف بل تُصر على أن يكون عملها مثالياً، وهذا عكسه."},"e":"الكمالية والحساسية المفرطة من الخصائص الانفعالية للموهوبين وقد تسبب القلق."},"d3mnvm":{"w":{"بافلوف":"بافلوف صاحب الإشراط الكلاسيكي الذي يقوى فيه الارتباط بتكرار الاقتران مرات عدة، والسؤال يطلب صاحب نظرية يكفي فيها اقتران واحد.","ثورندايك":"ثورندايك فسّر التعلم بالمحاولة والخطأ وقانون الأثر الذي يقوي الاستجابة المتبوعة بارتياح، لا باقتران واحد بين المثير والاستجابة.","سكنر":"سكنر صاحب الإشراط الإجرائي الذي تتحكم فيه نتائج السلوك والتعزيز، لا مبدأ المرة الواحدة الذي يكفي فيه اقتران واحد."},"e":"جاثري صاحب نظرية الاقتران الشرطي ومبدأ المرة الواحدة."},"1j183ky":{"w":{"قانون الأثر":"قانون الأثر عند ثورندايك يقوّي الارتباط أو يضعفه تدريجياً عبر محاولات متكررة، أما الطفل فتعلم الخوف من لسعة واحدة دون تكرار.","التعميم":"التعميم استجابة لمثيرات تشبه المثير الأصلي، والطفل هنا يتجنب النار نفسها التي لسعته لا مثيرات مشابهة لها.","الاسترجاع التلقائي":"الاسترجاع التلقائي عودة استجابة منطفئة فجأة بعد فترة راحة، والسؤال يصف تكوّن خوف جديد من أول خبرة لا عودة خوف قديم."},"e":"تكوّن الارتباط من خبرة واحدة شديدة الأثر دون تكرار هو التعلم من المحاولة الواحدة (قانون المرة الواحدة) عند جثري في نظرية الاشتراط بالاقتران."},"12tqsah":{"w":{"استجابي، وإجرائي":"الاستجابي هو اللاإرادي الذي يستثيره مثير سابق فمكانه الثاني، والإجرائي هو الإرادي الذي تتحكم فيه نتائجه فمكانه الأول.","شرطي، وغير شرطي":"الشرطي وغير الشرطي من مصطلحات إشراط بافلوف للمثيرات والاستجابات اللاإرادية، لا تسمية سكنر للسلوك الإرادي الذي تحكمه نتائجه.","كامن، وظاهر":"الكامن من مصطلحات تولمان للتعلم الذي يحدث دون تعزيز ويظهر عند الحاجة، ولا صلة له بتقسيم سكنر للسلوك إلى إرادي ولا إرادي."}},"gxui25":{"w":{"كوهلر":"كوهلر من أعلام الجشطلت واشتهر بتجربة القرد والعصوين في الاستبصار، أما قوانين التنظيم الإدراكي فتُنسب إلى فرتهايمر مؤسس المدرسة.","تولمان":"تولمان صاحب التعلم الكامن والخرائط المعرفية من تجارب الفئران في المتاهة، لا قوانين الإدراك كالتقارب والتشابه والإغلاق.","أوزوبل":"أوزوبل صاحب التعلم ذي المعنى والمنظم المتقدم، وليس من مدرسة الجشطلت ولا واضع قوانين التنظيم الإدراكي."},"e":"فرتهايمر مؤسس الجشطلت."},"fcj0a5":{"w":{"الاشتراط الإجرائي":"الاشتراط الإجرائي عند سكنر يفسر التعلم بنتائج السلوك والتعزيز، ولا يتناول ما يجري داخل العقل من استقبال ومعالجة وإخراج.","التعلم بالاستبصار":"الاستبصار عند الجشطلت فهم مفاجئ بإعادة تنظيم الموقف، أما تشبيه العقل بحاسوب يستقبل ويعالج ويُخرج فهو نموذج معالجة المعلومات.","التعلم الاجتماعي":"التعلم الاجتماعي عند باندورا يكون بملاحظة نموذج وتقليده، ولا يقوم على تشبيه العقل بحاسوب يعالج المدخلات ثم يُخرجها."}},"hbztig":{"w":{"بياجيه":"بياجيه صاحب نظرية النمو المعرفي بالتمثل والمواءمة، أما تخزين المعلومة لفظياً وبصرياً معاً فهو الترميز المزدوج عند بافيو.","باندورا":"باندورا صاحب التعلم الاجتماعي بالملاحظة والنمذجة، ولا تتناول نظريته تخزين المعلومة في نظامين لفظي وبصري.","برونر":"برونر يرى التمثيل يتدرج من عملي إلى أيقوني إلى رمزي، أما تخزين المعلومة الواحدة لفظياً وبصرياً معاً فهو الترميز المزدوج."},"e":"بافيو صاحب الترميز المزدوج (لفظي وتصوري)."},"1j5451b":{"w":{"التدريب المكثف أفضل للاحتفاظ":"المذاكرة المكثفة في جلسة طويلة ليلة الاختبار تُنسى سريعاً، والمعلم نصح بعكسها: جلسات قصيرة متباعدة أبقى في الذاكرة.","التكرار الآلي يضمن الفهم":"التكرار الآلي يثبّت الحفظ لكنه لا يكفي وحده للفهم، ونصيحة المعلم عن توزيع المراجعة على الزمن لا عن طريقة تكرارها.","الحفظ يسبق الفهم دائماً":"تقديم الحفظ على الفهم ليس مبدأً تربوياً ثابتاً، ونصيحة المعلم هنا عن توزيع المراجعة على جلسات متباعدة لا عن ترتيب الحفظ والفهم."},"e":"الممارسة الموزعة تعزز التخزين طويل المدى وتقلل التداخل."},"177j4in":{"w":{"القرد والعصا":"تجربة القرد والعصا لكوهلر من الجشطلت وتفسر التعلم بالاستبصار، لا تقليد الأطفال لنموذج يضرب دمية.","الكلب والجرس":"تجربة الكلب والجرس لبافلوف في الإشراط الكلاسيكي باقتران المثيرات، لا في التعلم بملاحظة نموذج وتقليده.","القط والصندوق":"تجربة القط في الصندوق لثورندايك وتفسر التعلم بالمحاولة والخطأ، لا بمشاهدة نموذج وتقليده كما فعل أطفال باندورا."},"e":"دمية بوبو تجربة باندورا في التعلم بالملاحظة."},"o1m8y6":{"w":{"الاشتراط الكلاسيكي":"الاشتراط الكلاسيكي يقوم على مثير سابق يستدعي استجابة لا إرادية، والمشاركة هنا سلوك إرادي ضعف لأن التعزيز لم يأتِ بعده.","التعميم":"التعميم استجابة لمثيرات تشبه المثير الأصلي، والسؤال يصف سلوكاً يضعف تدريجياً لغياب التعزيز لا امتداد الاستجابة إلى مثيرات مشابهة.","العقاب السالب":"العقاب السالب سحب معزز قائم بعد السلوك، والمعلم هنا لم يسحب شيئاً من الطالب بل امتنع عن منح التعزيز أصلاً."},"e":"المشاركة سلوك إرادي، ولما غاب التعزيز الذي ينتظره الطالب بعدها ضعفت تدريجياً، وهذا هو الانطفاء في الاشتراط الإجرائي (سكنر). والانطفاء موجود أيضاً في الاشتراط الكلاسيكي (بافلوف)، لكنه هناك يخص استجابة لا إرادية لمثير شرطي يتكرر دون المثير الطبيعي، والموقف هنا لا مثير سابق فيه بل نتيجة غابت بعد السلوك."},"i1ml9p":{"w":{"التعزيز السالب":"التعزيز السالب إزالة منفّر عن الطالب نفسه فيزيد سلوكه، والطالب هنا لم يُزل عنه شيء بل رأى زميله يُكافأ فقلّده.","التشكيل":"التشكيل أن يعزز المعلم الطالب نفسه على خطوات متتابعة تقترب من السلوك المطلوب، وهنا لم يُعزَّز الطالب بل تعلم بمشاهدة مكافأة زميله.","الانطفاء":"الانطفاء ضعف السلوك حين يتوقف تعزيزه، والسلوك هنا لم يضعف بل ظهر بعد أن رأى الطالب زميله يُكافأ."},"e":"التعزيز البديل عند باندورا: ملاحظة نموذج يُعزَّز يزيد احتمال تقليده."},"zdzf9a":{"w":{"تثبيتاً":"التثبيت مرحلة تلي الشرح لترسيخ ما تعلمه الطلاب، أما الفيلم فعُرض قبل الدرس ليربط الجديد بما في بنيتهم المعرفية.","تعزيزاً":"التعزيز مفهوم سلوكي يقوي استجابة بعد حدوثها، والفيلم لم يأتِ مكافأة على سلوك بل تمهيداً يسبق درس الشحنات.","كفاية ذاتية":"الكفاية الذاتية عند باندورا اعتقاد الطالب بقدرته على أداء مهمة محددة، وليست مادة يعرضها المعلم تمهيداً للدرس كهذا الفيلم."},"e":"المادة التمهيدية العامة التي تُعرض قبل الدرس لربطه بالبنية المعرفية هي المنظم المتقدم عند أوزوبل."},"1unojk9":{"w":{"البنائية المعرفية (بياجيه)":"بياجيه بنائي أيضاً لكنه يرى البناء فردياً بتفاعل الطفل مع الأشياء، والسؤال يجعل التفاعل الاجتماعي والحوار مع الأكثر خبرة أساس التعلم.","السلوكية (سكنر)":"سكنر يفسر التعلم بالتعزيز الذي يلي السلوك الإرادي، لا بالحوار والتعاون مع الأكثر خبرة كما يصف السؤال.","الجشطلت":"الجشطلت تفسر التعلم بالاستبصار وإعادة تنظيم الموقف إدراكياً، ولا تجعل التفاعل الاجتماعي والحوار مع الأكثر خبرة مصدره."},"e":"فيجوتسكي يرى التعلم اجتماعياً أولاً عبر الحوار والمساعدة في منطقة النمو القريب."},"ws6uzu":{"w":{"المادية":"المعززات المادية أشياء ملموسة كالهدايا والأدوات، ومسح الرأس والابتسامة تعبير عن الرضا والتقدير لا شيء ملموس يُعطى للطالب.","الرمزية":"المعززات الرمزية كالنجوم والنقاط تُجمع وتُستبدل لاحقاً بمكافأة، والابتسامة ومسح الرأس أثرهما مباشر ولا يُستبدلان بشيء.","النشاطية":"المعززات النشاطية تمنح الطالب نشاطاً محبباً كوقت اللعب، والمعلم هنا لم يمنحه نشاطاً بل لمسة وابتسامة تعبيراً عن رضاه."},"e":"اللمسة والابتسامة والمدح معززات اجتماعية، وتسمى أيضاً معنوية في التقسيم الثنائي (مادية ومعنوية)."},"pn3mn3":{"w":{"ملقّن ينقل المعرفة ويتحكم في التعزيز":"الملقّن الذي ينقل المعرفة ويتحكم في التعزيز دور المعلم في السلوكية، والبنائية تجعل الطالب يبني معرفته بنفسه والمعلم ميسّراً.","مصدر وحيد للمعلومات":"المعلم مصدراً وحيداً ينقل المعلومات إلى متلقٍّ نظرة تقليدية، والبنائية ترى الطالب يبني معرفته على خبراته السابقة والمعلم ييسر ذلك.","مراقب للاستجابات الظاهرة فقط":"الاهتمام بالاستجابات الظاهرة وحدها سمة السلوكية، والبنائية تهتم بما يبنيه الطالب من معرفة داخلية وتعدّ أخطاءه فرصة للتعلم."},"e":"البنائية تجعل المعلم ميسراً والطالب بانياً نشطاً."},"14w09eu":{"w":{"تعزيز سالب":"التعزيز السالب إزالة منفّر فيزيد السلوك، والمعلم هنا سحب حصة محببة فقلّ الإهمال، فهو عقاب لا تعزيز.","عقاب موجب":"العقاب الموجب إضافة منفّر كالتوبيخ أو واجب إضافي، والمعلم هنا لم يضف شيئاً بل سحب حصة الرياضة المحببة.","تشكيل":"التشكيل تعزيز تقريبات متتابعة لبناء سلوك جديد، والمعلم هنا لم يعزز خطوات بل سحب امتيازاً ليقل الإهمال."},"e":"سحب امتياز مكتسب (حصة الرياضة) بعد السلوك غير المرغوب فقلّ السلوك = تكلفة الاستجابة، وهي صورة من العقاب السالب."},"f8sqs2":{"w":{"عقاب موجب":"العقاب الموجب إضافة منفّر بعد السلوك كالتوبيخ، والمعلم هنا لم يضف شيئاً بل أوقف الانتباه الذي كان يعزز الصراخ.","تعزيز سالب":"التعزيز السالب إزالة منفّر لزيادة سلوك، والمعلم هنا لا يريد زيادة الصراخ بل يوقف الانتباه المعزّز له ليتلاشى.","إقصاء":"الإقصاء يتطلب إبعاد الطالب مؤقتاً عن الموقف المعزّز، والطالب هنا بقي في الصف وأُوقف الانتباه عن صراخه فقط."},"e":"وقف التعزيز (الانتباه) عن السلوك فيتلاشى = انطفاء، مع تعزيز السلوك البديل (تعزيز تفاضلي)."},"1u8vmaq":{"w":{"نسبة متغيرة":"النسبة المتغيرة تعزيز بعد عدد غير منتظم من الاستجابات، والمعلم هنا يعطي النجمة بعد خمس إجابات بالضبط في كل مرة.","فترة ثابتة":"الفترة الثابتة تعزيز بعد مرور زمن محدد في كل مرة، والنجمة هنا مرتبطة بعدد الإجابات الصحيحة لا بالوقت.","فترة متغيرة":"الفترة المتغيرة تعزيز بعد أزمنة غير منتظمة كالاختبار المفاجئ، والنجمة هنا تُعطى بعدد ثابت من الإجابات لا بالزمن."},"e":"التعزيز بعد عدد ثابت من الاستجابات = نسبة ثابتة."},"1y50m6k":{"w":{"النسبة المتغيرة":"النسبة المتغيرة تعزيز بعد عدد غير منتظم من الاستجابات، وتنتج أداءً مرتفعاً منتظماً، لا مذاكرة مرتبطة بموعد اختبار شهري.","الفترة المتغيرة":"الفترة المتغيرة كالاختبار المفاجئ تبقي الأداء منتظماً لأن الطالب لا يعرف الموعد، وهنا الموعد معروف فيذاكرون قبله فقط.","المستمر":"التعزيز المستمر يكافئ كل استجابة صحيحة، والتعزيز هنا مرتبط بموعد زمني ثابت هو اختبار الشهر، فترتفع المذاكرة قبله فقط."}},"dkakf9":{"w":{"تسلسل":"التسلسل ربط خطوات مكتملة متتالية في سلسلة سلوكية واحدة، أما هنا فكل مرحلة تقريب أقرب من سابقتها إلى كتابة الاسم.","نمذجة":"النمذجة تعلّم بملاحظة نموذج ثم تقليده، والسؤال لا يذكر نموذجاً، بل تعزيز الطفل عند كل خطوة تقربه من كتابة اسمه.","تعميم":"التعميم أن تظهر الاستجابة مع مثيرات تشبه المثير الأصلي، أما هنا فبناء سلوك جديد بتعزيز خطوات متتابعة نحوه."},"e":"تعزيز التقريبات المتتابعة نحو السلوك النهائي هو التشكيل."},"1vk9hi":{"w":{"التمييز":"التمييز استجابة للمثير الأصلي وحده دون ما يشبهه، والطالب هنا صار يخاف كل حصة فيها أرقام لا حصة الرياضيات وحدها.","الانطفاء":"الانطفاء ضعف الاستجابة حتى تختفي حين يتكرر المثير بلا توبيخ، والخوف هنا لم يضعف بل امتد إلى حصص مشابهة.","الاسترجاع التلقائي":"الاسترجاع التلقائي عودة استجابة منطفئة فجأة بعد راحة، والخوف هنا لم ينطفئ أصلاً بل انتقل إلى حصص مشابهة."},"e":"إصدار الاستجابة الشرطية لمثيرات تشبه المثير الأصلي هو التعميم."},"7gdthd":{"w":{"تعميم المثير":"تعميم المثير انتقال الاستجابة إلى مثيرات تشبه الأصلي، والخوف هنا لم ينتقل إلى مثير جديد، بل عاد هو نفسه بعد انطفائه وإجازة طويلة.","التمييز بين المثيرات":"التمييز أن يستجيب الطالب للمثير الأصلي وحده دون ما يشبهه، والسؤال هنا عن خوف انطفأ ثم عاد فجأة بعد راحة طويلة.","الكف الشرطي":"الكف الشرطي يعني كبح الاستجابة ومنع ظهورها، أما هنا فالخوف المنطفئ عاد وظهر فجأة بعد إجازة طويلة، وهذا عكس الكف."}},"1415s7z":{"w":{"الجشطلت":"الجشطلت تفسر التعلم بالاستبصار المفاجئ وإعادة تنظيم الموقف، لا بالتكرار ومدح الإجابة الصحيحة ومراعاة الاستعداد.","فيجوتسكي":"فيجوتسكي يرى التعلم بناءً اجتماعياً بالسقالات في منطقة النمو القريب، وليس له قوانين التدريب والأثر والاستعداد الظاهرة في التكرار والمدح.","أوزوبل":"أوزوبل يدعو إلى التعلم ذي المعنى بربط الجديد بالبنية المعرفية، والتكرار والمدح هنا تطبيق لقانوني التدريب والأثر لا للربط بالمعنى."}},"1ysbj6z":{"w":{"المحاولة والخطأ":"في المحاولة والخطأ يتحسن الأداء تدريجياً مع تناقص الأخطاء، أما الطالب هنا فتوقف ثم جاءه الحل كاملاً فجأة.","التشكيل":"التشكيل يحتاج معلماً يعزز خطوات متتابعة نحو السلوك، والسؤال لا يذكر تعزيزاً، بل حلاً مفاجئاً وصل إليه الطالب بنفسه.","التلقين":"التلقين أن يُعطى الطالب الإجابة جاهزة، والطالب هنا لم يعطه أحد الحل بل صاح «فهمت!» ورسمه بنفسه."},"e":"الحل المفاجئ بعد إعادة تنظيم الموقف هو الاستبصار (الجشطلت/كوهلر)."},"qtzsrt":{"w":{"تعلم ذو معنى بالاستقبال":"التعلم ذو المعنى يربط الجديد بالبنية المعرفية، وهؤلاء الطلاب استقبلوا التعريف لكنهم حفظوه دون ربطه بما يعرفونه عن الحركة.","تعلم ذو معنى بالاكتشاف":"الاكتشاف أن يصل الطالب إلى المبدأ بنفسه، والطلاب هنا يحفظون تعريفاً جاهزاً دون ربطه بمعرفتهم، فلا اكتشاف ولا معنى.","تعلم كامن":"التعلم الكامن لتولمان يحدث دون تعزيز ويظهر عند الحاجة، والسؤال عن حفظ تعريف دون ربطه بالمعرفة السابقة، وهذا من تصنيف أوزوبل."},"e":"الحفظ دون ربط بالبنية المعرفية هو التعلم الاستظهاري (الصمّ) بالاستقبال."},"oua9cz":{"w":{"التسميع":"التسميع تكرار المعلومة لإبقائها في الذاكرة، والمعلم هنا لم يطلب تكراراً بل عرض الرقم نفسه مقسماً إلى ثلاث مجموعات.","التنظيم الهرمي":"التنظيم الهرمي ترتيب المفاهيم في مستويات من العام إلى الخاص، والرقم هنا سلسلة أرقام قُسمت إلى مجموعات لا مفاهيم متدرجة.","الترميز المزدوج":"الترميز المزدوج لبايفيو يخزن المعلومة لفظياً وبصرياً معاً، والمعلم هنا لم يضف صورة بل قسّم الأرقام إلى مجموعات أقل عدداً."},"e":"تجميع الوحدات المتفرقة في وحدات أكبر ذات معنى يقلل عدد ما يُحفظ، فتستوعب الذاكرة قصيرة المدى معلومات أكثر مع أن سعتها تبقى نحو 7±2 وحدات."},"1bep20v":{"w":{"تداخل قبلي (سابق)":"التداخل القبلي أن يعيق التعلم القديم تذكر الجديد، وهنا العكس: الإسبانية الجديدة هي التي أنسته الفرنسية القديمة.","الاضمحلال (تلاشي الأثر)":"الاضمحلال نسيان بمرور الزمن وعدم الاستعمال، والسؤال يربط النسيان بتعلم قائمة جديدة بعدها، فالسبب تداخل لا مرور وقت.","الكبت (نسيان دافعي)":"الكبت نسيان دافعي لذكريات مؤلمة يبعدها الفرد عن وعيه، وقائمة الكلمات الفرنسية لم يتجنبها الطالب بل أنسته إياها القائمة الجديدة."},"e":"التعلم الجديد (الإسبانية) أعاق تذكر القديم (الفرنسية) = تداخل بعدي."},"d2jvih":{"w":{"إخباره بأنه ذكي فقط":"عبارة «أنت ذكي» إقناع لفظي، وهو وحده أضعف أثراً في الكفاءة الذاتية من خبرات النجاح الفعلية التي يعيشها الطالب بنفسه.","تقليل التوقعات منه":"خفض التوقعات منه يؤكد اعتقاده بأنه لن ينجح، والكفاءة الذاتية ترتفع بنجاحات متدرجة يعيشها لا بإعفائه من التحدي.","مقارنته بالمتفوقين":"المقارنة بالمتفوقين تضعف الكفاءة الذاتية لأنهم لا يشبهونه، والنموذج المؤثر عند باندورا نموذج مشابه للطالب نجح في مهمة مثلها."},"e":"أقوى مصادر الكفاءة الذاتية خبرات الإتقان ثم الخبرات البديلة."},"19960at":{"w":{"المواءمة":"المواءمة تعديل المخطط أو بناء مخطط جديد، والطفل هنا لم يكوّن مفهوماً جديداً للحمار الوحشي بل أدخله في مخطط الحصان.","الموازنة":"الموازنة العملية التي تحرك التمثل والمواءمة لاستعادة التوازن، والسؤال يصف ما فعله الطفل بالخبرة: أدخلها في مخطط الحصان القائم.","التعميم الشرطي":"التعميم الشرطي مفهوم سلوكي لانتقال استجابة شرطية إلى مثيرات مشابهة، والسؤال عن بياجيه وإدخال خبرة جديدة في مخطط معرفي قائم."},"e":"إدخال الخبرة الجديدة في مخطط قائم (الحصان) دون تعديله هو التمثل."},"3mt9j6":{"w":{"التعليم المبرمج":"التعليم المبرمج لسكنر يجزئ المادة إلى خطوات صغيرة مع تعزيز فوري، ولا يقوم على دعم مؤقت يُسحب تدريجياً مع تقدم الطلاب.","التعزيز المتقطع":"التعزيز المتقطع مكافأة بعض الاستجابات لا كلها، وما تقدمه المعلمة هنا ليس مكافأة بل أدوات دعم تقللها مع تقدم الطلاب.","الإثراء الأفقي":"الإثراء الأفقي توسيع التعلم بأنشطة إضافية في المستوى نفسه، والمعلمة هنا تقدم دعماً مؤقتاً للكتابة ثم تسحبه تدريجياً."}},"1uxma9s":{"w":{"أفقي":"الانتقال الأفقي استخدام المهارة في المستوى نفسه في سياق آخر، والضرب هنا مهارة أعلى مستوى تُبنى على الجمع.","سلبي":"الانتقال السلبي أن يعيق التعلم السابق اللاحق، والجمع هنا أساس يُبنى عليه الضرب فيسهّله ولا يعيقه.","صفري":"الانتقال الصفري ألا يؤثر التعلم السابق في اللاحق، والضرب هنا يُبنى على الجمع فالأثر بينهما واضح."},"e":"تعلم مهارة أعلى مستوى تبنى على سابقة = انتقال رأسي."},"c109ez":{"w":{"الانطفاء":"الانطفاء إيقاف التعزيز فيضعف السلوك، والسلوك هنا زاد عند الطلاب الذين رأوا زميلهم يُمدح على نظافته.","الإشراط الكلاسيكي":"الإشراط الكلاسيكي اقتران مثير محايد بمثير طبيعي يستدعي استجابة لا إرادية، والنظافة هنا سلوك إرادي تعلّمه الطلاب بملاحظة زميل يُمدح.","التعلم الكامن":"التعلم الكامن لتولمان يحدث دون تعزيز ويظهر لاحقاً عند الحاجة، والتحسن هنا جاء بعد رؤية زميل يُعزَّز أمامهم مباشرة."}},"meu04t":{"w":{"الاستمرارية":"الاستمرارية بقاء السلوك قائماً حتى يتحقق الهدف، أما توجيه السلوك نحو هدف محدد كما في السؤال فهو الغرضية.","التنوع":"التنوع تعدد أساليب السلوك وتغييرها حين لا يتحقق الهدف، وهو لا يعني توجه السلوك نحو هدف محدد.","التحسين":"التحسين تحسّن الأداء مع تكرار المحاولات، والسؤال يصف خاصية أخرى هي توجه السلوك نحو هدف محدد."},"e":"الغرضية خاصية التوجه نحو هدف."},"ixls99":{"w":{"بيولوجية فطرية":"الدوافع البيولوجية الفطرية يولد بها الإنسان كالجوع والنوم، والسؤال يضع التقدير والإنجاز في مقابلها لأنهما يُكتسبان من البيئة.","فسيولوجية جسمية":"الدوافع الفسيولوجية ترتبط بحاجات الجسم كالطعام والنوم، أما التقدير والإنجاز فيكتسبهما الفرد من تفاعله مع الآخرين.","لا شعورية مكبوتة":"الدوافع اللاشعورية المكبوتة مفهوم من التحليل النفسي، والسؤال يصنّف الدوافع بمصدرها، ومصدر التقدير والإنجاز التفاعل الاجتماعي."},"e":"الدوافع الاجتماعية تُكتسب من التفاعل مع البيئة كالانتماء والتقدير والإنجاز."},"oz0297":{"w":{"ستانفورد بينيه":"مقياس ستانفورد بينيه في صورته التقليدية يعتمد كثيراً على اللغة، فلا يناسب من لا يجيدها كما يشترط السؤال.","وكسلر اللفظي":"وكسلر اللفظي هو القسم اللفظي من مقياس وكسلر، فيعتمد على اللغة لا على إكمال مصفوفات الأشكال.","مقياس ليكرت":"مقياس ليكرت أداة لقياس الاتجاهات بدرجات الموافقة والرفض، وليس اختباراً للذكاء أصلاً."},"e":"مصفوفات رافن المتتابعة اختبار غير لفظي يطلب إكمال النمط الناقص في مصفوفة أشكال، فيناسب من لا يجيد اللغة."},"1dzrij3":{"w":{"التفكير الحدسي":"التفكير الحدسي إدراك مباشر للحل بلا خطوات منظمة، والطلاب هنا يمرون بخطوات متتابعة من تحديد المشكلة إلى اختبار الفروض.","التفكير التأملي":"التفكير التأملي أعم، يتأمل الموقف ويحلله ويقترح تفسيرات، ولا يشترط جمع البيانات واختبار الفروض كما فعل الطلاب هنا.","التفكير التقاربي":"التفكير التقاربي بحث عن إجابة واحدة صحيحة، أما تسلسل المشكلة فالبيانات فالفروض فاختبارها فهو خطوات المنهج العلمي."},"e":"الإحساس بالمشكلة ثم تحديدها وجمع البيانات وفرض الفروض واختبارها والوصول إلى نتيجة هي خطوات المنهج العلمي، فالنشاط ينمي التفكير العلمي."},"1uggoz6":{"w":{"الحفظ":"الحفظ تخزين المعلومة لاسترجاعها كما هي، والطالب هنا أصدر حكماً بربط ملاحظاته الجديدة بمعلوماته السابقة.","التذكر":"التذكر استرجاع معلومة مخزنة سابقاً، أما الطالب فانتقل من ملاحظاته عن الحرارة إلى نتيجة عن تمدد المعادن.","التخيل":"التخيل تكوين صور ذهنية لأشياء غير حاضرة، والطالب هنا بنى حكمه على ملاحظات واقعية ومعلومات سابقة."},"e":"الاستدلال وصول إلى نتيجة بناءً على أدلة كافية مربوطة بالمعرفة السابقة."},"1x0fid9":{"w":{"تعزيز أي تقدم يحققه مادياً":"التعزيز المادي إجراء سلوكي يقوم على المكافأة، والسؤال يطلب حلاً من النظريات المعرفية التي تهتم بتفسير الطالب لفشله.","توفير بيئة خالية من أي نقد":"منع النقد كلياً لا يغيّر الطريقة التي يفسر بها الطالب فشله، وهذا التفسير هو محور نظرية العزو.","تشجيعه على تكرار المحاولات دون تفسير":"نظرية العزو تجعل تفسير الطالب لسبب فشله هو المفتاح، والتكرار دون تفسير يُهمل هذا العنصر الأساسي."},"e":"نظرية العزو (واينر): عزو الفشل إلى الجهد (متغير قابل للضبط) يدفع للمحاولة، وعزوه إلى القدرة يُحبط."},"4mdqo7":{"w":{"داخلي ثابت":"السبب الداخلي الثابت هو القدرة، والطالب هنا لم ينسب نجاحه إلى نفسه بل إلى سهولة الاختبار.","داخلي متغير":"السبب الداخلي المتغير هو الجهد، والطالب لم يذكر مذاكرته بل نسب نجاحه إلى سهولة الاختبار.","خارجي متغير":"السبب الخارجي المتغير هو الحظ، أما سهولة الاختبار فصفة في المهمة نفسها، فهي سبب خارجي ثابت."},"e":"صعوبة المهمة سبب خارجي ثابت."},"1mn1tg7":{"w":{"إتقان، والثاني توجهه أداء":"الترتيب هنا معكوس، فالسعي إلى أعلى درجة لإظهار التفوق توجه أداء، والسعي إلى الفهم مع قبول الخطأ توجه إتقان.","داخلي، والثاني خارجي":"داخلي وخارجي تصنيف لمصدر الدافعية، ودويك تصنّف أهداف التعلم إلى أداء يُظهر القدرة وإتقان يسعى للفهم.","تجنب، والثاني اقتراب":"الاقتراب والتجنب يصفان الإقبال على النجاح أو الهروب من الفشل، والأول هنا مقبل على إظهار تفوقه لا متجنب."}},"1hjbb57":{"w":{"مقارنة درجات الطلاب علناً":"المقارنة العلنية بين الدرجات تُحبط الطلاب الأضعف، وتحوّل الاهتمام من التعلم إلى التنافس على الترتيب.","مكافآت مادية لكل إجابة":"الإفراط في المكافآت المادية يضعف الدافعية الداخلية، فقد يتوقف الطالب عن الجهد حين تتوقف المكافأة.","تأجيل التغذية الراجعة إلى نهاية الفصل":"التغذية الراجعة المؤجلة تفقد أثرها، لأن الطالب لا يعرف خطأه ولا يصححه في وقت تعلمه."},"e":"التغذية الفورية الوصفية والأهداف القريبة ترفع الكفاءة الذاتية."},"okf76q":{"w":{"بطء تعلم":"بطء التعلم يقع بين 70 و 85 في نسبة الذكاء، والطالب هنا حصل على 68 مع قصور في مهارات الحياة.","صعوبات تعلم":"صعوبات التعلم تكون مع ذكاء عادي وتظهر في مهارة محددة كالقراءة، ودرجة 68 دون المتوسط بوضوح.","موهبة":"الموهبة تبدأ من نسبة ذكاء 130 فأكثر، والطالب هنا دون 70 ولديه قصور في السلوك التكيفي."},"e":"أقل من 70 مع قصور في السلوك التكيفي = إعاقة فكرية."},"38ahgu":{"w":{"الطلاقة":"الطلاقة عدد الأفكار، والسؤال يميز الأول بتنوع فئات أفكاره بين التخزين والديكور واللعب والزراعة لا بعددها.","الأصالة":"الأصالة ندرة الفكرة التي لا يذكرها غيره، والسؤال يركز على تنوع مجالات الأفكار لا على ندرتها.","الحساسية للمشكلات":"الحساسية للمشكلات رؤية ثغرات لا يراها الآخرون، والسؤال يقارن تنوع استخدامات العلبة بين الطالبين."}},"vclas1":{"w":{"الطلاقة":"الطلاقة كثرة الأفكار المطروحة، والطالب هنا لم يزد عدد أفكاره بل فصّل فكرة واحدة بالخطوات والرسوم.","المرونة":"المرونة تنوع فئات الأفكار وتغيير زاويتها، والطالب هنا بقي في فكرة واحدة وأضاف تفاصيلها.","الأصالة":"الأصالة ندرة الفكرة وجدّتها، والسؤال لا يصف فكرة نادرة بل إضافة خطوات وأدوات ورسوم إلى فكرة مطروحة."}},"bt0l4q":{"w":{"الحمراء":"القبعة الحمراء مشاعر وحدس بلا تبرير، والطالب هنا علّل حكمه بأسباب واضحة هي التكلفة والوقت.","الصفراء":"القبعة الصفراء للفوائد والإيجابيات، والطالب هنا يذكر مخاطر الفكرة وأسباب فشلها.","الخضراء":"القبعة الخضراء لتوليد بدائل وأفكار جديدة، والطالب هنا لم يقترح بديلاً بل حذّر من فشل الفكرة."},"e":"الحذر والسلبيات والمخاطر قبعة سوداء."},"v62mo3":{"w":{"البيضاء":"القبعة البيضاء للحقائق والأرقام المحايدة، والطالبة هنا تعبّر عن شعور بلا معلومة ولا دليل.","الصفراء":"القبعة الصفراء لذكر الفوائد والإيجابيات، والطالبة هنا تعبّر عن شعور بعدم الارتياح دون تبرير.","الزرقاء":"القبعة الزرقاء لضبط التفكير وتلخيص ما توصلت إليه المجموعة، والطالبة هنا تعبّر عن إحساسها الشخصي."}},"6tgvu9":{"w":{"إبداعي":"التفكير الإبداعي يولّد الحلول، كتوليد قائمة العشرين نفسها، أما اختيار أفضل ثلاثة بمعايير فتقويم وفرز.","تباعدي":"التفكير التباعدي يفتح إجابات متعددة، والمهمة هنا عكسه: تضييق عشرين حلاً إلى أفضل ثلاثة بمعايير محددة.","حدسي":"التفكير الحدسي إدراك مباشر بلا تبرير، والمعلم هنا يشترط تبرير الاختيار بمعايير واضحة."},"e":"الفرز والمفاضلة والتقويم بمعايير تفكير ناقد (تقاربي)."},"2ynyji":{"w":{"من بطل القصة؟":"سؤال البطل له إجابة واحدة موجودة في القصة، فهو استدعاء معلومة لا توليد أفكار جديدة.","في أي زمن وقعت أحداث القصة؟":"زمن الأحداث معلومة مذكورة في القصة يسترجعها الطالب، ولا يفتح مجالاً لإجابات متعددة أصيلة.","ما معنى الكلمة الواردة في السطر الثالث؟":"معنى الكلمة إجابة محددة يستخرجها الطالب من السياق أو يتذكرها، فلا يستدعي توليد أفكار متعددة."},"e":"السؤال المفتوح متعدد الإجابات (ماذا لو) يستدعي الطلاقة والأصالة."},"4pgmo3":{"w":{"التقليدي":"المعلم التقليدي ناقل للمعلومة يحتكر الحصة والطالب سلبي، والمعلم هنا يسلّم طلابه تنظيم تعلمهم ويكتفي بالمتابعة.","المرشد":"المرشد يوجه طلابه إلى المصادر ويرشدهم أثناء العمل، أما هنا فقد سلّمهم مسؤولية التنظيم وتوزيع المهام واكتفى بالمتابعة.","الملقن":"الملقن يملي المعلومات والطلاب متلقون، وهذا عكس معلم يترك طلابه ينظمون تعلمهم ويوزعون المهام بينهم."},"e":"المعلم المفوّض يفوض المسؤولية للطلاب ويراقب."},"g2dc6d":{"w":{"الاستنباطية (من القاعدة للأمثلة)":"الاستنباطية تبدأ بالقاعدة ثم تطبقها على الأمثلة، والمعلم هنا بدأ بالأمثلة واستنتج القاعدة منها ثم طبّق عليها.","الحوارية (السقراطية)":"الحوار السقراطي أسئلة متتابعة تكشف التناقض حتى يصل الطالب إلى الصواب، والخطوات هنا محددة: تمهيد فعرض فربط فاستنتاج فتطبيق.","طريقة المشروع (كلباترك)":"طريقة المشروع تمر باختيار الهدف والتخطيط والتنفيذ والتقويم وتنتهي بمنتج، والخطوات هنا تنتهي باستنتاج قاعدة لغوية وتطبيقها."},"e":"خطوات هربارت الخمس: تمهيد، عرض، ربط، استنتاج، تطبيق، تبدأ استقراءً وتُختم بتطبيق القاعدة؛ وتسميها بعض المراجع الاستدلالية (الهربارتية) وأغلبها الاستقرائية، والاستقرائية ليست بين البدائل."},"1s645ue":{"w":{"التاريخي":"المدخل التاريخي يرتب المحتوى بتتبع تطور الفكر عبر العصور، والمعلم هنا رتّب المادة بحسب صعوبتها ودرجة تجريدها.","الديني":"المدخل الديني يربط المحتوى بالقيم والتعاليم الدينية، والقرينة هنا تدرّج من السهل إلى الصعب ومن المحسوس إلى المجرد، وهو أساس المدخل المنطقي.","التكاملي":"المدخل التكاملي يربط المادة بغيرها كربط النسبة بالزكاة، أما ما فعله المعلم هنا فترتيب للمادة نفسها بحسب صعوبتها وتجريدها."},"e":"المدخل المنطقي يعتمد التدرج المنطقي للمادة."},"1bcayjm":{"w":{"قاعدة جاهزة وأمثلة":"القاعدة الجاهزة مع أمثلتها من سمات الاستنباط، والموقف هنا غامض فيه هدف يريده الطالب ولا يعرف بعد طريق الوصول إليه.","معلومات محفوظة تُسترجع":"استرجاع المحفوظ لا يصنع مشكلة لأن الجواب معروف مسبقاً، والطالب هنا يصرّح بأنه لا يعرف الحل ويريد الوصول إليه.","تعزيز فوري":"التعزيز الفوري مبدأ سلوكي يأتي بعد الاستجابة الصحيحة، وما يجعل الموقف مشكلة وجود هدف يسعى إليه الطالب وعائق يحول دونه."}},"1yv8avw":{"w":{"العرض العملي":"العرض العملي أداء المعلم للمهارة أمام طلابه مع شرح متزامن، والطلاب هنا يحللون موقفاً واقعياً مفصلاً ويقترحون قراراً لعلاجه.","المحاضرة":"في المحاضرة يلقي المعلم المعلومات والطالب متلقٍّ، أما هنا فالطلاب هم من يحللون موقف التنمر ويقترحون القرار.","التعليم المبرمج":"التعليم المبرمج تعلم فردي بخطوات صغيرة وتعزيز فوري، والمهمة هنا تحليل موقف واقعي متكامل واتخاذ قرار لعلاجه."},"e":"دراسة الحالة تحليل موقف واقعي أو خيالي واتخاذ قرار."},"azla21":{"w":{"الحقيبة التعليمية":"الحقيبة التعليمية مادة تعلم ذاتي فيها أهداف واختبار قبلي وأنشطة بديلة واختبار بعدي، وليست اتفاقاً مكتوباً يتعهد فيه الطالب.","الموديول":"الموديول وحدة صغيرة مستقلة من برنامج أكبر يتعلمها الطالب ذاتياً، أما هنا فاتفاق موقّع على مهام ومعايير مقابل تقدير.","الخطة العلاجية":"الخطة العلاجية إجراء يضعه المعلم لمعالجة ضعف عند الطالب، والموقف هنا تعهّد مكتوب من الطالب بإنجاز مهام مقابل تقدير."},"e":"عقد التعلم اتفاق مكتوب بين المعلم والطالب على مهام ومعايير ومكافأة."},"q2g5n7":{"w":{"التلخيص، التنبؤ، التوضيح، الأسئلة":"هذه هي الاستراتيجيات الأربع نفسها لكن بترتيب مخالف، فالترتيب الشائع يبدأ بالتنبؤ قبل القراءة ثم الأسئلة فالتوضيح ثم التلخيص.","القراءة، الحفظ، التسميع، التقويم":"هذه خطوات حفظ وتسميع لا حوار فيها حول النص، واستراتيجيات التدريس التبادلي تنبؤ وتوليد أسئلة وتوضيح وتلخيص تنمي ما وراء المعرفة.","العصف، التصنيف، المقارنة، الحكم":"هذه مهارات تفكير عامة لا تخص التدريس التبادلي، فاستراتيجياته الأربع عند بالينسكار وبراون التنبؤ والأسئلة والتوضيح والتلخيص."}},"1mh3ejl":{"w":{"تعاونية":"البيئة التعاونية ينجح فيها الجميع معاً، والقرينة هنا أن فوز طالب مرتبط بخسارة زميله.","فردية":"في البيئة الفردية يعمل كل طالب مستقلاً ولا يرتبط نجاحه بنتيجة غيره، وهنا نجاح الطالب مرتبط بخسارة زميله.","تشاركية":"البيئة التشاركية يتقاسم فيها الطلاب العمل والنجاح كالتعاونية، أما هنا فلا يفوز إلا واحد على حساب الآخرين."},"e":"البيئة التنافسية يرتبط فيها الفوز بخسارة الآخر."},"1pfhclv":{"w":{"داخل الفصل":"تدريس الأقران داخل الفصل يكون بين زملاء الصف نفسه، والطالب المعلِّم هنا من الثالث المتوسط ويعلّم طلاب الأول المتوسط.","خارج الفصل للمنقطعين":"السؤال لا يذكر منقطعين ولا تعليماً خارج الفصل، والحاسم أن الطالب المعلِّم من صف أعلى يعلّم طلاب صف أدنى، وهذا تدريس عبر الصفوف.","أقران المجموعة":"أقران المجموعة زملاء يتعلمون معاً داخل مجموعتهم، والحاسم هنا أن الطالب المعلِّم من الصف الثالث والمتعلمين من الصف الأول."},"e":"تدريس الأقران عبر الصفوف: طالب من صف أعلى يعلم طلاب صف أدنى."},"1ghlrop":{"w":{"تقنيات التعليم":"تقنيات التعليم أشمل من الأدوات لأنها منظومة من الإنسان والآلة والطريقة، والتعريف هنا مقصور على الأجهزة والأدوات والمواد.","مصادر التعلم":"مصادر التعلم أوسع، فهي كل ما يتفاعل معه المتعلم ليتعلم، والتعريف هنا محصور في أجهزة وأدوات ومواد تُكسب خبرات محددة.","المنهج":"المنهج أوسع بكثير، إذ يشمل الأهداف والمحتوى والطرق والتقويم، أما الأجهزة والمواد التي تُكسب خبرات محددة فهي الوسائل."},"e":"الوسائل التعليمية أدوات ومواد."},"jgdmiu":{"w":{"الميسّر (المسهّل)":"الميسّر يهيئ ظروف التعلم ويدعم الطلاب عند الحاجة وهم نشطون، والمعلم هنا يحتكر الحديث والطلاب متلقون صامتون.","المفوّض للمسؤولية":"المفوّض يسلّم طلابه مسؤولية تعلمهم ويتابع، وهذا عكس معلم يحتكر الحديث ويملي المعلومات طوال الحصة.","المرشد (الموجّه)":"المرشد يوجه طلابه إلى المصادر ليصلوا إلى المعلومة، أما هنا فالمعلم يملي المعلومات بنفسه والطلاب صامتون."},"e":"المعلم التقليدي ناقل للمعلومة والطالب سلبي."},"pl9mo6":{"w":{"المعرفي، والاجتماعي":"المعرفي يهتم بالتفكير والاكتشاف، والاجتماعي بالتفاعل والنمذجة، والمعلمان هنا يركز أحدهما على التعزيز وضبط السلوك والآخر على المشاعر والإدراكات الذاتية.","الاجتماعي، والسلوكي":"الضبط بالتعزيز والتعليم المبرمج سلوكي لا اجتماعي، ومشاعر الطالب وإدراكاته الذاتية من اهتمام المدخل الإنساني لا السلوكي.","الإنساني، والمعرفي":"التعزيز والتعليم المبرمج من المدخل السلوكي لا الإنساني، والمعرفي يهتم بالتفكير والاكتشاف لا بمشاعر الطالب وإدراكاته الذاتية."},"e":"السلوكي ضبط وتعزيز، والإنساني أو الشخصي يركز على الإدراكات الفردية والوجدان."},"a811ya":{"w":{"عامة وخاصة":"التقسيم إلى عامة وخاصة يكون بحسب حاجة التخصص، والسؤال هنا عن التقسيم بحسب الاحتكاك بين المعلم والمتعلم.","جمعية وفردية":"التقسيم إلى جمعية وفردية يكون بحسب عدد المتعلمين، لا بحسب درجة الاحتكاك بين المعلم والمتعلم.","استقرائية واستنباطية":"الاستقراء والاستنباط يختلفان في اتجاه السير بين الأمثلة والقاعدة، وهذا تقسيم بحسب طريقة التفكير لا بحسب الاحتكاك بين المعلم والمتعلم."},"e":"وفق الاحتكاك: مباشرة وغير مباشرة."},"rdhr0o":{"w":{"التدريس المصغر":"التدريس المصغر تدريب للمعلم على مهارة تدريسية واحدة مع عدد قليل من الطلاب، وليس برنامج تعلم ذاتي باختبارات قبلية وبعدية.","لعب الأدوار":"لعب الأدوار استراتيجية جماعية يمثل فيها الطلاب مشهداً ثم يناقشون سلوكياته، والوصف هنا برنامج تعلم ذاتي فردي متكامل.","العصف الذهني":"العصف الذهني توليد جماعي للأفكار بإرجاء النقد والكم قبل الكيف، ولا صلة له بالحقائب التعليمية ولا بالاختبارات القبلية والبعدية."},"e":"المجمعات التعليمية نظام تعلم ذاتي متكامل."},"1nwf36o":{"w":{"الاجتماعية":"العائلة الاجتماعية تقوم على التفاعل بين الطلاب كالتعلم التعاوني ولعب الأدوار، والتعليم المبرمج والإتقان يقومان على خطوات صغيرة وتعزيز.","الشخصية":"العائلة الشخصية تركز على الفرد ووجدانه وتطوره الذاتي كالتدريس غير الموجه، لا على ضبط السلوك بالتعزيز والخطوات الصغيرة.","معالجة المعلومات":"معالجة المعلومات تركز على العمليات العقلية كالاستقراء واكتساب المفاهيم والمنظم المتقدم، لا على تعديل السلوك بالتعزيز."},"e":"يقسم جويس وويل نماذج التدريس إلى أربع عائلات: معالجة المعلومات، والاجتماعية، والشخصية، والنظم السلوكية. والتعليم المبرمج والتعلم للإتقان والتعليم المباشر من عائلة النظم السلوكية، لأنها تقسّم التعلم إلى خطوات صغيرة متتابعة مع تغذية راجعة وتعزيز فوري. أما الاجتماعية فتضم التعلم التعاوني ولعب الأدوار."},"izauts":{"w":{"السلوكية":"العائلة السلوكية تعدّل السلوك بخطوات صغيرة وتعزيز كالتعليم المبرمج، والمطلوب هنا تعلم يقوم على تفاعل الطلاب في جو اجتماعي.","الشخصية":"العائلة الشخصية تركز على الفرد وتطوره الذاتي، أما التعلم التعاوني والتقصي الجماعي فيقومان على التفاعل مع الآخرين.","معالجة المعلومات":"معالجة المعلومات تركز على العمليات العقلية كالاستقراء والمنظم المتقدم، والنموذجان المذكوران يقومان على العمل الجماعي والتفاعل."},"e":"العائلة الاجتماعية تركز على التعلم من التفاعل مع الآخرين."},"1qis62p":{"w":{"الاستقراء":"الاستقراء يبدأ بالأمثلة حتى يصل الطلاب إلى القاعدة، والمعلم هنا بدأ بذكر قاعدة المساحة ثم طلب تطبيقها.","الاكتشاف الحر":"في الاكتشاف الحر يحدد الطالب المشكلة والأدوات ويصل إلى المفهوم بنفسه، والقاعدة هنا قدّمها المعلم جاهزة.","حل المشكلات":"حل المشكلات يبدأ بالشعور بمشكلة ثم وضع الفروض واختبارها، والدرس هنا عرض قاعدة جاهزة ثم تطبيقها على مسائل."},"e":"الاستنباط (القياس) يسير من القاعدة العامة إلى الحالات الجزئية."},"8oyzki":{"w":{"المحاضرة":"المحاضرة إلقاء لفظي مجرد يجعل المتعلم متلقياً، ولا تثير خيال طالبات في السادسة كما تفعل القصة.","المناظرة":"المناظرة مجموعة مؤيدة وأخرى معارضة يحكم بينهما محكّمون، وتحتاج نضجاً جدلياً أكبر من مرحلة الصف الأول الابتدائي.","التعليم المبرمج":"التعليم المبرمج تعلم فردي بخطوات صغيرة وتعزيز، ولا يناسب الأهداف الوجدانية كغرس قيمة الصدق."},"e":"القصة تناسب الصغار وتقدم القيم في موقف حي يثير الخيال."},"vnkvdh":{"w":{"وضع خطة تفصيلية للتنفيذ":"التخطيط هو الخطوة الثانية ويأتي بعد اختيار المشروع، إذ لا تُوضع خطة تفصيلية لمشروع لم يُختر بعد.","تنفيذ المشروع ميدانياً في الحديقة":"التنفيذ الميداني هو الخطوة الثالثة، ويسبقه اختيار المشروع مع الطلاب ثم التخطيط له.","تقويم المشروع ونتائجه":"التقويم يأتي بعد التنفيذ للحكم على ما أنجزه الطلاب، فهو من آخر خطوات المشروع، والبداية اختيار المشروع بمشاركتهم."}},"18iyz0u":{"w":{"المحاضرة المسجلة":"المحاضرة المسجلة مصدر عرض واحد يتلقاه الطالب، وليس فيها اختبار قبلي وبعدي ولا أنشطة بدائل كما في الوحدة الموصوفة.","الرحلة المعرفية":"الرحلة المعرفية بحث موجّه عبر الإنترنت، أما الوحدة الموصوفة فتجمع أهدافاً واختباراً قبلياً وأنشطة بدائل واختباراً بعدياً.","خريطة المفاهيم":"خريطة المفاهيم رسم يربط المفاهيم بعلاقاتها، وهي أداة لتنظيم المعرفة لا وحدة تعلم ذاتي باختبارات وأنشطة بدائل."},"e":"الحقيبة التعليمية وحدة تعلم ذاتي متكاملة بهذه المكونات."},"jqyt41":{"w":{"التفاعل وجهاً لوجه":"التفاعل وجهاً لوجه تواصل الأعضاء المباشر أثناء العمل، وقد يوجد شكلاً هنا، لكن المفقود محاسبة كل عضو على إسهامه.","الاعتماد الإيجابي المتبادل":"الاعتماد الإيجابي المتبادل ربط نجاح كل عضو بنجاح المجموعة، ومشكلة هذه المجموعة ليست الربط بل غياب محاسبة كل عضو على إسهامه.","المهارات الاجتماعية":"المهارات الاجتماعية كالإصغاء وإدارة الخلاف، والسؤال لا يذكر خللاً في التواصل، بل يذكر أن طالباً واحداً أنجز العمل والبقية شاهدوا."},"e":"المسؤولية الفردية تعني أن كل عضو مسؤول عن تعلمه وإسهامه، ويضمنها المعلم بتوزيع الأدوار والاختبار الفردي."},"1kpwf6d":{"w":{"العصف الذهني":"العصف الذهني توليد أكبر عدد من الأفكار حول قضية مع إرجاء الحكم، والطلاب هنا يمثلون موقفاً بأدوار محددة لا يولّدون أفكاراً.","التدريس التبادلي":"التدريس التبادلي حوار حول نص مقروء بالتلخيص والتساؤل والتوضيح والتنبؤ، والطلاب هنا يمثلون مقابلة عمل ولا يحللون نصاً.","الاستقراء":"الاستقراء انتقال من الأمثلة إلى استنتاج القاعدة، والنشاط هنا تمثيل موقف واقعي بأدوار ثم مناقشته، لا استنتاج قاعدة."},"e":"لعب الأدوار محاكاة لموقف واقعي يتقمص فيه الطلاب أدواراً ثم يناقشونها."},"1bntas6":{"w":{"حذف الفكرة التي سُخر منها لأنها غير منطقية":"حذف الفكرة حكم عليها في مرحلة التوليد، وهذا يخالف إرجاء الحكم ويؤيد السخرية بدل أن يوقفها.","إيقاف الجلسة ومعاقبة الطالب الساخر":"إيقاف الجلسة والعقاب يقطعان تدفق الأفكار، والمطلوب تصحيح السلوك بتذكير القاعدة مع مواصلة جمع الأفكار.","الطلب من صاحب الفكرة الدفاع عنها الآن":"الدفاع عن الفكرة الآن يحوّل الجلسة إلى نقاش وتقويم في مرحلة التوليد، ومناقشة الأفكار تأتي بعد انتهاء جمعها."},"e":"إرجاء الحكم قاعدة أساسية، والمعلم يعيد تثبيتها دون قطع الجلسة."},"xbtrpu":{"w":{"حضور دورة نظرية عن الأسئلة":"الدورة النظرية تعطي معرفة عن الأسئلة دون ممارسة فعلية، والمعلم هنا يريد أن يتدرب عملياً ويتلقى تغذية راجعة على أدائه.","قراءة كتاب في طرق التدريس":"القراءة تبني معرفة نظرية فقط، ولا تتيح للمعلم أن يمارس طرح الأسئلة ويتلقى تغذية راجعة من مدرب وزملاء.","تدريس حصة كاملة أمام المشرف":"الحصة الكاملة تجمع مهارات كثيرة فتشتت التركيز، والمعلم يريد التدرب على مهارة طرح الأسئلة وحدها دون درس كامل."},"e":"التدريس المصغر مصمم لهذا الغرض: مهارة واحدة، وقت قصير، تغذية راجعة، وإعادة أداء."},"nqdulk":{"w":{"خبرة ممثلة":"الخبرة الممثلة تمثيل درامي لموقف يتعذر عيشه، والطالبات هنا يزرعن البذور فعلاً ويتابعن نموها بأنفسهن.","رموز بصرية":"الرموز البصرية رسوم وخرائط ومخططات مجردة، والطالبات هنا يمارسن الزراعة الحقيقية بأيديهن لا يشاهدن رسماً.","خبرة بديلة عبر الفيديو":"الفيديو خبرة مشاهدة يرى فيها الطالب ما يحدث دون أن يمارسه، والطالبات هنا يزرعن ويتابعن النمو بأنفسهن."},"e":"الطالبة تمارس النشاط الحقيقي بنفسها، وهذه الخبرة المباشرة الهادفة في قاعدة المخروط."},"1v1boh2":{"w":{"إجراء التجربة بحذر مع تقليل الكميات":"السؤال ينص على أن التفاعل خطر لا يمكن إجراؤه في معمل المدرسة، فتقليل الكميات لا يجعله ممكناً ولا آمناً هناك.","الاكتفاء بوصف التجربة شفهياً":"الوصف الشفهي رمز لفظي في قمة التجريد وضعيف الأثر، والمحاكاة تقرّب التجربة للطلاب بصورة أقرب إلى الواقع دون خطر.","تكليف الطلاب بإجرائها في المنزل":"نقل تجربة خطرة إلى المنزل يعرّض الطلاب للخطر بعيداً عن إشراف المعلم، والمحاكاة بديل آمن يحقق الهدف نفسه."},"e":"المحاكاة خبرة بديلة آمنة تقرب التجارب الخطرة أو المكلفة."},"igkw6d":{"w":{"المحاضرة":"المحاضرة يقدم فيها المعلم الرأي والمعلومة جاهزين، ولا يقود الطالب بأسئلة متتابعة ليكتشف التناقض في رأيه بنفسه.","التعليم المبرمج":"التعليم المبرمج تعلم فردي بإطارات مكتوبة متتابعة وتعزيز فوري، لا حوار مباشر يقوده المعلم بالأسئلة لكشف التناقض.","لعب الأدوار":"لعب الأدوار تمثيل موقف يتقمص فيه الطلاب شخصيات ثم يناقشونه، وليس سلسلة أسئلة تكشف التناقض في رأي الطالب."},"e":"الحوار السقراطي يقوم على أسئلة متتابعة تقود المتعلم إلى اكتشاف الحقيقة."},"2l27l7":{"w":{"الاكتشاف الحر بالتجريب الذاتي":"الاكتشاف الحر يحتاج وقتاً طويلاً ويحدد فيه الطالب المشكلة والأدوات، فلا يتسع لمحتوى كثيف مع 45 طالباً في حصة واحدة.","المشروعات الجماعية خارج الحصة":"المشروعات تمر بالتخطيط والتنفيذ والتقويم وتحتاج وقتاً طويلاً، والمعلم هنا يريد تغطية محتوى نظري كثيف في حصة واحدة قبل الاختبار.","لعب الأدوار في مجموعات صغيرة":"لعب الأدوار يناسب تمثيل المواقف الاجتماعية، ولا يناسب تغطية محتوى نظري كثيف لصف كبير في حصة واحدة."},"e":"المحاضرة اقتصادية في الوقت وتناسب الأعداد الكبيرة والمحتوى الكثيف، ويُحسّنها دعمها بالعرض والأسئلة."},"15uyv66":{"w":{"الحقائق المنفصلة كالتواريخ":"التواريخ حقائق منفصلة تُحفظ مباشرة ولا قاعدة فيها تُستنتج، والاستقراء يسير من الأمثلة إلى بناء القاعدة أو المفهوم.","المهارات الحركية":"المهارات الحركية تحتاج العرض العملي والممارسة، والاستقراء طريقة لاستنتاج المفهوم أو القاعدة من الأمثلة لا لأداء الحركة.","القراءة الجهرية":"القراءة الجهرية مهارة أدائية تنمو بالقدوة والتدريب، والاستقراء يناسب بناء مفهوم أو قاعدة من أمثلة متعددة."},"e":"الاستقراء يبني المفهوم أو القاعدة من الأمثلة، فيناسب المفاهيم والتعميمات."},"1qjwp29":{"w":{"سلوكياً، وعاماً":"الترتيب هنا معكوس: حب الوطن لا يُقاس مباشرة في حصة فهو العام، و«يذكر ثلاث مدن» فعل ملاحظ بمحتوى محدد فهو السلوكي.","وجدانياً، ونفس‑حركياً":"«يذكر ثلاث مدن» استرجاع لمعلومة من المجال المعرفي لا أداء حركي، فوصف الهدف الثاني بالنفس‑حركي لا يصح.","تربوياً، وغاية":"الغاية أبعد مستويات الأهداف وتعبر عن فلسفة المجتمع، و«يذكر ثلاث مدن» هدف دقيق لحصة واحدة يُقاس مباشرة فهو سلوكي."}},"h2wdwa":{"w":{"تتضمن أكثر من ناتج تعلم":"تعدد النواتج يكون حين يجمع الهدف فعلين مثل «يذكر ويشرح»، وهنا فعل واحد هو «يوضح»، فالمشكلة في الفاعل لا في العدد.","غير مرتبطة بالمحتوى":"المحتوى في الصياغة محدد وهو مفهوم التفاعل الكيميائي، فالخلل ليس في المحتوى بل في أن الفاعل هو المعلم.","تفتقر إلى الفعل السلوكي":"«يوضح» فعل سلوكي ظاهر يمكن ملاحظته، لكنه منسوب هنا إلى المعلم، والهدف السلوكي يصف ما يفعله الطالب."},"e":"الهدف السلوكي يصف ما سيفعله الطالب بعد التعلم، والصياغة هنا فاعلها المعلم."},"tqbzy1":{"w":{"يصف سلوك المعلم":"الفاعل في الصياغة هو الطالب لا المعلم، فالمشكلة هنا ليست في الفاعل بل في جمع «يذكر» و«يشرح» في هدف واحد.","يستخدم فعلاً غير قابل للقياس":"«يذكر» و«يشرح» فعلان ظاهران يمكن ملاحظتهما وقياسهما، والخلل في اجتماعهما ناتجين في هدف واحد لا في نوع الفعل.","يفتقر إلى المحتوى":"المحتوى محدد وهو أركان الإسلام، فالصياغة لا ينقصها محتوى، وإنما تحمل ناتجين من مستويين مختلفين في هدف واحد."},"e":"القاعدة أن يتضمن الهدف ناتج تعلم واحداً؛ وهنا «يذكر» و«يشرح» ناتجان من مستويين مختلفين."},"solhqr":{"w":{"شرط الأداء":"شرط الأداء هو الظرف الذي يؤدي فيه الطالب العمل، وفي هذا الهدف هو «دون آلة حاسبة»، أما «8 من 10» فحد أدنى للإتقان.","الفعل السلوكي":"الفعل السلوكي في الهدف هو «يحل»، وعبارة «8 من 10» لا تصف ما يفعله الطالب بل الحد الأدنى المقبول من أدائه.","المحتوى":"المحتوى هو مسائل الجمع التي يعمل عليها الطالب، أما «8 من 10» فتحدد مقدار الإتقان المطلوب لا موضوع التعلم."},"e":"المعيار هو الحد الأدنى المقبول للأداء."},"1xt9kqa":{"w":{"زيادة عدد أسئلة التذكر لتكون أشمل":"زيادة أسئلة التذكر تعمّق المشكلة نفسها، فمعظم الأسئلة تقيس التذكر أصلاً، والمطلوب إضافة أسئلة للمستويات العليا كالتحليل والتقويم.","حذف كل أسئلة التذكر من الاختبار":"التذكر مستوى مطلوب في الاختبار المتوازن، والمشكلة هنا غياب المستويات العليا لا وجود التذكر، فلا يُحذف كلياً.","تحويل الأسئلة كلها إلى مقالية":"تغيير شكل السؤال إلى مقالي لا يرفع مستواه بالضرورة، فسؤال «اذكر» يبقى تذكراً ولو كان مقالياً."},"e":"الأسئلة الحالية تقيس التذكر فقط، والاختبار الجيد يغطي المستويات العليا وفق جدول المواصفات دون إلغاء التذكر كلياً."},"18vz863":{"w":{"الاستجابة، الاستقبال، التنظيم، التقييم، التميز بالقيمة":"يقدّم الاستجابة على الاستقبال والتنظيم على التقييم، والطالب لا يستجيب لمثير قبل أن ينتبه إليه، ولا ينظّم قيماً قبل تبنيها.","الاستقبال، التقييم، الاستجابة، التميز بالقيمة، التنظيم":"يضع التقييم قبل الاستجابة ويختم بالتنظيم، والصحيح أن المشاركة تسبق تبني القيمة، وأن التميز بالقيمة هو القمة بعد التنظيم.","التنظيم، الاستقبال، الاستجابة، التقييم، التميز بالقيمة":"يبدأ بالتنظيم وهو ترتيب القيم في نظام، ولا يرتب الطالب قيماً لم يتبنها بعد، فالبداية الصحيحة الاستقبال أي الانتباه."}},"154t3x8":{"w":{"الاستجابة":"الاستجابة مشاركة فعلية كالسؤال أو تنفيذ المطلوب، والطالب هنا يصغي فقط دون أن يشارك أو يبادر.","التقييم":"التقييم أن يتبنى الطالب القيمة ويظهر تقديره لها في سلوكه، والسؤال يصف إصغاءً فقط دون مشاركة أو تبنٍّ.","التنظيم":"التنظيم ترتيب القيم في نظام متسق بعد تبنيها، وهو أعلى بكثير من حال طالب ما زال يصغي دون مشاركة."},"e":"الاستقبال هو الانتباه والإصغاء للمثير، وهو أدنى المستويات."},"sitl3k":{"w":{"الاستقبال":"الاستقبال مجرد انتباه وإصغاء للمثير، والطالب هنا يمارس النظافة من تلقاء نفسه حتى صارت سمة معروفة عنه.","الاستجابة":"الاستجابة مشاركة عند الطلب أو التوجيه، أما هذا الطالب فينظف من تلقاء نفسه في كل موقف حتى صار ذلك سمة له.","التقييم":"التقييم تبني القيمة وتقديرها دون أن تصير سمة ثابتة بعد، والسؤال يصف قيمة صارت جزءاً من شخصية الطالب يعرفه بها زملاؤه."},"e":"التميز بالقيمة أعلى المستويات: تصبح القيمة جزءاً ثابتاً من الشخصية يوجه السلوك باستمرار."},"4loawo":{"w":{"كراثوول":"كراثوول صاحب تصنيف المجال الوجداني بمستوياته الخمسة من الاستقبال إلى التميز بالقيمة، لا تصنيف المهارات الحركية.","بلوم":"بلوم ارتبط اسمه بتصنيف المجال المعرفي بمستوياته الستة من التذكر إلى التقويم، والسؤال عن تصنيف المجال المهاري.","ماجر":"ماجر معروف بصياغة الهدف السلوكي بمكوناته الثلاثة: السلوك والشرط والمعيار، وليس صاحب تصنيف مستويات المجال المهاري."},"e":"سمبسون صاحب التصنيف السباعي للمجال النفس‑حركي (ومعه هارو وديف)."},"1uqegnc":{"w":{"الآلية":"الآلية أداء المهارة بثقة وتعوّد دون حاجة إلى توجيه، والطالب هنا ما زال يقلد يد المعلم خطوة بخطوة تحت إشرافه.","الاستجابة المعقدة":"الاستجابة المعقدة أداء سلس لمهارة مركبة بلا تردد، والطالب هنا في بداية التعلم يقلد المعلم خطوة بخطوة.","الإبداع":"الإبداع أعلى مستويات سمبسون وفيه يبتكر المتعلم أنماطاً حركية جديدة، والطالب هنا يقلد حركة المعلم ولا يبتكر."},"e":"الاستجابة الموجهة أداء المهارة بالتقليد والمحاولة تحت توجيه."},"10pbgf4":{"w":{"الاستجابة الموجهة":"الاستجابة الموجهة أداء المهارة بالتقليد تحت توجيه في أول تعلمها، واللاعب هنا أتقن التصويب ويعدّله وحده لمواقف متغيرة.","الإدراك الحسي":"الإدراك الحسي أول مستويات سمبسون، وفيه ينتبه المتعلم بحواسه لمثيرات المهارة قبل أدائها، لا تعديل مهارة متقنة.","الاستعداد":"الاستعداد التهيؤ الذهني والجسمي والانفعالي لأداء المهارة قبل البدء بها، واللاعب هنا يؤدي مهارة متقنة ويعدّلها لموقف جديد."},"e":"التكيف تعديل المهارة المتقنة لمواجهة مواقف جديدة."},"1f3nxmp":{"w":{"التهيئة":"التهيئة تكون في بداية الحصة لإعداد الطلاب للدرس، والخطوة هنا في دقائقها الأخيرة لتلخيص الأفكار وربطها.","التقويم القبلي":"التقويم القبلي يُجرى قبل التدريس لمعرفة ما لدى الطلاب، أما تلخيص أفكار الدرس في آخر الحصة فهو غلق.","التمهيد":"التمهيد مدخل يسبق عرض الدرس في بدايته، بينما يطلب المعلم هنا تلخيص الأفكار وربطها في ختام الحصة."},"e":"الغلق خطوة ختامية لتلخيص الدرس وتثبيته."},"12ek1vk":{"w":{"الطلاب سينسون أنهم اختُبروا":"المشكلة ليست في تذكّر الطلاب للاختبار، بل في أن التأخير يفصل بين أدائهم ومعرفة أخطائهم فيضعف التصحيح.","الدرجات ستكون أقل من المتوقع":"الدرجات تحددها إجابات الطلاب وقت الاختبار لا موعد إعادة الأوراق، فالتأخير يمس أثر التغذية الراجعة لا الدرجة.","المعلم سيحتاج إلى إعادة الاختبار":"تأخر إعادة الأوراق لا يُبطل الاختبار ولا يستدعي إعادته، وإنما يقلل استفادة الطلاب من معرفة نتائجهم وأخطائهم."},"e":"التغذية الراجعة الفورية أعلى أثراً، وتأخيرها يفصل بين الأداء ومعرفة النتيجة فيضعف التصحيح."},"1m72bla":{"w":{"الأول لأنه يرفع معنويات الطالب":"كلمة «ممتاز» قد تشجع الطالب، لكنها لا تبين له ما أحسنه ولا ما يحتاج تحسيناً في مقاله.","الأول لأنه أقصر وأسرع":"قِصر التعليق لا يجعله أنفع، فالعبرة بأن يحدد للطالب موضع الضعف وخطوة التحسين كما فعل التعليق الثاني.","كلاهما بالقدر نفسه":"التعليقان غير متكافئين، فالأول حكم عام بلا توجيه، والثاني يحدد ضعف الدليل الثاني ويقترح إضافة مثال من النص."},"e":"التغذية الراجعة الوصفية المحددة توضح جوانب القوة والضعف وخطوة التحسين."},"zv94p2":{"w":{"مفهوم":"المفهوم تصور مجرد يُطلق على فئة مثل «الغليان»، والعبارة هنا معلومة محددة ثابتة قابلة للتحقق عن درجة غليان الماء.","تعميم":"التعميم عبارة تربط بين مفهومين أو أكثر وتنطبق على حالات كثيرة، والعبارة هنا معلومة واحدة محددة يمكن التحقق منها بالقياس.","مهارة":"المهارة أداء يتقنه الطالب بالممارسة مثل استخدام مقياس الحرارة، والعبارة هنا معلومة تُعرف لا أداء يُنفَّذ."},"e":"الحقيقة معلومة محددة ثابتة قابلة للتحقق."},"8tyq1b":{"w":{"6 أسئلة":"الرقم 6 هو عدد حصص الوحدة لا عدد أسئلتها، والصحيح 6 ÷ 20 = 30%، و 30% من 40 = 12 سؤالاً.","20 سؤالاً":"هذا العدد نصف الاختبار، أي كأن الوحدة أخذت 10 حصص من 20، وهي أخذت 6 فقط فنصيبها 12 سؤالاً.","8 أسئلة":"هذا العدد يساوي 20% من 40، أي ما يقابل 4 حصص فقط، والوحدة أخذت 6 حصص فنصيبها 12 سؤالاً."},"e":"الوزن النسبي = 6 ÷ 20 = 30%، و30% من 40 = 12 سؤالاً."},"edwf74":{"w":{"يزيد تحصيل الطلاب أكثر من اللازم":"مشكلة الإجراء ليست زيادة التحصيل، بل أن ربط الواجب بالعقاب يجعله منفراً ويضعف دافعية الطلاب نحو المادة.","يستغرق وقتاً في التصحيح":"وقت التصحيح عبء على المعلم لا على الطلاب، والخلل التربوي هنا أن الواجب صار عقاباً فيكره الطلاب الواجب والمادة.","يخالف رغبة أولياء الأمور":"السؤال لا يذكر موقف أولياء الأمور، والعلة في الإجراء نفسه: الواجب أداة تعلم، واستخدامه عقاباً ينفّر منه."},"e":"الواجب أداة تعلم لا عقاب؛ ربطه بالعقاب يجعله منفراً ويقتل دافعيته."},"11n6988":{"w":{"توافر جهاز العرض وجاهزية القاعة قبل بداية الحصة":"جاهزية الجهاز والقاعة أمر تنظيمي، ولا تحدد قدرة الطلاب على تعلم جمع الكسور العشرية كما يحددها إتقانهم للمتطلبات السابقة.","موعد اختبار الوحدة في الخطة الفصلية":"موعد اختبار الوحدة يخص الخطة الفصلية، ولا يكشف هل يملك الطلاب ما يلزمهم لفهم جمع الكسور العشرية.","عدد الطلاب الغائبين عن الحصة السابقة":"عدد الغائبين معلومة تنظيمية، والأهم قبل الدرس التأكد من إتقان الطلاب جميعاً للمتطلبات السابقة التي يُبنى عليها."},"e":"المتطلبات السابقة شرط لبناء التعلم الجديد، والتأكد منها جزء من التخطيط."},"5dzebk":{"w":{"الاكتفاء بالشرح وتحويل كل الأنشطة إلى واجبات منزلية":"تحويل الأنشطة كلها إلى واجبات يفرغ الحصة من التطبيق، والأنسب تنفيذ الأهم منها للأهداف وتأجيل الباقي.","أخذ حصة إضافية من زميل":"أخذ حصة من زميل يسد نقص الوقت على حساب مادة أخرى، ولا يعالج التخطيط نفسه بترتيب الأنشطة حسب أولويتها.","تنفيذ الأنشطة كلها بسرعة دون تقويم":"تسريع الأنشطة وحذف التقويم يضعف التعلم ويحرم المعلم من دليل على تحقق الأهداف."},"e":"التخطيط يقوم على الأولوية للأهداف؛ فيُنفذ الأهم ويؤجل الباقي."},"6wgdyz":{"w":{"الاعتماد على التعريفات اللفظية المجردة لأنها أدق":"التعريفات اللفظية رموز مجردة يصعب فهمها على من لم يصل إلى قدرة عالية على التجريد، كبعض الطلاب هنا.","تأجيل الدرس حتى ينضج الطلاب عقلياً":"تأجيل الدرس يهمل دور التعليم في دعم النمو، والدرس مقرر لصفهم فيُيسَّر لهم بالمحسوسات بدل انتظار نضجهم.","تكليف الطلاب بقراءة الدرس من الكتاب فقط":"القراءة وحدها تعتمد على الرموز المجردة أيضاً، فلا تقدم لمن يحتاج المحسوس نموذجاً يراه أو يلمسه."},"e":"التخطيط يراعي مستوى النمو المعرفي؛ فالمحسوسات والنماذج جسر إلى المجرد."},"jxh8sx":{"w":{"أن يعدد الطالب علامات رفع الفعل المضارع الأصلية":"التعداد استرجاع لمعلومة محفوظة فهو في مستوى التذكر، أما إعطاء مثال من عند الطالب فيدل على فهمه.","أن يصمم الطالب لوحة تجمع أزمنة الفعل وأحكامه":"التصميم إنتاج عمل جديد فهو في مستوى الإبداع، ويقابله التركيب في تصنيف بلوم الأصلي، لا في مستوى الفهم.","أن يحكم الطالب على صحة إعراب زميله في الجملة":"الحكم على صحة عمل الآخرين في مستوى التقويم، وهو من المستويات العليا لا من مستوى الفهم."},"e":"إعطاء مثال من عند الطالب يدل على إدراك المعنى، وهو فهم."},"ldsidt":{"w":{"يُرضي المشرف التربوي عند زيارته الصفية":"إرضاء المشرف غاية شكلية، والتخطيط وُضع لخدمة تعلم الطلاب بتوجيه التنفيذ نحو الأهداف.","يقلل عدد الحصص المطلوبة لإنهاء المقرر":"عدد حصص المقرر محدد مسبقاً، والتخطيط ينظم استثمارها نحو الأهداف ولا يختصرها.","يغني عن التقويم في نهاية الدرس":"التخطيط لا يغني عن التقويم بل يتضمنه، فخطة الدرس تحدد أدوات التقويم التي تكشف تحقق الأهداف."},"e":"التخطيط خريطة التنفيذ: يحدد الأهداف مسبقاً ويرتب لها الأنشطة والوقت والتقويم، فيمضي الدرس نحوها بلا عشوائية."},"ifub0t":{"w":{"التقويمية":"التهيئة التقويمية تتحقق بأسئلة من فهم الطلاب للدرس السابق، وسؤال المعلم هنا لغز جديد يثير الفضول لا مراجعة للسابق.","الانتقالية":"التهيئة الانتقالية تربط ما سبق تعلمه بالجديد، أما سؤال المعلم هنا فمفارقة محيرة غرضها إثارة الفضول وحب الاستطلاع.","الغلق":"الغلق يأتي في ختام الحصة لتلخيص الدرس، والمعلم هنا طرح سؤاله في بدايتها قبل أن يبدأ الدرس."},"e":"السؤال المحير يثير الاهتمام وحب الاستطلاع، وهذه التهيئة الحافزة."},"1suuix1":{"w":{"الكرسي الساخن":"الكرسي الساخن يجلس فيه طالب واحد يجيب عن أسئلة زملائه، ولا ترقيم فيه ولا استدعاء عشوائي لممثل المجموعة.","حوض السمك":"حوض السمك دائرتان: داخلية تتناقش وخارجية تلاحظ، والموقف هنا ترقيم أعضاء المجموعة واستدعاء رقم عشوائي.","جيكسو":"جيكسو يتخصص فيها كل عضو بجزء من الموضوع في مجموعة خبراء ثم يعلّمه لمجموعته، ولا تقوم على نداء رقم عشوائي."},"e":"الرؤوس المرقمة تضمن استعداد كل عضو لأن أي رقم قد يُستدعى."},"1px8wlh":{"w":{"أشكال فن":"أشكال فن دائرتان متقاطعتان للمقارنة بين مفهومين، لا بطاقة رباعية لتعريف مفهوم واحد وخصائصه وأمثلته.","جدول KWL":"جدول KWL أعمدة ثلاثة للمعرفة السابقة والمرغوبة والمكتسبة، لا خانات أربع للتعريف والخصائص والأمثلة والأمثلة غير المنتمية.","خريطة الشكل V":"خريطة الشكل V تُستخدم في التجارب العلمية لربط المفاهيم والنظريات بخطوات العمل حول سؤال رئيس، لا بطاقة رباعية لمفهوم."},"e":"فراير منظم رباعي للمفهوم (تعريف، خصائص، أمثلة، لا أمثلة)."},"1f4pthl":{"w":{"التدريس التبادلي":"التدريس التبادلي أربع خطوات: التنبؤ والتساؤل والتوضيح والتلخيص، وليس فيه تنظيم ولا بحث ولا مقارنة كما في السؤال.","الخطوات الست":"اسم الخطوات الست يدل على ست خطوات، والاستراتيجية في السؤال خمس خطوات تبدأ بالتنبؤ وتنتهي بالمقارنة.","KWL":"KWL جدول من ثلاثة أعمدة: ماذا أعرف وماذا أريد أن أعرف وماذا تعلمت، لا خمس خطوات تبدأ بالتنبؤ."}},"fsnv8x":{"w":{"ثورياً، وتطورياً":"الترتيب مقلوب: التعديل البسيط بإضافة معلومة تغير تطوري، والاستبدال الكامل للمفهوم تغير ثوري.","استقبالياً، واكتشافياً":"الاستقبالي والاكتشافي نوعان من التعلم عند أوزوبل بحسب طريقة تقديم المعرفة، لا نوعان لتغيير المفهوم الخاطئ.","أفقياً، ورأسياً":"الأفقي والرأسي نوعان من انتقال أثر التعلم، لا وصفان لتعديل المفهوم الخاطئ أو استبداله."},"e":"التغير التطوري لتعديل بسيط، والثوري لاستبدال المفهوم كله."},"7vesb6":{"w":{"متزامن":"المتزامن يجمع المعلم والطلاب في الوقت نفسه ولو اختلفت أماكنهم، وهنا يشاهد الطلاب التسجيل في الأوقات التي تناسبهم.","مباشر":"التعليم المباشر عن بعد يعني البث الحي في الوقت نفسه، والطلاب هنا يشاهدون شرحاً مسجلاً متى شاؤوا.","تنافسي":"التنافسي وصف لطريقة تفاعل الطلاب بالمسابقة والفوز، لا لنمط تقديم التعليم من حيث توقيت المشاهدة والتواصل."},"e":"يشاهد الطلاب الشرح ويرسلون أسئلتهم في أوقات مختلفة، واختلاف الوقت هو ما يجعل التعليم غير متزامن."},"812kx":{"w":{"مدمج":"المدمج يوزع التعلم نفسه بين الحضوري والإلكتروني، والمنصة هنا ترفع الواجبات والمصادر فقط دون تغيير بنية الحصة.","كامل عن بعد":"الكامل عن بعد يستبدل الحضور كله بالتعليم الإلكتروني، والمعلم هنا يبقي الحصة الحضورية ويستخدم المنصة داعماً لها.","مقلوب":"الصف المقلوب ينقل الشرح إلى المنزل والتطبيق إلى الفصل، وهنا يبقى التدريس في الحصة والمنصة للواجبات والمصادر فقط."},"e":"المساند يدعم الصفي دون تغيير بنيته."},"zuopw4":{"w":{"الوسائل التعليمية":"الوسائل التعليمية أدوات ومواد يستعين بها المعلم، والمصطلح المطلوب أوسع يشمل المعلم نفسه والمكتبة والمتحف وغيرها.","التقويم البديل":"التقويم البديل أساليب لقياس تعلم الطالب كالملفات والمشروعات، لا موارد يتفاعل معها لاكتساب الخبرة.","المنهج الرسمي":"المنهج الرسمي وثيقة معتمدة تحدد ما يُدرَّس، أما المكتبة والمعمل والمتحف فموارد يتعلم منها الطالب."},"e":"مصادر التعلم تشمل الموارد البشرية وغير البشرية التي يتفاعل معها المتعلم."},"12nlkf1":{"w":{"التقويم البديل، ونموذج تايلر":"نموذج تايلر لبناء المنهج يبدأ بالأهداف ثم الخبرات وتنظيمها وتقويمها، ولا يمر بالتحليل والتصميم والتطوير والتنفيذ.","التعلم النشط، ونموذج 5E":"نموذج 5E دورة تعلم للدرس: انشغال واستكشاف وتفسير وتوسع وتقويم، لا مدخل لتخطيط التعليم يبدأ بالتحليل.","دمج التقنية، ونموذج SAMR":"نموذج SAMR يقيس عمق أثر التقنية في المهمة بأربعة مستويات تبدأ بالاستبدال، لا مراحل لتخطيط التعليم وتطويره."},"e":"نموذج ADDIE أشهر نماذج التصميم التعليمي."},"2chwzp":{"w":{"المدونة":"المدونة صفحة ينشر فيها صاحبها ويعلّق الزوار، ولا يحرر محتواها عدة مستخدمين معاً كما في السؤال.","البودكاست":"البودكاست محتوى صوتي مسجل يُستمع إليه، لا صفحة يحررها عدة مستخدمين ويضيفون إليها.","الفيديو التفاعلي":"الفيديو التفاعلي مقطع مرئي يتحكم فيه المشاهد أو يجيب فيه عن أسئلة، لا صفحة يضيف إليها المستخدمون محتوى تشاركياً."},"e":"الويكي تحرير جماعي."},"1sehdgy":{"w":{"الفيديو التفاعلي":"الفيديو التفاعلي مقطع مرئي يتفاعل معه المشاهد، والمعلم هنا سجل ملفات صوتية فقط يُستمع إليها.","الواقع المعزز":"الواقع المعزز يضيف عناصر رقمية إلى المشهد الحقيقي عبر الكاميرا، لا ملفات صوتية مسجلة للاستماع.","الرحلة المعرفية":"الرحلة المعرفية بحث موجه في مصادر على الإنترنت أعدها المعلم، لا تسجيلات صوتية يستمع إليها الطلاب."},"e":"البودكاست محتوى صوتي مسجل."},"hk488d":{"w":{"أكسس":"أكسس لإنشاء قواعد البيانات وإدارة السجلات، أما الجداول الحسابية والرسوم البيانية فمكانها إكسل.","باوربوينت":"باوربوينت لإعداد العروض التقديمية بالشرائح، لا لتنظيم الدرجات في جداول وحسابها ورسم مخططاتها.","وورد":"وورد لكتابة النصوص وتنسيقها، والأنسب لتنظيم الدرجات وحسابها ورسم مخططها برنامج الجداول الحسابية."},"e":"إكسل جداول وحسابات ورسوم بيانية."},"1geq7fd":{"w":{"أكسس، وإكسل":"أكسس وإكسل برنامجان لتنظيم البيانات وحسابها، لا لتصميم ملصق جذاب أو رسم خريطة معرفية.","زوم، وتيمز":"زوم وتيمز لعقد الاجتماعات والفصول الافتراضية، ولا يُصمم بهما ملصق ولا تُبنى خريطة معرفية.","SPSS، وكاهوت":"برنامج SPSS للتحليل الإحصائي وكاهوت للمسابقات التفاعلية، فلا يصلح أي منهما لتصميم ملصق أو خريطة معرفية."},"e":"كانفا للتصميم المرئي، وبوبلت للخرائط المعرفية."},"jqgc80":{"w":{"عرضها مباشرة لأن الأداة دقيقة دائماً":"أدوات الذكاء الاصطناعي قد تخطئ في المعلومة أو الصياغة، فعرض أسئلتها دون مراجعة ينقل أخطاءها إلى الطلاب.","رفض استخدام الأداة نهائياً":"الأداة مساعدة نافعة إذا راجع المعلم ناتجها، فرفضها كلياً يضيع فائدتها بدل ضبط استخدامها بالتحقق.","تركها للطلاب ليحكموا على صحتها":"التحقق من دقة الأسئلة ومواءمتها للأهداف مسؤولية المعلم قبل العرض، ولا يُنقل هذا الحكم إلى الطلاب."}},"puuowx":{"w":{"أهداف ومحتوى فقط":"الأهداف والمحتوى جزء من مدخلات المنهج، ونظرة النظم تضيف إليها العمليات والمخرجات والتغذية الراجعة.","كتاب مدرسي ومعلم":"الكتاب والمعلم من مدخلات النظام فقط، ونظرة النظم تشمل معها العمليات والمخرجات والتغذية الراجعة.","اختبارات ودرجات":"الاختبارات والدرجات أدوات تقويم تقدم التغذية الراجعة، وهي جزء واحد من النظام لا النظام كله."}},"1nfec84":{"w":{"حديث، وتقليدي":"الترتيب مقلوب: حصر المنهج في الكتاب والحفظ هو المفهوم التقليدي، وشموله جميع الخبرات هو المفهوم الحديث.","خفي، ورسمي":"الخفي ما يُتعلم ضمناً دون تخطيط والرسمي الوثيقة المعتمدة، وهما نوعان للمنهج لا مفهومان قديم وحديث له.","فارغ، وحلزوني":"الفارغ ما لا يُدرَّس والحلزوني تنظيم يعيد المفاهيم بعمق متزايد، ولا يصف أي منهما رؤية المعلمين لمعنى المنهج."},"e":"المنهج التقليدي يساوي المقرر والحفظ، والحديث يشمل كل الخبرات ويراعي المتعلم."},"i0pvox":{"w":{"منطقي":"التنظيم المنطقي يرتب المحتوى وفق بنية المادة من البسيط إلى المعقد، والسؤال يستبعده صراحة ويقدم حاجات المتعلمين وميولهم.","حلزوني":"التنظيم الحلزوني (برونر) يعيد المفاهيم نفسها عبر الصفوف بعمق متزايد، والمعيار هنا خصائص المتعلمين وميولهم.","محوري":"المحوري تنظيم للمنهج كله حول محور مشترك ومعه مواد اختيارية، والسؤال عن ترتيب موضوعات وحدة واحدة مقابل الترتيب المنطقي."},"e":"التنظيم السيكولوجي يبدأ من المتعلم."},"xujurt":{"w":{"المحوري":"المنهج المحوري يدور حول محور مشترك من حاجات الطلاب ومشكلاتهم ومعه مواد اختيارية، لا على التقنية والخطو الذاتي.","الحلزوني":"المنهج الحلزوني (برونر) يعيد المفاهيم عبر الصفوف بعمق متزايد، ولا يقوم على توظيف التقنية والخطو الذاتي.","الخفي":"المنهج الخفي ما يتعلمه الطالب ضمناً دون تخطيط، والسؤال يصف تنظيماً مخططاً يوظف التقنية."},"e":"المنهج التكنولوجي قائم على التقنية والخطو الذاتي."},"11emr20":{"w":{"التجميع الثابت حسب الذكاء":"التجميع الثابت يبقي الطالب في مجموعة واحدة بحسب تصنيفه، والطالب هنا ينتقل بين مجموعات مختلفة بحسب المهمة واستعداده.","جيكسو":"جيكسو تقسم الموضوع أجزاء يتخصص كل عضو بجزء منها، أما تغيير المجموعة بحسب استعداد الطالب للمهمة فهو المجموعات المرنة.","الرؤوس المرقمة":"الرؤوس المرقمة ترقيم أعضاء مجموعة ثابتة واستدعاء رقم عشوائي للإجابة، ولا انتقال فيها بين المجموعات."}},"y6a10q":{"w":{"إعادة شرح الدرس كاملاً للجميع":"إعادة الشرح كاملاً تعيد الصف التقليدي وتضيع وقت الحصة على من شاهد الفيديو، والأنسب معالجة سريعة لمن لم يشاهد.","منع من لم يشاهد من المشاركة في الأنشطة":"المنع عقاب لا يعالج المشكلة، فيبقى ثلث الطلاب بلا فهم ولا تطبيق بدل تمكينهم من المشاهدة السريعة.","إلغاء الصف المقلوب نهائياً":"إلغاء الاستراتيجية حل متسرع لمشكلة تُعالج بآلية تحقق وزاوية مشاهدة، وثلثا الطلاب شاهدوا الفيديو فعلاً."},"e":"الاستراتيجية تتطلب آلية تحقق ومعالجة سريعة دون إضاعة وقت الحصة."},"m6u5gy":{"w":{"التعلم القائم على المشكلات":"القائم على المشكلات ينطلق من مشكلة مفتوحة يبحث الطلاب عن حلولها، والموقف عمل ممتد انتهى بمنتج عُرض هو الفيلم.","الاستقصاء العادل بالتجريب":"الاستقصاء العادل مناظرة في قضية خلافية بين فريق مؤيد وآخر معارض يحكم بينهما محكّمون، لا عمل ممتد لأسابيع ينتهي بفيلم يُعرض.","الكرسي الساخن في الحوار":"الكرسي الساخن حوار يجيب فيه طالب عن أسئلة زملائه داخل الحصة، لا عمل ممتد لأسابيع ينتهي بإنتاج فيلم."},"e":"العمل الممتد الذي ينتهي بمنتج يُعرض هو التعلم القائم على المشروعات."},"q32yvd":{"w":{"التفسير":"التفسير يقدم فيه المعلم المفهوم ويشرحه بعد الاستكشاف، والطلاب هنا يجربون قبل أي شرح.","التوسع":"التوسع تطبيق المفهوم في موقف جديد بعد فهمه، والطلاب هنا ما زالوا يجربون المغناطيسات قبل تقديم المفهوم.","التقويم":"التقويم المرحلة الأخيرة للتحقق من الفهم، أما تجريب المواد وتسجيل الملاحظات قبل الشرح فهو الاستكشاف."},"e":"الاستكشاف مرحلة يعالج فيها الطلاب المواد بأنفسهم قبل الشرح."},"uuc6ku":{"w":{"الخريطة الذهنية (فروع من مركز)":"الخريطة الذهنية تتفرع شعاعياً حول فكرة مركزية واحدة، ولا تُظهر الشبه والاختلاف بين شيئين كما يطلب المعلم.","الخط الزمني (أحداث مرتبة)":"الخط الزمني يرتب الأحداث بحسب وقوعها، والمطلوب هنا مقارنة خليتين لا تسلسل أحداث في الزمن.","الخريطة الجغرافية (مواقع)":"الخريطة الجغرافية تبين المواقع والأماكن، ولا علاقة لها بمقارنة خصائص الخلية النباتية والحيوانية."},"e":"أشكال فن مصممة للمقارنة: الشبه في التقاطع والاختلاف في الجانبين."},"xcc0an":{"w":{"التغذية الراجعة المؤجلة":"التغذية الراجعة المؤجلة تأتي بعد مدة من الإجابة، والمعلم هنا تفاعل فوراً بأسئلة متدرجة قادت الطالب إلى الصواب.","العقاب السالب":"العقاب السالب سحب مثير محبب لإضعاف سلوك، ولا علاقة له بأسئلة متدرجة تقود الطالب إلى الإجابة الصحيحة.","إعادة الصياغة":"إعادة الصياغة طرح السؤال نفسه بكلمات أوضح، وقد تُستعمل بعد صمت الطالب أو خطئه، أما هنا فطرح المعلم سلسلة أسئلة جديدة متدرجة تبني على إجابته حتى وصل إلى الصواب، وهذا هو السبر المشجع."},"e":"السبر المشجع سلسلة أسئلة متدرجة بعد إجابة خاطئة أو ناقصة تقود الطالب إلى الصواب بنفسه. والفرق عن إعادة الصياغة: إعادة الصياغة سؤال واحد يُعاد بكلمات أوضح، والسبر أسئلة متتابعة جديدة تبني على إجابة الطالب. والتغذية المؤجلة تأتي بعد مدة."},"1epa20b":{"w":{"طرح أسئلة أسهل فقط":"المشكلة الموصوفة قصر زمن الانتظار لا صعوبة الأسئلة، فتسهيلها لا يمنح الطلاب وقتاً للتفكير قبل أن يجيب المعلم بنفسه.","الاكتفاء بسؤال المتفوقين":"سؤال المتفوقين وحدهم يقلل مشاركة بقية الطلاب، ولا يعالج المشكلة الموصوفة وهي إجابة المعلم بعد ثانية واحدة فقط.","إلغاء الأسئلة الشفهية":"إلغاء الأسئلة الشفهية يفقد المعلم أداة مهمة للتفكير والمشاركة، والمطلوب تعديل طريقة طرحها بإطالة زمن الانتظار."},"e":"قِصر زمن الانتظار يمنع الطلاب من التفكير فيجيب المعلم بنفسه."},"16uo8pu":{"w":{"السبر التبريري":"السبر التبريري يطلب من المجيب نفسه تعليل إجابته بسؤال «لماذا»، والمعلم هنا حوّل السؤال إلى طالب آخر.","إعادة الصياغة":"إعادة الصياغة تغيير صيغة السؤال حين لا يجيب أحد، أما هنا فقد أجاب الطالب ووجّه المعلم إجابته إلى زميل آخر.","التلقين":"التلقين يقدم فيه المعلم المعلومة أو التلميح للطالب نفسه، أما هنا فقد طلب من طالب آخر أن يعلّق على الإجابة ويضيف إليها."},"e":"إعادة التوجيه تحويل السؤال إلى طالب آخر للبناء على الإجابة."},"1qgy5hs":{"w":{"التعلم المتنقل":"التعلم المتنقل يصف التعلم عبر الأجهزة المحمولة، أما تخزين الملفات على خوادم عبر الإنترنت ومشاركتها فهو خدمة سحابية.","الواقع المعزز":"الواقع المعزز يدمج عناصر رقمية بالمشهد الحقيقي أمام المستخدم، ولا علاقة له بتخزين الملفات على خوادم عبر الإنترنت.","التعليم المبرمج":"التعليم المبرمج أسلوب لعرض المادة في خطوات صغيرة بتعزيز فوري، وليس خدمة لتخزين الملفات ومشاركتها عبر الإنترنت."},"e":"الحوسبة السحابية تقدم التخزين والتطبيقات كخدمة عبر الإنترنت (قوقل درايف، ون درايف)."},"tmjcqc":{"w":{"التكرار الزائد":"مبدأ التكرار الزائد يخص عرض النص المكتوب مع التعليق الصوتي نفسه، والمشكلة هنا فصل النص عن الرسم في شريحتين.","الشخصنة الحوارية":"مبدأ الشخصنة يفضّل أسلوب الحديث الودي بدل الرسمي، ولا علاقة له بمكان النص من الرسم في الشرائح.","التجزئة إلى مقاطع":"مبدأ التجزئة يقسم العرض إلى أجزاء يتحكم المتعلم في تقدمها، والمشكلة هنا بُعد النص عن الرسم الذي يشرحه."},"e":"مبدأ التقارب المكاني يقضي بوضع النص قرب الصورة التي يشرحها."},"xivld0":{"w":{"التعزيز":"التعزيز بديل تقني يضيف تحسيناً وظيفياً للمهمة، والمعلم هنا نقل النص نفسه إلى العرض دون أي إضافة.","التعديل":"التعديل يعيد تصميم جزء كبير من المهمة بالتقنية، والمعلم هنا لم يغير المهمة بل نقل نص السبورة كما هو.","إعادة التعريف":"إعادة التعريف تخلق مهمة جديدة مستحيلة دون تقنية، وعرض نص السبورة نفسه كان ممكناً دونها."},"e":"الاستبدال استخدام التقنية بديلاً مباشراً بلا تغيير وظيفي."},"16vz03w":{"w":{"الاستبدال المباشر":"الاستبدال يستخدم التقنية بديلاً لأداة قديمة دون تغيير المهمة، والمهمة هنا جديدة ما كانت ممكنة دون تقنية.","التعزيز الوظيفي":"التعزيز يضيف تحسيناً وظيفياً لمهمة ممكنة أصلاً، أما البحث المشترك مع طلاب دولة أخرى فمهمة مستحيلة دون التقنية.","التعديل الجوهري":"التعديل يعيد تصميم المهمة بالتقنية دون أن تكون مستحيلة قبلها، والسؤال يصرح بأن المهمة ما كانت ممكنة دونها."},"e":"إعادة التعريف أعلى مستويات SAMR: مهمة جديدة كلياً غير ممكنة بلا تقنية."},"3yy9yx":{"w":{"مهارة الكتابة على لوحة المفاتيح":"الكتابة على لوحة المفاتيح مهارة تشغيل تقنية، والمشكلة هنا سلوكية تتعلق بالخصوصية واحترام الزميل في الفضاء الرقمي.","التعلم المتنقل":"التعلم المتنقل نمط تعلم عبر الأجهزة المحمولة، ولا يعالج سلوك نشر صورة الزميل دون إذنه.","الحوسبة السحابية":"الحوسبة السحابية خدمة لتخزين الملفات ومشاركتها، ولا تعالج احترام خصوصية الآخرين الذي أخل به الطالب."},"e":"الموقف يتعلق بالخصوصية والاحترام في الفضاء الرقمي، وهو جوهر المواطنة الرقمية."},"1oduotx":{"w":{"منهج المواد المنفصلة":"منهج المواد المنفصلة تنظيم تقليدي يقدم كل مادة مستقلة وفق بنيتها، ولا ينطلق من ميول الطلاب وحل مشكلاتهم كما عند ديوي.","المنهج المحوري":"المنهج المحوري يجمع الطلاب حول محور مشترك تصاحبه مواد اختيارية، أما المنهج القائم على الميول المرتبط بديوي فهو منهج النشاط.","منهج المجالات الواسعة":"منهج المجالات الواسعة يدمج المواد المتقاربة في مجال واحد كالعلوم العامة، فأساسه تنظيم المواد لا ميول الطلاب."},"e":"منهج النشاط لديوي ينطلق من ميول الطلاب ومشكلاتهم."},"1b9yhof":{"w":{"منهج الوحدات":"منهج الوحدات ينظم التعلم حول موضوعات أو مشكلات في وحدات متكاملة، ولا يقوم على إعادة المفهوم نفسه بعمق متزايد عبر الصفوف.","المنهج المحوري":"المنهج المحوري يدور حول محور مشترك من حاجات الطلاب ومشكلاتهم، لا حول عودة مفهوم واحد بعمق أكبر في صفوف متتالية.","منهج النشاط":"منهج النشاط ينطلق من ميول الطلاب وحل المشكلات عند ديوي، ولا يصف عودة مفهوم الطاقة بتجريد أعلى في كل مرحلة."},"e":"المنهج الحلزوني (برونر) يعيد المفاهيم الأساسية بتعمق متزايد عبر الصفوف."},"7a9q5r":{"w":{"المواد المندمجة":"الاندماج يصهر المادتين في مادة واحدة كالاجتماعيات، والسؤال يصرح ببقاء كل مادة مستقلة بحصصها.","المواد المنفصلة":"المواد المنفصلة تُدرَّس كل منها دون تنسيق مع غيرها، والمعلمان هنا نسقا لتدريس الموضوع في الأسبوع نفسه.","المنهج المحوري":"المنهج المحوري يقوم على محور مشترك من حاجات الطلاب ومشكلاتهم مع مواد اختيارية، لا على تنسيق موضوع بين مادتين منفصلتين."},"e":"الترابط تنسيق بين مادتين مع بقائهما منفصلتين."},"1v5gk1i":{"w":{"تايلر":"نموذج تايلر يبدأ بالأهداف من الأعلى ثم الخبرات وتنظيمها وتقويمها، لا بتشخيص المعلم لحاجات طلابه استقرائياً.","برونر":"برونر صاحب المنهج الحلزوني الذي يعيد المفاهيم بعمق متزايد، وليس صاحب نموذج يبدأ بتشخيص حاجات الطلاب.","بوسنر":"بوسنر صاحب نموذج التغير المفاهيمي لمعالجة التصورات البديلة، لا نموذج لبناء المنهج يبدأ بتشخيص الحاجات."},"e":"هيلدا تابا ترى أن المنهج يُبنى من الأسفل بيد المعلم بدءاً بتشخيص الحاجات."},"1cmbgzw":{"w":{"الهوية الوطنية":"الهوية الوطنية تُعزز بربط المحتوى بالانتماء والتراث والمناسبات الوطنية، والنشاط هنا يدرب على إدارة الميزانية والادخار.","الثقافة الرقمية":"الثقافة الرقمية الاستخدام الآمن والأخلاقي للتقنية وتقويم المصادر، ولا يتضمن حساب ميزانية الأسرة شيئاً منها.","مهارات اللغة":"مهارات اللغة ترتبط بالقراءة والكتابة والتواصل، والنشاط هنا حسابي يدرب على إدارة المال في الحياة اليومية."},"e":"إدارة الميزانية والادخار من المهارات الحياتية التي تُنمى عبر المواد."},"4i3kbk":{"w":{"الثقافة الرقمية":"الثقافة الرقمية تخص الاستخدام الآمن والأخلاقي للتقنية، والنشاط لا يقوم على التقنية بل يربط الدرس بتراث المملكة ويومها الوطني.","المهارات الحياتية":"المهارات الحياتية كإدارة المال وحل المشكلات اليومية، والنشاط هنا يربط المحتوى بتراث الوطن ومناسباته.","التفكير الرياضي":"التفكير الرياضي يقوم على الأعداد والاستدلال الكمي، ولا صلة له بوصف الاحتفالات الوطنية باللغة الإنجليزية."},"e":"ربط المحتوى بتراث الوطن ومناسباته يعزز الهوية الوطنية عبر مادة غير مخصصة لها."},"n0j6qf":{"w":{"النمط التسلطي في الإدارة":"النمط التسلطي يقوم على فرض المعلم القواعد ومراقبتها بنفسه، وهنا أشرك طلابه في وضعها ومراقبتها فقلّ تدخله.","النمط الفوضوي في الضبط":"النمط الفوضوي تضيع فيه الضوابط ويُترك الطلاب بلا قواعد، والمعلم هنا وضع قواعد مع طلابه وهم يراقبون التزامهم بها.","العقاب الجماعي للصف":"العقاب الجماعي معاقبة الصف كله بخطأ بعضهم وهو ممنوع، والموقف هنا لا عقاب فيه بل مشاركة الطلاب في وضع القواعد ومراقبتها."},"e":"الإدارة الذاتية تنقل الضبط من المعلم إلى الطلاب (انضباط ذاتي)."},"n4yn4d":{"w":{"الإشباع":"الإشباع تقديم المثير أو المعزز بكثرة حتى يُمل منه، والمعلم هنا لم يُكثر من شيء بل أحلّ الضغط على الكرة محل العض.","التلقين":"التلقين تلميح لفظي أو جسدي يساعد الطالب على أداء الاستجابة الصحيحة، والمعلم هنا درّبه على استجابة بديلة لا تجتمع مع العض.","ضبط المثير":"ضبط المثير تعديل البيئة أو المثيرات التي تسبق السلوك، والمعلم هنا لم يغيّر البيئة بل درّب الطالب على استجابة بديلة للتوتر."},"e":"الكف المتبادل إحلال استجابة مقبولة لا تجتمع مع غير المرغوبة."},"1n8f5wv":{"w":{"الغمر":"الغمر علاج للخوف بتعريض الشخص فجأة وبقوة لمثير خوفه، والطالب هنا لا يعاني خوفاً بل لا يقدّر الممتلكات العامة.","تكلفة الاستجابة":"تكلفة الاستجابة عقاب سالب بسحب نقاط أو امتياز، والمعلم هنا لم يسحب شيئاً بل استعان بقصص واقعية وأنشطة خدمية.","السحب التدريجي":"السحب التدريجي تقليل المساعدة شيئاً فشيئاً حتى يؤدي الطالب السلوك وحده، والمعلم هنا يواجه الطالب بواقع سلوكه وأثره في مجتمعه."},"e":"الإرشاد بالواقع (جلاسر) يواجه الطالب بواقع سلوكه وأثره على الآخرين ويحمّله مسؤولية اختياره ويضع معه خطة لسلوك أفضل، والقصص الواقعية والأنشطة الخدمية هنا وسائل لذلك."},"iuj8zf":{"w":{"علاجي، وتعزيزي":"الترتيب هنا معكوس، فالعلاجي لغير المتقنين والتعزيزي لمن أتقن، والسؤال يذكر المتقنين أولاً ثم غير المتقنين.","إثرائي، وتعزيزي":"التدريبات الأساسية لغير المتقنين نشاط علاجي لا تعزيزي، والنشاط الإضافي هنا غرضه تثبيت الهدف نفسه لا تجاوز المنهج كالإثرائي.","صفي، ولاصفي":"صفي ولاصفي تصنيف بحسب مكان تنفيذ النشاط، والسؤال يصنّف النشاطين بغرضهما: تثبيت تعلم من أتقن، وعلاج من لم يتقن."},"e":"النشاط التعزيزي لمن أتقن لتثبيت التعلم، والعلاجي لمن لم يتقن."},"1rn2vqq":{"w":{"لفظي كتابي":"الاتصال اللفظي الكتابي ينقل الرسالة بكلمات مكتوبة، والمعلم هنا لم يكتب شيئاً بل أوصل رسالته بالاقتراب والنظر المباشر.","لفظي شفهي":"الاتصال اللفظي الشفهي ينقل الرسالة بكلمات منطوقة، والسؤال ينص على أن المعلم نبّه الطالب دون أن يتكلم.","أحادي الاتجاه":"أحادي الاتجاه تصنيف للاتصال بحسب اتجاه الرسالة وتفاعل المستقبل، أما ما يميز هذا الموقف فإيصال الرسالة بالاقتراب والنظر دون كلام."},"e":"الاقتراب من الطالب (المسافة)، والنظر المباشر (لغة العينين)، ونبرة الصوت (اللغة الموازية) كلها اتصال غير لفظي؛ فالنبرة تُحسب غير لفظية ولو صاحبت الكلام، لأنها تنقل المعنى بطريقة النطق لا بالكلمات. والمعلم لم يوجّه للطالب كلمة، فانتبه بالإشارات وحدها. أما اللفظي فكلمات منطوقة أو مكتوبة."},"19gfani":{"w":{"اللغة الموازية":"اللغة الموازية ما يصاحب الكلام من نبرة الصوت وسرعته وارتفاعه، والسؤال يتحدث عن المسافة والقرب المكاني من الطالب.","لغة الجسد":"لغة الجسد تعبيرات الوجه والإيماءات وحركات اليدين، أما استخدام المسافة والقرب المكاني فله اسم خاص هو اللغة التقاربية.","الاتصال اللفظي":"الاتصال اللفظي ينقل الرسالة بكلمات منطوقة أو مكتوبة، والسؤال نفسه يحصر الإجابة في أنواع الاتصال غير اللفظي."},"e":"التقاربية تخص المسافة المكانية."},"1mxkadz":{"w":{"نجمتان وأمنية":"نجمتان وأمنية تعليق يذكر نقطتي قوة ونقطة تحسين، والمعلم هنا لم يكتب تعليقاً بل لوّن الأوراق بلونين.","الكرسي الساخن":"الكرسي الساخن استراتيجية يجلس فيها طالب أمام زملائه ويجيب عن أسئلتهم، ولا صلة لها بتلوين أوراق التقويم.","بطاقة الخروج من الحصة":"بطاقة الخروج أداة تقويم تكويني يكتب فيها الطالب إجابة قصيرة قبل مغادرة الحصة، والمعلم هنا يعيد أوراقاً ملوّنة بلونين."},"e":"التخطيط باللونين تغذية راجعة بصرية بلونين."},"1ahuqc5":{"w":{"التوقعات المنخفضة تحمي الطلاب من الإحباط فترفع تحصيلهم":"التوقع المنخفض يخفض التحصيل بالطريقة نفسها التي يرفعه بها التوقع العالي، والوقاية من الإحباط تكون بتحدٍّ قابل للتحقيق مع دعم لا بخفض التوقع.","التوقعات العالية ترفع تحصيل المتفوقين وتخفض تحصيل الضعاف":"أثر بجماليون يشمل جميع الطلاب، والتوقع العالي المقرون بالدعم يرفع تحصيل الضعاف أيضاً، أما خفض التوقع منهم فهو الذي يخفض تحصيلهم.","العلاقة بين التوقعات والتحصيل ضعيفة لا تُذكر":"دراسة روزنثال وجاكوبسون بيّنت أن توقعات المعلم تتحول إلى نبوءة تحقق ذاتها، فهي تؤثر في التحصيل ولا يصح إنكار أثرها."},"e":"مفهوم التوقعات العالية يقوم على أثر بجماليون (روزنثال وجاكوبسون 1968): ما يتوقعه المعلم من طلابه ينعكس في تعامله معهم، فيرتفع تحصيلهم كلما ارتفعت توقعاته، أي علاقة طردية، وتصير التوقعات نبوءة تحقق ذاتها."},"gy4jsu":{"w":{"الاكتفاء بإخبار الطالب بأنه مخطئ":"إخبار الطالب بخطئه دون خطوة تالية يغلق الموقف، أما التوقع العالي فيبقيه فيه بإعادة صياغة السؤال حتى يصل إلى الإجابة.","تقديم الإجابة النموذجية عن السؤال":"تقديم الإجابة الجاهزة يحرم الطالب من الوصول إليها بنفسه، والتوقع العالي يعني منحه فرصة أخرى بسؤال معاد الصياغة.","طلب الإجابة الصحيحة من طالب آخر":"نقل السؤال إلى طالب آخر يوحي بأن المعلم تخلى عن الأول، والتوقع العالي يبقيه في الموقف ليصل إلى الإجابة بنفسه."},"e":"إعادة الصياغة تبقي الطالب في الموقف وتؤكد أنه قادر على الوصول للإجابة."},"cduqhj":{"w":{"إعفاؤها من المهام الصعبة مراعاة لحالتها":"إعفاؤها من المهام الصعبة خفض للمطلوب يثبّت اعتقادها بالعجز، أما رفع ثقتها فيكون بمهمة قصيرة تنجح فيها ثم تعزيز جهدها.","مقارنتها بزميلتها المتفوقة لتحفيزها":"مقارنة الطالبة بزميلتها المتفوقة تزيد شعورها بالفشل، والمقارنة الصحيحة بأدائها السابق بعد خبرة نجاح صغيرة.","إبلاغ ولي الأمر بضعف ثقتها بنفسها":"إبلاغ ولي الأمر خطوة لاحقة إن استمرت المشكلة، والخطوة الأولى تتولاها المعلمة في الصف بخبرة نجاح تكسر توقعها للفشل."},"e":"كسر دائرة الفشل يبدأ بخبرة إتقان صغيرة (أقوى مصدر للكفاءة الذاتية) مع تعزيز الجهد."},"wznw4x":{"w":{"زيادة الدافعية الداخلية":"الجائزة المادية عن كل إجابة تجعل الطالب يتعلم من أجلها لا من أجل المعرفة، فتضعف الدافعية الداخلية ولا تزيدها.","ارتفاع تقدير الطلاب لذواتهم":"تقدير الذات يُبنى بخبرات نجاح حقيقية وإبراز جوانب القوة، أما الجائزة عن كل إجابة بسيطة فتربط الجهد بالمكافأة الخارجية.","تعلم أعمق وأكثر استمراراً":"التعلم من أجل الجائزة يضعف غالباً بتوقفها، والتعلم الأعمق والأبقى يرتبط بالدافعية الداخلية التي يضعفها هذا الإفراط."}},"1mduce3":{"w":{"«ضعيف، راجعي الدرس»":"حكم عام سلبي لا يحدد للطالبة ما أصابت فيه ولا ما تحتاج تحسينه، فلا هو وصفي ولا يعكس توقعاً عالياً.","«حاولي أكثر في المرة القادمة»":"تشجيع عام لا يحدد نقطة قوة ولا نقطة تحسين ولا كيفية التحسين، فلا يصلح تغذية راجعة وصفية.","«زميلتك كتبت أفضل منك، انظري إلى ورقتها»":"مقارنة بالأقران تُشعر الطالبة بالعجز، والتوقع العالي يقارنها بأدائها السابق ويحدد لها ما تحسّنه وكيف."},"e":"التعليق الصحيح يسمي نقطة القوة ونقطة التحسين وكيفيتها ويطلب محاولة أخرى."},"kz0j7r":{"w":{"لا يبدأ العمل إلا بوعد بمكافأة":"انتظار المكافأة قبل البدء بالعمل علامة دافعية خارجية، أما الداخلية فتظهر في العمل بجد دون مقابل.","يختار دائماً أسهل المهام المتاحة":"اختيار أسهل المهام علامة على تجنب التحدي، وصاحب الدافعية الداخلية يميل إلى المهام المتحدية ويثابر فيها.","يتوقف عن العمل عند غياب المعلم":"التوقف عند غياب المعلم يعني أن العمل مرتبط بالرقابة الخارجية، وصاحب الدافعية الداخلية يواصل العمل دون رقيب."},"e":"الدافعية الداخلية تظهر في المثابرة بلا مقابل خارجي واختيار المهام المتحدية."},"1crpj70":{"w":{"التنافس بين الطلاب":"التنافس يقوم على مقارنة الطالب بزملائه، والمعلم هنا يقارن تقدم كل طالب بأدائه السابق لا بغيره.","الدافعية الخارجية فقط":"الدافعية الخارجية تقوم على المكافآت والدرجات، والمعلم هنا يبني على أهداف يحددها الطالب لنفسه ومقارنة بأدائه السابق.","الضبط الصفي الصارم":"الضبط الصارم يتعلق بفرض النظام ومراقبة السلوك، والموقف هنا عن أهداف التعلم وقياس تقدم كل طالب بأدائه السابق."}},"kjp83a":{"w":{"استيعاب الطلاب للقواعد والأنظمة الصفية":"استيعاب الطلاب للقواعد جزء من الضبط الصفي، وإدارة الصف أشمل منه فهي تنظيم البيئة المادية والنفسية والاجتماعية ليحدث التعلم.","توظيف ما لدى المعلم من خبرات":"خبرات المعلم وسيلة يستعين بها في عمله، وليست تعريفاً لإدارة الصف التي هي تنظيم البيئة التعليمية ليحدث التعلم.","الاهتمام بحل المشكلات الطارئة بحزم":"حل المشكلات الطارئة بحزم جانب ضيق يركز على الضبط، أما إدارة الصف فتنظيم شامل للبيئة يسبق المشكلات ويهيئ للتعلم."},"e":"إدارة الصف تنظيم شامل للبيئة المادية والنفسية والاجتماعية."},"1pbvp4j":{"w":{"كثيرة لتغطي كل المواقف المحتملة":"القواعد الفعالة قليلة من 3 إلى 5 قواعد واضحة يسهل حفظها وتطبيقها، وكثرتها تشتت الطالب فلا يلتزم بها.","تُصاغ بالنهي لتكون حازمة":"صياغة النهي تذكر الممنوع فقط، والقاعدة الجيدة إيجابية الصياغة تصف السلوك المطلوب ليعرف الطالب ما يفعله لا ما يتجنبه.","يضعها المعلم وحده ويعلنها في منتصف الفصل الدراسي":"القواعد توضع مع الطلاب في بداية العام لأن مشاركتهم تولّد الالتزام، وانفراد المعلم بها وتأخير إعلانها يضعفان ذلك الالتزام."}},"1wczat7":{"w":{"إلغاء العمل في مجموعات حفاظاً على الوقت":"الإلغاء يضحّي باستراتيجية العمل التعاوني نفسها، والمشكلة هنا في طريقة الانتقال إلى المجموعات لا في المجموعات، فتُعالج بروتين مدرَّب.","معاقبة من يتأخر في الانتقال":"العقاب يعالج العرض، وسبب ضياع الوقت هنا غياب إجراء ثابت يعرف به الطلاب أدوارهم وأماكنهم قبل الانتقال.","تمديد الحصة لتعويض الوقت الضائع":"تمديد الحصة لا يعالج سبب الهدر، فالانتقال غير المنظم يبقى كما هو ويتكرر في كل حصة، والحل تنظيم الانتقال نفسه."},"e":"الانتقالات السلسة من مهارات إدارة الوقت الأكاديمي وتُبنى بإجراءات روتينية مدرَّبة."},"6ohckn":{"w":{"صفوف متوازية تواجه السبورة مباشرة":"الصفوف المتوازية تناسب العرض والشرح، وفيها يرى الطالب ظهور زملائه، والنقاش المفتوح يحتاج أن يرى الجميع بعضهم.","مجموعات صغيرة متباعدة منعزلة":"المجموعات الصغيرة تناسب التعاون داخل كل مجموعة، وتباعدها يقطع تبادل الآراء بين طلاب الصف كله الذي يتطلبه النقاش المفتوح.","مقاعد فردية متجهة إلى جدران الصف":"توجيه المقاعد إلى الجدران يمنع التواصل البصري بين الطلاب ومع المعلم، فلا يصلح لنقاش يتبادلون فيه الآراء."}},"7i0ipz":{"w":{"يوقف الحصة ويحقق معهما أمام الجميع":"التحقيق أمام الصف يصعّد الشجار ويحرج الطالبين، والمعالجة مع المتسببين تكون فردية بعد تهدئة الموقف لا أمام زملائهم.","يستدعي مدير المدرسة فوراً":"إبلاغ الإدارة خطوة لاحقة، واستدعاء المدير قبل الفصل بين الطالبين يترك الخطر قائماً حتى يصل، فالأولوية لاحتواء الموقف.","يعاقب الطالبين معاً دون سؤال":"العقاب قبل سماع كل طرف ظلم قد يقع على المعتدى عليه، والمعلم يبدأ بالتهدئة والفصل ثم يستمع لكل طالب على انفراد."},"e":"في الأزمة يبدأ المعلم باحتواء الموقف: يحافظ على هدوئه، ويفصل المتشاجرين، ويشغل بقية الصف، ثم يستمع لكل طرف على انفراد ويرصد المشكلة ويسلمها لإدارة المدرسة، لأن الشجار من مشكلات الدرجة الثانية في الابتدائي والثالثة في المتوسط والثانوي."},"f96fj2":{"w":{"قراءة كتب عن التعامل مع الأسر والمجتمع":"التعامل مع الأسر والمجتمع موضوع بعيد عن إدارة الصف، والمعلم الجديد يحتاج نماذج حية لضبط الصف وتنظيمه.","مناقشة الصعوبات مع المدير وطلب تقويم متكرر":"مناقشة الصعوبات وطلب التقويم يأتيان بعد التطبيق حين تظهر الصعوبات، والسؤال عن خطوة يبدأ بها قبل أن يبني خطته.","التعاون مع المعلمين الجدد فقط ومناقشة صعوباتهم":"المعلمون الجدد يفتقرون إلى الخبرة نفسها التي يبحث عنها، وكلمة «فقط» تحرمه من خبرة المعلمين الفعالين في المدرسة."},"e":"الخبرة الصفية الحية للمعلمين الفعالين أقرب مصدر للمعلم الجديد."},"1jgng2d":{"w":{"تعزيز سالب":"التعزيز السالب إزالة منفّر بعد السلوك لزيادته، والمعلم هنا أضاف عبارة ثناء ولم يزل شيئاً.","عقاب سالب":"العقاب السالب سحب معزز لتقليل سلوك، والمعلم هنا أضاف ثناءً فازداد الالتزام بالواجب بدل أن يقل.","انطفاء":"الانطفاء حجب التعزيز عن السلوك حتى يتلاشى، والمعلم هنا قدّم الثناء بعد كل واجب فزاد السلوك ولم يتلاشَ."}},"ape2yw":{"w":{"عقاب موجب":"العقاب الموجب إضافة منفّر بعد السلوك كالتوبيخ، والمعلم هنا لم يضف شيئاً بل حجب فرصة الإجابة عن الطالب الصائح.","تكلفة استجابة":"تكلفة الاستجابة سحب معزز مكتسب كالدرجات، والطالب هنا لم يخسر شيئاً يملكه، بل لم ينل فرصة الإجابة التي يسعى إليها.","تشكيل":"التشكيل تعزيز تقريبات متتابعة لبناء سلوك جديد خطوة خطوة، والمعلم هنا حجب التعزيز عن الصياح وعزز رفع اليد بهدوء."},"e":"حجب التعزيز (فرصة الإجابة) عن الصياح هو الإطفاء، وإعطاء الفرصة للهادئ تعزيز تفاضلي للبديل."},"1mpulci":{"w":{"الاقتصاد الرمزي":"الاقتصاد الرمزي رموز كالنجوم تُجمع ثم تُستبدل بمعززات، والمعلم هنا لم يعط رموزاً بل ربط القراءة الحرة بإنهاء التمارين مباشرة.","تكلفة الاستجابة":"تكلفة الاستجابة خصم معزز مكتسب لتقليل سلوك، والمعلم هنا لا يخصم شيئاً بل يعد بنشاط محبب بعد إنجاز التمارين.","التحصين التدريجي":"التحصين التدريجي تعريض متدرج لمثير مخيف لإزالة الخوف، والموقف هنا لا خوف فيه بل نشاط محبب مشروط بإنهاء التمارين."},"e":"نشاط محبب (القراءة الحرة) اشتُرط بإنهاء نشاط أقل حباً (التمارين)، وهذا بريماك."},"cea9sa":{"w":{"مبدأ بريماك":"مبدأ بريماك يجعل نشاطاً محبباً مشروطاً بإنهاء نشاط أقل حباً، والطلاب هنا يجمعون نجوماً يستبدلونها لاحقاً بجوائز.","العقد السلوكي":"العقد السلوكي اتفاق مكتوب بين المعلم وطالب يحدد السلوك والمكافأة، والسؤال لم يذكر اتفاقاً بل نجوماً يجمعها الطلاب ثم يستبدلونها بجوائز.","التعزيز المتقطع":"التعزيز المتقطع جدول يعزز السلوك في بعض المرات لا كلها، والنجوم هنا تُعطى عند كل سلوك إيجابي ثم تُستبدل بجوائز."}},"11qxnik":{"w":{"التسلسل":"التسلسل يعزز كل حلقة من حلقات مترابطة تكوّن معاً سلوكاً عاماً، والمعلم هنا يعزز تقريبات متتابعة نحو إتقان سلوك واحد هو الكتابة.","التلقين":"التلقين تلميح يقدمه المعلم ليساعد الطالب على أداء الاستجابة، والمعلم هنا لا يلمّح بل يعزز كل تقدم حتى يتقن الطفل الكتابة.","النمذجة":"النمذجة تعلم بملاحظة نموذج يؤدي السلوك ثم تقليده، والسؤال لم يذكر نموذجاً بل تعزيزاً متدرجاً لكل تقدم في الكتابة."},"e":"تعزيز التقريبات المتتابعة نحو السلوك النهائي هو التشكيل (تدرج في الاستجابة)."},"1i67bns":{"w":{"التشكيل":"التشكيل يعزز تقريبات متتابعة نحو سلوك واحد، أما تعزيز كل حلقة من حلقات سلسلة مترابطة فهو التسلسل.","الإفاضة":"الإفاضة في العلاج السلوكي اسم آخر للغمر، أي مواجهة المثير المخيف دفعة واحدة، وهي في الإبداع إضافة التفاصيل، ولا تعزيز في أيهما لحلقات سلسلة سلوكية.","التلقين":"التلقين تلميح لفظي أو إيمائي أو جسدي يساعد على حدوث الاستجابة، لا تعزيز يُقدَّم عند إتمام كل حلقة من السلسلة."},"e":"التسلسل يُعلَّم فيه سلوك مركب من حلقات مترابطة، ويُعزَّز المتعلم عند أداء كل حلقة حتى تكتمل السلسلة (مثل خطوات الوضوء أو غسل اليدين). أما التشكيل فيعزز تقريبات متتابعة لسلوك واحد حتى يصل إلى صورته النهائية."},"1ajjqyj":{"w":{"أن يؤجل إلى نهاية الأسبوع ليجمع السلوكيات":"تأجيل التعزيز يضعف ارتباطه بالسلوك فلا يعرف الطالب أي سلوك عُزّز، والتعزيز الفعال يأتي عقب السلوك مباشرة.","أن يكون معززاً واحداً لجميع الطلاب":"المعزز الواحد يتجاهل الفروق بين الطلاب ويقود إلى الإشباع، والتعزيز الفعال متنوع يناسب ما يحبه كل طالب.","أن يُقدم بغض النظر عن السلوك":"التعزيز يقوّي السلوك الذي يأتي بعده، فإذا قُدّم دون سلوك محدد فقد معناه ولم يرتبط بالسلوك المرغوب."},"e":"الفورية أهم شروط التعزيز لأنها تربطه بالسلوك مباشرة."},"13oqisz":{"w":{"العقاب السالب بسحب امتياز":"العقاب السالب سحب معزز موجود كامتياز أو درجات، والمعلم هنا لم يسحب شيئاً بل حجب انتباهه عن التشويش ثم أثنى على الانشغال بالعمل.","التشكيل بالتقريبات المتتابعة":"التشكيل تعزيز تقريبات متتابعة نحو سلوك جديد، والمعلم هنا عزز سلوكاً بديلاً قائماً هو الانشغال بالعمل وتجاهل نقيضه.","التلقين والتلاشي التدريجي":"التلقين تلميح يساعد على الاستجابة ثم يُسحب تدريجياً، والمعلم هنا لم يلمّح بشيء بل تجاهل التشويش وأثنى على العمل."}},"11slhca":{"w":{"تعزيز سالب وهو مقبول":"التعزيز السالب إزالة منفّر لزيادة سلوك مرغوب، والإخراج هنا يهدف إلى تقليل التشويش، وإخراج الطالب من الفصل ممنوع بنص القواعد.","انطفاء وهو الأسلوب الأمثل":"الانطفاء حجب التعزيز بتجاهل السلوك داخل الصف، والمعلم هنا لم يتجاهل التشويش بل أخرج الطالب إلى الممر، وهذا ممنوع.","تكلفة استجابة وهو مقبول":"تكلفة الاستجابة خصم معزز مكتسب كالدرجات، والطالب هنا لم يخسر درجات بل عُزل خارج الفصل، وهو إجراء ممنوع لا مقبول."}},"q0i9jg":{"w":{"ترك الحرية له في المشاركة من عدمها":"ترك القرار له يبدو احتراماً، لكنه يبقي الخجول على انسحابه فيثبت خجله، والمطلوب دعمه ليشارك خطوة بعد خطوة.","مراعاة ظروفه بعدم إشراكه":"إعفاؤه من المشاركة يحرمه فرص النجاح ويرسخ خجله، والدرس يجعل البداية علاقة ثقة ومهاماً سهلة ينجح فيها.","تحويله إلى المرشد الطلابي":"التحويل للموجه الطلابي تصعيد قبل أن يحاول المعلم بنفسه، والخجل يبدأ علاجه داخل الصف ببناء الثقة والتدرج."},"e":"الدعم والتدرج يبنيان ثقته."},"yv1353":{"w":{"تنبيهه مرة أخرى بالأسلوب نفسه":"التنبيه إجراء أولي استنفده المعلم مع تطبيق العواقب، وتكرار السلوك بعدهما يعني الانتقال إلى التصعيد المنظم لا إعادة الأسلوب نفسه.","معاقبة الصف كله حتى يضغط عليه زملاؤه":"العقاب الجماعي ممنوع لأنه يعاقب الملتزمين بذنب غيرهم ويهدم الثقة بالمعلم، والمخالف هنا طالب واحد معروف.","نقل الطلاب المعتدى عليهم إلى فصل آخر":"نقل المعتدى عليهم يعاقب الضحايا بدل المخالف ويترك المعتدي دون علاج، والمطلوب حمايتهم وتصعيد حالة المعتدي."},"e":"استنفد المعلم إجراءاته داخل الفصل، فيأتي التصعيد المنظم: يرصد المشكلة ويسلمها لإدارة المدرسة، وهي التي تستدعي ولي الأمر وتحيل الطالب إلى الموجه الطلابي (المرشد) لدراسة حالته، ويُطبق الإجراء التالي مباشرة عند التكرار."},"1t8y0as":{"w":{"وضوح القواعد والعواقب وثباتها":"القواعد الواضحة والعواقب المعلنة الثابتة من أسس الانضباط الحازم والبيئة الآمنة، فهي ممارسة صحيحة وليست الاستثناء.","معالجة المخالفة على انفراد":"المعالجة على انفراد تعالج السلوك دون إحراج علني، وهي قاعدة ثابتة في الدرس، فلا تكون هي المستثناة.","تعزيز السلوك البديل المرغوب":"تعزيز البديل المرغوب يزيد السلوك الصحيح بدل الاكتفاء بمنع الخطأ، وهو من أركان البيئة الآمنة، فليس هو الاستثناء."},"e":"العقاب الجماعي يظلم الملتزمين ويهدم الثقة بالمعلم، وهو ممنوع تربوياً."},"7wyvsr":{"w":{"تحويله فوراً إلى المرشد الطلابي":"التحويل الفوري للموجه تصعيد قبل أن يحاول المعلم فهم السبب، وضعف الدافعية يبدأ علاجه داخل الصف بخبرات نجاح متدرجة.","إبلاغ ولي الأمر بإهماله":"إبلاغ ولي الأمر خطوة لاحقة، ووصف حاله بالإهمال حكم قبل معرفة سبب إحجامه، والأول فهم السبب ثم بناء نجاحات صغيرة.","تجاهله حتى يبادر بنفسه":"الطالب المحبط عالق في دائرة فشل تضعف مبادرته، فتجاهله يتركه فيها، والمطلوب كسرها بمهام متدرجة ينجح فيها."},"e":"فهم السبب أول خطوة في أي تعديل سلوك، ثم تُبنى خبرات نجاح صغيرة."},"1la0kr9":{"w":{"إبلاغ ولي أمر كل منهما هاتفياً من مكانه":"الإبلاغ خطوة لاحقة بعد فهم ما حدث، والموقف القائم يحتاج أولاً إيقاف الشجار وتفريق المتجمعين حولهما.","تسجيل مخالفة لكليهما دون سماعهما":"التسجيل قبل السماع حكم دون تحقق قد يظلم أحدهما، والصواب إيقاف الموقف أولاً ثم الاستماع لكل منهما على انفراد.","الطلب من الطلاب المتجمعين الحكم بينهما":"المتجمعون جمهور يعزز العدوان فيجب تفريقهم، وإشراكهم في الحكم يبقي الموقف علنياً ويخالف معالجة كل طرف على انفراد."},"e":"إيقاف الموقف وإزالة الجمهور (المعزز للعدوان) أولاً، ثم التحقق الهادئ."},"iqh0t2":{"w":{"استجواب الطالب أمام زملائه لمعرفة السبب":"الاستجواب العلني يؤذي الطالب ويكشف خصوصيته، والاشتباه في الإيذاء يُعالج بسرية عبر الموجه والإدارة.","الاتصال بوالده وتوبيخه على ما يحدث لابنه":"الاتصال المباشر بالوالد قد يعرض الطالب لخطر أكبر إن كان الإيذاء من داخل الأسرة، والتعامل مع الاشتباه للجهات المختصة.","تجاهل الأمر لأنه شأن أسري خاص بالوالدين":"الكدمات المتكررة مع التهرب من الحديث علامة اشتباه في إيذاء، وحماية الطالب واجب مهني لا شأن أسري، فيُبلغ الموجه والإدارة."},"e":"الاشتباه في إيذاء خارج صلاحية المعلم ويتطلب جهات مختصة بسرية."},"1orzgjn":{"w":{"أقل من ثانية":"أقل من ثانية زمن قصير جداً لا يتيح للطالب التفكير وصياغة إجابته، فتقل المشاركة وتقصر الإجابات، والمناسب من 3 إلى 5 ثوانٍ.","15–20 ثانية":"انتظار 15 ثانية فأكثر يطيل الصمت حتى يصير إحراجاً ويفقد الدرس زخمه، بينما تكفي من 3 إلى 5 ثوانٍ للتفكير.","دقيقة كاملة":"الدقيقة صمت طويل جداً يحرج الطلاب ويشتت انتباههم ويوقف سير الدرس، والمناسب من 3 إلى 5 ثوانٍ."}},"1nh5x5y":{"w":{"«ممتاز»":"«ممتاز» تعزيز عام يمدح دون أن يسمي ما أُنجز جيداً أو ما يحتاج إلى تحسين، فليس تغذية راجعة وصفية.","«ضعيف، راجع الدرس»":"«ضعيف» حكم عام و«راجع الدرس» توجيه مبهم، فلا يحدد موضع الضعف في العمل ولا كيف يحسّنه الطالب.","«7 من 10»":"الدرجة حكم رقمي على العمل بلا توجيه، فلا تخبر الطالب بما أحسن فيه ولا بما يحتاج إلى تحسينه."},"e":"الوصفية تسمي ما أُنجز وما يُحسَّن وكيف."},"d3l09d":{"w":{"اللفظي العلني أمام الصف كله":"التواصل العلني يضع الخجول في بؤرة اهتمام الصف فيزيد توتره، بينما الإشارة غير اللفظية تشجعه دون أن تلفت إليه الأنظار.","الكتابي الرسمي فقط دون حديث":"الاقتصار على الكتابة الرسمية يبعد الخجول عن التواصل المباشر ولا يقربه من المشاركة، والدرس يجعل غير اللفظي الأنسب لتشجيعه.","التوبيخ الخفيف لتحفيزه على المشاركة":"التوبيخ ولو كان خفيفاً يزيد خوف الخجول وانسحابه، فما يحتاجه علاقة ثقة وتشجيع لطيف كالابتسامة والإيماءة."},"e":"الإشارات غير اللفظية تشجع دون أن تضعه في بؤرة الاهتمام."},"1irbhvl":{"w":{"نقل السؤال إلى طالب أفضل منه تخفيفاً عنه":"نقل السؤال يسحب فرصة الطالب ويؤكد للصف أن الضحك نجح، والمطلوب حمايته من السخرية وإتاحة الوقت ليكمل.","إنهاء النقاش والانتقال إلى نقطة أخرى في الدرس":"الانتقال لنقطة أخرى يترك السخرية دون موقف ويقطع على الطالب فرصته، فيتعلم الصف أن الضحك يوقف المشاركة.","الطلب من الطالب الجلوس حتى لا يُحرج أكثر":"إجلاسه يحرمه إكمال إجابته ويكافئ الضاحكين، والأمان النفسي يقتضي إيقاف الضحك بحزم ثم تعزيز الطالب بعد أن يكمل."},"e":"الأمان النفسي يقتضي حماية الطالب من السخرية وإكمال فرصته."},"qimmsp":{"w":{"الرد برسالة دفاعية مفصلة تثبت خطأ الطالب":"الرد الدفاعي يبدأ بوجهة نظر المعلم قبل الإنصات فيصعّد الخلاف، والترتيب الصحيح استمع ثم افهم ثم اشرح ثم اتفق.","تجاهل الرسالة لأنها غير مهذبة في أسلوبها":"تجاهل الرسالة يقطع التواصل ويترك اتهام التحيز قائماً، وغضب ولي الأمر يُقابل بالإنصات ثم عرض الحقائق بهدوء.","تحويل الرسالة إلى مدير المدرسة فوراً دون رد":"التحويل الفوري دون رد تخلٍّ عن التواصل، والمعلم هو المعني بالاتهام فيبدأ بلقاء ينصت فيه ثم يعرض الحقائق."},"e":"الإنصات أولاً قاعدة التعامل مع ولي الأمر الغاضب، ثم الحقائق بهدوء."},"ha3yjq":{"w":{"أن تكون مفتوحة لأي شخص من خارج المدرسة":"فتحها لمن هم خارج المدرسة يعرض الطلاب لغرباء ويهدد خصوصيتهم، ومؤشر الهيئة يجعلها مع زملائهم تحت إشراف المعلم.","أن تُخصص للتسلية والترفيه بعد الدوام":"تخصيصها للترفيه يفقدها هدفها التعليمي، والسؤال يريد تعزيز التعلم، وهذا يحتاج أهداف تعلم واضحة وإشراف المعلم.","أن يديرها الطلاب وحدهم دون أي متابعة":"غياب متابعة المعلم يفقد المجموعات توجيهها التعليمي ويعرضها للتشتت، والمؤشر ينص على أنها تحت إشرافه وتوجيهه."}},"77m124":{"w":{"الاكتفاء بالمتطوعين لأنهم الأكثر رغبة في المشاركة":"الاكتفاء بالمتطوعين يهمّش بقية الصف ويبقي المشاركة في ثلاثة طلاب، وهي المشكلة نفسها التي يريد المعلم حلها.","خصم درجات من غير المشاركين لدفعهم إلى المشاركة":"خصم الدرجات عقاب يولد الخوف، والخوف من الخطأ معوق للتفاعل اللفظي، فلا يبني مشاركة حقيقية بل يزيد القلق.","طرح أسئلة أصعب على المتطوعين لتحدي قدراتهم":"تحدي المتطوعين يبقي الأسئلة موجهة إليهم وحدهم، فلا يوسع المشاركة لبقية الصف وهي هدف المعلم في السؤال."},"e":"التوزيع العادل مع زمن الانتظار يرسل رسالة أن الجميع متوقع منهم المشاركة."},"1o53xq7":{"w":{"الاختيار من متعدد":"الاختيار من متعدد سؤال موضوعي يختار فيه الطالب إجابة محددة سلفاً، فلا تختلف درجته باختلاف المصحح، فليس هو الاستثناء.","الصواب والخطأ":"الصواب والخطأ من الأسئلة الموضوعية ذات الإجابة المنتقاة، يحكم فيه الطالب على العبارة بإحدى إجابتين محددتين، فليس هو الاستثناء.","المطابقة":"المطابقة سؤال موضوعي يصل فيه الطالب بين قائمتين بإجابات محددة سلفاً، وتصحيحها ثابت لا يتأثر بالمصحح."},"e":"المقالية المقيدة يكتب فيها الطالب إجابته بأسلوبه وإن حُدد نطاقها (مثل: اذكر ثلاثة أسباب)، فتتأثر درجتها بتقدير المصحح، فهي مقالية لا موضوعية. أما الاختيار من متعدد والصواب والخطأ والمطابقة والإكمال فإجاباتها محددة سلفاً وتصحيحها ثابت لا يختلف باختلاف المصحح."},"3eva0l":{"w":{"معياري المرجع":"معياري المرجع يقارن الطالب بأقرانه، والمعلم هنا قارن الطالب بدرجته هو في الاختبار القبلي.","محكي المرجع":"محكي المرجع يقارن الأداء بمحك إتقان محدد، والمقارنة هنا بين درجتين للطالب نفسه لمعرفة تقدمه.","ختامي":"الختامي تصنيف بزمن التقويم وغرضه لا بمرجع التفسير، والسؤال يسأل عن المرجع، وهو هنا درجة الطالب السابقة."},"e":"ذاتي المرجع يقارن الطالب بنفسه عبر الزمن."},"k8xs7a":{"w":{"داخلياً، وخارجياً":"الترتيب هنا معكوس، فتقويم الوزارة والهيئة من خارج المدرسة خارجي، وتقويم المدرسة لنفسها داخلي.","معيارياً، ومحكياً":"المعياري والمحكي تصنيف بمرجع تفسير الدرجة، أما السؤال فيصنّف التقويم بالجهة التي تقوم به.","ختامياً، وتكوينياً":"الختامي والتكويني تصنيف بزمن التقويم وغرضه، أما السؤال فيفرّق بالجهة المقوّمة: من خارج المدرسة أو من داخلها."}},"l5pmyi":{"w":{"قائمة الشطب":"قائمة الشطب تسأل عن وجود السلوك أو غيابه بنعم أو لا، والأداة هنا تدرّج الموافقة في خمس درجات.","الاختبار التحصيلي":"الاختبار التحصيلي يقيس ما تعلمه الطالب من معارف ومهارات، والمطلوب هنا اتجاهاته نحو المادة، وهي جانب وجداني.","السجل القصصي":"السجل القصصي يكتب فيه المعلم وصفاً لمواقف لاحظها من سلوك الطالب، ولا يختار فيه الطالب درجة موافقته على عبارات."},"e":"ليكرت مقياس تقرير ذاتي خماسي للاتجاهات (نواتج وجدانية)."},"1to2g75":{"w":{"الموضوعي":"الاختبار الموضوعي كتابي سريع التصحيح لا يتأثر بذاتية المصحح، وهذا عكس ما يصفه السؤال من طول الوقت وتأثره بذاتية المعلم.","المقالي":"المقالي اختبار كتابي، فلا يكشف التلاوة والنطق في مادة القرآن، ولا يناسب طلاب الصفوف الأولية الذين لم يتقنوا الكتابة بعد.","الأدائي":"الاختبار الأدائي يقيس تنفيذ مهمة عملية كالتجربة والوضوء بالملاحظة، أما مناسبة الصفوف الأولية والقرآن وانعدام الغش مع طول الوقت والذاتية فسمات الاختبار الشفوي."},"e":"الاختبار الشفوي يكشف النطق والتعبير ولا مجال فيه للغش، وعيوبه الوقت والذاتية."},"1x9evls":{"w":{"الاعتماد على اختبار تحريري واحد":"الاختبار التحريري الواحد يخالف فكرة التقويم البديل القائم على مهام حقيقية وأدوات متعددة، ولا يمنح الطلاب فرصاً متكافئة لإظهار أدائهم.","إخفاء معايير التصحيح عن الطلاب":"التقويم البديل يقوم على معايير معلنة مسبقاً، فإخفاؤها يجعل الطالب يعمل دون أن يعرف ما يُحكم به على عمله.","تقويم الطلاب بأدوات مختلفة دون معيار":"تعدد الأدوات مفيد بشرط معيار واحد للجميع، وبدونه تختلف الأحكام من طالب لآخر فتضيع العدالة."}},"1bwbvhi":{"w":{"تصنيف الطلاب نهائياً دون تقديم أي علاج":"التقويم حكم يتبعه قرار تعديل وعلاج، فالتصنيف النهائي بلا علاج يقف عند الحكم وحده ويناقض غرض التقويم.","الاكتفاء برصد الدرجات في السجلات الرسمية":"رصد الدرجات وحده قياس، والتقويم يتجاوزه إلى الحكم ثم التشخيص والتوجيه والتطوير.","معاقبة المقصرين من الطلاب على تقصيرهم":"العقاب ليس من غايات التقويم، فالتقويم يكشف سبب التقصير ليعالجه ويوجه التعلم، لا ليعاقب عليه."},"e":"التقويم يشخص ويوجه ويحكم ويطور ويدعم القرارات."},"1nu0f1y":{"w":{"أن يقتصر على اختبار نهائي واحد":"الاقتصار على اختبار نهائي واحد يخالف الاستمرار والشمول، فالتقويم الجيد يرافق التعلم ويتنوع في أدواته.","أن يُسند إلى المشرف فقط":"التقويم الجيد تعاوني يشارك فيه المعلم والطالب وغيرهما، فحصره في المشرف وحده يخالف هذا الأساس.","أن يركز على الحفظ دون المهارات":"التقويم الجيد شامل لجوانب المتعلم المعرفية والمهارية والوجدانية، فالتركيز على الحفظ وحده يخالف الشمول."},"e":"أسس التقويم: وضوح الأهداف، الاستمرار، الشمول، التعاون، العلمية."},"1pers6t":{"w":{"تقويم ثم قياس ثم تقييم":"يبدأ هذا الترتيب بالعلاج قبل جمع الأرقام والحكم عليها، والعلاج لا يكون إلا بعد قياس الأداء والحكم عليه.","تقييم ثم قياس ثم تقويم":"لا يمكن الحكم على قيمة الأداء قبل قياسه، فالتقييم يحتاج رقماً يسبقه، ثم يأتي التقويم بعدهما.","قياس ثم تقويم ثم تقييم":"يضع هذا الترتيب قرار العلاج قبل الحكم، والعلاج يُبنى على الحكم، فالتقييم يسبق التقويم لا يتبعه."}},"qeobuh":{"w":{"استعداد":"اختبار الاستعداد يتنبأ بنجاح الطالب في تعلم لاحق، والمعلم هنا يريد ما اكتسبه طلابه فعلاً بعد تدريس الوحدة.","ذكاء":"اختبار الذكاء يقيس القدرة العقلية العامة، لا المعارف والمهارات التي اكتسبها الطلاب من وحدة درسوها.","قدرات عامة":"اختبار القدرات العامة يقيس استعدادات عقلية عامة، ولا يرتبط بمحتوى وحدة معينة درّسها المعلم لطلابه."},"e":"الاختبار التحصيلي يقيس نواتج التعلم الفعلية."},"11awf1s":{"w":{"تطبَّق في ظروف وتعليمات موحدة لجميع المختبرين":"توحيد التعليمات والظروف من أهم خصائص الاختبار المقنن، حتى تكون درجات جميع المختبرين قابلة للمقارنة، فليس هو الاستثناء.","يعدّها فريق من المتخصصين بإشراف مراكز القياس":"الاختبار المقنن يعده متخصصون لا معلم الفصل، فهذه خاصية أصيلة فيه وليست الاستثناء المطلوب.","لها معايير تُفسَّر الدرجات في ضوئها":"الاختبار المقنن له معايير تُقارن بها درجة الفرد بأداء مجموعة مرجعية، وهذه من خصائصه الأساسية فليست الاستثناء."}},"alhc6p":{"w":{"نوع الأسئلة: موضوعية مقابل مقالية":"نوع الأسئلة لا يميز بينهما، فكلاهما قد يستعمل الموضوعية والمقالية، والفرق الحاسم متى يُجرى التقويم ولأي غرض.","من يقوم بالتصحيح: الطالب مقابل المعلم":"من يصحح لا يحدد نوع التقويم، فقد يصحح المعلم في الحالتين، والفرق الحاسم في توقيته وغرضه: تحسين أم حكم.","عدد الأسئلة: قليلة مقابل كثيرة":"عدد الأسئلة لا يحدد النوع، فاختبار قصير قد يكون ختامياً، والفرق الحاسم أن التكويني للتحسين أثناء التعلم والختامي للحكم في نهايته."},"e":"التكويني أثناء التدريس وغايته التحسين والتغذية الراجعة، والختامي في النهاية وغايته الحكم."},"c7mb04":{"w":{"القبلي":"القبلي يسبق التعلم ليكشف الاستعداد والمتطلبات السابقة، فلا يحكم على طرق تدريس لم تُستعمل بعد.","التشخيصي":"التشخيصي يكشف نقاط القوة والضعف وأسباب الصعوبة ليُبنى عليه العلاج، لا ليحكم على فاعلية التدريس في الفصل كاملاً.","الذاتي":"الذاتي يقارن الطالب بأدائه السابق أو يحكم فيه الطالب على عمله بنفسه، والمطلوب هنا حكم على طرق التدريس بعد الفصل كله."},"e":"من أغراض التقويم الختامي الحكم على فاعلية جهود المعلم وطرق تدريسه ومقارنة الشعب."},"1krbytz":{"w":{"معياري المرجع":"معياري المرجع يقارن الطالب بأقرانه، أما هنا فينتقل الطالب بوصوله إلى نسبة 80% مهما كان أداء زملائه.","ذاتي المرجع":"ذاتي المرجع يقارن الطالب بدرجته السابقة، أما الانتقال هنا فمشروط بنسبة إتقان ثابتة محددة مسبقاً.","قبلي":"القبلي يسبق التعلم ليكشف المتطلبات السابقة، أما هنا فاختبار بعد تعلم المهارة يُحكم عليه بنسبة إتقان ثابتة."},"e":"نسبة الإتقان المحددة مسبقاً (80%) محك ثابت يقارن به أداء الطالب، فهو محكي المرجع."},"1whi173":{"w":{"معياري المرجع":"معياري المرجع يقارن درجة الطالب بدرجات أقرانه، والمعلم هنا قارنها بدرجة الطالب نفسه في الشهر الأول.","محكي المرجع":"محكي المرجع يقارن الأداء بمستوى إتقان محدد، والمقارنة هنا بين درجتي الطالب في شهرين لمعرفة تقدمه.","مقنن":"المقنن وصف لاختبار يعده متخصصون بظروف موحدة ومعايير، وليس طريقة لتفسير الدرجة كمقارنة الطالب بنفسه."},"e":"مقارنة الطالب بأدائه السابق تفسير ذاتي المرجع يركز على النمو الفردي."},"wtf0dc":{"w":{"التقويم الذاتي":"التقويم الذاتي يحكم فيه الطالب على عمله هو، والطالبان هنا صحّح كل منهما مسودة زميله.","التقويم الختامي":"الختامي حكم يصدره المعلم في نهاية الوحدة أو الفصل، أما هنا فطالب يحكم على مسودة زميله بمحكات أعدها المعلم.","تقويم الأداء":"تقويم الأداء يقيس إنجاز الطالب لمهمة فعلية، والسمة الحاسمة هنا أن من يحكم على العمل زميل لا المعلم."},"e":"حكم الطالب على عمل زميله وفق محكات هو تقويم الأقران."},"xhgb7g":{"w":{"رصد درجات أعمال السنة":"بطاقة الخروج أداة تقويم غير رسمي سريعة، غرضها أن يعرف المعلم ما غمض على طلابه فيعدّل الحصة التالية، لا رصد الدرجات.","التقويم الختامي للوحدة":"الختامي يأتي في نهاية الوحدة ليصدر حكماً، والكتابة هنا في نهاية كل حصة ليعدّل المعلم تدريسه في الحصة التالية.","تصنيف الطلاب إلى مستويات":"الطلاب هنا يكتبون ما فهموه وما غمض عليهم، وهذا يوجّه المعلم إلى تعديل تدريسه لا إلى توزيعهم على مستويات."},"e":"تذكرة الخروج تكشف ما تعلمه الطلاب وما غمض عليهم فيعدل المعلم الحصة التالية؛ وهذا تقويم تكويني."},"1tqiz4p":{"w":{"السجل القصصي":"السجل القصصي يكتبه المعلم ليصف سلوكاً لافتاً للطالب، وهنا الطالب نفسه يجمع أعماله ويراجعها ويكتب ملاحظاته عن تقدمه.","قائمة الشطب":"قائمة الشطب ترصد وجود السلوك أو غيابه بنعم أو لا، ولا تجمع أعمال الطالب في حقيبة ليراجعها ويتأمل في تقدمه.","سلم التقدير العددي":"سلم التقدير العددي يحدد درجة الأداء على مقياس مثل 1 إلى 5، والموقف هنا جمع منظم للأعمال يراجعه الطالب كل أسبوع."},"e":"جمع الأعمال بانتظام ومراجعتها بهدف التأمل في التقدم هو ملف الإنجاز (البورتفوليو)."},"teaev4":{"w":{"اختبار اختيار من متعدد عن خطوات التجربة":"الاختيار من متعدد يقيس معرفة الطالب بخطوات المعايرة، لا قدرته على تنفيذها فعلاً بيده في المختبر.","اختبار مقالي يصف فيه الطالب التجربة":"المقالي يكشف قدرة الطالب على وصف التجربة كتابة، والمطلوب تقويم مهارته في إجرائها، وهذا يحتاج ملاحظة أدائه الفعلي.","قائمة بالمصطلحات العلمية للحفظ":"حفظ المصطلحات وسيلة لتذكر المفردات لا أداة تقويم للأداء، ولا يكشف مهارة الطالب في إجراء المعايرة."},"e":"المهارة العملية تُقوَّم بملاحظة الأداء الفعلي بأداة مدرجة."},"m8pg73":{"w":{"التقويم الختامي للأعمال":"التقويم الختامي يصدر حكماً نهائياً في آخر الوحدة أو الفصل، والجلسة هنا حوار يسأل فيه المعلم الطالب كيف يطور أعماله.","الاختبار الشفهي المقنن":"الاختبار المقنن يعده متخصصون بتعليمات وظروف موحدة ومعايير، والجلسة هنا حوار فردي مرن حول أعمال الطالب واختياراته.","تقويم الأقران لأعمال زملائهم":"تقويم الأقران يحكم فيه الزملاء على أعمال بعضهم بمحكات معدة مسبقاً، والجلسة هنا بين المعلم والطالب وحدهما."},"e":"الحوار وجهاً لوجه مع الطالب حول أعماله وتفكيره هو التقويم بالتواصل."},"1f13eef":{"w":{"ملف الإنجاز للطالب":"ملف الإنجاز من أبرز أدوات التقويم البديل، إذ يجمع أعمال الطالب المؤرخة لمتابعة تقدمه والتأمل فيه، فليس هو المستثنى.","سلم التقدير اللفظي الوصفي":"سلالم التقدير اللفظية والوصفية من أدوات التقويم البديل، تقدّر الأداء في مهام حقيقية بمعايير معلنة، فليست هي المستثنى.","السجل القصصي للسلوك":"السجل القصصي من أدوات التقويم البديل القائمة على الملاحظة والسجلات، يصف فيه المعلم سلوك الطالب كما وقع، فليس هو المستثنى."}},"1sfmzrh":{"w":{"نقل الجملة حرفياً من الكتاب مع حذف كلمة":"النقل الحرفي من الكتاب يشجع الحفظ الآلي للنص بدل الفهم، والقاعدة صياغة العبارة بأسلوب جديد مع فراغ واحد مهم.","ترك عدة فراغات في الجملة الواحدة":"كثرة الفراغات في الجملة الواحدة تجعل معناها مبهماً فلا يعرف الطالب المطلوب، والقاعدة فراغ واحد لكلمة مهمة.","وضع الفراغ في بداية الجملة لتنبيه الطالب":"الفراغ في بداية الجملة يقطع السياق قبل أن يقرأه الطالب، والقاعدة وضعه قرب آخر الجملة ليتضح المطلوب."},"e":"الفراغ الواحد في موضع مهم قرب النهاية يجعل المطلوب واضحاً بعد قراءة السياق."},"4uq2g0":{"w":{"موضوعي لا يقيس التفكير":"السؤال الموضوعي يقدم إجابة جاهزة للاختيار، وهذا السؤال مقالي يكتب فيه الطالب الأسباب بنفسه، ومشكلته أنه غير محدد.","قصير جداً":"قِصر نص السؤال ليس عيباً في ذاته، ومشكلته هنا أنه لا يحدد عدد الأسباب ولا نطاق الإجابة المطلوبة.","يحتوي على كلمات جزم":"كلمات الجزم مثل «كل» و«دائماً» عيب في أسئلة الصواب والخطأ، وهذا السؤال مقالي خالٍ منها، ومشكلته عدم تحديد المطلوب."},"e":"السؤال لا يحدد عدد الأسباب ولا نطاق الإجابة فيختلف المصححون في تقدير الإجابة؛ والأفضل تقييده مثل: اذكر ثلاثة أسباب."},"1g2qix4":{"w":{"المقالية المقيدة":"المقالية المقيدة تطلب من الطالب أن يكتب حكمه ويبرره في نطاق محدد، فهي مناسبة لمستوى التقويم وليست الأقل مناسبة.","المقالية الحرة":"المقالية الحرة تتيح للطالب إصدار الحكم وتبريره بأسلوبه وتنظيمه، وهذا جوهر مستوى التقويم، فليست الأقل مناسبة.","الاختيار من متعدد المبني على موقف":"الاختيار من متعدد المبني على موقف يمكن أن يقيس مستويات عليا كالموازنة بين بدائل والحكم عليها، فليس الأقل مناسبة هنا."},"e":"مستوى التقويم يطلب حكماً مع تبرير. الصواب والخطأ حكم بين احتمالين بلا تبرير، ونسبة التخمين فيه 50%، فهو الأقل مناسبة. أما المقالية بنوعيها فتتيح كتابة الحكم وتبريره، والاختيار من متعدد المبني على موقف يقيس الحكم حين تكون بدائله أحكاماً أو مبررات يختار الطالب أقواها."},"1c5y1ht":{"w":{"6 أسئلة":"6 هو عدد حصص الوحدة لا عدد أسئلتها، والصحيح 6 ÷ 30 × 40 = 8 أسئلة.","12 سؤالاً":"12 سؤالاً تعني وزناً قدره 30% من الاختبار، بينما وزن الوحدة 6 ÷ 30 = 20%، فنصيبها 8 أسئلة فقط.","10 أسئلة":"10 أسئلة تعني 25% من الاختبار، ووزن الوحدة الفعلي 6 ÷ 30 = 20%، و 20% من 40 تساوي 8 أسئلة."},"e":"وزن الوحدة = 6 ÷ 30 = 0.20 أي 20%. عدد أسئلتها = 40 × 0.20 = 8 أسئلة."},"qtjxhf":{"w":{"صعوبة الموضوع على الطلاب":"صعوبة الموضوع تُراعى في صياغة الفقرات وترتيبها، أما وزنه فيُحسب من عدد حصصه أو أهدافه ÷ المجموع × 100.","ترتيب الموضوع في الكتاب":"تسلسل الموضوع في الكتاب لا يعكس حجمه في التدريس، فقد يأخذ موضوع متأخر حصصاً أكثر، والوزن يتبع الحصص والأهداف.","رغبة الطلاب في الموضوع":"رغبة الطلاب أمر يخص الدافعية لا تمثيل المحتوى، والوزن يُحدد بحجم الموضوع في التدريس وأهميته ليتحقق صدق المحتوى."},"e":"الوزن النسبي يُشتق من حجم الموضوع في التدريس (حصصه أو أهدافه) وأهميته."},"1vefmno":{"w":{"الاعتماد على أسئلة مقالية حرة":"المقالية الحرة تترك للطالب حرية واسعة في الإجابة، فيختلف المصححون في تقديرها وترتفع الذاتية بدل الموضوعية.","ترك تقدير الدرجة لانطباع المصحح":"الانطباع الشخصي يجعل الدرجة تابعة لرأي المصحح، والموضوعية تعني أن تبقى الدرجة واحدة أياً كان المصحح.","عدم تحديد درجة لكل سؤال":"إذا لم تُحدد درجة كل سؤال مسبقاً وزّعها كل مصحح باجتهاده، فتختلف الدرجات وتضعف موضوعية الاختبار."},"e":"الموضوعية هي استقلال الدرجة عن المصحح، وتتحقق بالأسئلة محددة الإجابة ونموذج تصحيح."},"t2ex8t":{"w":{"اختبار للرياضيات فقط":"تاليس لا يقيس الرياضيات ولا أي مادة، فهو استطلاع للمعلمين وقادة المدارس عن ظروف التدريس والتطوير المهني.","اختبار يُعقد سنوياً للصف الأول":"تاليس لا يُطبق على طلاب أي صف، بل يستطلع المعلمين وقادة المدارس عن بيئات التدريس والتطوير المهني.","اختبار وطني خاص بالمملكة":"تاليس مسح دولي تجريه منظمة التعاون الاقتصادي والتنمية في دول عدة، أما الاختبارات الوطنية في المملكة فهي نافس."}},"ejh7di":{"w":{"0.12":"المعامل 0.12 يقابل مجموعاً قدره 0.12 × 200 = 24 درجة فقط، والمجموع هنا 120، فالمعامل 120 ÷ 200 = 0.60.","6.0":"الرقم 6 هو متوسط درجة الطالب (120 ÷ 20) قبل قسمته على درجة السؤال 10، والمعامل 6 ÷ 10 = 0.60.","0.83":"المعامل 0.83 يقابل مجموعاً نحو 166 درجة من 200، والمجموع الفعلي 120، فالمعامل 120 ÷ 200 = 0.60."}},"1rqkh54":{"w":{"زيادة التخمين":"التخمين يجعل الإجابة الصحيحة مصادفة قد تتغير من تطبيق لآخر، فيخفض الثبات ولا يرفعه.","غموض صياغة الأسئلة":"الغموض يجعل الطالب يفهم السؤال بطرق مختلفة في كل مرة، فتضطرب إجابته وينخفض الثبات.","اضطراب الطلاب أثناء التطبيق":"اضطراب الطلاب أثناء التطبيق عامل عارض يبعد أداءهم عن مستواهم الحقيقي، فيخفض اتساق الدرجات أي الثبات."},"e":"طول الاختبار بفقرات متجانسة متوسطة الصعوبة يزيد الثبات."},"1lbqlmv":{"w":{"ملتوٍ التواءً موجباً وذيله جهة اليمين":"الالتواء الموجب يحدث حين تكون أغلب الدرجات منخفضة وقلة عالية، والسؤال يصف العكس: أغلبية مرتفعة وقلة منخفضة.","اعتدالي تماماً":"المنحنى الاعتدالي متماثل حول متوسطه، أما تكدس أغلب الدرجات في الجهة العليا مع قلة منخفضة فيكسر هذا التماثل.","مدبب بلا التواء":"التدبب وصف لحدة القمة لا لميل التوزيع، وتكدس الدرجات في الجهة العليا مع قلة منخفضة التواء سالب."},"e":"الالتواء يُسمى بجهة الذيل لا بجهة تجمع الدرجات: أغلب الدرجات مرتفعة وقلة منخفضة، فالذيل الطويل جهة الدرجات المنخفضة (اليسار)، فالالتواء سالب. وإذا كانت أغلب الدرجات منخفضة وقلة مرتفعة فالذيل جهة اليمين والالتواء موجب."},"1a2rqdw":{"w":{"مفرطح":"المفرطح قمته أكثر انبساطاً من المنحنى الاعتدالي، والسؤال يصف قمة حادة ودرجات متقاربة حول المتوسط.","ملتوٍ موجباً":"الالتواء الموجب يصف ميل التوزيع وذيله الممتد نحو الدرجات العالية، والسؤال يصف حدة القمة لا الميل.","ملتوٍ سالباً":"الالتواء السالب يصف ذيلاً ممتداً نحو الدرجات المنخفضة، والسؤال يتحدث عن حدة القمة، وهذا من التفرطح."},"e":"التفرطح يصف شكل القمة مقارنة بالمنحنى الاعتدالي: القمة الأحدّ منه مدببة."},"3spxsy":{"w":{"الاختبار الثابت صادق بالضرورة لأن نتائجه مستقرة":"استقرار النتائج يعني الثبات فقط، وقد يتسق الاختبار وهو يقيس غير المقصود، كالميزان الذي يزيد كيلوين في كل مرة.","لا علاقة بينهما، فكل منهما يقيس جانباً مستقلاً من الاختبار":"بينهما علاقة شرطية، فالثبات شرط ضروري للصدق، ولا يقيس الاختبار السمة بدقة إذا كانت نتائجه غير متسقة.","الثبات أشمل من الصدق ويتضمنه":"العلاقة معكوسة هنا، فالصدق هو الأشمل ويتضمن الثبات، والثبات شرط ضروري له لكنه غير كافٍ."}},"1pa2fsv":{"w":{"المحتوى (المضمون)":"صدق المحتوى يتحقق من تمثيل الفقرات للمحتوى بجدول المواصفات والتحكيم، أما مطابقة أبعاد النظرية بالتحليل العاملي فصدق بناء.","التلازمي (التزامني)":"الصدق التلازمي ارتباط الدرجات بمحك خارجي يُجمع في الوقت نفسه، والباحث هنا لم يستخدم محكاً بل التحليل العاملي.","الظاهري (السطحي)":"الصدق الظاهري مجرد مظهر الاختبار وهو أضعف الأنواع، والباحث هنا تحقق إحصائياً من انتظام الفقرات في أبعاد النظرية."}},"j6hv7k":{"w":{"الثبات، لأن الاختبار طُبّق مرة واحدة":"التطبيق مرة واحدة لا يعني ضعف الثبات، والمشكلة هنا أن اختبار القواعد استُخدم للحكم على قدرة لغوية شاملة لا يقيسها.","الموضوعية، لأن أسئلة القواعد مقالية":"السؤال لم يذكر أن أسئلة القواعد مقالية، والخلل هنا في استخدام الاختبار لغرض غير غرضه لا في تصحيحه.","التمييز، لأن أسئلة القواعد سهلة":"السؤال لم يذكر سهولة الأسئلة، والخلل هنا أن اختبار القواعد لا يقيس القراءة والكتابة والتحدث التي حُكم عليها."}},"1g3aqnk":{"w":{"الثبات":"الثبات يُقدّر من درجات الطلاب باتساق نتائجهم، أما حكم المتخصصين على تمثيل الفقرات للمحتوى فأسلوب لصدق المحتوى.","الصدق التنبؤي":"الصدق التنبؤي يحتاج محكاً يُجمع مستقبلاً ويُحسب ارتباطه بالدرجات، والمعلم هنا اكتفى بحكم المتخصصين على الفقرات.","معامل التمييز":"معامل التمييز يُحسب من إجابات الفئتين العليا والدنيا بعد التطبيق، ولا يتحقق بعرض الفقرات على متخصصين."},"e":"حكم المحكمين على تمثيل الفقرات للمحتوى والأهداف أسلوب لتقدير صدق المحتوى."},"8yp5mb":{"w":{"كرونباخ ألفا للمقاييس المتدرجة":"كرونباخ ألفا يُستخدم للمقاييس المتدرجة كمقياس ليكرت، والفقرات هنا ثنائية التصحيح، وهذا موضع كودر ريتشاردسون.","معادلة التنبؤ":"معادلة التنبؤ تقدّر قيمة متغير من متغير آخر، ولا تحسب ثبات اختبار من تطبيق واحد.","معامل سبيرمان للرتب":"معامل سبيرمان للرتب يقيس الارتباط بين ترتيبين لمتغيرين، ولا يقدّر الاتساق الداخلي لفقرات ثنائية التصحيح."},"e":"كودر ريتشاردسون (20 و21) مخصصة للفقرات ثنائية التصحيح."},"1keiss9":{"w":{"0.60":"الرقم 0.60 هو ارتباط النصفين قبل التصحيح ويمثل ثبات نصف الاختبار فقط، والتصحيح (2 × 0.60) ÷ 1.60 = 0.75.","0.30":"الرقم 0.30 نصف ارتباط النصفين، والتصحيح يرفع المعامل ولا يخفضه، فالثبات (2 × 0.60) ÷ 1.60 = 0.75.","0.80":"لو كان الثبات 0.80 لكان ارتباط النصفين نحو 0.67، والمعطى 0.60، فالثبات 1.20 ÷ 1.60 = 0.75."}},"emurkh":{"w":{"طول الاختبار الزائد":"طول الاختبار يرفع الثبات لأنه يقلل أثر الصدفة، فلا يفسر انخفاضه، والسبب هنا تقارب قدرات العينة.","صعوبة الفقرات المتوسطة":"توسط صعوبة الفقرات يرفع الثبات لأنه يزيد تباين الدرجات، والسبب هنا تقارب قدرات العينة الذي يقلل التباين.","وضوح التعليمات":"وضوح التعليمات يقلل الغموض فيرفع الثبات، والسؤال يشير إلى تقارب قدرات العينة سبباً للانخفاض."},"e":"معامل الثبات ارتباط، والارتباط ينخفض حين يقل التباين؛ فالعينة المتجانسة تعطي ثباتاً أقل."},"vhv2gd":{"w":{"الصدق شرط للثبات، والثبات شرط للموضوعية":"الترتيب هنا معكوس، فالموضوعية في القاعدة شرط للثبات، والثبات شرط للصدق الذي يأتي في القمة.","الثبات شرط للموضوعية، والموضوعية شرط للصدق":"الموضوعية تسبق الثبات لا تليه، فتأثر الدرجة بالمصحح يخل باتساقها، ثم يأتي الصدق في القمة مشروطاً بالثبات.","لا توجد علاقة شرطية بين الثلاث":"بين الثلاث علاقة شرطية: تأثر الدرجة بالمصحح يخل بالثبات، واختلال الثبات يمنع قياس السمة بدقة أي الصدق."}},"32psis":{"w":{"الإبقاء عليها لأن صعوبتها متوسطة":"صعوبتها فعلاً متوسطة (20 ÷ 40 = 0.50)، لكن التمييز السالب خلل جوهري يوجب الحذف مهما كانت الصعوبة.","تعديلها قليلاً لأن تمييزها 0.40":"التمييز هنا (6 − 14) ÷ 20 = −0.40 بإشارة سالبة لا موجبة، أي أن الضعاف أجابوا أفضل، فالفقرة تُحذف لا تُعدّل.","استبدال أحد مشتتاتها فقط":"استبدال مشتت واحد علاج جزئي لبديل ضعيف، أما التمييز السالب فيعني أن الضعاف أجابوا أفضل، وهذا خلل جوهري يستوجب حذف الفقرة."}},"uwevwk":{"w":{"صفر و1":"معامل الصعوبة صفر يعني أن أحداً لم يُصب، والتمييز 1 يعني أن العليا أصابت كلها والدنيا أخطأت، وهنا أصاب الجميع.","0.5 و0.5":"الصعوبة 0.5 تعني أن نصف الطلاب أصابوا، والتمييز يقيس الفرق بين الفئتين، وهنا أصاب الجميع فلا فرق بينهما.","1 و1":"التمييز 1 يعني أن العليا أصابت كلها والدنيا أخطأت كلها، وهنا أصاب الجميع فالفرق بين الفئتين صفر رغم أن الصعوبة 1."}},"1nfm0dc":{"w":{"الفقرات شديدة الصعوبة أعلى تمييزاً دائماً":"الفقرة التي لا يجيبها أحد تقريباً تخطئ فيها الفئتان العليا والدنيا معاً، فيقترب الفرق بينهما وتمييزها من الصفر.","الفقرات شديدة السهولة أعلى تمييزاً دائماً":"الفقرة التي يجيبها الجميع تقريباً تصيب فيها الفئتان معاً، فلا يظهر فرق بينهما ويقترب تمييزها من الصفر.","لا علاقة بينهما إطلاقاً":"الصعوبة تحدد أقصى تمييز ممكن، فالفقرة المتطرفة في السهولة أو الصعوبة لا تترك فرقاً يُذكر بين الفئتين."},"e":"حين تكون الصعوبة قرب 0.50 يمكن أن يكون الفرق بين الفئتين أكبر ما يمكن."},"1lip386":{"w":{"يزيد كل منهما 5 درجات":"إضافة 5 تزيد المتوسط 5، لكنها تنقل الدرجات كلها معاً، فتبقى المسافات بينها والانحراف المعياري كما هما.","لا يتغير المتوسط ويزيد الانحراف 5":"ارتفاع كل درجة 5 يرفع المتوسط 5 حتماً، والانحراف المعياري يبقى ثابتاً لأن المسافات بين الدرجات لم تتغير.","يتغير كل منهما بنسبة 5%":"التغير بنسبة يحدث عند ضرب الدرجات في ثابت، أما إضافة 5 فترفع المتوسط 5 درجات ولا تمس الانحراف."}},"173mg75":{"w":{"الصف الثاني أكثر تجانساً":"الانحراف 12 يعني تباعد درجات الصف الثاني عن متوسطها، والتجانس يكون مع الانحراف الأصغر 3 في الصف الأول.","الصفان متساويان في التجانس":"تساوي المتوسط لا يعني تساوي التجانس، فالتجانس يُحكم عليه بالانحراف المعياري، وهو 3 مقابل 12.","الصف الثاني أعلى تحصيلاً":"التحصيل يُقارن بالمتوسط وهو 70 في الصفين، والانحراف الأكبر في الصف الثاني يدل على تشتت لا على تفوق."},"e":"الانحراف المعياري يقيس التشتت حول المتوسط؛ وصغره يعني تقارب الدرجات (تجانس)."},"tmat34":{"w":{"7":"7 عدد الفئة 80 إلى 89 وحدها، والمطلوب 70 فأكثر، فيُضاف إليها 11 من الفئة 70 إلى 79.","11":"11 عدد الفئة 70 إلى 79 وحدها، والمطلوب 70 فأكثر، فيُضاف إليها 7 من الفئة 80 إلى 89.","22":"22 عدد من حصلوا على أقل من 70 (10 + 12)، والمطلوب 70 فأكثر: 11 + 7 = 18."},"e":"الطلاب في 70 إلى 79 عددهم 11، وفي 80 إلى 89 عددهم 7؛ المجموع = 18."},"1eorapr":{"w":{"68%":"68% تقع بين 40 و 60 أي ضمن انحراف واحد في الجهتين، والمطلوب من 50 إلى 60 فقط، فهو نصفها 34%.","16%":"16% نسبة من تزيد درجاتهم على 60، والمطلوب من يقعون بين المتوسط 50 وانحراف واحد فوقه.","50%":"50% نسبة كل من فوق المتوسط 50، والفترة من 50 إلى 60 جزء منهم فقط يساوي 34%."},"e":"الفترة من المتوسط إلى انحراف واحد فوقه تضم نصف الـ68% أي 34%."},"1lyy9vo":{"w":{"العربي لأن درجته الخام أعلى":"الدرجة الخام لا تكفي للمقارنة بين مادتين، فدرجته المعيارية في العربي (80 − 70) ÷ 10 = 1 فقط مقابل 3 في الرياضيات.","المادتين بالتساوي":"التساوي يتطلب درجتين معياريتين متساويتين، وهنا ز العربي 1 وز الرياضيات (65 − 50) ÷ 5 = 3.","لا يمكن الحكم دون الدرجة الكلية":"الدرجة المعيارية تُحسب من درجة الطالب ومتوسط المادة وانحرافها، وكلها معطاة، فتُقارن المادتان دون الحاجة إلى الدرجة الكلية."}},"1stgjh0":{"w":{"العلاقة قوية بين المادتين":"الارتباط القوي ما زاد على 0.7، و 0.2 أقل من 0.3، فتُعد العلاقة ضعيفة.","الاختبارات تمتاز بالصدق والثبات":"ارتباط درجات اختبارين مختلفين يصف العلاقة بينهما فقط، ولا يدل وحده على صدق أي منهما أو ثباته.","الاختباران شديدا السهولة":"السهولة تُعرف من معامل الصعوبة أي نسبة المصيبين، لا من معامل الارتباط بين درجات الاختبارين."},"e":"0.2 قيمة منخفضة تدل على ارتباط ضعيف."},"1bbe389":{"w":{"صفر و1":"من صفر إلى 1 مدى معامل الثبات، أما الارتباط فيشمل القيم السالبة للعلاقة العكسية حتى −1.","صفر و100":"الارتباط لا يُعبَّر عنه بنسبة مئوية من 100، بل بقيمة بين −1 و +1 تحدد إشارتها الاتجاه.","−100 و+100":"القيم ±100 تتجاوز الحد الممكن، فأقصى ارتباط تام قيمته 1 طردياً أو −1 عكسياً."}},"1o713f0":{"w":{"أدنى من المتوسط بانحراف ونصف":"الدرجة التائية فوق 50 تعني موقعاً فوق المتوسط، و 65 أكبر من 50 فهو أعلى منه لا أدنى.","عند المتوسط تماماً":"الطالب يكون عند المتوسط حين تكون درجته التائية 50، ودرجته 65 تزيد عليها 15، أي انحرافاً ونصفاً.","أعلى من المتوسط بـ 65 درجة":"65 هي الدرجة التائية نفسها لا المسافة عن المتوسط، والمسافة (65 − 50) ÷ 10 = 1.5 انحراف معياري."}},"aamee1":{"w":{"إبراز جهود المعلم والمدرسة":"التقرير موجه لخدمة تعلم الطالب، فيركز على مستواه وحاجاته، لا على عرض ما قدمه المعلم والمدرسة.","تحقيق مبدأ الثواب والعقاب":"نتائج التقويم لا تُستخدم أداة عقاب، والتقرير وسيلة شراكة مع الأسرة لدعم الطالب فيما يحتاجه.","مقارنة الطالب بالمتفوقين في صفه":"تقرير ولي الأمر يبين مستوى الطالب وتقدمه بلا مقارنة بالآخرين، فالمقارنة لا تكشف ما يحتاجه هو من دعم."},"e":"التقرير وسيلة شراكة مع الأسرة لدعم تعلم الطالب، فيركز على مستواه وتقدمه وحاجاته."},"17puof1":{"w":{"تعديل خطة التدريس وأساليبه":"تعديل التدريس استخدام مشروع، فالمعلم يحلل النتائج ليعرف مواطن الضعف ثم يغير طريقته لعلاجها.","تصنيف الطلاب لبرامج علاجية وإثرائية":"التصنيف هنا لتقديم الدعم المناسب: علاج لمن أخفق في مهارة وإثراء لمن أتقن، وهو من توظيف النتائج السليم.","إعداد تقارير لأولياء الأمور":"التقرير لولي الأمر توظيف مشروع للنتائج، يبين مستوى الطالب وتقدمه وحاجاته ليشارك الأسرة في دعمه."},"e":"نتائج التقويم أداة تحسين وتوجيه لا أداة عقاب؛ فالحرمان لا يعالج الضعف بل يزيد النفور."},"e8kqva":{"w":{"لائحة السلوك والمواظبة":"تنظم سلوك الطلاب وانضباطهم داخل المدرسة، ولا تجرّم الجرائم الإلكترونية العامة كالابتزاز والتشهير عبر الشبكة.","لائحة الوظائف التعليمية":"لائحة الوظائف تنظم وظائف المعلمين ورتبهم ومهامهم، وليست نظاماً جزائياً يجرّم التنصت والابتزاز عبر الشبكة.","ميثاق أخلاقيات مهنة التعليم":"الميثاق يحدد أخلاقيات المعلم وواجباته المهنية، وليس نظاماً جزائياً يجرّم الجرائم الإلكترونية ويحدد عقوباتها."},"e":"نظام مكافحة الجرائم المعلوماتية (1428هـ) هو المرجع الجزائي للجرائم الإلكترونية."},"rdh5fr":{"w":{"يرجح رأيه الشخصي ويطلب من الطلاب الالتزام به":"فرض الرأي الشخصي في مسألة خلافية يخالف الحياد الذي تطلبه أخلاقيات المهنة، والمطلوب بيان الخلاف والإحالة إلى المختصين.","يرفض الإجابة ويطلب عدم إثارة مثل هذه الأسئلة":"الرفض يقمع سؤال الطالب ويغلق باب الحوار، والمطلوب أن يبين أن المسألة خلافية ويحيله إلى المصادر الموثوقة.","يفتح نقاشاً مفتوحاً ليصوّت الطلاب على الرأي الأصح":"التصويت يجعل الحكم الشرعي بالأغلبية، والمسائل الفقهية تُرجع إلى العلماء والجهات المختصة لا إلى رأي الطلاب."},"e":"الحياد في القضايا الخلافية من أخلاقيات المهنة."},"x8zvns":{"w":{"يعاقب الساخرين أمام زملائهم ليكونوا عبرة":"العقاب العلني يمس كرامة الطلاب ويخالف الميثاق، ولا يعلّمهم أن تنوع اللهجات ثراء لوطن واحد.","يطلب من الطالب تغيير لهجته ليندمج مع زملائه":"طلب تغيير اللهجة يحمّل الطالب الضحية المسؤولية، ويجعل تنوع اللهجات عيباً بدل أن يكون ثراءً وطنياً.","يتجاهل الموقف لأنه مزاح أطفال":"التجاهل يترك السخرية قائمة ويضيّع فرصة تحويل الموقف إلى درس في وحدة الوطن مع تنوع مناطقه."},"e":"الهوية الوطنية الجامعة تُبنى بتحويل الموقف إلى درس في وحدة الوطن مع تنوعه."},"192v77t":{"w":{"يثني على تدينه ويطلب من زملائه الاقتداء به":"الثناء هنا يعزز الغلو في الحكم على الزملاء، والمطلوب معالجته بالحوار والدليل وبيان سماحة الإسلام ووسطيته.","يمنعه من الحديث في الدين داخل الصف":"المنع قمع يغلق باب الحوار ولا يعالج فكرة التشدد، والغلو يُعالج بالحوار والأدلة والقدوة.","يحيله مباشرة إلى المرشد الطلابي دون حوار":"الإحالة قبل أي حوار تخطٍّ لدور المعلم، فمعالجة الغلو بالحوار والدليل والقدوة دوره هو أولاً."},"e":"الغلو يُعالج بالحوار والدليل والقدوة، وهو دور المعلم أولاً."},"xr8m21":{"w":{"قصر التعليم على المسار الأكاديمي":"قصر التعليم على مسار واحد يعاكس هدف الرؤية في مواءمة مخرجات التعليم مع احتياجات سوق العمل.","إلغاء التعليم الأهلي":"الرؤية تتجه إلى توسيع شراكة المجتمع والقطاع الخاص في التعليم، وإلغاء التعليم الأهلي يعاكس هذا الاتجاه.","تقليص مراحل التعليم العام":"أهداف الرؤية في التعليم تدور حول جودة المخرجات والتعلم مدى الحياة، ولا تتضمن تقليص مراحل التعليم العام."},"e":"الرؤية تستهدف جودة المخرجات وربطها بسوق العمل وتنمية الشراكة المجتمعية والتعلم مدى الحياة."},"18chi1t":{"w":{"برنامج جودة الحياة":"برنامج جودة الحياة يعنى بتحسين نمط حياة الفرد بالثقافة والرياضة والترفيه، لا ببناء قدراته منذ الطفولة المبكرة.","برنامج التحول الوطني":"برنامج التحول الوطني يركز على تطوير العمل الحكومي ورفع كفاءته، لا على إعداد المواطن بالقيم والمهارات منذ الطفولة.","برنامج الإسكان":"برنامج الإسكان يستهدف رفع نسبة تملك الأسر السعودية للمساكن، ولا يُعنى ببناء القيم والمهارات والتعلم مدى الحياة."},"e":"برنامج تنمية القدرات البشرية هو المعني بإعداد مواطن تنافسي عالمياً بالقيم والمعارف والمهارات."},"1hs3gtf":{"w":{"الالتزام بالأنظمة واللوائح":"ورد القول في الميثاق عند الحديث عن التفاعل مع الثقافات الأخرى، ومعناه أخذ الحكمة من أي مصدر لا الالتزام بالأنظمة.","العدل بين الطلاب":"العدل بين الطلاب إنصافهم في التعامل والتقويم دون تحيز، والقول أورده الميثاق في سياق التفاعل الإيجابي مع الثقافات الأخرى.","التطوير المهني الذاتي":"قد يبدو قريباً لأنه عن طلب المعرفة، لكن الميثاق أورده في سياق التفاعل الإيجابي مع الثقافات الأخرى لا التطوير المهني."}},"3vkv5y":{"w":{"يطلب منه الاقتصار على ما ورد في المنهج":"الاقتصار على المنهج يغلق فرصة التفاعل الإيجابي مع ثقافة زميلهم، والمطلوب إتاحة الحديث باختصار مع تأكيد الثوابت.","يؤجل سؤاله إلى ما بعد الحصة ولا يعود إليه":"التأجيل دون عودة تجاهل لسؤال الطالب، ويضيّع فرصة تعليم احترام الثقافات الأخرى في سياق الدرس نفسه.","يحوّل الحديث إلى نقد عادات بلده":"نقد عادات بلد الطالب إساءة له ولثقافته، ويناقض التفاعل الإيجابي واحترام الثقافات الذي ينص عليه المعيار."},"e":"التفاعل الإيجابي مع الثقافات مع الحفاظ على الثوابت هو جوهر التنوع الثقافي في المعيار."},"10hvt2e":{"w":{"اللوائح الإدارية للمدرسة":"اللوائح الإدارية تنظم الإجراءات والعمل داخل المدرسة، أما القدوة فنص في الميثاق ضمن القيم والأخلاقيات.","متطلبات التطوير المهني":"التطوير المهني يعني تنمية المعلم لمعارفه ومهاراته، أما القدوة فسلوك أخلاقي نص عليه الميثاق في مادة المعلم وطلابه.","مبادئ الشراكة المجتمعية":"الشراكة المجتمعية تعاون المدرسة مع الأسرة والمجتمع، أما القدوة ولو للمجتمع فقيمة أخلاقية في سلوك المعلم نفسه."}},"1q1uj4r":{"w":{"لائحة الوظائف التعليمية":"لائحة الوظائف تنظم وظائف المعلمين ورتبهم ومهامهم، أما غرس الاعتدال ونبذ الغلو فبند أخلاقي في الميثاق.","لائحة السلوك والمواظبة":"قواعد السلوك تذكر الاعتدال الفكري في دور المعلم أيضاً، لكن العبارة الموصوفة هنا بند في مادة «المعلم وأداؤه المهني» من الميثاق.","قواعد القبول والتسجيل":"قواعد القبول والتسجيل تنظم شروط قبول الطلاب وتسجيلهم في المدارس، ولا صلة لها بغرس الاعتدال والتحذير من التطرف."},"e":"مادة «المعلم وأداؤه المهني» في الميثاق تنص على أن المعلم يغرس مبدأ الاعتدال والتسامح والتعايش بعيداً عن الغلو والتطرف."},"1t37q4e":{"w":{"العلم الوطني":"العلم رمز وطني جامع ورد ضمن رموز الهوية السعودية، بخلاف شعار المدرسة الخاص بمؤسسة واحدة.","النشيد الوطني":"النشيد من رموز الهوية الوطنية التي تجمع المملكة كلها، فهو منها وليس الاستثناء المطلوب.","يوم التأسيس":"هذه المناسبة تحيي ذكرى قيام الدولة السعودية الأولى، وهي من رموز الهوية الوطنية لا الاستثناء."}},"1gq8dme":{"w":{"يعرض رأيه الشخصي بصراحة":"عرض الرأي الشخصي في قضية سياسية خلافية يخالف الحياد الواجب، والمدونة تطلب تجنب الدخول في نقاشات حولها.","يسمح بنقاش مفتوح بين الطلاب حول القضية":"النقاش المفتوح في قضية خلافية يحوّل الصف إلى ساحة جدل، والمدونة تنص على تجنب الدخول في نقاشات حولها.","يسخر من الطرف الذي يخالفه":"السخرية تخرق الحياد وتسيء إلى طرف في القضية، وتناقض القدوة والتسامح المطلوبين من المعلم."},"e":"الحياد في القضايا الخلافية واجب مهني، والتوجيه للمصادر الرسمية يحمي الطلاب من التضليل."},"1o1gob8":{"w":{"مصادرة الهواتف جميعاً وإتلاف المقطع":"مصادرة الهواتف وإتلاف ما فيها من مواد ممنوعة ليسا قرار المعلم منفرداً، بل إجراء للجنة التوجيه الطلابي بعد الإحالة وبمحضر.","تجاهل الأمر لأنه حدث خارج الحصة":"التجاهل يترك الضرر قائماً والمقطع مستمراً في الانتشار، والأولوية هنا حماية الطالب المتضرر بإيقاف التداول فوراً.","معاقبة من صوّر المقطع أمام زملائه":"العقاب أمام الزملاء يمس كرامة الطالب ويخالف الميثاق، ولا يوقف انتشار المقطع ولا يحمي الطالب المتضرر."},"e":"أول ما يفعله المعلم حماية الطالب المتضرر بإيقاف الانتشار فوراً مع توعيتهم بأن ذلك جريمة معلوماتية، ثم إبلاغ الموجه الطلابي (المرشد سابقاً) والإدارة."},"13agsh4":{"w":{"ارتداء الزي التراثي دون محتوى معرفي":"الزي التراثي مظهر احتفالي، وبلا محتوى معرفي لا يبني فهماً لتاريخ الدولة ولا انتماءً عميقاً كما يفعل المشروع البحثي.","حفظ تاريخ الحدث لاختبار قصير":"تاريخ الحدث معلومة مجردة يستظهرها الطالب للاختبار، فلا يبني معرفته بنفسه ولا يربطها بالشواهد.","عرض مقطع مرئي دون مناقشة":"العرض دون مناقشة يجعل الطالب متلقياً صامتاً، فلا يبحث ولا يربط ما يراه بشواهد تبني انتماءه."},"e":"المشروع يجعل الطالب يبني المعرفة بنفسه ويربطها بالشواهد."},"bwy1rh":{"w":{"لائحة الوظائف التعليمية":"لائحة الوظائف تنظم وظائف المعلمين ورتبهم ومهامهم، ولا تتناول بنص مباشر احترام الشعوب والثقافات الأخرى.","قواعد الانضباط الصفي":"قواعد الانضباط الصفي تنظم سلوك الطلاب وإدارة الصف، والمخالفة هنا من المعلم نفسه وتمس قيمة التسامح في الميثاق.","تعليمات الأنشطة غير الصفية":"تعليمات الأنشطة غير الصفية تنظم البرامج خارج الحصة، والسلوك هنا داخل الصف ويناقض قيم التسامح في الميثاق."},"e":"الازدراء يناقض الوسطية والتسامح المنصوص عليهما في الميثاق."},"1nbmvic":{"w":{"تجاهل حديثهم لأنه خارج المنهج":"التجاهل يترك تشكيكهم دون جواب، والمراهق يحتاج حواراً بالشواهد يوجهه إلى قنوات التعبير النظامية.","التهديد بالإبلاغ عنهم":"التهديد يقطع الثقة بين المعلم وطلابه ويغلق باب الحوار، فيبقى التشكيك قائماً دون أن يُعالج بالحقائق.","مجاراتهم في النقد لكسب ثقتهم":"المجاراة في النقد تخل بحياد المعلم وقدوته، وكسب الثقة يكون بالحوار الهادئ والشواهد لا بموافقتهم."},"e":"المراهق يحتاج حواراً بالشواهد وتوجيهاً إلى القنوات النظامية، وهذا جوهر تعزيز الهوية."},"4pydv5":{"w":{"المحاكمة العقلية":"المحاكمة العقلية مناقشة منظمة يوازن فيها الطلاب أدلة طرفين حتى يصلوا إلى حكم، والمعلم هنا رد بسؤال قصير فقط.","التلقين المباشر للقيمة":"التلقين يفرض القيمة على الطالب من الخارج، والمعلم هنا لم يحكم ولم يعظ بل سأله ليفكر بنفسه.","لعب الأدوار":"لعب الأدوار تمثيل الطلاب لموقف يتقمصون فيه شخصيات، ولم يحدث تمثيل هنا بل سؤال قصير على عبارة الطالب."},"e":"الاستجابة الموضحة سؤال قصير يرد به المعلم على عبارة الطالب، فيدفعه إلى التفكير في قيمته بنفسه دون وعظ أو حكم، وهي من أساليب مدخل توضيح القيم (راث وهارمن وسايمون)."},"1xuirj2":{"w":{"الاستجابة الموضحة":"الاستجابة الموضحة سؤال قصير يرد به المعلم على عبارة طالب واحد، والمعلم هنا نظّم فريقين يوازنان الأدلة.","القصة الهادفة":"القصة الهادفة أسلوب غير مباشر ينقل القيمة عبر أحداث وشخصيات، ولا يقوم على عرض الأدلة والموازنة بينها كما حدث هنا.","القدوة الحسنة":"القدوة تعليم للقيمة بسلوك المعلم العملي، أما هنا فالطلاب عرضوا أدلة فريقين ووازنوا بينها حتى بلغوا حكماً."},"e":"المحاكمة العقلية تعرض قضية قيمية، ويناقش الطلاب الأدلة المؤيدة والمعارضة حتى يصلوا إلى حكم مسبَّب، وتناسب المرحلة الثانوية لأنها تتطلب تفكيراً مجرداً."},"1ior0l4":{"w":{"تعليق صور المعالم التراثية على جدار الفصل طوال الفصل الدراسي دون نقاش":"تعليق الصور دون نقاش عرض سلبي للتراث تمر عليه الطالبات، ولا يعشن فيه خبرة نشطة تبني اعتزازهن به.","إلقاء محاضرة مفصلة عن أهمية التراث الوطني في نهاية الحصة":"المحاضرة تنقل معلومات عن التراث والطالبات مستمعات فقط، فلا تتحقق الخبرة النشطة التي يطلبها مؤشر الممارس.","توزيع مطوية جاهزة عن التراث تقرؤها الطالبات في المنزل":"المطوية الجاهزة قراءة فردية في المنزل خارج الدرس، فلا تشارك الطالبات في توثيق التراث ولا عرضه بأنفسهن."},"e":"مؤشر 1.2 للممارس يطلب توظيف خبرات ومواقف وأنشطة تعليمية تدعم الاعتزاز بالتراث؛ المقابلة والتوثيق والعرض خبرة نشطة يبني فيها الطالب الاعتزاز بنفسه."},"1xwtdxv":{"w":{"توحيد المملكة العربية السعودية وإعلان اسمها على يد الملك عبدالعزيز عام 1351هـ":"ذكرى التوحيد وإعلان اسم المملكة هي اليوم الوطني في 23 سبتمبر، لا يوم التأسيس في 22 فبراير.","اعتماد العلم الوطني بشكله الحالي":"للعلم مناسبة خاصة هي يوم العلم في 11 مارس، أما 22 فبراير فذكرى تأسيس الدولة السعودية الأولى.","دخول الملك عبدالعزيز الرياض واستردادها عام 1319هـ":"استرداد الرياض عام 1319هـ بداية تأسيس الدولة السعودية الثالثة، ويوم التأسيس يعود إلى الدولة الأولى عام 1139هـ."},"e":"يوم التأسيس (22 فبراير) لذكرى تأسيس الدولة السعودية الأولى عام 1139هـ (1727م)."},"q8s8cz":{"w":{"الهدف السلوكي":"الهدف السلوكي يصف ما يُتوقع أن يؤديه الطالب بعد التعلم، والسؤال عن دليل على ممارسة المعلم نفسه للمعيار.","الكفاية":"الكفاية قدرة مركبة يمتلكها المعلم، والسؤال عن الدليل الملاحظ المقيس الذي يثبت تحقق المعيار في ممارسته.","الرتبة المهنية":"الرتبة المهنية مستوى وظيفي في لائحة الوظائف التعليمية كممارس ومتقدم وخبير، لا دليلاً على تحقق معيار في الممارسة."},"e":"المعيار عبارة عامة عمّا يجب أن يعرفه المعلم ويؤديه، والمؤشر دليل قابل للقياس على تحققه."},"10m3w6l":{"w":{"1427هـ":"عام 1427 هو سنة صدور ميثاق أخلاقيات مهنة التعليم، أما وثيقة السياسة فتشتهر بعام 1390 وقرارها في 1389.","1440هـ":"عام 1440 هو سنة صدور لائحة الوظائف التعليمية، ووثيقة السياسة أقدم منها بنصف قرن، إذ تشتهر بعام 1390.","1373هـ":"عام 1373 هو عام إنشاء وزارة المعارف، ووثيقة السياسة جاءت بعده بقرار مجلس الوزراء 779 عام 1389."},"e":"اعتُمدت وثيقة سياسة التعليم بقرار مجلس الوزراء رقم 779 وتاريخ 16/9/1389هـ، وتشتهر في المراجع التربوية بأنها صدرت عام 1390هـ، وهو الأقرب بين البدائل."},"2bduhh":{"w":{"1390هـ":"عام 1390 تشتهر به وثيقة سياسة التعليم، أما ميثاق أخلاقيات المهنة فصدر بعدها بعقود في عام 1427.","1440هـ":"عام 1440 صدرت فيه لائحة الوظائف التعليمية، والميثاق أسبق منها، إذ صدر في عام 1427.","1428هـ":"عام 1428 صدر فيه نظام مكافحة الجرائم المعلوماتية، والميثاق صدر قبله بعام واحد، فلا تخلط بينهما."},"e":"الميثاق صدر عام 1427هـ."},"133ivtl":{"w":{"50 فأعلى":"درجة 50 هي بداية مستوى ممارس الذي يمتد إلى 69، أما رخصة متقدم فتبدأ من 70 في الاختبارين معاً.","80 فأعلى":"درجة 80 فأكثر هي حد رخصة خبير، وهو المستوى الأعلى، أما متقدم فيكفيه من 70 إلى 79.","60 فأعلى":"درجة 60 تقع داخل مدى مستوى ممارس الممتد من 50 إلى 69، فلا تكفي لمتقدم الذي يبدأ من 70."}},"4gyypv":{"w":{"ثلاث سنوات":"ثلاث سنوات هي مدة تقويم الأداء المشترطة للترقية، أما صلاحية الرخصة فخمس سنوات من إصدارها أو ترقيتها أو تجديدها.","عشر سنوات":"عشر سنوات ضعف مدة الصلاحية المقررة، فالرخصة تسري خمس سنوات ثم تحتاج إلى تجديد.","سنتان":"سنتان هي مدة التجربة للمعيّن ابتداءً على الوظائف التعليمية، لا مدة صلاحية الرخصة التي تبلغ خمس سنوات."}},"4yh5av":{"w":{"اجتياز الاختبار بأي درجة وموافقة مدير المدرسة":"الترقية تحتاج رخصة بمستوى الرتبة المطلوبة لا أي درجة، فمتقدم يتطلب 70 في الاختبارين، وموافقة المدير ليست من شروط المادة 10.","حضور عدد محدد من الدورات التدريبية فقط":"نقاط التطوير المهني شرط واحد من أربعة شروط مجتمعة، وكلمة «فقط» تُسقط الرخصة وتقويم الأداء وسنوات الرتبة.","تزكية من المشرف التربوي":"التزكية ليست من شروط المادة 10، فالترقية تقوم على شروط محددة: الرخصة ونقاط التطوير وتقويم الأداء ومدة الرتبة."}},"15mu7u5":{"w":{"الدورات التدريبية التي تقيمها إدارة التعليم":"الدورات وسيلة من وسائل التطوير، والتعريف يجعله عملية منظمة مستمرة مرتبطة بالمعايير المهنية لا مجرد دورات تقيمها جهة واحدة.","ما يحصل عليه المعلم من مؤهلات أكاديمية":"المؤهل الأكاديمي شهادة يحصل عليها المعلم، والتطوير المهني في التعريف عملية مستمرة لتنمية معارفه ومهاراته وفق المعايير المهنية.","تقويم الأداء الوظيفي السنوي":"تقويم الأداء قياس سنوي لعمل المعلم يُعتمد في الترقية، أما التطوير المهني فعملية لتنمية المعارف والمهارات لا لقياسها."}},"1bm0xel":{"w":{"سنة":"مدة التجربة في لائحة الوظائف التعليمية سنتان لا سنة، يُقوَّم المعيّن خلالهما مرة على الأقل قبل ثبوت صلاحيته.","ستة أشهر":"ستة أشهر أقل بكثير من مدة التجربة المقررة، فاللائحة تجعلها سنتين يُقوَّم فيهما المعلم مرة على الأقل.","ثلاث سنوات":"ثلاث سنوات أطول من المدة المقررة، فالمعيّن ابتداءً يبقى تحت التجربة سنتين، وإن لم تثبت صلاحيته خلالهما تنتهي خدمته."}},"yxvcd5":{"w":{"أربع سنوات":"أربع سنوات هي مدة الرتبة لحامل الدكتوراه، أما حامل البكالوريوس فيحتاج ست سنوات في رتبته قبل الترقية.","سبع سنوات":"سبع سنوات أكثر من المدة المقررة، فالمادة 10 تشترط لحامل البكالوريوس ست سنوات، وتنقص سنة عند الترقية من متقدم إلى خبير.","ثلاث سنوات":"ثلاث سنوات هي مدة تقويم الأداء المطلوبة للترقية، لا سنوات الرتبة التي تبلغ ست سنوات لحامل البكالوريوس."},"e":"تشترط المادة 10 من لائحة الوظائف التعليمية لحامل البكالوريوس ست سنوات في رتبته قبل ترقيته (5 للماجستير و4 للدكتوراه)، وتُخفض كل مدة سنة واحدة عند الترقية من متقدم إلى خبير."},"zw5zpu":{"w":{"المرشد الطلابي":"المرشد، واسمه اليوم الموجه الطلابي، من منسوبي المدرسة الذين يطبّقون القواعد، أما تسليم النسخة والتوقيع بالعلم فللطالب وولي أمره.","معلم الفصل":"معلم الفصل يوقّع بالاطلاع على دوره في تطبيق القواعد، أما النسخة التي يُوقَّع على استلامها بالعلم فتُسلَّم لولي الأمر مع الطالب.","وكيل شؤون الطلاب":"وكيل شؤون الطلاب من منسوبي المدرسة المسؤولين عن تطبيق القواعد، والقواعد تنص على تسليم النسخة لولي الأمر وأخذ توقيعه بالعلم."},"e":"تنص قواعد السلوك والمواظبة على إطلاع الطلبة وأولياء أمورهم على القواعد وتسليمهم نسخة منها وأخذ توقيعهم بذلك وفق نموذج الالتزام المدرسي، ويُجدد في بداية كل عام دراسي."},"1xy87f4":{"w":{"داخل أسوار المدرسة فقط":"القواعد تمتد خارج الأسوار إلى الحافلات والأنشطة الخارجية والشوارع المحاذية للمدرسة، فحصرها في داخل المدرسة يضيّق نطاقها.","في أي مكان خارج المدرسة":"نطاق القواعد خارج المدرسة محدد بأنشطتها وحافلاتها والشوارع المحاذية لها إذا رصدها منسوبوها، لا أي مكان يذهب إليه الطالب.","في حافلة النقل المدرسي فقط":"الحافلة المدرسية من نطاق القواعد فعلاً، لكن كلمة «فقط» تُخرج داخل المدرسة والأنشطة الخارجية والشوارع المحاذية لها."},"e":"تنص المادة 28 من قواعد السلوك والمواظبة 1447 على تطبيقها على ما يقع داخل المدرسة، وفي التعليم الإلكتروني، والبرامج والأنشطة خارجها، وحافلات النقل المدرسي، وفي حدود المدرسة (الشوارع المحاذية لها) إذا رصده منسوبو المدرسة أو كاميراتها. وهذا النطاق لطلاب جميع المراحل في قواعد 1447، وذكر المتوسطة والثانوية في السؤال من صياغة الإصدارات السابقة."},"1u5bt2c":{"w":{"واجب النمو المهني":"النمو المهني واجب يخص تطوير المعلم لعلمه ومهارته، والخطأ هنا ليس إهمالاً للتعلم بل إفشاء أسرار أسرة الطالب.","العمل بروح الفريق":"روح الفريق تحكم علاقة المعلم بزملائه وإدارته، والمخالفة هنا تمس الطالب وأسرته بإفشاء معلومات خاصة عنهم.","التعاون مع المجتمع المحلي":"التعاون مع المجتمع المحلي واجب في الانفتاح عليه وخدمته، والمشكلة هنا ليست ضعف تعاون بل إفشاء سر أسرة الطالب في مجلس عام."},"e":"الميثاق يلزم المعلم بأن يصون كرامة طلابه (المادة 5، البند 5)، ومدونة السلوك 1447 توجب التعامل مع المعلومات الشخصية للطلاب بسرية تامة وتحظر إفشاء ما فيه خصوصية."},"5lg759":{"w":{"العقاب البدني جائز إذا كان خفيفاً":"الميثاق لا يفرّق بين عقاب بدني خفيف وشديد، فالمربي القدير يتجنب العقاب البدني كله لأنه ينفّر الطالب من المدرسة.","العقاب النفسي مقبول بديلاً عن البدني":"نص الميثاق يذكر العقاب البدني والنفسي معاً ويرفضهما، فإبدال أحدهما بالآخر لا يُخرج المعلم من المخالفة.","يحق للمعلم اختيار أسلوب العقاب بحرية":"أسلوب العقاب ليس حرية مطلقة للمعلم، فالميثاق يطلب منه تجنب العقاب البدني والنفسي معاً لأنهما ينفّران الطالب من المدرسة."},"e":"الميثاق يرفض العقاب البدني والنفسي معاً."},"hfcux0":{"w":{"المعلم وطلابه":"مادة المعلم وطلابه تتناول العدل بينهم وصون كرامتهم وتجنب العقاب البدني والنفسي، أما الشراكة مع الوالدين فموضعها مادة المعلم والأسرة.","المعلم والمجتمع المدرسي":"مادة المجتمع المدرسي تخص علاقة المعلم بزملائه وإدارته بالثقة وروح الفريق، والبند هنا عن شراكته مع الوالدين في التربية.","المعلم وأداؤه المهني":"مادة المعلم وأداؤه المهني تتناول قدوته ونموه المهني وصدقه وأمانته ورقابته الذاتية، ولا تتناول علاقته بالوالدين التي يخصها هذا البند."}},"wij3bi":{"w":{"المنافسة على التميز":"المنافسة الفردية تناقض ثقافة التعاون التي يقوم عليها المجتمع المدرسي، والميثاق يجعل الأساس الثقة المتبادلة وروح الفريق.","الالتزام الرسمي بالمراسلات":"المراسلات الرسمية وسيلة تنظيمية للتواصل الإداري، أما أساس العلاقة في الميثاق فقيمة أخلاقية هي الثقة المتبادلة وروح الفريق.","التسلسل الإداري الصارم":"التسلسل الإداري يحدد مرجعية القرار، لكن الميثاق يبني علاقة المعلم بالإدارة على الثقة والعمل المشترك لا على الصرامة."},"e":"مادة المعلم والمجتمع المدرسي تنص على الثقة وروح الفريق."},"bzhfge":{"w":{"حق المعلم في التظلم من القرارات":"التظلم حق مشروع وهو القناة الصحيحة للاعتراض، والمعلم هنا لم يتظلم بل امتنع عن التنفيذ، فخالف الالتزام بالأنظمة.","مبدأ التطوير المهني الذاتي المستمر":"التطوير المهني يخص نمو معارف المعلم ومهاراته، ورفض التعميم لعدم الاقتناع مسألة التزام بالتعليمات الرسمية لا مسألة تطوير.","قواعد ضبط الصف وإدارته":"قواعد ضبط الصف تنظم سلوك الطلاب داخل الحصة، والمخالفة هنا من المعلم نفسه تجاه تعميم رسمي من الوزارة."},"e":"الميثاق يعد احترام قواعد السلوك الوظيفي والالتزام بالأنظمة ركناً أساسياً."},"1xgg3bn":{"w":{"إعداد الطالب لمتطلبات سوق العمل فقط":"ربط التعليم بسوق العمل من توجهات رؤية 2030، أما الغاية في الوثيقة فتبدأ بفهم الإسلام وغرس العقيدة ثم القيم والمعارف والمهارات.","حفظ المقررات الدراسية واستظهارها":"الحفظ والاستظهار وسيلة تعلم محدودة لا غاية، والوثيقة تجعل الغاية فهم الإسلام وغرس العقيدة وتزويد الطالب بالقيم والمعارف والمهارات.","تخريج أكبر عدد ممكن من الطلاب":"عدد الخريجين مؤشر كمي لا غاية تربوية، والغاية في الوثيقة نوعية تبدأ بفهم الإسلام فهماً صحيحاً متكاملاً وغرس العقيدة."},"e":"الغاية في المادة 28 تبدأ بفهم الإسلام وغرس العقيدة ثم القيم والمعارف والمهارات."},"1mrpk6q":{"w":{"ابتدائي خمس ومتوسط أربع وثانوي ثلاث":"مجموع السنوات هنا 12 لكن التوزيع خطأ، فالابتدائي في الوثيقة ست سنوات والمتوسط ثلاث، لا خمس وأربع.","ابتدائي ست ومتوسط ثلاث وثانوي أربع":"الابتدائي والمتوسط صحيحان، لكن الثانوي ثلاث سنوات لا أربع، فيصير السلم 13 صفاً بدل 12.","ابتدائي أربع ومتوسط أربع وثانوي أربع":"التقسيم المتساوي يعطي 12 صفاً أيضاً، لكن الوثيقة تجعل الابتدائي ست سنوات ثم ثلاثاً للمتوسط وثلاثاً للثانوي."}},"nu12sh":{"w":{"مبدأ الشراكة المجتمعية":"الشراكة المجتمعية تخص علاقة المدرسة بالأسرة والمجتمع، ومشكلة المعلم هنا مواظبته على وقت حصصه، وهي من قواعد السلوك الوظيفي.","متطلبات البحث الإجرائي":"البحث الإجرائي أداة لدراسة مشكلة صفية وحلها، ولا صلة له بحضور المعلم في وقته وبقائه حتى نهاية الحصة.","تنمية الهوية الوطنية":"تنمية الهوية الوطنية هدف تربوي لبناء انتماء الطلاب، أما التأخر عن الحصة والخروج قبل نهايتها فإخلال بالمواظبة الوظيفية."}},"g8syao":{"w":{"اختيارية لجميع المعلمين على رأس العمل":"التعديل جعل الرخصة شرطاً لمزاولة المهنة، والإعفاء خاص بمن بلغ الخمسين قبل فبراير 2026، فلا تكون اختيارية لجميع المعلمين.","مطلوبة للترقية بين الرتب فقط":"الرخصة شرط للترقية فعلاً، لكن التعديل جعلها شرطاً لمزاولة التعليم نفسه، فكلمة «فقط» تجعلها أضيق من حكمها.","مرتبطة باستحقاق العلاوة السنوية":"ربط الرخصة بالعلاوة ألغاه هذا التعديل نفسه، وجعلها بدلاً من ذلك شرطاً لمزاولة المهنة من فبراير 2026."}},"1acq2ku":{"w":{"عملاً تطوعياً اختيارياً":"الميثاق يعد المشاركة في نشاطات المدرسة ركناً أساسياً بجانب الالتزام بالأنظمة، فلا تبقى أمراً تطوعياً يتركه المعلم متى شاء.","من صلاحيات رائد النشاط وحده":"رائد النشاط ينظّم النشاطات ويشرف عليها، لكن الميثاق يجعل المشاركة فيها واجباً على كل معلم لا اختصاصاً لشخص واحد.","مرتبطة بالمكافآت فقط":"ربط المشاركة بالمكافأة يجعلها مقابلاً مادياً، والميثاق يعدها ركناً في تحقيق أهداف المؤسسة التعليمية يؤديه المعلم ضمن رسالته."}},"wy2uad":{"w":{"فرض رسوم دراسية على جميع مراحل التعليم":"فرض الرسوم يناقض المادة 233 من الوثيقة التي تنص على مجانية التعليم، فلا يكون أساساً من أسسها.","إلزامية التعليم الثانوي":"الوثيقة لم تجعل التعليم الثانوي إلزامياً، وحتى نظام 1448 جعل الإلزام من سن 6 إلى 15، فلا يمتد إلى نهاية الثانوي.","اعتماد اللغة الإنجليزية لغة للتدريس":"لغة التعليم في الوثيقة هي العربية، والأسس العامة تبدأ بالإيمان بالله والتصور الإسلامي، لا باختيار لغة أجنبية للتدريس."},"e":"الأسس العامة في الباب الأول من وثيقة السياسة، وأولها (المادة 2) الإيمان بالله رباً وبالإسلام ديناً وبمحمد صلى الله عليه وسلم نبياً ورسولاً، ثم التصور الإسلامي للكون والإنسان والحياة (المادة 3)."},"1ethj1b":{"w":{"بالامتناع عن العمل حتى يُعدَّل":"الامتناع عن العمل مخالفة للسلوك الوظيفي، والاعتراض على التقويم يكون بتظلم رسمي وفق الإجراءات المنظمة له.","عبر وسائل التواصل الاجتماعي":"النشر في وسائل التواصل تشهير يخالف السلوك الوظيفي، والتظلم يُقدَّم للجهة المختصة بإجراءات رسمية لا علناً للناس.","بطلب إعادة التقويم من زميل آخر":"الزميل لا يملك صلاحية إعادة تقويم الأداء، فالتظلم يُقدَّم رسمياً للجهة المختصة وفق إجراءات الإطار التنظيمي."},"e":"اللائحة تنظم التظلم بإجراءات رسمية."},"1a2hodp":{"w":{"شهادة حسن سيرة وسلوك":"شهادة حسن السيرة والسلوك تصدرها المدرسة للطالب ولا علاقة لها بالمخالفة، والمطلوب من ولي الأمر هنا التوقيع على التعهد السلوكي.","طلب نقل الطالب":"طلب النقل معاملة لانتقال الطالب من فصله أو مدرسته، وليس ما يوقّعه ولي الأمر عند المخالفة، وهو التعهد السلوكي بعدم التكرار.","تقويم أداء المعلم":"تقويم أداء المعلم شأن وظيفي بين المعلم وإدارته، ولا صلة له بمخالفة الطالب ولا بما يوقّعه ولي أمره."},"e":"قواعد السلوك والمواظبة 1447 تشرك ولي الأمر في المتابعة: يُشعَر بالمشكلة ويُدعى للاتفاق على خطة تعديل السلوك، ويوقّع مع الطالب ومدير المدرسة نموذج «التعهد السلوكي» بعدم التكرار، ويُوثَّق رفضه إن رفض."},"csj2r":{"w":{"إضاعة وقت الحصة":"ضياع الوقت أثر عابر إن حدث، والسؤال عن الأثر التربوي الأخطر، وهو أن يتعلم الطلاب من قدوتهم الاستهانة بالأنظمة.","إضعاف علاقته بالإدارة":"ضعف العلاقة بالإدارة أثر يخص المعلم نفسه، والسؤال عن الأثر التربوي على الطلاب، وهو فقدانهم القدوة في احترام الأنظمة.","تأخر خطته الدراسية":"تأخر الخطة أثر جانبي في سير المنهج إن حدث، أما الأخطر تربوياً فاهتزاز احترام الطلاب للأنظمة حين يستهين بها قدوتهم."},"e":"المعلم قدوة؛ استهانته بالنظام تُعلّم الطلاب الاستهانة به."},"m8l4b4":{"w":{"النظام مطبق من تاريخ صدور المرسوم الملكي، لا من تاريخ نشره في الجريدة الرسمية":"المادة 68 تحسب مدة النفاذ من تاريخ النشر في الجريدة الرسمية لا من تاريخ المرسوم، ويبدأ العمل بعد 180 يوماً منه.","النظام يُعمل به بعد سنة كاملة من تاريخ النشر":"السنة مدة أخرى تخص الفترة الانتقالية لإقرار بديل الوثائق الملغاة، أما النظام فيُعمل به بعد 180 يوماً من نشره.","النظام لا يُعمل به إلا بعد صدور جميع لوائحه التنفيذية":"المادة 68 ربطت النفاذ بمدة محددة هي 180 يوماً من النشر، ولم تعلّقه على صدور اللوائح التنفيذية."},"e":"تنص المادة 68 على أن النظام يُعمل به بعد 180 يوماً من تاريخ نشره في الجريدة الرسمية. والمدة تُحسب من تاريخ النشر."},"1tpj37f":{"w":{"إدارات التعليم في المناطق":"إدارات التعليم جهات تنفيذية قائمة أصلاً، والقرار نص على أن مجلس شؤون التعليم العام هو الذي يمارس اختصاصاته من تاريخ النشر.","هيئة تقويم التعليم والتدريب":"هيئة تقويم التعليم والتدريب جهة قائمة تصدر الرخصة المهنية وتقوّم التعليم، والنص على العمل من تاريخ النشر يخص مجلس شؤون التعليم العام.","لجنة المخالفات المنصوص عليها في النظام":"لجنة المخالفات من أحكام النظام نفسه، فتتبع بدء العمل به بعد 180 يوماً، بخلاف المجلس الذي يعمل من تاريخ النشر."}},"xdtamu":{"w":{"بقيت سارية دون تغيير، لأن مواد النظام لم تذكرها بالاسم ولم تنص على إلغائها صراحة":"الإلغاء جاء صراحة في قرار مجلس الوزراء 103 بالموافقة على النظام، فخلوّ مواد النظام من اسمها لا يعني بقاءها دون تغيير.","ألغيت فوراً من تاريخ نشر النظام في الجريدة الرسمية دون أي فترة انتقالية لأحكامها":"القرار 103 أبقى أحكامها سارية حتى يقر المجلس البديل خلال سنة من نفاذ النظام، فالإلغاء انتقال منظم لا فوري.","دُمجت نصوصها كاملة في المادة الثانية من النظام، فأصبحت أهداف التعليم العام فيه هي نصوص السياسة نفسها":"السياسة في 236 مادة والنظام كله 68 مادة، فلم تُدمج فيه، بل أُلغيت بالقرار 103 مع بقاء أحكامها سارية حتى يُقر بديلها."}},"1ypp098":{"w":{"من بداية الحضانة حتى نهاية رياض الأطفال":"البداية من الحضانة صحيحة، لكن النظام يمد المرحلة بعد الروضة لتشمل الصفوف الثلاثة الأولى حتى نهاية الصف الثالث.","من الولادة حتى سن السادسة":"تعريف المادة 1 مربوط بالمراحل الدراسية لا بالعمر، فيبدأ من الحضانة وينتهي بنهاية الصف الثالث لا عند سن السادسة.","من رياض الأطفال حتى نهاية الصف السادس":"المرحلة تبدأ من الحضانة قبل رياض الأطفال، وتنتهي عند نهاية الصف الثالث لا السادس."},"e":"عرّفت المادة 1 الطفولة المبكرة بأنها التعليم والرعاية من بداية الحضانة حتى نهاية الصف الثالث."},"mt0241":{"w":{"من السنة السادسة حتى نهاية الصف الثاني عشر":"نهاية الصف الثاني عشر هي حد التعليم العام كله في المادة 1، أما الإلزام في المادة 4 فينتهي عند الخامسة عشرة.","من رياض الأطفال حتى الخامسة عشرة":"رياض الأطفال من مراحل التعليم العام لكنها قبل سن الإلزام، فالإلزام في المادة 4 يبدأ من السنة السادسة.","من السنة السابعة حتى الثامنة عشرة":"الحدان كلاهما خطأ، فالإلزام في النظام يبدأ من السنة السادسة لا السابعة، وينتهي عند الخامسة عشرة لا الثامنة عشرة."},"e":"تنص المادة 4/1 على أن سن التعليم الإلزامي تبدأ من السنة السادسة حتى الخامسة عشرة."},"kj1e09":{"w":{"يُترك الأمر لولي الأمر لأنه صاحب القرار في تعليم ابنه ما دام ينفق عليه":"الطالب في الحادية عشرة داخل سن الإلزام، والمادة 4/2 توجب الإجراءات النظامية تجاه من يتسبب في انقطاعه ولو كان ولي أمره.","يُحوَّل الطالب إلى برامج الانتساب ليجمع بين العمل والدراسة بدلاً من الحضور اليومي":"النظام يجعل التعليم حضورياً، والطالب داخل سن الإلزام، فالمطلوب إجراء نظامي تجاه من تسبب في انقطاعه لا تكييف دراسته مع عمله.","تكتفي المدرسة بتسجيل غيابه وإنذار ولي أمره حتى يتجاوز الطالب سن الإلزام":"تسجيل الغياب والإنذار إجراء مدرسي لا يكفي هنا، فالمادة 4/2 توجب على الوزارة إجراءات نظامية مع الجهات المختصة خلال سنوات الإلزام."}},"1tohmfc":{"w":{"حاصلاً على مؤهل جامعي تربوي في أي تخصص":"المؤهل المناسب من شروط الحصول على الرخصة، لكن تعريف المادة 1 يربط صفة المعلم بالترخيص له بالمهنة لا بالمؤهل وحده.","معيَّناً على وظيفة تعليمية في مدرسة حكومية":"التعيين في وظيفة حكومية علاقة وظيفية مع جهة العمل، أما التعريف فيربط صفة المعلم بالترخيص له بمزاولة مهنة التعليم العام.","يدرّس مقرراً دراسياً في أي مؤسسة تعليمية":"التدريس الفعلي لا يكفي في نص التعريف دون ترخيص، وعبارة «أي مؤسسة» تتجاوز التعليم العام الذي يخصه النظام."},"e":"عرّفت المادة 1 المعلم بأنه «من يُرخَّص له بالعمل في مهنة التعليم العام»، فالتعريف مربوط بالترخيص."},"p1zmrc":{"w":{"المنهج التعليمي":"المنهج التعليمي أهداف مخطط لها تحقق نواتج مقصودة يُتأكد منها بالتقويم، والتعريف هنا يصف محتوى يدرسه الطلاب لا أهدافاً.","البرنامج التعليمي":"البرنامج التعليمي نشاط يُنظَّم في إطار المنهج لتحقيق أهداف في مجال محدد، والتعريف هنا عن المحتوى الذي يدرسه الطلاب.","الإطار الوطني للمناهج":"الإطار الوطني للمناهج وثيقة عامة تُعدّها الوزارة والهيئة مع المركز الوطني للمناهج لتوجيه المناهج كلها، لا المحتوى الذي يدرسه الطلاب."},"e":"في المادة 1: المقرر الدراسي هو المحتوى."},"1aqb0fb":{"w":{"تعلم لغة أجنبية واحدة على الأقل، وتنمية مهاراتها الأساسية لدى الطلاب":"هدف تعلم اللغة الأجنبية يخص اكتساب مهارات لغة أخرى، والنشاط هنا تحليل مقطع مضلل والتحقق من مصدره، فلا صلة له بلغة أجنبية.","تنمية حب العمل والانضباط والإنتاجية، والوعي بالعادات الصحية":"هذا الهدف يتعلق بقيم العمل والإنتاجية والصحة، والنشاط هنا يدرب على نقد المحتوى الإعلامي المضلل والتحقق من مصادره.","ترسيخ الهوية الوطنية، والاعتزاز بتاريخ الوطن ورموزه، ومعرفة جغرافيته":"ترسيخ الهوية الوطنية يتعلق بتاريخ الوطن ورموزه وجغرافيته، أما النشاط فيدرب الطلاب على فحص المعلومة المضللة ومصدرها."}},"1oplepb":{"w":{"يُمنع التعليم بغير اللغة العربية منعاً تاماً في جميع مراحل التعليم العام":"النظام لا يمنع غير العربية منعاً تاماً، بل يجعل العربية الأساس ويجيز لغة إضافية وفق ضوابط يقرها المجلس.","يجوز التعليم بأي لغة تختارها المدرسة دون ضوابط":"إطلاق الاختيار للمدرسة يخالف المادة 5، فالعربية هي الأساس والتعليم بلغة إضافية مقيد بضوابط يقرها المجلس.","يجوز ذلك في المدارس الحكومية وحدها، بقرار يصدره مدير التعليم في المنطقة":"المادة 5 لا تقصر اللغة الإضافية على المدارس الحكومية، والضوابط يقرها مجلس شؤون التعليم العام لا مدير التعليم في المنطقة."}},"djy552":{"w":{"رئيس هيئة تقويم التعليم والتدريب":"رئيس هيئة تقويم التعليم والتدريب عضو في المجلس بنص المادة 7، أما رئاسته فللوزير.","نائب الوزير للتعليم العام":"نائب الوزير للتعليم العام هو نائب رئيس المجلس بنص المادة 7، والرئاسة للوزير نفسه.","رئيس المركز الوطني للمناهج":"المركز الوطني للمناهج يشارك في إعداد الإطار الوطني للمناهج، أما رئاسة المجلس فقد جعلتها المادة 7 للوزير."},"e":"تنص المادة 7 على إنشاء المجلس برئاسة الوزير."},"1mf0ili":{"w":{"وزارة التعليم":"الوزارة يرأسها الوزير الذي يرأس المجلس أيضاً، لكن المادة 8/2 جعلت تحديد سن القبول اختصاصاً للمجلس نفسه لا للوزارة.","مجلس الوزراء":"مجلس الوزراء وافق على النظام بقراره 103، أما تحديد سن القبول فأسنده النظام إلى مجلس شؤون التعليم العام.","إدارات التعليم في المناطق":"سن القبول يحدده المجلس بنص المادة 8/2 حكماً موحداً، فلا تنفرد كل إدارة تعليم بتحديده لمنطقتها."}},"2jdxue":{"w":{"لا يجيز النظام تكليف معلم المدرسة الحكومية بأي مقرر يخرج عن تخصصه":"المادة 46 تجيز صراحة للوزارة تكليف معلمي المؤسسات الحكومية بمقررات خارج تخصصاتهم، بشرط اتباع القواعد التي يقرها المجلس.","يقرره مدير المدرسة منفرداً بحسب احتياج الجدول الدراسي ونصاب المعلمين فيها":"التكليف في المادة 46 صلاحية للوزارة تُمارس وفق قواعد يقرها المجلس، لا قرار فردي من مدير المدرسة بحسب الجدول.","يكون التكليف بموافقة المعلم الكتابية فقط، دون قواعد عامة يقرها المجلس أو الوزارة":"النظام لم يعلّق التكليف على موافقة المعلم الكتابية، بل نظمه بقواعد يقرها المجلس تشمل المزايا المالية ومتطلبات التأهيل."}},"1dukz9m":{"w":{"يحق لولي الأمر اختيار التعليم عن بُعد بديلاً كاملاً عن الحضور في أي مرحلة دراسية":"المادة 24 تجعل التعليم حضورياً في كل المراحل، والتقنية جزء منه لا بديل يختاره ولي الأمر عن الحضور.","التعليم عن بُعد هو الأصل في المرحلة المتوسطة، والحضور إلى المدرسة اختياري للطالب":"الأصل في النظام الحضور في جميع مراحل التعليم العام ومنها المتوسطة، والحضور ليس اختيارياً للطالب.","يُحال الطلب إلى المؤسسات التعليمية الافتراضية لتقبله دون أي ضوابط":"المؤسسات التعليمية الافتراضية لها لوائح يقرها المجلس فلا تقبل طلباً دون ضوابط، والأصل في المادة 24 هو الحضور."}},"17errdz":{"w":{"بالاختبار نفسه الذي يؤديه زملاؤه في الفصل، دون أي تعديل أو تقنية مساعدة":"المادة 20 توجب تقويم الطالب ذي الإعاقة بأساليب تراعي خصائصه مع تقنيات مساعدة، فتوحيد الاختبار بلا تكييف يخالفها.","يُعفى من التقويم كلياً ما دام مدموجاً في الفصل العادي":"الدمج لا يعني الإعفاء، فالمادة 20 تنص على تقويمه بأساليب تراعي قدراته لا على إسقاط تقويمه.","يُنقل إلى مركز متخصص ليُقوَّم هناك ثم يعود إلى فصله":"المراكز المتخصصة في المادة 21 لمن يتعذر دمجه، وهذا الطالب مدموج في فصله فيُقوَّم فيه بأساليب مكيّفة."},"e":"تنص المادة 20 على دمج الطلاب ذوي الإعاقة في المؤسسات التعليمية، وتوفير الوسائل المناسبة لهم، وتقويمهم بأساليب تراعي خصائصهم واحتياجاتهم وقدراتهم، مع توفير التقنيات المساعدة والتكيفية."},"o1p7sq":{"w":{"الاكتفاء بمعدل الطالب في السنة الأخيرة":"المادة 23 تشترط إجراءات تقويم شاملة، والمعدل وحده مؤشر واحد لا يكفي للحكم على جاهزية الطالب للمرحلة التالية.","موافقة معلم المادة التي تفوق فيها الطالب":"رأي معلم واحد لا يرد في ضوابط المادة 23، فهي تتطلب تقويماً شاملاً وتنسيقاً مع أولياء الأمور.","اجتياز الطالب اختباراً دولياً معتمداً":"الضوابط في المادة 23 لا تشترط اختباراً دولياً، بل معايير واضحة وتقويماً شاملاً وتدريب المعلمين والتنسيق مع الأسرة."}},"13vwaq4":{"w":{"الوزارة وحدها، دون مشاركة هيئة التقويم أو المركز الوطني للمناهج":"المادة 27 لا تجعل الإطار عمل الوزارة وحدها، بل تشترك فيه مع هيئة تقويم التعليم والتدريب والمركز الوطني للمناهج.","مجلس شؤون التعليم العام بالاشتراك مع وزارة الثقافة ووزارة الإعلام":"وزارتا الثقافة والإعلام ليستا من الجهات التي سمتها المادة 27، فالإطار تعدّه الوزارة والهيئة مع المركز الوطني للمناهج.","المركز الوطني للمناهج وإدارات التعليم في المناطق":"المركز الوطني للمناهج شريك فعلاً، لكن إدارات التعليم ليست من الجهات التي سمتها المادة 27، وغابت عن الخيار الوزارة وهيئة تقويم التعليم والتدريب."}},"znm681":{"w":{"الاعتماد المدرسي اختياري للمدارس التي تطبق برامج دولية سبق أن اعتمدتها الوزارة":"المادة 30/2 تجعل الاعتماد المدرسي إلزامياً على المدارس الخاصة، واعتماد الوزارة للبرنامج الدولي لا يحوّله إلى خيار.","يكفي اعتماد الوزارة للبرنامج الدولي، ويغني ذلك عن أي اعتماد مدرسي من جهة أخرى":"اعتماد الوزارة للبرنامج الدولي في المادة 28 أمر مستقل، ويبقى على المدرسة اعتماد مدرسي من الهيئة أو هيئة دولية تعتمدها.","تختار المدرسة أي هيئة اعتماد دولية تشاء دون أن تعتمدها هيئة التقويم":"الهيئة الدولية مقبولة بشرط أن تعتمدها هيئة تقويم التعليم والتدريب، فلا تختار المدرسة جهة اعتماد لم تعتمدها الهيئة."},"e":"تنص المادة 30/2 على أن المؤسسات التعليمية الخاصة ملزمة بالحصول على الاعتماد المدرسي من هيئة تقويم التعليم والتدريب، أو من إحدى الهيئات الدولية التي تعتمدها الهيئة."},"z5dzt3":{"w":{"يجوز ما دامت المدرسة حاصلة على اعتماد مدرسي من هيئة دولية معترف بها":"الاعتماد المدرسي الدولي ينظم جودة المدرسة، ولا يُسقط إشراف الوزارة على تدريس مواد الهوية الوطنية بنص المادة 31.","يجوز للمدارس التي تطبق برامج دولية فقط، لأن الوزارة اعتمدت برنامجها":"المادة 31 تفرض مواد الهوية على المدارس الخاصة ومنها التي تطبق برامج دولية، فاعتماد البرنامج لا يعفي منها.","يجوز إذا وافق أولياء الأمور كتابياً على إعفاء أبنائهم":"مواد الهوية الوطنية حكم نظامي تشرف عليه الوزارة، فلا تسقطه موافقة أولياء الأمور الكتابية على إعفاء أبنائهم."}},"k8mg63":{"w":{"تبلغه الوزارة بقرارها شفهياً خلال 90 يوماً، دون أن تذكر أسباب الرفض":"المادة 32/2 توجب قراراً مكتوباً خلال 30 يوماً، والرفض فيها مسبَّب مع حق التظلم، فلا إبلاغ شفهي ولا رفض بلا أسباب.","يُعدّ الطلب مقبولاً حكماً إذا لم ترد الوزارة عليه خلال 60 يوماً":"المدة النظامية للرد 30 يوماً لا 60، والمادة 32/2 تلزم الوزارة بقرار مكتوب يُبلَّغ لطالب الترخيص.","يصدر القرار من مجلس شؤون التعليم العام في أول اجتماع له":"الرد على طلب الترخيص من الوزارة بنص المادة 32/2 خلال 30 يوماً من الطلب، لا من المجلس في أول اجتماعاته."}},"6y29mo":{"w":{"غرامة لا تقل عن 50,000 ريال ولا تزيد على 500,000 ريال":"حدود الغرامة في المادة 60 من 5,000 إلى 50,000 ريال، فالرقم 50,000 هو الحد الأعلى لا الأدنى.","إغلاقها فوراً وتوزيع طلابها على المدارس الحكومية في اليوم نفسه":"أشد جزاء في المادة 60 إلغاء الترخيص مع إكمال الطلاب المقيدين عامهم الدراسي على نفقة المالك، لا الإغلاق الفوري.","سحب رخص معلميها المهنية":"جزاءات المادة 60 تقع على المدرسة نفسها كالإنذار وإيقاف التسجيل والغرامة، والرخصة المهنية تخص المعلم وتصدرها هيئة التقويم."}},"3iirei":{"w":{"تصرف نظامي، لأن المحافظة على الكتب وإعادتها من واجبات الطالب":"قد يكون إرجاع الكتاب مطلوباً، لكن المادة 38/1 تجعل تسلم الشهادة حقاً دون قيد أو شرط، فيُعالج الكتاب بطريق آخر.","يجوز إذا أبلغت المدرسة ولي الأمر كتابياً بسبب حجب الشهادة":"إبلاغ ولي الأمر كتابياً لا يجعل الحجب نظامياً، فحق تسلم الشهادة في المادة 38/1 غير معلّق على أي شرط.","يجوز حجبها حتى يدفع ولي الأمر قيمة الكتاب":"ربط الشهادة بدفع قيمة الكتاب شرط آخر، والمادة 38/1 تمنح الطالب شهادته دون قيد أو شرط، ويُعالج الكتاب منفصلاً."}},"b87xhz":{"w":{"الرعاية الصحية الأولية داخل المؤسسة التعليمية عند الحاجة إليها":"الرعاية الصحية حق يخص صحة الطالب داخل المدرسة، والمشكلة هنا تكليفه بشراء أدوات لمشروع خارج الخطة مع التهديد بالدرجات.","الحصول على جوائز وحوافز مادية ومعنوية عند تميزه":"الجوائز والحوافز حق يرتبط بتميز الطالب، والموقف هنا عن تكليف بعمل من اجتهاد المعلم لا عن مكافأة متميز.","تسلم شهادة النجاح بعد إتمام السنة الدراسية دون قيد أو شرط":"حق تسلم الشهادة يُخالَف بحجبها عن الطالب الناجح، والموقف هنا ليس حجب شهادة بل تكليف الطلاب بمشروع من اجتهاد المعلم الفردي."}},"1yeyhvt":{"w":{"سماعها شفهياً ونصحها بالصبر على زميلتها":"السماع خطوة واحدة من ثلاث في المادة 38/1، ويبقى قيد الشكوى واتخاذ الإجراء، والنصح بالصبر لا يعالج المشكلة.","إحالتها إلى ولي أمرها ليتابع الشكوى خارج المدرسة":"الشكوى قُدّمت للمدرسة، والمادة 38/1 تلزمها بسماعها وقيدها واتخاذ الإجراء، لا بنقل المتابعة إلى ولي الأمر خارجها.","تأجيل النظر فيها إلى نهاية الفصل الدراسي":"التأجيل إلى نهاية الفصل يعطّل اتخاذ الإجراء اللازم، وحق الطالبة في المادة 38/1 سماع شكواها وقيدها والتصرف حيالها."},"e":"من حقوق الطالب في المادة 38/1 (الفقرة ج): سماع شكواه، وقيدها، واتخاذ الإجراء اللازم حيالها. فالإجراء الكامل له ثلاث خطوات."},"ehm2hv":{"w":{"المشاركة في لجان تقويم المعلمين":"التزامات الطالب في المادة 38/2 تخص الاحترام والحضور والجهد وحماية المرافق والسلوك، وتقويم المعلمين ليس منها.","تحمّل تكاليف النقل المدرسي في المؤسسات الحكومية":"التزامات المادة 38/2 سلوكية كالاحترام والحضور وعدم الإضرار بالمرافق، ولا تتضمن أي التزام مالي كتكاليف النقل.","اختيار المقررات الدراسية التي يرغب فيها":"اختيار المقررات ليس التزاماً على الطالب، والتزاماته في المادة 38/2 احترام الآخرين والحضور وبذل الجهد والالتزام بقواعد السلوك."}},"au3aav":{"w":{"لا يخالف شيئاً، لأن واجبات المعلم في النظام مقصورة على اليوم الدراسي داخل المدرسة":"المادة 49/3 تمد واجب صون شرف المهنة إلى داخل المدرسة وخارجها، فخارج الدوام لا يعفي المعلم من هذا الواجب.","المادة 38، لأنها تحدد واجبات المعلم داخل الفصل الدراسي فقط":"المادة 38 تحدد حقوق الطالب والتزاماته لا واجبات المعلم، وواجبات المعلم وردت في المادة 49.","المادة 60، لأنها تنظم جزاءات المؤسسات التعليمية الخاصة المخالفة للنظام":"المادة 60 خاصة بجزاءات المدارس الخاصة المخالفة، والموقف هنا سلوك معلم فرد يمس شرف المهنة، فتحكمه المادة 49."}},"7mvs4f":{"w":{"استثمار اليوم الدراسي في أداء المهمات المنوطة به وتطوير إمكاناته":"استثمار اليوم الدراسي واجب يخص إدارة الوقت وتطوير المعلم نفسه، والتقصير هنا في توزيع الفرص بعدل بين الطلاب.","الإسهام في البحوث والدراسات التي تخدم القضايا التعليمية":"الإسهام في البحوث واجب يخدم قضايا التعليم عامة، والمشكلة هنا تمييز المعلم بين طلابه في المشاركة داخل الصف.","تدريس المقررات المسندة إليه وفق الأهداف والبرامج المعتمدة":"تدريس المقررات وفق الأهداف يتعلق بمحتوى ما يُدرَّس، والخلل هنا في تعامله مع الطلاب وتجاهل منخفضي المستوى."}},"1f3v5x":{"w":{"الإعفاء من تدريس أي مقرر يخرج عن تخصصه متى طلب ذلك كتابياً من مديره":"المادة 46 تجيز للوزارة تكليف المعلم بمقررات خارج تخصصه وفق قواعد المجلس، فلا يملك الإعفاء بمجرد طلب كتابي.","اختيار طلاب فصله بنفسه بحسب مستوياتهم وقدراتهم التحصيلية":"حقوق المعلم في المادة 48 بيئة مناسبة وتدريب وفرص إسهام وحوافز، وليس منها اختيار طلاب فصله بحسب مستوياتهم.","تحديد سن القبول في مدرسته وفق احتياجات الحي":"تحديد سن القبول من اختصاص مجلس شؤون التعليم العام بنص المادة 8/2، فلا يملكه معلم ولا مدرسة."}},"1lsrnd7":{"w":{"الصلح بين أسرتي الطالبين وإغلاق الموضوع داخلياً":"المادة 65 توجب إبلاغ الجهة المختصة لاستكمال الإجراءات النظامية، فالصلح الداخلي لا يغني عن هذا الإبلاغ.","عدم التدخل لأن الواقعة حدثت خارج مبنى المدرسة":"واجب الإبلاغ في المادة 65 يشمل ما يقع في محيط المدرسة، والمشاجرة عند بوابتها داخلة في هذا المحيط.","الاكتفاء بإبلاغ ولي أمر الطالب المصاب":"إبلاغ ولي الأمر لا يكفي، فالمادة 65 توجب على الإدارة إبلاغ الجهة المختصة عن الاعتداء لاستكمال الإجراءات."}},"19zbi2k":{"w":{"لا؛ الواجب يقتصر على الاعتداء على الطلاب":"المادة 65 تنص على الاعتداء على أي من الطلاب أو منسوبي المؤسسة، والمعلم من منسوبيها فيشمله الواجب.","لا؛ يكتفي المعلم برفع شكوى شخصية":"شكوى المعلم الشخصية لا تُسقط واجب الإدارة، فالمادة 65 تلزمها بإبلاغ الجهة المختصة عن الاعتداء على منسوبيها.","نعم بشرط أن يطلب المعلم ذلك كتابياً":"الواجب في المادة 65 على إدارة المؤسسة مباشرة، ولم يعلّقه النظام على طلب كتابي من المعتدى عليه."},"e":"المادة 65 تنص على الإبلاغ عن أي اعتداء أو إيذاء يقع على أي من طلاب المؤسسة أو منسوبيها، والمعلم من منسوبيها. والمُلزَم بالإبلاغ إدارة المؤسسة."},"1n4b6ec":{"w":{"الإنذار في المرة الأولى، ثم إنهاء الخدمة إذا تكررت منه المخالفة":"الإنهاء عند التكرار حكم المخالفة غير الجسيمة في المادة 59/1، والمخالفة هنا جسيمة ثابتة فتُنهى الخدمة مع المنع من العودة.","نقله إلى مدرسة أخرى في المنطقة نفسها، مع إنذاره كتابياً بالفصل عند التكرار":"المادة 59/2 لا تكتفي بالنقل والإنذار عند ثبوت المخالفة الجسيمة، بل تنهي الخدمة وتمنع العودة إلى التعليم العام والخاص.","حسم من راتبه مع بقائه في عمله ومنعه من الترقية مدة سنة":"بقاء المعلم في عمله يناقض حكم المادة 59/2، فثبوت المخالفة الجسيمة يوجب إنهاء خدمته ومنعه من العودة للمجال التعليمي."},"e":"تنص المادة 59/2 على أنه إذا ثبت ارتكاب مخالفة جسيمة تنهى خدمته، ولا يسمح له بالعودة للعمل في المجال التعليمي في القطاعين العام والخاص."},"na72b1":{"w":{"إنهاء خدمته فوراً قبل التحقيق في المخالفة وثبوتها عليه":"إنهاء الخدمة جزاء يأتي عند ثبوت المخالفة، أما مرحلة القرائن فتجيز المادة 58 فيها تدابير عاجلة مؤقتة ككف اليد.","الانتظار حتى يصدر حكم قضائي نهائي دون اتخاذ أي إجراء":"المادة 58 لا تترك البيئة التعليمية بلا حماية عند القرائن، فتجيز للوزير تدابير عاجلة إلى أن يُفصل في المخالفة.","نقله إلى مدرسة أخرى بقرار من مدير المدرسة إلى حين التحقيق":"تدابير المادة 58 العاجلة يتخذها الوزير أو من يفوضه، لا مدير المدرسة من تلقاء نفسه، ومن صورها المنع من العمل داخل المؤسسة أو كف اليد."}},"10mr4i2":{"w":{"لها التظلم أمام مدير المدرسة خلال 30 يوماً":"التظلم في المادة 63 أمام الجهة القضائية المختصة خلال 60 يوماً، لا أمام مدير المدرسة ولا خلال 30 يوماً.","لها التظلم أمام مجلس شؤون التعليم العام خلال 90 يوماً":"مجلس شؤون التعليم العام ليس جهة التظلم، فالمادة 63 تجعله أمام الجهة القضائية المختصة خلال 60 يوماً من العلم.","لا يجوز التظلم من قرارات لجنة المخالفات":"المادة 63 تجيز صراحة لكل من صدر في حقه جزاء أن يتظلم منه أمام الجهة القضائية خلال 60 يوماً."}},"jvnddj":{"w":{"اجتهاد كل مدرسة بحسب ظروفها دون إطار عام تضعه الوزارة":"المادة 50 تجعل الشراكة مع الأسرة وفق ضوابط تضعها الوزارة، فلا تُترك لاجتهاد كل مدرسة دون إطار عام.","لائحة يصدرها مجلس الوزراء لكل منطقة تعليمية على حدة":"الضوابط في المادة 50 تضعها الوزارة إطاراً عاماً، لا مجلس الوزراء ولا لائحة منفصلة لكل منطقة تعليمية.","اتفاقيات تبرمها المدرسة مع القطاع الخاص لتمويل مشاركة الأسر":"المادة 50 تتحدث عن شراكة المدرسة مع الأسرة بضوابط من الوزارة، والتمويل من القطاع الخاص لا صلة له بها."}},"1rrqlv0":{"w":{"يضعها مجلس الوزراء، وتصدر بمرسوم ملكي بعد الرفع بها":"المرسوم الملكي أداة إصدار النظام نفسه، أما لوائح تنفيذه فتضعها الوزارة بنص المادة 67 وتصدر بقرار الوزير.","تضعها هيئة الخبراء بمجلس الوزراء، وتصدر بقرار من مجلس الوزراء":"هيئة الخبراء لا ذكر لها في المادة 67، فاللوائح التنفيذية تضعها الوزارة بالتنسيق مع الجهات المعنية وتصدر بقرار الوزير.","تضعها كل إدارة تعليم لمنطقتها، وتصدر بقرار من مديرها":"اللوائح التنفيذية موحدة تضعها الوزارة وتصدر بقرار الوزير، فلا تضع كل إدارة تعليم لائحة لمنطقتها بقرار مديرها."}},"94c039":{"w":{"50 درجة للسلوك و50 درجة للمواظبة":"السلوك والمواظبة درجتان منفصلتان لكل منهما 100 درجة، فلا تُقسم درجة السلوك بينهما نصفين.","100 درجة للسلوك الإيجابي تُحسم منها المخالفات فقط":"درجة السلوك ليست كلها للإيجابي، فالإيجابي 80 تُحسم منها المخالفات، و 20 للسلوك المتميز تُكتسب بممارسات كالتسامح والأمانة.","60 درجة للسلوك داخل الفصل و40 درجة خارجه":"القواعد لا تقسم درجة السلوك بحسب المكان، بل بحسب نوعه: 80 للسلوك الإيجابي و 20 للسلوك المتميز."}},"oaj6b3":{"w":{"حسم خمس درجات من درجات المواظبة":"الحسم في القواعد درجة واحدة عن كل يوم غياب بدون عذر، فخمس درجات تقابل خمسة أيام غياب لا يوماً واحداً.","حرمانه من دخول الاختبار مباشرة":"يوم الغياب الواحد يُحسم به درجة فقط، والحرمان في القواعد يكون من الانتقال عند تجاوز الغياب بدون عذر 10%.","لا يؤثر الغياب في الدرجة إلا بعد أسبوع":"الحسم يقع عن كل يوم غياب بدون عذر من أوله، فلا تنتظر القواعد مرور أسبوع قبل احتساب أثره."}},"1qwn5bm":{"w":{"دراسة حالة الطالب المخالف بعد تنفيذ الإجراء":"دراسة حالة الطالب المخالف وعلاجها هي الدور الذي أبقته القواعد للموجه الطلابي، فهي من مهامه لا الاستثناء.","متابعة الطلبة متكرري الغياب بالتنسيق مع وكيل شؤون الطلبة":"دراسة حالة متكرر الغياب ومتابعته من عمل الموجه الطلابي، والممنوع عليه رصد الدرجات وحسمها لا المتابعة والعلاج.","توعية الطلبة المخالفين بحقهم في فرص تعويض الدرجات":"توعية المخالفين بحقهم في فرص تعويض درجات السلوك منصوص عليها في دور الموجه الطلابي، فهي من مهامه لا الاستثناء، والممنوع عليه الرصد والحسم."}},"o5j4q1q":{"w":{"تصوير سجلات الأداء الأكاديمي للطالب في ذلك العام وإرسالها.":"إرسال سجلات الطالب لجهة خارجية دون الرجوع للإدارة إخلال بسرية معلوماته، فالإدارة تملك صلاحية الإفصاح وفق اللوائح.","استشارة معلمين آخرين لإعداد سجل غير رسمي للطالب وإرساله.":"السجل غير الرسمي يكشف معلومات الطالب خارج القنوات المعتمدة فهو إخلال بالسرية، والخطوة الأولى الرجوع إلى إدارة المدرسة.","إبلاغ الطالب وأخذ إذنه بالموافقة لإرسال المعلومات المطلوبة.":"الطالب في الأول المتوسط قاصر فإذنه وحده لا يكفي، والإفصاح عن معلوماته صلاحية إدارة المدرسة وفق اللوائح."},"e":"معلومات الطالب سرية، وأي جهة خارجية تُحال إلى إدارة المدرسة التي تملك صلاحية الإفصاح وفق اللوائح. (المعيار 1.3)"},"oooa2nc":{"w":{"تسهم في اعتياد المعلم على عملية التقويم وإحساسه بالراحة فيها.":"الاعتياد على التقويم فائدة ثانوية، والمعلم الجديد يحتاج أولاً إلى ما ينقصه وهو الخبرة بأساليب التدريس التي يملكها زملاؤه.","تساعد المعلم على تعلم تطبيق المبادئ التدريسية بفاعلية في جو الفصل.":"تحسين تطبيق المبادئ في الصف ثمرة تأتي بعد اكتساب الخبرة، وأهم ما ينقص المعلم الجديد خبرة بأساليب التدريس ينقلها إليه نقد الزملاء الخبراء.","توصل لزملاء المعلم رغبته في أن يكون عضوًا فاعلًا في الفريق.":"إظهار الرغبة في الانتماء للفريق فائدة اجتماعية ثانوية، والمعلم طلب الزيارة والنقد البنّاء ليكتسب خبرة تدريسية لا ليعلن رغبته."},"e":"المعلم الجديد يفتقر للخبرة بالأساليب التدريسية، وزيارة الزملاء له تطلعه على الأساليب الناجحة التي يستخدمونها من واقع خبراتهم. (المعيار 2.1)"},"oyofqoi":{"w":{"زيارة المكتبة للاطلاع على كتب ودراسات تساعد في توجيه التعامل مع أولياء الأمور.":"هذه الكتب تخص التعامل مع أولياء الأمور، والمعلم هنا يريد تحسين خطته لإدارة الصف، فهي لا تخدم حاجته.","مناقشة الصعوبات التي تراها مع مدير المدرسة وطلب تقويم متكرر لتحسين أدائك.":"النقاش مع المدير وطلب تقويمه خطوة أقل مباشرة، فالتقويم يرصد الأداء، ومشاهدة زملاء فاعلين تقدم نموذجاً عملياً لإدارة الصف.","التعاون مع معلمين جدد آخرين في المدرسة ومناقشة الصعوبات التي واجهوها في المدرسة.":"المعلمون الجدد يمرون بالصعوبات نفسها ولا يملكون بعد خبرة يُتعلم منها، والأنفع مراقبة زملاء فاعلين ذوي خبرة في المدرسة."},"e":"التطوير المهني الأنفع للمعلم الجديد هو التعلم من الممارسة الناجحة لزملاء ذوي خبرة في السياق نفسه. (المعيار 2.2)"},"o1l2k38p":{"w":{"تساهم في اعتياده على عملية التقويم وإحساسه بأهميتها.":"الاعتياد على التقويم ليس الغرض الأساسي من الإشراف، فالمعلم الجديد يطلب نقد الخبراء ليكتسب من آرائهم وخبراتهم المتنوعة في التدريس.","تساعده على تعلم تطبيق المبادئ التدريسية بفاعلية في جو الفصل الدراسي.":"تحسين التطبيق في الصف ثمرة لاحقة لا يضمنها الإشراف وحده، وأهم ما يقدمه نقد الزملاء الخبراء آراء وخبرات متنوعة في التدريس يبني عليها المعلم.","توصل لزملائه رغبته بأن يكون عضوًا فعالًا في الفريق.":"إظهار الرغبة في الانتماء أثر اجتماعي جانبي، والمعلم يطلب الإشراف والنقد ليحصل على تغذية راجعة وخبرة متنوعة من ذوي الخبرة."},"e":"غرض الزيارة الإشرافية من الزملاء هو الحصول على تغذية راجعة وخبرة متنوعة من ذوي الخبرة لتحسين الأداء في العام الأول. (المعيار القديم 11.2)"},"o12uhk87":{"w":{"زيارة المكتبة للاطلاع على كتب ودراسات تساعد في توجيه التعامل مع الأسر والمجتمعات الكبيرة.":"هذه الكتب موجهة للتعامل مع الأسر والمجتمع، والمطلوب تحسين خطة إدارة الصف، فلا تخدم الحاجة المباشرة هنا.","مناقشة الصعوبات التي تراها مع مدير المدرسة وطلب تقويم متكرر لتحسين أدائك التدريسي.":"طلب التقويم المتكرر من المدير خيار أقل مباشرة، فهو يحكم على الأداء، ومراقبة زملاء فعالين تقدم نماذج عملية لإدارة الصف.","التعاون مع معلمين جدد آخرين في المدرسة ومناقشة الصعوبات التي واجهوها في المدرسة.":"المعلمون الجدد يواجهون الصعوبات نفسها ويفتقرون للخبرة، فالتعلم منهم لا يقدم حلولاً مجربة كما يقدمها المعلمون الفعالون في المدرسة."},"e":"التعلم من الممارسين الناجحين في المدرسة نفسها أنسب وأسرع طريق لتحسين الإدارة الصفية. (المعيار القديم 10.1، صعوبة 0.556)"},"3d9l1d":{"w":{"التنافس الفردي بين المعلمين":"التنافس الفردي يضع المعلمين في مواجهة بعضهم، ومن مبادئ مجتمع التعلم ثقافة التعاون التي تجمعهم على تحسين تعلم الطلاب.","الاعتماد على التدريب الخارجي فقط":"مجتمع التعلم مهنيون داخل المدرسة يتعاونون بشكل مخطط ومستمر، فحصر التطوير في تدريب يأتي من خارجها يناقض فكرته.","تقويم المعلمين بعضهم لبعض لأغراض الترقية":"ربط تقويم الزملاء بالترقية يحوّله إلى محاسبة وتنافس، فيناقض ثقافة التعاون التي هي أحد المبادئ الأربعة لمجتمع التعلم."},"e":"المبادئ الأربعة: رؤية مشتركة، ثقافة تعاون، تركيز على تعلم الطلاب، تركيز على النتائج."},"1j7exxu":{"w":{"الاختبارات الوطنية":"الاختبارات الوطنية أدوات لقياس تحصيل الطلاب على مستوى الدولة، لا صيغ عمل يتعاون فيها المعلمون ليتطوروا مهنياً.","اجتماعات أولياء الأمور":"اجتماعات أولياء الأمور قناة تواصل بين المدرسة والأسرة، أما أوعية مجتمع التعلم فصيغ يتطور فيها المعلمون مهنياً معاً.","تقويم الأداء الوظيفي":"تقويم الأداء الوظيفي إجراء إداري تحكم فيه الجهة المسؤولة على عمل المعلم، لا وعاء تعاوني يتبادل فيه الزملاء الخبرة."}},"1gpdpma":{"w":{"زيادة عدد الحصص لكل معلم":"زيادة النصاب تستهلك وقت المعلم فتحرمه من اللقاءات والتعاون مع زملائه، وهذا الوقت هو ما يحتاجه مجتمع التعلم لينجح.","حصر العضوية في المعلمين الجدد":"يُشكَّل مجتمع التعلم حسب الصفوف التي يدرّسها المعلمون لا حسب سنوات الخبرة، وحصره في الجدد يحرمهم خبرة زملائهم الأقدم.","الاكتفاء باللقاءات الافتراضية":"اللقاءات الافتراضية وسيلة لقاء مساعدة، أما عوامل النجاح فهي نظام فاعل للتطبيق وقيادة داعمة وبنية تنظيمية داعمة."},"e":"عوامل النجاح: نظام فاعل للتطبيق، قيادة داعمة، بنية تنظيمية داعمة."},"19viocb":{"w":{"تبرعات مالية تقدمها الشركات للمدارس":"التبرعات المالية صورة واحدة من صور الشراكة، والتعريف أوسع منها فيشمل الفكر والمشورة والموارد البشرية في علاقة تبادلية.","اجتماعات دورية بين المدير والمعلمين":"اجتماعات المدير والمعلمين عمل داخلي بين منسوبي المدرسة، والشراكة المجتمعية إسهام أولياء الأمور ومؤسسات المجتمع من خارجها.","زيارات الطلاب للمصانع والمؤسسات":"زيارات الطلاب للمؤسسات نشاط تعليمي قد تتيحه الشراكة، لا تعريفها، فالشراكة إسهام المجتمع بالفكر والمشورة والموارد في تطوير التعليم."},"e":"الشراكة أوسع من المال؛ تشمل الفكر والمشورة والموارد البشرية، والعلاقة تبادلية."},"zz7dsw":{"w":{"مواجهة الطالب أمام والده بأخطائه":"مواجهة الطالب أمام والده تحرجه وتفقد اللقاء الثقة، والمطلوب الإنصات للوالد ثم عرض أدلة من أعمال الطالب دون الحديث عنه أمامه.","رفض اللقاء وإحالته إلى الإدارة":"الإحالة إلى الإدارة لما ليس من صلاحية المعلم، أما شكوى تخص تعامله مع الطالب فهو أعرف بحقائقها، فالأصل أن يستقبل الوالد ويستمع إليه.","إنهاء اللقاء سريعاً لتجنب الجدل":"إنهاء اللقاء سريعاً يترك شكوى الوالد بلا إنصات ولا توضيح فيبقى الخلاف قائماً، والمطلوب الاستماع أولاً ثم عرض الحقائق بأدلة."},"e":"الإنصات ثم الأدلة الموثقة مع الحفاظ على سرية اللقاء وعدم الحديث أمام الطفل."},"sza88x":{"w":{"إعفاؤهم من النصاب التعليمي":"الإعفاء من النصاب قرار إداري يخص توزيع الحصص، وليس من وظائف مجتمع التعلم الذي يقدّم للمستجد الإسناد المهني من زملائه.","تقليل متطلبات التخطيط":"مجتمع التعلم يعين المستجد على متطلبات عمله كالتخطيط بالإسناد وتبادل الخبرة مع زملائه، لا بتقليل هذه المتطلبات.","تأجيل تقويم أدائهم":"تأجيل التقويم إعفاء إداري ليس من وظائف مجتمع التعلم، فمزيته للمستجد أن يجد بيئة داعمة تعينه على تحسين أدائه."},"e":"الأدبيات تذكر الإسناد والبيئة الداعمة للمستجدين كمزية صريحة."},"rl9luf":{"w":{"وزارة التعليم وإداراتها فقط":"قصر المجتمع المحيط على وزارة التعليم وإداراتها يحصره في جهات الإشراف، وهو يشمل كل الجهات الحكومية والأهلية والأفراد القادرين على الدعم حول المدرسة.","المدارس الأخرى في المدينة فقط":"حصر المجتمع المحيط في المدارس الأخرى يُسقط معظمه، فهو يشمل كل الجهات الحكومية والأهلية والأفراد القادرين على الدعم حول المدرسة.","الطلاب وأولياء الأمور فقط":"الطلاب وأولياء الأمور جزء من شركاء المدرسة، لكن المجتمع المحيط أوسع فيضم الجهات الحكومية والأهلية والأفراد القادرين على الدعم."}},"1w9yv8x":{"w":{"التطوير المهني المستمر (2)":"المعيار 2 يخص تطوير المعلم لنفسه مهنياً، أما الترحيب بخبرات أولياء الأمور ومهنهم فتواصل مع الأسرة يندرج في التفاعل مع أولياء الأمور.","الالتزام بالأخلاق المهنية واللوائح (1.3)":"المعيار الفرعي 1.3 يخص الأخلاق المهنية واللوائح، والسلوك هنا تحفيز أولياء الأمور على الإسهام بخبراتهم، وهو من مؤشرات التفاعل معهم.","التقويم (10)":"المعيار 10 يخص تقويم تعلم الطلاب وأدواته، ولا صلة له بإشراك أولياء الأمور بخبراتهم ومهنهم في دعم برامج التعلم."},"e":"المعيار الفرعي 3.2 (التفاعل مع أولياء الأمور) يتضمن مؤشر توظيف التواصل الإيجابي في تحفيز أولياء الأمور على الإسهام بخبراتهم وعلمهم وقدراتهم في دعم برامج التعلم (من مؤشرات المعلم المتقدم)."},"u3soqh":{"w":{"زيادة الأعباء الإدارية على المعلم":"زيادة الأعباء أثر سلبي لا نتيجة مقصودة، ونتائج الشراكة الموثقة تحصيل أعلى وتسرب أقل ودعم أكبر من أولياء الأمور ومعنويات أعلى.","تقليص دور المدرسة لصالح الأسرة":"الشراكة علاقة تبادلية تأخذ فيها المدرسة من مجتمعها وتعطيه، فهي تقوّي دور المدرسة بالتعاون ولا تنقله إلى الأسرة.","الاعتماد على التبرعات في رواتب المعلمين":"رواتب المعلمين ليست مما تتولاه الشراكة، فهي إسهام في تطوير التعليم بالفكر والمشورة والموارد، ونتائجها تحصيل أعلى وتسرب أقل."},"e":"النتائج الموثقة: تحصيل أعلى، تسرب أقل، دعم أكبر من أولياء الأمور، معنويات أعلى."},"13toup7":{"w":{"الاكتفاء بإرسال الدرجات النهائية إلى أولياء الأمور في آخر الفصل الدراسي":"إرسال الدرجات النهائية تواصل متأخر في اتجاه واحد لا يتيح متابعة ولا نقاشاً، والمعوق هنا الوقت فعلاجه مرونة القنوات والمواعيد.","تسجيل أسماء الغائبين ورفعها للإدارة":"رفع الأسماء للإدارة يعامل الغياب كمخالفة، وسببه هنا معروف وهو عمل أولياء الأمور مساءً، فالحل تغيير موعد التواصل وقناته.","إلغاء التواصل مع أولياء الأمور لعدم جدواه":"التواصل مع ولي الأمر شراكة في مصلحة الطالب لا تُلغى بسبب معوق، فالمطلوب استخلاص المعوق وهو الوقت ثم التغلب عليه بمواعيد مرنة."}},"m49vob":{"w":{"إرسال رسائل إيجابية دورية عن تقدم الطالب":"الرسائل الإيجابية الدورية حل لمعوق التجربة السلبية، فهي تكسر ربط التواصل بالمشكلات وتشجع الأسرة على التواصل مع المدرسة.","كتابة التقارير لأولياء الأمور بلغة بسيطة خالية من المصطلحات":"اللغة البسيطة في التقارير علاج لمعوق اللغة، فهي تجعل ولي الأمر يفهم مستوى ابنه وتقدمه، فلا تُعد معوقاً بل حلاً.","عقد مجالس أولياء الأمور في مواعيد مناسبة لظروف عملهم":"مراعاة ظروف العمل في المواعيد علاج لمعوق الوقت، فهي تزيد فرص حضور أولياء الأمور ولا تعيق التواصل معهم."},"e":"ربط التواصل بالمشكلات فقط يولّد لدى الأسرة تجربة سلبية فتتجنب المدرسة."},"11847ml":{"w":{"تخصيص الحصة لموعظة عن الإسراف بدل الدرس":"الموعظة تترك هدف الدرس جانباً، ومن ضوابط توظيف القضية ألا تتحول الحصة إلى موعظة، بل يستعمل الطلاب النسبة المئوية لفهم المشكلة.","ذكر القضية في التهيئة باختصار، ثم العودة إلى تمارين الكتاب المعتادة":"ذكر القضية في التهيئة ثم تركها لا يجعل الطلاب يستعملون النسبة المئوية في فهمها، والتوظيف المطلوب أن تصبح بياناتها مادة الحساب نفسه.","تكليف الطلاب بكتابة موضوع إنشائي عن أهمية المياه":"الموضوع الإنشائي نشاط لغوي لا يوظف النسبة المئوية، والمطلوب أن تخدم القضية هدف درس الرياضيات ببيانات حقيقية يحسب منها الطلاب."},"e":"مؤشر 3.3: يتقصى القضايا المحلية ويوظفها في التدريس بصورة تعزز وظيفة المعرفة؛ أي يستخدم الطالب المعرفة الرياضية لفهم مشكلة واقعية واقتراح حل."},"14bpf5b":{"w":{"أن تكون أكثر القضايا إثارة للجدل في وسائل التواصل الاجتماعي":"شهرة القضية وإثارتها للجدل ليستا معياراً لاختيارها، فالضابط أن ترتبط بهدف الدرس وتناسب عمر الطلاب وتخلو من التشهير.","أن يختارها الطلاب دون أي توجيه من المعلم":"المعلم هو من يتقصى القضية ويضمن ارتباطها بهدف الدرس ومناسبتها لأعمار الطلاب وخلوها من التشهير، وترك الاختيار بلا توجيه يُضيّع هذه الضوابط.","أن تكون بعيدة عن بيئة الطلاب وواقعهم حتى لا تحرج أحداً منهم":"القضية المحلية بطبيعتها من بيئة الطالب ليفهم بها واقعه، وتجنب الإحراج يتحقق بالخلو من التشهير لا بالابتعاد عن الواقع."},"e":"توظيف القضية يخدم الهدف التعليمي ويراعي المرحلة والقيم."},"o109qx09":{"w":{"يطلب من الأب توضيح ردة فعله التي يظن أنها الأنسب للتعامل مع الموقف.":"سؤال الأب عن ردة الفعل الأنسب ينقل اللقاء إلى الحلول مبكراً، وهي خطوة لاحقة تأتي بعد أن يعبّر عن رأيه ومشاعره وفهمه لما حصل.","يراجع مع الأب قوانين المدرسة والفصل التي خالفها ابنه في ذلك الموقف.":"مراجعة القوانين خطوة صحيحة في توقيت خاطئ، فالبدء بها يفترض ثبوت المخالفة والأب يرى أن العقوبة ظالمة، فيُسمع رأيه أولاً.","يصف للأب بالتفصيل وجهة نظره فيما يتعلق بالحادثة وأسباب ردة الفعل.":"عرض المعلم وجهة نظره بالتفصيل خطوة لاحقة، فالقاعدة مع ولي الأمر المنزعج الإنصات أولاً ثم العرض بعد معرفة رأيه وفهمه لما حصل."},"e":"الخطوة الأولى للتفاعل الإيجابي مع ولي الأمر هي السماح له بالتعبير عن رأيه ومشاعره تجاه المشكلة. (المعيار 3.2)"},"og8ycvb":{"w":{"تقديم معلومات لولي الأمر عن خدمات تدريس الطلاب ذوي صعوبات التعلّم.":"معلومات الخدمات عامة لا تجيب عن سؤال الأب عن ابنه، وتفترض وجود الصعوبة قبل أن يشخّصها المختص.","مناقشة عملية التدخلات النظامية ودور ولي الأمر في المراقبة والتقويم مع معلمه.":"مناقشة التدخلات تأتي بعد ثبوت الصعوبة، والتشخيص ليس من صلاحية معلم الصف، فالخطوة الأولى إحالة ولي الأمر إلى المختص.","توصية ولي الأمر بمراقبة أداء ابنه في واجباته المدرسية وعاداته السلوكية.":"التوصية بالمراقبة نصيحة عامة لا تجيب عن سؤال الأب هل يعاني ابنه صعوبة تعلم، والجواب المهني يحتاج تشخيص المختص لا رأي المعلم."},"e":"تشخيص صعوبات التعلم ليس من اختصاص معلم الصف، فالرد المهني إحالة ولي الأمر إلى المختص داخل المدرسة. (المعيار 3.2)"},"oxn6su9":{"w":{"مكافأة المعلمين الذين يستخدمون طرق تدريس فعّالة.":"المكافأة شأن إداري لتحفيز المعلمين، وهدف مجتمع التعلم المهني تحسين تعلم الطلاب بتبادل الإستراتيجيات لا مكافأة من يتميز.","التأكيد على أن بعض المعلمين يستخدمون طرقًا تدريسية أفضل من غيرهم.":"المقارنة بين المعلمين تناقض ثقافة التعاون، فاللقاء هنا لتبادل الإستراتيجيات حتى يصل التعليم المناسب إلى كل الطلاب لا لترتيب المعلمين.","استشارة بعضهم بعضًا وتبادل الآراء حول إزالة الشعور بالإحباط لديهم.":"تبادل الآراء حول الإحباط يجعل محور اللقاء مشاعر المعلمين، والسؤال يحدد موضوعه بإستراتيجيات تساعد الطلاب المتعثرين في الرياضيات."},"e":"هذا مجتمع تعلم مهني هدفه تحسين تعلم الطلاب بتبادل الإستراتيجيات. (المعيار 3.1)"},"o1f8vpbd":{"w":{"كتابة ملاحظات إيجابية وإرسالها لأولياء الأمور حول مدى تقدّم أبنائهم.":"الملاحظات الإيجابية تعزز العلاقة مع البيت، لكنها تواصل في اتجاه واحد من المعلم إلى ولي الأمر، والهدف هنا مناقشة وتبادل آراء.","ضمان استلام أولياء الأمور تقارير الأداء لأبنائهم وتوقيعها وإعادتها للمعلم.":"التقارير الموقّعة توضح مستوى الطالب وتثبت الاستلام لكنها لا تفتح نقاشاً، وتبادل الآراء يحتاج تواصلاً ثنائي الاتجاه كالاجتماع.","إلزام الطلاب بالمحافظة على دفتر المتابعة اليومية وتوقيعه من أولياء أمورهم.":"دفتر المتابعة ينقل ملاحظات يومية يكتفي ولي الأمر بتوقيعها، فهو تواصل في اتجاه واحد لا يحقق المناقشة التي يريدها المعلم."},"e":"الهدف «مناقشة وتبادل آراء» ولا يحققه إلا تواصل ثنائي الاتجاه كالاجتماع. (المعيار 3.2)"},"osuxb93":{"w":{"يطلب من الأب اقتراح العقوبة التي يرى أنها الأنسب للتعامل مع الموقف.":"طلب اقتراح العقوبة يفترض ثبوت المخالفة مسبقاً، والأب يرى أن ابنه عوقب ظلماً، فالبداية الصحيحة سماع رأيه وفهمه لما حصل.","يراجع مع الأب قوانين المدرسة التي قام ابنه بمخالفتها في ذلك الموقف.":"مراجعة القوانين في البداية تفترض ثبوت المخالفة، والأب يرى أن ابنه عوقب بغير عدل، فهي خطوة لاحقة تأتي بعد الإنصات له.","يصف المعلم وجهة نظره فيما يتعلق بالحادثة وأسباب ردة الفعل للأب بالتفصيل.":"البدء بوجهة نظر المعلم يقلب ترتيب المقابلة، فهي لسماع اعتراض الأب أولاً، ثم يأتي عرض المعلم بعد فهم رأيه ومشاعره."},"e":"الاستماع أولاً لولي الأمر يتيح فهم رأيه ومشاعره وتصحيح المفاهيم لدى الطرفين قبل أي نقاش، وهو مفتاح الدليلين (قياس 1436 والهيئة 1441). أما طلب اقتراح عقوبة أو مراجعة القوانين فيفترض ثبوت المخالفة مسبقاً، وعرض وجهة نظر المعلم أولاً يقلب ترتيب المقابلة. (المعيار القديم 10.2)"},"o8pktb":{"w":{"تقديم معلومات جاهزة لولي الأمر عن خدمات تدريس الطلبة ذوي صعوبات التعلّم ومصادر وبرامج متنوعة وإضافية موجودة على الإنترنت.":"المعلومات الجاهزة عامة لا تجيب عن سؤال الأب عن ابنه تحديداً، وتفترض وجود الصعوبة قبل أن يشخّصها المختص في المدرسة.","مناقشة عملية التدخلات النظامية ودور ولي الأمر في المراقبة والتقويم معك.":"التدخلات النظامية تُناقش بعد ثبوت الصعوبة، والتشخيص من اختصاص المختص لا معلم الصف، فالبداية اجتماع يضمه مع الإدارة وولي الأمر.","توصية ولي الأمر بمراقبة أداء ابنه في واجباته المدرسية وعاداته السلوكية باستمرار.":"التوصية بالمراقبة نصيحة عامة تترك سؤال الأب عن صعوبات ابنه بلا جواب، والجواب المهني يحتاج المختص في اجتماع منظم."},"e":"تشخيص صعوبات التعلم من اختصاص المختص، فالرد المهني هو ترتيب اجتماع يضم المختص والإدارة وولي الأمر. (المعيار القديم 10.2، صعوبة 0.325)"},"o1u4q9h7":{"w":{"تقارير فرديّة لتقدّم التعلّم للطلاب.":"التقارير الفردية بيانات خاصة بكل طالب تُرسل لولي أمره وحده، ونشرها في موقع يطلع عليه الجميع يمس خصوصية الطلاب.","الآراء الشخصية والمناظرات حول سياسة التعليم في المدرسة.":"الآراء الشخصية في سياسة المدرسة لا تليق بموقع صفي رسمي، فالموقع لنشر معلومات عامة تخص الفصل كالأنشطة والمواعيد.","نتائج اختبارات المنطقة لجميع مستويات المراحل الدراسية.":"نتائج اختبارات المنطقة تخص كل المراحل لا هذا الفصل، وموقع الصف ينشر معلومات عامة تخص طلابه كالأنشطة والمواعيد، لا نتائج اختبارات."},"e":"ما يُنشر للجميع يجب أن يكون معلومات عامة لا تمس خصوصية أحد، كأخبار الفصل والمواعيد. (المعيار القديم 10.2، صعوبة 0.408)"},"o1vfqt7m":{"w":{"اهتمام المثقفين بالمجلات والدوريات.":"الاهتمام ذُكر في الجملة الأولى فقط، وبقية النص تشرح «سر ذلك الشد»، والفكرة الرئيسة في نص يفسر ظاهرة هي السبب لا الظاهرة.","دور المجلات والدوريات في إبراز روائع التراث.":"النص لم يجعل للمجلات دوراً في إبراز التراث، بل ذكر أنها توقظ في المكتفي بالتراث التطلع إلى الإضافة والمعاصرة.","انقطاع صلة المثقفين بالتراث وانبهارهم بالمجلات.":"النص يذكر من يكتفي بروائع تراث أمته، فصلته بالتراث قائمة، والمجلات توقظ فيه التطلع إلى الإضافة، فالقول بالانقطاع يعارض النص."},"e":"النص بمجمله يفسر «سر» اهتمام المثقفين بالمجلات، فالفكرة الرئيسة هي السبب لا مجرد الاهتمام. (المعيار 4.1)"},"o18355d5":{"w":{"المعلم بقدرته على التوجيه والإشراف والقدوة هو محل الإبداع.":"النص يصف المتعلمين بأنهم المبدعون، وذكر المعلم جاء في جزئية «تحت توجيهات وإشراف المعلم»، ولم يذكر القدوة أصلاً.","أساليب التقويم وتطبيقاته حولت الاهتمام للتعلم المتمركز حول الطالب.":"النص يقول إن التقويم طُوّر «لتعكس هذا التوجه»، فهو نتيجة للنظرة الجديدة إلى المتعلم لا سبب لها، وجزئية لا فكرة رئيسة.","سلوك المواقف الحقيقية داخل حجرة الدراسة هو الموجه الحقيقي لإبداع.":"المواقف الحقيقية ذُكرت في وصف تطوير التقويم فقط، وهي جزئية فرعية، ولم يجعلها النص موجهاً للإبداع."},"e":"محور النص أن المتعلم مبدع يصنع بناءه المعرفي بنفسه، وما بعده تفاصيل تخدم هذه الفكرة. (المعيار القديم 2.1)"},"1gu1mq1":{"w":{"الدرجات كلها أصفار":"الانحراف الصفري يعني أن القيم متساوية أياً كانت قيمتها، فدرجات كلها 15 انحرافها صفر وليست أصفاراً.","المتوسط يساوي صفراً":"الانحراف يقيس تباعد الدرجات عن المتوسط لا قيمة المتوسط، فإذا كانت الدرجات كلها 15 كان الانحراف صفراً والمتوسط 15.","البيانات غير صحيحة":"الانحراف الصفري نتيجة ممكنة وصحيحة تحدث حين تتساوى القيم كلها، فلا يدل على خطأ في البيانات.","نصف الدرجات فوق المتوسط":"انعدام الانحراف يعني أن كل درجة تساوي المتوسط، فلا توجد درجة فوقه ولا دونه أصلاً.","التوزيع ملتوٍ التواءً موجباً":"الالتواء الموجب يحتاج تشتتاً تمتد فيه قلة نحو الدرجات العالية، والانحراف صفر يعني ألا تشتت إطلاقاً."}},"oudawes":{"w":{"34":"34 تعني خصم 6 ريالات، أي 15% فقط، والخصم 20% من 40 يساوي 8 ريالات، فالسعر 32.","36":"36 ناتج طرح 4 ريالات، أي خصم 10% فقط، والخصم 20% من 40 يساوي 8 ريالات، فالسعر 32.","38":"38 ناتج طرح ريالين فقط، والخصم 20% من 40 يساوي 8 ريالات، فالسعر 40 − 8 = 32."},"e":"الخصم = 20 ÷ 100 × 40 = 8 ريالات، فالسعر بعد الخصم = 40 − 8 = 32 ريالًا. (المعيار القديم 2.4)"},"y1c81p":{"w":{"سرعته ثابتة في جميع المراحل":"معدلات النمو مختلفة، سريعة في الطفولة المبكرة والمراهقة وبطيئة في الطفولة المتوسطة، والتراكمية تصف ترابط المراحل لا سرعتها.","يحدث في جميع الجوانب بالدرجة نفسها":"جوانب النمو متكاملة لكنها تختلف في مقدارها وسرعتها، والتراكمية تعني أن اللاحق يُبنى على السابق لا أن الجوانب تتساوى.","لا تتدخل فيه الوراثة":"النمو محصلة تفاعل الوراثة والبيئة معاً، والتراكمية وصف لبناء المراحل بعضها على بعض لا حديث عن مصدر النمو."},"e":"التراكمية والتتابع تعنيان أن المراحل مترابطة."},"pfzus7":{"w":{"الابتدائية الدنيا":"الصفوف الأولية طفولة متوسطة يغلب عليها الفضول وكثرة الأسئلة والتعلم بالمحسوسات، أما أحلام اليقظة والاستقلال فمن سمات المراهقة المبكرة.","الابتدائية العليا":"الصفوف العليا طفولة متأخرة تتسم بروح الجماعة وزيادة المفردات، أما كثرة أحلام اليقظة والسعي إلى الاستقلال فتظهر مع المراهقة المبكرة.","الروضة":"طفل الروضة في مرحلة اللعب والرموز مع التمركز حول الذات، أما أحلام اليقظة والاستقلال والانتماء القوي للرفاق فمن سمات المراهقة المبكرة."},"e":"أحلام اليقظة والاستقلال والانتماء للرفاق سمات المراهقة المبكرة (المتوسطة)."},"e15k7q":{"w":{"أن يتجاوز الطفل سن الحادية عشرة":"ربط تعلم المفهوم المعقد بسن معينة أقرب إلى مراحل بياجيه، أما برونر فيرى إمكان تعليمه لأي طفل بصورة أمينة تناسب تمثيله.","أن يتعلمه بالتلقين والتكرار":"التلقين والتكرار ينقلان العبارة دون بناء المفهوم، وشرط برونر صورة أمينة للمفهوم تناسب تمثيل الطفل عملياً أو أيقونياً أو رمزياً.","أن يُقدَّم رمزياً دائماً":"التمثيل الرمزي أعلى أنماط برونر الثلاثة، والطفل الصغير يناسبه غالباً العملي أو الأيقوني، فالشرط ملاءمة التمثيل للطفل لا الرمزية."}},"191b73e":{"w":{"ثورندايك":"ثورندايك صاحب المحاولة والخطأ وقوانين الأثر والتدريب، ويفسر التعلم بالربط بين المثير والاستجابة لا بمراحل يبني فيها الطفل مفاهيمه.","باندورا":"باندورا صاحب التعلم الاجتماعي بالملاحظة والنمذجة، ونظريته تفسر اكتساب السلوك من القدوة لا تطور مفاهيم الزمن والمكان والعدد.","سكنر":"سكنر صاحب الإشراط الإجرائي والتعزيز، ويفسر التعلم بتشكيل السلوك الظاهر لا ببناء الطفل مفاهيم الزمن والمكان والعدد عبر مراحل نمائية."},"e":"بياجيه رائد نظرية النمو المعرفي ودرس كيف يبني الطفل مفاهيم العدد والزمن والمكان والسببية."},"5vpkw3":{"w":{"الاحتفاظ":"الاحتفاظ إدراك أن الكمية لا تتغير بتغير شكلها ويظهر في العمليات المحسوسة، أما البحث عن اللعبة المخفية فيدل على إدراك وجودها رغم غيابها.","المعكوسية":"المعكوسية قدرة ذهنية على عكس العملية والرجوع إلى الحالة الأولى في المحسوسة، والموقف هنا بحث عن شيء غاب عن البصر لا عكس لعملية.","التمركز حول الذات":"التمركز حول الذات عجز عن رؤية الأشياء من منظور الآخر في ما قبل العمليات، والطفل هنا يُظهر إدراك بقاء الشيء رغم اختفائه."},"e":"البحث عن الشيء المخفي يعني إدراك أنه موجود رغم غيابه عن البصر؛ وهذا دوام الشيء، يبدأ نحو 8–12 شهراً ويكتمل في نهاية الحس-حركية."},"8pvm7r":{"w":{"الطلاب يفتقرون إلى الدافعية":"عجز معظم الصف عن سؤال «ماذا لو» يرجع إلى حدود مرحلتهم، فالتفكير الافتراضي من العمليات المجردة، ومشكلتهم هنا ليست الدافعية.","المعلم لم يستخدم التعزيز الكافي":"التعزيز يزيد تكرار سلوك يقدر عليه الطالب أصلاً، وتصور الافتراضات الخيالية يحتاج تفكيراً مجرداً لم يبلغه طالب الثالث بعد.","الطلاب لم يحفظوا قانون الجاذبية":"حفظ القانون لا يمنح القدرة على تخيل عالم افتراضي، فسؤال «ماذا لو» يتطلب تفكيراً مجرداً يتجاوز مرحلة العمليات المحسوسة."},"e":"التفكير في الافتراضات الخيالية (ماذا لو) من سمات العمليات المجردة، وطلاب الثالث الابتدائي في المحسوسة."},"w5ia55":{"w":{"اضطراب سلوكي يستدعي الإحالة":"المجادلة والتأثر بالأقران سلوك متوقع في المراهقة المبكرة، والإحالة تكون لتغير مفاجئ أو مؤشرات اضطراب، لا لسلوك طبيعي يُحتوى بالحوار.","ضعف في الانتباه":"ضعف الانتباه يظهر في التشتت وصعوبة متابعة المهام، أما رفض النصائح والمجادلة وطلب موافقة الأقران فتعبير عن السعي إلى الاستقلال في المراهقة.","نقص في مطالب نمو الطفولة المتوسطة":"مطالب الطفولة المتوسطة عند هافجهرست كالقراءة والحساب واللعب الجماعي تخص الابتدائية، وطالب الثاني المتوسط في المراهقة ومطلبها الاستقلال."},"e":"المجادلة والاستقلال والتأثر بالأقران من خصائص المراهقة المبكرة (أزمة الهوية)."},"fekw5a":{"w":{"القانون والنظام (التقليدي)":"مرحلة القانون والنظام تلتزم بالقاعدة لأنها تحفظ النظام، كقول «نظام المدرسة يمنعه»، والطالب هنا يربط امتناعه بالخوف من عقاب المعلم.","العقد الاجتماعي (ما بعد التقليدي)":"العقد الاجتماعي يرى القوانين اتفاقاً لخدمة مصلحة الجماعة يُحترم ويُعدَّل بالتوافق، وتبرير الطالب هنا لا يتجاوز تجنب العقاب الشخصي.","الولد الطيب (التقليدي)":"مرحلة الولد الطيب يتصرف فيها الطالب لينال رضا الآخرين، كقول «حتى لا يزعل أبي»، والطالب هنا لا يذكر رضا أحد بل يخشى العقاب."},"e":"ربط الصواب بتجنب العقاب هو المرحلة الأولى من المستوى ما قبل التقليدي."},"vl7ui6":{"w":{"يجنّبه العقاب":"الحكم على الصواب بتجنب العقاب هو المرحلة الأولى في المستوى ما قبل التقليدي، أما الثالثة فمعيارها رضا الآخرين وموافقتهم.","يحقق له منفعة مقابل منفعة":"تبادل المنفعة هو المرحلة الثانية، المصلحة المتبادلة، في المستوى ما قبل التقليدي، والثالثة تنتقل إلى طلب رضا الآخرين وصورة الولد الطيب.","يتفق مع مبادئ العدل العامة":"الاحتكام إلى مبادئ العدل العامة هو المرحلة السادسة، المبادئ العالمية، وهي أعلى مراحل كولبرج، أما الثالثة فتقيس الصواب بموافقة المحيطين."},"e":"المرحلة الثالثة «الولد الطيب»: الصواب ما يرضي المحيطين ويكسب موافقتهم."},"1qn1z69":{"w":{"الفمية":"الفمية أولى مراحل فرويد في سن الرضاعة وتتركز فيها اللذة حول الفم، أما سن الابتدائية فيوافق الكمون الذي تهدأ فيه الدوافع.","القضيبية":"القضيبية تسبق المدرسة من 3 إلى 6 سنوات، وتليها مرحلة الكمون التي توافق الابتدائية وتهدأ فيها الدوافع ويتجه الطفل إلى التعلم.","التناسلية":"التناسلية تبدأ مع البلوغ في المراهقة وتعود فيها الدوافع إلى النشاط، بينما سن الابتدائية يوافق هدوءها في مرحلة الكمون."},"e":"مرحلة الكمون (6–12) فيها تهدأ الدوافع ويتجه الطفل إلى التحصيل والصداقات."},"1t9l77f":{"w":{"الهو":"الهو مستودع الدوافع الغريزية ويعمل وفق مبدأ اللذة طلباً للإشباع الفوري، أما الضمير والمثل العليا فمكانهما الأنا الأعلى.","الأنا":"الأنا يعمل وفق مبدأ الواقع ويوازن بين مطالب الهو وقيود الأنا الأعلى، فهو الوسيط المنظم لا مصدر الضمير والقيم.","الليبيدو":"الليبيدو عند فرويد الطاقة النفسية للدوافع الغريزية، وليس أحد مكونات الشخصية الثلاثة، والضمير والمثل العليا يمثلها الأنا الأعلى."},"e":"الأنا الأعلى يحمل القيم والضمير المكتسبة من الوالدين."},"1ihq78d":{"w":{"اختيار المهنة والاستعداد لها":"اختيار المهنة من مطالب المراهقة عند هافجهرست، أما مطالب الطفولة المتوسطة فالقراءة والكتابة والحساب واللعب الجماعي وتكوين الضمير.","الاستقلال الانفعالي عن الوالدين":"الاستقلال الانفعالي عن الوالدين مطلب من مطالب المراهقة، وطفل الطفولة المتوسطة مطالبه المهارات الأساسية في القراءة والحساب واللعب.","تقبل التغيرات الجسمية للبلوغ":"تقبل التغيرات الجسمية مطلب يرتبط بالبلوغ في المراهقة، أما مطالب الطفولة المتوسطة فالمهارات الأساسية كالقراءة والحساب واللعب الجماعي."},"e":"القراءة والكتابة والحساب ومهارات اللعب مطالب الطفولة المتوسطة."},"15ssquu":{"w":{"المركزي–الطرفي":"المركزي–الطرفي يصف النمو من محور الجسم نحو الأطراف، كالتحكم في الذراع قبل الأصابع، والسؤال يصف تقدماً من الرأس إلى القدمين.","من العام إلى الخاص":"هذا الاتجاه يصف الحركات الكلية قبل الدقيقة، كالقبض بالكف قبل الالتقاط بإصبعين، لا ترتيب التحكم من الرأس نزولاً إلى القدمين.","من الخاص إلى العام":"النمو يسير من العام إلى الخاص لا العكس، فالحركة الكلية تسبق الدقيقة، والسؤال أصلاً يصف اتجاهاً من الرأس إلى القدمين."},"e":"الرأسي–الذيلي يصف تقدم النمو من الرأس إلى الأسفل."},"5u13yh":{"w":{"التعلم":"التعلم تغير ناتج عن الخبرة والتدريب، والسؤال يصف تغيراً بيولوجياً يحدث تلقائياً دون تدريب ويسبق التعلم بوصفه شرطاً له.","الانتقال":"الانتقال يرد في علم النفس التربوي بمعنى انتقال أثر التعلم من موقف إلى آخر، لا تغيراً بيولوجياً تلقائياً يحدد استعداد الطفل.","التكيف":"التكيف عند بياجيه تمثل ومواءمة يتفاعل بهما الطفل مع البيئة بالخبرة، لا تغير داخلي يحدث تلقائياً دون تدريب."},"e":"النضج تغير داخلي لا يحتاج خبرة."},"1nkxdwk":{"w":{"يسير من العام إلى الخاص":"اتجاه النمو من الحركات الكلية إلى الدقيقة مبدأ صحيح، كالقبض بالكف قبل الالتقاط بإصبعين، فليس هو الاستثناء المطلوب.","يتأثر بتفاعل الوراثة والبيئة":"النمو فعلاً محصلة تفاعل الوراثة والبيئة، وهذا من مبادئه، فالمستثنى هو القول بمعدل واحد لأن سرعته تختلف بين المراحل.","مظاهره متكاملة يؤثر بعضها في بعض":"جوانب النمو الجسمية والعقلية والانفعالية والاجتماعية متكاملة فعلاً يؤثر بعضها في بعض، فهو مبدأ صحيح وليس الاستثناء المطلوب."},"e":"النمو مستمر لكن بمعدلات متفاوتة: سريع في الطفولة المبكرة والمراهقة وبطيء في الطفولة المتوسطة."},"cl9czc":{"w":{"التمركز حول الذات":"العجز عن رؤية الأشياء من منظور الآخر سمة أساسية لمرحلة ما قبل العمليات فعلاً، فهو من خصائصها وليس الاستثناء.","الإحيائية":"الإحيائية، أي نسبة الحياة والمشاعر إلى الجمادات، من سمات ما قبل العمليات فعلاً، فلا تكون هي المستثناة.","ظهور اللغة واللعب الرمزي":"الوظيفة الرمزية من لغة ولعب إيهامي هي أبرز إنجازات ما قبل العمليات فعلاً، فهي من خصائصها لا الاستثناء."},"e":"الاحتفاظ والمعكوسية إنجازا مرحلة العمليات المحسوسة لا ما قبلها."},"pkz85v":{"w":{"الثقة مقابل عدم الثقة":"هذه أولى أزمات إريكسون الثماني في سن الرضاعة، حين يبني الطفل ثقته بمن يرعاه، فهي من أزماته فعلاً وليست المستثناة.","المبادرة مقابل الذنب":"هذه أزمة إريكسون في سن ما قبل المدرسة من 3 إلى 6 سنوات، فهي من أزماته الثماني فعلاً وليست الاستثناء.","الإنتاجية مقابل الركود":"هذه أزمة منتصف العمر عند إريكسون، فهي من أزماته الثماني فعلاً، أما الاحتفاظ والتمركز فمفهومان عند بياجيه."},"e":"الاحتفاظ والتمركز مفهومان عند بياجيه لا أزمتان عند إريكسون."},"1m4j0nk":{"w":{"التقلب الانفعالي":"التقلب الانفعالي من أبرز سمات المراهقة فعلاً مع تغيرات البلوغ، فهو من خصائصها وليس الاستثناء المطلوب.","الاهتمام بالمظهر وصورة الذات":"عناية المراهق بمظهره وصورته أمام نفسه وأقرانه سمة معروفة تصاحب تغيرات البلوغ وتكوين الهوية، فليست هي الاستثناء.","الميل إلى المثالية ونقد الكبار":"المثالية ونقد الكبار من سمات المراهقة فعلاً مع اكتمال التفكير المجرد وتكوين الهوية، فهي من خصائصها لا الاستثناء."},"e":"المراهقة تتميز بطفرة نمو جسمي سريعة لا ببطئه."},"t4s4y3":{"w":{"التفكير الحسي الحركي":"الحسي الحركي تفكير الرضيع من الولادة إلى سنتين، يعرف العالم بحواسه وحركته، ولا يضع فروضاً يختبرها ذهنياً كطالب الثانوي.","التفكير ما قبل الإجرائي":"ما قبل الإجرائي تفكير الطفل من 2 إلى 7 سنوات، يعتمد على الرموز والإدراك المباشر، ولا يقدر على وضع الفروض واختبارها ذهنياً.","التفكير المتمركز حول الذات":"التمركز حول الذات عجز عن رؤية منظور الآخر في ما قبل العمليات، أما وضع الفروض واختبارها عقلياً فجوهر العمليات المجردة."},"e":"وضع الفروض واختبارها عقلياً جوهر العمليات المجردة (وتسمى أيضاً العمليات الشكلية أو الصورية)."},"1pf8hr2":{"w":{"سلوك عدواني يحتاج تعديلاً":"العدوان قصد إيذاء الآخرين، والرضيع هنا يرمي الأشياء ويتذوقها ليتعرف خصائصها، فهو استكشاف طبيعي للمرحلة الحس-حركية لا يحتاج تعديلاً.","تعلم بالملاحظة":"التعلم بالملاحظة عند باندورا اكتساب السلوك بمشاهدة نموذج وتقليده، والسؤال يصف رضيعاً يتعرف الأشياء بفعله المباشر بالحواس والحركة.","مظهر لفرط الحركة":"فرط الحركة اضطراب يُحكم عليه بنشاط زائد عن المعتاد لعمر الطفل، ورمي الأشياء وتذوقها سلوك معتاد عند الرضع يتعرفون به ما حولهم."},"e":"الرضيع يعرف العالم بالحواس والأفعال الحركية؛ الرمي والتذوق استكشاف طبيعي."},"16ujwib":{"w":{"الأولاد يسبقون البنات بنحو سنتين":"الثابت عكس ذلك، فالبنات يبدأن طفرة البلوغ قبل الأولاد بنحو سنة إلى سنتين، ولهذا تكون كثيرات منهن أطول من الأولاد في مثل سنهن آخر الابتدائية.","الجنسين يبلغان في السن نفسها":"موعد البلوغ يختلف بين الجنسين، فطفرة النمو عند البنات أبكر بنحو سنة إلى سنتين، وهذا يفسر تفاوت الأحجام في الصفوف العليا.","لا علاقة للجنس بموعد البلوغ":"الجنس من أوضح العوامل المؤثرة في موعد البلوغ، فالبنات يسبقن الأولاد عادة بنحو سنة إلى سنتين مع وجود فروق فردية."}},"qowfqw":{"w":{"الحس-حركية":"الحس-حركية مرحلة الرضيع حتى سنتين، يتعرف فيها العالم بالحواس والحركة ويكتسب دوام الشيء، أما اللغة واللعب الإيهامي فإنجاز المرحلة التالية.","العمليات المحسوسة":"العمليات المحسوسة من 7 إلى 11 يكتسب فيها الطفل الاحتفاظ والمعكوسية، والسؤال يصف مرحلة يغيب فيها الاحتفاظ، فهي سابقة لها.","العمليات المجردة":"العمليات المجردة من 11 فأكثر أبرز ما فيها التفكير الافتراضي، والاحتفاظ مكتسب قبلها، فلا توصف بغيابه ولا باللعب الإيهامي."}},"p04uid":{"w":{"شرح تعريف الكسر لفظياً ثم حل تمارين مجردة":"التجريد اللفظي يناسب من بدأ التفكير المجرد في المتوسطة وما بعدها، وطالب الثالث في المحسوسات يحتاج أن يرى الأجزاء ويقسمها بيده.","عرض قاعدة عامة واستنباط الأمثلة منها":"الانطلاق من قاعدة عامة إلى أمثلتها استنباط يناسب التفكير المجرد، وطالب الثالث يحتاج أن يبدأ من أشياء محسوسة يقسمها بنفسه.","طلب تخيّل الكسر ذهنياً دون أدوات":"تخيّل الكسر ذهنياً بلا أدوات يتخطى التعامل اليدوي، وطالب العمليات المحسوسة يفهم الكسور حين يقسم أشياء حقيقية بيده أولاً."},"e":"طالب الثالث في المحسوسات، فالتعامل اليدوي مع المواد (التمثيل العملي عند برونر) هو الأنسب."},"1ufwiq6":{"w":{"التعزيز":"التعزيز مفهوم سلوكي عند سكنر يزيد تكرار الاستجابة، أما رابع عوامل بياجيه فالموازنة التي تعيد التوازن العقلي بين التمثل والمواءمة.","النمذجة":"النمذجة تعلم بمشاهدة نموذج وتقليده في نظرية باندورا الاجتماعية، وليست من عوامل النمو المعرفي الأربعة عند بياجيه.","الاستبصار":"الاستبصار إدراك مفاجئ للعلاقات في الموقف عند الجشطلت، كتجارب كوهلر على القردة، وليس من عوامل بياجيه التي رابعها الموازنة."},"e":"الموازنة هي العامل الرابع الذي ينظم التمثل والمواءمة عند بياجيه."},"6s60n4":{"w":{"جان جاك روسو":"روسو يرى الطفل يولد خيّراً بطبعه وينمو نمواً طبيعياً حراً يفسده المجتمع، لا عقلاً فارغاً تكتبه الخبرة كما في رأي المعلم.","جان بياجيه":"بياجيه يرى الطفل يبني معرفته بنشاطه في مراحل نمائية ثابتة الترتيب، لا عقلاً سلبياً فارغاً تنقش عليه الخبرات الحسية معارفه.","سيجموند فرويد":"فرويد فسر الشخصية بالدوافع اللاشعورية ومراحل النمو النفسي الجنسي، أما فكرة الصفحة البيضاء التي تكتبها الخبرة فتعود إلى جون لوك."},"e":"قال جون لوك إن العقل يولد صفحة بيضاء تكتب عليها الخبرة، فأكد أثر البيئة والتعليم والحواس."},"1bcombd":{"w":{"الإسقاط":"الإسقاط أن ينسب الفرد مشاعره أو عيوبه إلى غيره، أما سلوك الطالب هنا فتفريغ لغضبه في هدف أضعف من مصدره.","التبرير":"التبرير اختلاق أسباب مقبولة لتسويغ السلوك، والسؤال لا يذكر تسويغاً، بل غضباً من المعلم أُفرغ في هدف أضعف بلا سبب.","النكوص":"النكوص رجوع إلى سلوك مرحلة عمرية سابقة كمص الإصبع، أما الطالب هنا فنقل غضبه من المعلم إلى زميل أصغر منه."},"e":"الإزاحة (النقل) توجيه الانفعال من مصدره الأصلي الذي يصعب مواجهته إلى هدف أضعف أو أكثر أماناً. وحيل الدفاع أساليب لا شعورية لخفض القلق وصفها فرويد وفصّلتها ابنته آنا فرويد."},"2eozvz":{"w":{"الإزاحة":"الإزاحة تفريغ الانفعال في هدف أضعف من مصدره، أما الطالب هنا فينسب كراهيته هو إلى زميله فيدّعي أن زميله يكرهه.","التعويض":"التعويض سد نقص يشعر به الفرد بالتفوق في مجال آخر، والسؤال لا يصف نقصاً ولا تفوقاً بل نسبة الكراهية إلى الزميل.","التسامي":"التسامي توجيه دافع غير مقبول إلى نشاط مقبول اجتماعياً، والسؤال لا يذكر نشاطاً بديلاً، بل نسبة الطالب كراهيته إلى زميله."},"e":"الإسقاط أن ينسب الفرد إلى غيره مشاعر أو عيوباً يرفض الاعتراف بها في نفسه، فالطالب نسب كراهيته إلى زميله."},"tqiuwo":{"w":{"التسامي":"التسامي تحويل دافع غير مقبول اجتماعياً كالعدوان إلى نشاط مقبول، والسؤال لا يذكر دافعاً كهذا بل نقصاً في التحصيل غطّاه بالتفوق الرياضي.","الإسقاط":"الإسقاط أن ينسب الفرد مشاعره أو عيوبه إلى غيره، والسؤال يصف طالباً يغطي تأخره الدراسي بالتفوق في مجال آخر.","الإزاحة":"الإزاحة تفريغ الانفعال في هدف أضعف من مصدره، والسؤال لا يصف غضباً منقولاً بل جهداً يسد به الطالب نقصه بالتفوق الرياضي."},"e":"التعويض أن يغطي الفرد نقصاً يشعر به في مجال بالتفوق في مجال آخر."},"yxuxrx":{"w":{"التعويض":"التعويض سد نقص يشعر به الفرد بالتفوق في مجال آخر، والسؤال لا يذكر نقصاً بل اندفاعاً عدوانياً وُجّه إلى نشاط منظم مقبول.","الإزاحة":"الإزاحة تنقل الانفعال إلى هدف أضعف من مصدره دون أن يصير نشاطاً مقبولاً، والطالب هنا حوّل اندفاعه إلى تدريب منظم يحقق فيه إنجازات.","التبرير":"التبرير اختلاق أسباب مقبولة لتسويغ السلوك، والسؤال لا يذكر تسويغاً للعراك، بل تحويل الاندفاع إلى رياضة منظمة مقبولة اجتماعياً."},"e":"التسامي (ويسمى الإعلاء) تحويل دافع غير مقبول اجتماعياً كالعدوان إلى نشاط مقبول ومفيد، ويُعد من أنضج حيل الدفاع."},"16uyigp":{"w":{"مناقشة ظروفه الأسرية أمام زملائه ليتعاطفوا معه ويدعموه":"ظروف الطالب الأسرية من خصوصياته، وكشفها أمام زملائه ينتهك السرية وقد يحرجه ولو قُصد التعاطف، والمطلوب حوار فردي هادئ.","خصم درجات المشاركة لتحفيزه على الانتباه":"تراجع الطالب مرتبط بحدث أسري ضاغط، والعقاب بخصم الدرجات يزيد الضغط عليه ولا يعالج سبب شروده وانطوائه.","الانتظار حتى نهاية الفصل لعل الحالة تتحسن":"التغير المفاجئ في التحصيل والسلوك علامة تحذيرية تستدعي تدخلاً مبكراً، والتأجيل حتى نهاية الفصل قد يفاقم المشكلة ويضيّع وقت الدعم."},"e":"مؤشر 5.1: يبين تأثير الأحداث اليومية الضاغطة على التعلم وكيفية التعامل معها؛ البداية احتواء فردي يحفظ السرية ثم الإحالة للمختص."},"1l5au06":{"w":{"حماس الطالب الزائد في الأنشطة الجماعية وحرصه على المشاركة":"الحماس للأنشطة الجماعية والحرص على المشاركة من مظاهر الاندماج، ولا يدل على حدث ضاغط ما لم يكن تغيراً مفاجئاً عن حال الطالب السابقة.","ميل طالب المرحلة المتوسطة إلى الأقران وتأثره بآرائهم":"الميل إلى الأقران والتأثر بهم سلوك نمائي طبيعي في المراهقة المبكرة، والعلامة التحذيرية تغير مفاجئ عن حال الطالب لا سلوك متوقع لمرحلته.","كثرة أسئلة طفل الصفوف الأولية":"كثرة الأسئلة من سمات الطفولة المتوسطة التي يغلب عليها الفضول، فهي سلوك نمائي طبيعي لا علامة على تأثر بحدث ضاغط."},"e":"العلامة التحذيرية هي التغير المفاجئ عن المعتاد."},"1422m6e":{"w":{"تكليفه بتقديم نفسه أمام الصف كاملاً في أول حصة يحضرها":"الطالب القلق المعزول يحتاج إشراكاً متدرجاً، ووضعه أمام الصف كله في أول حصة قد يزيد قلقه بدل أن يساعده على الاندماج.","تركه حتى يتكيف وحده دون تدخل":"الانتقال حدث ضاغط، وقلق الطالب وعزلته في الفسحة يستدعيان دعماً بالتعريف والزميل المرافق، وتركه وحده قد يطيل عزلته.","إحالته مباشرة إلى لجنة التوجيه الطلابي بوصفه حالة سلوكية":"قلق الطالب المنتقل حديثاً استجابة متوقعة لحدث ضاغط لا مشكلة سلوكية، والإحالة المباشرة سابقة لأوانها قبل الدعم الصفي والزميل المرافق."},"e":"الانتقال حدث ضاغط شائع؛ والدعم يكون بالتعريف والزميل المرافق والإشراك المتدرج."},"fi9lio":{"w":{"كثرة الحركة في الفصل وحب الكلام":"النشاط الحركي والكلام الكثير سلوك شائع عند الأطفال قد يكون نمائياً، ولا صلة له بحرمان الطالب من حاجاته الأساسية كالغذاء والنظافة والرعاية الصحية.","تفوق دراسي مع خجل اجتماعي بسيط":"الخجل البسيط سمة شخصية شائعة، والتفوق دليل تحصيل جيد، وليس في المجموعة ما يشير إلى نقص في الغذاء أو النظافة أو الرعاية.","انشغال بالأقران وتغير الاهتمامات والمزاج في مرحلة المراهقة":"الانشغال بالأقران وتقلب المزاج والاهتمامات من خصائص المراهقة الطبيعية، والإهمال تدل عليه علامات الحرمان من الحاجات الأساسية كالجوع وسوء النظافة."},"e":"الإهمال عدم توفير حاجات الطالب الأساسية أو التقصير فيها (الجسدية والصحية والعاطفية والتعليمية...) كما عرفته قواعد السلوك والمواظبة، وعلاماته تتعلق بهذه الحاجات."},"1r7pvyq":{"w":{"المشرف التربوي للمادة في مكتب التعليم":"المشرف التربوي يتابع تدريس المادة وتطوير أداء المعلم، وحالة الإيذاء العاجلة تُبلَّغ فوراً إلى مركز البلاغات 1919 بنص المادة 29.","مجلس أولياء الأمور والمعلمين في المدرسة":"المجلس إطار للتعاون والتواصل بين المدرسة والأسر، وحالة الإيذاء العاجلة سرية تُبلَّغ فوراً إلى مركز البلاغات 1919 لا إلى مجلس.","لجنة التحصيل الدراسي بالمدرسة لدراسة الحالة":"لجنة التحصيل تعنى بالمستوى الدراسي للطلاب، والإيذاء العاجل لا ينتظر دراسة داخلية بل يُبلَّغ فوراً إلى مركز البلاغات 1919."}},"1f06w3n":{"w":{"تبدأ بالتنبيه الشفهي ثم تتدرج كالمخالفات السلوكية":"التدرج من التنبيه فما بعده خاص بالمخالفات السلوكية، أما الإيذاء والإهمال فنصت المادة 29 على أن إجراءاتهما لا تتدرج بل تتبع خطورة الحالة.","يتولاها المعلم وحده دون إشراك الإدارة":"دور المعلم أن يلاحظ ويوثق ويبلغ مدير المدرسة فوراً، ثم تتولى لجنة التوجيه الطلابي الحالة، فالمعلم لا يحقق فيها وحده.","تؤجَّل إلى نهاية الفصل لجمع أدلة كافية":"إجراءات الإيذاء عاجلة لضمان سلامة الطالب ومنع تفاقم الحالة، والمعلم يبلغ بما لاحظه ووثقه دون أن يؤجل لجمع أدلة أو التحقيق."}},"13fdibx":{"w":{"الاستعداد":"الاستعداد قدرة كامنة تمكّن الفرد من التعلم لاحقاً، والمعلم هنا قاس زمناً فعلياً بين ظهور المثير وبدء الاستجابة.","الاتجاه":"الاتجاه جانب وجداني يُقاس عادة بمقياس من موافق بشدة إلى غير موافق بشدة، والمعلم هنا قاس زمناً بين المثير والاستجابة.","الميل":"الميل جانب وجداني يعبّر عن انجذاب الفرد إلى نشاط يحبه، ولا يُقاس بحساب الزمن بين المثير وبدء الاستجابة."},"e":"زمن الرجع هو الفترة بين المثير وبدء الاستجابة وهو من الفروق الفردية القابلة للقياس."},"159zls6":{"w":{"ثانوية":"الصعوبات الثانوية في تصنيف كيرك وكالفانت (التفكير واللغة الشفهية) تنشأ عن خلل الأولية فهي نتيجة له، والسؤال عن الخلل في العمليات الأساسية نفسها. والتدني بسبب سوء التعليم أو الحرمان البيئي لا يُسمى صعوبة تعلم أصلاً.","أكاديمية":"الصعوبات الأكاديمية تخص القراءة والكتابة والحساب، أما السؤال فيصف خللاً في العمليات النفسية الأساسية نفسها كالانتباه والذاكرة.","مؤقتة":"وصف الصعوبة بالمؤقتة يتعلق بمدتها لا بمصدرها، والسؤال يصنفها بمصدرها: خلل داخلي في العمليات النفسية الأساسية نفسها."},"e":"الصعوبات الأولية تعود إلى اضطراب داخلي في العمليات النفسية الأساسية نفسها (الانتباه والإدراك والذاكرة). أما التدني الناتج عن سوء التعليم أو الحرمان البيئي فمستبعد أصلاً من صعوبات التعلم (محك الاستبعاد)."},"19unzib":{"w":{"التعلم للإتقان":"التعلم للإتقان يمنح كل طالب الزمن والتصحيح حتى يبلغ مستوى الإتقان، والمعلمة هنا نوّعت المحتوى وأتاحت اختيار المنتج.","التعليم المبرمج":"التعليم المبرمج يقدّم المادة في خطوات صغيرة متتابعة يسير فيها الطالب بسرعته، والمعلمة هنا نوّعت المصادر وأتاحت اختيار المنتج.","التعلم التعاوني":"التعلم التعاوني يقوم على عمل الطلاب في مجموعات صغيرة باعتماد متبادل، والموقف لا يذكر مجموعات بل تنويع المحتوى واختيار المنتج."},"e":"هدف واحد مع تنويع المحتوى والعملية والمنتج وفق الاستعداد والاهتمام هو التمايز (توملينسون)."},"g1j7ga":{"w":{"التعجيل":"التعجيل يغيّر مستوى الموهوب أو زمن دراسته بقبول مبكر أو تخطي صف أو ضغط منهج، والمعلم هنا يريد إبقاءهم في صفهم.","التجميع":"التجميع يضع الموهوبين في مجموعات خاصة بهم بعيداً عن زملائهم، والمعلم هنا يريد بقاءهم في صفهم مع تعميق خبراتهم.","الدمج الجزئي":"الدمج الجزئي نوع من دمج ذوي الإعاقة مع العاديين في بعض المواد، والسؤال عن تعميق خبرات الموهوبين وتوسيعها داخل صفهم."},"e":"الإثراء يعمّق (رأسي) أو يوسّع (أفقي) الخبرة داخل الصف نفسه."},"1c6eicf":{"w":{"تكليف الطالب بتمارين إضافية من النوع نفسه":"زيادة التمارين من النوع نفسه لا تغيّر زمن التعلم ولا مستواه، وهي خطأ شائع يزيد ملل الموهوب، أما التعجيل فيختصر الزمن.","جعل الطالب مساعداً للمعلم":"جعله مساعداً للمعلم يشغل وقته دون تقدم في تعلمه، والتعجيل يعني اجتياز المنهج أو الصف في زمن أقل من المعتاد.","إعفاؤه من الواجبات":"الإعفاء من الواجبات ينقص تعلمه ولا يسرّعه، وصور التعجيل القبول المبكر وتخطي الصف وضغط المنهج في زمن أقل."},"e":"ضغط المنهج يعني دراسة المادة في زمن أقل من المعتاد، وهذا من صور التعجيل نصاً في دليل الاختبار العام للمعلمين (قياس 1436، السؤال 13)، ومثله النقل إلى صف أعلى والقبول المبكر. أما التمارين المكررة وجعله مساعداً للمعلم وإعفاؤه من الواجبات فلا تختصر زمن التعلم، وهي ممارسات خاطئة مع الموهوب."},"u593w":{"w":{"الذكاء والتحصيل والوراثة":"التحصيل المرتفع ليس من حلقات رنزولي الثلاث، والنموذج لا يكتفي بالذكاء بل يضيف إليه الإبداع والالتزام بالمهمة.","الطلاقة والمرونة والأصالة":"الطلاقة والمرونة والأصالة مكونات الإبداع وحده، وهو حلقة واحدة من ثلاث عند رنزولي مع القدرة والالتزام بالمهمة.","الذاكرة والانتباه والإدراك":"الذاكرة والانتباه والإدراك عمليات معرفية أساسية تُذكر في صعوبات التعلم النمائية، لا حلقات الموهبة عند رنزولي."},"e":"حلقات رنزولي: قدرة فوق المتوسط، إبداع، التزام بالمهمة (الدافعية)."},"1m9yzy9":{"w":{"تكليفه بحل المزيد من التمارين نفسها":"التمارين المكررة من النوع نفسه لا تقدّم تحدياً جديداً، فتزيد ملل الموهوب الذي ينهي المهام قبل زملائه.","معاقبته على الإزعاج":"العقاب يعالج الإزعاج الظاهر لا سببه، وسبب الإزعاج هنا ملل الموهوب من مهام لا تتحداه.","نقله إلى آخر الصف ليشغل نفسه":"نقله إلى آخر الصف يتركه بلا تحدٍّ فيبقى سبب ملله قائماً، والمطلوب مهام أعمق ترتبط بالدرس."},"e":"الملل سببه عدم التحدي، فالحل إثراء رأسي بمهام أعمق."},"1xnrdh4":{"w":{"بطء في اكتساب المفردات":"بطء اكتساب المفردات عكس خصائص الموهوب، فهو يتميز بنمو لغوي مبكر وحصيلة مفردات واسعة.","الحاجة إلى تكرار كثير لفهم المفاهيم":"الحاجة إلى تكرار كثير من سمات بطيء التعلم، أما الموهوب فيفهم المفاهيم بسرعة ويحفظها بذاكرة قوية.","تجنب الأسئلة والمشكلات المعقدة":"تجنب المشكلات المعقدة عكس خصائص الموهوب، فهو فضولي كثير الأسئلة ويحب التحدي والمسائل الصعبة."},"e":"الموهوب يتميز بالنمو اللغوي المبكر والذاكرة والفضول وحب التحدي."},"rjp7sq":{"w":{"ديسلكسيا":"الديسلكسيا صعوبة تعلم في القراءة وفك رموز الكلمات، والسؤال يصف صعوبة في الكتابة ورداءة الخط.","ديسكالكوليا":"الديسكالكوليا صعوبة تعلم في الحساب والمفاهيم العددية، والسؤال يصف صعوبة في الكتابة وتنظيم الحروف.","ديسفازيا":"الديسفازيا اضطراب في اللغة فهماً أو تعبيراً، لا في مهارة الكتابة ورداءة الخط المذكورة في السؤال."},"e":"الديسغرافيا عسر الكتابة."},"1di9vg0":{"w":{"التوحد":"التوحد يتميز بقصور التواصل والتفاعل وسلوك نمطي ومقاومة للتغيير، والطالب هنا يظهر نشاطاً زائداً واندفاعاً ونسياناً.","بطء التعلم":"بطء التعلم يُعرف بذكاء حدّي وتدنٍّ عام في التحصيل، والسمات المذكورة هنا حركة زائدة ومقاطعة واندفاع ونسيان.","الإعاقة الفكرية":"الإعاقة الفكرية ذكاء دون 70 تقريباً مع قصور في السلوك التكيفي، والسمات هنا نشاط زائد واندفاعية وضعف انتباه."},"e":"النشاط الزائد والاندفاعية وضعف الانتباه هي الثلاثية المميزة لاضطراب فرط الحركة وتشتت الانتباه."},"10fid95":{"w":{"إبلاغ ولي الأمر بأن ابنه معاق":"إبلاغ ولي الأمر بحكم غير مؤكد ضار، فالتشخيص للمختص، ودور المعلم أن يلاحظ ويحيل أولاً.","تشخيص الحالة بنفسه وتعديل المنهج":"التشخيص من عمل المختص وبمصادر متعددة لا بمقياس واحد، ودور معلم الصف الملاحظة والإحالة لا التشخيص.","تجاهل الأمر لأن الطفل ما زال صغيراً":"تجاهل العلامات بحجة صغر السن يضيّع فرصة التدخل المبكر، والمطلوب تسجيل الملاحظة وإحالته إلى المختص."},"e":"دور معلم الصف العادي الملاحظة والإحالة؛ التشخيص للمختص."},"1dn0ene":{"w":{"لغة الإشارة":"لغة الإشارة وسيلة تواصل للصم وضعاف السمع بحركات اليدين، لا طريقة للقراءة والكتابة عند المكفوفين.","قراءة الشفاه":"قراءة الشفاه يعتمد فيها الصم وضعاف السمع على رؤية حركة شفاه المتكلم، والكفيف لا يرى فلا تناسبه.","الكتابة الصوتية":"الكتابة الصوتية ليست نظاماً خاصاً بالمكفوفين، فهم يقرؤون ويكتبون بنظام نقاط بارزة تُقرأ باللمس."},"e":"برايل نظام نقاط بارزة للمكفوفين."},"5cxnr9":{"w":{"القدرات الحركية فقط":"قصور القدرات الحركية وحدها ليس شرط التعريف، فالإعاقة الفكرية تشترط قصوراً في السلوك التكيفي يظهر في مرحلة النمو.","الحواس البصرية والسمعية":"قصور الحواس البصرية والسمعية يندرج في الإعاقات الحسية، أما الإعاقة الفكرية فتشترط مع انخفاض الذكاء قصوراً في السلوك التكيفي.","التحصيل في مادة واحدة":"القصور في مادة واحدة مع ذكاء عادي يشير إلى صعوبات التعلم، أما الإعاقة الفكرية فتشترط قصور السلوك التكيفي."},"e":"التعريف يشترط انخفاض الذكاء وقصور السلوك التكيفي خلال فترة النمو."},"10422j2":{"w":{"ذا صعوبات تعلم":"ذو صعوبات التعلم ذكاؤه عادي أو فوق العادي وتدنيه في مجال محدد، والطالب هنا ذكاؤه حدّي وتدنيه في جميع المواد.","موهوباً متدني التحصيل":"الموهوب متدني التحصيل ذكاؤه مرتفع رغم انخفاض تحصيله، والطالب هنا ذكاؤه حدّي بين 70 و 85 تقريباً.","معاقاً فكرياً":"الإعاقة الفكرية ذكاء دون 70 تقريباً مع قصور في السلوك التكيفي، والسؤال يذكر ذكاءً حدّياً وتدنياً في التحصيل فقط."},"e":"نسبة الذكاء الحدّية (70–85 تقريباً) مع تدنٍّ في جميع المواد هي سمة بطء التعلم."},"13d9552":{"w":{"تكليفها بالمهام نفسها بالسرعة نفسها احتراماً للمساواة":"تقديم المهام نفسها بالسرعة نفسها مساواة شكلية، والعدالة أن تُعطى بطيئة التعلم ما تحتاجه من تبسيط ووقت أطول.","تحويلها إلى معهد التربية الفكرية":"معاهد التربية الفكرية لذوي الإعاقة الفكرية، وبطيئة التعلم ذكاؤها حدّي وتُعلَّم في الصف العادي بالتبسيط والتكرار.","إعفاؤها من الاختبارات":"الإعفاء من الاختبارات لا يعلّمها شيئاً ويحرمها من قياس تقدمها، والمطلوب تكييف التدريس والوقت لا إسقاط التقويم."},"e":"بطيء التعلم يحتاج تبسيطاً وتجزئة ووقتاً وتكراراً داخل الصف العادي."},"m27dbb":{"w":{"فروق نوعية تجعل كل فرد فئة مستقلة":"الفروق الفردية فروق في الدرجة لا في النوع، فالأفراد يشتركون في السمة نفسها ويختلفون في مقدارها.","تظهر في القدرات العقلية أكثر من السمات الشخصية":"مدى الفروق يختلف باختلاف السمة، وأوسعه في السمات الشخصية والانفعالية، فالفروق فيها أكبر منها في القدرات العقلية لا العكس.","أنماط ثابتة لا يغيّرها التعليم والبيئة":"الفروق الفردية تنتج عن تفاعل الوراثة والبيئة، فالتعليم والبيئة يغيّران مستوى الفرد في السمة، ولذلك يراعيها المعلم بالتنويع والتعليم المتمايز."},"e":"الفروق الفردية كمية: الأفراد يشتركون في السمة نفسها ويختلفون في مقدارها (درجة لا نوع)، ومعظمهم قرب المتوسط فتتوزع توزيعاً اعتدالياً. وتشمل السمات الجسمية والعقلية والانفعالية والشخصية، وأوسع مداها في الشخصية والانفعالية، وتنتج عن تفاعل الوراثة والبيئة."},"1f5mb2q":{"w":{"التعليم المبرمج":"التعليم المبرمج يقسم المادة إلى خطوات صغيرة يسير فيها كل طالب بسرعته، فهو من أساليب مراعاة الفروق.","الموديولات التعليمية":"الموديولات وحدات تعلم ذاتي يتقدم فيها الطالب حسب سرعته وقدرته، فهي تراعي الفروق أكثر من المحاضرة.","الصف المقلوب":"الصف المقلوب يتيح للطالب مشاهدة الشرح قبل الحصة وإعادته بحسب سرعته، فيراعي الفروق أكثر من المحاضرة."},"e":"المحاضرة تقدم المحتوى نفسه بالسرعة نفسها للجميع."},"r63ldg":{"w":{"المكاني":"الذكاء المكاني يظهر في إدراك الأشكال والأبعاد والصور، والطالب هنا يصنف النباتات والحشرات ويلاحظ الطيور.","الجسمي الحركي":"الذكاء الجسمي الحركي يظهر في استخدام الجسم والحركة بمهارة، والطالب هنا منشغل بتصنيف الكائنات الحية وملاحظتها.","الذاتي":"الذكاء الذاتي فهم الفرد لنفسه ومشاعره وأهدافه، والطالب هنا يهتم بتصنيف الكائنات الحية وملاحظتها في الطبيعة."},"e":"الاهتمام بالكائنات الحية وتصنيفها من الذكاء الطبيعي."},"4fjp9b":{"w":{"متوسط الفروق الفردية":"المتوسط مقياس نزعة مركزية يحدد مركز الدرجات، أما المدى فمقياس تشتت يبين اتساع ما بين أعلى درجة وأقلها.","ثبات الصفة عبر الزمن":"ثبات الصفة يعني استقرارها عند الفرد مع مرور الزمن، أما المدى فيقارن أعلى درجة وأقلها بين الأفراد.","صدق قياس الصفة":"صدق القياس يعني أن الأداة تقيس ما وُضعت لقياسه، والمدى لا يحكم على الأداة بل يصف تشتت الدرجات."}},"c8118k":{"w":{"مقياس الاتجاه":"مقياس الاتجاه يقيس موقف الطالب الوجداني بعبارات موافق أو غير موافق، ولا يكشف الفجوة بين القدرة والتحصيل.","استبانة الميول":"استبانة الميول تكشف ما يحبه الطالب من أنشطة ومجالات، ولا تقيس تحصيله لتُقارن بقدرته.","مقياس تقدير الذات":"مقياس تقدير الذات يقيس نظرة الطالب إلى نفسه وقيمته، لا مستوى تحصيله الذي يُقارن بقدرته لكشف الصعوبة."},"e":"الفجوة بين القدرة والتحصيل تُكشف بالاختبارات التحصيلية والتشخيصية."},"1glww2k":{"w":{"جدول المواصفات":"جدول المواصفات أداة لبناء الاختبار توزّع الأسئلة على الأهداف والمحتوى، لا وثيقة لأهداف طالب بعينه وخدماته.","الخطة الفصلية":"الخطة الفصلية تنظم تدريس المنهج لعموم الصف خلال الفصل، لا أهداف طالب واحد من ذوي الاحتياجات وخدماته.","السجل القصصي":"السجل القصصي أداة ملاحظة يدوّن فيها المعلم مواقف سلوكية لافتة للطالب، ولا يحدد أهدافاً أو خدمات."},"e":"الخطة التربوية الفردية تُعدّ لكل طالب من ذوي الاحتياجات الخاصة."},"f05x34":{"w":{"تغيير الترتيب باستمرار ليعتاد":"تغيير الترتيب باستمرار يزيد اضطراب الطالب، لأن مقاومة التغيير سمة التوحد، وبيئته المناسبة روتين ثابت.","تجاهل انزعاجه حتى يتوقف":"تجاهل الانزعاج لا يعالج سببه، فالطالب يحتاج تهيئة مسبقة قبل التغيير بجدول بصري ضمن التعلم المنظم.","معاقبته على النوبات":"العقاب يزيد الاضطراب ولا يعالج سببه، فانزعاجه مرتبط بمقاومة التغيير، وتعالَج بالروتين والتهيئة المسبقة."},"e":"مقاومة التغيير سمة التوحد، والتعامل معها بالروتين والتهيئة المسبقة بالجداول البصرية (التعلم المنظم)."},"1jt30y0":{"w":{"لا يحتاجون أي خدمات خاصة لأنهم متفوقون":"الموهوبون من ذوي الاحتياجات الخاصة، ويحتاجون إثراءً يتحداهم، وإلا ملّوا وربما انخفض تحصيلهم.","يُكتشفون دائماً بدرجات الاختبار":"الكشف عن الموهوبين بمحكات متعددة كالذكاء والإبداع وترشيح المعلم، فالتحصيل وحده لا يكشف جميعهم.","ينبغي عزلهم دائماً في فصول خاصة":"العزل الدائم في فصول خاصة ليس الخيار الأفضل، فالإثراء يعمّق خبرة الموهوب ويوسّعها وهو في صفه."},"e":"الموهوب يحتاج إثراءً وإلا ملّ وربما انخفض تحصيله."},"toy7me":{"w":{"الحبسة الكلامية الاستقبالية":"في الحبسة الاستقبالية يضطرب فهم الكلام وقد يتكلم المصاب بطلاقة، والطالب هنا يفهم وينفذ لكن يتعسر عليه الكلام.","التأتأة (اضطراب الطلاقة)":"التأتأة اضطراب في انسياب الكلام بتكرار أو إطالة أو توقف، لا اضطراب لغوي في تركيب الجمل بعد إصابة الدماغ.","عسر القراءة (الديسلكسيا)":"الديسلكسيا صعوبة تعلم في القراءة، أما الطالب هنا فمشكلته في إخراج الكلام بعد إصابة في الرأس."},"e":"الحبسة الكلامية (الأفازيا) اضطراب لغوي مكتسب بسبب إصابة في الدماغ. في الحبسة التعبيرية يبقى الفهم جيداً ويضطرب إنتاج الكلام."},"1xdadf6":{"w":{"خصم درجات من لم ينجز المشروع ليتعلموا الالتزام بالمواعيد":"خصم الدرجات يعاقب الطالب على ظرف أسرته الاقتصادي لا على تقصير منه، والمطلوب توفير بدائل ومصادر تمكّنه من الإنجاز.","إعفاء هؤلاء الطلاب من المشروع نهائياً":"الإعفاء النهائي من المشروع يحرم الطالب من التعلم، والعدالة أن يُعطى بدائل منخفضة التكلفة ومصادر المدرسة.","مطالبة أولياء الأمور بتوفير الأدوات خلال يومين":"مطالبة أولياء الأمور بالأدوات خلال يومين تتجاهل ظروف أسرهم الاقتصادية، فتبقى المشكلة نفسها التي منعت الإنجاز."},"e":"مؤشر 5.2: يميز الاختلافات العائدة للخلفيات الاجتماعية والاقتصادية واحتياجاتها التعليمية التي ينبغي تلبيتها؛ وتلبيتها بتوفير البدائل والمصادر."},"1icbsx1":{"w":{"خفض المستوى المطلوب من الطلاب الوافدين مراعاةً لظروفهم اللغوية":"خفض المستوى المطلوب من الوافدين قالب نمطي لا مراعاة، والتدريس المستجيب ثقافياً يحفظ توقعات عالية للجميع مع الدعم.","اختيار أمثلة من بيئة الأغلبية فقط لتوحيد الفهم داخل الفصل":"الاقتصار على أمثلة الأغلبية يقطع الجسر بين ثقافة الوافدين والتعلم، والتدريس المستجيب ثقافياً يوظف أمثلة من بيئات الجميع.","تجنب أي إشارة إلى خلفيات الطلاب الثقافية":"تجاهل خلفيات الطلاب يحرمهم من ربط التعلم بخبراتهم، والتدريس المستجيب ثقافياً يجعل ثقافة الطالب جسراً للتعلم."},"e":"التدريس المستجيب ثقافياً يجعل ثقافة الطالب وخبرته جسراً للتعلم مع الحفاظ على توقعات عالية."},"nd9hkm":{"w":{"تقديم المهام نفسها بالطريقة نفسها والزمن نفسه لجميع الطلاب دون استثناء":"تقديم المهام نفسها بالطريقة والزمن نفسيهما تطابق في المعاملة لا تكافؤ، فالتكافؤ فرص متنوعة تراعي الفروق.","تخصيص الأنشطة الإثرائية للمتفوقين وحدهم":"قصر الأنشطة الإثرائية على المتفوقين يحرم بقية الطلاب منها، والمبدأ يطلب فرصاً متنوعة لجميع الفئات.","توزيع الطلاب على فصول ثابتة حسب مستوى أسرهم":"التوزيع الثابت حسب مستوى الأسر يصنف الطلاب بخلفياتهم لا بحاجاتهم، ويخالف إتاحة فرص متكافئة ومتنوعة لجميع الفئات."},"e":"تكافؤ الفرص في الإطار الوطني: فرص متكافئة ومتنوعة تراعي الفروق الفردية والقدرات والخلفيات الثقافية والاجتماعية لجميع الفئات."},"1d6utx1":{"w":{"موافقة المعلم المستشار":"موافقة المعلم المستشار ليست الشرط الذي نص عليه الدليل، فالقياس يبدأ بعد موافقة ولي الأمر خطياً وإشعاره رسمياً.","انتهاء العام الدراسي":"الدليل لا يربط بدء القياس بنهاية العام، بل بموافقة ولي الأمر خطياً بعد إشعاره، والانتظار يؤخر التدخل.","حصول الطالب على درجة متدنية في الاختبار النهائي":"الدرجة المتدنية في الاختبار ليست شرطاً لبدء القياس، فالدليل يشترط موافقة ولي الأمر خطياً بعد إشعاره رسمياً."}},"1vli8ns":{"w":{"معلم التربية الخاصة":"معلم التربية الخاصة عضو أساسي في لجنة الخطط الفردية وفق الدليل التنظيمي، فلا يكون هو المستثنى.","ولي أمر الطالب أو من ينوب عنه":"ولي الأمر أو من ينوب عنه عضو في اللجنة وفق الدليل، لأن الأسرة شريك أساسي في خطة ابنها.","معلم التعليم العام":"معلم التعليم العام عضو في اللجنة وفق الدليل، إذ يكيّف التدريس ويشارك في الخطة والتقويم."}},"1d8fx5o":{"w":{"أهداف المنهج العام للصف كما هي دون أي تعديل":"أهداف المنهج العام دون تعديل لا تراعي حاجات الطالب، والخطة الفردية تشتق أهدافها من مستوى أدائه الحالي.","رغبة ولي الأمر في نجاح ابنه":"رغبة ولي الأمر مهمة لكنها ليست أساس صياغة الأهداف، فالأهداف تُشتق من مستوى الأداء الحالي المستخلص من التشخيص.","متوسط أداء زملائه في الفصل":"متوسط أداء الزملاء يقارن الطالب بغيره، والخطة الفردية تنطلق من مستوى أدائه هو بنقاط قوته واحتياجاته."}},"oqhqnsk":{"w":{"استخدام الأسئلة التي تتيح للطلاب تقديم إجابات مختصرة.":"الأسئلة ذات الإجابات المختصرة تتجاهل تنوع مستويات الطلاب اللغوية، ولا تقدم لكل مستوى أنشطة تناسبه.","اتباع طريقة ثابتة لتقديم المفاهيم المهمة في الدرس للطلاب.":"الطريقة الثابتة تقدم المفاهيم للجميع بأسلوب واحد فتتجاهل تنوع خلفياتهم اللغوية، والمطلوب أنشطة تناسب كل مستوى.","إتاحة الفرصة للطلاب ليتحدثوا عن محتوى الدرس.":"إتاحة الحديث للجميع خيار مغرٍ، لكنه نشاط واحد لا يراعي اختلاف مستوياتهم اللغوية كما يفعل تجميع المتقاربين."},"e":"مراعاة الفروق الفردية تقتضي تجميع الطلاب في مجموعات متقاربة المستوى لتلقي أنشطة تناسب كل مجموعة. (المعيار 5.2)"},"oebwynn":{"w":{"طرق التعلّم المفضّلة لديهم.":"طرق التعلم المفضلة أنماط كالبصري والسمعي لا يثبت ارتباطها المباشر بالمستوى الاقتصادي، والسؤال يربط الفرق باطلاع بعضهم على مصادر أكثر.","قدرتهم على التعلّم بشكل عام.":"الظروف الاقتصادية المحدودة تفرّق الطلاب في خلفياتهم المعرفية لا في قدرتهم على التعلم، إذ لا يثبت ارتباط مباشر بينهما.","دافعيتهم والتزامهم بمهام التعلّم.":"الدافعية والالتزام بالمهام لا يثبت ارتباطهما المباشر بالمستوى الاقتصادي، والسؤال يربط الفرق بتفاوت الاطلاع على المصادر التعليمية والثقافية."},"e":"الظروف الاقتصادية تؤثر في توفر مصادر المعرفة ونوعيتها، فتختلف الخلفية المعرفية والخبرات. (المعيار القديم 1.3)"},"owsjpoq":{"w":{"استخدام أساليب الأسئلة التي تتيح للطلاب ذوي الأداء المنخفض تقديم إجابات مختصرة بغض النظر عن كونها صحيحة أو غير صحيحة.":"قبول إجابات مختصرة دون نظر إلى صحتها يخفض التوقعات من ذوي الأداء المنخفض، ولا يقدم لهم أنشطة تناسب مستواهم.","إتباع طريقة تدريس ثابتة لجميع الطلاب لتقديم المفاهيم المهمة في الدرس لهم.":"الطريقة الثابتة لجميع الطلاب تتجاهل تنوع ثقافاتهم ومستوياتهم، والمطلوب تجميع مرن بحسب المستوى مع أنشطة مناسبة.","إتاحة فرص متعددة للطلاب المتميزين ليتحدثوا باللغة الإنجليزية ويكتبوا ويقرؤوا عن محتوى الدرس.":"إتاحة الفرص للمتميزين وحدهم تخدم فئة واحدة وتترك بقية الطلاب، والمطلوب أنشطة تناسب كل مستوى في الفصل."},"e":"مراعاة الفروق تقتضي تجميعًا مرنًا بحسب المستوى مع أنشطة تناسب كل مجموعة. (المعيار القديم 1.3، صعوبة 0.295)"},"o1aavwhx":{"w":{"دراسة المادة في زمن أقل من المعتاد.":"دراسة المادة في زمن أقل هي ضغط المنهج، وهو صورة فعلية من التعجيل، فلا تكون هي المستثناة.","النقل إلى صفوف أعلى في زمن أقل.":"النقل إلى صف أعلى في زمن أقل هو تخطي الصفوف، وهو صورة فعلية من التعجيل الدراسي.","قبولهم في سن مبكرة في المرحلة الابتدائية أو الجامعية.":"القبول المبكر في المرحلة الابتدائية أو الجامعية صورة معروفة من التعجيل، لأنه يقدّم زمن دخول الموهوب إلى المرحلة."}},"o161kkya":{"w":{"يدرك الأنماط والعلاقات.":"إدراك الأنماط والعلاقات تفكير مجرد في الروابط بين الأشياء، أما المتعلم الحسي فيفضّل الخبرة الملموسة ويتعلم باللمس والعمل اليدوي.","يهتم بالرسوم البيانية والخرائط.":"الاهتمام بالرسوم البيانية والخرائط سمة النمط البصري الذي يتعلم بالنظر، أما الحسي فيتعلم باللمس والحركة.","يميل لحل المسائل الرياضية.":"حب المسائل الرياضية اهتمام بنوع من المحتوى، ونمط التعلم طريقة استقبال المعلومات، والحسي يستقبلها باللمس والعمل اليدوي."},"e":"المتعلم الحسي (الحركي) يتعلم باللمس والعمل اليدوي كتركيب المجسمات. (المعيار القديم 1.3، صعوبة 0.485)"},"4uciap":{"w":{"الكلاسيكي":"الكلاسيكي اسم اشتراط بافلوف القائم على اقتران مثيرين، أما الإجرائي فاستجابة إرادية تكون وسيلة للحصول على المعزز.","الاستجابي":"الاستجابي اسم آخر لاشتراط بافلوف حيث يستدعي المثير استجابة لا إرادية، لا لاشتراط سكنر الذي تتحكم فيه نتائج السلوك.","البسيط":"البسيط من أسماء اشتراط بافلوف القائم على اقتران المثيرات، أما الإجرائي فسُمي وسيلياً لأن الاستجابة وسيلة للمعزز."},"e":"يسمى وسيلياً لأن الاستجابة وسيلة للحصول على المعزز."},"eklbrd":{"w":{"التوفيق التكاملي":"التوفيق التكاملي مبدأ آخر لأوزوبل يربط المفاهيم ويزيل التعارض بينها، والمعلم هنا يتدرج من الأشمل إلى التفاصيل.","المنهج الحلزوني":"المنهج الحلزوني لبرونر تعود فيه المفاهيم بعمق أكبر في كل صف، والسؤال عن مبدأ لأوزوبل يتدرج من العام إلى الخاص.","الاستبصار":"الاستبصار عند الجشطلت فهم مفاجئ بإعادة تنظيم الموقف، لا مبدأ لأوزوبل في ترتيب المحتوى من الأشمل إلى الأقل شمولاً."},"e":"التمايز التقدمي (ويسمى التدريجي) يبدأ بالأفكار الأعم ثم ينتقل إلى التفاصيل، وهو مبدأ عند أوزوبل."},"t6re3b":{"w":{"التعزيز البديل":"التعزيز البديل مفهوم آخر لباندورا: يزيد سلوك الملاحظ حين يرى النموذج يُكافأ، وليس التفاعل المستمر بين الفرد وسلوكه وبيئته.","الاستبصار":"الاستبصار مفهوم الجشطلت للفهم المفاجئ بإعادة تنظيم الموقف، وليس من مبادئ باندورا في تفسير نشوء السلوك.","التمثل":"التمثل عند بياجيه إدخال خبرة جديدة في مخطط قائم، ولا صلة له بالتفاعل المستمر بين الفرد وسلوكه وبيئته عند باندورا."},"e":"الحتمية (التفاعل) التبادلية جوهر النظرية الاجتماعية المعرفية."},"10x7vo6":{"w":{"تعزيز سالب":"التعزيز السالب يزيد السلوك بإزالة مثير منفّر، والمعلم هنا أضاف مثيراً سارّاً هو الشكر ولم يُزل شيئاً.","عقاب سالب":"العقاب السالب سحب معزّز ليقل السلوك، أما هنا فأُضيف الشكر فازداد رفع اليد.","انطفاء":"الانطفاء إيقاف التعزيز فيتلاشى السلوك تدريجياً، والمعلم هنا عزّز بالشكر فازداد السلوك بدل أن يتلاشى."},"e":"الشكر مثير سارّ أُضيف بعد السلوك فزاد، وهذا التعزيز الموجب."},"uday7a":{"w":{"تكلفة استجابة":"تكلفة الاستجابة سحب شيء مكتسب كالدرجات أو النقاط، والطالب هنا لم يُسحب منه شيء اكتسبه بل أُبعد مؤقتاً عن مصدر التعزيز.","تعزيز سالب":"التعزيز السالب إزالة منفّر ليزيد السلوك، والمعلم هنا يريد تقليل الشغب بإبعاد الطالب عن مصدر التعزيز.","انطفاء":"الانطفاء تجاهل السلوك بإيقاف تعزيزه حتى يتلاشى، أما هنا فأُخرج الطالب من مجموعة اللعب ليجلس وحده."},"e":"الإبعاد المؤقت عن مصدر التعزيز هو الإقصاء."},"8gmx84":{"w":{"فترة ثابتة":"الفترة الثابتة موعد منتظم كاختبار كل أسبوع فيتركز الاستذكار قبيله، والاختبارات هنا مفاجئة فاستمر الاستذكار طوال الفصل.","نسبة ثابتة":"النسبة الثابتة تعزيز بعد عدد محدد من الاستجابات، والاختبارات هنا مرتبطة بأوقات غير متوقعة لا بعدد مرات الاستذكار.","تعزيز مستمر":"التعزيز المستمر يأتي بعد كل استجابة، والاختبارات هنا متفرقة تأتي في أوقات غير متوقعة."},"e":"الاختبارات في أوقات زمنية غير منتظمة = فترة متغيرة، وتحافظ على أداء مستمر."},"3sgz85":{"w":{"النسبة الثابتة":"النسبة الثابتة تعزيز بعد عدد محدد من الاستجابات فيمكن توقعه، والنسبة المتغيرة غير المتوقعة هي الأقوى والأكثر مقاومة للانطفاء.","الفترة الثابتة":"في الفترة الثابتة يأتي التعزيز في موعد منتظم فيرتفع الأداء قبيل الموعد فقط، فلا يعطي أعلى معدل استجابة.","التعزيز المستمر":"التعزيز المستمر أسرع الجداول تعلماً لكنه أسرعها انطفاءً، فهو أقلها مقاومة للانطفاء لا أكثرها كما يطلب السؤال."},"e":"النسبة المتغيرة (كألعاب الحظ) الأقوى وأكثرها مقاومة للانطفاء."},"17u15hl":{"w":{"التعزيز السالب":"التعزيز السالب إزالة منفّر ليزيد السلوك، والمعلم هنا يضيف نقاطاً تُستبدل بامتيازات، فهو تعزيز بإضافة لا بإزالة.","مبدأ بريماك":"مبدأ بريماك أن يعزز نشاط محبب نشاطاً أقل تفضيلاً، أما هنا فنقاط رمزية يجمعها الطلاب ثم يستبدلونها بامتيازات.","العقد السلوكي":"العقد السلوكي اتفاق مكتوب بين المعلم والطالب على سلوك ومكافأته، والسؤال يصف رموزاً تُجمع وتُستبدل لاحقاً بمعززات."},"e":"الرموز القابلة للاستبدال بمعززات هي الاقتصاد الرمزي."},"10enkcl":{"w":{"التعميم":"التعميم أن يمتد الخوف إلى مثيرات تشبه الأصلي، فلو عمّم الطفل لخاف من والده أيضاً حين يلبس المعطف الأبيض.","الانطفاء":"الانطفاء ضعف الاستجابة حتى تختفي بتكرار المثير الشرطي وحده، وخوف الطفل من الطبيب ما زال قائماً.","الإشراط من الدرجة الثانية":"الإشراط من الدرجة الثانية أن يقترن مثير جديد بالمثير الشرطي فيصير شرطياً بدوره، والسؤال عن تفريق الطفل بين الطبيب ووالده."}},"g202w1":{"w":{"مثيراً غير شرطي":"المثير غير الشرطي يستدعي الاستجابة طبيعياً دون تعلم وهو الطعام، أما الجرس فاكتسب أثره بالاقتران.","استجابة شرطية":"الاستجابة الشرطية هي اللعاب الذي يسيل للجرس، والسؤال عن الجرس نفسه وهو مثير لا استجابة.","استجابة غير شرطية":"الاستجابة غير الشرطية هي اللعاب الطبيعي عند تقديم الطعام، والجرس مثير وليس استجابة."},"e":"الجرس مثير محايد صار شرطياً."},"11bhvun":{"w":{"بافلوف":"بافلوف صاحب تجربة الكلب والجرس في الاشتراط الكلاسيكي، أما تجربة الطفل ألبرت وتأسيس المدرسة السلوكية فلواطسون.","ثورندايك":"ثورندايك صاحب المحاولة والخطأ وقانون الأثر بتجربة القط في الصندوق، لا تجربة الطفل ألبرت.","تولمان":"تولمان من المعرفيين وصاحب التعلم الكامن والخرائط المعرفية، لا مؤسس السلوكية ولا صاحب تجربة ألبرت."},"e":"واطسون مؤسس السلوكية ومعه تجربة ألبرت الصغير."},"lcr8ci":{"w":{"الاستبصار":"الاستبصار فهم مفاجئ بإعادة تنظيم الموقف كقرد كوهلر، أما الفئران هنا فتعلمت دون تعزيز وظهر تعلمها عند تقديم الطعام.","الانطفاء":"الانطفاء ضعف الاستجابة حتى تختفي حين يغيب التعزيز، والفئران هنا تحسن أداؤها ولم يضعف.","التعزيز البديل":"التعزيز البديل أن يرى الملاحظ نموذجاً يُكافأ فيزيد سلوكه، ولا نموذج يُلاحَظ في تجربة الفئران."}},"3lcv7o":{"w":{"تعزيز متقطع":"التعزيز المتقطع جدول لتقديم المكافأة بعد بعض الاستجابات، والمعلم هنا يقدم إطاراً عاماً قبل الدرس لا مكافأة.","استبصار":"الاستبصار فهم مفاجئ يحدث للمتعلم بإعادة تنظيم الموقف، لا إجراء يقدمه المعلم في بداية الوحدة.","سقالات":"السقالات دعم مؤقت أثناء أداء المتعلم يُسحب تدريجياً، أما الخريطة هنا فإطار عام يُعرض قبل الدرس لربطه بما سبق."},"e":"الإطار العام المقدّم قبل الدرس لربطه بالبنية المعرفية هو المنظم المتقدم."},"byivad":{"w":{"بياجيه (الحس-حركي ثم المجرد)":"مراحل بياجيه مراحل نمو عقلي يمر بها الطفل بحسب عمره، أما التدرج هنا فأنماط تمثيل المفهوم الواحد: عملي ثم أيقوني ثم رمزي.","سكنر (التعليم المبرمج)":"التعليم المبرمج لسكنر تقسيم المحتوى إلى خطوات صغيرة مع تعزيز فوري، لا تدرج من المجسم إلى الصورة إلى المعادلة.","باندورا (النمذجة)":"النمذجة عند باندورا تعلم بملاحظة نموذج يؤدي السلوك، والمعلم هنا ينوّع طريقة تمثيل المفهوم من المجسم إلى الرمز."}},"1kmb1jc":{"w":{"المنهج المحوري":"المنهج المحوري ينظم الدراسة حول محور من حاجات المتعلمين أو مشكلاتهم، لا حول عودة المفاهيم نفسها بعمق متزايد في كل صف.","منهج النشاط":"منهج النشاط يبني الدراسة على ميول المتعلمين وأنشطتهم، وليس تنظيماً يعيد المفاهيم الأساسية بتعمق متزايد عبر الصفوف.","المنهج المدمج":"المنهج المدمج يدمج مواد متقاربة في مجال واحد، أما عودة المفهوم نفسه بعمق أكبر في كل صف فهي المنهج الحلزوني لبرونر."}},"c073hu":{"w":{"غير محدودة":"السعة غير المحدودة صفة الذاكرة طويلة المدى، أما قصيرة المدى فمحدودة بنحو 7±2 وحدات.","وحدة واحدة":"الذاكرة العاملة تحتفظ بعدة وحدات معاً لا بوحدة واحدة، وقد قدّر ميلر سعتها بنحو 7±2 وحدات.","50 وحدة":"الرقم 50 يتجاوز كثيراً سعة الذاكرة قصيرة المدى، فقد قدّرها ميلر بنحو 7±2 وحدات فقط."},"e":"ميلر: 7±2 وحدات، وتبقى المعلومة فيها نحو 15–30 ثانية دون تسميع."},"330w3n":{"w":{"الذاكرة طويلة المدى":"الذاكرة طويلة المدى تخزن المعلومات زمناً طويلاً بعد ترميزها، والمعلم هنا يختبر حفظاً سريعاً لثوانٍ بعد مسح الأرقام.","الذاكرة الإجرائية":"الذاكرة الإجرائية تخزن المهارات وطريقة أداء الأعمال كركوب الدراجة، والمطلوب هنا الاحتفاظ بأرقام لثوانٍ قليلة.","الذاكرة الحسية فقط":"الذاكرة الحسية تحتفظ بالمثير لحظات قصيرة جداً قبل الانتباه إليه، أما استرجاع الأرقام بعد مسحها فيحتاج معالجة في الذاكرة العاملة."}},"1i6c1td":{"w":{"الدافعية ← الانتباه ← الاحتفاظ ← الإنتاج":"الدافعية عند باندورا آخر المراحل، تدفع الملاحظ إلى تكرار السلوك بعد إنتاجه، فلا تأتي قبل الانتباه إلى النموذج.","الاحتفاظ ← الانتباه ← الدافعية ← الإنتاج":"لا يحتفظ الملاحظ بسلوك لم ينتبه إليه، فالانتباه أولاً ثم الاحتفاظ، والدافعية تأتي بعد الإنتاج لا قبله.","الإنتاج ← الانتباه ← الاحتفاظ ← الدافعية":"إنتاج السلوك يحتاج نموذجاً انتبه إليه الملاحظ واحتفظ به، فالإنتاج ثالث المراحل لا أولها."}},"190fppu":{"w":{"تعزيز موجب مباشر":"التعزيز الموجب المباشر أن يُكافأ الطالب نفسه على سلوكه، وهو هنا لم يُكافأ بل رأى زميله يُكافأ.","استبصار":"الاستبصار فهم مفاجئ لحل مشكلة بإعادة تنظيم الموقف، والطالب هنا قلّد سلوكاً رأى صاحبه يُكافأ عليه.","تمييز":"التمييز استجابة للمثير الأصلي دون ما يشبهه، والسؤال يصف زيادة سلوك بعد ملاحظة زميل يُكافأ."},"e":"زيادة سلوك الملاحظ بعد رؤية النموذج يُعزز هي التعزيز البديل (باندورا)."},"ouhb52":{"w":{"مسائل الخطوتين فقط حتى يتقنها تماماً":"مسائل الخطوتين يحلها الطالب وحده فهي مستوى نموه الفعلي، والتدريس عند فيجوتسكي يستهدف ما ينجزه بالمساعدة.","مسائل من ثماني خطوات ليتحدى نفسه":"حدود منطقة النمو القريب هنا أربع خطوات بالتلميحات، ومسائل الثماني أبعد مما ظهر أنه ينجزه بالمساعدة، والبعيد جداً يُحبط.","ترك الطالب يختار بنفسه دائماً":"ترك الاختيار للطالب يُغفل دور الأكثر خبرة عند فيجوتسكي، فالمعلم يوجهه إلى ما ينجزه بمساعدته ثم يسحب الدعم تدريجياً."},"e":"التدريس الفعال يستهدف منطقة النمو القريب (ما ينجزه بالمساعدة) مع سقالات تُسحب تدريجياً."},"ewnc8t":{"w":{"دليل على تمركز حول الذات يجب علاجه":"عدّ بياجيه الحديث الذاتي تمركزاً حول الذات، والسؤال عن فيجوتسكي الذي يراه أداة لتنظيم التفكير لا مشكلة تُعالج.","مظهر لتشتت الانتباه":"الطفل هنا يوجّه حديثه إلى خطوات الأحجية نفسها، فهو عند فيجوتسكي تنظيم للتفكير أثناء المهمة لا انصراف عنها.","سلوك يجب إيقافه حفاظاً على الهدوء":"يرى فيجوتسكي الحديث الذاتي وسيلة يضبط بها الطفل فعله ثم يتحول لاحقاً إلى حديث داخلي، فإيقافه يحرمه أداة تفكير."},"e":"فيجوتسكي يرى الحديث الذاتي وسيلة لضبط الذات وتوجيه الفعل ويتحول لاحقاً إلى حديث داخلي."},"cdggze":{"w":{"انتقال أثر إيجابي":"الانتقال الإيجابي أن تسهّل الخبرة السابقة الأداء الجديد، وعادة القيادة على اليسار هنا أوقعته في أخطاء كثيرة.","انتقال صفري":"الانتقال الصفري ألا تؤثر الخبرة السابقة في الموقف الجديد، والعادة القديمة هنا أثرت فعلاً فأعاقت أداءه.","تعميم إيجابي":"التعميم مصطلح من الاشتراط يعني الاستجابة لمثيرات تشبه الأصلي، والسؤال عن خبرة سابقة أعاقت أداءً جديداً، وهذا انتقال أثر سلبي."}},"10xm8zz":{"w":{"استبصار في الموقف الجديد":"الاستبصار مفهوم الجشطلت للفهم المفاجئ بإعادة تنظيم الموقف، وثورندايك سلوكي فسّر الانتقال بتشابه عناصر الموقفين.","دافعية داخلية مرتفعة":"الدافعية حالة داخلية تحرك السلوك نحو الهدف، وليست تفسير ثورندايك للانتقال، فهو يربطه بتشابه عناصر الموقفين.","منظم متقدم":"المنظم المتقدم من أفكار أوزوبل لربط الدرس الجديد بالبنية المعرفية، لا تفسير ثورندايك لانتقال الأثر بين موقفين متشابهين."}},"1gqll4v":{"w":{"يزيد من احتمال تكرار السلوك":"التعزيز السالب تعزيز فعلاً، والتعزيز بنوعيه يزيد السلوك، فهذه العبارة تنطبق عليه وليست هي المطلوبة.","يتضمن إزالة مثير منفّر":"إزالة المنفّر هي معنى «السالب» في التعزيز السالب، فهذه العبارة تنطبق عليه وليست هي الاستثناء.","يحدث بعد صدور الاستجابة":"التعزيز السالب كغيره من التعزيز في الإشراط الإجرائي يأتي بعد الاستجابة فيقويها، فهذه العبارة تنطبق عليه."}},"1qk6zpi":{"w":{"منطقة النمو القريب":"منطقة النمو القريب من مفاهيم فيجوتسكي في البنائية الاجتماعية، فهي فعلاً من مفاهيم النظرية البنائية وليست الاستثناء.","التمثل والمواءمة":"التمثل والمواءمة عمليتا بياجيه في بناء المخططات المعرفية، فهما من صميم البنائية وليسا الاستثناء.","السقالات":"السقالات دعم مؤقت مرتبط بمنطقة النمو القريب عند فيجوتسكي، فهي من مفاهيم البنائية وليست الاستثناء."},"e":"جداول التعزيز من الإشراط الإجرائي."},"7zzt4z":{"w":{"التسميع الموزع":"التسميع الموزع على جلسات متباعدة ينقل المعلومة إلى الذاكرة طويلة المدى، وهو أفضل للاحتفاظ من المذاكرة المكثفة، فليس الاستثناء.","التجميع":"التجميع ينظم المعلومات في وحدات أكبر كتقسيم الرقم الطويل إلى مجموعات، وهو فعلاً من طرق نقلها إلى الذاكرة طويلة المدى.","الربط بالمعرفة السابقة (التوسيع)":"ربط الجديد بالمعرفة السابقة تفصيل يعطي المعلومة معنى فتُخزن في الذاكرة طويلة المدى، فهو استراتيجية صحيحة لا استثناء."},"e":"تكديس المعلومات دفعة واحدة قبل الاختبار يثقل الذاكرة العاملة ويُنسى سريعاً، فليس استراتيجية لنقلها إلى الذاكرة طويلة المدى."},"10n2f33":{"w":{"انطفاء الاستجابة":"الانطفاء مفهوم سلوكي يعني تلاشي الاستجابة حين يتوقف تعزيزها، والسؤال يطلب تفسيراً من معالجة المعلومات لشرح طويل متواصل.","ضعف قانون الاستعداد":"قانون الاستعداد من قوانين ثورندايك السلوكية، والمشكلة هنا كثافة الشرح المتواصل التي أثقلت الذاكرة العاملة لا استعداد الطلاب.","غياب المواءمة":"المواءمة عند بياجيه تعديل المخطط المعرفي ليستوعب خبرة جديدة، وهي مفهوم بنائي لا يفسر توقف المتابعة بعد شرح طويل متواصل."}},"1sdtta0":{"w":{"الانتباه الانتقائي":"الانتقائي تركيز على مثير واحد وتجاهل غيره، والمعلم هنا لم يتجاهل الصفوف الخلفية بل تابعها وهو يشرح.","الانتباه المتناوب":"المتناوب تحويل الانتباه بين مهمتين واحدة بعد الأخرى، والمعلم هنا يشرح ويتابع الطلاب في الوقت نفسه.","الانتباه القسري":"القسري انتباه يفرضه مثير قوي مفاجئ كصوت عالٍ، ولا مثير مفاجئ هنا، فالمعلم يوزع انتباهه بإرادته."},"e":"الانتباه الموزع (ويسمى المنقسم) توجيه الانتباه إلى أكثر من مثير أو مهمة في الوقت نفسه."},"jyqfsp":{"w":{"تعلم المبادئ (القواعد)":"تعلم المبادئ يسبق حل المشكلات مباشرة في هرم جانييه، فهو شرط له وليس قمة الهرم.","تعلم المفاهيم":"تعلم المفاهيم في المستوى السادس من الهرم، وتُبنى عليه المبادئ ثم حل المشكلات في القمة.","التعلم الإشاري":"التعلم الإشاري قاعدة هرم جانييه وأبسط أنواعه، فهو أول المستويات لا أعلاها."}},"hkvoeo":{"w":{"يحدث بالتكرار الآلي وحده":"التكرار الآلي أقرب إلى الحفظ الصمّ، والتعلم المستند إلى الدماغ يرى الدماغ باحثاً عن المعنى يحتاج معالجة نشطة لا تكراراً فقط.","لا يتأثر بالانفعالات":"من مبادئ كين وكين أن الانفعالات أساسية في التعلم، ولهذا يحرص المعلم هنا على بيئة خالية من السخرية والخوف.","يتم بمعالجة الأجزاء منفصلة عن الكل":"يرى كين وكين أن الدماغ يعالج الأجزاء والكل معاً، فالفصل بينهما يخالف مبادئ التعلم المستند إلى الدماغ."},"e":"من مبادئ كين وكين: التعلم يتعزز بالتحدي ويُكبح بالتهديد؛ ومنها عنصر الاسترخاء اليقظ."},"1bq0q5c":{"w":{"الاسترخاء اليقظ":"الاسترخاء اليقظ أمان نفسي مع تحدٍّ مرتفع في بيئة الصف، أما التلخيص والتطبيق والمناقشة بعد الشرح فمعالجة نشطة للمفهوم.","الانغماس المنظم":"الانغماس المنظم يضع الطلاب في خبرات حقيقية غنية أثناء التعلم، أما التلخيص بكلماتهم والمناقشة بعد الشرح فتثبيت للمعنى بالمعالجة النشطة.","التعزيز السلبي":"التعزيز السالب مفهوم سلوكي يعني إزالة منفّر لزيادة السلوك، وليس من عناصر نموذج التعلم المستند إلى الدماغ الثلاثة."}},"1hov45p":{"w":{"مستقل عن المجال الإدراكي":"المستقل عن المجال يحلل الأجزاء ويفصلها عن السياق ويفضل العمل الفردي، والطالب هنا يدرك الكل ويفضل المجموعة.","متروٍّ (تأملي)":"التروي أحد طرفي بُعد كاجان (الاندفاع والتروي) ويصف التأني قبل الإجابة، لا بُعد ويتكن الذي يخص إدراك الكل والتأثر بالسياق.","مندفع (متسرع)":"الاندفاع الطرف الآخر من بُعد كاجان ويصف السرعة في الإجابة مع كثرة الخطأ، والسؤال عن بُعد ويتكن في إدراك الموقف والتأثر بالسياق."},"e":"المعتمد على المجال يدرك كلياً ويتأثر بالمحيط ويفضل التوجيه والعمل الجماعي."},"13vhk78":{"w":{"حرمانه من المشاركة الشفهية حتى يتعلم الانضباط":"منع المندفع من الإجابة الشفهية عقاب لا يعلّمه مهارة التروي، وعلاج الاندفاع تدريبه على التوقف وتمديد وقت الانتظار.","تكليفه بأسئلة أسرع لاستثمار سرعته":"زيادة السرعة تقوّي الاندفاع نفسه الذي سبّب أخطاءه، والمطلوب إبطاؤه ليفحص البدائل قبل أن يجيب.","نقله إلى مجموعة الطلاب الأضعف":"السؤال يذكر أنه قادر وأن أخطاءه من التسرع، فتصنيفه مع الأضعف لا يعالج اندفاعه ولا يعلّمه التروي."},"e":"الأسلوب المندفع يستجيب بسرعة وبأخطاء أكثر، ويُعالج بتعليم التوقف والتفكير وفحص البدائل وتمديد وقت الانتظار."},"1wfhr8u":{"w":{"معرفية فقط":"الهدوء والإضاءة عوامل بيئية، والمثابرة والحاجة إلى التنظيم عوامل انفعالية في نموذج دن ودن، فحصرها في المعرفي يُغفلهما.","وراثية ثابتة":"عناصر الوصف هنا بيئية كالهدوء والإضاءة وانفعالية كالمثابرة والتنظيم، ولا ذكر فيه للوراثة، والأسلوب ثابت نسبياً لا ثابت تماماً.","اجتماعية فقط":"العوامل الاجتماعية تخص تفضيل العمل وحده أو مع الآخرين، والوصف هنا عن الهدوء والإضاءة والمثابرة، وهي عوامل بيئية وانفعالية."}},"o171w7a9":{"w":{"تعزيز التعلم.":"التعزيز يدعم السلوك ليتكرر بنتيجة تتبعه، ولا يعني توظيف الخبرة السابقة في موقف تعليمي جديد.","الدافعية للتعلم.":"الدافعية حالة داخلية تحرك السلوك نحو الهدف، أما استخدام الخبرة السابقة في موقف جديد فهو انتقال الأثر.","النضج المرافق للتعلم.":"النضج تغيرات بيولوجية داخلية تحدث مع النمو، لا استخدام لخبرات سابقة مكتسبة في موقف تعليمي جديد."},"e":"انتقال أثر التعلم هو توظيف معلومات أو خبرات سابقة في أداء مهام في مواقف جديدة. (المعيار 5.2)"},"o6k1b1c":{"w":{"يُظهر عدم النضج الاجتماعي.":"الحديث الذاتي عند فيجوتسكي أداة ينظم بها الطفل تفكيره أثناء حل المسائل، وهو تطور طبيعي في سنه لا دليل على عدم النضج.","يطوّر عادة يجب علاجها إذا استمرت.":"الحديث الذاتي عند فيجوتسكي لا يحتاج علاجاً، فهو أداة لتوجيه السلوك تتحول مع النمو إلى حديث داخلي.","يوظّف إستراتيجية لجذب انتباه الآخرين له.":"خالد يحدّث نفسه أثناء حل المسائل ولا يخاطب غيره، فحديثه موجه لتنظيم تفكيره لا لجذب انتباه الآخرين."},"e":"الحديث الذاتي عند فيجوتسكي وسيلة ينظم بها الطفل تفكيره ويوجه سلوكه أثناء حل المشكلات، وهو طبيعي في هذه السن. (المعيار 5.2)"},"o1drpfzu":{"w":{"تعريف الطلاب بأصعب جوانب المهارة المقصودة.":"تعريف الطلاب بالجوانب الصعبة إخبار لفظي عن المهارة، أما التعلم بالملاحظة فيقوم على نموذج يؤديها أمامهم ليقلدوه.","شرح ترتيب الخطوات شفهيًّا للطلاب حسب ترتيبها في المهارة.":"الشرح الشفهي للخطوات تلقين لفظي لا ملاحظة، فالتعلم بالملاحظة يتطلب أن يرى الطلاب نموذجاً يؤدي المهارة فعلاً.","ضمان تركيز انتباه الطلاب على الجوانب المهمة في المهارة الموضحة.":"الانتباه أول مراحل التعلم بالملاحظة، لكنه شرط عند المتعلم يأتي بعد توفير النموذج، فلا تعلم بالملاحظة دون نموذج."},"e":"التعلم بالملاحظة (باندورا) يقوم أساسًا على وجود نموذج حي يؤدي المهارة أمام المتعلم ليقلده، فلا تعلم بالملاحظة بلا نموذج. (المعيار 10.2)"},"oel01fp":{"w":{"الربط بالمعايير للدرس.":"الربط بالمعايير يوضح للطلاب أي معيار أو هدف يحققه الدرس، أما العبارة هنا فتربط عدد الكواكب بصورة مألوفة ليسهل تذكره.","ملاحظة تلخيص المحتوى.":"التلخيص يجمع أهم أفكار الدرس في عبارات قصيرة، والعبارة هنا لا تلخص محتوى بل تربط رقماً واحداً بصورة تسهّل استرجاعه.","وسيلة مراجعة للمفاهيم.":"المراجعة إعادة عرض للمحتوى بعد تعلمه، أما هذه العبارة فصورة ذهنية تربط الرقم بشيء مألوف لتسهيل استرجاعه."},"e":"العبارة وسيلة تذكرية (ربط ذاكري) من إستراتيجيات معالجة المعلومات لتسهيل الاسترجاع. (المعيار القديم 1.2، صعوبة 0.739)"},"o1ux71zi":{"w":{"يشرح معناه.":"شرح المعنى تلقين لفظي يخبر الطلاب عن السلوك، والنمذجة أن يؤدي المعلم السلوك أمامهم ليلاحظوه ويقلدوه.","يحث على فعله.":"الحث على السلوك توجيه لفظي لا نموذج يُلاحَظ، فالنمذجة تتطلب أن يرى الطلاب المعلم يحترم آراءهم فعلاً.","يكافئ من يمارسه.":"مكافأة من يمارس السلوك تعزيز سلوكي مباشر، أما النمذجة فأن يكون المعلم قدوة يؤدي السلوك أمام طلابه."},"e":"النمذجة (باندورا) تعني أن يكون المعلم قدوة يؤدي السلوك أمام الطلاب ليلاحظوه ويقلدوه. (المعيار القديم 8.4، صعوبة 0.664)"},"14lyurs":{"w":{"تحديد مستوى ذكاء الطالب":"مستوى الذكاء تكشفه اختبارات الذكاء المقننة، أما الدافعية فحالة داخلية تحرك السلوك نحو هدف وتحافظ عليه.","تفسير الفروق الوراثية":"الفروق الوراثية موضوع دراسات الوراثة كدراسات جالتون، والدافعية لا تفسرها بل تحرك السلوك وتوجهه نحو هدف.","قياس التحصيل الدراسي":"قياس التحصيل وظيفة الاختبارات التحصيلية، والدافعية لا تقيس شيئاً بل تطلق السلوك وتحدد شدته ومدة استمراره."},"e":"الدافعية تولد السلوك وتوجهه وتحدد شدته وديمومته."},"19xj4jj":{"w":{"سبيرمان":"سبيرمان عُرف بنظرية العامل العام والعوامل الخاصة في الذكاء، أما تأكيد أثر الوراثة فاشتهر به جالتون.","جاردنر":"جاردنر صاحب نظرية الذكاءات المتعددة الثمانية، ولا صلة لها بتأكيد أثر الوراثة ولا بفكرة معامل الارتباط.","ستيرنبرغ":"ستيرنبرغ صاحب نظرية الذكاء الثلاثي التحليلي والإبداعي والعملي، لا صاحب دراسات الوراثة ومعامل الارتباط."},"e":"جالتون رائد دراسة الوراثة والفروق ومعامل الارتباط."},"ll28ao":{"w":{"المرونة التكيفية":"المرونة التكيفية يغيّر فيها الفرد وجهته الذهنية لأن المشكلة تتطلب ذلك، والسؤال يصف أفكاراً تأتي دون تغيير في الموقف.","الطلاقة اللفظية":"الطلاقة اللفظية كثرة الألفاظ، والسؤال لا يقيس عدد الكلمات بل توليد أفكار غير مألوفة من تلقاء النفس.","الإفاضة (التوسع)":"الإفاضة إضافة التفاصيل إلى فكرة قائمة لتوسيعها، أما هنا فالطالب يولّد أفكاراً جديدة متنوعة من تلقاء نفسه."},"e":"المرونة التلقائية إنتاج أفكار متنوعة من تلقاء النفس دون أن يفرض الموقف تغيير الاتجاه."},"cnggni":{"w":{"التفكير الإبداعي بالإثارة العشوائية":"الإثارة العشوائية أداة إبداعية لتوليد أفكار جديدة، والنشاط هنا تمييز للمترابط عن غيره مع تعليل، وهذا فرز وحكم ناقد.","ما وراء المعرفة بالتساؤل الذاتي":"التساؤل الذاتي يراقب به الطالب تفكيره هو، أما النشاط هنا فيفحص الكلمات نفسها ويحكم على ترابطها بتعليل.","التفكير الجانبي بالقبعات":"التفكير الجانبي توليد إبداعي لمداخل غير مألوفة، والقبعات زوايا نظر متعددة، والنشاط هنا تمييز وتصنيف بتعليل وهو تفكير ناقد."},"e":"الكلمات المترابطة استراتيجية لتعليم التفكير الناقد (التمييز والتصنيف)."},"1om6ici":{"w":{"البيضاء":"البيضاء لعرض الحقائق والمعلومات المحايدة، أما إدارة الجلسة وتحديد تسلسلها والقرار النهائي فدور الزرقاء.","الحمراء":"الحمراء للتعبير عن المشاعر والحدس دون تبرير، ولا تتولى تنظيم الجلسة ولا اتخاذ القرار النهائي.","الخضراء":"الخضراء للإبداع واقتراح البدائل الجديدة، أما ضبط تسلسل التفكير والخروج بالخلاصة فوظيفة الزرقاء."},"e":"الزرقاء قبعة التنظيم والضبط واتخاذ القرار."},"1j6ticq":{"w":{"الانطفاء في الإشراط الكلاسيكي":"الانطفاء الكلاسيكي زوال استجابة شرطية بتكرار المثير الشرطي وحده، والرسم هنا نشاط إرادي كان ممتعاً بذاته فأضعفت الدرجات دافعه.","تدني الذكاء المكاني":"الطالب كان يرسم بمتعة قبل الدرجات، فقدرته على الرسم لم تتغير، والذي تغير دافعه حين تحول من داخلي إلى خارجي.","العجز المتعلم":"العجز المتعلم توقف عن المحاولة بعد فشل متكرر، والطالب هنا لم يفشل بل توقف حين توقفت المكافأة التي صارت دافعه."}},"vuw2r0":{"w":{"زيادة المكافآت والدرجات":"السؤال يذكر أن المكافآت لا تنفع معه، فالحوافز لا تؤثر قبل إشباع حاجته إلى الطعام والأمن وفق ماسلو.","تكليفه بمهام تحقق ذاته":"تحقيق الذات قمة هرم ماسلو، ولا تبرز هذه الحاجة بقوة والطالب جائع وخائف لم تُشبع حاجاته الدنيا بعد.","تجاهل الأمر لأنه خارج الصف":"جوعه وخوفه يعوقان تعلمه داخل الصف، ولذلك يبدأ المعلم وفق ماسلو بتأمين طعامه وأمنه قبل أي حافز."}},"v6xle7":{"w":{"خطية موجبة: كلما زاد القلق تحسن الأداء":"القلق المرتفع جداً يضعف الأداء بعد حد معين، فالعلاقة ليست تصاعدية مستمرة بل يبلغ الأداء أفضله عند الاستثارة المتوسطة.","خطية سالبة: كلما زاد القلق ساء الأداء":"الاستثارة المنخفضة جداً تضعف الأداء أيضاً، فلو كانت العلاقة سالبة لكان انعدام القلق أفضل الحالات، وهذا ما ينفيه القانون.","لا علاقة بينهما":"القانون يثبت علاقة على شكل منحنى مقلوب، فالأداء يتغير بتغير الاستثارة ويبلغ أفضله عند مستواها المتوسط."}},"ux0tp3":{"w":{"سهلة جداً لضمان النجاح":"اختيار المهام السهلة جداً سمة منخفض دافع الإنجاز، فنجاحها المضمون لا يحمل تحدياً يُشعر صاحبه بالإنجاز.","مستحيلة ليُعذر عند الفشل":"اختيار الصعب جداً ليُعذر صاحبه عند الفشل سمة منخفض دافع الإنجاز، أما مرتفعه فيطلب تحدياً يمكن النجاح فيه.","يختارها له الآخرون":"السؤال عن مهام يختارها الطالب بنفسه، وذو دافع الإنجاز المرتفع يتحمل مسؤولية اختياره فيطلب تحدياً متوسط الصعوبة."},"e":"وفق ماكليلاند وأتكنسون، ذو دافع الإنجاز المرتفع يفضل المهام متوسطة الصعوبة."},"1o17gzl":{"w":{"الذكاء الموروث":"الكفاءة الذاتية اعتقاد الفرد بقدرته يُبنى من خبراته وما يمر به، والذكاء الموروث ليس من مصادرها الأربعة عند باندورا.","المستوى الاقتصادي":"المستوى الاقتصادي ظرف أسري خارجي، وليس من مصادر باندورا الأربعة التي تبني اعتقاد الفرد بقدرته.","جداول التعزيز":"جداول التعزيز مفهوم عند سكنر ينظم توقيت المكافأة، لا مصدر من مصادر الكفاءة الذاتية عند باندورا."}},"1aeh32n":{"w":{"سبيرمان":"سبيرمان صاحب نظرية العاملين في الذكاء، أما أول اختبار للذكاء ومفهوم العمر العقلي فلبينيه.","وكسلر":"وكسلر وضع مقاييسه بعد بينيه بعقود، فليس صاحب أول اختبار للذكاء ولا صاحب مفهوم العمر العقلي.","جاردنر":"جاردنر صاحب نظرية الذكاءات المتعددة، وهي نظرية تفسر الذكاء لا أول اختبار يقيسه بالعمر العقلي."},"e":"بينيه (1905) وضع أول مقياس للذكاء مع سيمون."},"vkkzf6":{"w":{"العمر الزمني ÷ العمر العقلي × 100":"هذه قسمة معكوسة، فطفل عمره العقلي 12 وزمنه 10 يخرج له نحو 83 بدل 120، فتجعل المتقدم عقلياً دون المتوسط.","العمر العقلي − العمر الزمني":"الطرح يعطي فرقاً بالسنوات لا نسبة؛ فطفل عمره العقلي 12 وزمنه 10 يخرج له 2، والصحيح القسمة ثم الضرب في 100.","العمر العقلي + العمر الزمني ÷ 2":"جمع العمرين وقسمتهما على 2 يعطي متوسطهما بالسنوات، والنسبة الصحيحة قسمة العقلي على الزمني ثم الضرب في 100."}},"1ikdmoh":{"w":{"80":"80 ناتج القسمة المعكوسة 8 ÷ 10 × 100، والصحيح قسمة العقلي على الزمني: 10 ÷ 8 × 100 = 125.","100":"100 تعني تساوي العمرين، وهنا العمر العقلي 10 أكبر من الزمني 8، فالصحيح 10 ÷ 8 × 100 = 125.","180":"180 تعني عمراً عقلياً 14.4 لطفل عمره 8 سنوات، والصحيح 10 ÷ 8 × 100 = 125."},"e":"10 ÷ 8 × 100 = 125."},"1sh1slx":{"w":{"ثيرستون":"ثيرستون رأى الذكاء سبع قدرات أولية مستقلة نسبياً، ولم يقل بعامل عام واحد تشترك فيه جميع القدرات.","جاردنر":"جاردنر قسم الذكاء إلى ثمانية ذكاءات متعددة مستقلة، ولا يفترض عاملاً عاماً يجمعها كما عند سبيرمان.","ستيرنبرغ":"ستيرنبرغ يرى الذكاء ثلاثياً تحليلياً وإبداعياً وعملياً، لا عاملاً عاماً تصحبه عوامل خاصة."},"e":"سبيرمان صاحب نظرية العاملين."},"45i4y6":{"w":{"المتبلور":"المتبلور معارف مكتسبة كالمفردات والمعلومات العامة، وهي ضعيفة عند هذا الطالب، والبارز عنده حل المسائل الجديدة.","الوجداني":"الذكاء الوجداني فهم الانفعالات وإدارتها عند جولمان، وليس من تقسيم كاتل، والسؤال عن حل مسائل جديدة بسرعة.","العملي":"الذكاء العملي من نظرية ستيرنبرغ الثلاثية لا من تقسيم كاتل، وهو تكيف مع مواقف الحياة لا سرعة حل المسائل غير المألوفة."},"e":"السائل قدرة فطرية على حل المشكلات الجديدة."},"p5mljy":{"w":{"جاردنر":"جاردنر صاحب الذكاءات المتعددة الثمانية، أما نموذج العمليات والمحتوى والنواتج والتمييز بين التقاربي والتباعدي فلجيلفورد.","ثيرستون":"ثيرستون حدد سبع قدرات أولية في قائمة واحدة، لا نموذجاً ثلاثي الأبعاد من العمليات والمحتوى والنواتج.","بينيه":"بينيه وضع أول اختبار للذكاء ومفهوم العمر العقلي، ولم يصنف القدرات في أبعاد بنية العقل."}},"b6gf9q":{"w":{"المرونة":"المرونة تنوع فئات الأفكار، أما طلب أكبر عدد ممكن في دقيقتين فيقيس كمية الأفكار وهي الطلاقة.","الأصالة":"الأصالة ندرة الفكرة التي لا يذكرها غيره، والنشاط هنا يركز على عدد الاستخدامات في زمن محدد.","التوسع":"التوسع إضافة تفاصيل لفكرة واحدة وشرحها، والمعلم هنا يطلب أكبر عدد من الاستخدامات لا تفصيل أحدها."},"e":"الطلاقة كمية الأفكار في زمن محدد."},"18t7tjv":{"w":{"الطلاقة":"الطلاقة عدد الأفكار، والسؤال يصف فكرة لم يذكرها أحد، فتميزها بندرتها لا بكثرة ما قدمته الطالبة.","المرونة":"المرونة تنوع فئات الأفكار والتنقل بينها، والقرينة هنا أن الفكرة لم يذكرها أحد، وهذه ندرة لا تنوع.","الإفاضة":"الإفاضة إضافة تفاصيل تشرح الفكرة وتوسعها، والسؤال يركز على جدة الفكرة لا على تفاصيلها."}},"1adoxg1":{"w":{"الإلهام ← الإعداد ← الاحتضان ← التحقق":"يبدأ هذا الترتيب بالإلهام، وومضة الحل لا تأتي قبل جمع المعلومات وتركها تختمر؛ فالإلهام ثالث المراحل عند والاس.","الاحتضان ← الإعداد ← التحقق ← الإلهام":"الاحتضان تختمر فيه معلومات جُمعت في الإعداد فلا يسبقه، والتحقق اختبار لفكرة جاءت في الإلهام فلا يسبقه.","الإعداد ← الإلهام ← الاحتضان ← التحقق":"يقدّم الإلهام على الاحتضان، وعند والاس تُترك المشكلة تختمر أولاً ثم تأتي ومضة الحل."}},"xxgs6m":{"w":{"الإعداد":"الإعداد جمع المعلومات والانشغال المباشر بالمشكلة، والباحث هنا توقف عن التفكير فيها وذهب للمشي.","التحقق":"التحقق اختبار الحل بعد ظهوره، والسؤال عن المرحلة التي سبقت خطور الحل لا التي تليه.","الإلهام":"الإلهام ومضة الحل نفسها، والسؤال عن المرحلة التي قبلها حين تُركت المشكلة تختمر أثناء المشي."}},"i79ysr":{"w":{"يقرأ الطالب النص قراءة صامتة":"القراءة الصامتة مهارة معرفية تعالج النص نفسه، ولا يراقب فيها الطالب تفكيره ولا يقوّم خطته.","يحفظ الطالب القصيدة":"الحفظ عملية معرفية لتخزين المعلومة، وليس فيه تخطيط للتفكير أو مراقبة له أو تقويم.","ينسخ الطالب الدرس في دفتره":"النسخ نقل آلي للمحتوى، ولا يتضمن تفكيراً في التفكير كمراجعة الخطة وسؤال النفس عن أفضل طريقة."},"e":"مراقبة الخطة وتقويمها تفكير في التفكير."},"7zoqku":{"w":{"الزرقاء":"الزرقاء تضبط سير التفكير وتلخصه، أما طلب الأرقام والحقائق المتوفرة فعرض لمعلومات محايدة وهو البيضاء.","الحمراء":"الحمراء للمشاعر والحدس بلا تبرير، والقائد هنا يطلب أرقاماً وحقائق لا انطباعات شخصية.","السوداء":"السوداء للحذر والمخاطر ونقد العيوب، وعرض الأرقام المتوفرة لا يحكم على شيء بل يقدم معلومات محايدة."},"e":"البيضاء للحقائق والمعلومات المحايدة."},"19r5cnz":{"w":{"الخضراء":"الخضراء لتوليد بدائل وأفكار جديدة، والمعلم هنا يلخص ما توصلوا إليه ويحدد الخطوة التالية، وهذا ضبط للتفكير.","الصفراء":"الصفراء للفوائد والإيجابيات، أما التلخيص وتحديد الخطوة التالية في ختام النقاش فإدارة لعملية التفكير.","البيضاء":"البيضاء لعرض الحقائق والمعلومات، والتلخيص في نهاية النقاش وتحديد الخطوة التالية من وظائف الزرقاء."}},"lakqrx":{"w":{"الحقائق والمعلومات":"الحقائق والمعلومات المحايدة مجال القبعة البيضاء، أما الخضراء لون النمو فتختص بالأفكار الجديدة والبدائل.","السلبيات والمخاطر":"السلبيات والمخاطر مجال القبعة السوداء، وهي حذر ونقد، والخضراء توليد لأفكار جديدة.","الإيجابيات والفوائد":"الإيجابيات والفوائد مجال القبعة الصفراء، أما الخضراء فلاقتراح البدائل والأفكار الجديدة."},"e":"الخضراء لون النمو: الإبداع والاقتراحات."},"12kvq70":{"w":{"4MAT":"هذا النموذج لمكارثي دورة تعلم رباعية تراعي أنماط المتعلمين، لا برنامج ديبونو لتعليم التفكير في وحدات.","سكامبر":"سكامبر أداة لتوليد الأفكار بقائمة أسئلة للتعديل والتبديل، لا برنامج ديبونو المقسم إلى وحدات لتعليم التفكير.","VARK":"هذا تصنيف لأنماط التعلم كالبصري والسمعي والحركي، لا برنامج لتعليم مهارات التفكير في وحدات."},"e":"كورت برنامج ديبونو."},"7bn5u":{"w":{"التذكر والفهم والتطبيق":"هذه المستويات الثلاثة الدنيا في بلوم المعدل، والعليا التي تليها هي التحليل والتقويم والإبداع.","الفهم والتطبيق والتحليل":"يضم الفهم والتطبيق وهما من المستويات الدنيا، ويُسقط التقويم والإبداع وهما من العليا.","التذكر والتقويم والإبداع":"التذكر أدنى مستويات بلوم المعدل، والثالث من المستويات العليا هو التحليل لا التذكر."},"e":"المستويات العليا الثلاثة: تحليل، تقويم، إبداع."},"1acyssr":{"w":{"التقاربي":"التقاربي يتجه إلى إجابة واحدة صحيحة، والسؤال عن تفكير يولّد إجابات متعددة لمشكلة واحدة.","الناقد":"التفكير الناقد يفحص الأفكار ويقوّمها بمعايير، أما توليد إجابات متعددة فهو التفكير التباعدي أساس الإبداع.","الاستنباطي":"الاستنباط ينتقل من قاعدة عامة إلى نتيجة محددة تلزم عنها، فيصل إلى نتيجة واحدة لا إجابات متعددة."},"e":"التباعدي ينطلق إلى حلول متعددة."},"1nfmuh0":{"w":{"الخوف من الخطأ":"الخوف من الخطأ يمنع الطالب من طرح أفكاره الجريئة، فهو فعلاً من معوقات الإبداع لا الاستثناء المطلوب.","النقد المبكر للأفكار":"النقد المبكر أكبر معوقات الإبداع لأنه يوقف الفكرة قبل نضجها، ولذلك يرجئ العصف الذهني الحكم أثناء الطرح.","الجمود الذهني":"الجمود الذهني تمسك بطريقة واحدة مألوفة في التفكير، فهو من معوقات الإبداع المعروفة لا مما يُستثنى منها."},"e":"تقبل الغريب من محفزات الإبداع."},"7fvfa3":{"w":{"الوعي بالذات":"الوعي بالذات أي فهم الفرد لانفعالاته، وهو من مكونات الذكاء الوجداني الخمسة عند جولمان فلا يكون الاستثناء.","التعاطف":"التعاطف فهم مشاعر الآخرين، وهو فعلاً من مكونات الذكاء الوجداني الخمسة عند جولمان.","تنظيم الانفعالات":"تنظيم الانفعالات أي إدارتها وضبطها، وهو من مكونات جولمان الخمسة، والخارج عنها القدرة العددية."}},"2bu0xv":{"w":{"الذكاء المنطقي الرياضي":"الذكاء المنطقي الرياضي قدرة على الأعداد والاستدلال، ومشكلة الطالب هنا في ضبط غضبه وفهم مشاعر زملائه.","الطلاقة اللفظية":"الطلاقة اللفظية كثرة الألفاظ وسرعة إنتاجها، ومشكلة الطالب هنا ليست في الكلام بل في ضبط غضبه وفهم مشاعر زملائه.","الذكاء المكاني":"الذكاء المكاني إدراك الأشكال والفراغ وتصورها، ولا صلة له بسرعة التوتر وضعف فهم مشاعر الآخرين."}},"5p1gs2":{"w":{"الانتباه":"الانتباه في نموذج كيلر يُثار بالمفاجأة والتنويع، والمهام المتدرجة لا تثيره بل تضمن نجاحاً مبكراً يبني الثقة.","الصلة (الملاءمة)":"الصلة تحققت في الدرس بربطه بخصومات المتاجر، أما المهام المتدرجة فتضمن نجاحاً مبكراً يبني الثقة.","الرضا":"الرضا تحقق في ختام الدرس بإعلان الإنجازات، والمهام المتدرجة التي سبقته تبني ثقة الطالب بقدرته على النجاح."},"e":"نموذج كيلر للدافعية (ARCS) أربعة عناصر: الانتباه، والصلة بحياة المتعلم، والثقة بقدرته على النجاح، والرضا عن نتائج تعلمه. المهام المتدرجة تبني الثقة لأنها تضمن نجاحاً مبكراً."},"1iayk6a":{"w":{"المقارنة":"المقارنة مهارة أساسية قد تدخل عند موازنة المواقع، لكن النشاط ينتهي باختيار الأنسب وتبريره، وهذا اتخاذ قرار.","التصنيف":"التصنيف توزيع الأشياء في فئات وفق خصائص مشتركة، والنشاط هنا لا يجمع المواقع في فئات بل يختار أحدها بمعايير ويبرره.","الملاحظة الدقيقة":"الملاحظة مهارة أساسية لجمع المعلومات بالحواس، وقد تخدم النشاط، لكن غايته اختيار مسبَّب بين بدائل وفق معايير."},"e":"اتخاذ القرار من مهارات التفكير المركب، ويقوم على وضع بدائل وموازنتها وفق معايير ثم اختيار الأنسب وتبريره. ومن مهارات التفكير المركب أيضاً التفكير الناقد والإبداعي وحل المشكلات."},"1jls3a4":{"w":{"الإقدام على مخاطر مسؤولة":"الإقدام على مخاطر مسؤولة تجريب الجديد بجرأة محسوبة، والطالب هنا يتأنى ويفهم ويخطط قبل الحل، وهذا ضبط للتسرع.","إيجاد الدعابة":"إيجاد الدعابة رؤية الجانب المرح في المواقف، ولا صلة له بالتأني وقراءة السؤال كاملاً قبل البدء.","الاستجابة بدهشة ورهبة":"الاستجابة بدهشة ورهبة تعني الفضول والاستمتاع بالاكتشاف، أما قراءة السؤال كاملاً والتخطيط قبل الحل فتحكم بالتهور."}},"1k3nyaa":{"w":{"التفكير التبادلي":"التفكير التبادلي تعاون مع الآخرين وتبادل للأفكار، والسلوك البارز هنا الإصرار على الحل بعد فشل ثلاث طرق.","الإصغاء بتفهم وتعاطف":"الإصغاء بتفهم وتعاطف فهم كلام الآخرين ومشاعرهم، أما تجريب طريقة رابعة بعد ثلاث فاشلة فعدم استسلام.","جمع البيانات باستخدام جميع الحواس":"جمع البيانات بالحواس يعني الملاحظة والاستماع واللمس لفهم الموقف، والطالب هنا يكرر المحاولة بطرق جديدة حتى يصل إلى الحل."}},"flsfij":{"w":{"مجموعة معارف نظرية يحفظها الطالب عن مهارات التفكير وتصنيفاتها":"عادات العقل سلوك ذكي يمارسه الطالب أمام مشكلة، لا معلومات يحفظها عن مهارات التفكير وتصنيفاتها.","قدرات عقلية فطرية ثابتة لا تتأثر بالتعليم ولا بالتدريب":"عادات العقل تُتعلم وتُنمّى بالنمذجة والممارسة، فليست قدرات فطرية ثابتة لا يغيرها التدريب.","خطوات ثابتة لحل المسائل الرياضية":"عادات العقل لا تختص بالرياضيات ولا تتبع خطوات محددة، بل هي سلوكيات ذكية أمام أي مشكلة لا يُعرف حلها فوراً."}},"1k50say":{"w":{"تذكيرها بأهمية الرياضيات لمستقبلها في بداية كل حصة":"التذكير المتكرر بالأهمية وعظ يخاطب الجانب المعرفي فقط، ولا يمنحها خبرة نجاح تغير شعورها بأنها لا تفهم.","مقارنتها بزميلاتها المتفوقات لتحفيزها":"المقارنة بالمتفوقات تؤكد شعورها بالعجز وتزيد تجنبها، والاتجاه السلبي يُعدّل بخبرات نجاح متدرجة لا بالمقارنة.","إعفاؤها من كل المهام الصعبة لحمايتها من الإحباط والقلق":"الإعفاء من المهام خفض للتوقعات يثبّت اعتقادها بأنها لا تستطيع، بدل خبرات نجاح متدرجة تغيّر هذا الاعتقاد."},"e":"مؤشر 5.3: يبين تأثير الاتجاهات والقيم على التعلم وكيفية استخدامها لدعمه؛ الاتجاه السلبي يُعدّل بخبرات نجاح وربط بالحياة."},"ho36mt":{"w":{"الوجداني ثم السلوكي ثم المعرفي":"العبارة الأولى اعتقاد بالأهمية وهو المكون المعرفي لا الوجداني، فالشعور بالمتعة هو الوجداني ويأتي ثانياً.","السلوكي ثم المعرفي ثم الوجداني":"العبارة الأولى اعتقاد وليست فعلاً فهي المكون المعرفي، أما السلوكي فالميل إلى استعارة الكتب في آخر العبارات.","المعرفي ثم السلوكي ثم الوجداني":"يبدأ صحيحاً بالمعرفي ثم يعكس الأخيرين، فالشعور بالمتعة وجداني يأتي ثانياً، والميل إلى استعارة الكتب سلوكي يأتي ثالثاً."}},"otoeb28":{"w":{"يستخدم الطلاب الإنترنت لتحديد معلومات عن الكاتب.":"البحث عن معلومات الكاتب جمع واستدعاء لمعلومات موجودة، ولا ينتج فيه الطالب فكرة جديدة كما في تغيير نهاية القصة.","يرسم الطلاب صورة لبطل القصة.":"رسم البطل إعادة إنتاج لشخصية موصوفة في القصة، لا إضافة أصيلة جديدة كتأليف نهاية مختلفة لها.","يصور الطلاب مقطعَ فيديو لإعادة تمثيل أحداث مختارة من القصة.":"إعادة تمثيل الأحداث تنقل ما في القصة كما هو، فهي إعادة إنتاج لا توليد لأفكار جديدة أصيلة."},"e":"إعادة كتابة القصة بنهاية جديدة تتطلب إنتاج أفكار أصيلة وهذا جوهر الإبداع. (المعيار 8.2)"},"onn9mtx":{"w":{"وضع خط زمني لتسلسل الأحداث خلال فترة التوسع باتجاه الغرب.":"الخط الزمني ترتيب للأحداث كما وقعت، فهو تذكر وتسلسل لا يحلل دوافع المستكشفين ولا يحكم عليها.","إكمال اختبار قصير من فقرات الاختيار من متعدد في نهاية الوحدة.":"الاختبار القصير بالاختيار من متعدد يطلب اختيار إجابة جاهزة فهو أقرب إلى التذكر، ولا يُنتج فيه الطالب تحليلاً وحكماً كالمقال.","رسم صورة تخيلية لأحد المستكشفين الأوائل في تلك الفترة.":"الرسم التخيلي نشاط إبداعي يعتمد على الخيال، أما التفكير الناقد فيحلل دوافع المستكشفين ويحكم عليها بمعايير."},"e":"كتابة مقال من منظور شخصية تاريخية تتطلب تحليل الأحداث وتفسير دوافعها والحكم عليها، وهي مستويات عليا. (المعيار 8.2)"},"oqcmot5":{"w":{"أساليب الانضباط المتبعة في المنزل.":"أساليب الانضباط تنظم سلوك الطفل في البيت، وأثرها في نظرته لكفاءته العلمية أبعد وأضعف من توقعات والديه المعلنة عن قدراته.","الترتيب بين الإخوة وطبيعة العلاقة بهم.":"ترتيب الطفل بين إخوته وعلاقته بهم عامل أسري عام، وأثره في نظرته لكفاءته العلمية أضعف من توقعات والديه المعلنة عن قدراته.","أنواع الألعاب في المنزل والقيمة التعليمية التي تحملها.":"الألعاب التعليمية قد تنمي مهارات الطفل، لكن نظرته لكفاءته تتشكل أكثر من توقعات والديه المعلنة عن قدراته."},"e":"إدراك الطفل لكفاءته (الكفاءة الذاتية) يتشكل كثيرًا من توقعات الوالدين المعلنة عن قدراته. (المعيار القديم 1.2)"},"o1055as9":{"w":{"أن يستخدم الطلاب الإنترنت لتحديد معلومات عن الكاتب.":"البحث عن معلومات الكاتب تذكّر وجمع لما هو موجود، ولا يضيف الطالب فيه شيئاً جديداً إلى القصة.","أن يرسم الطلاب صورة ثابتة لبطل القصة.":"رسم صورة البطل ينقل ما وصفته القصة، فهو إعادة إنتاج لما هو موجود لا إنتاج أصيل كتغيير النهاية.","أن يصور الطلاب مقطع فيديو لإعادة تمثيل أحداث القصة.":"تمثيل أحداث القصة كما وردت إعادة إنتاج لها، ولا يتطلب طلاقة ومرونة في توليد أفكار جديدة كما يتطلبه تغيير النهاية."},"e":"تغيير نهاية القصة إنتاج أصيل يتطلب طلاقة ومرونة وهذا جوهر الإبداع. (المعيار القديم 1.2، صعوبة 0.484)"},"o8turda":{"w":{"وضع خط زمني لتسلسل الأحداث خلال فترة التوسع باتجاه الغرب.":"ترتيب الأحداث على خط زمني يعتمد على تذكر تسلسلها، ولا يتطلب تحليل دوافع المستكشفين وإصدار أحكام عليها.","إكمال اختبار قصير من فقرات الاختيار من متعدد في نهاية الوحدة التدريسية.":"الاختبار القصير هنا يستدعي ما دُرس في الوحدة فهو في مستوى التذكر، لا في أعلى مستويات التفكير الناقد.","رسم صورة تخيلية لأحد المستكشفين الأوائل في تلك الفترة.":"الرسم التخيلي يعتمد على الخيال فهو أقرب إلى الإبداع، ولا يتضمن تفسير الأحداث والحكم عليها الذي يميز التفكير الناقد."},"e":"المقال من منظور الشخصيات يتطلب تحليل الدوافع وتفسير الأحداث وإصدار أحكام، وهي أعلى مستويات التفكير الناقد. (المعيار القديم 4.2، صعوبة 0.387)"},"ospaimv":{"w":{"ما مكونات الماء؟":"سؤال مكونات الماء له إجابة علمية واحدة محفوظة، فهو تذكر وتفكير تقاربي لا يولّد حلولاً متعددة.","عدِّد أنواع الطاقة المتجددة؟":"التعداد هنا استرجاع لقائمة معروفة من الأنواع، فتعدد الإجابات لا يعني إبداعاً لأن الطالب لا يولّد جديداً.","متى ولد النبي صلى الله عليه وسلم؟":"سؤال عن زمن حدث تاريخي محدد، فإجابته معلومة واحدة تُسترجع من الذاكرة ولا تستدعي توليد أفكار."},"e":"السؤال المفتوح «كيف نحافظ…» يقبل إجابات متعددة ويستدعي توليد حلول، وهذا ما يشجع الإبداع. (المعيار القديم 4.2، صعوبة 0.721)"},"8n1cb":{"w":{"المفوّض":"المفوّض يسلّم الطلاب مسؤولية تعلمهم ويكتفي بالمتابعة، أما الدور المطلوب هنا فتوجيه المتعلم إلى المصادر وطرق التعلم.","التقليدي":"المعلم التقليدي يلقّن المعلومة والطالب متلقٍّ، والدور المطلوب هنا توجيه المتعلم إلى المصادر ليتعلم منها بنفسه.","الممتحن":"الممتحن يقيس تحصيل الطالب ويحكم عليه بالاختبار، أما توجيه المتعلم إلى مصادر التعلم وطرقه فدور المرشد."},"e":"المعلم المرشد يوجه المتعلم."},"1a6k3x5":{"w":{"مرادف لأسلوب المعلم الشخصي":"الأسلوب بصمة المعلم الشخصية في تنفيذ الطريقة، أما النموذج فتصور نظري عام لخطوات التدريس لا يختص بمعلم بعينه.","الفلسفة العامة التي يستند إليها التدريس":"هذا تعريف المدخل نفسه الذي يُطلب التفريق عنه، فالمدخل فلسفة ومنطلقات، والنموذج تصور لخطوات التدريس تُشتق منه الاستراتيجيات.","أداة أو وسيلة تعليمية":"الوسيلة أداة أو مادة تخدم أي طريقة كالسبورة الذكية، والنموذج تصور نظري لخطوات التدريس لا أداة ملموسة."},"e":"النموذج تصور نظري لخطوات التدريس (جويس وويل)"},"enc949":{"w":{"المنطقي":"المدخل المنطقي يرتب محتوى المادة نفسها من البسيط إلى المعقد، والمعلم هنا ربط الرياضيات بالفقه والجغرافيا خارج حدود مادته.","الضبط":"مدخل الضبط يقوم على التحكم في سلوك المتعلم، ولا صلة له بربط درس النسبة بالزكاة وقراءة الخرائط.","النشاط":"مدخل النشاط يقوم على فعل الطالب وممارسته، والسمة البارزة هنا ربط النسبة بمواد أخرى بعلاقات أفقية، وهذا هو التكامل."},"e":"المدخل التكاملي يربط المادة بالمواد الأخرى بعلاقات أفقية."},"g0jeko":{"w":{"اختيار المشروع":"اختيار المشروع وهدفه أول خطوات كلباترك، والسؤال يطلب الخطوة التي تأتي بعد التقويم في نهاية المشروع.","تشكيل المجموعات":"تشكيل المجموعات إجراء تنظيمي في بداية العمل، والسؤال يطلب الخطوة التي تلي التقويم وتختم المشروع.","جمع الأدوات":"جمع الأدوات يسبق التنفيذ أو يرافقه، والسؤال يطلب ما يأتي بعد التقويم، وهو كتابة التقرير كما تضيفه كتب عربية."},"e":"خطوات كلباترك: اختيار الهدف، فالتخطيط، فالتنفيذ، فالتقويم، وتضيف كتب عربية كتابة التقرير خطوة أخيرة."},"jar6g5":{"w":{"التعليم الفردي":"التعليم الفردي أن يؤدي كل طالب المهام نفسها منفرداً، والمعلم هنا جعل لكل طالب مهام مختلفة بحسب ميوله.","التعليم الجمعي":"التعليم الجمعي يقدَّم للصف كله بمهام موحدة، والمعلم هنا خصص لكل طالب مهامه وأنشطته بحسب توجهه.","التدريس المباشر":"في التدريس المباشر يشرح المعلم ويعرض للجميع ثم يطبقون، ولا يقوم على تصميم مهام خاصة بكل طالب بحسب ميوله."},"e":"التفريدي يخصص المهام لكل طالب."},"6yjeq4":{"w":{"التعلم التعاوني":"التعلم التعاوني عمل جماعي في مجموعات غير متجانسة، والمطلوب هنا برنامج علاجي فردي يُصمم لطالب واحد بعد تشخيصه.","التعليم المبرمج الخطي":"البرمجة الخطية مسار واحد يسير عليه جميع الطلاب، أما البرنامج هنا فمصمم لطالب بعينه بعد تشخيص مستواه.","التدريس المصغر":"التدريس المصغر تدريب للمعلم على مهارة تدريسية واحدة، لا برنامج علاجي يُصمم لطالب بعد تشخيص مستواه."},"e":"التعلم الموصوف للفرد برنامج فردي علاجي بعد التشخيص."},"s44etr":{"w":{"الإنتاجية، التعرف، الإنهاء، بلورة معايير العمل":"الإنتاجية لا تسبق التعرف على المهمة، وبلورة معايير العمل بتوزيع الأدوار تأتي قبل الإنتاجية لا بعد الإنهاء.","بلورة معايير العمل، الإنهاء، التعرف، الإنتاجية":"توزيع الأدوار في بلورة المعايير يحتاج أولاً إلى التعرف على المهمة، والإنهاء بعرض النتائج يأتي آخراً بعد الإنتاجية.","الإنهاء، الإنتاجية، بلورة معايير العمل، التعرف":"هذا الترتيب مقلوب كاملاً، فالمجموعة تبدأ بالتعرف على المهمة ومعطياتها، وتختم بعرض ما توصلت إليه في مرحلة الإنهاء."}},"13e3c8m":{"w":{"لعب الأدوار":"لعب الأدوار تقمص الطلاب شخصيات في موقف يمثلونه، ولا يقوم على التنافس الفردي أو الجماعي الذي يصفه السؤال.","المحاكاة":"المحاكاة تمثيل لموقف واقعي كبديل آمن للتجربة الحقيقية، والسمة المميزة هنا تنافس ممتع موجه نحو أهداف الدرس.","العصف الذهني":"العصف الذهني توليد أكبر عدد من الأفكار مع إرجاء النقد، ولا يقوم على تنافس الطلاب كما في السؤال."},"e":"الألعاب التعليمية تنافس ممتع موجه."},"jcel29":{"w":{"المحاضرة والإلقاء":"المحاضرة يقودها المعلم مصدراً للمعرفة والطالب متلقٍّ، والسؤال يطلب وسائل يتعلم بها الطالب دون تدخل مباشر من المعلم.","العرض العملي":"في العرض العملي يؤدي المعلم المهارة بنفسه مع الشرح أمام الطلاب، فهو طريقة يقودها المعلم لا وسيلة تعلم ذاتي.","المناقشة الجماعية":"المناقشة الجماعية يديرها المعلم بالأسئلة وتنظيم الحوار بين الطلاب، فهي طريقة صفية لا وسيلة تعلم ذاتي."},"e":"التعليم المبرمج والحقائب والموديولات والحاسوب وسائل تعلم ذاتي."},"10jreiq":{"w":{"المادة الدراسية":"مدخل المادة الدراسية يهتم بمحتوى الكتاب المدرسي نفسه، والسؤال يستبعد ذلك صراحة ويطلب المفاهيم الكبرى وطرق البحث.","الضبط":"مدخل الضبط من التوجه السلوكي ويقوم على التحكم في السلوك، لا على مفاهيم العلم الكبرى وطرق البحث فيه.","النشاط":"مدخل النشاط يرتبط بديوي ويقوم على فعل الطالب وخبرته، أما الاهتمام بالمفاهيم الكبرى وطرائق العلماء فهو بنية العلم."},"e":"مدخل بنية العلم يركز على المفاهيم الكبرى وطرائق العلماء"},"1gk5xn":{"w":{"سكنر وبافلوف وواطسون":"سكنر وبافلوف وواطسون رواد المدرسة السلوكية في الإشراط والتعزيز، لا واضعو الأسس النظرية للتعلم التعاوني.","بياجيه وكوهلر":"بياجيه وكوهلر من رواد المدرسة المعرفية، كالنمو المعرفي والتعلم بالاستبصار، وليسا من واضعي أسس التعلم التعاوني.","أوزوبل وبرونر":"أوزوبل وبرونر من رواد المدخل المعرفي في التعلم ذي المعنى والاكتشاف، لا من واضعي أسس التعلم التعاوني."},"e":"ديوي وباركر ودويتش ثم جونسون وجونسون رواد التعلم التعاوني."},"mreif6":{"w":{"توحيد سرعة التعلم لجميع الطلاب":"التعليم الفردي يتيح لكل طالب أن يتعلم بسرعته وقدرته، فتوحيد السرعة للجميع يناقض فكرته الأساسية.","زيادة التنافس بين الطلاب":"التنافس سمة البيئة التنافسية التي يرتبط فيها فوز طالب بخسارة آخر، والتعليم الفردي يركز على تقدم كل طالب نحو الإتقان.","تقليل دور الطالب في تعلمه":"التعليم الفردي ينمي استقلالية الطالب ويحمّله مسؤولية أكبر في تعلمه، فتقليل دوره عكس أهدافه."},"e":"التعليم الفردي يراعي الفروق ويسعى للإتقان والاستقلالية والإبداع."},"1an8kq":{"w":{"أسلوب التدريس":"الأسلوب بصمة المعلم الشخصية في تنفيذ الطريقة، أما «أدرّس وفق المدخل البنائي» فإعلان عن فلسفة عامة تنبثق منها الطرق.","تقنية التدريس":"التقنية أداة تخدم الطريقة كالسبورة الذكية، والسؤال يصف إطاراً فكرياً عاماً تنبثق منه طرق التدريس.","طريقة التدريس":"الطريقة إجراءات تنفيذية يشترك فيها المعلمون وتنبثق من المدخل، والسؤال يصف الفلسفة التي تنبثق منها الطرق نفسها."},"e":"المدخل هو التصور النظري الذي تقوم عليه الطريقة."},"1fcnjc7":{"w":{"استراتيجية ← مدخل ← أسلوب ← طريقة":"المدخل فلسفة تضم الاستراتيجيات فلا يأتي بعدها، والأسلوب أخص من الطريقة لأنه طابع المعلم الشخصي في تنفيذها.","طريقة ← استراتيجية ← مدخل ← أسلوب":"هذا الترتيب يبدأ بالطريقة وهي أخص من الاستراتيجية، ويضع المدخل ثالثاً مع أنه الفلسفة الأعم التي تأتي أولاً.","أسلوب ← طريقة ← استراتيجية ← مدخل":"هذا ترتيب من الأخص إلى الأعم، أي عكس المطلوب، فالمدخل الأعم يأتي أولاً والأسلوب الشخصي آخراً."},"e":"المدخل فلسفة عامة تضم استراتيجيات، والاستراتيجية خطة تضم طرقاً، والطريقة تُنفذ بأساليب شخصية."},"c3uyv0":{"w":{"المحاضرة":"المحاضرة عرض لفظي والطالب فيها متلقٍّ، ولا تتضمن أداء المهارة أمامه ثم تطبيقه لها كما في درس الوضوء.","لعب الأدوار":"لعب الأدوار تمثيل الطلاب لموقف اجتماعي بشخصياته، والمعلم هنا يؤدي مهارة أدائية بنفسه خطوة خطوة ثم يطبقها الطلاب.","الاستقصاء":"في الاستقصاء يولّد الطالب المعرفة بالأسئلة والبحث بنفسه، والمعلم هنا هو من أدى المهارة وشرحها قبل أن يطبقها الطلاب."},"e":"العرض العملي يؤدي فيه المعلم المهارة أمام الطلاب ثم يطبقونها، ويناسب المهارات الأدائية."},"11m01ky":{"w":{"اختبار الفروض":"اختبار الفروض يكون بالملاحظة والتجربة لقبولها أو رفضها، والسؤال يصف اقتراح تفسيرات محتملة لا تجريبها.","الشعور بالمشكلة":"الشعور بالمشكلة أول خطوة قبل تحديدها، والسؤال يذكر أن الطلاب حددوا المشكلة فعلاً ثم انتقلوا إلى اقتراح التفسيرات.","التعميم":"التعميم يأتي في آخر الخطوات بعد التحقق من الفروض، والطلاب هنا ما زالوا يقترحون تفسيرات محتملة لم تُختبر بعد."},"e":"الفروض تفسيرات مؤقتة محتملة للمشكلة."},"1aqdjt9":{"w":{"أنها تبدأ بالشعور بالمشكلة":"الشعور بالمشكلة أول خطوات حل المشكلات عند ديوي، فلا يميز المشروعات عنها، والمشروع يبدأ باختيار الهدف.","أنها تعتمد على وضع الفروض":"وضع الفروض واختبارها من صميم خطوات حل المشكلات، فلا يصلح أن يكون هو ما يميز المشروعات عنها.","أنها تُنفذ داخل الصف فقط":"المشروعات غالباً ميدانية تمتد خارج الصف، فحصرها داخله وصف غير صحيح لها، والمميز الحقيقي أنها تنتهي بمنتج."},"e":"المشروع عمل هادف ممتد ينتهي بمنتج (حديقة، مجسم، معرض)."},"g5mqs1":{"w":{"البرمجة الخطية":"البرمجة الخطية لسكنر مسار واحد مستقيم يسير عليه الجميع، ولا تحوّل المخطئ إلى إطار علاجي كما في السؤال.","البرمجة التعاونية":"النوعان الرئيسان للبرمجة خطية ومتشعبة، والتعليم المبرمج فردي أصلاً، وتحويل المخطئ إلى إطار علاجي سمة المتشعبة.","البرمجة الاستقرائية":"الاستقراء طريقة تدريس تسير من الأمثلة إلى القاعدة لا نوع برمجة، والتفرع إلى إطار علاجي عند الخطأ سمة المتشعبة لكراودر."},"e":"البرمجة المتشعبة (كراودر) تتفرع حسب استجابة الطالب وتقدم إطارات علاجية."},"wmmz9i":{"w":{"تقسيم المادة إلى خطوات صغيرة":"تقسيم المادة إلى خطوات صغيرة متتابعة من أسس التعليم المبرمج عند سكنر، فهو خاصية فيه لا المستثنى منها.","التعزيز الفوري للاستجابة الصحيحة":"التعزيز الفوري تطبيق للإشراط الإجرائي وخاصية أساسية في التعليم المبرمج، فلا يكون هو المستثنى.","التقدم بسرعة المتعلم الخاصة":"الخطو الذاتي، أي تقدم كل متعلم بسرعته، خاصية أساسية في التعليم المبرمج، فلا يصح أن يكون المستثنى."},"e":"التعليم المبرمج فردي ولا ينمي التفاعل الاجتماعي، وهذا من عيوبه."},"xs7w15":{"w":{"المشروع":"المشروع عمل هادف ممتد ينتهي بمنتج غالباً، لا وحدة صغيرة مستقلة من برنامج أكبر يدرسها الطالب ذاتياً ثم يُقوَّم.","الاستقصاء":"الاستقصاء طريقة يولّد فيها الطالب المعرفة بالأسئلة والبحث، لا وحدة تعليمية مستقلة جاهزة ضمن برنامج أكبر.","التدريس المصغر":"التدريس المصغر تدريب للمعلم على مهارة تدريسية واحدة، لا وحدة يدرسها الطالب ذاتياً ضمن برنامج أكبر."},"e":"الموديول (الوحدة النسقية) وحدة صغيرة مستقلة للتعلم الذاتي."},"1jkekz0":{"w":{"متجانسة من المتفوقين فقط":"مجموعات التعلم التعاوني غير متجانسة ليساعد المتقن زميله، وجمع المتفوقين وحدهم يحرم الآخرين من تعليم الأقران.","كبيرة تضم نصف الصف":"حجم المجموعة التعاونية من 4 إلى 6 طلاب، ونصف الصف عدد كبير يضعف التفاعل ويخفي مسؤولية كل عضو.","مكونة من الأصدقاء الذين يختارون بعضهم":"مجموعات الأصدقاء تجمع المتشابهين غالباً وتضعف التفاعل والمسؤولية، والأفضل أن يشكّلها المعلم غير متجانسة في التحصيل."},"e":"المجموعات غير المتجانسة الصغيرة تتيح تعليم الأقران ومساعدة الضعفاء."},"1yn131u":{"w":{"الشرح الكامل للمهمة لكل مجموعة على حدة":"الشرح الكامل لكل مجموعة يعيد المعلم ملقّناً ويلغي دور المجموعة في التفكير، ودوره هنا ميسّر يدعم عند الحاجة.","الجلوس في مكتبه حتى تنتهي المجموعات":"الانسحاب التام يفقد المجموعات المتابعة والتوجيه، والمعلم في التعلم التعاوني ميسّر يلاحظ ويتدخل عند الحاجة.","حل المهمة أمام الصف ليقلدها الطلاب":"حل المهمة أمام الصف يلغي عمل المجموعات ويجعل الطلاب مقلدين، والمطلوب أن يصلوا إليها بتعاونهم مع دعم المعلم عند الحاجة."},"e":"المعلم في التعاوني ميسر يلاحظ ويقدم الدعم عند الحاجة."},"1cd2iks":{"w":{"إيقاف التمثيل فوراً وتصحيح الأداء أمام الجميع":"المشهد في لعب الأدوار لا يُقاطع ما دام آمناً، والإيقاف والتصحيح أمام الجميع يكسران الموقف ويحرجان الطالب.","استبدال الطالب بآخر في منتصف المشهد":"الاستبدال في منتصف المشهد مقاطعة تكسر الموقف وتحرج الطالب، ويمكن إعادة المشهد بعد مناقشته في مرحلة التقويم.","إنهاء النشاط وتحويله إلى محاضرة":"أداء الطالب المختلف مادة للنقاش بعد المشهد، والسؤال ينص على أنه دون إساءة، فلا داعي لإلغاء النشاط كله."},"e":"في لعب الأدوار لا يُقاطع المشهد ما دام آمناً؛ فالمناقشة والتقويم مرحلة تلي التمثيل، وقد يُعاد المشهد بعدها."},"1uf76yx":{"w":{"الطالب الضعيف وحده":"حصر الفائدة في الطالب الضعيف يغفل أن الشرح يرسّخ فهم القرين المعلّم نفسه، فتدريس الأقران يفيد الطرفين.","الطالب المتفوق وحده":"المتفوق يرسخ فهمه بالشرح، لكن زميله يستفيد أيضاً من شرح بلغة قريبة منه، فالفائدة للطرفين لا لأحدهما.","المعلم فقط لأنه وفر وقته":"توفير وقت المعلم ليس غاية تدريس الأقران، فالمستفيد الأساسي الطالبان: المعلّم يرسخ فهمه والمتعلم يتلقى شرحاً قريباً منه."},"e":"من مزايا تدريس الأقران أن الشرح يعمق فهم القرين المعلّم، وأن المتعلم يستفيد من لغة قريبة منه."},"x4131b":{"w":{"التعلم التعاوني":"التعلم التعاوني يتعلم فيه الطالب بتفاعله مع زملائه والمعلم ميسّر، فهو متمركز حول المتعلم ولا يكون المستثنى.","الاكتشاف الموجه":"في الاكتشاف الموجه يصل الطالب إلى المفهوم بنفسه بتوجيه من المعلم، فهو من الطرق المتمركزة حول المتعلم.","المشروعات":"المشروعات من أكثر الطرق تطلباً لفعالية المتعلم، إذ يخطط وينفذ ويقوّم بنفسه، فهي متمركزة حوله."},"e":"المحاضرة تتمركز حول المعلم بوصفه مصدر المعرفة."},"1dw9itr":{"w":{"المناظرة":"المناظرة مجموعة مؤيدة وأخرى معارضة يحكم بينهما محكّمون، والمتخصصون هنا يعرض كل منهم جانباً من الموضوع لا موقفاً مضاداً.","لعب الأدوار":"لعب الأدوار تمثيل الطلاب لشخصيات في موقف، والموقف هنا عرض متخصصين حقيقيين لجوانب موضوع واحد ثم نقاش.","العصف الذهني":"العصف الذهني توليد أفكار كثيرة من الطلاب أنفسهم مع إرجاء النقد، والعرض هنا يقدمه متخصصون للطلاب."},"e":"الندوة عرض عدة متخصصين لجوانب موضوع واحد يعقبه نقاش."},"184smdu":{"w":{"الاكتشاف الحر غير الموجه":"في الاكتشاف الحر يحدد الطالب المشكلة والأدوات بنفسه، والمعلم هنا قدّم حدثاً متناقضاً مقصوداً وقيّد الأسئلة بنعم أو لا.","العصف الذهني":"العصف الذهني توليد أكبر عدد من الأفكار مع إرجاء النقد، لا جمع بيانات بأسئلة جوابها نعم أو لا لتفسير حدث محير.","التعلم القائم على المشروع":"المشروع عمل ممتد يمر بالتخطيط والتنفيذ وينتهي بمنتج، والموقف هنا تفسير حدث متناقض بأسئلة جوابها نعم أو لا."},"e":"التدريب الاستقصائي لسوشمان يبدأ بحدث متناقض يثير الحيرة، ثم يجمع الطلاب المعلومات بأسئلة إجابتها نعم أو لا، ثم يصوغون الفروض ويختبرونها حتى يفسروا الحدث."},"1frzxcz":{"w":{"الإلقائي والحواري والاستقرائي والاستنباطي (القياسي)":"هذه طرق تدريس كالمحاضرة والحوار والاستقراء، وهي تندرج تحت المداخل ولا تمثل المداخل العامة الأربعة في المؤشر 7.1.","التعاوني والتنافسي والفردي والجماعي":"هذه أنماط لتنظيم عمل الطلاب وبيئات التعلم، كالتعاونية والتنافسية والفردية، لا مداخل عامة تقوم على أسس نظرية.","التشخيصي والتكويني والختامي والتتبعي":"هذه أنواع للتقويم بحسب توقيته وغرضه، لا مداخل للتدريس تقوم على أسس نظرية كالسلوكية والمعرفية."},"e":"مؤشرات 7.1 للممارس تتناول أسس المدخل السلوكي والمعرفي والإنساني أو الشخصي والاجتماعي"},"1sb2pph":{"w":{"حفظ أسماء رواد كل مدخل ونظرياتهم وتواريخ ظهورها":"حفظ الأسماء والتواريخ ليس هو الغاية من معرفة الأسس، فالمؤشر يربط أهميتها بتحفيز المتعلمين وتنمية قدراتهم وتعديل سلوكهم.","الالتزام بمدخل واحد في جميع الدروس طوال العام الدراسي":"معرفة المداخل المتعددة تساعد على اختيار الأنسب لكل موقف وطلاب، والتقيد بمدخل واحد طوال العام يعطّل هذا الاختيار.","تقليل الحاجة إلى التخطيط للدروس":"معرفة الأسس النظرية توجّه التخطيط نحو اختيار ما يحفز الطلاب، ولا تغني المعلم عن التخطيط لدروسه."}},"chnpy6":{"w":{"الإنساني":"المدخل الإنساني يعنى بالجوانب الوجدانية والاستقلالية والوعي بالذات، والمعلم هنا يحلل المهارة إلى خطوات صغيرة ويعزز كل استجابة فوراً.","الاجتماعي":"المدخل الاجتماعي يوظف التفاعل ونمذجة السلوك ليحاكيه الطلاب، والقرينة هنا خطوات صغيرة متتابعة وتعزيز فوري وإتقان قبل الانتقال.","المعرفي":"المدخل المعرفي يمكّن الطالب من التفكير والاكتشاف ليصل إلى المعرفة بجهده، أما الخطوات الصغيرة مع التعزيز الفوري فأسس سلوكية."}},"18ohill":{"w":{"السلوكي":"المدخل السلوكي يقدّم المهمة في خطوات صغيرة مع تعزيز فوري، والمعلم هنا ترك الطلاب يجمعون البيانات ويصلون إلى التفسير بأنفسهم.","الإنساني":"المدخل الإنساني يعنى بالمشاعر والوعي بالذات والاستقلالية، والقرينة هنا ظاهرة محيرة يفسرها الطلاب بالتفكير والبحث، وهذا معرفي.","الاجتماعي":"المدخل الاجتماعي يقوم على التفاعل ونمذجة السلوك ليحاكيه الطلاب، والمطلوب هنا أن يصلوا إلى التفسير بالبحث دون أن يُقدَّم لهم."}},"1s31fgm":{"w":{"تعزيز الاستجابات الصحيحة فوراً لتثبيتها":"التعزيز الفوري من أسس المدخل السلوكي، والمنظم المتقدم لأوزوبل يهيئ ذهن الطالب بفكرة عامة تُربط بها التفاصيل الجديدة.","تنمية الوعي بالذات والمسؤولية":"الوعي بالذات والمسؤولية من اهتمامات المدخل الإنساني، والمنظم المتقدم أداة معرفية تربط الجديد بما يعرفه الطالب.","نمذجة السلوك الاجتماعي المرغوب أمام الطلاب":"نمذجة السلوك أداة المدخل الاجتماعي ليحاكيها الطلاب، أما عرض فكرة عامة تُبنى عليها التفاصيل فتنظيم للبنية المعرفية."}},"1q53c63":{"w":{"السلوكي":"المدخل السلوكي يعدّل السلوك الظاهر بخطوات صغيرة وتعزيز من المعلم، والمعلم هنا يشرك الطلاب في أهدافهم ويصغي لمشاعرهم.","المعرفي":"المدخل المعرفي يركز على التفكير والاكتشاف وبناء المعرفة، والقرائن هنا وجدانية: الإصغاء للمشاعر بتعاطف والتقويم الذاتي ودور الميسر.","الاجتماعي":"المدخل الاجتماعي يوظف التفاعل بين الطلاب ونمذجة السلوك، والمعلم هنا يركز على مشاعر كل طالب وأهدافه الشخصية وتقويمه لنفسه."}},"19is0iq":{"w":{"ألبرت باندورا":"باندورا صاحب نظرية التعلم الاجتماعي ونمذجة السلوك، أما التدريس غير الموجه بمعلم ميسّر متقبل فنموذج إنساني لروجرز.","بنجامين بلوم":"بلوم يرتبط بالتعلم للإتقان وتصنيف الأهداف، لا بالتدريس غير الموجه الذي يكون فيه المعلم ميسراً متقبلاً للمتعلم.","ديفيد أوزوبل":"أوزوبل صاحب التعلم ذي المعنى والمنظم المتقدم في المدخل المعرفي، لا التدريس غير الموجه في المدخل الإنساني."},"e":"روجرز رائد علم النفس الإنساني وصاحب التدريس غير الموجه."},"1v6djmz":{"w":{"السلوكي":"المدخل السلوكي يعتمد خطوات صغيرة وتعزيزاً فورياً للاستجابة، والقرينة هنا أداء المعلم للسلوك ومحاكاة الطلاب له في تفاعل جماعي.","المعرفي":"المدخل المعرفي يقوم على وصول الطالب إلى المعرفة بالتفكير والبحث، أما أداء المعلم سلوكاً يحاكيه الطلاب فنمذجة اجتماعية.","الإنساني":"المدخل الإنساني يعنى بالمشاعر والوعي بالذات والاستقلالية، والإجراء هنا نمذجة سلوك يحاكيه الطلاب ويتبادلون الملاحظات حوله."}},"owumpd":{"w":{"تقسيم الطلاب إلى مجموعات تنفذ التجربة في الوقت نفسه":"الأدوات نسخة واحدة فلا تكفي مجموعات متزامنة، والمادة قابلة للاشتعال فتنفيذ الطلاب لها يعرضهم للخطر.","المحاضرة مع وصف لفظي للتجربة دون أدوات":"الوصف اللفظي وحده لا يُري الطلاب خطوات التجربة، والأداة متوفرة بنسخة تكفي ليعرضها المعلم أمامهم مع الشرح.","تكليف الطلاب بتنفيذها في المنزل":"المادة قابلة للاشتعال فتنفيذها في المنزل يعرض الطلاب للخطر، والأدوات المتوفرة نسخة واحدة فقط."},"e":"العرض العملي يناسب التجارب الخطرة أو التي لا تتوفر أدواتها للجميع، ويجمع بين الأداء والشرح"},"1aejwno":{"w":{"توزيع ورقة الاختبار على الطلاب":"الاختبار يقيس التعلم بعد العرض والتطبيق، أما التهيئة قبل العرض فتجريبه مسبقاً وضمان رؤية الجميع له.","إخفاء هدف العرض لزيادة التشويق":"من خطوات العرض العملي أن يوضح المعلم هدفه للطلاب، فإخفاؤه يشتت انتباههم عما ينبغي ملاحظته.","تنفيذ الخطوات بسرعة لتوفير وقت الحصة للتطبيق الفردي":"العرض العملي يؤدَّى خطوة خطوة ببطء مع الشرح ليتابعه الطلاب، والسرعة تفوّت عليهم تفاصيل سيطبقونها بعده."}},"1p916v5":{"w":{"حفظه التعريف العلمي الصحيح":"حفظ التعريف لا يزيل التصور البديل لأنه مقاوم للتغيير، وأول شروط بوسنر أن يشعر الطالب بعدم الرضا عن تصوره.","إعادة المعلم شرح المفهوم عدة مرات":"التصور البديل يبدو للطالب منطقياً فيقاوم التغيير، وإعادة شرح الصواب دون إحداث عدم الرضا لا تغيره غالباً، فالشرط الأول عدم الرضا.","حصوله على درجة منخفضة في الاختبار":"الدرجة المنخفضة حكم خارجي لا يكشف للطالب قصور تصوره، وعدم الرضا المقصود ينشأ حين يعجز تصوره عن تفسير ما يلاحظه."}},"1od94fg":{"w":{"التعزيز الفوري للإجابة الصحيحة":"التعزيز الفوري أداة سلوكية لتثبيت الاستجابة، والإجراء هنا إسقاط كرتين بنتيجة تخالف توقع الطلاب فيولّد عدم الرضا.","التلقين المباشر للقانون العلمي":"التلقين يقدم القانون جاهزاً، وإعادة الصواب دون عدم رضا لا تغير التصور غالباً، والمعلم هنا جعل الملاحظة تخالف التوقع أولاً.","تقسيم المهارة إلى خطوات صغيرة":"تقسيم المهارة إلى خطوات صغيرة من أسس المدخل السلوكي، والموقف هنا تصحيح تصور بديل بحدث يخالف التوقع لا تعلم مهارة."}},"o1vb988g":{"w":{"المراقب بحيث يراقب الطلاب ويقوّم تقدّمهم.":"المراقب يكتفي برصد التقدم والحكم عليه، والمجموعات المتنقلة بين المراكز تحتاج من يدعمها ويوضح لها أثناء التعلم.","النموذج الذي يشرح للطلاب الطرق المناسبة لأداء مهامهم.":"الشرح للطلاب يعيد المعلم إلى مركز العملية، والتعلم في المراكز قائم على قراءة الطلاب واستماعهم ومشاهدتهم بأنفسهم.","المدرب الذي يحلل أداء الطلاب ويقترح طرقًا لتحسينه.":"تحليل الأداء واقتراح التحسين تركيز على التقويم والتصحيح، والتعلم هنا متمركز حول الطالب ويحتاج دعماً عند الحاجة أثناء النشاط."},"e":"في مراكز التعلم التعاونية يكون التعلم متمركزًا حول الطالب، ودور المعلم ميسّر يقدم الدعم عند الحاجة. (المعيار 7.2)"},"otni2px":{"w":{"سيربط الطلاب بين فروع المادة العلمية مما يعيق فهمهم للمفاهيم الواسعة.":"ربط فروع المادة يخدم فهم المفاهيم الواسعة عادة لا يعيقه، والقصة هنا تربط الحقائق بحياة شخصيات ملهمة لا بفروع المادة.","سيؤدي ذلك لاستخدام الطلاب لمخيلتهم وتنمية قدرتهم على تطبيق مهارات التفكير الإبداعي.":"الطلاب هنا يستمعون إلى قصة يرويها المعلم، والاستماع وحده لا يدرّبهم على تطبيق التفكير الإبداعي بالضرورة.","سيكون محتوى المادة أكثر سهولة للطلاب مما يزيد من استيعابهم لها.":"سهولة المحتوى ليست نتيجة مؤكدة للقصة، فأثرها الأرجح أنها تربط الحقائق بحياة الطلاب فيسهل تذكرها."},"e":"القصة تربط الحقائق التاريخية بحياة البشر وتجاربهم فتصبح ذات معنى وأسهل في التذكر. (المعيار 7.2)"},"ocvlawb":{"w":{"المراقب، الذي يراقب الطلاب ويقوّم تقدّمهم.":"المراقب يركز على الحكم على تقدم الطلاب، والمجموعات المتنقلة بين المراكز تحتاج أثناء النشاط من يدعمها ويوضح لها.","المحاضر، الذي يشرح للطلاب الطرق المناسبة لأداء مهامهم.":"المحاضر يعيد المعلم إلى مركز الدرس مصدراً للشرح، والطلاب هنا يتعلمون في المراكز بالقراءة والاستماع والمشاهدة بأنفسهم.","المقوّم، الذي يحلل أداء الطلاب ويقترح الطرق لتحسينه.":"المقوّم يركز على تحليل الأداء والحكم عليه واقتراح تحسينه، والمطلوب أثناء التنقل بين المراكز دعم المجموعات عند حاجتها."},"e":"في التعلم بمراكز المجموعات يكون المعلم ميسّرًا يتدخل بالدعم عند الحاجة فقط. (المعيار القديم 4.1، صعوبة 0.585)"},"o50nzn7":{"w":{"تطبيق المعرفة.":"تطبيق المعرفة غاية تخدمها طرق كثيرة كالاستنباط، أما الاستكشاف فيدرّب الطالب على كيف يصل إلى المعلومة بنفسه.","اكتساب خبرات التعلم.":"اكتساب الخبرات هدف عام تشترك فيه طرق التدريس كلها، والاستكشاف يتميز بتدريب الطالب على عملية الوصول إلى المعرفة.","الحصول على المعلومات.":"الحصول على المعلومات نتيجة لأي طريقة حتى المحاضرة، والاستكشاف غايته أن يتعلم الطالب كيف يصل إليها لا أن يتلقاها جاهزة."},"e":"التعلم بالاستكشاف غايته أن يتعلم الطالب «كيف» يصل إلى المعرفة بنفسه، لا أن يتلقاها جاهزة. (المعيار القديم 6.5، صعوبة 0.594)"},"oaupqur":{"w":{"سوف يقوم الطلاب بالربط بين فروع المادة العلمية التفصيلية مما يعيق فهمهم للمفاهيم (الصورة) الكبيرة.":"هذه نتيجة سلبية غير لازمة، فالقصة تربط الحقائق بحياة شخصيات مؤثرة وتمنحها معنى، ولا يلزم منها إعاقة فهم الصورة الكبيرة.","سيؤدي ذلك لاستخدام الطلاب لمخيلتهم وتنمية قدرتهم على تطبيق مهارات التفكير الإبداعي في تعلمهم.":"القصة هنا يرويها المعلم والطلاب يستمعون، والاستماع وحده لا يدرّبهم على تطبيق التفكير الإبداعي بالضرورة.","سوف يكون وقت الدرس أكثر إمتاعًا وسيصعب ربطه بمحتوى المادة من مفاهيم وحقائق.":"القصة قد تمتع الطلاب، لكنها تُبنى على حقائق المادة نفسها فتربطها بالحياة، فلا يلزم أن يصعب ربط الدرس بمفاهيمه."},"e":"القصة تجعل الحقائق ذات معنى ومرتبطة بالحياة فيسهل تذكرها. (المعيار القديم 4.2، صعوبة 0.622)"},"obwty6v":{"w":{"الانخراط بفاعلية في عملية بناء المعرفة العلمية.":"هذا وصف جوهر التعلم الاستكشافي، ونراه الأقرب علمياً، لكن مفتاح الدليل الرسمي (قياس 1436، السؤال 23) هو (أ)، فأبقينا المفتاح كما في الدليل.","وضع أهداف تعلّم واضحة ومراقبة التقدّم في تحقيقها.":"وضع أهداف واضحة ومراقبة التقدم نحوها إجراء عام في أي تخطيط للتدريس، ولا يختص به التعلم الاستكشافي.","الحصول على فكرة مختصرة عن مجال واسع من المحتوى لتسهيل التعلّم فيما بعد.":"تقديم فكرة عامة مختصرة عن مجال واسع تسهّل التعلم اللاحق وظيفة المنظم المتقدم لأوزوبل في التعلم الاستقبالي، لا الاستكشاف."},"e":"المفتاح الرسمي في دليل الاختبار العام للمعلمين (قياس 1436، السؤال 23) هو (أ): تعلّم محتوى جديد بمعدل تقدم قياسي من الأسهل إلى الأكثر تعقيداً، وأبقيناه لأنه نص الدليل. لكننا نرى أن (ب) أقرب علمياً: جوهر التعلم الاستكشافي أن يبني الطالب المعرفة بنفسه، أما التقدم بمعدل قياسي من السهل إلى الصعب فأقرب إلى التعليم المبرمج. ومعامل صعوبته في الدليل 0.287، أي أن نحو 29% فقط من عينة الدليل اختاروا (أ)."},"t2qvr5":{"w":{"يصف سلوك المعلم":"عيب وصف سلوك المعلم يظهر في صيغ مثل «يوضح المعلم»، أما هنا ففاعل القراءة هو الطالب نفسه.","يتضمن أكثر من ناتج":"تعدد النواتج يظهر حين يجمع الهدف فعلين مثل يقرأ ويلخص، وهذا الهدف فيه فعل واحد هو القراءة.","غير قابل للملاحظة":"عدم الملاحظة عيب أفعال مثل «يفهم»، أما القراءة فتُلاحظ، لكنها نشاط يؤدى لا ناتج يكتسبه الطالب."},"e":"الهدف السلوكي يصف الناتج الذي يكتسبه الطالب (كأن يستخرج الفكرة الرئيسة)، أما قراءة الدرس فنشاط يؤدى للوصول إلى الناتج."},"ypxwmj":{"w":{"معيار الأداء":"المعيار يحدد مستوى الإتقان المقبول، وهو هنا «في 10 دقائق»، أما الأطلس فأداة يُؤدى بها الرسم.","الفعل السلوكي":"الفعل السلوكي في هذا الهدف هو «يرسم»، أما عبارة الأطلس فتصف الأداة التي يُؤدى بها الفعل.","ناتج التعلم":"ناتج التعلم ما يكتسبه الطالب ويظهر في أدائه وهو رسم الخريطة، أما الأطلس فأداة من ظروف الأداء."},"e":"الشرط هو الظرف أو الأدوات التي يُؤدى فيها السلوك."},"ste4k6":{"w":{"هدفاً سلوكياً":"الهدف السلوكي يصف سلوكاً محدداً يُقاس في حصة واحدة، و«يكتسب مهارات» عبارة عامة تمتد على فصل دراسي كامل.","غاية تربوية":"الغاية بعيدة المدى وتعبر عن فلسفة المجتمع، وهذا الهدف محدد بمهارة القراءة الناقدة في فصل دراسي واحد.","هدف حصة واحدة":"هدف الحصة قريب المدى يتحقق في درس واحد، وعبارة «خلال الفصل الدراسي» تجعل هذا الهدف متوسط المدى لمقرر."},"e":"الهدف يمتد على فصل كامل ولا يقاس مباشرة في حصة، فهو هدف عام."},"12lrqw3":{"w":{"التذكر":"التذكر استرجاع المعلومة كما حُفظت، أما التلخيص بأسلوب الطالب الخاص فإعادة صياغة تدل على الفهم.","التحليل":"التحليل تفكيك المادة إلى أجزاء وبيان العلاقات بينها، والتلخيص هنا يعيد صياغة المعنى دون تفكيك علاقاته.","الإبداع":"الإبداع إنتاج عمل جديد كتصميم أو تأليف، والتلخيص يعيد معنى الفقرة نفسها بكلمات الطالب."},"e":"التلخيص وإعادة الصياغة بأسلوب خاص من أفعال الفهم."},"fovilu":{"w":{"التطبيق":"التطبيق أن يستخدم الطالب القاعدة ليحل المسألة بنفسه، والمطلوب هنا الحكم على حل زميله وتبريره بمعايير.","الفهم":"الفهم شرح خطوات الحل أو تفسيرها، والمطلوب هنا إصدار حكم على صحة الحل مع تبرير هذا الحكم.","التذكر":"التذكر استرجاع معلومة محفوظة كقانون أو تعريف، والطلب هنا حكم مبرر على صحة حل لا استرجاع."},"e":"إصدار الحكم المبرر وفق معايير هو التقويم."},"efu22i":{"w":{"بُعد الدافعية":"الدافعية ليست من أبعاد التصنيف المعدل، فبعداه العمليات المعرفية من التذكر إلى الإبداع وأنواع المعرفة الأربعة.","بُعد المهارات الحركية":"المهارات الحركية مجال مستقل هو النفس حركي وله تصنيفاته مثل سمبسون، لا بعد أضيف إلى تصنيف بلوم المعرفي.","بُعد القيم":"القيم موضوع المجال الوجداني المستقل، أما المعدل فأضاف إلى المجال المعرفي بعد أنواع المعرفة الأربعة."},"e":"التصنيف المعدل ثنائي الأبعاد: العمليات المعرفية (تذكر…إبداع) وأنواع المعرفة الأربعة."},"1iqbsr4":{"w":{"الحقائقية":"المعرفة الحقائقية مصطلحات وتفاصيل محددة كوحدة قياس الكثافة، والهدف هنا يصف خطوات إجراء التجربة وطريقتها.","المفاهيمية":"المعرفة المفاهيمية تصنيفات وعلاقات ونظريات كعلاقة الكتلة بالحجم، والهدف هنا يتناول كيف تُجرى التجربة خطوة خطوة.","ما وراء المعرفية":"ما وراء المعرفة وعي الطالب بتفكيره وطريقة تعلمه، والهدف هنا يصف خطوات تجربة لا تفكير الطالب في تعلمه."},"e":"الخطوات والطرائق معرفة إجرائية."},"1sw3y9r":{"w":{"الاستقبال":"الاستقبال انتباه للقيمة واهتمام بها دون فعل، والطالب هنا تجاوز الانتباه إلى مشاركة فعلية بالتطوع.","التنظيم":"التنظيم ترتيب القيم في منظومة متسقة وحل التعارض بينها، والسلوك هنا مشاركة فعلية في حملة لا بناء منظومة قيم.","التميز بالقيمة":"التميز بالقيمة أعلى المستويات حين تصير القيمة سمة ثابتة في سلوك الطالب، والسؤال يصف مشاركة عقب درس فقط."},"e":"الاستجابة هي المشاركة الفعلية والتطوع والتفاعل مع الموقف."},"1bd4ia3":{"w":{"التوجيهية":"التهيئة التوجيهية توجّه انتباه الطلاب نحو موضوع الدرس الجديد، والمعلم هنا يتحقق بالأسئلة من إتقانهم للجزء السابق.","الحافزة":"التهيئة الحافزة تثير اهتمام الطلاب بسؤال مشوق أو موقف غريب، وأسئلة المعلم هنا غرضها التأكد من إتقان السابق.","الانتقالية":"الانتقالية تربط السابق بالجديد وتسهّل الانتقال دون تحقق من الإتقان، والمعلم هنا سأل ليتأكد من إتقانهم."},"e":"نوع التهيئة يُعرف بغرضها: التقويمية غرضها التحقق من إتقان الطلاب لما سبق قبل البناء عليه، وهذا ما فعله المعلم بأسئلته. وكلمة «الانتقال» في السؤال فخ: التهيئة الانتقالية تسهّل الانتقال وتربط السابق بالجديد دون أن تختبر الإتقان، والتوجيهية توجّه الانتباه إلى موضوع الدرس، والحافزة تثير الاهتمام."},"t3viue":{"w":{"حقيقة":"الحقيقة معلومة جزئية محددة لا تعميم فيها، والعبارة هنا علاقة بين الضغط ودرجة الغليان تنطبق على حالات كثيرة.","مفهوماً":"المفهوم تصور مفرد يُعبر عنه بكلمة مثل الضغط الجوي، والعبارة هنا تربط بين مفهومين بعلاقة عامة.","قيمة":"القيمة معيار وجداني يوجه السلوك كالأمانة والنظافة، والعبارة هنا علاقة علمية بين الضغط ودرجة الغليان."},"e":"التعميم علاقة بين مفهومين أو أكثر تنطبق على حالات كثيرة."},"r58x6l":{"w":{"إلغاء الواجبات نهائياً":"الواجب المرتبط بالدرس أداة لمتابعة التعلم، وإلغاؤه لا يعالج سبب الشكوى وهو عدم فهم المطلوب.","مضاعفة الواجب ليتدربوا أكثر":"المضاعفة تزيد العبء ولا توضح المطلوب، والواجب الجيد مناسب الكم، والشكوى هنا من غموض المطلوب لا قلة التدريب.","تكليف أولياء الأمور بحله معهم":"نقل الحل إلى الأسرة يفقد الواجب غرضه في تدريب الطالب نفسه، ولا يعالج غموض المطلوب من المعلم."},"e":"التوجيهات الواضحة ونمذجة الحل من شروط الواجب الفعال."},"8ctalv":{"w":{"الأهداف السلوكية":"الأهداف السلوكية أساس الخطة اليومية، ومنها تُشتق الأنشطة والتقويم، فهي من عناصرها لا الاستثناء.","التقويم":"التقويم عنصر أساسي في خطة الدرس يجمع دليلاً على تحقق الأهداف، فهو من عناصرها لا الاستثناء.","الوسائل التعليمية":"الوسائل التعليمية تُحدد في الخطة اليومية لخدمة أهداف الدرس، فهي من عناصرها، والاستثناء توزيع المقرر طويل المدى."},"e":"توزيع المقرر على الأسابيع من التخطيط طويل المدى لا من الخطة اليومية."},"1iui5gq":{"w":{"التطبيق":"التطبيق استخدام القاعدة أو المعرفة في موقف جديد بأفعال مثل يحل ويستخدم، والأفعال هنا كلها إصدار أحكام.","الفهم":"الفهم تفسير المعنى وشرحه بأفعال مثل يلخص ويفسر، أما الحكم والنقد والتبرير فإصدار أحكام وفق معايير.","التذكر":"التذكر استرجاع المعلومات بأفعال مثل يذكر ويعدد، والأفعال هنا تتطلب حكماً مبرراً لا استرجاعاً."},"e":"إصدار الأحكام المبررة وفق معايير هو التقويم."},"1oh8pcv":{"w":{"التطبيق":"التطبيق استخدام قاعدة في حل مسألة، والفعل الرئيس هنا «يصمم» الذي ينتج نموذجاً جديداً يجمع عناصر متعددة.","التحليل":"التحليل تفكيك المادة إلى أجزائها وبيان علاقاتها، والفعل «يصمم» هنا بناء لنموذج جديد لا تفكيك.","الفهم":"الفهم شرح المفاهيم وتفسيرها كشرح الطاقة المتجددة، والهدف يتجاوز ذلك إلى تصميم نموذج جديد يوظفها."},"e":"التصميم إنتاج بناء جديد يجمع عناصر متعددة، وهو الإبداع في التصنيف المعدل."},"qx4izp":{"w":{"صياغة الأهداف التعليمية":"صياغة الأهداف الخطوة الثانية في نموذج آشور، وتأتي بعد تحليل خصائص المتعلمين وتُبنى على نتائجه.","اختيار الوسائط والمواد":"اختيار الطرق والوسائط الخطوة الثالثة في نموذج آشور، ويأتي بعد تحليل المتعلمين وصياغة الأهداف.","تقويم الدرس ومراجعته":"التقويم والمراجعة آخر خطوات نموذج آشور، تأتي بعد استخدام الوسائط وإشراك المتعلمين لا في بدايته."}},"1c1w96v":{"w":{"التخطيط الخطي من صفحات الكتاب":"التخطيط الخطي ينطلق من محتوى الكتاب صفحة بعد صفحة، والمعلم هنا انطلق من نواتج التعلم ثم أدلتها قبل الأنشطة.","تحليل المهمة":"تحليل المهمة تفكيك مهارة إلى خطوات فرعية متتابعة، والمعلم هنا يرتب التخطيط: النواتج ثم الأدلة ثم الأنشطة.","التعلم للإتقان":"التعلم للإتقان يمنح الطالب وقتاً وتصحيحاً حتى يتقن الوحدة قبل الانتقال، والسؤال يصف ترتيب خطوات التخطيط من النواتج إلى الأدلة ثم الأنشطة."}},"1meu2i5":{"w":{"صياغة الهدف بفعل غير قابل للقياس والملاحظة":"«يقارن» فعل قابل للملاحظة والقياس، فالخلل ليس في صياغة الهدف بل في أن سؤال التذكر لا يقيس المقارنة.","كثرة أدوات التقويم في الدرس":"التقويم هنا سؤال واحد هو «اذكر أنواع الصخور»، فالمشكلة في مستواه الأدنى من الهدف لا في كثرة أدواته.","ارتباط الهدف بمعايير المنهج":"ارتباط الهدف بمعايير المنهج مطلوب في التخطيط الجيد وليس مشكلة، والخلل هنا بين مستوى الهدف ومستوى سؤال التقويم."},"e":"المحاذاة تعني أن الهدف والنشاط والتقويم تقيس الشيء نفسه وبالمستوى نفسه؛ «يقارن» أعلى من «يذكر» فلا يقيسه سؤال تذكر."},"1x8gtve":{"w":{"عرضه لأنه يجذب انتباه الطلاب":"الجاذبية وحدها ليست معياراً للاختيار، والفيديو يخل بالدقة والحداثة لقدم معلوماته، وبشرط الخلو من المحتوى غير المناسب لإعلاناته.","عرضه دون تعليق على الأخطاء لتوفير الوقت":"العرض دون تعليق ينقل للطلاب معلومات علمية قديمة على أنها صحيحة، والدقة من شروط اختيار المصدر الأساسية.","تكليف الطلاب بمشاهدته في المنزل بدل الحصة":"نقل المشاهدة إلى المنزل لا يعالج قدم المعلومات ولا الإعلانات، بل يعرض الطلاب لها دون توجيه المعلم."},"e":"من شروط اختيار المصدر: الدقة العلمية والحداثة وموثوقية الناشر وخلوه من المحتوى غير المناسب"},"1yfaftl":{"w":{"حداثة الجهاز المستخدم في عرضه":"حداثة جهاز العرض لا تجعل المصدر مناسباً، فالمصدر وسيلة لا غاية، وأول شروط اختياره ارتباطه بأهداف الدرس.","ارتفاع تكلفته ودلالتها على جودته":"الأغلى ليس الأفضل بالضرورة، ومصادر البيئة المحلية قليلة التكلفة وفاعلة، فالتكلفة لا تدل على الجودة.","كثرة المؤثرات البصرية فيه":"كثرة المؤثرات قد تشتت الانتباه عن المحتوى، والشرط الأول أن يرتبط المصدر بهدف الدرس لا أن يبهر الطلاب."}},"n2387t":{"w":{"إلغاء استخدام أي مصدر رقمي في الدرس":"الإلغاء الكامل يحرم الدرس من مصدر مناسب، والمشكلتان هنا تُعالجان بنسخة مكبرة وبديل يعمل دون شبكة.","تنفيذ الدرس كما خُطط له تماماً، ثم حل المشكلات عند ظهورها أثناء الحصة":"التجريب قبل الحصة وإعداد البديل من شروط استخدام المصدر، والمعلم يعلم مسبقاً بضعف الشبكة فلا ينتظر ظهور المشكلة.","إعفاء الطالب ضعيف البصر من النشاط":"الإتاحة للجميع من شروط اختيار المصدر، والإعفاء يحرم الطالب من الهدف بدل تكييف المصدر له بنسخة مكبرة."}},"o1bwbsxw":{"w":{"الفهم.":"الفهم يصف المعنى ويفسره فقط، أما نقد الأفكار وتبريرها فإصدار حكم عليها وفق معايير، وهو التقويم.","التحليل.":"التحليل يفكك المعلومات ويوضح العلاقات بينها، أما النقد والتبرير فحكم على قيمة الأفكار وفق معايير.","التركيب.":"التركيب يجمع الأفكار في بناء جديد، والهدف هنا لا ينتج جديداً بل ينقد الأفكار ويبرر الحكم عليها."},"e":"النقد والتبرير وإصدار الأحكام هي جوهر مستوى التقويم. (المعيار 10.1)"},"olwsk5m":{"w":{"الاستقبال - الاستجابة - التقمص.":"هذه المستويات الدنيا للمجال الوجداني في دليل الهيئة، والسؤال يطلب المستويات العليا للمجال النفس حركي.","الملاحظة - التقليد - التجريب.":"هذه المستويات الدنيا للمجال النفس حركي، تبدأ بملاحظة المهارة وتقليدها، والسؤال يطلب مستوياته العليا.","التقدير - التنظيم - التجسيد.":"هذه المستويات العليا للمجال الوجداني الخاص بالقيم والاتجاهات، لا المستويات العليا للمجال النفس حركي."},"e":"الممارسة والإتقان والإبداع هي المستويات الثلاثة العليا في المجال النفس حركي. (المعيار 10.1)"},"o1yif32j":{"w":{"أن يعرف الطالب الوضوء تعريفًا كاملًا.":"التعريف هدف معرفي في مستوى التذكر، والهدف العام يطلب أداء العبادة أداءً صحيحاً، فالمشتق منه يكون أداءً.","أن يعدد الطالب أركان الوضوء وشروطه.":"تعداد الأركان والشروط استرجاع معرفي، ولا يدل على أن الطالب يؤدي الوضوء بصورة صحيحة كما يطلب الهدف العام.","أن يذكر الطالب شواهد من القرآن والسنة على فرض الوضوء.":"ذكر الشواهد هدف معرفي يدعم فهم الحكم، لكنه لا يدرب الطالب على أداء الوضوء الذي يطلبه الهدف العام."},"e":"الهدف العام مهاري (أداء العبادات)، فالهدف الخاص المشتق منه يجب أن يكون أداءً كذلك: «يؤدي». (المعيار القديم 5.1، صعوبة 0.762)"},"o1n7l0nj":{"w":{"التطبيق.":"التطبيق استخدام المعرفة في موقف جديد، و«عرّف» و«عدّد» تطلبان استرجاع المعلومة كما حُفظت فقط.","التحليل.":"التحليل تفكيك المعلومات وبيان العلاقات بينها، والسؤالان هنا يطلبان تعريفاً وتعداداً محفوظين دون تفكيك.","التركيب.":"التركيب جمع الأفكار في بناء جديد، أما التعريف وتعداد الفروض فاسترجاع لما حُفظ لا إنتاج جديد."},"e":"«عرّف» و«عدّد» أفعال استرجاع للمعلومات كما حُفظت، وهي مستوى التذكر في تصنيف بلوم. (المعيار القديم 5.1، صعوبة 0.622)"},"bbp7ke":{"w":{"الرؤوس المرقمة":"الرؤوس المرقمة ترقّم أعضاء كل مجموعة ثم يُختار رقم ليجيب عنها، ولا دائرة داخلية تناقش وخارجية تراقب كما في الموقف.","فكر‑زاوج‑شارك":"هذه الاستراتيجية تتدرج من تفكير فردي إلى نقاش ثنائي ثم مشاركة جماعية، لا دائرتين إحداهما تناقش والأخرى تلاحظ وتدوّن.","الأعواد":"الأعواد طريقة لسحب اسم طالب عشوائياً ليجيب، أما الموقف فيصف دائرة تناقش وأخرى تراقب ثم تتبادلان الأدوار."},"e":"حوض السمك: مشاركون في الداخل وملاحظون في الخارج."},"1g10ujd":{"w":{"تنال القمر":"تنال القمر استراتيجية للفهم القرائي، والمطلوب هنا كتابة إبداعية يُحدَّد فيها الدور والجمهور والصيغة والموضوع.","شبكة الأسئلة":"شبكة الأسئلة تجمع أسئلة الطلاب حول الموضوع وتنظمها، ولا تكلّف الطالب بكتابة نص يتقمص فيه دوراً لجمهور محدد.","التساؤل الذاتي":"التساؤل الذاتي يراقب به القارئ فهمه بأسئلة يوجهها لنفسه، وليس كتابة إبداعية تحدد الدور والجمهور والصيغة."},"e":"RAFT عناصرها: الدور، الجمهور، الصيغة، الموضوع."},"rndq77":{"w":{"التغير المفاهيمي":"التغير المفاهيمي لبوسنر يركز على معالجة التصورات البديلة، والأطوار الأربعة المذكورة هنا ليست أطواره بل أطوار التعليم التوليدي.","دورة التعلم الخماسية":"دورة التعلم الخماسية خمس مراحل تبدأ بالانشغال وتنتهي بالتقويم، والسؤال يذكر أربعة أطوار أولها التمهيدي وآخرها التطبيق.","التعلم للإتقان":"التعلم للإتقان لبلوم وكارول يشترط إتقان الوحدة قبل الانتقال، وليس نموذجاً بنائياً اجتماعياً بأطوار تمهيد وتركيز وتحدٍّ وتطبيق."},"e":"التعليم التوليدي (أوزبورن وويتروك) يولّد المعنى في سياق اجتماعي بأطوار أربعة."},"1dt9db4":{"w":{"العصف الذهني":"العصف الذهني توليد جماعي لأكبر عدد من الأفكار دون نقد، والطالب هنا يحاور نفسه فردياً ليراقب فهمه أثناء القراءة.","الكرسي الساخن":"الكرسي الساخن يجلس فيه طالب بدور شخصية ويجيب عن أسئلة زملائه، أما هنا فالطالب يوجه الأسئلة إلى نفسه.","لعب الأدوار":"لعب الأدوار تمثيل الطلاب لشخصيات أو مواقف، ولا تمثيل في الموقف، بل أسئلة يطرحها القارئ على نفسه لمراقبة فهمه."},"e":"التساؤل الذاتي مهارة ما وراء معرفية يراقب بها الطالب فهمه."},"1ewqdp":{"w":{"الوسائل التعليمية":"الوسائل التعليمية أجهزة ومواد فقط وهي جزء من تقنيات التعليم، والتعريف هنا يضم الإنسان والطرق أيضاً في منظومة واحدة.","الكتاب المدرسي":"الكتاب المدرسي وعاء يحمل المحتوى والأنشطة، وليس منظومة تجمع الإنسان والأجهزة والطرق والمواد معاً.","المنهج الخفي":"المنهج الخفي ما يتعلمه الطالب ضمناً دون تخطيط، ولا صلة له بتعريف منظومة الإنسان والأجهزة والطرق والمواد."},"e":"تقنيات التعليم منظومة أشمل من الوسائل (أجهزة ومواد فقط)."},"16qbz42":{"w":{"الويكي":"الويكي صفحات يحررها المشاركون جماعياً ويعدّلون نصها معاً، والموقف صفحة شخصية ينشر فيها المعلم وحده ويكتفي الطلاب بالتعليق.","قاعدة البيانات":"قاعدة البيانات تنظم السجلات وتخزنها للبحث والاسترجاع، ولا تُستعمل لنشر تأملات شخصية يعلّق عليها الطلاب.","الحوسبة السحابية":"الحوسبة السحابية تخزين وموارد عبر الإنترنت تناسب تحرير الملفات معاً، لا صفحة نشر شخصية مفتوحة لتعليقات الطلاب."},"e":"المدونة للنشر الشخصي والتعليق."},"j0vq2x":{"w":{"البودكاست":"البودكاست ملفات صوتية مسجلة يستمع إليها المتعلم، فلا تمزج الحاسوب بالفيديو ولا تتفرع بحسب استجابته.","الويكي":"الويكي صفحات يحررها المشاركون جماعياً، فهي أداة كتابة تشاركية لا وسيلة فيديو يتحكم فيها المتعلم ويتفرع.","المدونة":"المدونة صفحة ينشر فيها صاحبها ويعلّق القراء، وليست وسيلة فيديو تتفرع بحسب استجابة المتعلم في تعلمه الفردي."},"e":"الفيديو التفاعلي يسمح بالتحكم والتفرع وفق استجابة المتعلم."},"4lbb2k":{"w":{"إكسل":"برنامج الجداول الحسابية يناسب الدرجات والعمليات الحسابية، لكنه ليس نظاماً لإدارة قواعد بيانات علائقية تربط جداول متعددة.","كانفا":"أداة تصميم للصور والمطويات والعروض، ولا تنشئ قاعدة بيانات تربط سجلات الطلاب بأولياء أمورهم ودرجاتهم.","كاهوت":"أداة مسابقات وألعاب تفاعلية للتقويم داخل الصف، لا برنامج لإدارة قواعد بيانات علائقية تربط السجلات ببعضها."},"e":"أكسس نظام إدارة قواعد بيانات."},"q9svo9":{"w":{"TPACK":"نموذج ميشرا وكوهلر يصف معارف المعلم في التقنية والتربية والمحتوى، وليس معايير دولية موجهة للطلاب والمعلمين والقادة.","SAMR":"نموذج بونتيدورا يقيس عمق أثر التقنية في المهمة من الاستبدال إلى إعادة التعريف، وليس معايير دولية للفئات الثلاث.","ADDIE":"نموذج للتصميم التعليمي يبدأ بالتحليل وينتهي بالتقويم، ولا يحدد معايير لتوظيف التقنية عند الطلاب والمعلمين والقادة."},"e":"معايير ISTE تصدرها الجمعية الدولية للتقنية في التعليم."},"1mfdin7":{"w":{"مرادف للكتاب تماماً":"المقرر قائمة موضوعات المادة لصف معين، والكتاب وعاء مادي يحملها مع الوسائل والأنشطة، فبينهما فرق لا ترادف.","أشمل من المنهج":"المنهج بمفهومه الحديث جميع الخبرات المخططة داخل المدرسة وخارجها، فهو أعم من المقرر، والمقرر جزء منه.","يقتصر على الأنشطة اللاصفية":"المقرر موضوعات دراسية محددة لمادة في صف معين، والأنشطة اللاصفية جزء من المنهج الواسع لا تعريف للمقرر."},"e":"المقرر قائمة الموضوعات، والكتاب الوعاء المادي للمحتوى والأنشطة."},"gs16a7":{"w":{"الرأسي (تدرج المحتوى عبر الصفوف)":"البعد الرأسي هو التتابع الذي يصف تدرج المحتوى عبر الصفوف، أما المدى فيصف اتساعه داخل الصف الواحد.","الزمني للحصة":"مصفوفة المدى والتتابع بعداها اتساع المحتوى أفقياً وتدرجه رأسياً عبر الصفوف، وزمن الحصة ليس أحدهما.","الوجداني للأهداف":"الوجداني مجال من مجالات الأهداف يخص الميول والاتجاهات والقيم، ولا علاقة له بالمدى الذي يصف اتساع المحتوى في الصف الواحد."},"e":"المدى اتساع أفقي في المستوى الواحد."},"gw3d75":{"w":{"فكر‑زاوج‑شارك":"هذه الاستراتيجية تبدأ بتفكير فردي ثم ثنائي ثم جماعي، أما النموذج هنا فيبدأ باكتشاف ثنائي وينتهي بتقويم ذاتي فردي.","التعلم للإتقان":"التعلم للإتقان يقسم المحتوى إلى وحدات لا ينتقل الطالب منها قبل إتقانها، ولا يمر بتمهيد واكتشاف ثنائي وأنشطة تعاونية.","التعليم المبرمج":"التعليم المبرمج فردي يسير فيه الطالب بخطوات صغيرة متتابعة بتغذية راجعة فورية، والنموذج هنا يقوم على اكتشاف ثنائي وأنشطة تعاونية."},"e":"نموذج التعلم البنائي الاجتماعي يبدأ ثنائياً وينتهي فردياً."},"k1x3je":{"w":{"الانشغال":"الانشغال أول مراحل الدورة لإثارة الاهتمام وكشف المعرفة السابقة، والطلاب هنا فهموا المفهوم وصاروا يطبقونه في موقف جديد.","الاستكشاف":"الاستكشاف تجريب يسبق الشرح ليصل الطلاب إلى المفهوم، أما هنا فالكثافة مفهومة سلفاً والمطلوب تطبيقها على طفو السفن.","التفسير":"مرحلة التفسير يُقدَّم فيها المفهوم ومصطلحاته أول مرة، والكثافة هنا مفهومة سلفاً، وطلب تفسير طفو السفن تطبيق لها في موقف جديد."},"e":"التوسع تطبيق المفهوم في موقف جديد يعمق الفهم."},"49p2sb":{"w":{"المنتج":"تمايز المنتج ينوّع طريقة إظهار الطلاب لما تعلموه، والمعلم هنا نوّع أنشطة الوصول إلى المفهوم لا ما يسلّمه الطلاب في النهاية.","المحتوى":"تمايز المحتوى يغيّر ما يُقدَّم للطالب نفسه، والمفهوم هنا واحد للمجموعات الثلاث وتغيّر فقط النشاط الذي يتعلمون به.","التقويم":"التمايز في التقويم يكون بتنويع أدوات قياس التعلم، والموقف لا يذكر تقويماً بل أنشطة مختلفة للوصول إلى المفهوم نفسه."},"e":"تنويع الأنشطة للوصول إلى المفهوم نفسه هو تمايز العملية."},"mrcqwp":{"w":{"توفير وقت الحصة":"ترتيب طرح السؤال قبل تسمية المجيب لا يختصر وقتاً، وغرضه أن يفكر كل الطلاب لاحتمال أن يُختار أي منهم.","ضمان إجابة الطالب المتفوق":"الغرض أن يستعد جميع الطلاب للإجابة، وحصر الإجابة في المتفوق يُخرج بقية الصف من التفكير، وهو عكس المقصود.","تجنب إحراج الطالب الضعيف":"تقديم السؤال على تسمية المجيب لا يخص الطالب الضعيف وحده، بل يجعل الصف كله يفكر لأن أي طالب قد يُختار."},"e":"اختيار المجيب قبل السؤال يجعل بقية الطلاب يتوقفون عن التفكير."},"p0q1fe":{"w":{"زمن التعلم ثابت ومعيار التحصيل متغير":"تثبيت الزمن مع تفاوت التحصيل وصف للتدريس التقليدي، والإتقان يعكسه فيمنح كل طالب وقته ليبلغ المعيار نفسه.","التقويم فيها ختامي فقط":"التقويم في التعلم للإتقان تكويني مستمر يكشف من لم يتقن الوحدة فيُعالَج قبل الانتقال، لا ختامي فقط.","الطلاب فيها متجانسون":"التعلم للإتقان يفترض تفاوت الطلاب في الزمن الذي يحتاجونه، فيمنح كلاً منهم وقته بدل افتراض تجانسهم."},"e":"في الإتقان يُمنح كل طالب الوقت الذي يحتاجه لبلوغ المعيار نفسه، عكس التقليدي الذي يثبت الزمن فتتفاوت النتائج."},"84zuol":{"w":{"نص مكتوب مطول على الشاشة":"النص المكتوب مع الرسم يزاحمه في القناة البصرية، ومبدأ الصيغة يفضّل الكلام المنطوق ليتوزع الحمل على السمع والبصر.","نص مكتوب وصوت يقرأه حرفياً معاً":"إضافة النص المكتوب نفسه إلى الصوت مع الرسم تخالف مبدأ التكرار الزائد عند ماير، فالأفضل الصوت مع الرسم وحدهما.","لا شيء؛ الرسم وحده كافٍ":"مبدأ الصيغة يقوم على إقران الرسم بكلام منطوق يشرحه، وترك الرسم بلا شرح يفقد الطالب الكلمات التي توضح خطوات العملية."},"e":"الصوت المنطوق مع الرسوم يوزع الحمل على القناتين السمعية والبصرية."},"rslben":{"w":{"المنهج الخفي":"المنهج الخفي ما يتعلمه الطلاب ضمناً دون تخطيط، والموضوع هنا لم يتعلموه أصلاً لأن اللجنة حذفته عمداً.","المنهج الرسمي":"المنهج الرسمي هو المكتوب المعتمد الذي يُدرَّس فعلاً، والموضوع هنا استُبعد منه فلم يُدرَّس.","منهج النشاط":"منهج النشاط تنظيم عند ديوي يقوم على ميول الطلاب وحل المشكلات، ولا صلة له بحذف موضوع من الكتاب."},"e":"المنهج الفارغ (ويسمى أيضاً الصفري) عند آيزنر ما لا يُدرَّس للطالب، حُذف عمداً كما هنا أو أُغفل، فيتعلم الطالب بغيابه."},"ptjdak":{"w":{"المنهج الخفي":"المنهج الخفي غير مكتوب ويُتعلم ضمناً من سلوك المعلمين وبيئة المدرسة، والسؤال يصف وثيقة مكتوبة معتمدة من الوزارة.","المنهج الفارغ":"المنهج الفارغ ما لا يُدرَّس عمداً أو سهواً فهو غائب عن الوثيقة، والسؤال عن الوثيقة نفسها بأهدافها ومحتواها وتقويمها.","المنهج المُختبَر":"المنهج المختبَر ما يعيشه الطالب فعلاً داخل الفصل، لا الوثيقة المكتوبة التي تعتمدها الوزارة قبل التدريس."},"e":"المنهج الرسمي هو المخطط المكتوب المعتمد."},"vw1ts8":{"w":{"منهج النشاط":"منهج النشاط ينطلق كله من ميول الطلاب وحل مشكلاتهم، ولا يقوم على جزء مشترك إلزامي يليه اختيار مواد تخصصية.","المواد المنفصلة":"المواد المنفصلة تُدرَّس فيها كل مادة مستقلة عن غيرها، بلا محور مشترك من الخبرات العامة يجمع الطلاب.","المنهج الحلزوني":"المنهج الحلزوني عند برونر يعيد المفاهيم بعمق متزايد عبر السنوات، ولا يقسم الدراسة إلى محور مشترك ومواد اختيارية."},"e":"المنهج المحوري يجمع بين جزء مشترك إلزامي وجزء اختياري."},"1d1rbrs":{"w":{"التجهيزات التقنية المتاحة في المدرسة فقط":"التجهيزات المتاحة عامل مساعد في التنفيذ، لكن المؤشر يجعل الأساس حاجات المتعلمين وخصائصهم وطبيعة الأهداف، لا التجهيزات وحدها.","الاستراتيجيات التي يفضلها شخصياً":"تفضيل المعلم الشخصي يجعل الاختيار يدور حوله لا حول طلابه، والمؤشر يربطه بحاجات المتعلمين وطبيعة الأهداف.","ما يطلبه أولياء الأمور":"مطالب أولياء الأمور عامل ثانوي، والمؤشر ينص على اختيار الاستراتيجيات وفق حاجات المتعلمين وخصائصهم وطبيعة أهداف التعلم."},"e":"المؤشر ينص على استراتيجيات تلبي حاجات المتعلمين وخصائصهم وتراعي طبيعة الأهداف."},"1yj7z4":{"w":{"اكتساب المعرفة وتكاملها":"اكتساب المعرفة وتكاملها بُعد يبني فيه الطالب المعرفة الجديدة ويربطها بالسابقة، والطلاب هنا تعلموا الصخور سلفاً وصاروا يقارنونها ويصنفونها.","الاستخدام ذو المعنى للمعرفة":"الاستخدام ذو المعنى يكون بحل مشكلة أو اتخاذ قرار أو بحث، أما المقارنة والتصنيف فمن عمليات تعميق المعرفة وصقلها.","عادات العقل المنتجة":"عادات العقل المنتجة نزعات عامة كالتفكير الناقد والتنظيم الذاتي، لا عمليات مقارنة وتصنيف على محتوى بعينه."},"e":"أبعاد التعلم عند مارزانو خمسة: الاتجاهات والإدراكات الإيجابية نحو التعلم، واكتساب المعرفة وتكاملها، وتعميق المعرفة وصقلها، والاستخدام ذو المعنى للمعرفة، وعادات العقل المنتجة. والمقارنة والتصنيف والتجريد من عمليات بُعد التعميق والصقل."},"27ho0d":{"w":{"جدول التعلم (أعرف، أريد، تعلمت)":"جدول التعلم لأوجل ينشط المعرفة السابقة بأعمدته الثلاثة، ولا يتضمن تحويل العناوين إلى أسئلة ثم التسميع والمراجعة.","التدريس التبادلي":"التدريس التبادلي حوار جماعي يتناوب فيه الطلاب قيادة التنبؤ والتساؤل والتوضيح والتلخيص، لا خطوات مسح ثم تسميع ومراجعة.","فكر، زاوج، شارك":"هذه الاستراتيجية نقاش يبدأ فردياً ثم ثنائياً ثم جماعياً، وخطوات الموقف خطة قراءة: مسح وسؤال وقراءة وتسميع ومراجعة."},"e":"استراتيجية روبنسون خمس خطوات: المسح، والسؤال، والقراءة، والتسميع، والمراجعة، ويرمز لها بالحروف الأولى من أسمائها بالإنجليزية."},"6cuywp":{"w":{"الاكتشاف الموجه":"الاكتشاف الموجه يصل فيه الطالب إلى مفهوم أو قاعدة بتوجيه المعلم، والمشروع هنا تصميم حل وتجريبه وتحسينه بدمج عدة مجالات.","المنهج المحوري":"المنهج المحوري تنظيم للمنهج كله بجزء مشترك وآخر اختياري، لا مشروع واحد يدمج العلوم والهندسة والرياضيات.","التعلم بالأقران":"التعلم بالأقران يقوم على تعليم الطلاب بعضهم بعضاً، والموقف يصف تصميماً هندسياً وحساباً رياضياً وتجريباً علمياً في مشروع واحد."},"e":"مدخل ستيم يدمج العلوم والتقنية والهندسة والرياضيات في مشروع تطبيقي يصمم فيه الطلاب حلاً ويجربونه ويحسنونه، وهو ما في الموقف: تصميم هندسي وحساب رياضي وتجريب علمي."},"1s6e6k5":{"w":{"الشمول يعزل ذوي الاحتياجات في فصول خاصة، والدمج يضعهم مع أقرانهم في الفصل العادي":"الشمول لا يعزل أحداً، بل يعلّم الجميع معاً في الفصل العام ويغيّر النظام ليستوعب تنوعهم، والعزل في فصول خاصة نقيضه.","الشمول يقتصر على الموهوبين والمتفوقين، والدمج يقتصر على الطلاب ذوي الإعاقة":"الشمول يستوعب تنوع جميع الطلاب لا الموهوبين وحدهم، والفرق الحاسم بينهما من يتكيف: النظام في الشمول، والطالب في الدمج.","لا فرق بينهما في المفهوم ولا في الممارسة":"بينهما فرق جوهري: الدمج يطلب من الطالب أن يتكيف مع النظام القائم، والشمول يغيّر النظام نفسه ليناسب الجميع."}},"10mghsq":{"w":{"التعليم المبرمج الخطي":"التعليم المبرمج الخطي يسير فيه كل الطلاب في تسلسل واحد من خطوات صغيرة، ولا ينوّع طرق العرض والتعبير والتحفيز.","نموذج التدريس المباشر الصريح":"التدريس المباشر يشرح فيه المعلم وينمذج ثم يوجه التدريب خطوة خطوة، والموقف يصف تخطيطاً مسبقاً لوسائل متعددة للتمثيل والتعبير والتحفيز.","استراتيجية التعلم للإتقان":"التعلم للإتقان يمنح الطالب وقتاً إضافياً حتى يبلغ نسبة الإتقان، لا وسائل متعددة للعرض والتعبير والتحفيز يُخطط لها منذ البداية."}},"u9dz7f":{"w":{"تقوى الله والوسطية والاعتدال والشغف المعرفي وتقدير الذات":"هذه من القيم الست في المؤشر لا من الأولويات، والأولويات ثلاث: المواطنة المسؤولة ومكانة المملكة الريادية والتنمية المستدامة.","حل المشكلات والاعتماد على الذات والتواصل والعمل الجماعي":"هذه مهارات تُنمّى بالمهام كحل المشكلات والاعتماد على الذات، وليست الأولويات الثلاث: المواطنة المسؤولة وريادة المملكة والتنمية المستدامة.","القراءة والكتابة والحساب والمهارات الرقمية":"هذه مهارات أساسية للتعلم عامة لا يذكرها المؤشر أولويات، فأولوياته المواطنة المسؤولة ومكانة المملكة الريادية والتنمية المستدامة."},"e":"مؤشر 8.4 الأول: خبرات تستهدف تنمية الأولويات المتصلة بالمواطنة المسؤولة ومكانة المملكة الريادية والتنمية المستدامة."},"1sxgmme":{"w":{"الشغف المعرفي":"الشغف المعرفي من القيم الست لا من الأولويات ويعني حب الاستطلاع، أما ترشيد الكهرباء فحفاظ على الموارد للأجيال القادمة.","تقدير الذات":"تقدير الذات قيمة تتصل بثقة الطالب بنفسه وليست أولوية، والمهمة هنا ترشيد استهلاك الطاقة حفاظاً على الموارد.","مكانة المملكة الريادية":"مكانة المملكة الريادية أولوية تُنمّى بإبراز منجزات الوطن ودوره، أما تحليل الفاتورة وترشيد الاستهلاك فصورة مباشرة للتنمية المستدامة."}},"1ap36y5":{"w":{"الصدق، الأمانة، التعاون، النظافة، الطاعة، الكرم":"قيم أخلاقية عامة مهمة لكن المؤشر لم يسمّها، والقيم الست فيه تبدأ بتقوى الله والوسطية والاعتدال وتقدير الذات.","المواطنة، الريادة، الاستدامة، الإبداع، الابتكار، التميز":"المواطنة والريادة والاستدامة هي الأولويات الثلاث لا القيم، والإبداع والابتكار والتميز أضيفت إليها وليست من نص المؤشر.","حل المشكلات، الاعتماد على الذات، التواصل الفعال، القيادة، التفكير الناقد، العمل ضمن فريق":"هذه مهارات تُنمّى بالمهام والأنشطة كحل المشكلات والاعتماد على الذات، لا القيم الست التي نص عليها المؤشر."}},"redn15":{"w":{"تقوى الله":"تقوى الله قيمة تتصل بمراقبة الله في القول والعمل، والموقف يصف إثارة الفضول والبحث عن المعرفة خارج الكتاب.","الوسطية والاعتدال":"الوسطية والاعتدال قيمة تعني التوازن ونبذ الغلو في الفكر والسلوك، ولا صلة مباشرة لها بإثارة الفضول والبحث.","تقدير العمل وإتقانه":"تقدير العمل وإتقانه يظهر في تجويد المنتج ومراجعته، أما هنا فالمعلم يثير الفضول ويشجع البحث، وهذا شغف معرفي."}},"1yxqvc5":{"w":{"الشغف المعرفي":"الشغف المعرفي حب الاستطلاع والرغبة في المعرفة، والمعلمة هنا لا تثير فضولاً بل تطلب تجويد المشروع مرحلة بعد مرحلة.","الوسطية والاعتدال":"الوسطية والاعتدال توازن ونبذ للغلو في الفكر والسلوك، والموقف يدور حول مراجعة العمل وتجويده حتى يبلغ أفضل صورة.","تقدير الذات":"تقدير الذات ثقة الطالبة بنفسها وقيمتها، أما المراجعة المرحلية والتجويد قبل التسليم فتنصبّ على جودة العمل نفسه."}},"11p29bh":{"w":{"تقديم المعلم الحل كاملاً ثم مطالبة الطالب بنسخه":"تقديم الحل جاهزاً ثم نسخه يجعل الطالب متلقياً، والاعتماد على الذات ينمو حين يخطط الطالب وينفذ ويقوّم بنفسه.","حل الطالب التمارين بمساعدة ولي أمره في كل خطوة من خطوات الحل":"المساعدة في كل خطوة تبقي الطالب معتمداً على غيره، والمطلوب دعم يتلاشى تدريجياً حتى يتولى المهمة بنفسه.","انتظار الطالب تعليمات المعلم قبل كل خطوة":"انتظار التعليمات قبل كل خطوة اعتماد على المعلم، وهو نقيض المهارة المطلوبة التي يخطط فيها الطالب لمهمته وينفذها بنفسه."}},"i6zstu":{"w":{"الحفظ والاستظهار":"الحفظ والاستظهار تذكر للمعلومات، والموقف يمر بخطوات تحديد المشكلة وجمع معلوماتها واقتراح الحلول وتجريب أفضلها.","القراءة الجهرية":"القراءة الجهرية مهارة لغوية في أداء النص بصوت مسموع، ولا صلة لها بتحديد مشكلة واقعية واقتراح حلول وتجريبها.","الإصغاء بتفهم":"الإصغاء بتفهم مهارة تواصل في الاستماع للآخرين، والمعلم هنا يدرّب على خطوات منظمة لعلاج مشكلة واقعية في المدرسة."}},"o17lor3h":{"w":{"الرحلات الميدانية.":"الرحلات الميدانية زيارات تعليمية خارج الصف إلى مواقع حقيقية، والموقف بحث جماعي عبر الإنترنت في مصادر أعدها المعلم.","التعلم المبرمج.":"التعلم المبرمج فردي ذاتي يسير فيه الطالب بخطوات صغيرة، والسؤال يصف بحثاً جماعياً عبر الإنترنت في مصادر موثوقة.","التعلم المدمج.":"التعلم المدمج نمط يجمع التعليم الحضوري والإلكتروني، ولا يحدد بحثاً جماعياً في مصادر أعدها المعلم مسبقاً."},"e":"الرحلات المعرفية (الويب كويست) تقوم على بحث جماعي عبر الإنترنت في مصادر اختارها المعلم مسبقًا. (المعيار 8.3)"},"ob6hopc":{"w":{"استخدام وسائل التواصل التقني.":"وسائل التواصل التقني أداة لنقل المعلومات لا عملية عقلية، والاستقصاء يقوم على عمليات أساسها الملاحظة والتصنيف والقياس والتنبؤ.","تقويم جودة الحلول التي يتوصل لها.":"تقويم جودة الحلول مستوى لاحق يأتي بعد البحث وجمع البيانات، ودعم الاستقصاء يبدأ بالتدريب على الملاحظة وتنظيم البيانات.","سرعة إنجاز المهام بنسبة مقبولة من الأخطاء.":"سرعة الإنجاز مع قبول بعض الأخطاء ترتبط بممارسة معرفة سابقة، والاستقصاء يولّد معرفة جديدة بالملاحظة وتنظيم البيانات."},"e":"الاستقصاء يولّد المعرفة بالبحث وطرح الأسئلة عبر عمليات عقلية أساسها الملاحظة والتصنيف والقياس والتنبؤ. (المعيار 9.4)"},"o1i0c2fc":{"w":{"أن يكون للسؤال إجابة واحدة صحيحة.":"السؤال ذو الإجابة الواحدة سؤال مغلق يناسب قياس التذكر، واستثارة التفكير تحتاج سؤالاً مفتوحاً يقبل إجابات متعددة.","أن يطرح السؤال بلغة صحيحة وسليمة.":"سلامة لغة السؤال شرط عام في صياغة أي سؤال، ولا تجعله وحدها مستثيراً للتفكير، فذلك يتحقق بانفتاح السؤال.","الأسئلة المباشرة التي تبحث عن حقائق محددة.":"الأسئلة المباشرة عن حقائق محددة ترتبط بمستوى الحفظ والتذكر، ولا تستثير التفكير كما تفعل الأسئلة المفتوحة."},"e":"الأسئلة المفتوحة تتعلق بمستويات التفكير العليا فتستثير التفكير. (المعيار 8.3)"},"oxr12w7":{"w":{"منح المعلمين مرونة أكبر في تحضير الدروس والأنشطة.":"مرونة التحضير تعود على المعلم لا على تعلم الطالب، وميزة التنويع أنه يراعي ميول الطلاب فيقل نفورهم من المادة.","إعطاء الطلاب فرصة لتعميم المعرفة الجديدة وتطبيقها.":"تعميم المعرفة وتطبيقها ميزة للممارسة والتطبيق نفسه لا للتنويع بحد ذاته، وميزة التنويع المباشرة تقليل الملل والنفور من المادة.","تقليل شعور المعلمين بالضغط الناتج عن كثرة الموضوعات.":"تخفيف ضغط كثرة الموضوعات عن المعلم يتعلق براحته لا بتعلم الطالب، وميزة التنويع أنه يراعي ميول الطلاب فيقل نفورهم."},"e":"التنويع في الإستراتيجيات يراعي أنماط الطلاب وميولهم فيقل الملل والنفور من المادة، وهذه ميزة تعود على المتعلم. (المعيار 8.3)"},"od82tts":{"w":{"تقويم فاعلية الأساليب الأدبية في القصص الخيالية التي يدرسونها.":"نقد الأساليب الأدبية مهارة تحليل للنص الأدبي، والتدريب هنا على أساليب قراءة تختلف باختلاف الغرض كالاطلاع والبحث والفكرة الرئيسة.","استخدام إستراتيجيات التقويم الذاتي لتحسين مستويات القراءة.":"التقويم الذاتي يراجع به الطالب أداءه ويحسنه، والمعلم هنا لم يدرّب على مراجعة الأداء بل على اختيار أسلوب القراءة بحسب الغرض.","تحليل صحة الحجج ودقة الجمل المساندة في الكتابة المقنعة لهم.":"تحليل الحجج والجمل المساندة مهارة في نقد الكتابة المقنعة، ولم يرد في التدريب الذي ربط كل أسلوب قراءة بغرض مختلف."},"e":"كل أسلوب قراءة ذُكر مرتبط بغرض مختلف (اطلاع، بحث، فكرة رئيسة)، فالمهارة المكتسبة هي اختيار طريقة القراءة بحسب الغرض. (المعيار 8.3)"},"o1mdaqpf":{"w":{"عدد الروابط الموجودة على الموقع وسرعة تحديثها.":"كثرة الروابط وسرعة التحديث مظهر نشاط للموقع ولا تثبت دقة معلوماته، فالدقة تُحكم بمعرفة معدّه وإمكانية التحقق منه.","وضوح المعلومات المعروضة في الموقع.":"وضوح العرض يسهّل الفهم لكنه لا يثبت صحة المعلومة، فقد تُعرض معلومة خاطئة بوضوح تام.","تقديم المعلومات بطريقة جديّة ومنظمة.":"الجدية والتنظيم في العرض مظهر شكلي، ولا يدل على الدقة إلا معرفة جهة الإعداد وإمكانية التحقق منها."},"e":"مصداقية المصدر الرقمي تُحكم بمعرفة جهة الإعداد وإمكانية التحقق منها. (المعيار 9.3)"},"o1tr1x9z":{"w":{"تسهيل استخدام الطلاب لمهارات التفكير التحليلي.":"التفكير التحليلي تفكيك المعلومات وفحص علاقاتها، والمناقشة القبلية هنا تحدد ما يريد الطلاب معرفته قبل القراءة ولا تدرب على التحليل.","زيادة استخدام الطلاب لاستراتيجيات مراقبة الذات.":"مراقبة الذات متابعة القارئ لفهمه أثناء القراءة، والمناقشة هنا تسبق القراءة لتضع غرضاً لها وتنشط ما يعرفه الطلاب.","تقديم مصطلحات غير معروفة لمحتوى المادة وربطها بالمفاهيم المعروفة.":"تقديم المصطلحات الجديدة يكون بعرضها وربطها بالمعروف، والمناقشة هنا انطلقت مما يعرفه الطلاب ويسألون عنه لا من مصطلحات قدمها المعلم."},"e":"المناقشة القبلية وقائمة الأسئلة توجه القراءة نحو غرض محدد وتنشط المعرفة السابقة (التهيئة). (المعيار القديم 4.2)"},"op3223j":{"w":{"يوضح للطلاب الغرض من استخدام البرنامج لإثارة اهتمامهم.":"توضيح الغرض للطلاب خطوة لاحقة عند التطبيق، وتفترض أن البرنامج مناسب لهم قبل التحقق من ذلك مع الزملاء.","يجرب مميزات البرنامج المتعددة للتأكّد من أنها تعمل كما يجب.":"تجربة المميزات تتأكد أن البرنامج يعمل تقنياً، لكنها لا تحكم وحدها على مناسبته للطلاب والنشاط كما تفعل مراجعته مع زملاء.","يعيد كتابة وثيقة الدعم الفني لضمان فهم الطلاب لها بسهولة.":"إعادة كتابة وثيقة الدعم الفني جهد لا يلزم قبل الاستخدام الأول، وتفترض أن البرنامج مناسب قبل التحقق من ملاءمته للطلاب."},"e":"مراجعة البرنامج مع زملاء تحكم على مناسبته للطلاب والنشاط بقرار جماعي قبل التطبيق. (المعيار القديم 4.3)"},"ox32c4c":{"w":{"أن يكون السؤال عن المعارف وله إجابة واحدة صحيحة.":"السؤال المعرفي ذو الإجابة الواحدة يقيس التذكر، وأسئلة التحليل والتقويم تحتاج صياغة مفتوحة تستثير التفكير وتقبل الرأي.","أن يراعي المعلم مستوى انتباه الطلاب في الفصل وإزعاجهم.":"ضبط الانتباه والإزعاج مطلوب في كل المواقف الصفية، فليس هو المبدأ الخاص بصياغة أسئلة التحليل والتقويم.","أن يتوقع المعلم ردود فعل الطلاب ويحكم عليهم قبل أن يجيبوا على السؤال.":"الحكم المسبق على ردود الطلاب يقيّد المعلم ويغلق باب الإجابات غير المتوقعة، وهي ما تنتظره أسئلة التحليل والتقويم."},"e":"أسئلة التحليل والتقويم تستثير التفكير وتفتح باب الرأي والإجابات غير المتوقعة. (المعيار القديم 6.3)"},"o1vvva68":{"w":{"طلب المشاركة بين أعضاء المجموعة في المواد لإكمال المهمة.":"مشاركة المواد مطلب بدهي لإكمال المهمة، لكنه لا يضمن أن يسهم كل عضو فعلياً كما يضمنه تقويم الزملاء لدوره.","إلزام كل مجموعة بتسليم منتج واحد فقط.":"المنتج الواحد للمجموعة قد يُنجزه بعض الأعضاء ويتكل الباقون، فلا يحقق المساءلة الفردية التي يحققها تقويم كل عضو لزملائه.","عمل مهام معقدة تتطلب من الأعضاء الاعتماد على بعضهم في الحصول على المعلومات.":"تعقيد المهام قد ينفّر الطلاب، والاعتماد على الآخرين في المعلومات لا يضمن وحده أن يسهم كل عضو، بخلاف تقويم الزملاء لدوره."},"e":"تقويم الأقران داخل المجموعة يحقق المساءلة الفردية فيشارك كل طالب فعليًا لأن زملاءه سيقوّمون دوره. (المعيار القديم 9.2)"},"oc7gh2e":{"w":{"توجيه مجموعة من الأسئلة للطلاب.":"الأسئلة أداة لتقويم الفهم وكشف من لم يستوعب، لكنها لا تقدم له طريقة تعلم تناسبه كما يفعل التنويع.","البدء بعرض المفاهيم الرئيسة للموضوع.":"عرض المفاهيم الرئيسة في البداية يخص ترتيب الدرس، ويبقى طريقة واحدة لا تراعي اختلاف أنماط الطلاب وقدراتهم.","إعادة شرح الدرس في الحصة عدة مرات.":"إعادة الشرح بالطريقة نفسها لا تفيد من لم يفهم أول مرة، والاستيعاب الشامل يحتاج طرقاً متنوعة تناسب اختلاف الطلاب."},"e":"لا يستوعب «جميع» الطلاب إلا إذا تنوعت الطرق لتناسب اختلاف أنماطهم وقدراتهم. (المعيار القديم 4.2، صعوبة 0.629)"},"o62yb1":{"w":{"الجمع بين الترفيه والتعليم.":"الجمع بين المتعة والتعلم من مميزات الحاسب المعروفة كالألعاب التعليمية والوسائط المتعددة، فلا يكون هو المستثنى.","مراعاة السرعة الذاتية للتعلم.":"يتيح الحاسب لكل طالب أن يتقدم بسرعته الخاصة ويعيد ما يحتاجه، وهذه ميزة معروفة له، فلا تكون هي المستثناة.","اعتماد الطالب على نفسه في التعليم.":"التعلم بالحاسب فردي في الغالب فينمي اعتماد الطالب على نفسه، وهذه ميزة له، أما ضعف التفاعل الاجتماعي فمن مآخذه."},"e":"التعلم بالحاسب فردي في الغالب، فمن مآخذه لا مميزاته ضعف التفاعل الاجتماعي. انتبه لصيغة النفي «لا يُعد». (المعيار القديم 4.3، صعوبة 0.546)"},"1d2ajxa":{"w":{"الإغراق":"الإغراق يعرّض الفرد لمثيره المخيف دفعة واحدة وبشدة حتى يزول خوفه، والمعلم هنا يدرّب الطالب على التعبير عن رأيه وطلب حقوقه.","الكف المتبادل":"الكف المتبادل إحلال استجابة مضادة كالاسترخاء محل القلق المرتبط بمثير معين، أما تدريب الطالب على التعبير عن رأيه وطلب حقوقه بثقة فهو التدريب التوكيدي.","الإشباع":"الإشباع السماح بالسلوك أو تقديم المثير بكثرة حتى يفقد قيمته فيقل، والمعلم هنا يريد أن يزيد تعبير الطالب عن رأيه لا أن يقلل سلوكاً."},"e":"السلوك التوكيدي يبني ثقة الطالب بنفسه في التعبير."},"vj2nwt":{"w":{"الانطفاء":"الانطفاء حجب التعزيز بالتجاهل المقصود حتى يتلاشى السلوك، والمعلم هنا لم يتجاهل الطالب بل أتاح له الحديث طويلاً حتى ملّ.","الإقصاء":"الإقصاء إبعاد مؤقت للطالب عن النشاط المعزز، والمعلم هنا لم يبعده بل أعطاه فرصة أطول للحديث.","التصحيح الزائد":"التصحيح الزائد يكلف الطالب بإصلاح أثر خطئه وزيادة عليه، والمعلم هنا لم يطلب منه إصلاح شيء بل أطال له الحديث حتى ملّ."},"e":"الإشباع تقديم المثير أو السماح بالسلوك بكثرة حتى يفقد قيمته."},"1m6g5ao":{"w":{"الإقصاء":"الإقصاء إجراء خارجي يبعد فيه المعلم الطالب مؤقتاً عن نشاط معزز، والطالب هنا يقيّد نفسه بنفسه دون تدخل من أحد.","العقاب السالب":"العقاب السالب سحب معزز يملكه الفرد بعد سلوك غير مرغوب ليقل، والطالب هنا يمنع نفسه عن الحلويات بإرادته لا بإجراء خارجي.","الانطفاء":"الانطفاء إجراء خارجي يتجاهل فيه المعلم سلوكاً قائماً حتى يتلاشى بغياب تعزيزه، والطالب هنا يقيّد نفسه بنفسه رغم رغبته."},"e":"ضبط الذات مجاهدة النفس وتقييدها ذاتياً."},"1w9bwpz":{"w":{"ضعف القناة":"ضعف القناة خلل في وسيلة نقل الرسالة كخفوت الصوت أو رداءة العرض، والطلاب هنا يسمعون المعلم لكن أذهانهم شاردة.","غياب المرسل":"المرسل حاضر هنا وهو المعلم الذي يشرح ويسمعه طلابه، فالخلل ليس في وجوده بل في انتباه المستقبل.","انعدام التغذية الراجعة":"التغذية الراجعة رد المستقبل على الرسالة بعد استقبالها، والخلل هنا يقع قبل ذلك في انتباه الطلاب وهم يسمعون فلا يستوعبون."},"e":"شرود الذهن معوق يخص المستقبل."},"1tfzkkj":{"w":{"داخلي متغير قابل للضبط (الجهد)":"عزو الفشل إلى الجهد يعني أن الطالب يرى نتيجته تتحسن إذا اجتهد، وهو هنا يقول إنه لن ينجح مهما فعل.","خارجي متغير (الحظ)":"الحظ سبب خارجي يتغير من مرة إلى أخرى، والطالب هنا ينسب فشله إلى نفسه بقوله «أنا غبي» لا إلى سوء حظه.","خارجي ثابت (صعوبة المادة)":"صعوبة المادة سبب خارجي يخص المهمة نفسها، والطالب هنا يصف قدرته هو بقوله «أنا غبي» فالسبب عنده داخلي."},"e":"الغباء سبب داخلي يراه الطالب ثابتاً وخارج سيطرته، وهذا أخطر أنواع العزو لأنه يقود إلى العجز المتعلم."},"1dv9x6o":{"w":{"ذكائه الفطري":"العزو إلى الذكاء الفطري يربط النجاح بقدرة ثابتة، فيخاف الطالب من المهام الصعبة التي قد تكشف عكس ذلك.","سهولة الاختبار":"سهولة الاختبار سبب خارجي يقلل قيمة نجاح الطالب أمام زملائه، ولا يعلّمه أن نتيجته ثمرة ما بذله هو.","حظه في الأسئلة":"الحظ سبب خارجي متغير لا يتحكم فيه الطالب، فالثناء به يوحي بأن نجاحه صدفة ولا يدفعه إلى المثابرة."},"e":"عزو النجاح للجهد يرسخ أن النتيجة تحت سيطرة الطالب فيثابر."},"1a8hvud":{"w":{"أهداف بعيدة المدى عامة الصياغة":"الأهداف البعيدة العامة لا تتيح للطالب أن يقيس تقدمه، فلا يشعر بنجاحات قريبة ترفع دافعيته كما تفعل الأهداف القصيرة الواضحة.","أهداف سهلة جداً يضمن تحقيقها دون جهد":"الأهداف السهلة جداً بلا تحدٍّ فتُملّ الطالب، ونجاحه فيها دون جهد لا يمنحه شعوراً حقيقياً بالإنجاز.","أهداف يحددها المعلم دون إطلاع الطالب عليها":"الهدف المخفي عن الطالب لا يوجّه جهده ولا يريه تقدمه، والدافعية ترتفع بأهداف واضحة يعرفها ويسعى إليها."},"e":"الأهداف القصيرة الواضحة تمنح نجاحات متتابعة محسوسة، والتحدي المناسب يحفظ الاهتمام."},"14a891e":{"w":{"الطلاب يقلدون سلوك المعلم بالملاحظة":"تقليد السلوك بالملاحظة هو النمذجة عند باندورا، أما أثر بجماليون فيخص توقعات المعلم التي تغيّر معاملته للطالب فيتحقق ما توقعه.","الدافعية تزداد بزيادة المكافآت":"ربط الدافعية بالمكافآت فكرة التعزيز الخارجي، وأثر بجماليون يتعلق بتوقعات المعلم عن قدرة الطالب لا بكمية المكافآت.","التعلم يحدث بتعزيز التقريبات المتتابعة":"تعزيز التقريبات المتتابعة هو التشكيل في تعديل السلوك، وأثر بجماليون عن توقعات المعلم التي تتحقق لأنه يعامل الطالب وفقها."},"e":"بجماليون (روزنثال وجاكوبسون): من توقع المعلم تفوقه تفوق فعلاً."},"gy2jto":{"w":{"الإقناع اللفظي من المعلم":"الإقناع اللفظي من مصادر الكفاءة الذاتية عند باندورا، لكنه أضعف من خبرة الإتقان لأن الكلام لا يعادل نجاحاً جربه الطالب بنفسه.","ملاحظة نجاح الأقران":"ملاحظة نجاح الأقران خبرة بديلة من مصادر الكفاءة الذاتية، لكن أثرها أضعف من نجاح الطالب نفسه في مهمة سابقة.","الحالة الانفعالية والجسمية":"الحالة الانفعالية والجسمية كالقلق أو الارتياح من مصادر الكفاءة الذاتية عند باندورا، لكن أثرها أقل من خبرات الإتقان الشخصية."},"e":"النجاح الفعلي في مهمة سابقة أقوى دليل للطالب على قدرته."},"1wu1lsa":{"w":{"توزيع الأسئلة التي تتطلب تفكيراً على جميع الطلاب":"توزيع أسئلة التفكير على الجميع يعكس إيمان المعلم بقدرة كل طلابه، فهو من مؤشرات التوقعات العالية وليس الاستثناء.","انتظار إجابة الطالب المتردد وتشجيعه":"منح المتردد وقتاً كافياً للإجابة مع تشجيعه رسالة بأنه قادر عليها، فهو من مؤشرات التوقعات العالية وليس الاستثناء.","الإصرار على إكمال المهمة مع تقديم الدعم":"الإصرار على الإكمال مع الدعم هو التحدي المصحوب بالمساندة، وهذا جوهر التوقع العالي، فليس هو الاستثناء."}},"xumbju":{"w":{"يعفيه من المشاركة حتى يتحسن مستواه":"الإعفاء من المشاركة يحرمه من فرص النجاح التي تبني ثقته، ويحمل رسالة ضمنية بأنه غير قادر.","يذكره دائماً بضرورة بذل الجهد":"التذكير بالجهد كلام لا يمنحه نجاحاً محسوساً، والثقة تُبنى بخبرة إتقان حقيقية في مهمة يستطيع أداءها.","يعلن درجاته أمام الصف ليتحفز":"إعلان درجات طالب متدني التحصيل أمام الصف يحرجه ويقارنه بزملائه، فيهبط تقديره لذاته بدل أن يرتفع."},"e":"إشراكه في مجموعة ناجحة بدور في متناوله يمنحه خبرة إتقان وانتماء."},"1dignz6":{"w":{"فوضوي":"النمط الفوضوي تضيع فيه الضوابط ويُترك الطلاب بلا توجيه، والمعلم هنا يفرض الطاعة التامة ويخشاه طلابه.","ديمقراطي":"النمط الديمقراطي يشرك الطلاب في القرار ويقوم على الاحترام المتبادل، والمعلم هنا يحتكر المعرفة ويعتمد على الخوف والطاعة.","تشاركي":"التشاركية تعني إشراك الطلاب في القرار والتعلم، وهذا يناقض معلماً يرى نفسه المصدر الوحيد للمعلومات ويطلب الطاعة التامة."}},"w7z4fc":{"w":{"زيادة النقد والإبداع لديهم":"النقد والإبداع يحتاجان حرية في التعبير، والتسلط يقوم على الخوف والطاعة التامة فيكبتهما، وزيادتهما أثر إيجابي لا سلبي.","قوة الانضباط الذاتي":"الانضباط في النمط التسلطي مرتبط برهبة المعلم فيضعف بغيابه، وهذا عكس الانضباط الذاتي الذي ينبع من الطالب نفسه.","ارتفاع تقدير الذات":"ارتفاع تقدير الذات أثر إيجابي لا سلبي، والتسلط القائم على الخوف يُضعف ثقة الطالب بنفسه فيزيد اعتماده على المعلم."}},"166fifz":{"w":{"اليقظة":"اليقظة وعي المعلم بكل ما يجري في الصف، أما ما فعلته المعلمة هنا فمعالجة الهمس دون قطع المساعدة، وهذا فعل متزامن اسمه التداخل.","تنبيه المجموعة":"تنبيه المجموعة إبقاء الصف كله منتبهاً ومستعداً للمشاركة، كطرح السؤال قبل اختيار المجيب، والمعلمة هنا تعالج موقفين في وقت واحد.","السلاسة":"السلاسة انتقال المعلم بين الأنشطة دون توقف أو قفز مفاجئ، والسؤال يصف إدارة موقفين متزامنين لا الانتقال بين نشاطين."},"e":"التداخل overlapping عند كونين هو القدرة على إدارة موقفين متزامنين."},"1nznasc":{"w":{"الفوضى تنتقل من طالب إلى آخر بالتقليد":"هذا وصف لانتقال السلوك بين الطلاب بالتقليد، أما أثر الموجة عند كونين فمصدره المعلم: طريقة معالجته لطالب واحد يتأثر بها الباقون.","تكرار القاعدة يثبتها لدى الطلاب":"تثبيت القاعدة بتكرارها يخص بناء القواعد الصفية، وأثر الموجة يخص امتداد أثر معالجة المعلم لطالب واحد إلى بقية الصف.","العقوبات تتدرج في الشدة":"تدرج العواقب من مبادئ الانضباط الحازم عند كانتر، وأثر الموجة يصف تأثر الصف كله بطريقة معالجة المعلم لسلوك طالب واحد."}},"1izi9m7":{"w":{"متجانسة في المستوى يختارها الطلاب بأنفسهم":"تجانس المستوى يحرم المجموعة من معاونة أفرادها لبعضهم، وهي الهدف الأول للتعلم التعاوني، فالأفضل مجموعات غير متجانسة بأدوار محددة.","كبيرة العدد لتقليل عدد المجموعات":"المجموعة الكبيرة يختفي فيها بعض الأعضاء ولا يجد كل منهم دوراً، والعدد المناسب للمجموعة التعاونية من 4 إلى 6 أعضاء.","متغيرة الأعضاء كل عشر دقائق":"تغيير الأعضاء كل عشر دقائق يقطع العمل في المهمة المشتركة قبل أن تستقر الأدوار ويتعاون الأعضاء على إنجازها."},"e":"عدم التجانس يحقق معاونة الأفراد لبعضهم (الهدف الأول للتعاوني) والأدوار تضمن المسؤولية الفردية."},"zh6xth":{"w":{"حل المجموعة وتكليف كل طالب بالعمل فردياً":"حل المجموعة تخلٍّ عن استراتيجية التعلم التعاوني، والمشكلة هنا غياب المسؤولية الفردية داخلها لا العمل الجماعي نفسه.","مكافأة الطالب النشط أمام المجموعة":"مكافأة الطالب النشط تعزز انفراده بالعمل، ولا تجعل المتفرجين مسؤولين عن أي جزء من المهمة.","تقليل حجم المهمة المطلوبة":"تقليل المهمة لا يوزع العمل على الأعضاء، فيبقى طالب واحد ينجزها والباقون يتفرجون كما هم."},"e":"المسؤولية الفردية والاعتماد المتبادل شرطا التعلم التعاوني، وتتحققان بالأدوار ومحاسبة كل عضو."},"1fz0n5r":{"w":{"ملقّن يشرح المهمة من مكانه":"التلقين من المكان يجعل الطلاب متلقين، ودور المعلم أثناء عمل المجموعات أن يتنقل بينها ويتابعها ويوجهها بالأسئلة.","مراقب صامت لا يتدخل حتى النهاية":"الصمت حتى النهاية انسحاب يترك المجموعات المتعثرة بلا توجيه، والمعلم الميسّر يتدخل بالسؤال والدعم عند الحاجة.","مصحح يتابع الدفاتر في مكتبه":"الانشغال بالتصحيح في المكتب ابتعاد عن المجموعات أثناء عملها، فلا يتابع تقدمها ولا يدعمها عند الحاجة."}},"1c3s8mj":{"w":{"توبيخه أمام زملائه":"التوبيخ العلني يحرجه أمام زملائه ولا يعالج سبب حديثه، وهو فراغ وقته بعد إنهاء الواجب مبكراً، فالأولى مهمة تشغله.","تكليفه بإعادة حل الواجب":"إعادة الواجب الذي أنجزه عقاب على الإنجاز نفسه، وتكرار عمل منتهٍ لا يضيف له تعلماً جديداً.","تجاهله حتى ينتهي الوقت":"التجاهل يترك وقته فارغاً فيستمر حديثه مع زميله ويشوش على الصف، والأولى استثمار هذا الوقت بنشاط إثرائي."},"e":"الطالب الذي ينهي عمله مبكراً يحتاج مهمة لا عقوبة؛ النشاط الإثرائي يستثمر وقته ويمنع التشويش."},"1b4vb90":{"w":{"تمديد الشرح على حساب النشاط":"تمديد الشرح يأكل وقت النشاط الذي يتعلم فيه الطلاب بالممارسة، فهو هدر للوقت الأكاديمي لا إدارة له.","تأجيل التهيئة إلى آخر الحصة":"التهيئة تكون في بداية الحصة لتجذب الانتباه وتربط الجديد بالسابق، وتأجيلها إلى آخرها يفقدها وظيفتها.","الاستطراد لإبعاد الملل":"الاستطراد خروج عن موضوع الدرس يستهلك الوقت المخصص للتعلم، والملل يُعالج بتنويع الأنشطة لا بالابتعاد عن الموضوع."},"e":"الروتين الثابت يوفر الوقت الضائع في البدايات والنهايات."},"xoqtgt":{"w":{"عقاب سالب":"العقاب السالب سحب معزز يملكه الطالب كنقاط أو امتياز، والمعلم هنا أضاف مثيراً منفّراً هو التوبيخ فقلّ السلوك.","تعزيز سالب":"التعزيز السالب إزالة مثير منفّر ليزيد السلوك، والمعلم هنا أضاف التوبيخ فقلّت المقاطعات، والإضافة مع النقص عقاب موجب.","تكلفة استجابة":"تكلفة الاستجابة خصم نقاط أو امتياز بعد السلوك فهي عقاب سالب، والمعلم هنا لم يخصم شيئاً بل أضاف توبيخاً."}},"php3yu":{"w":{"التصحيح الزائد":"التصحيح الزائد إصلاح الضرر مع عمل إضافي كتنظيف بقية الفصل، والمعلمة هنا طلبت تنظيف مكان العصير فقط.","تكلفة الاستجابة":"تكلفة الاستجابة خصم نقاط أو امتياز بعد السلوك، والمعلمة هنا لم تخصم شيئاً بل طلبت إزالة أثر ما سكبه.","الإقصاء":"الإقصاء إبعاد مؤقت عن النشاط المعزز، والطالب هنا لم يُبعد عن شيء بل كُلف بإصلاح الضرر الذي أحدثه."},"e":"إزالة الضرر بقدر الخطأ دون أعمال إضافية هو التصحيح البسيط."},"tefs9o":{"w":{"متقطعاً من البداية":"التعزيز المتقطع يناسب المحافظة على سلوك اكتُسب، أما السلوك الجديد فيحتاج تعزيزاً متواصلاً في كل مرة حتى يُبنى.","مؤجلاً حتى يثبت السلوك":"التعزيز الفعال فوري يتبع الاستجابة مباشرة، وتأجيله يضعف ارتباطه بالسلوك الجديد فلا يعرف الطالب ما الذي استحق عليه التعزيز.","رمزياً فقط":"المعززات الرمزية نوع واحد من المعززات، والسؤال عن توقيت التعزيز وتكراره لاكتساب سلوك جديد، والتعزيز الفعال متنوع لا يقتصر على نوع."}},"1xfchgz":{"w":{"تكلفة الاستجابة":"تكلفة الاستجابة خصم نقاط أو امتياز بعد السلوك غير المرغوب، وهي عقاب سالب يقلل السلوك فعلاً، فليست الاستثناء.","الإقصاء":"الإقصاء إبعاد مؤقت عن النشاط المعزز، وهو عقاب سالب يقلل السلوك غير المرغوب فعلاً، فليس هو الاستثناء.","الانطفاء":"الانطفاء حجب التعزيز عن السلوك بالتجاهل المقصود فيتلاشى تدريجياً، فهو يقلل السلوك غير المرغوب وليس الاستثناء."},"e":"التعزيز السالب يزيد السلوك المرغوب بإزالة منفّر."},"wsphuw":{"w":{"تعزيز موجب":"التعزيز الموجب إضافة مثير محبب كالثناء أو الجائزة، والمعلم هنا لم يضف شيئاً بل أزال الواجب الذي يراه الطالب منفّراً.","عقاب سالب":"العقاب السالب سحب شيء محبب ليقل السلوك، والمعلم هنا أزال الواجب المنفّر ليزيد المشاركة لا ليقللها.","انطفاء":"الانطفاء حجب التعزيز عن سلوك ليتلاشى، والمعلم هنا كافأ المشاركة بالإعفاء من الواجب ليزيدها لا ليطفئها."}},"10vxac":{"w":{"تكلفة الاستجابة":"تكلفة الاستجابة خصم نقاط أو امتياز مؤقت، وهي أسلوب تعديل سلوك مقبول بضوابط لا يمس جسد الطالب ولا كرامته.","العقد السلوكي":"العقد السلوكي اتفاق مكتوب بين المعلم والطالب على سلوك محدد ومعززه، وهو أسلوب تعديل مقبول لا إيذاء فيه ولا تشهير.","التصحيح الزائد":"التصحيح الزائد يكلف الطالب بإصلاح أثر خطئه وزيادة عليه، وهو أسلوب تعديل مقبول بضوابط لا يتضمن إيذاء ولا تشهيراً."},"e":"العقاب البدني والتشهير ممنوعان: قواعد السلوك والمواظبة 1447 تمنع الإيذاء الجسدي أو النفسي والسخرية من الطالب، وتوجب سرية معلومات المخالف."},"ko7q4y":{"w":{"عقاب سالب":"العقاب السالب سحب معزز يملكه الطالب، والمعلم هنا لم يسحب منه شيئاً بل قلّما يناديه فغاب التعزيز عن رفع يده.","تعزيز سالب":"التعزيز السالب إزالة مثير منفّر فيزيد السلوك، والسلوك هنا قلّ ولم يُزل عن الطالب أي منفّر.","تعميم":"التعميم انتقال الاستجابة إلى مثيرات مشابهة للمثير الأصلي، والسؤال يصف سلوكاً قلّ تدريجياً لأنه لم يعد يُعزز."},"e":"السلوك الذي لا يُعزز يتلاشى، وهذا الانطفاء."},"4im8dw":{"w":{"يقدم المعزز نفسه بعد كل استجابة":"تكرار المعزز نفسه بعد كل استجابة هو ما يسبب الإشباع، فيفقد المعزز قيمته عند الطالب ويضعف أثره.","يزيد كمية المعزز باستمرار":"زيادة كمية المعزز تعجّل الإشباع بدل أن تمنعه، والتعزيز الفعال يتناسب مع حجم الاستجابة ولا يتضخم باستمرار.","يوقف التعزيز نهائياً":"إيقاف التعزيز نهائياً يؤدي إلى انطفاء السلوك المرغوب نفسه، والمطلوب حفظ قيمة المعزز بالتنويع لا إلغاؤه."}},"1uqo3fm":{"w":{"إبلاغ ولي أمره بالحادثة في اليوم نفسه":"إبلاغ ولي الأمر خطوة لاحقة تتولاها إدارة المدرسة بعد أن يرصد المعلم المشكلة، والخطوة الأولى إيقاف السب في لحظته.","إحالته إلى المرشد الطلابي":"الإحالة إلى الموجه الطلابي خطوة لاحقة بعد رصد المشكلة وتسليمها للإدارة، والموقف الحاضر يحتاج أولاً إيقاف الإساءة فوراً.","تجاهل الموقف لأنه الأول":"التجاهل المقصود يصلح لسلوك يطلب الانتباه كالمقاطعة، أما السب فإساءة إلى زميل لا تُترك ولو كانت أول مرة."},"e":"الخطوة الأولى المباشرة إيقاف الإساءة وإشعار المعتدي بأن سلوكه مرفوض وستتبعه إجراءات."},"1izcgzd":{"w":{"مواجهته مع المتنمر أمام الصف لتسوية الخلاف":"المواجهة العلنية تزيد أذى طالب صامت منعزل، والمعتدى عليه يُحمى وتُبنى ثقته لا يُواجه بالمتنمر أمام الصف.","مطالبته بالدفاع عن نفسه بالمثل":"الرد بالمثل يوسع العنف ويحمّل الضحية مسؤولية حماية نفسها، والتنمر يُعالج بخطة مدرسية مع الموجه والإدارة والأسرة.","تجاهل الأمر لأنه سيتجاوزه مع الوقت":"التجاهل يترك الطالب بلا حماية فيستمر التنمر وتتعمق عزلته وصمته، والمعتدى عليه يحتاج حماية ودعماً يبني ثقته."},"e":"المعتدى عليه يحتاج حماية وثقة ومهارات."},"1ljrdfi":{"w":{"زيادة المشاركة الصفية":"زيادة المشاركة علامة اندماج وارتياح، والطالب المتنمَّر عليه يميل إلى الانسحاب والصمت وتجنب الظهور أمام زملائه.","ارتفاع تقدير الذات":"التنمر يهز ثقة الضحية بنفسها فينخفض تقديرها لذاتها، فارتفاعه عكس ما يظهر على الطالب المتنمَّر عليه.","المبادرة إلى قيادة المجموعات":"المبادرة إلى القيادة تدل على ثقة بالنفس، والطالب الذي يتعرض للتنمر ينسحب ويتجنب المواقف الاجتماعية لا يتصدرها."}},"b2en59":{"w":{"تسجيل مخالفة في سجل السلوك":"التسجيل إجراء إداري لاحق، والخطر قائم ما دامت المواد في يد الطالب، فيُوقف أولاً وتُبعد المواد قبل أي تسجيل.","إبلاغ ولي الأمر بالحادثة":"إبلاغ ولي الأمر خطوة لاحقة لا تحمي أحداً في اللحظة نفسها، والسلامة تبدأ بإيقاف الخطر وإبعاد المواد الكيميائية فوراً.","إخراجه من المختبر بقية الفصل الدراسي":"الحرمان من المختبر فصلاً كاملاً عقوبة طويلة غير متناسبة، والموقف يحتاج أولاً إيقاف العبث وإبعاد المواد ثم التذكير بقواعد السلامة."},"e":"الخطر الفوري يُوقف أولاً قبل أي إجراء إداري."},"1pyfffd":{"w":{"العقوبة الفورية القصوى لأي مخالفة":"القواعد تصنف المخالفات في درجات وتتدرج إجراءاتها من التنبيه الشفهي فما بعده، فلا تبدأ بأقصى عقوبة لأي مخالفة.","إشراك الطلاب في معاقبة زملائهم":"معالجة المخالفات مسؤولية المعلم والإدارة، وإشراك الطلاب في معاقبة زملائهم يحرج المخالف علناً ويخالف سرية معلوماته.","حرمان المخالف من الدراسة":"القواعد تتدرج في الإجراءات لتعديل السلوك وتمنع حتى إقصاء الطالب خارج الصف، فالحرمان من الدراسة ليس من مبادئها."}},"169ezef":{"w":{"رفع صوت المعلم فوق أصواتهم":"رفع صوت المعلم يرفع ضوضاء الصف بدل أن يخفضها، والإشارة الصامتة المتفق عليها تضبط الصوت دون صراخ.","معاقبة الصف كله بواجب إضافي":"العقاب الجماعي ممنوع لأنه يعاقب الملتزم مع المخالف، والمشكلة هنا تُعالج بإجراء صفي متفق عليه لا بعقوبة.","إيقاف العمل بالمجموعات نهائياً":"إيقاف المجموعات نهائياً تخلٍّ عن استراتيجية مفيدة، والمشكلة هنا في ضبط الصوت أثناء انشغال المعلم لا في العمل الجماعي نفسه."},"e":"الإشارة المتفق عليها إجراء صفي يضبط الصوت دون قطع النشاط أو عقاب جماعي."},"y90rb1":{"w":{"تطبيق العواقب المتفق عليها بثبات":"الثبات في تطبيق العواقب المعلنة يجعل الطالب يربط سلوكه بنتيجته، فهو إجراء مناسب عند التكرار وليس الاستثناء.","إشراك المرشد الطلابي في دراسة الحالة":"تكرار المخالفة يستدعي التصعيد إلى الموجه الطلابي لدراسة أسبابها، فهو إجراء مناسب وفق سلّم التصعيد وليس الاستثناء.","التواصل مع ولي الأمر":"إشراك ولي الأمر عند تكرار المخالفة جزء من سلّم التصعيد المنظم، فهو إجراء مناسب وليس الاستثناء."},"e":"التشهير إهانة علنية ممنوعة وتولد العناد."},"hs9zxz":{"w":{"مستويات إنجاز الطلاب":"الترتيب حسب مستوى الإنجاز يوسم الطلاب ويضر بالبيئة الآمنة، والمقاعد تُرتب أصلاً وفق النشاط: صفوف للعرض ومجموعات للتعاون.","الخلفيات الاجتماعية والثقافية للطلاب":"توزيع الطلاب حسب خلفياتهم الاجتماعية يعزلهم ويوسمهم، والسؤال عن ترتيب الأماكن والأدوات، وهذا يحدده نوع النشاط المخطط له.","أطوال الطلاب فقط":"الطول تفصيل ثانوي يساعد على الرؤية، والاكتفاء به يتجاهل الأساس، وهو أن شكل الترتيب يتبع النشاط: صفوف للعرض ومجموعات للتعاون."},"e":"التنظيم الفيزيائي يتبع النشاط: صفوف للعرض ومجموعات للتعاون."},"r7mkv":{"w":{"يكثر من التهديد بالعقوبات":"كثرة التهديد تبني الانضباط على الخوف كما في النمط التسلطي، أما القدوة فتجعل الطلاب يقلدون السلوك ويقبلون القواعد عن اقتناع.","يعتمد على العقاب الجماعي":"العقاب الجماعي ممنوع لأنه يعاقب غير المخطئ مع المخطئ ويهدم الثقة، بينما يتعلم الطلاب الانضباط مما يرونه في سلوك معلمهم.","يحيل كل مخالفة إلى الإدارة":"المعلم يعالج المخالفات البسيطة في أول حدوثها بنفسه، وإحالة كل مخالفة تُضعف دوره في الصف، والقدوة تؤثر في السلوك قبل أي إحالة."}},"l48lrv":{"w":{"إنذار كتابي فوري وإحالة للإدارة":"الإنذار الكتابي والإحالة تصعيد، والمعلم قرر هنا أن يبدأ بأسلوب بنّاء قبل التصعيد، فلا يناسبان هذه المرحلة.","تجاهل كل مخالفاته مهما كانت":"التجاهل المقصود أسلوب لسلوك بسيط غرضه لفت الانتباه، أما تجاهل المخالفات كلها فيتركها بلا معالجة ولا يحدد له السلوك المطلوب وعواقبه.","نقله إلى فصل آخر":"نقل الطالب إلى فصل آخر ينقل المشكلة ولا يعالجها، ولا يشركه في تحمل مسؤولية سلوكه كما يفعل العقد السلوكي."},"e":"العقد السلوكي يشركه في المسؤولية ويحدد التوقعات والعواقب بوضوح."},"14fgfk2":{"w":{"مغلق له إجابة واحدة":"السؤال المغلق يستدعي معلومة واحدة محددة، وهذا السؤال يطلب رأياً وتبريراً، فتتعدد إجاباته بتعدد آراء الطلاب.","سابر يبني على إجابة سابقة":"السؤال السابر يتابع إجابة قالها الطالب ليعمّقها أو يصححها، وهنا لا توجد إجابة سابقة، بل سؤال يفتح باب الرأي من البداية.","تجميعي":"السؤال التجميعي (التقاربي) يقود الطلاب إلى إجابة واحدة صحيحة، أما طلب الرأي والتبرير فيفتح إجابات متعددة، وهذا تفكير متباعد."},"e":"الرأي والتبرير يحتملان إجابات متعددة، وهذا السؤال المفتوح."},"6vo2gu":{"w":{"تحقيق الذات وفق هرم ماسلو":"تحقيق الذات قمة هرم ماسلو ولا يتحقق بموقف استماع واحد، أما الإنصات الدافئ فيلبي حاجة الأمن والانتماء التي يحتاجها الطالب ليبوح بمشكلته.","التفوق الدراسي الفوري":"التفوق الدراسي نتيجة بعيدة تحتاج تعلماً وجهداً متراكماً، والإنصات المتقبل أثره المباشر نفسي: يطمئن الطالب فيتحدث عن مشكلته.","التنافس مع زملائه":"التنافس مقارنة بالآخرين لا صلة لها بموقف إنصات فردي، فالدفء والتقبل يمنحان الطالب الأمان ليعبر عن مشكلته."},"e":"الإنصات المتقبل يوفر الأمن والانتماء، وهما شرط البوح."},"1xqw7zg":{"w":{"منح نجمتين لكل إجابة صحيحة":"النجمتان هنا ليستا مكافأة رمزية، بل نقطتا قوة يذكرهما المعلم في عمل الطالب، تليهما أمنية تحدد ما يحتاج إلى تحسين.","تأجيل التغذية الراجعة إلى نهاية الوحدة":"الاستراتيجية تحدد محتوى التغذية الراجعة لا توقيتها، وتأجيلها إلى نهاية الوحدة يضعف أثرها، فهي أنفع حين تأتي قريبة من الأداء.","مقارنة الطالب بزميلين متفوقين":"الاستراتيجية تصف عمل الطالب نفسه: قوتان فيه وجانب يحسّنه، أما مقارنته بزملاء متفوقين فتضعف دافعيته ولا تحدد له ما يحسّنه."}},"13sgr4o":{"w":{"وحيد الاتجاه":"الاتصال وحيد الاتجاه يرسل فيه المعلم ويستقبل الطلاب فقط كالمحاضرة، والسؤال يصف تفاعل الجميع مع بعضهم ومع المعلم.","ثنائي الاتجاه":"ثنائي الاتجاه حوار يتبادل فيه المعلم والطالب الأسئلة والإجابات، دون تفاعل الطلاب بعضهم مع بعض كما يصف السؤال.","ثلاثي الاتجاه":"ثلاثي الاتجاه يضيف تفاعلاً محدوداً بين بعض الطلاب، لكنه لا يصل إلى تفاعل جميع الطلاب مع بعضهم ومع المعلم، وهذا وصف النمط المتعدد."},"e":"المفتوح نمط التعلم التعاوني."},"qmzznz":{"w":{"مقاطعة الطالب لتصحيح خطئه فوراً":"الإنصات النشط يقوم على عدم المقاطعة، فيُترك الطالب ليكمل فكرته، ثم يبحث المعلم عن الجزء الصحيح فيها قبل أن يصحح.","النظر إلى الدفتر أثناء حديث الطالب":"الانشغال بالدفتر رسالة غير لفظية بعدم الاهتمام، والإنصات النشط يظهر بالنظر إلى الطالب والإيماء له وهو يتكلم.","الانتقال فوراً إلى سؤال آخر":"الانتقال السريع يقطع الحوار ويُشعر الطالب أن كلامه لم يُسمع، والإنصات النشط يتوقف عند كلامه ويعيد صياغته ليتأكد من فهمه."}},"vx940y":{"w":{"تجميع طلاب كل خلفية في مجموعة واحدة":"التجميع حسب الخلفية يعزل الطلاب ويوسمهم، والمجموعات الأنفع غير متجانسة يتعلم فيها كل طالب من اختلاف زملائه.","تجنب الحديث عن الاختلافات نهائياً":"تجنب الاختلافات تماماً يتجاهل جزءاً من هوية الطلاب، واحترام التنوع يعني الاعتراف به وإشراك الجميع في النقاش باحترام.","إعفاء بعضهم من المشاركة مراعاة لظروفهم":"الإعفاء من المشاركة يعزل الطالب ويوحي بضعف التوقع منه، والمراعاة الصحيحة دعمه ليشارك مع زملائه لا إبعاده."},"e":"احترام التنوع يعني إشراك الجميع باحترام."},"wm1mgx":{"w":{"ضبطاً صارماً للصف":"الضبط الصارم يقوم على القواعد والعواقب، أما التحية بالأسماء فتبني علاقة دافئة تُشعر الطالب بالترحيب قبل أي أداة أو عقوبة.","تقويماً تشخيصياً":"التقويم التشخيصي يقيس معارف الطلاب السابقة قبل التعلم، والتحية عند الباب لا تقيس شيئاً، بل تبني علاقة وانتماء.","تعزيزاً سالباً":"التعزيز السالب إزالة شيء مزعج ليزيد سلوك معين، والتحية بالأسماء لا تزيل شيئاً ولا تستهدف سلوكاً بعينه، بل تبني الانتماء."}},"9nrxp6":{"w":{"زمن انتظار كافٍ بعد السؤال":"زمن الانتظار من 3 إلى 5 ثوانٍ يرفع جودة الإجابات ويتيح للخجولين المشاركة، فهو يعزز التواصل الداعم لا يعيقه.","تنويع الأسئلة بين مغلقة ومفتوحة":"تنويع الأسئلة يتيح للطلاب أن يتذكروا ثم يفكروا ويعبروا عن آرائهم، فهو من ممارسات التواصل الداعم للتعلم لا مما يعيقه.","التغذية الراجعة الوصفية":"التغذية الراجعة الوصفية تحدد للطالب ما أحسنه وما يحسّنه، وهي من أقوى صور التواصل الداعم للتعلم، فلا تكون هي الاستثناء."}},"1o25a3v":{"w":{"نمطاً فوضوياً في الإدارة":"النمط الفوضوي تضيع فيه الضوابط، والعبارة لا تتحدث عن غياب قواعد، بل عن معلم ينصت لطلابه ويحتفظ برأيه حين يختلف معهم.","ضعفاً في الضبط الصفي":"الاستماع مع الاحتفاظ بالرأي ليس تساهلاً، فاختلاف المعلم مع طلابه يدل على موقف واضح، وإنصاته لهم يدل على احترام لا على ضعف ضبط.","تعزيزاً مادياً":"التعزيز المادي أشياء ملموسة تُمنح بعد السلوك، والعبارة تصف أسلوب المعلم في الإنصات والاحترام، لا مكافأة يقدمها."}},"cjsqcr":{"w":{"كلام مباشر يحد من مشاركة الطلاب":"الكلام المباشر عند فلاندرز هو الشرح وإعطاء التوجيهات والنقد، والمعلم هنا يمدح ويبني على أفكار الطلاب ويسأل، وهذه فئات غير مباشرة.","كلام طلاب يبادرون به من أنفسهم":"فئتا كلام الطلاب تخصان ما يقوله الطلاب أنفسهم، والمشرف هنا يصنف كلام المعلم: مدحه وبناءه على أفكارهم وأسئلته.","صمت أو فوضى لا يمكن تصنيفها":"فئة الصمت أو الفوضى تُرصد حين يتوقف الكلام أو يتعذر فهمه، والمشرف هنا رصد كلاماً واضحاً للمعلم: مدحاً وأسئلة وبناءً على أفكار الطلاب."}},"mfyauf":{"w":{"تجاهل الخطأ حفاظاً على مكانته أمام الطلاب":"الاعتراف بالخطأ يبني الثقة ولا يُضعف مكانة المعلم، وتجاهله يترك الطلاب على قاعدة خاطئة ويخالف مؤشر التراجع عن الخطأ وتصحيحه.","تصحيحه في ورقة الاختبار دون إشارة إلى ما حدث":"التصحيح يكون في أقرب وقت أمام من وصلهم الخطأ، أما وضعه في الاختبار فيحاسب الطلاب على ما لم يُشرح لهم صحيحاً.","انتظار أن يكتشف الطلاب الخطأ بأنفسهم":"المعلم هو من اكتشف الخطأ، وانتظار اكتشاف الطلاب يؤخر التصحيح وقد لا يحدث، فتبقى القاعدة الخاطئة عندهم."}},"1i4l8w3":{"w":{"قبول الطلب والتواصل معه عبر حسابه الخاص لتقوية العلاقة وكسب ثقته":"التواصل الشخصي خارج القنوات المعتمدة يتجاوز حدود العلاقة المهنية مهما كانت النية، والثقة تُبنى بودّ عادل داخل القنوات المدرسية.","رفض الطلب بحدة أمام زملائه ليكون عبرة لغيره":"حفظ الحدود لا يحتاج إلى إحراج، فالرفض بحدة أمام الزملاء يجرح الطالب علناً، والأنسب توجيهه على انفراد وبلطف إلى القنوات المعتمدة.","تجاهل الطلب دون أي رد":"التجاهل لا يوجه الطالب إلى مكان يعرض فيه أموره الخاصة، فيبقى بلا دعم، والأنسب توجيهه بلطف إلى القنوات المعتمدة والموجه الطلابي."}},"cs1fz5":{"w":{"توثيق درجات السلوك ورصدها في نظام نور":"توثيق درجات السلوك ورصدها في النظام من أدوار إدارة المدرسة، أما المعلم فيرصد مشكلات الدرجة الثانية فأعلى ويسلّم أسماء الطلاب للإدارة.","إصدار قرار نقل الطالب المخالف إلى مدرسة أخرى":"قرار نقل الطالب إلى مدرسة أخرى تصدره الجهة المختصة في إدارة التعليم، فهو خارج صلاحيات المعلم وإدارة المدرسة معاً.","حسم درجات المواظبة على الطالب المتغيب":"حسم درجات المواظبة من أدوار إدارة المدرسة لا المعلم، ودور المعلم المنصوص عليه هنا تمثيل القدوة الحسنة وتعزيز الانضباط الذاتي."},"e":"من أدوار المعلم في القواعد: تمثيل القدوة الحسنة في القول والفعل وتعزيز الانضباط الذاتي."},"x1ty6o":{"w":{"حسم درجتين من درجات السلوك الإيجابي":"التأخر لأول مرة من مشكلات الدرجة الأولى، وإجراؤها الأول تنبيه شفهي تربوي، والحسم ليس من الإجراءات الثلاثة الأولى التي يباشرها المعلم.","استدعاء ولي الأمر وأخذ تعهد خطي عليه بعدم التكرار":"إشعار ولي الأمر يأتي بعد تنبيهين في الإجراءات المتدرجة، والتأخر هنا لأول مرة، فيبدأ المعلم بتنبيه شفهي تربوي.","تحويله فوراً إلى لجنة التوجيه الطلابي":"المعلم يباشر الإجراءات الثلاثة الأولى بنفسه ولا يحيل إلا من لم يستجب، وتأخر أول مرة لا يستدعي تحويلاً فورياً إلى اللجنة."}},"spk3as":{"w":{"حسم درجات السلوك بنفسه مباشرة، ثم إبلاغ الطالب وولي أمره بذلك":"مشكلات الدرجة الثانية تتخذ إجراءاتها الإدارة، ودور المعلم رصدها وتسليم الأسماء، فحسمه الدرجات بنفسه تجاوز لصلاحيته.","إخراج الطالب من الصف بقية اليوم":"إقصاء الطالب خارج الصف ممارسة ممنوعة بنص المادة 28 من القواعد، ولا يعالج المخالفة، بل يحرمه من التعلم.","الاكتفاء بالتنبيه الشفهي دون توثيق":"التنبيه الشفهي أول إجراءات الدرجة الأولى، والخروج دون استئذان من الدرجة الثانية، فيلزم المعلم رصده وتسليم اسم الطالب للإدارة."},"e":"الدخول أو الخروج من الفصل دون استئذان من مشكلات الدرجة الثانية، وعلى المعلم رصد مشكلات الدرجة الثانية فأعلى التي باشرها وتسليم الأسماء للإدارة التي تتخذ الإجراءات."},"10aw4bc":{"w":{"تمكينه من فرص تعويض الدرجات المحسومة":"فرص التعويض ممارسة تربوية تتيحها القواعد ليصلح الطالب سلوكه ويستعيد درجاته، فهي مطلوبة لا مما نصت على تجنبه.","إشعار ولي أمره بالإجراءات المتخذة":"إشعار ولي الأمر جزء من الإجراءات المتدرجة نفسها، كما في الإجراء الثالث لمشكلات الدرجة الأولى، فهو مطلوب لا ممنوع.","مراعاة مناسبة الإجراء لمرحلته العمرية":"مناسبة الإجراء لعمر الطالب مبدأ تربوي يجعل المعالجة مفهومة له وعادلة، فهي ممارسة مطلوبة لا مما نصت القواعد على تجنبه."}},"2e4yqx":{"w":{"إعطاء الأجهزة للطلاب المتفوقين فقط لضمان إنجاز النشاط":"حصر الأجهزة في المتفوقين يحرم بقية الطلاب من المصدر، والمؤشر يطلب إتاحة المصادر لجميع المتعلمين بتناوب عادل عند نقصها.","إلغاء النشاط كاملاً":"إلغاء النشاط يحرم الجميع رغم توفر 10 أجهزة، والنقص يُعالج بتناوب منظم بين المجموعات مع مهمة موازية لمن ينتظر.","السماح لمن يملك جهازاً شخصياً فقط بالمشاركة في النشاط الرقمي":"ربط المشاركة بامتلاك جهاز شخصي يجعل الإتاحة تابعة لظروف الأسرة فيُحرم بعض الطلاب، والمؤشر يطلب وصول الجميع إلى المصدر."}},"1tmfcmr":{"w":{"تشغيل الجهاز لأول مرة أمام الطلاب":"التشغيل لأول مرة أمام الطلاب يعني أن الجهاز لم يُفحص، فإن تعطل ضاع وقت الحصة، والجاهزية فحص قبل الحصة مع بديل.","الاعتماد على الطلاب لإصلاح أي عطل":"إصلاح الأعطال ليس مهمة الطلاب، والاعتماد عليهم يضيع وقت التعلم، والجاهزية مسؤولية المعلم بفحص الجهاز مسبقاً وتجهيز بديل.","تأجيل العرض إذا تعطل الجهاز إلى الأسبوع التالي":"التأجيل رد فعل بعد العطل يضيع وقت التعلم، والجاهزية تمنع ذلك مسبقاً بفحص الجهاز وتجهيز بديل يكمل به الحصة."}},"je75hp":{"w":{"السماح للطلاب بجمع أغراضهم قبل الخروج":"جمع الأغراض يؤخر الخروج ويعيق الحركة في الممرات، وخطة الإخلاء تنص على الخروج فوراً دون الحقائب.","التحقق بنفسه من مصدر الإنذار قبل إخراج الطلاب":"الإخلاء يُنفذ فور الإنذار دون انتظار التأكد من مصدره، فالتحقق يؤخر الخروج وقد يترك الطلاب بلا إشراف في لحظة خطر.","إبقاء الطلاب في الفصل مع إغلاق الباب حتى تصل تعليمات الإدارة":"إنذار الحريق يستوجب تنفيذ خطة الإخلاء فوراً، وانتظار تعليمات الإدارة داخل الفصل يؤخر الخروج ويعرض الطلاب للخطر."}},"1a3rxw8":{"w":{"السماح للطلاب بتذوق المواد للتعرف عليها":"تذوق مواد المختبر خطر قد يسبب تسمماً، ولهذا تُوسم المواد ليُتعرف عليها بقراءة الملصق لا بالتذوق.","البدء بالتجربة مباشرة ثم شرح التعليمات في نهايتها":"تعليمات السلامة تُشرح قبل التجربة لتمنع الخطر، وشرحها في النهاية يأتي بعد أن يكون الطلاب قد تعرضوا له.","ترك الطلاب ينفذون التجربة دون إشراف لتنمية استقلاليتهم":"الاستقلالية لا تُنمّى على حساب السلامة، والمختبر يتطلب إشرافاً دائماً من المعلم مهما كان نوع التجربة."}},"4j2t88":{"w":{"مطالبته بالعودة إلى مقعده بهدوء حتى نهاية الحصة ثم الحديث معه":"تأجيل الحديث حتى نهاية الحصة يعامل الحالة كأنها عادية، والمادة 30 تطلب أخذ كلامه بجدية وتبليغ الجهات المختصة فوراً.","توجيه أسئلة كثيرة له لمعرفة كل التفاصيل قبل إبلاغ أحد":"المادة 30 تطلب تجنب الضغط على الطالب بكثرة الأسئلة، والإبلاغ يكون فوراً لا بعد جمع التفاصيل.","إخبار زملائه بحالته ليراقبوه":"إخبار الزملاء يكشف خصوصية الطالب، والمادة 30 توجب مراعاة خصوصيته، ومتابعة حالته مسؤولية الكبار والجهات المختصة لا زملائه."}},"os2s5h8":{"w":{"مساعدة الطالب المعنف على تعلم المهارات الاجتماعية المناسبة لعمره.":"تعليم المهارات الاجتماعية إجراء وقائي لاحق، وهو موجّه إلى الضحية، والخطوة الأولى تعالج الموقف الحاضر بتنبيه المعتدين أنفسهم.","إبلاغ الإداريين والأهل بالحادثة ليتم التدخل بالأسلوب الملائم.":"التبليغ خطوة لاحقة، فالحادثة تقع لأول مرة ويستطيع المعلم معالجتها بنفسه، والتصعيد يكون عند التكرار أو الخطر.","توفير نموذج للسلوك المقبول والذي يفترض على جميع الطلاب اتباعه.":"نموذج السلوك المقبول للجميع إجراء عام لا يعالج الموقف الحاصل، والطالب يُشتم الآن، فالأولى تنبيه المعتدين مباشرة."},"e":"الخطوة الأولى في موقف يحدث لأول مرة هي إشعار المعتدين فورًا بأن سلوكهم مرفوض لتحقيق البيئة الآمنة. (المعيار 9.3)"},"o145d4xe":{"w":{"وضع ملصق مكتوب عليه عبارة «أحسنت» على أعمال الطلاب.":"الملصق تعزيز عام لا يحدد للطالب ما الذي أجاده، وطلاب الثانوية يتأثرون أكثر بتعليق فردي يسمّي الجوانب المميزة في عملهم.","تسجيل أسماء الطلاب المكرمين أسبوعيًّا؛ لضمان عدم تجاهل أي طالب.":"القوائم الأسبوعية تعزيز عام ومتأخر عن الأداء، ولا تخبر الطالب بما أجاده تحديداً، بخلاف التعليق الفردي على الجوانب المميزة.","خفض عدد الواجبات والمهام المطلوبة تشجيعًا لهم.":"خفض الواجبات يقلل فرص التعلم ويخفض التوقعات من طلاب أداؤهم جيد، والدعم الأقوى تعليق فردي يبرز جوانب تميزهم."},"e":"التغذية الراجعة الفردية المحددة على الجوانب المميزة هي أقوى أشكال التعزيز لطلاب المرحلة الثانوية. (المعيار 9.4)"},"o1iiyjxn":{"w":{"مستويات إنجاز الطلاب.":"ترتيب الجلوس حسب مستوى الإنجاز يوصم الطلاب ويضر بالبيئة الآمنة، والبيئة المادية تُرتب وفق النشاط: صفوف للعرض ومجموعات للتعاون.","طبيعة المادة والمهارات التي سيدرسها.":"طبيعة المادة أعم من أن تحدد ترتيب المقاعد، فالمادة الواحدة تحتاج عرضاً مرة ونقاشاً أو عملاً تعاونياً مرة أخرى، ولكل نشاط ترتيبه.","الخلفيات الاجتماعية والثقافية للطلاب.":"الترتيب حسب الخلفية الاجتماعية يوصم الطلاب ويفرقهم، والمقاعد والأدوات تُرتب وفق ما يتطلبه النشاط من عمل فردي أو جماعي أو نقاش."},"e":"ترتيب البيئة المادية للصف يتبع نوع النشاط (فردي، مجموعات، نقاش، عرض). (المعيار 9.3)"},"o1quks2d":{"w":{"تذكير الطلاب بأن عدم الانتباه للدرس سيكون له عواقب وخيمة.":"التهديد بالعواقب يعالج الطالب لا السبب، فعدم انتباه عدد من الطلاب معاً مؤشر على ملل الدرس، وعلاجه تغيير النشاط.","التغافل عن هؤلاء الطلاب وعدم إرباك خطة سير الدرس.":"التغافل يترك المشكلة قائمة والطلاب خارج التعلم، وكسر الروتين بنشاط قصير يستعيد انتباههم دون أن يضيع خطة الدرس.","نقل أماكن جلوس الطلاب الذين لم ينتبهوا للدرس إلى المقاعد الأمامية.":"نقل المقاعد يعالج أفراداً ولا يعالج سبب الملل الذي أصاب عدداً من الطلاب معاً، فيبقى الدرس على حاله."},"e":"عدم الانتباه الجماعي مؤشر على ملل الدرس، والعلاج تغيير النشاط لاستعادة الانتباه ثم المتابعة. (المعيار 9.2)"},"oil3nv":{"w":{"الاجتماع بالطلاب في بداية العمل وعند نهايته لتقويم العمل.":"الاجتماع في البداية والنهاية فقط يترك فترة التنفيذ بلا دعم، مع أن أسئلة الطلاب وعقباتهم تظهر أثناء العمل وتحتاج متابعة منتظمة.","عمل قائمة بالمهارات الأكاديمية اللازمة لإكمال المشروعات البحثية بنجاح.":"قائمة المهارات تخطيط مسبق لا متابعة، وهي لا تجيب عن أسئلة المجموعات حين تواجه صعوبة أثناء التنفيذ.","طلب المعلم من بقية زملائه معلمي الصف الأول المتوسط دمج بعض مهارات البحث في دروسهم.":"دمج مهارات البحث في دروس الزملاء تعاون عام قد يفيد لاحقاً، لكنه لا يضمن متابعة مجموعات هذا المعلم وتيسير تنفيذ بحوثهم."},"e":"الهدف سهولة التنفيذ، وأكثر ما يضمنها متابعة منتظمة لكل مجموعة في جدول معلن يُجاب فيه عن أسئلتهم أثناء العمل. (المعيار 9.2)"},"o1tl00vw":{"w":{"الأنشطة المدرسية لضمان التركيز على الأنشطة التي يبادر بها الطلاب.":"التركيز على أنشطة يبادر بها الطلاب وسيلة تنظيمية، والتسرب مرتبط بضعف الانتماء، فالهدف الرئيس بناء شعور الطالب بالعضوية في مجتمع تعلم متعاون.","الوقت في جدول يتيح للطلاب معرفة أقصى وقت يستغرقه الدرس مسبقًا.":"إعلان مدة الدرس مسبقاً إجراء لتنظيم الوقت، وهو وسيلة لا هدف رئيس، ولا يعالج ضعف الانتماء المرتبط بالتسرب.","الوقت لضمان تنفيذ أنشطة تتيح المشاركة الجماعية والفردية بالتساوي.":"توزيع المشاركة بالتساوي بين الجماعي والفردي ترتيب إجرائي للوقت، والهدف الرئيس الذي يعالج التسرب هو تعزيز انتماء الطالب ومشاركته في مجتمع تعلم."},"e":"التسرب مرتبط بضعف الانتماء، فالهدف الرئيس لإدارة بيئة التعلم بناء شعور الطالب بالانتماء والعضوية في مجتمع متعاون. (المعيار 8.2)"},"o1vqqywv":{"w":{"وضع أهداف تعليمية موحدة لجميع الطلاب.":"الأهداف الموحدة للجميع تتجاهل الفروق الفردية بينهم، والسؤال عن بيئة إيجابية، وهي تبدأ بعلاقة دافئة تُشعر الطلاب بالترحيب.","تقديم دروس سهلة لجميع الطلاب.":"الدروس السهلة للجميع تخفض التوقعات من الطلاب، والبيئة الإيجابية تقوم على علاقة دافئة مع تحدٍّ مدعوم، لا على تقليل المطلوب.","منح الطلاب حرية تكوين المجموعات أثناء الأنشطة الجماعية.":"حرية تكوين المجموعات قد تقصي بعض الطلاب فلا يختارهم أحد، والمجموعات الأنسب غير متجانسة بأدوار محددة."},"e":"البيئة الإيجابية تبدأ بعلاقة دافئة وإشعار الطلاب بالترحيب، والتحية اليومية أبسط تطبيق لذلك. (المعيار 9.3)"},"o36lqhl":{"w":{"تقليل احتمالية حدوث هذه المواقف، بمساعدة الطالب المتعرّض للعنف على تعلم المهارات الاجتماعية المناسبة لعمره.":"إجراء وقائي يقلل تكرار المواقف مستقبلاً ويوجَّه إلى الضحية، أما الموقف الحاصل فيعالجه المعلم أولاً بتنبيه المعتدين أنفسهم.","تبليغ إدارة المدرسة والمرشد والأهل بالحادثة ليتدخلوا تدخلًا مباشرًا.":"التبليغ غير مناسب لسلوك يحدث أول مرة ويستطيع المعلم علاجه بحكمته، فمكانه عند التكرار أو الخطر لا كخطوة أولى.","توفير نموذج للسلوك المقبول يفترض على جميع الطلاب اتباعه.":"نموذج السلوك المقبول للجميع إجراء عام يفيد في الوقاية، لكنه لا يعالج اعتداء وقع الآن على طالب بعينه."},"e":"في أول حدوث للسلوك يعالج المعلم الموقف فورًا بتنبيه المعتدين وبيان خطورة التكرار. (المعيار القديم 8.4)"},"o1k3b6zh":{"w":{"الاجتماع بمسؤول المكتبة المدرسية ومناقشة سهولة تصنيف المصادر التعليمية في المكتبة.":"تصنيف مصادر المكتبة شأن يخص مسؤولها وخارج دائرة المتابعة المباشرة، فلا يضمن دعم المجموعات والإجابة عن أسئلتها أثناء العمل.","عمل قائمة بالمهارات التعليمية المتوقع من الطلاب اكتسابها بعد تنفيذ المشروعات البحثية بنجاح.":"قائمة المهارات المتوقع اكتسابها تخطيط لنواتج التعلم بعد المشروع، والمطلوب هنا تيسير التنفيذ نفسه بمتابعة كل مجموعة أثناء العمل.","طلب المعلم من بقية زملائه معلمي الصف الأول المتوسط مناقشة الطلاب في مشروعاتهم البحثية أثناء شرح دروسهم.":"الزملاء خارج دائرة المتابعة المباشرة لهذا المشروع، وصاحب المشروع أولى بجدول يلتقي فيه كل مجموعة ويجيب عن أسئلتها."},"e":"سهولة التنفيذ تتحقق بجدول متابعة معلن لكل مجموعة يضمن الدعم والإجابة عن الأسئلة طوال العمل. (المعيار القديم 5.3، صعوبة 0.496)"},"oo0hudq":{"w":{"تنظيم الأنشطة المدرسية لضمان التركيز على الأنشطة التي يوجهها المعلم لطلابه.":"التركيز على أنشطة يوجهها المعلم يجعل الطالب متلقياً، ولا يبني شعوره بالعضوية في مجتمع تعلم، وهذا الشعور هو ما يرتبط بعلاج التسرب.","تنظيم الوقت في جدول يتيح للطلاب معرفة أقصى وقت يستغرقه النشاط سلفًا.":"إعلان مدة النشاط مسبقاً إجراء تنفيذي لتنظيم الوقت وليس هدفاً رئيساً، ولا يعالج ضعف الانتماء المرتبط بالتسرب.","تنظيم الأنشطة التي تتيح مشاركة الفصل بأكمله والمجموعات الصغيرة والتعلّم الفردي بالتساوي.":"التوازن بين عمل الفصل كله والمجموعات والتعلم الفردي إجراء تنفيذي لتوزيع الأنشطة، أما الهدف الرئيس فتعزيز انتماء الطالب وعضويته في مجتمع تعلم."},"e":"علاج التسرب يبدأ من تعزيز انتماء الطالب للمدرسة وشعوره بالعضوية في مجتمع تعلم؛ هذا هو الهدف الرئيس لإدارة بيئة التعلم. (المعيار القديم 9.2، صعوبة 0.720)"},"17o4dl3":{"w":{"تشخيصي":"التشخيصي يحدد نقاط القوة والضعف وأسباب الصعوبة ليُبنى عليها العلاج، والمعلم هنا يقيس بقاء أثر التعلم بعد شهرين.","تكويني":"التكويني يجري أثناء التعلم لتحسينه وتعديل التدريس، أما هنا فالوحدة واختبارها النهائي انتهيا قبل شهرين.","قبلي":"القبلي يسبق التعلم ليقف على الاستعداد والمتطلبات السابقة، والمعلم هنا يقوّم بعد انتهاء الوحدة لا قبلها."},"e":"التتبعي يُجرى بعد فترة من التقويم الختامي لقياس بقاء أثر التعلم، وهذا ما فعله المعلم بعد شهرين."},"xdviav":{"w":{"ستانفورد بينيه ووكسلر":"هذان المقياسان يقيسان الذكاء والقدرة العقلية العامة، والمرشد هنا يريد قياس الميول المهنية للطلاب.","TIMSS وPISA":"هذان اختباران دوليان يقيسان أداء الطلاب في مجالات كالرياضيات والعلوم ويقارنان مستوى الدول، ولا يقيسان الميول المهنية للطالب.","ليكرت وثيرستون للاتجاهات":"ليكرت وثيرستون طريقتان لبناء مقاييس الاتجاهات، أي موقف الفرد من موضوع ما، أما الميول المهنية فلها مقاييس خاصة كسترونج وكودر."},"e":"سترونج وكودر مقياسا ميول مهنية."},"y8o2x7":{"w":{"الموضوعية":"الموضوعية أن تكون الدرجة مستقلة عن رأي المصحح، والخاصية هنا تتعلق بتغطية المحتوى والأهداف بأوزانها.","الثبات":"الثبات استقرار النتائج إذا أعيد تطبيق الاختبار في ظروف مماثلة، ولا علاقة له بتغطية المحتوى والأهداف بأوزانها.","التمييز":"التمييز قدرة الاختبار على كشف الفروق بين الطلاب المتفوقين والضعاف، والسؤال يصف تغطية جوانب المحتوى والأهداف."},"e":"الشمول تغطية المحتوى وفق جدول المواصفات."},"1xdhh5d":{"w":{"الاختبارات التحصيلية":"الاختبارات التحصيلية تقيس ما تعلمه الطالب من معارف، والأداة هنا يصف فيها الطالب اتجاهاته وميوله بنفسه.","اختبارات الأداء":"اختبارات الأداء تقيس المهارة بمهمة عملية ينفذها الطالب أمام المعلم، أما هنا فالطالب يصف اتجاهاته وميوله بنفسه.","قوائم الشطب":"قائمة الشطب يرصد بها المعلم الملاحِظ وجود السلوك أو غيابه، أما هنا فالطالب نفسه يصف اتجاهاته وميوله."},"e":"التقارير الذاتية تقيس النواتج الوجدانية بإجابة الطالب عن نفسه."},"d2anxz":{"w":{"قياساً":"القياس رصد رقمي للأداء بلا حكم، والمعلم هنا أضاف حكماً على مستوى الطالب مستنداً إلى محك.","تقويماً":"التقويم حكم يتبعه قرار علاج وتحسين، والمعلم هنا توقف عند الحكم دون وضع خطة لتحسين أداء الطالب.","تغذية راجعة":"التغذية الراجعة معلومات تصف للطالب جوانب أدائه وتوجهه للتحسين، وعبارة المعلم هنا حكم على المستوى فقط."},"e":"إصدار حكم على قيمة الأداء في ضوء محك هو التقييم."},"1erm4xk":{"w":{"مرادف للتقويم":"التقويم أشمل من الاختبار، فهو حكم يتبعه علاج وتعديل، والاختبار مجرد وسيلة لجمع البيانات الكمية.","أحد أنواع التقويم الختامي":"الاختبار أداة لا نوع من التقويم، وقد يُستخدم في التقويم القبلي والتكويني والختامي، فلا يختص بالختامي وحده.","الغاية التي يسعى إليها القياس":"الاختبار وسيلة يُجمع بها الرقم في عملية القياس، فهو أداة تخدم القياس وليس الغاية التي ينتهي إليها."},"e":"الاختبار وسيلة لجمع البيانات الكمية، أي أداة قياس."},"v84z89":{"w":{"تحصيل":"الاختبار التحصيلي يقيس ما تعلمه الطالب فعلاً من محتوى درسه، والمطلوب هنا التنبؤ بنجاحه في تخصص مستقبلي.","تشخيصي":"التشخيصي يبحث عن نقاط القوة والضعف وأسباب الصعوبة، لا عن التنبؤ بنجاح الطالب في تخصص هندسي مستقبلاً.","ختامي":"الختامي يأتي في نهاية الوحدة أو الفصل ليحكم بالنجاح والانتقال فيما مضى، والسؤال يريد التنبؤ بالمستقبل."},"e":"اختبارات الاستعداد تقيس إمكانية التعلم أو النجاح مستقبلاً."},"1m907l8":{"w":{"أن يكون مستمراً يواكب التعلم":"الاستمرار من خصائص التقويم الجيد فعلاً، فهو يرافق التعلم ليحسّنه أولاً بأول، فلا يكون هو الاستثناء.","أن يكون شاملاً لجوانب المتعلم المعرفية والمهارية والوجدانية":"الشمول خاصية أساسية للتقويم الجيد، فهو يغطي جوانب المتعلم كلها لا الجانب المعرفي وحده، فليس هو المستثنى.","أن يكون تعاونياً يشارك فيه المعلم والطالب وولي الأمر":"التعاون من خصائص التقويم الجيد المذكورة في الدرس، إذ يشترك فيه أطراف العملية التعليمية، فلا يكون هو الاستثناء."}},"1xxz6ax":{"w":{"النهائي":"النهائي اسم آخر للتقويم الختامي الذي يأتي في نهاية الوحدة أو الفصل، والتكويني يرافق التعلم أثناء التدريس.","المقنن":"المقنن وصف للاختبار الذي يعده متخصصون بتعليمات وظروف موحدة، لا اسم لنوع من التقويم يرافق التعلم.","المعياري":"المعياري طريقة لتفسير الدرجة بمقارنة الطالب بأقرانه، لا تسمية للتقويم الذي يجري أثناء التعلم."},"e":"لأنه يواكب التعلم ويستمر معه طوال التدريس."},"1ey1h4s":{"w":{"ختامي":"الختامي يأتي في نهاية الوحدة أو الفصل ليحكم بالنجاح والانتقال، والمعلم هنا قوّم في بداية العام قبل التعليم.","تكويني":"التكويني يجري أثناء التدريس لتحسين التعلم، أما هنا فالاختبار في بداية العام لتصنيف الطلاب قبل أن يبدأ التعلم.","ذاتي":"التقويم الذاتي يقوّم فيه الطالب عمله بنفسه، والذي طبّق الاختبار وصنّف الطلاب هنا هو المعلم في بداية العام."},"e":"توزيع الطلاب في مستويات وتصنيفهم قبل التعلم من أغراض التقويم القبلي."},"zv9ocr":{"w":{"ترتيب الطلاب من الأعلى إلى الأدنى":"الترتيب يقارن كل طالب بأقرانه ليحدد موقعه بينهم، وهذا تفسير معياري المرجع، أما المحكي فيقارن بمحك إتقان.","رتب مئينية ودرجات معيارية":"هذه الدرجات المحوّلة تحدد موقع الطالب بالنسبة لأقرانه، فهي من أدوات التفسير معياري المرجع لا المحكي.","منحنى اعتدالي لدرجات الصف":"المنحنى الاعتدالي يوزع درجات الصف حول متوسطها ليقارن الطلاب ببعضهم، وهذا من التفسير معياري المرجع."},"e":"المحكي يخبرنا ما يستطيع الطالب عمله (أتقن / لم يتقن) فنتائجه قائمة أهداف."},"bpc187":{"w":{"التأكد من إتقان الطالب لمهارات وحدة معينة":"التأكد من الإتقان يحتاج مقارنة أداء الطالب بمحك محدد، وهذا عمل التقويم محكي المرجع لا المعياري.","منح شهادة إتقان لمهارة مهنية":"شهادة الإتقان تُمنح لمن يبلغ مستوى محدداً مسبقاً مهما كان ترتيبه بين المتقدمين، فهي محكية المرجع.","تشخيص أسباب تدني أداء طالب":"تشخيص أسباب التدني يبحث في نقاط ضعف الطالب نفسه مقارنة بمحك، ولا يحتاج إلى ترتيبه بين أقرانه."},"e":"الانتقاء والمفاضلة يحتاجان ترتيب المتقدمين بعضهم بالنسبة لبعض، وهذا جوهر المعياري."},"10i0c9i":{"w":{"إصدار حكم نهائي على مستوى الطالب في نهاية الوحدة":"الحكم النهائي على الطالب في نهاية الوحدة هو تقويم التعلم الختامي، أما التقويم من أجل التعلم فتكويني يوجه الخطوة التالية.","ترتيب الطلاب لاختيار المتفوقين منهم":"المفاضلة بين الطلاب لانتقاء المتفوقين غرض التقويم معياري المرجع، لا التقويم الذي يفسر الأدلة لتوجيه التعلم.","قياس قدرات الطالب العقلية العامة":"القدرة العقلية العامة تقيسها اختبارات الذكاء، وهي ليست تقويماً صفياً يفسر أدلة التعلم لتوجيه التدريس."},"e":"التقويم من أجل التعلم تقويم تكويني يستخدم الأدلة لتوجيه التعلم والتدريس."},"15cphaw":{"w":{"يوفر على المعلم وقت التصحيح":"توفير وقت التصحيح فائدة تخص المعلم لا الطالب، والسؤال يسأل عن أهم ميزة للتقويم الذاتي بالنسبة للطالب.","يرفع درجاته في الاختبار الختامي":"التقويم الذاتي لا يرفع الدرجات بالضرورة، فقيمته أن يعي الطالب أخطاءه ويعدّل تعلمه، والدرجة نتيجة غير مضمونة.","يغني عن تقويم المعلم":"التقويم الذاتي يكمّل تقويم المعلم ولا يحل محله، فالمعلم يظل يقوّم الطالب ويوجهه بمحكات واضحة."},"e":"التقويم الذاتي ينمي وعي الطالب بأخطائه ودوافعه فيعدل سلوكه ويزيد ثقته."},"u8iylf":{"w":{"قائمة الشطب":"قائمة الشطب تسأل هل السلوك موجود أم لا بإجابة نعم أو لا، دون تدرج في تكرار حدوثه.","سلم التقدير العددي":"سلم التقدير العددي يقدّر درجة السلوك بأرقام مثل 1 إلى 5، والأداة هنا تستخدم كلمات وصفية للتكرار.","الروبرك":"الروبرك يصف بالتفصيل كيف يبدو كل مستوى جودة لكل معيار، لا مجرد كلمات تدل على تكرار السلوك."},"e":"التدريج بكلمات وصفية للتكرار هو سلم التقدير اللفظي."},"7ncavz":{"w":{"أسرع في التصحيح":"السرعة ميزة الروبرك الكلي لأنه يعطي حكماً واحداً، أما التحليلي فيستغرق وقتاً أطول لتقدير كل معيار وحده.","لا يحتاج إلى محكات مسبقة":"الروبرك بنوعيه يُبنى على محكات معدة مسبقاً تصف مستويات الأداء، فهذه ليست ميزة للتحليلي على الكلي.","يعطي حكماً عاماً واحداً على العمل":"الحكم العام الواحد هو ما يميز الروبرك الكلي، أما التحليلي فيعطي درجة مستقلة لكل معيار."},"e":"الروبرك التحليلي يفصّل الدرجة لكل معيار فيعرف الطالب موضع قوته وضعفه."},"sfaffo":{"w":{"لا يصلح إلا للمهارات العملية":"السجل القصصي يصف مواقف السلوك والجوانب الوجدانية للطالب، فاستعماله أوسع من المهارات العملية، وهذا ليس من عيوبه.","يقتصر على تسجيل الدرجات الرقمية":"السجل القصصي وصف سردي لمواقف يلاحظها المعلم، ولا يسجل درجات رقمية أصلاً، فهذا ليس من عيوبه.","لا يمكن استخدامه في الصفوف الدنيا":"السجل القصصي يكتبه المعلم عن الطالب، فيصلح في الصفوف كلها ومنها الصفوف الدنيا، وهذا ليس من عيوبه."},"e":"الوصف السردي لكل طالب يستهلك وقتاً ويعتمد على ما يلاحظه المعلم ويفسره."},"24dkqv":{"w":{"سرعتهم في الكتابة":"خريطة المفاهيم تُقوَّم بصحة الروابط بين المفاهيم وتنظيمها، لا بسرعة الطالب في الكتابة أو إنجازها.","قدرتهم على حفظ التعريفات حرفياً":"الحفظ الحرفي للتعريفات تقيسه أسئلة التذكر، أما الخريطة فتكشف كيف يربط الطالب المفاهيم بعضها ببعض.","مهاراتهم اليدوية في الرسم":"الرسم في الخريطة وسيلة لعرض العلاقات بين المفاهيم، والمقوَّم هو تنظيم الأفكار وترابطها لا جمال الرسم."},"e":"خريطة المفاهيم تُظهر كيف ينظم الطالب المفاهيم ويربطها، وهذا مؤشر على الفهم العميق."},"1bgib1t":{"w":{"الاعتماد على أسئلة الاختيار من متعدد فقط":"الاقتصار على الاختيار من متعدد سمة التقويم التقليدي، والتقويم الأصيل يقيس الأداء في مهام حقيقية ذات معنى.","إخفاء معايير التقويم عن الطلاب حتى نهاية المهمة":"التقويم الأصيل يعلن معاييره للطلاب قبل المهمة ليعرفوا المطلوب منهم، فإخفاؤها يناقض طبيعته.","التركيز على التذكر الحرفي للمعلومات":"التذكر الحرفي من سمات التقويم التقليدي، أما الأصيل فيطلب من الطالب تطبيق ما تعلمه في مواقف واقعية."},"e":"التقويم الأصيل يقيس الأداء في مواقف واقعية ذات معنى مع معايير يعرفها الطالب مسبقاً."},"81blt6":{"w":{"السجل القصصي":"السجل القصصي يكتبه المعلم عن مواقف سلوك الطالب، أما هنا فالطالب نفسه يكتب تأملاته عن تعلمه.","قائمة الشطب":"قائمة الشطب يرصد بها المعلم وجود السلوك أو غيابه بنعم أو لا، ولا يكتب فيها الطالب تأملاته.","بطاقة الملاحظة":"بطاقة الملاحظة أداة يرصد بها المعلم أداء الطالب أثناء العمل، والسجل هنا يكتبه الطالب عن نفسه."},"e":"سجل سير التعلم يكتبه الطالب عن تعلمه."},"1o8bovb":{"w":{"يتساوى عدد المقدمات والاستجابات تماماً":"تساوي العددين يجعل آخر إجابة تُعرف بالاستبعاد دون معرفة، لذا تُجعل الاستجابات أكثر من المقدمات.","تجمع القائمة عناصر من موضوعات مختلفة":"خلط موضوعات مختلفة يكشف الإجابة من نوع العنصر، والقاعدة أن تكون قائمة المطابقة متجانسة في موضوع واحد.","تُرتَّب الاستجابات بترتيب الإجابات الصحيحة":"ربط ترتيب الاستجابات بترتيب الإجابات الصحيحة يكشف للطالب تسلسلها فيخمّن، والمطلوب ألا يدل موضعها على مقدمتها."},"e":"زيادة الاستجابات تقلل التخمين بالاستبعاد، والتجانس يمنع كشف الإجابة من نوع العنصر."},"d7uc0b":{"w":{"أن تحتوي كل عبارة على فكرتين لزيادة الدقة":"العبارة ذات الفكرتين قد يكون جزء منها صحيحاً وجزء خاطئاً فيرتبك الحكم عليها، لذا تحمل كل عبارة فكرة واحدة.","أن تكون أغلب العبارات صحيحة":"إذا غلبت العبارات الصحيحة صار تخمين «صواب» يصيب كثيراً دون معرفة، والمطلوب توازن عدد العبارات الصحيحة والخاطئة.","أن تُستخدم كلمات مثل دائماً وأبداً لتوضيح المعنى":"كلمات الجزم والتعميم تكشف الإجابة لمن لم يتعلم، فالقاعدة تجنبها في عبارات الصواب والخطأ لا استخدامها."},"e":"الفكرة الواحدة تجعل الحكم واضحاً، والنفي المزدوج يربك الطالب."},"1qy00tu":{"w":{"تقليل البدائل إلى اثنين":"مع بديلين فقط يصبح احتمال الإصابة بالتخمين 50%، بينما ينخفض إلى 25% مع أربعة بدائل فعالة.","وضع الإجابة الصحيحة دائماً في البديل الأول":"تثبيت موضع الإجابة يكشف نمطها للطالب فيصيب دون معرفة، والمطلوب توزيع موضع الإجابة الصحيحة بين البدائل.","حذف المشتتات الصعبة":"حذف المشتتات القوية يترك بدائل سهلة الاستبعاد، فيرتفع احتمال الوصول إلى الإجابة بالتخمين لا بالمعرفة."},"e":"كلما زادت البدائل الفعالة انخفض احتمال التخمين الصحيح (25% مع أربعة بدائل)."},"gs2wnu":{"w":{"الأسئلة المقالية الحرة":"المقالية الحرة تحتاج وقتاً طويلاً للإجابة فلا يتسع الزمن إلا لأسئلة قليلة، فتغطي محتوى محدوداً.","المقابلة الشخصية":"المقابلة تُجرى مع كل طالب منفرداً وتستغرق وقتاً، فلا تناسب قياس عدد كبير من الحقائق في زمن محدود.","ملف الإنجاز":"ملف الإنجاز جمع منظم لأعمال الطالب عبر فترة لمتابعة تقدمه، فلا يناسب قياس حقائق كثيرة في زمن محدود."},"e":"الموضوعية قصيرة الإجابة فتغطي محتوى واسعاً بعدد كبير من الفقرات في وقت قصير."},"i2leld":{"w":{"يثبت في البديل الأول لتسهيل التصحيح":"تثبيت الإجابة في البديل الأول يسهّل التصحيح على المعلم، لكنه نمط يكتشفه الطالب فيجيب دون معرفة ويضعف الصدق.","يكون دائماً في البديل الأخير":"وضع الإجابة في البديل الأخير كل مرة نمط ثابت يلتقطه الطالب سريعاً، فيختار الأخير دون أن يعرف المحتوى.","يتبع نمطاً ثابتاً يسهل حفظه":"النمط الذي يسهل حفظه يكشف الإجابة لمن حفظه لا لمن تعلّم، فتقيس الدرجة الفطنة لا التحصيل ويضعف الصدق."},"e":"تغيير الموقع عشوائياً يمنع الطالب من اكتشاف نمط يجيب به دون معرفة."},"1do19t5":{"w":{"15 سؤالاً":"15 سؤالاً هي كل أسئلة الكسور (50 × 0.30)، والمطلوب منها أسئلة الفهم فقط: 15 × 0.40 = 6 أسئلة.","20 سؤالاً":"20 سؤالاً هي كل أسئلة مستوى الفهم (50 × 0.40)، والمطلوب منها أسئلة الكسور فقط: 20 × 0.30 = 6 أسئلة.","12 سؤالاً":"حاصل ضرب الوزنين 30% × 40% يساوي 12% وهي نسبة الخلية لا عدد أسئلتها، و 12% من 50 سؤالاً = 6 أسئلة."},"e":"أسئلة الخلية = العدد الكلي × وزن الموضوع × وزن المستوى = 50 × 0.30 × 0.40 = 6."},"11blrm2":{"w":{"أسماء الطلاب المتوقع نجاحهم":"التعليمات تخبر الطالب كيف يجيب وكم يستغرق، أما توقع نجاح طلاب بأعينهم فحكم مسبق لا يفيد في أداء الاختبار.","الإجابات النموذجية للأسئلة":"الإجابة النموذجية يستخدمها المعلم عند التصحيح، ووضعها في ورقة الاختبار يكشف الإجابات فيفقد الاختبار قيمته.","ملخصاً للمحتوى الدراسي":"ملخص المحتوى أداة مراجعة قبل الاختبار، ووجوده في الورقة يعطي الطالب المعلومة المطلوب قياسها."},"e":"التعليمات تخبر الطالب بما هو متوقع منه: الزمن وأسلوب الإجابة ومكانها وتوزيع الدرجات."},"ewcvv1":{"w":{"يصحح ورقة كل طالب كاملة قبل الانتقال لورقة أخرى":"تصحيح الورقة كاملة يجعل انطباع المعلم عن أول إجابات الطالب يؤثر في درجات بقية أسئلته، فيقوى أثر الهالة.","يبدأ بأوراق الطلاب المتفوقين":"البدء بالمتفوقين يعني معرفة صاحب الورقة، فيدخل الانطباع المسبق عن الطالب في درجته، وهذا جوهر أثر الهالة.","يصحح الأوراق حسب ترتيب الحضور":"ترتيب الأوراق بالحضور لا يعالج مصدر الهالة، فالحل إخفاء الأسماء وتصحيح السؤال الواحد لجميع الطلاب قبل غيره."},"e":"تصحيح السؤال نفسه عبر كل الأوراق يثبت المعيار ويمنع تأثر الدرجة بالانطباع عن الطالب أو عن إجاباته السابقة."},"ijqeza":{"w":{"صياغة الفقرات، تحديد الأهداف، جدول المواصفات، التعليمات":"يبدأ هذا الترتيب بصياغة الفقرات، والفقرات تُكتب في ضوء جدول المواصفات بعد تحديد الأهداف، كما يُسقط تحليل المحتوى.","جدول المواصفات، تحديد الأهداف، تحليل المحتوى، صياغة الفقرات":"جدول المواصفات يقاطع الأهداف مع المحتوى فلا يُبنى قبلهما، ومكانه بعد تحديد الأهداف وتحليل المحتوى.","تحليل المحتوى، صياغة الفقرات، تحديد الأهداف، التعليمات":"تحديد الأهداف هو الخطوة الأولى لا الثالثة، وهذا الترتيب يُسقط جدول المواصفات الذي تُصاغ الفقرات في ضوئه."}},"1j3k1jo":{"w":{"تحديد نجاح الطالب أو رسوبه في نهاية العام":"النجاح والرسوب يُبنيان على درجات المادة وفق لائحة تقويم الطالب، أما نافس فتشخّص المستوى الوطني ولا يترتب عليها نجاح.","ترتيب الطلاب داخل الصف الواحد":"ترتيب الطالب بين أقرانه غرض التقويم معياري المرجع، ونافس تقيس مستوى التعليم على مستوى الوطن لا ترتيب الأفراد.","منح الطالب شهادة إتمام المرحلة":"الشهادة تتبع نجاح الطالب في مواده، ونافس تقويم للنظام التعليمي يقدم مؤشرات عن جودته ولا يترتب عليه شهادة."}},"10ustjg":{"w":{"حفظ الطالب لمحتوى المنهج الوطني":"بيزا لا يتبع منهج دولة بعينها ولا يقيس استظهاره، بل يقيس قدرة الطالب على توظيف ما تعلمه في مواقف حياتية حقيقية.","سرعة الطالب في الإجابة عن أسئلة الكتاب":"أسئلة الكتاب مرتبطة بالمنهج المدرسي، وبيزا يقيس الثقافة القرائية والرياضية والعلمية في مواقف حياتية لا السرعة.","سلوك الطالب داخل الفصل":"سلوك الطالب في الفصل يُقوَّم بالملاحظة والسجل القصصي داخل المدرسة، وبيزا اختبار دولي للقراءة والرياضيات والعلوم."}},"12l56t1":{"w":{"ترتيب الطلاب داخل الفصل":"الترتيب مقارنة بالأقران وهو تقويم معياري المرجع، ومستويات الأداء محكية تقيس نسبة ما أتقنه الطالب من معايير المادة لا موقعه بين زملائه.","تحديد الطلاب الراسبين فقط":"المستويات الأربعة تصف إتقان كل طالب من متفوق إلى غير مجتاز، فلا تقتصر على حصر من لم يجتز بل توجه علاجه.","مقارنة المدرسة بغيرها":"مستويات الأداء تصف إتقان الطالب الفرد لمعايير مادته ليُبنى علاجه، فغرضها تشخيص الطالب نفسه لا مقارنة مدرسة بأخرى."},"e":"في الإجراءات التنفيذية للائحة تقويم الطالب 2025 تُقوَّم مواد الصفين الأول والثاني الابتدائي تكوينياً بمستويات أداء (متفوق، متقدم، متمكن، غير مجتاز) تُحدَّد بنسبة معايير المادة التي أتقنها الطالب، ويُعد المعلم برنامجاً علاجياً لمن لم يتقن معياراً أو أكثر؛ فغرضها تحديد الإتقان وتوجيه العلاج."},"gaptp4":{"w":{"تقويماً رسمياً ضمن دورة التقويم طويلة المدى":"الرسمي مخطط موثق بدرجة والدورة الطويلة على مستوى الوحدة أو الفترة، وهنا سؤال سريع بالبطاقات عُدّل بعده الشرح في الحصة نفسها.","تقويماً ختامياً لإصدار حكم نهائي على تعلم الطلاب":"الختامي يأتي نهاية الوحدة أو الفصل لإصدار حكم، والمعلم هنا قوّم أثناء الشرح وأعاد الشرح بمثال آخر ولم يُصدر حكماً.","تقويماً معيارياً لترتيب الطلاب":"المعياري يقارن الطالب بأقرانه لترتيبهم، والمعلم هنا لم يرتب أحداً بل استخدم نسبة الخطأ ليعدّل شرحه فوراً."}},"1gr3fcu":{"w":{"ملاحظة المعلم لتفاعل الطلاب أثناء النقاش":"ملاحظة التفاعل أثناء النقاش تجري تلقائياً ضمن التدريس دون إعلان مسبق أو زمن ودرجة، فهي من أساليب التقويم غير الرسمي.","سؤال شفهي عابر لتفقد الفهم":"السؤال الشفهي العابر يجري تلقائياً ليعدّل المعلم شرحه فوراً فهو غير رسمي، والرسمي مخطط موثق بزمن ودرجة.","إشارة الطلاب بالإبهام لمدى فهمهم أثناء الشرح":"إشارة الإبهام فحص سريع للفهم بلا درجة ولا توثيق يُبنى عليه حكم، فهي تقويم غير رسمي يوجّه الشرح لحظياً."},"e":"التقويم الرسمي مخطط ومنظم وموثق بشروط محددة ويُبنى عليه حكم."},"1fui3dp":{"w":{"40 درجة للتقويمات التكوينية و60 درجة لاختبار نهاية الفترة":"هذا عكس توزيع اللائحة، فالإجراءات التنفيذية تجعل 60 درجة للتقويمات التكوينية و 40 فقط لاختبار نهاية الفترة.","50 درجة للأعمال و50 درجة للاختبار":"التوزيع مناصفة لم تنص عليه لائحة 2025، فنصيب التقويمات التكوينية 60 درجة ونصيب اختبار نهاية الفترة 40 درجة.","100 درجة لاختبار نهاية الفترة فقط":"حصر الدرجة في الاختبار يلغي التقويم التكويني، والسؤال عن مواد تُقوَّم تكوينياً وختامياً فلها 60 درجة تكوينية و 40 للاختبار."}},"1a95zfw":{"w":{"يُعد ناجحاً لأن مجموعه تجاوز النهاية الصغرى 50% من الدرجة":"تجاوز النهاية الصغرى شرط واحد من شرطين، والشرط الثاني 20% من 40 أي 8 درجات، وهو حصل على 6 فقط.","يُعد ناجحاً لأن الاختبار التحريري لا يدخل في شروط النجاح":"الاختبار التحريري داخل في شروط النجاح عبر النسبة الشرطية، فلا بد من 20% من درجته أي 8 من 40.","يعيد الصف كاملاً دون دور ثانٍ":"عدم تحقيق النسبة الشرطية لا يعني إعادة الصف مباشرة، فالطالب يُختبر في الدور الثاني ولا تُطبق عليه الشرطية هناك."}},"1cboklk":{"w":{"إعفاؤه من اختبار العلوم كاملاً":"الإعفاء يحرمه من إثبات ما يعرفه، والتسهيل يغيّر طريقة الأداء فقط، ومشكلته هنا قراءة الأسئلة لا معرفة العلوم.","تخفيض درجة الاختبار إلى النصف":"تخفيض الدرجة لا يحل مشكلة قراءة الأسئلة، والتسهيل المنصوص عليه يغيّر طريقة الأداء لا الدرجة ولا المستوى المقيس.","إعطاؤه أسئلة أسهل من أسئلة زملائه دون الرجوع لخطته":"الأسئلة الأسهل تخفض المستوى المقيس فهي تعديل لا تسهيل، والتعديل يكون وفق الخطة الفردية، وهو يعرف الإجابات أصلاً."}},"wpah1f":{"w":{"أن يُختبر مع زملائه في الوقت نفسه وبالشروط نفسها دون استثناء":"التسهيلات حق للطالب ذي الإعاقة، ومنها الزمن المناسب والمكان المناسب ومرونة المواعيد، فلا تُفرض عليه شروط زملائه نفسها.","أن تُخفض درجة النجاح إلى النصف في جميع المواد":"التسهيلات تغيّر طريقة الاختبار أو مكانه أو زمنه دون خفض المستوى المقيس، فخفض درجة النجاح ليس من قواعد تقويمه العامة.","أن يتولى معلم التعليم العام وحده إعداد أسئلته":"يشرف معلم التربية الخاصة على تقويم الطالب ذي الإعاقة بالتعاون مع معلم التعليم العام، فلا ينفرد به معلم التعليم العام."},"e":"نصت القاعدة السابعة على ألا يُختبر الطالب ذو الإعاقة في أكثر من مادة تحريرية في اليوم الواحد مع إعطائه الزمن المناسب وتقديم الدعم."},"2yuh1e":{"w":{"يحسم درجة عن كل خطأ إملائي":"الإجراءات نصت على عدم محاسبة الطالب الأصم على الأخطاء الإملائية والنحوية في جميع المواد، فالحسم يخالفها ويقيس اللغة لا المادة.","يطلب منه إعادة الإجابة شفهياً":"إجابته المكتوبة صحيحة المضمون فتُقيَّم كما هي، والمطلوب ألا يتأثر تقويمه بتركيب لغته، لا أن يغيّر طريقة إجابته.","يعطيه صفراً في الأسئلة التي فيها أخطاء لغوية":"الصفر يحاسبه على الأخطاء اللغوية مع صحة مضمونه، والإجراءات نصت ألا يتأثر تقويم الأصم بالتركيب البنائي للغته المكتوبة."}},"o7hsr3":{"w":{"إخراجه من قاعة الاختبار عند كثرة حركته":"الإخراج يعاقبه على سمة من سمات حالته، والمنصوص السماح له بالتوقف والتحرك واختباره في ركن خاص بعيد عن المشتتات.","إعفاؤه من الاختبار والاكتفاء بالأعمال":"التسهيلات تغيّر طريقة الاختبار لا تلغيه، فيُختبر على فترات قصيرة مع السماح له بالتحرك بدل إعفائه.","إلزامه بالجلوس حتى نهاية الوقت ليتعود الانضباط والهدوء":"إلزامه بالجلوس يتجاهل حاجته، والقاعدة السابعة نصت على السماح له بالتوقف والتحرك وتوزيع الاختبار على فترات قصيرة."}},"o1uagvmy":{"w":{"يحدد مهاراته التقنية التي يحتاجها.":"تعبئة النموذج إلكترونياً وسيلة لأداء المهمة لا غايتها، فالمهمة تقيس توظيف ما تعلمه في موقف توظيف حقيقي لا حصر مهاراته التقنية.","يطبق إستراتيجيات ما وراء المعرفة.":"ما وراء المعرفة مراقبة الطالب لتفكيره وتنظيمه له، وليس هدف هذه المهمة التي تنقل ما تعلمه إلى موقف حياتي حقيقي.","يحدد أهدافه التعليمية التي يرغب في تحقيقها من المادة.":"تحديد الأهداف تخطيط ذاتي للتعلم، أما تعبئة طلب توظيف حقيقي فمهمة أصيلة يطبق فيها الطالب ما تعلمه في الواقع."},"e":"هذا تقويم أصيل (واقعي): تعبئة طلب توظيف حقيقي مع السيرة الذاتية مهمة من الحياة، فميزته أن يطبق الطالب ما تعلّمه في الواقع. والسؤال منقول حرفياً من دليل الهيئة 1441 (السؤال 15)، ومفتاحه الرسمي (أ). (المعيار 10.2)"},"o1u6nuvf":{"w":{"يتحدّى الطلاب في تطبيق معارفهم ومهاراتهم بطرق جديدة عليهم.":"تحدي الطلاب بمواقف جديدة يقيس قدرتهم على نقل التعلم، والاختبار التشخيصي هدفه كشف نقاط القوة والضعف والحاجات لا تحديهم.","يوضّح الفروق الفردية بين الطلاب فيما يتعلق بالمعارف والمهارات المستهدفة.":"إظهار الفروق الفردية وظيفة الاختبار التحصيلي معياري المرجع، والتشخيصي يركز على حاجات كل طالب لا على مقارنته بأقرانه.","يقدم معلومات عن إمكانات الطلاب المستقبلية إضافة إلى إنجازاتهم الحالية.":"التنبؤ بإمكانات الطالب المستقبلية وظيفة اختبارات الاستعداد، أما التشخيصي فيحدد نقاط قوته وضعفه الحالية لتوجيه التدريس."},"e":"الاختبار التشخيصي يكشف نقاط القوة والضعف والحاجات قبل التدريس أو عند تعثر التعلم. (المعيار 10.2)"},"o1nd1uo8":{"w":{"تساعد الطلاب في التقويم الذاتي وتطوير فهمهم لقدراتهم وإمكاناتهم في التعلّم.":"التقويم الذاتي يمارسه الطالب على عمله بمحكات معدة، أما الطرق هنا فيستعملها المعلم ليراقب تحصيلهم ويعدّل تدريسه.","تقلل من مستويات القلق لدى الطلاب من عملية التقويم الختامي.":"تقليل القلق فائدة ثانوية، والفائدة الأساسية للتقويم أثناء الوحدة مراقبة التقدم وتعديل التدريس.","تضمن للمعلم الحصول على بيانات أكثر لأداء الطلبة يساعده في الحكم المناسب.":"جمع البيانات لإصدار حكم وظيفة التقويم الختامي نهاية الوحدة، أما التقويم أثناء الوحدة فغرضه تعديل التدريس لا الحكم."},"e":"هذا تقويم تكويني (بنائي) وظيفته الأساسية مراقبة التقدم وتعديل التدريس أثناء الوحدة. (المعيار القديم 7.2)"},"o1dmvtbb":{"w":{"صياغة الأسئلة.":"الأسئلة تُصاغ في ضوء جدول المواصفات، فهي تأتي بعد تحديد الأهداف وتحليل المحتوى وبناء الجدول لا قبلها.","إعداد تعليمات الاختبار.":"التعليمات تُكتب بعد صياغة الفقرات لأنها تصف زمن الإجابة وطريقتها ودرجة كل سؤال، فلا تكون الخطوة الأولى.","تحليل محتوى المادة الدراسية المستهدفة.":"تحليل المحتوى خطوة مبكرة فعلاً لكنه الثانية، فهو يأتي بعد تحديد الأهداف التي سيقيسها الاختبار."},"e":"بناء الاختبار يبدأ بتحديد الأهداف التي سيقيسها، ثم تحليل المحتوى، ثم جدول المواصفات، ثم صياغة الفقرات والتعليمات. (المعيار القديم 7.1، صعوبة 0.593)"},"o1dfqhwq":{"w":{"اختبار تشخيصي تقدّمه إدارة التربية والتعليم.":"التشخيصي غرضه كشف نقاط القوة والضعف، واختبار الإدارة لا يطابق ما درّسه المعلم لطلابه في الشهر الثاني تحديداً.","اختبار الإنجاز المقنن الذي توفره الوزارة.":"المقنن يعده متخصصون بظروف ومعايير موحدة لمحتوى عام، فلا يطابق ما درّسه المعلم لطلابه في الشهر الثاني.","اختبارات يومية قصيرة يتضمنها كتاب الطالب.":"الاختبارات اليومية القصيرة تتابع أجزاء صغيرة من الدروس، فلا تغطي التمكن من محتوى الفترة كله كما يغطيه اختبار المعلم."},"e":"قياس التمكن من محتوى درّسه المعلم في فترة محددة يناسبه اختبار من إعداد المعلم نفسه لأنه مطابق لما دُرّس. (المعيار القديم 7.2، صعوبة 0.436)"},"o19v78sx":{"w":{"يحدد مهاراته التقنية التي يحتاج إليها.":"التعبئة الإلكترونية وسيلة لأداء المهمة لا هدفها، فالأسلوب يقيس توظيف ما تعلمه في موقف توظيف حقيقي لا حصر مهاراته التقنية.","يطبق إستراتيجيات ما وراء المعرفة.":"ما وراء المعرفة وعي الطالب بتفكيره وتخطيطه له ومراقبته، وليس هو ما يقيسه هذا الأسلوب الذي يضعه في موقف حقيقي يطبق فيه ما تعلمه.","يحدد أهدافه التعليمية التي يرغب في تحقيقها من المادة.":"تحديد الطالب أهدافه من المادة تخطيط ذاتي للتعلم، أما هذه المهمة فتضعه في موقف حقيقي يطبق فيه ما تعلمه."},"e":"هذا تقويم أصيل يضع الطالب في مهمة واقعية، فميزته تطبيق التعلم النظري في الواقع. (المعيار القديم 7.2، صعوبة 0.289)"},"o16sc5uu":{"w":{"مشاركة الطالب زملاءه في عملية التقويم.":"مشاركة الزملاء في التقويم هي تقويم الأقران، والطالب هنا يراجع أعماله هو وحده ثم يعيدها، فالغاية تأمله في تقدمه.","إتاحة النقاش بين الطلاب للمقارنة بين أعمالهم.":"المقارنة بين الطلاب لم تُطلب هنا، فكل طالب يراجع أعماله السابقة ليرى تقدمه هو، وهذه غاية ملف الإنجاز.","تقويم مستوى الطلاب في المحافظة على مقتنياتهم.":"إعادة الحقيبة إلى مكانها إجراء تنظيمي، وملف الإنجاز ليس للأرشفة أو حفظ المقتنيات بل للتأمل الذاتي ومتابعة التقدم."},"e":"هذا ملف الإنجاز (البورتفوليو) وغايته التأمل الذاتي في التقدم عبر مراجعة الأعمال دوريًا. (المعيار القديم 7.2، صعوبة 0.651)"},"139sowy":{"w":{"التنبؤي":"الصدق التنبؤي نوع من صدق المحك يقارن الدرجات بمحك يُجمع في المستقبل، ولا يبحث في كفاية عدد الأسئلة لتمثيل المادة.","الظاهري":"الصدق الظاهري يخص مظهر الاختبار وشكله العام، ولا يفحص هل يكفي عدد الأسئلة لتمثيل المادة الدراسية.","التلازمي":"الصدق التلازمي نوع من صدق المحك يقارن الدرجات بمحك يُجمع في الوقت نفسه، ولا يتعلق بكفاية عدد الأسئلة."},"e":"الصدق العيني وجه من صدق المحتوى يخص كفاية العينة من الفقرات."},"1jd4oe7":{"w":{"فقراته تمثل المحتوى تمثيلاً كاملاً":"تمثيل الفقرات للمحتوى هو صدق المحتوى ويُتحقق منه بجدول المواصفات وتحكيم المختصين، أما الظاهري فمظهر الاختبار فقط.","درجاته ترتبط بمحك مستقبلي":"ارتباط الدرجات بمحك يُجمع في المستقبل هو الصدق التنبؤي من صدق المحك، لا الصدق الظاهري الذي يخص الشكل.","فقراته تنسجم مع الإطار النظري للسمة":"الاتساق مع النظرية المفسرة للسمة هو صدق البناء ويُتحقق منه بالتحليل العاملي، أما الظاهري فمظهر فقط."},"e":"الصدق الظاهري يتعلق بالشكل العام وهو أضعف الأنواع."},"1ud9h60":{"w":{"0.81":"0.81 هو معامل الثبات نفسه المعطى في السؤال، والصدق الذاتي جذره التربيعي: جذر 0.81 = 0.90.","0.66":"0.66 هو مربع الثبات تقريباً (0.81 × 0.81 = 0.6561)، والمطلوب الجذر لا المربع: جذر 0.81 = 0.90.","0.19":"0.19 هو الفرق 1 − 0.81، والصدق الذاتي لا يُحسب بالطرح بل بالجذر التربيعي للثبات: جذر 0.81 = 0.90."},"e":"الصدق الذاتي = الجذر التربيعي لمعامل الثبات = جذر 0.81 = 0.9."},"rrtr2s":{"w":{"المحتوى بدقة أكبر":"اللغة الصعبة حالت دون إظهار الطلاب ما يعرفونه، فالدرجة تعكس فهم الصياغة لا المحتوى، فتقل دقة القياس ولا تزيد.","مستويات التفكير العليا":"مستويات التفكير العليا تُقاس بمهام كالتحليل والتقويم، وصعوبة الفقرات هنا مصدرها اللغة لا عمق التفكير المطلوب.","المحتوى دون أي تأثر":"عجز كثير من الطلاب عن فهم المطلوب يعني أن الدرجة تأثرت باللغة، وغموض الصياغة من عوامل ضعف الصدق."}},"1lp1zfs":{"w":{"صدق المحتوى":"صدق المحتوى يتحقق بجدول المواصفات وتحكيم المختصين، لا بحساب ارتباط الدرجات بدرجات اختبار آخر.","الصدق الظاهري":"الصدق الظاهري حكم على مظهر الاختبار وعنوانه وتعليماته، ولا يُحسب له معامل ارتباط مع اختبار آخر.","الصدق المنطقي":"الصدق المنطقي قريب من صدق المحتوى ويُقدَّر بالحكم والتحليل، لا بحساب معامل ارتباط مع درجات اختبار آخر."},"e":"صدق المحك بنوعيه (التلازمي والتنبؤي) يُحسب بمعامل ارتباط مع محك خارجي."},"zv6e63":{"w":{"غموض صياغة الأسئلة":"الغموض يُضعف الصدق فعلاً، لأن الطالب قد يخطئ لعدم فهم السؤال لا لنقص قدرته، فليس هو العامل المطلوب.","تطبيق الاختبار على فئة غير التي أُعد لها":"الصدق يكون لفئة معينة، فتطبيق الاختبار على فئة أخرى يُضعفه فعلاً كما في الدرس، فليس هو الاستثناء.","وجود تلميحات في الصياغة تكشف الإجابة":"التلميحات تُضعف الصدق فعلاً، لأنها تتيح الإجابة دون امتلاك المعرفة المقيسة، فليست هي العامل المطلوب."},"e":"تنويع المستويات يزيد تمثيل الأهداف فيرفع الصدق."},"y3rnz0":{"w":{"كودر ريتشاردسون":"معادلة كودر ريتشاردسون للفقرات الثنائية (صح أو خطأ)، ومقياس ليكرت هنا خماسي التدريج فيناسبه كرونباخ ألفا.","الصدق الذاتي":"الصدق الذاتي جذر معامل الثبات ويُحسب بعد معرفة الثبات، فليس طريقة لحساب ثبات مقياس ليكرت.","معامل الصعوبة":"معامل الصعوبة مؤشر لتحليل كل فقرة على حدة، ولا يقيس اتساق درجات المقياس كله أي ثباته."},"e":"الفقرات متعددة التدريج تحتاج كرونباخ ألفا."},"1am4qtv":{"w":{"6":"لو كان الخطأ 6 لكان جذر (1 − الثبات) = 0.6 والثبات 0.64 لا 0.84، والصحيح 10 × جذر 0.16 = 4.","8.4":"8.4 ناتج ضرب الانحراف في الثبات نفسه (10 × 0.84)، والصحيح ضربه في جذر (1 − 0.84) وهو 0.4، فالخطأ 4.","1.6":"1.6 ناتج ضرب الانحراف في (1 − 0.84) = 0.16 دون أخذ الجذر، وجذر 0.16 = 0.4، فالخطأ 10 × 0.4 = 4."}},"f68gxr":{"w":{"يرتفع":"العلاقة بين الخطأ المعياري والثبات عكسية، فكبر الخطأ يعني تذبذباً أكبر للدرجة الملاحظة حول الحقيقية، أي ثباتاً أقل.","لا يتأثر":"الخطأ المعياري يُحسب من الثبات نفسه: الانحراف × جذر (1 − الثبات)، فكبره مع بقاء الانحراف يعني ثباتاً أقل.","يساوي الصفر دائماً":"الثبات يساوي صفراً فقط إذا بلغ الخطأ المعياري الانحراف المعياري نفسه، أما كبر الخطأ عموماً فيخفض الثبات تدريجياً بين 0 و 1."}},"hqddft":{"w":{"ينخفض بسبب نسيان الطلاب":"أثر النسيان والتغير يظهر حين يطول الفاصل بين التطبيقين، أما يوم واحد فيجعل الذاكرة ترفع الاتفاق بين الدرجتين.","لا يتأثر بالفاصل الزمني":"ثبات الإعادة يتأثر بطول الفاصل، فقصره يرفعه زيفاً بالتذكر، ولذلك يُفضَّل فاصل مناسب نحو أسبوعين.","يصبح سالباً":"معامل الثبات يقع بين 0 و 1، والتذكر هنا يجعل الإجابتين متشابهتين فيرفع الاتفاق بين الدرجتين ولا يخفضه."}},"1no6fy6":{"w":{"الشمول":"الشمول يحسّن تمثيل الاختبار للمحتوى، لكنه خاصية مساعدة لا تُعد شرطاً منطقياً للصدق كالثبات الذي بدونه لا صدق.","سهولة التطبيق":"سهولة التطبيق خاصية عملية تخص الإجراء والوقت، ولا تتوقف عليها صحة قياس الاختبار لما وُضع له، فليست شرطاً للصدق.","طول الاختبار":"طول الاختبار من عوامل رفع الثبات، لكنه عامل مساعد لا شرط، أما الشرط الضروري غير الكافي فهو الثبات نفسه."},"e":"بلا ثبات لا صدق، لكن الثبات وحده لا يضمن الصدق."},"fgmbyu":{"w":{"زيادة عدد الفقرات":"زيادة عدد الفقرات تطيل الاختبار، والطول من عوامل ارتفاع الثبات لا انخفاضه كما في الدرس.","تباين قدرات العينة":"تباين قدرات العينة يرفع الثبات، أما العينة شديدة التجانس فهي التي تخفضه كما في الدرس.","صعوبة الفقرات المتوسطة":"توسط الصعوبة من عوامل ارتفاع الثبات في الدرس، لأنه يزيد تباين الدرجات بين الطلاب، فلا يخفضه."},"e":"الغموض وتفاوت الظروف يدخلان أخطاء عشوائية في الدرجات فيقل الاتساق."},"14dp3lo":{"w":{"0.25":"لو كان التمييز 0.25 لكان الفرق بين المجموعتين نحو 7 طلاب (0.25 × 27 = 6.75)، والفرق هنا 15، فالتمييز 15 ÷ 27 ≈ 0.56.","0.46":"0.46 هو معامل الصعوبة لا التمييز: (20 + 5) ÷ 54 ≈ 0.46، أما التمييز فالفرق 15 ÷ 27 ≈ 0.56.","0.15":"0.15 ناتج قسمة الفرق 15 على العدد الكلي 100، والقسمة تكون على عدد إحدى المجموعتين: 15 ÷ 27 ≈ 0.56."}},"j4d3fl":{"w":{"المشتت ممتاز ويؤدي وظيفته":"المشتت الفعال تختاره الفئة الدنيا أكثر من العليا، وهنا انجذبت إليه العليا أكثر، فهو عكس الفعال.","الفقرة سهلة جداً":"سهولة الفقرة تُعرف بارتفاع نسبة المصيبين، وانجذاب المتفوقين إلى بديل خاطئ يدل على خلل في البديل لا على السهولة.","الفئة العليا لم تذاكر":"الفئة العليا هي الأعلى درجة في الاختبار كله، فلا قرينة على قلة مذاكرتها، وانجذابها لبديل بعينه يشير إلى غموض فيه."}},"jnaxi5":{"w":{"من 0.90 إلى 1.00":"معامل 0.90 فأعلى يعني أن الجميع تقريباً أصابوا، فالفقرة شديدة السهولة فوق 0.80 ولا تميز بين الطلاب جيداً.","من صفر إلى 0.10":"معامل يقل عن 0.10 يعني أن قلة نادرة أصابت، فالفقرة شديدة الصعوبة دون 0.20 ولا تميز جيداً.","من 0.95 فأعلى":"معامل 0.95 فأعلى يعني أن كل الطلاب تقريباً أصابوا، والفقرة التي يجيبها الجميع تمييزها صفر."},"e":"المدى الشائع في المراجع من 0.20 إلى 0.80، والمثالي قرب 0.50، ودليل الاختبارات 2025 ينصح بالاحتفاظ بالفقرة إذا وقع معاملها بين 30% و70%."},"j01bdu":{"w":{"0.40":"0.40 هو معامل التمييز للفقرة نفسها: (18 − 8) ÷ 25، أما الصعوبة فمجموع المصيبين 26 ÷ 50 = 0.52.","0.72":"0.72 نسبة المصيبين في المجموعة العليا وحدها (18 ÷ 25)، والصعوبة تجمع المجموعتين: 26 ÷ 50 = 0.52.","0.32":"0.32 نسبة المصيبين في المجموعة الدنيا وحدها (8 ÷ 25)، والصعوبة تجمع المجموعتين: (18 + 8) ÷ 50 = 0.52."},"e":"الصعوبة = (18 + 8) ÷ (25 + 25) = 26 ÷ 50 = 0.52، فقرة متوسطة."},"zxv0kz":{"w":{"65%":"65% نسبة المصيبين نفسها، لأن معامل السهولة نسبة من أجابوا صحيحاً، والمطلوب المخطئون: 100% − 65% = 35%.","0.65 من طالب":"معامل السهولة نسبة من مجموع الطلاب لا كسر من طالب واحد، فالمعامل 0.65 يعني أن 65% أصابوا و 35% أخطؤوا.","50%":"50% تكون نسبة المخطئين لو أصاب نصف الطلاب فقط، والمصيبون هنا 65%، فالمخطئون 100% − 65% = 35%."}},"1nfnlzg":{"w":{"أعلى 50% وأدنى 50%":"تقسيم الصف نصفين يُلجأ إليه في الصفوف الصغيرة، أما الصف الكبير فتُؤخذ منه 27% من كل طرف.","أول 10 أوراق وآخر 10 أوراق بترتيب التسليم":"ترتيب التسليم لا علاقة له بمستوى الطالب، والمجموعتان الطرفيتان تُحددان بعد ترتيب الأوراق تنازلياً بالدرجة.","الأوراق كلها دون ترتيب":"طريقة المجموعتين تقارن العليا بالدنيا، ولا تتحدد المجموعتان إلا بعد ترتيب الأوراق بالدرجة الكلية."},"e":"النسبة المعتمدة للمجموعتين الطرفيتين 27% من كل طرف بعد الترتيب التنازلي بالدرجة."},"1cz7rxb":{"w":{"2":"2 هو الجذر التربيعي للانحراف المعياري، والتباين مربع الانحراف لا جذره: 4 × 4 = 16.","4":"4 هو الانحراف المعياري نفسه المعطى في السؤال، والتباين مربعه: 4 × 4 = 16.","8":"8 ضعف الانحراف المعياري (4 × 2)، والتباين مربعه أي ضربه في نفسه: 4 × 4 = 16."},"e":"التباين = مربع الانحراف المعياري = 4 × 4 = 16."},"wremyb":{"w":{"المتوسط الحسابي":"المتوسط يتطلب جمع القيم وقسمتها على عددها، والأنماط التعليمية فئات اسمية لا تُجمع، فلا معنى لمتوسطها.","الوسيط":"الوسيط القيمة الوسطى بعد الترتيب، والأنماط التعليمية فئات اسمية لا ترتيب بينها، فلا يمكن تحديد وسيطها.","التباين":"التباين مقياس تشتت لا نزعة مركزية، ويُحسب من انحرافات القيم عن المتوسط، فلا يصلح للبيانات الاسمية."}},"1s3srg7":{"w":{"الرسم الدائري":"الرسم الدائري يعرض نسب الأجزاء من كل واحد، ولا يبين تتابع فئات الدرجات وشكل توزيعها كالمدرج.","الخط البياني الزمني":"الخط البياني يعرض تغير قيمة عبر الزمن، والمطلوب هنا تكرار الدرجات في فئات متتالية لا تغيرها عبر الوقت.","الرسم الشجري":"الرسم الشجري يعرض التفرعات والتصنيفات الهرمية، ولا يعرض تكرار الدرجات في فئات متتالية."},"e":"المدرج التكراري يعرض تكرار كل فئة من الدرجات ويبين شكل التوزيع."},"1dwxgp2":{"w":{"9":"9 هي القيمة الرابعة بعد الترتيب 3، 5، 7، 9، 12، والوسيط القيمة الثالثة في الوسط وهي 7.","12":"12 أكبر قيمة وتقع في الطرف بعد الترتيب، والوسيط القيمة الوسطى الثالثة من القيم الخمس وهي 7.","7.2":"7.2 هو المتوسط الحسابي (36 ÷ 5)، أما الوسيط فالقيمة الوسطى بعد الترتيب وهي 7."},"e":"نرتب: 3، 5، 7، 9، 12؛ العدد فردي (5 قيم) فالوسيط القيمة الوسطى الثالثة = 7."},"177y8xm":{"w":{"الانحراف المعياري":"الانحراف المعياري يتأثر بالمتطرفة أيضاً لكنه يُحسب من كل القيم، أما المدى فتحدده القيمتان الطرفيتان وحدهما فتغيره قيمة واحدة.","التباين":"التباين يُحسب من انحرافات كل القيم عن المتوسط، بينما يتحدد المدى بالقيمتين الطرفيتين وحدهما، فهو الأشد تأثراً بقيمة متطرفة.","الانحراف الربيعي":"الانحراف الربيعي يعتمد على الربيعين الأول والثالث فيستبعد ربع القيم من كل طرف، فهو من أقل المقاييس تأثراً بالمتطرفة."},"e":"المدى يعتمد على قيمتين فقط هما الطرفان، فأي قيمة متطرفة واحدة تغيره كلياً."},"1r7oty7":{"w":{"5%":"5% مجموع الطرفين معاً خارج ± انحرافين، ونصفها فقط يقع فوق 70، أي نحو 2.5%.","16%":"16% نسبة من تزيد درجاتهم على 65 أي انحراف واحد فوق المتوسط، و 70 تبعد انحرافين فالنسبة نحو 2.5%.","34%":"34% نسبة الدرجات بين المتوسط 60 والدرجة 65، أما ما فوق 70 أي انحرافين فوق المتوسط فنحو 2.5% فقط."}},"13fmo0p":{"w":{"التوزيع ملتوٍ التواءً سالباً والاختبار سهل":"في الالتواء السالب يكون المتوسط أصغر من الوسيط، وهنا المتوسط 45 أكبر من الوسيط 35، فالالتواء موجب والاختبار صعب.","التوزيع اعتدالي":"في التوزيع الاعتدالي يتساوى المتوسط والوسيط والمنوال، وهي هنا مختلفة: 45 و 35 و 30.","الاختبار متوسط الصعوبة تماماً":"المتوسط أكبر من الوسيط والمنوال، فأغلب الدرجات منخفضة عند 30 وقلة عالية ترفع المتوسط، وهذه صورة الاختبار الصعب."}},"1xpfgtt":{"w":{"49":"49 ناتج 50 − 1 دون ضرب ز في 10، والصحيح 50 + 10 × (−1) = 40.","60":"60 هي الدرجة التائية لمن ز = +1 فوق المتوسط، أما ز = −1 فدون المتوسط: 50 − 10 = 40.","−10":"−10 ناتج 10 × ز وحده دون إضافة 50، والدرجة التائية تتخلص من السالب: 50 − 10 = 40."}},"6rrvhf":{"w":{"50 و10":"50 و 10 هما متوسط الدرجة التائية وانحرافها، أما الدرجة المعيارية ز فمتوسطها صفر وانحرافها 1.","100 و15":"100 و 15 متوسط نسبة الذكاء الانحرافية وانحرافها، أما الدرجة المعيارية ز فمتوسطها صفر وانحرافها 1.","1 وصفر":"هذا عكس الترتيب الصحيح، فمتوسط ز صفر وانحرافها 1، والانحراف صفر يعني درجات متساوية لا توزيعاً معيارياً."},"e":"ز توزيع متوسطه صفر وانحرافه 1."},"m4yle1":{"w":{"الطلاب المتفوقون في القراءة يميلون للتفوق في العلوم":"الارتباط الطردي القوي يعني أن من يرتفع في القراءة يرتفع غالباً في العلوم، فهذا استنتاج مشروع لا الاستثناء.","العلاقة بين المتغيرين طردية قوية":"الإشارة الموجبة تدل على علاقة طردية، والقيمة 0.85 فوق 0.7 فهي قوية، فهذا استنتاج صحيح لا الاستثناء.","يمكن التنبؤ بدرجة العلوم من درجة القراءة بدرجة جيدة":"الارتباط القوي يسمح بالتنبؤ بأحد المتغيرين من الآخر وإن لم يثبت السببية، فهذا استنتاج مشروع لا الاستثناء."},"e":"الارتباط يصف العلاقة ولا يثبت السببية؛ قد يكون وراء الاثنين عامل ثالث كالقدرة العامة أو الدافعية."},"ybas4h":{"w":{"58":"58 هي الدرجة الخام لمن ز = 1 فقط (50 + 8)، أما ز = 1.5 فتضيف 1.5 × 8 = 12، فالدرجة 62.","65":"لو كانت الدرجة 65 لكانت ز = (65 − 50) ÷ 8 ≈ 1.88 لا 1.5، والصحيح 50 + 1.5 × 8 = 62.","51.5":"51.5 ناتج إضافة ز إلى المتوسط دون ضربها في الانحراف، والصحيح 50 + 1.5 × 8 = 62."}},"1ta8szf":{"w":{"أن 95% من الطلاب نجحوا في الاختبارين":"معامل الارتباط يصف قوة العلاقة بين درجات الطلاب في الاختبارين، ولا يعبر عن نسبة الناجحين فيهما.","أن معامل صعوبة الاختبارين 0.95":"معامل الصعوبة نسبة المصيبين في الفقرة، أما 0.95 هنا فقوة العلاقة بين درجات الاختبارين لا مستوى صعوبتهما.","أن الاختبارين متطابقان في الأسئلة":"قد يرتبط اختباران مختلفا الأسئلة ارتباطاً قوياً إذا رتّبا الطلاب ترتيباً متقارباً، فالارتباط لا يدل على تطابق المحتوى."},"e":"الارتباط 0.95 يعني أن ترتيب الطلاب في الاختبارين متقارب جداً."},"umxasg":{"w":{"إعادة الاختبار في الأسبوع التالي":"إعادة الاختبار قبل معرفة سبب التدني لا تعالج السبب، فالخطوة الأولى تشخيص الفقرات والمهارات ثم تعديل التدريس.","توبيخ الطلاب على إهمالهم":"التوبيخ يفترض أن السبب إهمال الطلاب دون تحليل، وقد يكون في الفقرات أو التدريس، والنتائج لا تُستخدم أداة عقاب.","تخفيض مستوى الاختبار القادم":"تسهيل الاختبار القادم يخفي الضعف ولا يعالجه، والمطلوب أولاً تحديد مواطن الضعف ثم تعديل التدريس."},"e":"التدني العام يستدعي تشخيص الأسباب أولاً (الفقرات، المهارات، طريقة التدريس) ثم التعديل."},"15e75a6":{"w":{"رصد الدرجات في النظام فقط":"رصد الدرجات توثيق للنتائج، والتحليل يتجاوزه إلى كشف الفقرات الضعيفة والمهارات غير المتقنة لتعديل التدريس.","ترتيب الطلاب لإعلان المتفوقين":"ترتيب الطلاب ناتج ثانوي للنتائج، أما الغرض الأساسي من التحليل فكشف مواطن القوة والضعف لتعديل الخطة والتدريس.","تبرير الدرجات أمام الإدارة":"تبرير الدرجات استعمال إداري ثانوي، والتحليل يخدم أساساً تعديل الخطة بحسب ما أتقنه الطلاب وما لم يتقنوه."},"e":"التحليل يكشف الفقرات الضعيفة والمهارات غير المتقنة فيوجه قرارات التدريس."},"1t6goum":{"w":{"تتضمن عبارات ثناء عامة فقط":"الثناء العام لا يحدد للطالب ما أتقنه ولا ما يحسّنه، والتغذية الراجعة الفعالة محددة ووصفية.","تقتصر على نقاط الضعف":"الاقتصار على الضعف يحبط الطالب، والتغذية الراجعة تذكر نقاط القوة أولاً ثم ما يحتاج تحسيناً.","تكون مطولة تغطي كل جوانب الإجابة":"الإطالة تشتت الطالب عن الرسالة الأساسية، والأنفع ملاحظة موجزة محددة يفهم منها ما أتقنه وما يحتاج تحسينه."},"e":"الوضوح والإيجاز والتحديد يجعل الطالب يفهم ما يحتاج تحسينه ويطبقه."},"1idvg7i":{"w":{"رفع درجات الطلاب الضعاف":"حساب معاملات الفقرات يحلل جودة الأسئلة ولا يغير درجات الطلاب، فرفع الدرجات ليس من وظائفه.","إلغاء الحاجة إلى جدول المواصفات":"جدول المواصفات يخطط للاختبار قبل بنائه ليمثل المحتوى، وتحليل الفقرات يأتي بعد التطبيق، فلا يغني عنه.","تقليل عدد الأسئلة في الاختبار":"قد تُحذف بعض الفقرات الضعيفة بعد التحليل، لكن الغاية تحسين جودة الاختبار لا تقليل عدد أسئلته."},"e":"تحليل الفقرات بالتقنية يكشف الفقرات التي تحتاج تعديلاً أو حذفاً فتتحسن جودة الاختبار."},"1se6uwl":{"w":{"إعلان درجته أمام الصف لحثه على الاجتهاد":"إعلان الدرجة أمام الصف يحرج الطالب ويخالف سرية النتائج، فنتيجته تخصه وولي أمره والقائمين على تعليمه.","مقارنة درجته بدرجة المتفوق الأول":"المقارنة بالمتفوق تحبط الطالب، والتغذية الراجعة تركز على أدائه هو في المهمة وما يحتاج تحسينه لا على غيره.","الاكتفاء بإبلاغه الدرجة دون تعليق":"الدرجة وحدها لا توجه الطالب، فهو يحتاج أن يعرف ما أتقنه وما الخطوات المحددة لتحسين ما ضعف فيه."},"e":"التغذية الراجعة الداعمة تبدأ بنقاط القوة ثم توجه إلى خطوات تحسين محددة."},"vxq2zd":{"w":{"الاسمي":"الاسمي يصنف ويسمي فقط دون ترتيب كأرقام اللاعبين، والمعلم هنا رتب طلابه أولاً وثانياً وثالثاً.","الفتري (المسافات المتساوية)":"الفتري يتطلب مسافات متساوية بين القيم، والمعلم لم يذكر الفروق بين الدرجات، فلا نعرف كم يزيد الأول على الثاني.","النسبي":"النسبي يضيف إلى المسافات المتساوية صفراً حقيقياً كالوزن، والترتيب هنا لا يبين مسافات ولا صفراً."}},"3o4sho":{"w":{"الفتري، فمسافاته متساوية":"الفتري مسافاته متساوية لكن صفره اعتباري، فلا يجيز عبارة الضعف، كما لا نقول إن 40 درجة مئوية ضعف 20.","الرتبي، فهو يرتب الحقائب":"الرتبي يرتب دون مسافات متساوية ولا صفر حقيقي، فلا يجيز القول إن حقيبة تزن ضعف أخرى.","الاسمي، فلكل حقيبة رقم يميزها":"الاسمي يصنف ويسمي فقط كأرقام التمييز، والوزن مقدار بالكيلوجرام صفره يعني انعدام الوزن، فهو نسبي يجيز القول بالضعف."},"e":"لا تصح عبارة «ضعف» أو «نصف» إلا في المستوى النسبي، لأن له صفراً حقيقياً يعني انعدام الصفة، كالوزن والطول والزمن."},"1e0h9s4":{"w":{"لا يعرف شيئاً عن الكسور، فالصفر انعدام للمعرفة":"صفر الاختبار التحصيلي اعتباري لأن درجاته من المستوى الفتري، فلا يعني انعدام المعرفة بالكسور كلها.","درجته لا تقارن بدرجات زملائه لأنها صفر":"الصفر درجة كغيرها تُقارن بدرجات الزملاء وتُرتب معها، فهو أدنى درجة في هذا الاختبار.","درجته اسمية فلا تُرتب ولا تُجمع مع غيرها":"درجات الاختبار التحصيلي تُعامل معاملة المستوى الفتري لا الاسمي، فهي تُرتب وتُجمع ويُحسب لها متوسط."},"e":"درجات الاختبارات التحصيلية تعامل معاملة المستوى الفتري، وصفرها اعتباري: يعني أن الطالب لم ينجح في فقرات هذا الاختبار بعينه، لا انعدام المعرفة كلها. ولهذا لا نقول إن درجة 2 ضعف درجة 1 في التحصيل."},"1vgak21":{"w":{"الرتبي":"الرتبي يدل على ترتيب كالأول والثاني، ورقم القميص لا يعني أن اللاعب رقم 10 متقدم على رقم 2.","الفتري":"الفتري يقيس مقداراً بمسافات متساوية كدرجات الاختبار، ورقم القميص لا يدل على مقدار، ولا معنى للفرق بين رقمين.","النسبي":"النسبي يقيس مقداراً له صفر حقيقي كالوزن، وأرقام القمصان مجرد أسماء تميز اللاعبين فلا تقيس شيئاً."},"e":"الرقم هنا اسم يميز اللاعب، ولا يدل على مقدار ولا على تفوق؛ فاللاعب رقم 10 ليس أفضل من رقم 2، ولا معنى لجمع الأرقام. ومثله رقم الهوية ورقم الجوال."},"1wxplow":{"w":{"إعداد خطة علاجية فردية لطالبين أو ثلاثة فقط":"الخطة الفردية تناسب ضعفاً لدى قلة، أما إتقان 35% فقط فيعني أن أغلب الصف لم يتقن المعيار.","الانتقال إلى الوحدة التالية لأن معظم المعايير متقنة":"إتقان بقية المعايير لا يعوض ضعف هذا المعيار، إذ لم يتقنه 65% من الصف، فيحتاجون إعادة تدريسه قبل الانتقال.","حذف أسئلة هذا المعيار من الاختبارات القادمة":"حذف الأسئلة يخفي الضعف ولا يعالجه، والمؤشر يدعو إلى تعديل التدريس نفسه ثم إعادة تقويم المعيار."},"e":"انخفاض الإتقان لدى أغلب الصف في معيار بعينه مؤشر على حاجة التدريس نفسه إلى التعديل."},"175zkek":{"w":{"مرة واحدة في نهاية العام الدراسي، مباشرة في النظام الرقمي دون سجل يومي":"الإجراءات تنص على تدوين يومي في سجل المتابعة، ثم رصد الخلاصة في النظام الرقمي نهاية الفترة لا نهاية العام.","في دفتر خاص لا يطلع عليه أحد":"التدوين يكون في سجل متابعة تقويم الطالب، ثم تُرصد خلاصته في النظام الرقمي موثقة بشواهد في ملف الإنجاز.","عند طلب ولي الأمر فقط":"التدوين إجراء يومي منتظم لا يرتبط بطلب ولي الأمر، وخلاصته تُرصد في النظام الرقمي نهاية الفترة."}},"1akwrxe":{"w":{"ترتيب الطلاب أبجدياً حسب أسمائهم":"الترتيب الأبجدي ينظم الأسماء فقط، ولا يميز الدرجات التي تقع دون حد الإتقان في كل معيار.","تغيير نوع الخط وحجمه في جميع أعمدة الدرجات":"تغيير الخط وحجمه يشمل كل الخلايا بلا شرط، فلا يُبرز من لم يبلغ مستوى الإتقان دون غيره.","دمج الخلايا في رأس الجدول وتلوينه":"دمج خلايا الرأس وتلوينه تنسيق لعنوان الجدول، ولا يتعامل مع درجات الطلاب ولا يميز ما دون حد الإتقان."}},"1wtl0p0":{"w":{"المدخل الاجتماعي":"المدخل الاجتماعي يقوم على التفاعل بين المتعلمين ونمذجة السلوك (التعلم التعاوني، لعب الأدوار)، والنقاش هنا خطوة داخل وحدة محورها البيئة المحلية، فليس هو ما يميز الموقف.","المدخل الإنساني":"المدخل الإنساني يركز على حاجات المتعلم ومشاعره وتحقيق ذاته، ولا يجعل بيئة الطالب ومشكلاتها منطلق الدرس.","المدخل السلوكي":"المدخل السلوكي يقوم على تحديد السلوك المطلوب وتعزيزه خطوة خطوة، ولا علاقة له بالانطلاق من بيئة المتعلم."}}};
window.QBE = {"27zr80":"الفاقد التعليمي هو ما يخسره النظام بسبب الرسوب والتسرب وله آثار اجتماعية واقتصادية. التأخر الدراسي حالة طالب لا نظام.","q8s8cz":"المعيار عبارة عامة عمّا يجب أن يعرفه المعلم ويؤديه، والمؤشر دليل قابل للقياس على تحققه. الهدف السلوكي يخص تعلم الطالب.","y67t7y":"الإجازة الاضطرارية تُمنح للظروف الطارئة بحد لا يتجاوز خمسة أيام في السنة. المرضية تتطلب تقريراً طبياً، والاستثنائية بلا راتب لظروف خاصة طويلة.","11a4fh3":"مخاطبة الإدارة والجهات الرسمية تكون بخطاب إداري بعناصره الرسمية ليُوثق ويُتابع. الأساليب الودية والشفهية لا تناسب الطلب الرسمي.","pe12fw":"School Circle منصة تواصل وتشارك ملفات بين أطراف العملية التعليمية. إكسل للجداول، وأكسس لقواعد البيانات، وكانفا للتصميم.","n4yooq":"رمي الأشياء وتجريبها في الطفولة المبكرة استكشاف نمائي طبيعي لخصائص الأشياء. العدوان مقصود للإيذاء، وفرط الحركة اضطراب، والإحيائية إسناد الحياة للجماد.","1uvto8z":"بياجيه يرى أن الطفل لا يتعلم ما يتجاوز بنيته المعرفية، فالتعليم يُبنى على المرحلة الحالية. التسريع فكرة برونر، والتكرار والتلقين سلوكية.","1ah7m8l":"النضج تغيرات داخلية لا إرادية لا يسرّعها التدريب، وهو شرط لحدوث التعلم (لا يتعلم الطفل الكتابة قبل نضج عضلاته)، أما التعلم فيحتاج خبرة وممارسة.","y1c81p":"التراكمية والتتابع تعنيان أن المراحل مترابطة. النمو متغير السرعة ومختلف بين الجوانب وينتج عن تفاعل الوراثة والبيئة.","1dpme7l":"النمو التكويني (البنائي) زيادة في الحجم والشكل، أما الوظيفي فتحسن في أداء الأعضاء والقدرات.","pfzus7":"أحلام اليقظة والاستقلال والانتماء للرفاق سمات المراهقة المبكرة (المتوسطة). الابتدائية تتسم بحب الاستطلاع والتطبيع الاجتماعي.","1gs2n9a":"سن المدرسة الابتدائية (6–12) أزمتها الاجتهاد/الكفاية مقابل الدونية/النقص. الهوية للمراهقة، والمبادرة لمرحلة الروضة، والاستقلال للطفولة المبكرة.","13fdibx":"زمن الرجع هو الفترة بين المثير وبدء الاستجابة وهو من الفروق الفردية القابلة للقياس. الاستعداد قدرة كامنة، والاتجاه والميل وجدانيان.","19zo4rx":"الإعاقة الفكرية (العقلية) تجمع انخفاض الذكاء (دون 70 تقريباً) وقصور السلوك التكيفي قبل سن 18. أما بطء التعلم فذكاء حدي (70–85)، وصعوبات التعلم مع ذكاء عادي، والتأخر الدراسي تدنٍّ في التحصيل مع ذكاء عادي غالباً لأسباب خارجية كالغياب وضعف الدافعية والظروف الأسرية.","159zls6":"الصعوبات الأولية تعود إلى اضطراب داخلي في العمليات النفسية الأساسية نفسها (الانتباه والإدراك والذاكرة)، والثانوية (التفكير واللغة الشفهية) تنشأ عنها وفق تصنيف كيرك وكالفانت. أما التدني الناتج عن سوء التعليم أو الحرمان البيئي فمستبعد أصلاً من صعوبات التعلم (محك الاستبعاد)، والأكاديمية تخص القراءة والكتابة والحساب.","14z3o17":"مايكل بست مقياس تقدير سلوكي يملؤه المعلم للكشف الأولي عن صعوبات التعلم. ستانفورد بينيه للذكاء، وليكرت للاتجاهات.","1rsz5xj":"نموذج جانييه: الموهبة استعداد فطري غير مدرَّب، والتفوق أداء متميز في مجال نتيجة التدريب؛ ولذلك كل متفوق موهوب وليس كل موهوب متفوقاً.","d3mnvm":"جاثري صاحب نظرية الاقتران الشرطي ومبدأ المرة الواحدة. بافلوف إشراط كلاسيكي بالتكرار، وثورندايك محاولة وخطأ، وسكنر إجرائي.","1j183ky":"تكوّن الارتباط من خبرة واحدة شديدة الأثر دون تكرار هو التعلم من المحاولة الواحدة (قانون المرة الواحدة) عند جثري في نظرية الاشتراط بالاقتران. قانون الأثر عند ثورندايك يقوّي الارتباط أو يضعفه تدريجياً عبر محاولات متكررة، والتعميم استجابة لمثيرات مشابهة لا للمثير نفسه، والاسترجاع التلقائي عودة استجابة منطفئة بعد فترة راحة.","12tqsah":"السلوك الإجرائي إرادي تحكمه النتائج (التعزيز)، والاستجابي لا إرادي يستدعيه المثير (كما في بافلوف).","4uciap":"يسمى وسيلياً لأن الاستجابة وسيلة للحصول على المعزز. الكلاسيكي والبسيط والاستجابي أسماء لاشتراط بافلوف.","gxui25":"فرتهايمر مؤسس الجشطلت، وكوهلر صاحب تجربة القرد والعصا (الاستبصار)، وتولمان الخرائط المعرفية، وأوزوبل التعلم ذو المعنى.","eklbrd":"التمايز التقدمي (ويسمى التدريجي) يبدأ بالأفكار الأعم ثم ينتقل إلى التفاصيل، وهو مبدأ عند أوزوبل. أما التوفيق التكاملي فربط الأفكار الجديدة بالقديمة وإزالة التعارض، والمنهج الحلزوني لبرونر، والاستبصار للجشطلت.","fcj0a5":"نموذج معالجة المعلومات (نورمان، أتكنسون وشفرن) يفسر التعلم بالانتباه والترميز والتخزين والاسترجاع كالحاسوب.","hbztig":"بافيو صاحب الترميز المزدوج (لفظي وتصوري). بياجيه نمو معرفي، وباندورا تعلم اجتماعي، وبرونر تمثيلات ثلاث.","1j5451b":"الممارسة الموزعة تعزز التخزين طويل المدى وتقلل التداخل، بخلاف الحشو المكثف الذي يُنسى سريعاً.","t6re3b":"الحتمية (التفاعل) التبادلية جوهر النظرية الاجتماعية المعرفية. التعزيز البديل مفهوم آخر لباندورا يخص ملاحظة نموذج يُعزَّز.","177j4in":"دمية بوبو تجربة باندورا في التعلم بالملاحظة. القرد لكوهلر، والكلب لبافلوف، والقط لثورندايك.","o1m8y6":"المشاركة سلوك إرادي، ولما غاب التعزيز الذي ينتظره الطالب بعدها ضعفت تدريجياً، وهذا هو الانطفاء في الاشتراط الإجرائي (سكنر). والانطفاء موجود أيضاً في الاشتراط الكلاسيكي (بافلوف)، لكنه هناك يخص استجابة لا إرادية لمثير شرطي يتكرر دون المثير الطبيعي، والموقف هنا لا مثير سابق فيه بل نتيجة غابت بعد السلوك.","i1ml9p":"التعزيز البديل عند باندورا: ملاحظة نموذج يُعزَّز يزيد احتمال تقليده. التعزيز السالب إزالة منفر عن الطالب نفسه.","meu04t":"الغرضية خاصية التوجه نحو هدف. الاستمرار والتنوع والتحسين خصائص أخرى للدافعية لكنها لا تعني التوجه نحو هدف.","14lyurs":"الدافعية تولد السلوك وتوجهه وتحدد شدته وديمومته. الذكاء والوراثة والتحصيل مفاهيم أخرى.","ixls99":"الدوافع الاجتماعية تُكتسب من التفاعل مع البيئة كالانتماء والتقدير والإنجاز، بخلاف البيولوجية الفطرية كالجوع.","19xj4jj":"جالتون رائد دراسة الوراثة والفروق ومعامل الارتباط. سبيرمان العامل العام، وجاردنر الذكاءات المتعددة، وستيرنبرغ الثلاثي.","oz0297":"مصفوفات رافن المتتابعة اختبار غير لفظي يطلب إكمال النمط الناقص في مصفوفة أشكال، فيناسب من لا يجيد اللغة. ووكسلر اللفظي هو القسم اللفظي من مقياس وكسلر (وللمقياس قسم أدائي مستقل)، وستانفورد بينيه في صورته التقليدية يعتمد كثيراً على اللغة، وليكرت مقياس للاتجاهات لا للذكاء.","1dzrij3":"الإحساس بالمشكلة ثم تحديدها وجمع البيانات وفرض الفروض واختبارها والوصول إلى نتيجة هي خطوات المنهج العلمي، فالنشاط ينمي التفكير العلمي. التفكير التأملي أعم: تأمل الموقف وتحليله وكشف المغالطات وتقديم تفسيرات وحلول مقترحة، ولا يشترط جمع بيانات واختبار فروض كما في المنهج العلمي. الحدسي إدراك مباشر بلا خطوات، والتقاربي بحث عن إجابة واحدة صحيحة.","1uggoz6":"الاستدلال وصول إلى نتيجة بناءً على أدلة كافية مربوطة بالمعرفة السابقة. الحفظ والتذكر استرجاع، والتخيل تصور.","ll28ao":"المرونة التلقائية إنتاج أفكار متنوعة من تلقاء النفس دون أن يفرض الموقف تغيير الاتجاه، وهذا ما يميزها عن المرونة التكيفية التي يغيّر فيها الفرد وجهته الذهنية لأن المشكلة تتطلب ذلك. والطلاقة اللفظية كثرة الألفاظ، والإفاضة إضافة التفاصيل إلى الفكرة.","cnggni":"الكلمات المترابطة استراتيجية لتعليم التفكير الناقد (التمييز والتصنيف). الإثارة العشوائية إبداعية.","1om6ici":"الزرقاء قبعة التنظيم والضبط واتخاذ القرار. البيضاء حقائق محايدة، والحمراء عاطفة، والخضراء ابتكار.","4pgmo3":"المعلم المفوّض يفوض المسؤولية للطلاب ويراقب. التقليدي والملقن ناقل للمعلومة، والمرشد يوجه ويرشد.","8n1cb":"المعلم المرشد يوجه المتعلم. المفوض يفوض المسؤولية، والتقليدي يلقن.","g2dc6d":"خطوات هربارت الخمس: تمهيد، عرض، ربط، استنتاج، تطبيق، تبدأ استقراءً وتُختم بتطبيق القاعدة؛ وتسميها بعض المراجع الاستدلالية (الهربارتية) وأغلبها الاستقرائية، والاستقرائية ليست بين البدائل. الاستنباطية تبدأ بالقاعدة، والحوارية أسئلة وأجوبة.","1a6k3x5":"النموذج تصور نظري لخطوات التدريس (جويس وويل)، والمدخل الفلسفة والمنطلقات، والأسلوب ما يميز المعلم شخصياً.","1s645ue":"المدخل المنطقي يعتمد التدرج المنطقي للمادة. التاريخي يتتبع تطور الفكر عبر العصور، والتكاملي يربط المادة بغيرها.","enc949":"المدخل التكاملي يربط المادة بالمواد الأخرى بعلاقات أفقية. المنطقي ترتيب داخل المادة، والضبط تحكم في السلوك، والنشاط فعل الطالب.","1bcayjm":"المشكلة موقف غامض فيه هدف يسعى إليه المتعلم ومانع يحول دونه ويتعلم أثناء تجاوزه.","g0jeko":"خطوات كلباترك: اختيار الهدف، فالتخطيط، فالتنفيذ، فالتقويم، وتضيف كتب عربية كتابة التقرير خطوة أخيرة. اختيار المشروع وتشكيل المجموعات في البداية.","1yv8avw":"دراسة الحالة تحليل موقف واقعي أو خيالي واتخاذ قرار. العرض العملي أداء المعلم أمام الطلاب، والمبرمج خطوات صغيرة.","jar6g5":"التفريدي يخصص المهام لكل طالب. الفردي مهام موحدة فردياً، والجمعي للصف كله.","azla21":"عقد التعلم اتفاق مكتوب بين المعلم والطالب على مهام ومعايير ومكافأة. الحقيبة والموديول مواد تعلم ذاتي، والخطة العلاجية إجراء للمعلم.","6yjeq4":"التعلم الموصوف للفرد برنامج فردي علاجي بعد التشخيص. التعاوني جماعي، والمبرمج عام للجميع، والمصغر لتدريب المعلمين.","1zr1n0":"المحاكاة تمثل المواقف الخطرة أو المكلفة بأمان. التدريب والممارسة لتثبيت مهارة، والألعاب للتنافس، والاستقصاء للبحث.","q2g5n7":"استراتيجيات التدريس التبادلي (بالينسكار وبراون) أربع: التنبؤ وتوليد الأسئلة والتوضيح والتلخيص؛ والترتيب الشائع في الصف يبدأ بالتنبؤ قبل القراءة، وتنمي ما وراء المعرفة.","1mh3ejl":"البيئة التنافسية يرتبط فيها الفوز بخسارة الآخر. التعاونية نجاح الجميع معاً، والفردية كل طالب مستقل.","s44etr":"تبدأ المجموعة بالتعرف على المهمة ومعطياتها والمطلوب منها، ثم بلورة معايير العمل بتوزيع الأدوار والمسؤوليات، ثم الإنتاجية بالانخراط في العمل، ثم الإنهاء بعرض ما توصلت إليه. تحديد المهمة جزء من مرحلة التعرف وليس مرحلة مستقلة.","1pfhclv":"تدريس الأقران عبر الصفوف: طالب من صف أعلى يعلم طلاب صف أدنى. داخل الفصل بين زملاء الصف نفسه.","13e3c8m":"الألعاب التعليمية تنافس ممتع موجه. لعب الأدوار تقمص شخصيات، والمحاكاة تمثيل موقف واقعي، والعصف توليد أفكار.","1ghlrop":"الوسائل التعليمية أدوات ومواد. تقنيات التعليم منظومة أشمل (إنسان وآلة وطريقة)، ومصادر التعلم كل ما يتفاعل معه المتعلم.","1qjwp29":"الأول عام غير قابل للقياس المباشر في حصة، والثاني سلوكي بفعل قابل للملاحظة ومحتوى محدد.","1suuix1":"الرؤوس المرقمة تضمن استعداد كل عضو لأن أي رقم قد يُستدعى. الكرسي الساخن أسئلة لطالب خبير، وحوض السمك دائرتان، وجيكسو مجموعات خبرة.","bbp7ke":"حوض السمك: مشاركون في الداخل وملاحظون في الخارج. الأعواد سحب اسم عشوائي، والرؤوس المرقمة ترقيم الأعضاء.","1px8wlh":"فراير منظم رباعي للمفهوم (تعريف، خصائص، أمثلة، لا أمثلة). فن للمقارنة، وجدول KWL للمعرفة السابقة والمكتسبة.","1g10ujd":"RAFT عناصرها: الدور، الجمهور، الصيغة، الموضوع. تنال القمر للفهم القرائي، وشبكة الأسئلة جمع أسئلة الطلاب.","1f4pthl":"تنال القمر (أحرفها الأولى من خطواتها الخمس) وتشبه التدريس التبادلي الذي خطواته أربع (تنبؤ، أسئلة، توضيح، تلخيص).","rndq77":"التعليم التوليدي (أوزبورن وويتروك) يولّد المعنى في سياق اجتماعي بأطوار أربعة. دورة التعلم الخماسية مراحلها 5E، والتغير المفاهيمي لبوسنر.","fsnv8x":"التغير التطوري لتعديل بسيط، والثوري لاستبدال المفهوم كله. الاستقبالي والاكتشافي لأوزوبل، والأفقي والرأسي لانتقال الأثر.","1dt9db4":"التساؤل الذاتي مهارة ما وراء معرفية يراقب بها الطالب فهمه. العصف توليد أفكار جماعي.","7vesb6":"يشاهد الطلاب الشرح ويرسلون أسئلتهم في أوقات مختلفة، واختلاف الوقت هو ما يجعل التعليم غير متزامن. أما المتزامن (المباشر) فيجمع المعلم والطلاب في الوقت نفسه ولو اختلفت أماكنهم.","812kx":"المساند يدعم الصفي دون تغيير بنيته. المدمج يوزع التعلم بين الحضوري والإلكتروني، والكامل يستبدل الحضور، والمقلوب يقلب مهام الصف والمنزل.","1ewqdp":"تقنيات التعليم منظومة أشمل من الوسائل (أجهزة ومواد فقط). الكتاب وعاء المحتوى، والخفي ما يُتعلم ضمنياً.","zuopw4":"مصادر التعلم تشمل الموارد البشرية وغير البشرية التي يتفاعل معها المتعلم. الوسائل أدوات ومواد فقط.","12nlkf1":"نموذج ADDIE أشهر نماذج التصميم التعليمي. تايلر للمنهج، ونموذج 5E دورة تعلم، ونموذج SAMR لمستويات دمج التقنية.","2chwzp":"الويكي تحرير جماعي. المدونة صفحة شخصية للنشر والتعليق، والبودكاست محتوى صوتي، والفيديو التفاعلي يمزج الفيديو بالتحكم.","16qbz42":"المدونة للنشر الشخصي والتعليق. الويكي تحرير جماعي، والسحابية تخزين وموارد عبر الإنترنت.","1sehdgy":"البودكاست محتوى صوتي مسجل. الفيديو التفاعلي مرئي، والواقع المعزز يضيف عناصر رقمية للواقع، والرحلة المعرفية بحث موجه في الويب.","j0vq2x":"الفيديو التفاعلي يسمح بالتحكم والتفرع وفق استجابة المتعلم. البودكاست صوتي، والويكي والمدونة نصيتان.","hk488d":"إكسل جداول وحسابات ورسوم بيانية. أكسس لقواعد البيانات العلائقية، وباوربوينت للعروض، ووورد للنصوص.","4lbb2k":"أكسس نظام إدارة قواعد بيانات. إكسل جداول، وكانفا تصميم، وكاهوت ألعاب تفاعلية.","1geq7fd":"كانفا للتصميم المرئي، وبوبلت للخرائط المعرفية. أكسس وإكسل بيانات، وزوم وتيمز اجتماعات، وبرنامج SPSS للتحليل الإحصائي.","q9svo9":"معايير ISTE تصدرها الجمعية الدولية للتقنية في التعليم. أما TPACK فإطار معرفة المعلم، ونموذج SAMR لمستويات الدمج، ونموذج ADDIE للتصميم التعليمي.","jqgc80":"الذكاء الاصطناعي أداة مساعدة قد تخطئ، فيبقى التحقق من الدقة والمواءمة مسؤولية المعلم.","puuowx":"نظرة النظم للمنهج: مدخلات (أهداف ومحتوى) وعمليات (طرق وأنشطة) ومخرجات (نواتج) وتغذية راجعة (تقويم).","1nfec84":"المنهج التقليدي يساوي المقرر والحفظ، والحديث يشمل كل الخبرات ويراعي المتعلم. الخفي والفارغ والحلزوني مفاهيم أخرى.","1mfdin7":"المقرر قائمة الموضوعات، والكتاب الوعاء المادي للمحتوى والأنشطة، والمنهج أشمل منهما.","i0pvox":"التنظيم السيكولوجي يبدأ من المتعلم، والمنطقي من بنية المادة (السهل للصعب). الحلزوني تكرار بعمق، والمحوري جزء مشترك واختياري.","gs16a7":"المدى اتساع أفقي في المستوى الواحد، والتتابع تدرج رأسي عبر السنوات.","xujurt":"المنهج التكنولوجي قائم على التقنية والخطو الذاتي. المحوري مشترك واختياري، والحلزوني لبرونر، والخفي ضمني.","n0j6qf":"الإدارة الذاتية تنقل الضبط من المعلم إلى الطلاب (انضباط ذاتي). التسلطي يفرض، والفوضوي يترك، والجماعي يعاقب الكل.","1d2ajxa":"السلوك التوكيدي يبني ثقة الطالب بنفسه في التعبير. الإغراق مواجهة المخاوف دفعة واحدة، والكف المتبادل إحلال استجابة محل أخرى.","n4yn4d":"الكف المتبادل إحلال استجابة مقبولة لا تجتمع مع غير المرغوبة. الإشباع تقديم المثير بكثرة، والتلقين تلميح، وضبط المثير تعديل البيئة.","vj2nwt":"الإشباع تقديم المثير أو السماح بالسلوك بكثرة حتى يفقد قيمته. الانطفاء تجاهل، والإقصاء عزل، والتصحيح الزائد إصلاح الضرر وزيادة.","1n8f5wv":"الإرشاد بالواقع (جلاسر) يواجه الطالب بواقع سلوكه وأثره على الآخرين ويحمّله مسؤولية اختياره ويضع معه خطة لسلوك أفضل، والقصص الواقعية والأنشطة الخدمية هنا وسائل لذلك. الغمر مواجهة مفاجئة لمثير الخوف، وتكلفة الاستجابة سحب معزز، والسحب التدريجي تلاشي المساعدة.","1m6g5ao":"ضبط الذات مجاهدة النفس وتقييدها ذاتياً. الإقصاء والعقاب السالب إجراءان خارجيان من المعلم.","iuj8zf":"النشاط التعزيزي لمن أتقن لتثبيت التعلم، والعلاجي لمن لم يتقن. الإثرائي للموهوبين يتجاوز المنهج.","1rn2vqq":"الاقتراب من الطالب (المسافة)، والنظر المباشر (لغة العينين)، ونبرة الصوت (اللغة الموازية) كلها اتصال غير لفظي؛ فالنبرة تُحسب غير لفظية ولو صاحبت الكلام، لأنها تنقل المعنى بطريقة النطق لا بالكلمات. والمعلم لم يوجّه للطالب كلمة، فانتبه بالإشارات وحدها. أما اللفظي فكلمات منطوقة أو مكتوبة.","19gfani":"التقاربية تخص المسافة المكانية، والموازية نبرة الصوت وسرعته، ولغة الجسد التعبيرات والإيماءات.","1w9bwpz":"شرود الذهن معوق يخص المستقبل. القناة والمرسل والتغذية الراجعة عناصر أخرى في الاتصال.","1mxkadz":"التخطيط باللونين تغذية راجعة بصرية بلونين. نجمتان وأمنية نقطتا قوة ونقطة تحسين لفظياً، وبطاقة الخروج أداة تقويم تكويني.","1o53xq7":"المقالية المقيدة يكتب فيها الطالب إجابته بأسلوبه وإن حُدد نطاقها (مثل: اذكر ثلاثة أسباب)، فتتأثر درجتها بتقدير المصحح، فهي مقالية لا موضوعية. أما الاختيار من متعدد والصواب والخطأ والمطابقة والإكمال فإجاباتها محددة سلفاً وتصحيحها ثابت لا يختلف باختلاف المصحح.","3eva0l":"ذاتي المرجع يقارن الطالب بنفسه عبر الزمن. معياري بالأقران، ومحكي بمحك إتقان.","17o4dl3":"التتبعي يُجرى بعد فترة من التقويم الختامي لقياس بقاء أثر التعلم، وهذا ما فعله المعلم بعد شهرين. أما القبلي فقبل التعلم للاستعداد والمتطلبات السابقة، والتشخيصي في بدايته أو كلما ظهرت صعوبة متكررة قبل علاجها، والتكويني أثناء التعلم لتحسينه.","k8xs7a":"التصنيف حسب الجهة المقوّمة: خارجي من خارج المدرسة، وداخلي من داخلها، ومتعدد الأطراف يجمعهما.","l5pmyi":"ليكرت مقياس تقرير ذاتي خماسي للاتجاهات (نواتج وجدانية). قائمة الشطب نعم/لا للمهارات، والتحصيلي معرفي.","xdviav":"سترونج وكودر مقياسا ميول مهنية. ستانفورد ووكسلر للذكاء، أما (TIMSS, PISA) فاختبارات دولية.","1to2g75":"الاختبار الشفوي يكشف النطق والتعبير ولا مجال فيه للغش، وعيوبه الوقت والذاتية. الموضوعي سريع التصحيح، والمقالي كتابي.","y8o2x7":"الشمول تغطية المحتوى وفق جدول المواصفات. الموضوعية استقلال عن المصحح، والثبات استقرار، والتمييز كشف الفروق.","1x9evls":"العدالة تتطلب محكات معلنة وفرصاً متكافئة وتعدد الأدوات بمعيار واحد.","ejh7di":"في المقالي: مجموع الدرجات ÷ (عدد الطلاب × درجة السؤال) = 120 ÷ (20 × 10) = 0.60.","139sowy":"الصدق العيني وجه من صدق المحتوى يخص كفاية العينة من الفقرات. التنبؤي والتلازمي للمحك، والظاهري شكل الاختبار.","1rqkh54":"طول الاختبار بفقرات متجانسة متوسطة الصعوبة يزيد الثبات، أما التخمين والغموض والاضطراب فتخفضه.","1lbqlmv":"الالتواء يُسمى بجهة الذيل لا بجهة تجمع الدرجات: أغلب الدرجات مرتفعة وقلة منخفضة، فالذيل الطويل جهة الدرجات المنخفضة (اليسار)، فالالتواء سالب. وإذا كانت أغلب الدرجات منخفضة وقلة مرتفعة فالذيل جهة اليمين والالتواء موجب.","1a2rqdw":"التفرطح يصف شكل القمة مقارنة بالمنحنى الاعتدالي: القمة الأحدّ منه مدببة، والأكثر انبساطاً مفرطحة. الالتواء يصف انحراف الذيل لا القمة.","1qt1csv":"التغذية الراجعة الفعالة تأتي في وقتها (فورية غالباً) وتتكرر مع التعلم، وتغطي جوانب الأداء المهمة قوةً وضعفاً بعبارة موجزة محددة، وتركز على المهمة لا على شخص الطالب. أما العامة المؤجلة والموجهة إلى الشخصية والمقتصرة على الدرجة فلا ترشده إلى التحسين.","3spxsy":"الصدق يتضمن الثبات؛ فمن يقيس ما وُضع له يعطي نتائج مستقرة، أما الاتساق فلا يضمن قياس الهدف.","jgdmiu":"المعلم التقليدي ناقل للمعلومة والطالب سلبي. الميسر يدعم عند الحاجة، والمفوض يفوض المسؤولية، والمرشد يوجه.","jcel29":"التعليم المبرمج والحقائب والموديولات والحاسوب وسائل تعلم ذاتي. المحاضرة والعرض والمناقشة طرق يقودها المعلم.","dtnwuw":"الغدد الصماء (كالنخامية والدرقية) من العوامل البيولوجية المؤثرة في النمو الجسمي والانفعالي.","e15k7q":"برونر يرى إمكان تعليم أي مفهوم لأي طفل بصورة أمينة تناسب تمثيله (عملي، أيقوني، رمزي) إذا كان مستعداً، بخلاف بياجيه الذي يربط التعلم بالمرحلة.","pl9mo6":"السلوكي ضبط وتعزيز، والإنساني أو الشخصي يركز على الإدراكات الفردية والوجدان. المعرفي يهتم بالبنية المعرفية والاكتشاف، والاجتماعي بالتفاعل الجماعي.","10jreiq":"مدخل بنية العلم يركز على المفاهيم الكبرى وطرائق العلماء، بينما مدخل المادة الدراسية يهتم بمحتوى الكتاب. الضبط سلوكي والنشاط لديوي.","a811ya":"وفق الاحتكاك: مباشرة وغير مباشرة. وفق حاجة التخصص: عامة وخاصة. وفق عدد المتعلمين: جمعية وفردية.","1gk5xn":"ديوي وباركر ودويتش ثم جونسون وجونسون رواد التعلم التعاوني. البدائل الأخرى رواد السلوكية والمعرفية.","rdhr0o":"المجمعات التعليمية نظام تعلم ذاتي متكامل. التدريس المصغر لتدريب المعلمين، ولعب الأدوار والعصف استراتيجيات جماعية.","mreif6":"التعليم الفردي يراعي الفروق ويسعى للإتقان والاستقلالية والإبداع. التوحيد والتنافس يناقضانه.","11emr20":"المجموعات المرنة تتغير بحسب المهمة والاستعداد بدل التصنيف الثابت، وهي من أدوات التعليم المتمايز.","gw3d75":"نموذج التعلم البنائي الاجتماعي يبدأ ثنائياً وينتهي فردياً، بخلاف فكر‑زاوج‑شارك الذي يبدأ فردياً ثم ثنائياً ثم جماعياً.","1bwbvhi":"التقويم يشخص ويوجه ويحكم ويطور ويدعم القرارات. الرصد وحده قياس، والتصنيف النهائي والعقاب يناقضان غرضه.","1xdhh5d":"التقارير الذاتية تقيس النواتج الوجدانية بإجابة الطالب عن نفسه. التحصيلية معرفية، والأداء مهارية، وقوائم الشطب ملاحظة المعلم.","1nu0f1y":"أسس التقويم: وضوح الأهداف، الاستمرار، الشمول، التعاون، العلمية. الاقتصار على اختبار واحد يخالف الاستمرار والشمول.","191b73e":"بياجيه رائد نظرية النمو المعرفي ودرس كيف يبني الطفل مفاهيم العدد والزمن والمكان والسببية. الآخرون من رواد نظريات التعلم السلوكية والاجتماعية.","rl9aod":"الحكم على الكمية بالشكل الظاهري يعني غياب الاحتفاظ، وهو سمة ما قبل العمليات. لو كانوا في المحسوسة لأدركوا أن الكمية ثابتة. ليست مشكلة انتباه أو إدراك بصري.","1p11qon":"إضفاء الحياة والمشاعر على الجمادات هو الإحيائية، وهي طبيعية في ما قبل العمليات. ليست اضطراباً ولا دليلاً على موهبة، والتفكير الافتراضي من المرحلة المجردة.","5vpkw3":"البحث عن الشيء المخفي يعني إدراك أنه موجود رغم غيابه عن البصر؛ وهذا دوام الشيء، يبدأ نحو 8–12 شهراً ويكتمل في نهاية الحس-حركية. الاحتفاظ والمعكوسية يأتيان في المحسوسة.","8pvm7r":"التفكير في الافتراضات الخيالية (ماذا لو) من سمات العمليات المجردة، وطلاب الثالث الابتدائي في المحسوسة. ليست مشكلة دافعية أو حفظ أو تعزيز.","1a0tdkk":"العجز عن تبني منظور الآخر هو التمركز حول الذات (تجربة الجبال الثلاثة لبياجيه)، وهو سمة ما قبل العمليات لا عيب في الذاكرة أو الفهم.","jt76dg":"طالب الخامس الابتدائي (10–11 سنة) في مرحلة المحسوسات، فالتجربة الملموسة قبل القاعدة أنسب. الكمون تفسير فرويدي لا يتصل باختيار الطريقة.","w0cktd":"أزمة الابتدائية الاجتهاد مقابل الدونية، ويُحل القطب الإيجابي بخبرات إنجاز وتقدير. الإعفاء يرسخ الدونية، والمقارنة تزيدها، والإحالة سابقة لأوانها.","w5ia55":"المجادلة والاستقلال والتأثر بالأقران من خصائص المراهقة المبكرة (أزمة الهوية). التعامل معه بالاحتواء والحوار لا الإحالة.","1sb2nof":"الطفل في الطفولة المتوسطة انتباهه قصير وحاجته للحركة كبيرة، فالتنويع والأنشطة القصيرة أنسب. الجلوس الطويل والشرح المطوّل يناقضان خصائص المرحلة.","gdtz93":"اختيار المهنة والاستعداد لها من مطالب نمو المراهقة (هافجهرست) وتكوين الهوية (إريكسون). المحسوسات للابتدائية، وسن الجماعة للطفولة المتأخرة.","ifb5ao":"المعضلات الأخلاقية (قصة هاينز) هي أداة كولبرج لتحديد مرحلة التفكير الأخلاقي من خلال التبرير لا الاختيار. بياجيه يستخدم مهام الاحتفاظ، وإريكسون الأزمات.","fekw5a":"ربط الصواب بتجنب العقاب هو المرحلة الأولى من المستوى ما قبل التقليدي. الالتزام بالقانون لذاته مرحلة 4، وإرضاء الآخرين مرحلة 3.","5gu4wu":"الحفاظ على النظام الاجتماعي والقانون لذاته هو المرحلة الرابعة (المستوى التقليدي). المبادئ العالمية تتجاوز القانون إلى العدل والكرامة.","vl7ui6":"المرحلة الثالثة «الولد الطيب»: الصواب ما يرضي المحيطين ويكسب موافقتهم. تجنب العقاب مرحلة 1، والمنفعة مرحلة 2، ومبادئ العدل مرحلة 6.","1qn1z69":"مرحلة الكمون (6–12) فيها تهدأ الدوافع ويتجه الطفل إلى التحصيل والصداقات. الفمية للرضاعة، والقضيبية 3–6، والتناسلية للمراهقة.","1t9l77f":"الأنا الأعلى يحمل القيم والضمير المكتسبة من الوالدين. الهو مبدأ اللذة، والأنا مبدأ الواقع يوازن بينهما.","1ihq78d":"القراءة والكتابة والحساب ومهارات اللعب مطالب الطفولة المتوسطة. اختيار المهنة والاستقلال الانفعالي وتقبل الجسم من مطالب المراهقة.","15ssquu":"الرأسي–الذيلي يصف تقدم النمو من الرأس إلى الأسفل. المركزي–الطرفي من الجذع إلى الأطراف، ومن العام إلى الخاص يصف الحركات الكلية قبل الدقيقة.","b5trru":"القبض الكلي ثم الدقيق يجسد مبدأ من العام (الحركات الكلية) إلى الخاص (الحركات الدقيقة). النمو لا يسير بمعدل ثابت ولا يستقل عن النضج.","qzs114":"المهارة تحتاج نضجاً في العضلات الدقيقة والتآزر لا يكتمل في هذا العمر؛ التدريب قبل النضج لا يفيد. ليست مشكلة دافعية أو تعزيز، ولا يُشخص الأطفال بصعوبات تعلم في هذه السن.","5u13yh":"النضج تغير داخلي لا يحتاج خبرة، بخلاف التعلم الناتج عن الخبرة والتدريب. التكيف مصطلح بياجيه للتمثل والمواءمة.","1nkxdwk":"النمو مستمر لكن بمعدلات متفاوتة: سريع في الطفولة المبكرة والمراهقة وبطيء في الطفولة المتوسطة. الباقي مبادئ صحيحة.","cl9czc":"الاحتفاظ والمعكوسية إنجازا مرحلة العمليات المحسوسة لا ما قبلها. التمركز والإحيائية والرمز من سمات ما قبل العمليات.","pkz85v":"الاحتفاظ والتمركز مفهومان عند بياجيه لا أزمتان عند إريكسون. الثلاثة الأخرى من أزماته الثماني.","1m4j0nk":"المراهقة تتميز بطفرة نمو جسمي سريعة لا ببطئه. التقلب الانفعالي والاهتمام بالمظهر والمثالية من سماتها المعروفة.","t4s4y3":"وضع الفروض واختبارها عقلياً جوهر العمليات المجردة (وتسمى أيضاً العمليات الشكلية أو الصورية). الحسي الحركي للرضيع، وما قبل الإجرائي للطفولة المبكرة.","1pf8hr2":"الرضيع يعرف العالم بالحواس والأفعال الحركية؛ الرمي والتذوق استكشاف طبيعي. ليس عدواناً ولا فرط حركة ولا تعلماً بالملاحظة.","1e0zhme":"تأثير الأقران في المراهقة قوي، فتوظيفه بالتعاون والنمذجة الإيجابية يخدم التعلم. المقارنة العلنية تجرح وتُحبط، والمنع غير واقعي.","16ujwib":"تبدأ طفرة البلوغ عند البنات أبكر من الأولاد بنحو سنة إلى سنتين، وهذا يفسر تفاوت الأحجام في الصفوف العليا من الابتدائية.","1k39jvf":"تعديل المخطط القائم وإنشاء مفهوم جديد هو المواءمة. تسمية الكلب قطاً كانت تمثلاً (إدخال الجديد في مخطط قائم). التعميم مصطلح سلوكي.","11aykwv":"إرضاء الآخرين والحفاظ على صورة الولد الطيب هو المستوى التقليدي (المرحلة 3). ما قبل التقليدي يرتبط بالعقاب والمنفعة، وما بعده بالمبادئ.","qowfqw":"ظهور الوظيفة الرمزية (اللغة واللعب الإيهامي) مع غياب الاحتفاظ سمة ما قبل العمليات (2–7).","p04uid":"طالب الثالث في المحسوسات، فالتعامل اليدوي مع المواد (التمثيل العملي عند برونر) هو الأنسب. الشرح اللفظي المجرد والاستنباط من قاعدة يناسبان مراحل أعلى.","1ufwiq6":"الموازنة هي العامل الرابع الذي ينظم التمثل والمواءمة عند بياجيه. التعزيز سلوكي، والنمذجة لباندورا، والاستبصار للجشطلت.","8plo0t":"الطفولة المتأخرة سن الجماعة والقيادة، فتوظيف قوته الاجتماعية جسر لمهارة القراءة. المنع والإجبار يضران بأزمة الكفاءة، والتجاهل لا يعالج.","13ggc0d":"التأخر الدراسي: ذكاء عادي وتدنٍ ناتج عن عوامل خارجية (إهمال، غياب، دافعية). صعوبات التعلم اضطراب داخلي في العمليات، وبطء التعلم ذكاء حدّي.","g4tq59":"الرسوم والخرائط مدخل النمط البصري، وفي التقسيم الثلاثي (بصري، سمعي، حسي حركي) تُحسب القراءة معها؛ أما في نموذج VARK فللقراءة نمط مستقل ليس بين الخيارات. السمعي يفضل الشرح والمناقشة، والحسي التجربة والحركة.","1woqbxs":"نسبة الذكاء محسوبة بالنسبة لأقران العمر فتبقى ثابتة نسبياً عبر الزمن، مع تغيرات طفيفة.","19unzib":"هدف واحد مع تنويع المحتوى والعملية والمنتج وفق الاستعداد والاهتمام هو التمايز (توملينسون). الإتقان يركز على الزمن حتى الإتقان، والمبرمج خطوات صغيرة.","cd038i":"أبعاد التمايز الأربعة: المحتوى، العملية، المنتج، بيئة التعلم. الأهداف والمنهج الرسمي لا تتغير بين الطلاب.","1deppy8":"التمايز يقوم على مجموعات مرنة لا تصنيف دائم يوصم الطالب. الباقي من ممارساته.","g1j7ga":"الإثراء يعمّق (رأسي) أو يوسّع (أفقي) الخبرة داخل الصف نفسه. التعجيل يغيّر الزمن أو الصف (قبول مبكر، تخطي صفوف، ضغط المنهج)، والتجميع يعزلهم في مجموعات خاصة، والدمج الجزئي مصطلح يخص ذوي الإعاقة.","5xcous":"تخطي الصفوف أحد صور التعجيل مع القبول المبكر وضغط المنهج. الإثراء يبقي الطالب في صفه.","1c6eicf":"ضغط المنهج يعني دراسة المادة في زمن أقل من المعتاد، وهذا من صور التعجيل نصاً في دليل الاختبار العام للمعلمين (قياس 1436، السؤال 13)، ومثله النقل إلى صف أعلى والقبول المبكر. أما التمارين المكررة وجعله مساعداً للمعلم وإعفاؤه من الواجبات فلا تختصر زمن التعلم، وهي ممارسات خاطئة مع الموهوب.","u593w":"حلقات رنزولي: قدرة فوق المتوسط، إبداع، التزام بالمهمة (الدافعية). الطلاقة والمرونة مكونات الإبداع وحده.","qizhl2":"الكشف عن الموهبة يتطلب محكات متعددة لأن التحصيل وحده قد يخفي موهوباً ذا صعوبات أو ملل. الهدوء وطلب الأهل ليسا محكين.","1m9yzy9":"الملل سببه عدم التحدي، فالحل إثراء رأسي بمهام أعمق. التمارين المكررة تزيد الملل، والعقاب يعالج العرض لا السبب.","1xnrdh4":"الموهوب يتميز بالنمو اللغوي المبكر والذاكرة والفضول وحب التحدي. الباقي عكس خصائصه.","139dfiq":"قلب الحروف وبطء القراءة مع ذكاء عادي وفهم سمعي جيد علامات الديسلكسيا (صعوبة أكاديمية). بطء التعلم ضعف عام، والإعاقة البصرية تظهر في كل مهام الرؤية.","rjp7sq":"الديسغرافيا عسر الكتابة. الديسلكسيا قراءة، والديسكالكوليا حساب، والديسفازيا اضطراب لغوي.","141y0oq":"ذو الصعوبات يبقى في صفه مع تكييفات وخدمة غرفة المصادر. الإعفاء يحرمه، والتربية الفكرية للإعاقة العقلية، والقراءة العلنية تحرجه.","1di9vg0":"النشاط الزائد والاندفاعية وضعف الانتباه هي الثلاثية المميزة لاضطراب فرط الحركة وتشتت الانتباه. التوحد يتميز بقصور التواصل والسلوك النمطي.","1dgaujo":"قصور التواصل الاجتماعي والسلوك النمطي ومقاومة التغيير هي السمات المميزة للتوحد. الإعاقة السمعية لا تفسر السلوك النمطي، وصعوبات التعلم لا تُشخص في الروضة بهذه الصورة.","10fid95":"دور معلم الصف العادي الملاحظة والإحالة؛ التشخيص للمختص. إخبار الأهل بحكم غير مؤكد ضار، والتجاهل يضيّع التدخل المبكر.","1oefkxh":"المقدمة ومواجهة الوجه (لقراءة الشفاه) والوسائل البصرية تعوض القصور السمعي. رفع الصوت وحده غير كافٍ، والإعفاء يحرمه.","1dn0ene":"برايل نظام نقاط بارزة للمكفوفين. لغة الإشارة وقراءة الشفاه للصم وضعاف السمع.","5cxnr9":"التعريف يشترط انخفاض الذكاء وقصور السلوك التكيفي خلال فترة النمو. القصور في مادة واحدة يشير إلى صعوبات التعلم.","1hyhn0u":"متلازمة داون اضطراب وراثي كروموسومي يسبب إعاقة فكرية بدرجات متفاوتة.","1mk4iui":"ذوو الاحتياجات الخاصة كل من ينحرف عن المتوسط ويحتاج خدمات خاصة، وتشمل الموهوبين لا ذوي الإعاقة فقط.","10422j2":"نسبة الذكاء الحدّية (70–85 تقريباً) مع تدنٍّ في جميع المواد هي سمة بطء التعلم. أما صعوبات التعلم فذكاؤها عادي أو فوق العادي والتدني في مجال محدد، والإعاقة الفكرية دون 70 تقريباً مع قصور في السلوك التكيفي، والموهوب ذكاؤه مرتفع وإن انخفض تحصيله.","13d9552":"بطيء التعلم يحتاج تبسيطاً وتجزئة ووقتاً وتكراراً داخل الصف العادي. المعاهد للإعاقة الفكرية، والإعفاء لا يعلّم.","m27dbb":"الفروق الفردية كمية: الأفراد يشتركون في السمة نفسها ويختلفون في مقدارها (درجة لا نوع)، ومعظمهم قرب المتوسط فتتوزع توزيعاً اعتدالياً. وتشمل السمات الجسمية والعقلية والانفعالية والشخصية، وأوسع مداها في الشخصية والانفعالية، وتنتج عن تفاعل الوراثة والبيئة.","zf21x1":"تفاوت قدرات الطالب نفسه بين مجال وآخر هو الفروق داخل الفرد. لا يُحكم بصعوبات تعلم إلا بتشخيص.","1f5mb2q":"المحاضرة تقدم المحتوى نفسه بالسرعة نفسها للجميع. المبرمج والموديولات والصف المقلوب تتيح السير بالسرعة الذاتية.","1vqzxo5":"تنويع قنوات العرض يخاطب الأنماط السمعية والبصرية والحسية. التعزيز والانطفاء مفاهيم سلوكية لا تتصل بالعرض.","r63ldg":"الاهتمام بالكائنات الحية وتصنيفها من الذكاء الطبيعي. المكاني للأشكال والأبعاد، والجسمي للحركة.","11423xz":"فهم الآخرين والتأثير فيهم هو الذكاء الاجتماعي. الذاتي يخص فهم النفس.","4fjp9b":"المدى مقياس تشتت يبين اتساع الفروق بين الأفراد في الصفة.","1vly8rn":"الدمج الكلي يعني تلقي كل التعليم في الفصل العادي مع دعم. المشاركة في الفسحة فقط دمج اجتماعي، والمعهد عزل، وغرفة المصادر معظم اليوم دمج جزئي.","c8118k":"الفجوة بين القدرة والتحصيل تُكشف بالاختبارات التحصيلية والتشخيصية. مقاييس الاتجاه والميول والذات لا تقيس التحصيل.","1glww2k":"الخطة التربوية الفردية تُعدّ لكل طالب من ذوي الاحتياجات الخاصة. جدول المواصفات لبناء الاختبار، والخطة الفصلية لعموم الصف.","f05x34":"مقاومة التغيير سمة التوحد، والتعامل معها بالروتين والتهيئة المسبقة بالجداول البصرية (التعلم المنظم). التغيير المستمر والعقاب يزيدان الاضطراب.","1jt30y0":"الموهوب يحتاج إثراءً وإلا ملّ وربما انخفض تحصيله. التحصيل وحده لا يكشف كل الموهوبين، والعزل الدائم ليس الخيار الأفضل.","ee672j":"الكمالية والحساسية المفرطة من الخصائص الانفعالية للموهوبين وقد تسبب القلق. العجز المتعلم توقف عن المحاولة، وهي عكس ذلك.","zdzf9a":"المادة التمهيدية العامة التي تُعرض قبل الدرس لربطه بالبنية المعرفية هي المنظم المتقدم عند أوزوبل. التعزيز سلوكي والكفاية الذاتية لباندورا.","1unojk9":"فيجوتسكي يرى التعلم اجتماعياً أولاً عبر الحوار والمساعدة في منطقة النمو القريب. بياجيه يركز على البناء الفردي.","ws6uzu":"اللمسة والابتسامة والمدح معززات اجتماعية، وتسمى أيضاً معنوية في التقسيم الثنائي (مادية ومعنوية). المادية هدايا، والرمزية نجوم تُستبدل، والنشاطية وقت لعب.","pn3mn3":"البنائية تجعل المعلم ميسراً والطالب بانياً نشطاً. الأدوار الأخرى سلوكية.","10x7vo6":"الشكر مثير سارّ أُضيف بعد السلوك فزاد، وهذا التعزيز الموجب. التعزيز السالب إزالة منفّر، والعقاب السالب سحب معزّز.","14w09eu":"سحب امتياز مكتسب (حصة الرياضة) بعد السلوك غير المرغوب فقلّ السلوك = تكلفة الاستجابة، وهي صورة من العقاب السالب. التعزيز السالب إزالة منفّر فيزيد السلوك، والعقاب الموجب إضافة منفّر.","f8sqs2":"وقف التعزيز (الانتباه) عن السلوك فيتلاشى = انطفاء، مع تعزيز السلوك البديل (تعزيز تفاضلي). الإقصاء يتطلب إبعاده.","uday7a":"الإبعاد المؤقت عن مصدر التعزيز هو الإقصاء. تكلفة الاستجابة خسارة شيء مكتسب كالدرجات.","1u8vmaq":"التعزيز بعد عدد ثابت من الاستجابات = نسبة ثابتة. الفترة ترتبط بالزمن، والمتغيرة بعدد غير منتظم.","8gmx84":"الاختبارات في أوقات زمنية غير منتظمة = فترة متغيرة، وتحافظ على أداء مستمر. الفترة الثابتة (كل أسبوع) تجعل الاستذكار يتركز قبل الموعد.","3sgz85":"النسبة المتغيرة (كألعاب الحظ) الأقوى وأكثرها مقاومة للانطفاء. المستمر أسرع تعلماً لكنه أسرع انطفاءً.","1y50m6k":"التعزيز بعد زمن ثابت يُنتج نمط «الحافة»: ارتفاع الأداء قبل الموعد وانخفاضه بعده.","dkakf9":"تعزيز التقريبات المتتابعة نحو السلوك النهائي هو التشكيل. التسلسل ربط خطوات مكتملة، والنمذجة ملاحظة نموذج.","17u15hl":"الرموز القابلة للاستبدال بمعززات هي الاقتصاد الرمزي. بريماك نشاط محبب يعزز نشاطاً آخر، والعقد اتفاق مكتوب.","1vk9hi":"إصدار الاستجابة الشرطية لمثيرات تشبه المثير الأصلي هو التعميم. التمييز عكسه.","10enkcl":"الاستجابة للمثير الأصلي دون المشابه هي التمييز.","7gdthd":"عودة الاستجابة المنطفئة بعد فترة راحة هي الاسترجاع التلقائي عند بافلوف.","g202w1":"الجرس مثير محايد صار شرطياً. الطعام غير شرطي، واللعاب للجرس استجابة شرطية.","1415s7z":"التكرار (قانون التدريب)، والمدح (قانون الأثر)، والاستعداد هي قوانين ثورندايك.","11bhvun":"واطسون مؤسس السلوكية ومعه تجربة ألبرت الصغير. تولمان معرفي (التعلم الكامن).","lcr8ci":"التعلم حدث دون تعزيز وظهر عند وجود الدافع: التعلم الكامن والخرائط المعرفية عند تولمان.","1ysbj6z":"الحل المفاجئ بعد إعادة تنظيم الموقف هو الاستبصار (الجشطلت/كوهلر). المحاولة والخطأ تدريجي.","3lcv7o":"الإطار العام المقدّم قبل الدرس لربطه بالبنية المعرفية هو المنظم المتقدم. السقالات دعم أثناء الأداء.","qtzsrt":"الحفظ دون ربط بالبنية المعرفية هو التعلم الاستظهاري (الصمّ) بالاستقبال. ذو المعنى يربط الجديد بالقديم.","byivad":"التدرج من التمثيل العملي إلى الأيقوني إلى الرمزي هو ترتيب برونر لأنماط التمثيل.","1kmb1jc":"الحلزوني تنظيم برونر لتكرار المفاهيم بتعمق متزايد. وتتابع المفهوم عبر الصفوف تنظيم رأسي للمنهج، أما ربطه بالمواد الأخرى في الصف نفسه فتنظيم أفقي.","oua9cz":"تجميع الوحدات المتفرقة في وحدات أكبر ذات معنى يقلل عدد ما يُحفظ، فتستوعب الذاكرة قصيرة المدى معلومات أكثر مع أن سعتها تبقى نحو 7±2 وحدات. التسميع تكرار، والتنظيم الهرمي للمفاهيم.","c073hu":"ميلر: 7±2 وحدات، وتبقى المعلومة فيها نحو 15–30 ثانية دون تسميع. غير المحدودة هي طويلة المدى.","1bep20v":"التعلم الجديد (الإسبانية) أعاق تذكر القديم (الفرنسية) = تداخل بعدي. القبلي القديم يعيق الجديد.","330w3n":"الاحتفاظ بالمعلومات ثوانٍ قليلة ومعالجتها دون تثبيت عمل الذاكرة العاملة.","1i6c1td":"يبدأ الملاحظ بالانتباه للنموذج ثم الاحتفاظ بالصورة ثم إنتاج السلوك ثم الدافعية لأدائه.","190fppu":"زيادة سلوك الملاحظ بعد رؤية النموذج يُعزز هي التعزيز البديل (باندورا). التعزيز المباشر يقتضي أن يُكافأ هو.","d2jvih":"أقوى مصادر الكفاءة الذاتية خبرات الإتقان ثم الخبرات البديلة. الإقناع اللفظي وحده ضعيف، والمقارنة تضعفها.","19960at":"إدخال الخبرة الجديدة في مخطط قائم (الحصان) دون تعديله هو التمثل. لو كوّن مفهوماً جديداً لكان مواءمة.","ouhb52":"التدريس الفعال يستهدف منطقة النمو القريب (ما ينجزه بالمساعدة) مع سقالات تُسحب تدريجياً. ما يتقنه وحده لا يطوره، والبعيد جداً يُحبط.","3mt9j6":"الدعم المؤقت المتناقص مع تقدم المتعلم هو السقالات (فيجوتسكي/برونر).","ewnc8t":"فيجوتسكي يرى الحديث الذاتي وسيلة لضبط الذات وتوجيه الفعل ويتحول لاحقاً إلى حديث داخلي. بياجيه عدّه تمركزاً، لكن السؤال عن فيجوتسكي.","cdggze":"العادة القديمة أعاقت الأداء الجديد = انتقال سلبي.","1uxma9s":"تعلم مهارة أعلى مستوى تبنى على سابقة = انتقال رأسي. الأفقي مهارة بالمستوى نفسه في سياق آخر.","10xm8zz":"نظرية العناصر المتطابقة لثورندايك: ينتقل الأثر بقدر تشابه عناصر الموقفين. جد فسّره بالتعميم.","1gqll4v":"التعزيز بنوعيه يزيد السلوك؛ التقليل وظيفة العقاب. الالتباس الشائع هو عدّ «السالب» عقاباً.","1qk6zpi":"جداول التعزيز من الإشراط الإجرائي. الباقي من بياجيه وفيجوتسكي.","7zzt4z":"تكديس المعلومات دفعة واحدة قبل الاختبار يثقل الذاكرة العاملة ويُنسى سريعاً، فليس استراتيجية لنقلها إلى الذاكرة طويلة المدى. أما التسميع الموزع والتجميع والتوسيع (ربط الجديد بالمعرفة السابقة) فاستراتيجيات ترميز فعالة.","c109ez":"رؤية نموذج يُعزز يزيد السلوك عند الملاحظين (باندورا).","10n2f33":"المعلومات المتواصلة الكثيفة تفوق سعة الذاكرة العاملة (الحمل المعرفي الزائد)، فالحل التقسيم والتوقف للمعالجة.","1x0fid9":"نظرية العزو (واينر): عزو الفشل إلى الجهد (متغير قابل للضبط) يدفع للمحاولة، وعزوه إلى القدرة يُحبط. التعزيز المادي سلوكي لا معرفي.","1j6ticq":"أثر التبرير الزائد: المكافأة الخارجية على نشاط محبب داخلياً تُحوّل الدافع إلى خارجي فيزول بزوالها.","4mdqo7":"صعوبة المهمة سبب خارجي ثابت. الحظ خارجي متغير، والجهد داخلي متغير، والقدرة داخلية ثابتة.","vuw2r0":"الحاجات الدنيا (طعام، أمن) تسبق الحاجات العليا؛ لا تعلم مع جوع أو خوف.","v6xle7":"الاستثارة المتوسطة تُحسّن الأداء، أما المنخفضة جداً أو المرتفعة جداً فتضعفه.","elqe2f":"الأداء الأمثل عند الاستثارة المتوسطة، فالمنخفض يُرفع والمرتفع يُخفض.","ux0tp3":"وفق ماكليلاند وأتكنسون، ذو دافع الإنجاز المرتفع يفضل المهام متوسطة الصعوبة، ومنخفضه يختار السهل جداً أو الصعب جداً.","1mn1tg7":"توجه الأداء يسعى لإثبات القدرة والظهور، وتوجه الإتقان يسعى للتعلم ويرى الخطأ فرصة.","1hjbb57":"التغذية الفورية الوصفية والأهداف القريبة ترفع الكفاءة الذاتية. المقارنة تُحبط، والمكافآت المفرطة تضعف الداخلية، والتأجيل يفقد الأثر.","1o17gzl":"المصدر الرابع هو الحالة الفسيولوجية والانفعالية (القلق، التعب) التي يفسرها الفرد كمؤشر على قدرته.","1aeh32n":"بينيه (1905) وضع أول مقياس للذكاء مع سيمون. وكسلر لاحق، وسبيرمان نظرية العاملين.","vkkzf6":"معادلة ستيرن/تيرمان: ن.ذ = ع.ع ÷ ع.ز × 100؛ فطفل عمره العقلي 12 وزمنه 10 نسبته 120.","1ikdmoh":"10 ÷ 8 × 100 = 125. القسمة العكسية تعطي 80 خطأً.","okf76q":"أقل من 70 مع قصور في السلوك التكيفي = إعاقة فكرية. بطء التعلم 70–85، وصعوبات التعلم ذكاء عادي.","1sh1slx":"سبيرمان صاحب نظرية العاملين. ثيرستون قدرات أولية، جاردنر متعددة، ستيرنبرغ ثلاثي.","45i4y6":"السائل قدرة فطرية على حل المشكلات الجديدة، والمتبلور معارف مكتسبة (مفردات ومعلومات).","p5mljy":"جيلفورد صاحب نموذج بنية العقل (120–180 قدرة) والتفكير التباعدي أساس الإبداع.","b6gf9q":"الطلاقة كمية الأفكار في زمن محدد. المرونة تنوعها، والأصالة ندرتها، والتوسع التفاصيل.","38ahgu":"تنوع فئات الأفكار وتغيير الزاوية هو المرونة، بغض النظر عن عددها.","18t7tjv":"الأصالة ندرة الفكرة وجدّتها.","vclas1":"إضافة التفاصيل والتوضيحات إلى الفكرة هي الإفاضة.","1adoxg1":"والاس: جمع المعلومات (إعداد)، ثم تركها تختمر (احتضان)، ثم ومضة الفكرة (إلهام)، ثم اختبارها (تحقق).","xxgs6m":"ترك المشكلة تختمر لا شعورياً هو الاحتضان الذي يسبق الإلهام.","i79ysr":"مراقبة الخطة وتقويمها تفكير في التفكير. القراءة والحفظ والنسخ مهارات معرفية.","bt0l4q":"الحذر والسلبيات والمخاطر قبعة سوداء. الحمراء مشاعر، الصفراء فوائد، الخضراء إبداع.","7zoqku":"البيضاء للحقائق والمعلومات المحايدة. الزرقاء تنظم عملية التفكير.","v62mo3":"المشاعر والحدس دون تبرير قبعة حمراء.","19r5cnz":"الزرقاء تضبط عملية التفكير وتنظمها وتلخص وتتخذ القرار.","lakqrx":"الخضراء لون النمو: الإبداع والاقتراحات. البيضاء حقائق، السوداء مخاطر، الصفراء فوائد.","12kvq70":"كورت برنامج ديبونو. 4MAT لمكارثي، سكامبر لتوليد الأفكار، VARK أنماط التعلم.","7bn5u":"المستويات العليا الثلاثة: تحليل، تقويم، إبداع. الدنيا: تذكر، فهم، تطبيق.","6tgvu9":"الفرز والمفاضلة والتقويم بمعايير تفكير ناقد (تقاربي). توليد العشرين كان إبداعياً تباعدياً.","1acyssr":"التباعدي ينطلق إلى حلول متعددة، والتقاربي يصل إلى الحل الواحد الصحيح.","2ynyji":"السؤال المفتوح متعدد الإجابات (ماذا لو) يستدعي الطلاقة والأصالة. الأسئلة الأخرى استدعاء معلومات.","1nfmuh0":"تقبل الغريب من محفزات الإبداع. الخوف والنقد المبكر والجمود معوقات.","7fvfa3":"الاستدلال العددي قدرة عقلية أولية عند ثيرستون. مكونات جولمان: الوعي بالذات، تنظيم الانفعالات، الدافعية، التعاطف، المهارات الاجتماعية.","2bu0xv":"ضبط الانفعال والتعاطف من مكونات الذكاء الوجداني (جولمان).","13j985y":"ترجعون من الأفعال الخمسة لأنه مضارع اتصلت به واو الجماعة، ولم يسبقه ناصب ولا جازم فهو مرفوع بثبوت النون.","cf7g6z":"«ابتهاجاً» مصدر من لفظ الفعل «ابتهجت» جاء لتوكيده فهو مفعول مطلق. المفعول لأجله يبين السبب وليس من لفظ الفعل.","oub6ui":"«جميعاً» نكرة منصوبة جاءت بعد معرفة «المعلمون» تبيّن هيئتهم وقت الحضور، فهي حال منصوبة، ومثلها قوله تعالى: «إليه مرجعكم جميعاً». ولا تكون توكيداً معنوياً إلا مضافة إلى ضمير يعود على المؤكَّد: «حضر المعلمون جميعُهم».","1p4uyx8":"الفاعل مثنى مرفوع بالألف، ونون المثنى تُحذف عند الإضافة: طالبا العلم. و«طالبان» تصح لو لم يُضف.","7vq39i":"المال = الزكاة × 40 = 5000 × 40 = 200000؛ لأن الزكاة ربع العشر (2.5%).","p6427r":"من اليمين: 5 آحاد، 1 عشرات، 3 مئات، 1 آحاد الألوف، 7 عشرات الألوف، 5 مئات الألوف، 2 آحاد الملايين.","3mhvdo":"محيط المستطيل = 2 × (12 + 8) = 40 م، ودورتان = 80 م. و96 مساحته لا محيطه.","d2anxz":"إصدار حكم على قيمة الأداء في ضوء محك هو التقييم. القياس لا يتضمن حكماً، والتقويم يضيف العلاج والتعديل، والتغذية الراجعة تصف الأداء وتوجه.","1pers6t":"يبدأ بالقياس (جمع أرقام)، ثم التقييم (حكم في ضوء محك)، ثم التقويم (قرار التعديل والعلاج). لا يمكن الحكم قبل القياس ولا العلاج قبل الحكم.","1erm4xk":"الاختبار وسيلة لجمع البيانات الكمية، أي أداة قياس. ليس مرادفاً للتقويم لأن التقويم أشمل، وليس نوعاً من التقويم بل أداة قد تستخدم في أي نوع.","qeobuh":"الاختبار التحصيلي يقيس نواتج التعلم الفعلية. اختبار الاستعداد يتنبأ بإمكانية التعلم مستقبلاً، والذكاء والقدرات يقيسان قدرة عامة لا محتوى درسه الطالب.","v84z89":"اختبارات الاستعداد تقيس إمكانية التعلم أو النجاح مستقبلاً. التحصيلي يقيس ما تعلمه الطالب فعلاً، والتشخيصي يبحث عن مواطن الضعف، والختامي يصدر حكم النهاية.","11awf1s":"الاختبار المقنن يعدّه متخصصون ويطبَّق بظروف موحدة وله معايير؛ أما الاختبار الذي يعدّه المعلم لصفه فهو اختبار معلم غير مقنن مهما كانت جودته.","1m907l8":"التقويم الجيد مستمر وشامل وتعاوني وعلمي واقتصادي، وليس غاية بحد ذاته ولا نشاطاً ختامياً فقط؛ فاقتصاره على نهاية العام يفقده وظيفة التحسين.","alhc6p":"التكويني أثناء التدريس وغايته التحسين والتغذية الراجعة، والختامي في النهاية وغايته الحكم. أما نوع الأسئلة وعددها ومن يصحح فلا يميز بينهما.","1xxz6ax":"لأنه يواكب التعلم ويستمر معه طوال التدريس. النهائي هو الختامي، والمقنن وصف للاختبار لا لنوع التقويم، والمعياري طريقة تفسير.","1ey1h4s":"توزيع الطلاب في مستويات وتصنيفهم قبل التعلم من أغراض التقويم القبلي. الختامي يحكم بعد التعلم، والتكويني أثناءه، والذاتي يقوم به الطالب.","c7mb04":"من أغراض التقويم الختامي الحكم على فاعلية جهود المعلم وطرق تدريسه ومقارنة الشعب. القبلي والتشخيصي يسبقان التعلم أو يبحثان عن الصعوبات.","zv9ocr":"المحكي يخبرنا ما يستطيع الطالب عمله (أتقن / لم يتقن) فنتائجه قائمة أهداف. الترتيب والرتب المئينية والمنحنى الاعتدالي كلها أدوات التفسير معياري المرجع.","1krbytz":"نسبة الإتقان المحددة مسبقاً (80%) محك ثابت يقارن به أداء الطالب، فهو محكي المرجع. لا علاقة له بأداء الآخرين فليس معيارياً.","bpc187":"الانتقاء والمفاضلة يحتاجان ترتيب المتقدمين بعضهم بالنسبة لبعض، وهذا جوهر المعياري. الإتقان والشهادات والتشخيص تحتاج مقارنة بمحك محدد.","1whi173":"مقارنة الطالب بأدائه السابق تفسير ذاتي المرجع يركز على النمو الفردي. المعياري يقارن بالأقران، والمحكي بمستوى إتقان محدد.","10i0c9i":"التقويم من أجل التعلم تقويم تكويني يستخدم الأدلة لتوجيه التعلم والتدريس. الحكم النهائي هو تقويم التعلم، والترتيب معياري، وقياس القدرات ليس تقويماً صفياً.","wtf0dc":"حكم الطالب على عمل زميله وفق محكات هو تقويم الأقران. الذاتي حكم الطالب على عمله هو، والأداء يتعلق بإنجاز مهمة فعلية، والختامي حكم المعلم في النهاية.","15cphaw":"التقويم الذاتي ينمي وعي الطالب بأخطائه ودوافعه فيعدل سلوكه ويزيد ثقته. توفير الوقت نظرة تركز على المعلم، ولا يغني عن تقويم المعلم ولا يرفع الدرجات بالضرورة.","xhgb7g":"تذكرة الخروج تكشف ما تعلمه الطلاب وما غمض عليهم فيعدل المعلم الحصة التالية؛ وهذا تقويم تكويني. ليست أداة رصد درجات ولا تصنيف ولا حكم ختامي.","1tqiz4p":"جمع الأعمال بانتظام ومراجعتها بهدف التأمل في التقدم هو ملف الإنجاز (البورتفوليو). السجل القصصي يكتبه المعلم عن سلوك الطالب، والشطب والسلم أدوات رصد أداء.","u8iylf":"التدريج بكلمات وصفية للتكرار هو سلم التقدير اللفظي. العددي يستخدم أرقاماً، والشطب نعم / لا، والروبرك يصف مستويات الجودة لكل معيار.","7ncavz":"الروبرك التحليلي يفصّل الدرجة لكل معيار فيعرف الطالب موضع قوته وضعفه. الكلي أسرع لكنه يعطي حكماً عاماً واحداً، وكلاهما يحتاج محكات مسبقة.","teaev4":"المهارة العملية تُقوَّم بملاحظة الأداء الفعلي بأداة مدرجة. الاختبارات الكتابية تقيس المعرفة بالخطوات لا القدرة على تنفيذها.","sfaffo":"الوصف السردي لكل طالب يستهلك وقتاً ويعتمد على ما يلاحظه المعلم ويفسره. السجل القصصي يناسب السلوك والجوانب الوجدانية في جميع الصفوف ولا يسجل درجات.","m8pg73":"الحوار وجهاً لوجه مع الطالب حول أعماله وتفكيره هو التقويم بالتواصل. ليس اختباراً مقنناً ولا حكماً ختامياً ولا يشارك فيه أقران.","24dkqv":"خريطة المفاهيم تُظهر كيف ينظم الطالب المفاهيم ويربطها، وهذا مؤشر على الفهم العميق. الحفظ الحرفي يُقاس بأسئلة التذكر، والرسم والسرعة ليسا المقصود.","1bgib1t":"التقويم الأصيل يقيس الأداء في مواقف واقعية ذات معنى مع معايير يعرفها الطالب مسبقاً. إخفاء المعايير والاقتصار على التذكر أو الاختيار من متعدد سمات التقويم التقليدي.","1f13eef":"التقويم البديل يعتمد الأداء والملاحظة والملفات وسلالم التقدير بديلاً عن الاختبارات الورقية التقليدية؛ والاختيار من متعدد اختبار تقليدي.","81blt6":"سجل سير التعلم يكتبه الطالب عن تعلمه. السجل القصصي يكتبه المعلم عن سلوك الطالب، وقائمة الشطب وبطاقة الملاحظة أدوات يستخدمها المعلم لرصد الأداء.","1o8bovb":"زيادة الاستجابات تقلل التخمين بالاستبعاد، والتجانس يمنع كشف الإجابة من نوع العنصر. التساوي والخلط وترتيب الإجابات تسهّل التخمين.","1sfmzrh":"الفراغ الواحد في موضع مهم قرب النهاية يجعل المطلوب واضحاً بعد قراءة السياق. النقل الحرفي يشجع الحفظ، وكثرة الفراغات تجعل الجملة مبهمة، والفراغ في البداية يقطع السياق.","d7uc0b":"الفكرة الواحدة تجعل الحكم واضحاً، والنفي المزدوج يربك الطالب. ينبغي توازن الصواب والخطأ، وكلمات الجزم تكشف الإجابة.","1qy00tu":"كلما زادت البدائل الفعالة انخفض احتمال التخمين الصحيح (25% مع أربعة بدائل). تقليل البدائل أو تثبيت موضع الإجابة أو إضعاف المشتتات يرفع التخمين.","4uq2g0":"السؤال لا يحدد عدد الأسباب ولا نطاق الإجابة فيختلف المصححون في تقدير الإجابة؛ والأفضل تقييده مثل: اذكر ثلاثة أسباب. ليس موضوعياً ولا فيه كلمات جزم.","gs2wnu":"الموضوعية قصيرة الإجابة فتغطي محتوى واسعاً بعدد كبير من الفقرات في وقت قصير. المقالية تغطي محتوى محدوداً، والمقابلة وملف الإنجاز لا يناسبان هذا الغرض.","i2leld":"تغيير الموقع عشوائياً يمنع الطالب من اكتشاف نمط يجيب به دون معرفة. أي نمط ثابت يكشف الإجابة ويضعف الصدق.","1g2qix4":"مستوى التقويم يطلب حكماً مع تبرير. الصواب والخطأ حكم بين احتمالين بلا تبرير، ونسبة التخمين فيه 50%، فهو الأقل مناسبة. أما المقالية بنوعيها فتتيح كتابة الحكم وتبريره، والاختيار من متعدد المبني على موقف يقيس الحكم حين تكون بدائله أحكاماً أو مبررات يختار الطالب أقواها.","1c5y1ht":"وزن الوحدة = 6 ÷ 30 = 0.20 أي 20%. عدد أسئلتها = 40 × 0.20 = 8 أسئلة. الخطأ الشائع أخذ عدد الحصص (6) كأنه عدد الأسئلة.","1do19t5":"أسئلة الخلية = العدد الكلي × وزن الموضوع × وزن المستوى = 50 × 0.30 × 0.40 = 6. الرقم 15 هو كل أسئلة الكسور، و20 كل أسئلة الفهم.","qtjxhf":"الوزن النسبي يُشتق من حجم الموضوع في التدريس (حصصه أو أهدافه) وأهميته. الصعوبة والترتيب والرغبة ليست أسساً لتوزيع الأسئلة.","11blrm2":"التعليمات تخبر الطالب بما هو متوقع منه: الزمن وأسلوب الإجابة ومكانها وتوزيع الدرجات. الإجابات والملخص لا مكان لهما في ورقة الاختبار.","ewcvv1":"تصحيح السؤال نفسه عبر كل الأوراق يثبت المعيار ويمنع تأثر الدرجة بالانطباع عن الطالب أو عن إجاباته السابقة. تصحيح الورقة كاملة يقوّي أثر الهالة.","ijqeza":"يبدأ البناء بالأهداف ثم المحتوى، ثم يجمعهما جدول المواصفات، ثم تُكتب الفقرات في ضوئه، ثم التعليمات، ثم التجريب والتحليل.","1vefmno":"الموضوعية هي استقلال الدرجة عن المصحح، وتتحقق بالأسئلة محددة الإجابة ونموذج تصحيح. المقالية الحرة والانطباع وعدم تحديد الدرجات ترفع الذاتية.","1j3k1jo":"نافس تقويم نظامي يقدم مؤشرات عن جودة التعليم وليس اختباراً يترتب عليه نجاح الطالب أو ترتيبه أو شهادته.","t2ex8t":"تاليس استطلاع للمعلمين وقادة المدارس عن ظروف التدريس والتطوير المهني. الاختبارات الأخرى (بيزا، تيمس، بيرلز) تُطبَّق على الطلاب.","10ustjg":"بيزا يقيس الثقافة القرائية والرياضية والعلمية بمعنى القدرة على استخدام المعرفة في الحياة لا استظهار المنهج.","12l56t1":"في الإجراءات التنفيذية للائحة تقويم الطالب 2025 تُقوَّم مواد الصفين الأول والثاني الابتدائي تكوينياً بمستويات أداء (متفوق، متقدم، متمكن، غير مجتاز) تُحدَّد بنسبة معايير المادة التي أتقنها الطالب، ويُعد المعلم برنامجاً علاجياً لمن لم يتقن معياراً أو أكثر؛ فغرضها تحديد الإتقان وتوجيه العلاج، لا ترتيب الطلاب ولا حصر الراسبين ولا مقارنة المدارس.","1jd4oe7":"الصدق الظاهري يتعلق بالشكل العام وهو أضعف الأنواع. التمثيل الكامل صدق محتوى، والمحك المستقبلي تنبؤي، والإطار النظري صدق بناء.","1pa2fsv":"مطابقة الاختبار للإطار النظري للسمة وأبعادها هو صدق البناء (التكوين الفرضي)، ومن أساليبه التحليل العاملي والمقارنة بين المجموعات المتباينة.","1ud9h60":"الصدق الذاتي = الجذر التربيعي لمعامل الثبات = جذر 0.81 = 0.9. الخطأ الشائع إعادة كتابة الثبات نفسه أو تربيعه (0.66).","rrtr2s":"إذا حالت اللغة دون إظهار الطالب ما يعرفه فالدرجة لا تمثل تحصيله الحقيقي، وهذا خلل في الصدق.","j6hv7k":"الاختبار قد يكون صادقاً لقياس القواعد، لكنه غير صادق لقياس القدرة اللغوية الشاملة؛ فالصدق يرتبط بالغرض الذي يُستخدم له.","1lp1zfs":"صدق المحك بنوعيه (التلازمي والتنبؤي) يُحسب بمعامل ارتباط مع محك خارجي. المحتوى والظاهري والمنطقي تُقدَّر بالحكم والتحليل لا بالارتباط.","1g3aqnk":"حكم المحكمين على تمثيل الفقرات للمحتوى والأهداف أسلوب لتقدير صدق المحتوى. الثبات والتمييز يُحسبان من درجات الطلاب، والتنبؤي يحتاج محكاً لاحقاً.","zv6e63":"تنويع المستويات يزيد تمثيل الأهداف فيرفع الصدق. أما الغموض والتطبيق على فئة مختلفة والتلميحات فتجعل الدرجة لا تمثل القدرة الحقيقية.","8yp5mb":"كودر ريتشاردسون (20 و21) مخصصة للفقرات ثنائية التصحيح. ألفا أعم وتناسب المتدرج (ليكرت)، والمعادلات الأخرى لا تقيس الثبات.","y3rnz0":"الفقرات متعددة التدريج تحتاج كرونباخ ألفا. كودر ريتشاردسون للفقرات الثنائية فقط، والصدق الذاتي والصعوبة ليسا طرقاً لحساب الثبات.","1keiss9":"سبيرمان براون: الثبات = (2 × 0.60) ÷ (1 + 0.60) = 1.20 ÷ 1.60 = 0.75. التصحيح يرفع المعامل لأن ارتباط النصفين يمثل ثبات نصف الاختبار فقط.","1am4qtv":"الخطأ المعياري = الانحراف × الجذر التربيعي لـ(1 − الثبات) = 10 × جذر(1 − 0.84) = 10 × جذر(0.16) = 10 × 0.4 = 4.","f68gxr":"الخطأ المعياري يعبر عن تذبذب الدرجة الملاحظة حول الحقيقية؛ وكبره يعني اتساقاً أقل، أي ثباتاً أقل. العلاقة عكسية بينهما.","emurkh":"معامل الثبات ارتباط، والارتباط ينخفض حين يقل التباين؛ فالعينة المتجانسة تعطي ثباتاً أقل. الطول والصعوبة المتوسطة والوضوح عوامل ترفع الثبات.","hqddft":"قصر الفترة بين التطبيقين يجعل الذاكرة ترفع الاتفاق بين الدرجتين فيبدو الثبات أعلى من حقيقته؛ لذلك يُفضَّل فاصل مناسب (نحو أسبوعين).","1no6fy6":"بلا ثبات لا صدق، لكن الثبات وحده لا يضمن الصدق. الشمول والسهولة والطول خصائص مساعدة لا تُعد شرطاً منطقياً للصدق.","vhv2gd":"إذا تأثرت الدرجة بالمصحح اختل اتساقها (الثبات)، وإذا اختل الاتساق لم يقس الاختبار السمة بدقة (الصدق). فالموضوعية في القاعدة والصدق في القمة.","fgmbyu":"الغموض وتفاوت الظروف يدخلان أخطاء عشوائية في الدرجات فيقل الاتساق. الطول وتباين العينة والصعوبة المتوسطة ترفع الثبات.","14dp3lo":"التمييز = (20 − 5) ÷ 27 = 15 ÷ 27 ≈ 0.56، أي ممتاز. القسمة تكون على عدد أفراد إحدى المجموعتين (27) لا على العدد الكلي.","32psis":"التمييز = (6 − 14) ÷ 20 = −0.40؛ الإشارة السالبة تعني أن الضعاف أجابوا أفضل من المتفوقين، وهذا خلل جوهري يستوجب الحذف وإن كانت الصعوبة (20 ÷ 40 = 0.50) متوسطة.","j4d3fl":"إذا انجذب المتفوقون إلى بديل خاطئ فغالباً أن في البديل أو المقدمة غموضاً أو إجابة صحيحة جزئياً، فتُراجع الفقرة.","uwevwk":"الصعوبة = الكل ÷ الكل = 1 (سهلة جداً)، والتمييز = (العليا − الدنيا) ÷ العدد = صفر لأن الفئتين أجابتا بالتساوي. الفقرات شديدة السهولة لا تميز.","jnaxi5":"المدى الشائع في المراجع من 0.20 إلى 0.80، والمثالي قرب 0.50، ودليل الاختبارات 2025 ينصح بالاحتفاظ بالفقرة إذا وقع معاملها بين 30% و70%. أما الفقرات شديدة السهولة (فوق 0.80) أو شديدة الصعوبة (دون 0.20) فلا تميز جيداً.","j01bdu":"الصعوبة = (18 + 8) ÷ (25 + 25) = 26 ÷ 50 = 0.52، فقرة متوسطة. الرقم 0.40 هو معامل التمييز للفقرة نفسها.","1nfm0dc":"حين تكون الصعوبة قرب 0.50 يمكن أن يكون الفرق بين الفئتين أكبر ما يمكن. أما الفقرات التي يجيب عنها الجميع أو لا يجيب عنها أحد فتمييزها يقترب من الصفر.","zxv0kz":"معامل السهولة هو نسبة المصيبين (65%)، ومجموع نسبة المصيبين والمخطئين = 1، فالمخطئون = 1 − 0.65 = 0.35 أي 35%.","1nfnlzg":"النسبة المعتمدة للمجموعتين الطرفيتين 27% من كل طرف بعد الترتيب التنازلي بالدرجة؛ وفي الصفوف الصغيرة يُقسم الصف نصفين.","1cz7rxb":"التباين = مربع الانحراف المعياري = 4 × 4 = 16. الجذر (2) والضعف (8) إجابات خاطئة شائعة.","1lip386":"إضافة ثابت تنقل كل الدرجات بالمقدار نفسه فيزيد المتوسط بالثابت، لكن المسافات بين الدرجات لا تتغير فيبقى الانحراف المعياري كما هو.","wremyb":"البيانات الاسمية لا تُجمع ولا تُرتب فلا يمكن حساب متوسط أو وسيط، ويبقى المنوال (الفئة الأكثر تكراراً) هو المناسب.","173mg75":"الانحراف المعياري يقيس التشتت حول المتوسط؛ وصغره يعني تقارب الدرجات (تجانس). المتوسط المتساوي يعني تحصيلاً متقارباً لا تفوق أحدهما.","1gu1mq1":"الانحراف صفر يعني أن كل الدرجات تساوي المتوسط فلا تشتت. لا علاقة بقيمة المتوسط ولا بالالتواء.","1s3srg7":"المدرج التكراري يعرض تكرار كل فئة من الدرجات ويبين شكل التوزيع. الدائري للنسب من كل، والخطي للتغير عبر الزمن.","tmat34":"الطلاب في 70 إلى 79 عددهم 11، وفي 80 إلى 89 عددهم 7؛ المجموع = 18. الرقم 22 هو من حصلوا على أقل من 70.","1dwxgp2":"نرتب: 3، 5، 7، 9، 12؛ العدد فردي (5 قيم) فالوسيط القيمة الوسطى الثالثة = 7. الرقم 7.2 هو المتوسط الحسابي.","177y8xm":"المدى يعتمد على قيمتين فقط هما الطرفان، فأي قيمة متطرفة واحدة تغيره كلياً؛ بينما الانحراف المعياري والتباين يعتمدان على كل القيم.","1r7oty7":"70 تبعد انحرافين فوق المتوسط. بقاعدة 68–95–99.7 تقع 95% من الدرجات ضمن انحرافين، فالباقي 5% يتوزع على الطرفين، أي نحو 2.5% فوق 70، وهو البديل المقصود بكلمة «تقريباً». والنسبة الدقيقة 2.28%، فلا تناقض بينهما.","1eorapr":"الفترة من المتوسط إلى انحراف واحد فوقه تضم نصف الـ68% أي 34%. 16% هي نسبة من تزيد درجاتهم عن 60.","13fmo0p":"المتوسط أكبر من الوسيط أكبر من المنوال: الذيل نحو اليمين والتكدس عند الدرجات المنخفضة؛ التواء موجب يدل على اختبار صعب.","1xpfgtt":"ت = 50 + 10 × ز = 50 + 10 × (−1) = 50 − 10 = 40. الدرجة التائية تتخلص من الإشارة السالبة وتبقي المعنى (دون المتوسط بانحراف واحد).","1lyy9vo":"العربي: ز = (80 − 70) ÷ 10 = 1. الرياضيات: ز = (65 − 50) ÷ 5 = 3. الدرجة الخام الأعلى لا تعني أداءً نسبياً أفضل؛ المقارنة الصحيحة بالدرجة المعيارية.","6rrvhf":"ز توزيع متوسطه صفر وانحرافه 1. المتوسط 50 والانحراف 10 للدرجة التائية، و100 و15 لنسبة الذكاء الانحرافية.","1stgjh0":"0.2 قيمة منخفضة تدل على ارتباط ضعيف. لا يمكن استنتاج الصدق أو الثبات أو السهولة من ارتباط درجات اختبارين مختلفين.","m4yle1":"الارتباط يصف العلاقة ولا يثبت السببية؛ قد يكون وراء الاثنين عامل ثالث كالقدرة العامة أو الدافعية. أما الاتجاه والقوة والتنبؤ فاستنتاجات مشروعة.","1bbe389":"معامل الارتباط قيمة بين −1 (عكسي تام) و+1 (طردي تام)، والصفر يعني انعدام العلاقة الخطية.","ybas4h":"الدرجة الخام = المتوسط + ز × الانحراف = 50 + 1.5 × 8 = 50 + 12 = 62.","1ta8szf":"الارتباط 0.95 يعني أن ترتيب الطلاب في الاختبارين متقارب جداً. لا يخبرنا عن نسبة النجاح ولا الصعوبة ولا تطابق الأسئلة.","1o713f0":"ت = 50 + 10ز، فإذا كانت ت = 65 فإن ز = (65 − 50) ÷ 10 = 1.5، أي فوق المتوسط بانحراف ونصف.","umxasg":"التدني العام يستدعي تشخيص الأسباب أولاً (الفقرات، المهارات، طريقة التدريس) ثم التعديل. إعادة الاختبار أو التوبيخ أو التسهيل لا تعالج السبب.","aamee1":"التقرير وسيلة شراكة مع الأسرة لدعم تعلم الطالب، فيركز على مستواه وتقدمه وحاجاته. إبراز جهود المعلم يركز على المعلم، والعقاب والمقارنة لا يخدمان التعلم.","15e75a6":"التحليل يكشف الفقرات الضعيفة والمهارات غير المتقنة فيوجه قرارات التدريس. الرصد والترتيب والتبرير نواتج ثانوية لا تمثل الغرض الأساسي.","1t6goum":"الوضوح والإيجاز والتحديد يجعل الطالب يفهم ما يحتاج تحسينه ويطبقه. الثناء العام لا يفيد، والاقتصار على الضعف يحبط، والإطالة تضيع الرسالة.","17puof1":"نتائج التقويم أداة تحسين وتوجيه لا أداة عقاب؛ فالحرمان لا يعالج الضعف بل يزيد النفور. التعديل والتصنيف للدعم والتقارير كلها توظيف سليم.","1idvg7i":"تحليل الفقرات بالتقنية يكشف الفقرات التي تحتاج تعديلاً أو حذفاً فتتحسن جودة الاختبار. لا يغير درجات الطلاب ولا يغني عن التخطيط.","1se6uwl":"التغذية الراجعة الداعمة تبدأ بنقاط القوة ثم توجه إلى خطوات تحسين محددة. الإعلان والمقارنة يحرجان ويحبطان، والدرجة وحدها لا توجه.","1an8kq":"المدخل هو التصور النظري الذي تقوم عليه الطريقة. الطريقة إجراءات تنفيذية، والأسلوب طابع شخصي، والتقنية أداة.","1fcnjc7":"المدخل فلسفة عامة تضم استراتيجيات، والاستراتيجية خطة تضم طرقاً، والطريقة تُنفذ بأساليب شخصية. البدائل الأخرى تقلب العلاقة.","1nwf36o":"يقسم جويس وويل نماذج التدريس إلى أربع عائلات: معالجة المعلومات، والاجتماعية، والشخصية، والنظم السلوكية. والتعليم المبرمج والتعلم للإتقان والتعليم المباشر من عائلة النظم السلوكية، لأنها تقسّم التعلم إلى خطوات صغيرة متتابعة مع تغذية راجعة وتعزيز فوري. أما الاجتماعية فتضم التعلم التعاوني ولعب الأدوار.","izauts":"العائلة الاجتماعية تركز على التعلم من التفاعل مع الآخرين. الشخصية تركز على الفرد وتطوره الذاتي، ومعالجة المعلومات على العمليات العقلية كالاستقراء والمنظم المتقدم.","1qis62p":"الاستنباط (القياس) يسير من القاعدة العامة إلى الحالات الجزئية. الاستقراء يبدأ بالأمثلة ويصل إلى القاعدة، والاكتشاف الحر يترك للطالب تحديد المشكلة والأدوات.","c3uyv0":"العرض العملي يؤدي فيه المعلم المهارة أمام الطلاب ثم يطبقونها، ويناسب المهارات الأدائية. لعب الأدوار تمثيل لموقف اجتماعي، والمحاضرة لا تتضمن أداء المهارة.","8oyzki":"القصة تناسب الصغار وتقدم القيم في موقف حي يثير الخيال. المحاضرة مجردة، والمناظرة تحتاج نضجاً جدلياً، والمبرمج فردي ولا يناسب الأهداف الوجدانية.","11m01ky":"الفروض تفسيرات مؤقتة محتملة للمشكلة. اختبارها يكون بجمع الأدلة والتجريب، والتعميم في الخطوة الأخيرة بعد التحقق.","vnkvdh":"خطوات المشروع: اختيار المشروع، ثم التخطيط، ثم التنفيذ، ثم التقويم. اختيار المشروع يكون بمشاركة الطلاب ليرتبط بميولهم.","1aqdjt9":"المشروع عمل هادف ممتد ينتهي بمنتج (حديقة، مجسم، معرض). الشعور بالمشكلة والفروض من خطوات حل المشكلات، والمشروعات غالباً ميدانية خارج الصف.","g5mqs1":"البرمجة المتشعبة (كراودر) تتفرع حسب استجابة الطالب وتقدم إطارات علاجية. الخطية (سكنر) مسار واحد مستقيم لا يتفرع.","wmmz9i":"التعليم المبرمج فردي ولا ينمي التفاعل الاجتماعي، وهذا من عيوبه. الخطوات الصغيرة والتعزيز الفوري والخطو الذاتي خصائصه الأساسية.","18iyz0u":"الحقيبة التعليمية وحدة تعلم ذاتي متكاملة بهذه المكونات. الرحلة المعرفية بحث موجه عبر الإنترنت، والمحاضرة المسجلة مصدر واحد بلا أنشطة بدائل.","xs7w15":"الموديول (الوحدة النسقية) وحدة صغيرة مستقلة للتعلم الذاتي. التدريس المصغر تدريب للمعلم، والمشروع عمل ممتد، والاستقصاء طريقة بحث.","jqyt41":"المسؤولية الفردية تعني أن كل عضو مسؤول عن تعلمه وإسهامه، ويضمنها المعلم بتوزيع الأدوار والاختبار الفردي. التفاعل والاعتماد قد يكونان موجودين شكلاً مع غياب المحاسبة الفردية.","1jkekz0":"المجموعات غير المتجانسة الصغيرة تتيح تعليم الأقران ومساعدة الضعفاء. المجموعات المتجانسة أو الكبيرة أو مجموعات الأصدقاء تضعف التفاعل والمسؤولية.","1yn131u":"المعلم في التعاوني ميسر يلاحظ ويقدم الدعم عند الحاجة. الشرح الكامل أو حل المهمة يلغي دور المجموعة، والانسحاب التام يفقدها التوجيه.","1cd2iks":"في لعب الأدوار لا يُقاطع المشهد ما دام آمناً؛ فالمناقشة والتقويم مرحلة تلي التمثيل، وقد يُعاد المشهد بعدها. المقاطعة أو الاستبدال يكسران الموقف ويحرجان الطالب.","1kpwf6d":"لعب الأدوار محاكاة لموقف واقعي يتقمص فيه الطلاب أدواراً ثم يناقشونها. العصف توليد أفكار، والتبادلي حوار حول نص مقروء.","1bntas6":"إرجاء الحكم قاعدة أساسية، والمعلم يعيد تثبيتها دون قطع الجلسة. حذف الفكرة أو الدفاع عنها الآن يُدخل التقويم في مرحلة التوليد، والعقاب يوقف تدفق الأفكار.","1uf76yx":"من مزايا تدريس الأقران أن الشرح يعمق فهم القرين المعلّم، وأن المتعلم يستفيد من لغة قريبة منه. حصر الفائدة في طرف واحد يغفل هذه الميزة.","xbtrpu":"التدريس المصغر مصمم لهذا الغرض: مهارة واحدة، وقت قصير، تغذية راجعة، وإعادة أداء. الدورة النظرية والقراءة لا تتيحان الممارسة، والحصة الكاملة تشتت التركيز عن المهارة الواحدة.","nqdulk":"الطالبة تمارس النشاط الحقيقي بنفسها، وهذه الخبرة المباشرة الهادفة في قاعدة المخروط. الخبرة الممثلة دراما، والفيديو والرموز أكثر تجريداً.","1v1boh2":"المحاكاة خبرة بديلة آمنة تقرب التجارب الخطرة أو المكلفة. إجراؤها بحذر أو في المنزل خطر، والوصف الشفهي رمز لفظي ضعيف الأثر.","igkw6d":"الحوار السقراطي يقوم على أسئلة متتابعة تقود المتعلم إلى اكتشاف الحقيقة. المحاضرة تقدم الرأي جاهزاً، والمبرمج خطوات مكتوبة، ولعب الأدوار تمثيل.","x4131b":"المحاضرة تتمركز حول المعلم بوصفه مصدر المعرفة. التعاوني والاكتشاف والمشروعات تنقل النشاط إلى المتعلم.","1dw9itr":"الندوة عرض عدة متخصصين لجوانب موضوع واحد يعقبه نقاش. المناظرة مجموعتان مؤيدة ومعارضة، والعصف توليد أفكار من الطلاب أنفسهم.","2l27l7":"المحاضرة اقتصادية في الوقت وتناسب الأعداد الكبيرة والمحتوى الكثيف، ويُحسّنها دعمها بالعرض والأسئلة. الاكتشاف الحر والمشروعات تحتاج وقتاً طويلاً، ولعب الأدوار لا يناسب المحتوى النظري الكثيف.","15uyv66":"الاستقراء يبني المفهوم أو القاعدة من الأمثلة، فيناسب المفاهيم والتعميمات. الحقائق المنفصلة تُحفظ مباشرة، والمهارات الحركية تحتاج العرض والممارسة.","h2wdwa":"الهدف السلوكي يصف ما سيفعله الطالب بعد التعلم، والصياغة هنا فاعلها المعلم. الفعل «يوضح» سلوكي والمحتوى محدد، والناتج واحد.","t2qvr5":"الهدف السلوكي يصف الناتج الذي يكتسبه الطالب (كأن يستخرج الفكرة الرئيسة)، أما قراءة الدرس فنشاط يؤدى للوصول إلى الناتج. الفعل هنا ملاحظ وفاعله الطالب وناتجه واحد.","tqbzy1":"القاعدة أن يتضمن الهدف ناتج تعلم واحداً؛ وهنا «يذكر» و«يشرح» ناتجان من مستويين مختلفين. الفعلان قابلان للقياس والفاعل هو الطالب.","solhqr":"المعيار هو الحد الأدنى المقبول للأداء. «دون آلة حاسبة» شرط الأداء، و«يحل» الفعل السلوكي، و«مسائل الجمع» المحتوى.","ypxwmj":"الشرط هو الظرف أو الأدوات التي يُؤدى فيها السلوك. «في 10 دقائق» معيار زمني، و«يرسم» الفعل السلوكي.","ste4k6":"الهدف يمتد على فصل كامل ولا يقاس مباشرة في حصة، فهو هدف عام. الغاية أوسع وترتبط بالمجتمع، والسلوكي محدد بحصة.","12lrqw3":"التلخيص وإعادة الصياغة بأسلوب خاص من أفعال الفهم. التذكر يستدعي النص نفسه، والتحليل يفكك، والإبداع يبني جديداً.","fovilu":"إصدار الحكم المبرر وفق معايير هو التقويم. التطبيق حل المسألة، والفهم شرح الخطوات.","efu22i":"التصنيف المعدل ثنائي الأبعاد: العمليات المعرفية (تذكر…إبداع) وأنواع المعرفة الأربعة. البدائل الأخرى مجالات مستقلة لا أبعاداً للمعرفي.","1iqbsr4":"الخطوات والطرائق معرفة إجرائية. الحقائقية مصطلحات وتفاصيل، والمفاهيمية علاقات ونظريات، وما وراء المعرفية وعي الطالب بتفكيره.","1xt9kqa":"الأسئلة الحالية تقيس التذكر فقط، والاختبار الجيد يغطي المستويات العليا وفق جدول المواصفات دون إلغاء التذكر كلياً. تحويل النوع لا يغير المستوى بالضرورة.","18vz863":"يبدأ المجال الوجداني بالانتباه (الاستقبال) ثم المشاركة (الاستجابة) ثم تبني القيمة (التقييم) ثم ترتيب القيم (التنظيم) وينتهي بأن تصبح القيمة سمة ثابتة (التميز بالقيمة).","154t3x8":"الاستقبال هو الانتباه والإصغاء للمثير، وهو أدنى المستويات. الاستجابة تتطلب مشاركة فعلية، والتقييم تبني القيمة.","sitl3k":"التميز بالقيمة أعلى المستويات: تصبح القيمة جزءاً ثابتاً من الشخصية يوجه السلوك باستمرار. الاستجابة مشاركة عند الطلب، والتقييم تبني القيمة دون أن تصير سمة ثابتة بعد.","1sw3y9r":"الاستجابة هي المشاركة الفعلية والتطوع والتفاعل مع الموقف. الاستقبال اهتمام دون فعل، والتنظيم ترتيب منظومة القيم.","4loawo":"سمبسون صاحب التصنيف السباعي للمجال النفس‑حركي (ومعه هارو وديف). كراثوول للوجداني، وبلوم للمعرفي، وماجر لصياغة الهدف السلوكي.","1uqegnc":"الاستجابة الموجهة أداء المهارة بالتقليد والمحاولة تحت توجيه. الآلية أداء بثقة دون توجيه، والمعقدة أداء سلس لمهارة مركبة.","10pbgf4":"التكيف تعديل المهارة المتقنة لمواجهة مواقف جديدة. الإدراك والاستعداد والاستجابة الموجهة مستويات دنيا سابقة للإتقان.","shnn6c":"التهيئة الانتقالية تُستخدم للانتقال السلس بين أجزاء الدرس. التوجيهية في بداية الدرس، والتقويمية تتحقق من الإتقان، والحافزة تثير الاهتمام.","1bd4ia3":"نوع التهيئة يُعرف بغرضها: التقويمية غرضها التحقق من إتقان الطلاب لما سبق قبل البناء عليه، وهذا ما فعله المعلم بأسئلته. وكلمة «الانتقال» في السؤال فخ: التهيئة الانتقالية تسهّل الانتقال وتربط السابق بالجديد دون أن تختبر الإتقان، والتوجيهية توجّه الانتباه إلى موضوع الدرس، والحافزة تثير الاهتمام.","1f3nxmp":"الغلق خطوة ختامية لتلخيص الدرس وتثبيته. التهيئة والتمهيد في البداية، والتقويم القبلي قبل التدريس.","12ek1vk":"التغذية الراجعة الفورية أعلى أثراً، وتأخيرها يفصل بين الأداء ومعرفة النتيجة فيضعف التصحيح. البدائل الأخرى لا تصف أثر التأخير على التعلم.","124mf6v":"التغذية الراجعة العامة لا تخبر الطالب ماذا أحسن وماذا يحسّن. الفورية والتحديد والتركيز على المهمة من خصائصها الجوهرية.","1m72bla":"التغذية الراجعة الوصفية المحددة توضح جوانب القوة والضعف وخطوة التحسين. «ممتاز» وحدها لا تعلّم شيئاً وإن كانت مشجعة.","zv94p2":"الحقيقة معلومة محددة ثابتة قابلة للتحقق. المفهوم تصور مجرد لفئة (الغليان)، والتعميم علاقة بين مفهومين، والمهارة أداء.","t3viue":"التعميم علاقة بين مفهومين أو أكثر تنطبق على حالات كثيرة. الحقيقة معلومة جزئية محددة، والمفهوم كلمة أو تصور مفرد.","8tyq1b":"الوزن النسبي = 6 ÷ 20 = 30%، و30% من 40 = 12 سؤالاً. البديل 6 يخلط عدد الحصص بعدد الأسئلة.","r58x6l":"التوجيهات الواضحة ونمذجة الحل من شروط الواجب الفعال. الإلغاء والمضاعفة لا يعالجان سبب الشكوى، ونقل الحل للأسرة يفقد الواجب غرضه.","edwf74":"الواجب أداة تعلم لا عقاب؛ ربطه بالعقاب يجعله منفراً ويقتل دافعيته. البدائل الأخرى لا تمس الأثر التربوي للإجراء.","11n6988":"المتطلبات السابقة شرط لبناء التعلم الجديد، والتأكد منها جزء من التخطيط. الجهاز والموعد والغياب أمور تنظيمية لا تحدد إمكانية التعلم.","5dzebk":"التخطيط يقوم على الأولوية للأهداف؛ فيُنفذ الأهم ويؤجل الباقي. تحويل الأنشطة كلها واجبات يفرغ الحصة من التطبيق، والحصة الإضافية والتسريع حلول غير منهجية.","8ctalv":"توزيع المقرر على الأسابيع من التخطيط طويل المدى لا من الخطة اليومية. الأهداف والتقويم والوسائل عناصر أساسية في خطة الدرس.","6wgdyz":"التخطيط يراعي مستوى النمو المعرفي؛ فالمحسوسات والنماذج جسر إلى المجرد. التعريفات اللفظية والقراءة وحدها رموز مجردة، والتأجيل يهمل دور التعليم.","1iui5gq":"إصدار الأحكام المبررة وفق معايير هو التقويم. التطبيق استخدام، والفهم تفسير، والتذكر استرجاع.","jxh8sx":"إعطاء مثال من عند الطالب يدل على إدراك المعنى، وهو فهم. التعداد تذكر، والتصميم إبداع، والحكم تقويم.","1oh8pcv":"التصميم إنتاج بناء جديد يجمع عناصر متعددة، وهو الإبداع في التصنيف المعدل. التطبيق استخدام قاعدة في مسألة، والتحليل تفكيك.","ldsidt":"التخطيط خريطة التنفيذ: يحدد الأهداف مسبقاً ويرتب لها الأنشطة والوقت والتقويم، فيمضي الدرس نحوها بلا عشوائية. إرضاء المشرف غاية شكلية، والتخطيط لا يقلل الحصص ولا يغني عن التقويم بل يتضمنه.","ifub0t":"السؤال المحير يثير الاهتمام وحب الاستطلاع، وهذه التهيئة الحافزة. التقويمية تتحقق من إتقان السابق، والانتقالية بين أجزاء الدرس.","y6a10q":"الاستراتيجية تتطلب آلية تحقق ومعالجة سريعة دون إضاعة وقت الحصة. إعادة الشرح الكامل يعيد الصف التقليدي، والمنع عقاب لا يعالج، والإلغاء حل متسرع.","m6u5gy":"العمل الممتد الذي ينتهي بمنتج يُعرض هو التعلم القائم على المشروعات. القائم على المشكلات ينطلق من مشكلة مفتوحة، والاستقصاء العادل مناظرة.","q32yvd":"الاستكشاف مرحلة يعالج فيها الطلاب المواد بأنفسهم قبل الشرح. التفسير يقدم فيه المعلم المفهوم بعد الاستكشاف، والتوسع تطبيق في موقف جديد.","k1x3je":"التوسع تطبيق المفهوم في موقف جديد يعمق الفهم. الانشغال إثارة في البداية، والاستكشاف تجريب قبل الشرح، والتفسير تقديم المفهوم.","49p2sb":"تنويع الأنشطة للوصول إلى المفهوم نفسه هو تمايز العملية. تمايز المحتوى يغير ما يُقدم، والمنتج يغير طريقة إظهار التعلم.","uuc6ku":"أشكال فن مصممة للمقارنة: الشبه في التقاطع والاختلاف في الجانبين. الذهنية لفكرة واحدة، والخط الزمني للأحداث.","xcc0an":"السبر المشجع سلسلة أسئلة متدرجة بعد إجابة خاطئة أو ناقصة تقود الطالب إلى الصواب بنفسه. والفرق عن إعادة الصياغة: إعادة الصياغة سؤال واحد يُعاد بكلمات أوضح، والسبر أسئلة متتابعة جديدة تبني على إجابة الطالب. والتغذية المؤجلة تأتي بعد مدة.","1epa20b":"قِصر زمن الانتظار يمنع الطلاب من التفكير فيجيب المعلم بنفسه. الأسئلة الأسهل والاقتصار على المتفوقين يقللان المشاركة، والإلغاء يفقد أداة مهمة.","mrcqwp":"اختيار المجيب قبل السؤال يجعل بقية الطلاب يتوقفون عن التفكير. البدائل الأخرى لا تعبر عن الغرض التربوي من الترتيب.","16uo8pu":"إعادة التوجيه تحويل السؤال إلى طالب آخر للبناء على الإجابة. التبريري يطلب «لماذا» من المجيب نفسه، وإعادة الصياغة تغيير صياغة السؤال عند عدم الإجابة.","p0q1fe":"في الإتقان يُمنح كل طالب الوقت الذي يحتاجه لبلوغ المعيار نفسه، عكس التقليدي الذي يثبت الزمن فتتفاوت النتائج. التقويم فيها تكويني مستمر.","1qgy5hs":"الحوسبة السحابية تقدم التخزين والتطبيقات كخدمة عبر الإنترنت (قوقل درايف، ون درايف). الواقع المعزز يدمج عناصر رقمية بالواقع.","tmjcqc":"مبدأ التقارب المكاني يقضي بوضع النص قرب الصورة التي يشرحها. التكرار الزائد يتعلق بتقديم النص المكتوب مع الصوت نفسه، والتجزئة بتقسيم العرض إلى أجزاء.","84zuol":"الصوت المنطوق مع الرسوم يوزع الحمل على القناتين السمعية والبصرية. النص المكتوب يزاحم الرسم في القناة البصرية، وتكرار النص مع الصوت نفسه يخالف مبدأ التكرار الزائد.","cfbv68":"مبدأ الاتساق يقضي بحذف الكلمات والصور والأصوات غير المرتبطة لأنها تستهلك الذاكرة العاملة. الزماني يتعلق بتزامن الصوت والصورة، والشخصنة بالأسلوب الحواري.","xivld0":"الاستبدال استخدام التقنية بديلاً مباشراً بلا تغيير وظيفي. التعزيز يضيف تحسيناً، والتعديل يعيد تصميم المهمة، وإعادة التعريف تخلق مهمة مستحيلة سابقاً.","16vz03w":"إعادة التعريف أعلى مستويات SAMR: مهمة جديدة كلياً غير ممكنة بلا تقنية. الاستبدال والتعزيز لا يغيران المهمة، والتعديل يعيد تصميمها دون أن تكون مستحيلة سابقاً.","3yy9yx":"الموقف يتعلق بالخصوصية والاحترام في الفضاء الرقمي، وهو جوهر المواطنة الرقمية. البدائل الأخرى مهارات أو أنماط تقنية لا تعالج السلوك.","rslben":"المنهج الفارغ (ويسمى أيضاً الصفري) عند آيزنر ما لا يُدرَّس للطالب، حُذف عمداً كما هنا أو أُغفل، فيتعلم الطالب بغيابه. الخفي يُتعلم ضمنياً، والرسمي مكتوب ومدرَّس.","ptjdak":"المنهج الرسمي هو المخطط المكتوب المعتمد. الخفي غير مكتوب، والفارغ محذوف، والمختبَر ما يعيشه الطالب فعلاً.","1oduotx":"منهج النشاط لديوي ينطلق من ميول الطلاب ومشكلاتهم. المواد المنفصلة تنظيم تقليدي، والمحوري محور مشترك ومواد اختيارية، والمجالات الواسعة دمج مواد متقاربة.","1b9yhof":"المنهج الحلزوني (برونر) يعيد المفاهيم الأساسية بتعمق متزايد عبر الصفوف. الوحدات تنظيم حول موضوعات، والمحوري محور مشترك.","7a9q5r":"الترابط تنسيق بين مادتين مع بقائهما منفصلتين. الاندماج يصهرهما في مادة واحدة كالاجتماعيات، والمنفصلة لا تنسيق فيها.","vw1ts8":"المنهج المحوري يجمع بين جزء مشترك إلزامي وجزء اختياري. النشاط ينطلق من الميول كلياً، والحلزوني يعيد المفاهيم بتعمق.","1v5gk1i":"هيلدا تابا ترى أن المنهج يُبنى من الأسفل بيد المعلم بدءاً بتشخيص الحاجات. تايلر يبدأ بالأهداف من الأعلى، وبرونر الحلزوني، وبوسنر التغير المفاهيمي.","1cmbgzw":"إدارة الميزانية والادخار من المهارات الحياتية التي تُنمى عبر المواد. الهوية ترتبط بالانتماء، والرقمية بالتقنية، واللغة بالتواصل.","4i3kbk":"ربط المحتوى بتراث الوطن ومناسباته يعزز الهوية الوطنية عبر مادة غير مخصصة لها. البدائل الأخرى أبعاد لا يستهدفها النشاط.","1d1rbrs":"المؤشر ينص على استراتيجيات تلبي حاجات المتعلمين وخصائصهم وتراعي طبيعة الأهداف. التجهيزات والتفضيل الشخصي وطلبات الأسر عوامل ثانوية.","1ahuqc5":"مفهوم التوقعات العالية يقوم على أثر بجماليون (روزنثال وجاكوبسون 1968): ما يتوقعه المعلم من طلابه ينعكس في تعامله معهم، فيرتفع تحصيلهم كلما ارتفعت توقعاته، أي علاقة طردية، وتصير التوقعات نبوءة تحقق ذاتها.","gy4jsu":"إعادة الصياغة تبقي الطالب في الموقف وتؤكد أنه قادر على الوصول للإجابة. نقل السؤال لطالب آخر يوحي بأن المعلم تخلى عنه.","1tfzkkj":"الغباء سبب داخلي يراه الطالب ثابتاً وخارج سيطرته، وهذا أخطر أنواع العزو لأنه يقود إلى العجز المتعلم. عزو الفشل للجهد كان سيبقي الأمل.","1dv9x6o":"عزو النجاح للجهد يرسخ أن النتيجة تحت سيطرة الطالب فيثابر. عزوه للذكاء يجعله يخاف من المهام الصعبة التي قد تكشف عكس ذلك.","cduqhj":"كسر دائرة الفشل يبدأ بخبرة إتقان صغيرة (أقوى مصدر للكفاءة الذاتية) مع تعزيز الجهد. الإعفاء يثبت عجزها، والمقارنة تزيد الإحباط.","1a8hvud":"الأهداف القصيرة الواضحة تمنح نجاحات متتابعة محسوسة، والتحدي المناسب يحفظ الاهتمام. السهلة جداً تُملّ، والبعيدة العامة لا تُشعر بالتقدم.","wznw4x":"الإفراط في المكافآت الخارجية يجعل الطالب يتعلم من أجل الجائزة لا من أجل المعرفة، فتضعف الدافعية الداخلية. التعزيز المادي مفيد مؤقتاً مع الطلاب الذين لا يُحفَّزون داخلياً.","14a891e":"بجماليون (روزنثال وجاكوبسون): من توقع المعلم تفوقه تفوق فعلاً. التقليد نمذجة، والتقريبات تشكيل.","gy2jto":"النجاح الفعلي في مهمة سابقة أقوى دليل للطالب على قدرته. ملاحظة الأقران والإقناع اللفظي مصادر أضعف.","1mduce3":"التعليق الصحيح يسمي نقطة القوة ونقطة التحسين وكيفيتها ويطلب محاولة أخرى. البدائل الأخرى إما حكم عام أو مقارنة بالأقران.","kz0j7r":"الدافعية الداخلية تظهر في المثابرة بلا مقابل خارجي واختيار المهام المتحدية. انتظار المكافأة دافعية خارجية.","1wu1lsa":"حصر الضعاف في الأسئلة السهلة واستعجالهم رسالة ضمنية بأنهم غير قادرين، وهو عكس التوقعات العالية.","1crpj70":"المقارنة بالذات وتحديد أهداف شخصية تؤكد أن كل طالب قادر على التقدم وأن الجهد هو المعيار.","xumbju":"إشراكه في مجموعة ناجحة بدور في متناوله يمنحه خبرة إتقان وانتماء. الإعفاء والتذكير بالجهد لا يقدمان نجاحاً محسوساً، والإعلان عن الدرجات يحرجه.","kjp83a":"إدارة الصف تنظيم شامل للبيئة المادية والنفسية والاجتماعية. حل المشكلات بحزم جزء ضيق منها يركز على الضبط.","1dignz6":"الخوف والطاعة التامة والاحتكار سمات النمط التسلطي، وآثاره اتكالية الطلاب ودافعية خارجية مصدرها الرهبة.","w7z4fc":"التسلط يجعل التعديل في السلوك مرتبطاً بزمن الرهبة، فيفشل الطالب في وضع أهداف لنفسه ويعتمد كلياً على المعلم.","1pbvp4j":"القواعد القليلة الواضحة تُحفظ وتُطبق، والصياغة الإيجابية تصف السلوك المطلوب لا الممنوع، والمشاركة تولد الالتزام.","8oz9kj":"اليقظة withitness هي إدراك كل ما يحدث وإشعار الطلاب بذلك. التداخل معالجة أمرين معاً، والزخم استمرار الدرس بلا توقف.","166fifz":"التداخل overlapping عند كونين هو القدرة على إدارة موقفين متزامنين. اليقظة هي الوعي، أما التداخل فهو الفعل المتزامن.","1nznasc":"أثر الموجة ripple effect: حين يعالج المعلم سلوك طالب بوضوح وهدوء، يضبط الآخرون سلوكهم تلقائياً.","1wczat7":"الانتقالات السلسة من مهارات إدارة الوقت الأكاديمي وتُبنى بإجراءات روتينية مدرَّبة. الإلغاء يضحي بالاستراتيجية، والعقاب يعالج العرض.","6ohckn":"ترتيب المقاعد يتبع نوع النشاط: الصفوف للعرض، والمجموعات للتعاون، وحرف U للنقاش الذي يتطلب تواصلاً بصرياً بين الجميع.","1izi9m7":"عدم التجانس يحقق معاونة الأفراد لبعضهم (الهدف الأول للتعاوني) والأدوار تضمن المسؤولية الفردية. العدد المناسب 4–6.","zh6xth":"المسؤولية الفردية والاعتماد المتبادل شرطا التعلم التعاوني، وتتحققان بالأدوار ومحاسبة كل عضو. حل المجموعة تخلٍّ عن الاستراتيجية.","1fz0n5r":"في التعلم النشط المعلم ميسّر ومرشد: يتابع ويسأل ويوجه دون أن يسيطر أو ينسحب.","1c3s8mj":"الطالب الذي ينهي عمله مبكراً يحتاج مهمة لا عقوبة؛ النشاط الإثرائي يستثمر وقته ويمنع التشويش. الإعادة عقاب على الإنجاز.","7i0ipz":"في الأزمة يبدأ المعلم باحتواء الموقف: يحافظ على هدوئه، ويفصل المتشاجرين، ويشغل بقية الصف، ثم يستمع لكل طرف على انفراد ويرصد المشكلة ويسلمها لإدارة المدرسة، لأن الشجار من مشكلات الدرجة الثانية في الابتدائي والثالثة في المتوسط والثانوي. التحقيق العلني يصعّد، واستدعاء المدير قبل الفصل بينهما يترك الخطر قائماً، والعقاب دون سؤال ظلم.","1b4vb90":"الروتين الثابت يوفر الوقت الضائع في البدايات والنهايات. الاستطراد والتمديد يهدران الوقت.","f96fj2":"الخبرة الصفية الحية للمعلمين الفعالين أقرب مصدر للمعلم الجديد. الجدد يفتقرون إلى الخبرة نفسها، والكتب عن الأسر بعيدة عن إدارة الصف.","1jgng2d":"أُضيف مثير سارّ (الثناء) بعد السلوك فزاد، وهذا تعزيز موجب.","xoqtgt":"التصنيف السلوكي بالعملية: «موجب» يعني إضافة مثير و«سالب» إزالة مثير؛ و«عقاب» يعني أن السلوك قلّ و«تعزيز» أنه زاد. المعلم أضاف التوبيخ فقلّت المقاطعة، فهذا عقاب موجب. وتربوياً التوبيخ العلني مرفوض وإن نجح مؤقتاً.","php3yu":"إزالة الضرر بقدر الخطأ دون أعمال إضافية هو التصحيح البسيط؛ لو كُلف بتنظيف بقية الفصل لصار تصحيحاً زائداً.","ape2yw":"حجب التعزيز (فرصة الإجابة) عن الصياح هو الإطفاء، وإعطاء الفرصة للهادئ تعزيز تفاضلي للبديل. لم يُضف منفّر ولم يُسحب معزز مكتسب.","187mckq":"الانطفاء حجب التعزيز عن السلوك فيتلاشى، وأبرز صوره التجاهل المقصود. الإبعاد إقصاء، والتأنيب عقاب موجب.","1mpulci":"نشاط محبب (القراءة الحرة) اشتُرط بإنهاء نشاط أقل حباً (التمارين)، وهذا بريماك. الاقتصاد الرمزي يحتاج رموزاً تُجمع وتُستبدل.","cea9sa":"المعززات الرمزية (النجوم) التي تُستبدل لاحقاً بمعززات حقيقية هي الاقتصاد الرمزي.","11qxnik":"تعزيز التقريبات المتتابعة نحو السلوك النهائي هو التشكيل (تدرج في الاستجابة). التسلسل تعزيز كل حلقة من حلقات مرتبطة تكوّن سلوكاً عاماً.","1i67bns":"التسلسل يُعلَّم فيه سلوك مركب من حلقات مترابطة، ويُعزَّز المتعلم عند أداء كل حلقة حتى تكتمل السلسلة (مثل خطوات الوضوء أو غسل اليدين). أما التشكيل فيعزز تقريبات متتابعة لسلوك واحد حتى يصل إلى صورته النهائية.","1ajjqyj":"الفورية أهم شروط التعزيز لأنها تربطه بالسلوك مباشرة. التنوع ومراعاة الفروق شرطان آخران، وتقديمه بلا سلوك يفقده معناه.","tefs9o":"المتواصل يبني السلوك الجديد، ثم المتقطع يحافظ عليه ويجعله أكثر مقاومة للانطفاء.","1xfchgz":"التعزيز السالب يزيد السلوك المرغوب بإزالة منفّر. البدائل الثلاثة تقلل السلوك: اثنان عقاب سالب والثالث حجب تعزيز.","wsphuw":"أُزيل مثير يراه الطالب منفّراً (الواجب) بعد سلوك مرغوب لزيادته، وهذا تعزيز سالب.","13oqisz":"الجمع بين إطفاء السلوك غير المرغوب وتعزيز نقيضه هو التعزيز التفاضلي، وهو أفعل من الإطفاء وحده.","10vxac":"العقاب البدني والتشهير ممنوعان: قواعد السلوك والمواظبة 1447 تمنع الإيذاء الجسدي أو النفسي والسخرية من الطالب، وتوجب سرية معلومات المخالف. أما تكلفة الاستجابة والعقد السلوكي والتصحيح الزائد فأساليب تعديل سلوك مقبولة بضوابط.","ko7q4y":"السلوك الذي لا يُعزز يتلاشى، وهذا الانطفاء. لم يُسحب شيء يملكه الطالب فلا عقاب سالب.","11slhca":"الإخراج عزل عن بيئة الصف فهو إقصاء من حيث التصنيف، لكنه يفقد الطالب التعلم ويتركه بلا إشراف وقد يعززه إن كان يكره الحصة؛ لذلك لا يُستخدم الإقصاء إلا داخل الصف ولمدة قصيرة، والطرد كعقوبة مرفوض في اللائحة.","4im8dw":"الإشباع يُضعف أثر المعزز، والحل التنويع (لفظي، رمزي، نشاط) والتناسب مع حجم الاستجابة.","q0i9jg":"الدعم والتدرج يبنيان ثقته. ترك الحرية أو عدم إشراكه يثبتان خجله، والتحويل الفوري تصعيد قبل محاولة المعلم.","1uqo3fm":"الخطوة الأولى المباشرة إيقاف الإساءة وإشعار المعتدي بأن سلوكه مرفوض وستتبعه إجراءات. أما إبلاغ ولي الأمر والإحالة إلى الموجه الطلابي فخطوتان لاحقتان تتولاهما إدارة المدرسة بعد أن يرصد المعلم المشكلة ويسلمها لها، والتجاهل لا يصلح مع الإساءة إلى زميل.","yv1353":"استنفد المعلم إجراءاته داخل الفصل، فيأتي التصعيد المنظم: يرصد المشكلة ويسلمها لإدارة المدرسة، وهي التي تستدعي ولي الأمر وتحيل الطالب إلى الموجه الطلابي (المرشد) لدراسة حالته، ويُطبق الإجراء التالي مباشرة عند التكرار. العقاب الجماعي مرفوض، ونقل المعتدى عليهم يعاقب الضحايا بدل المخالف.","1izcgzd":"المعتدى عليه يحتاج حماية وثقة ومهارات. المواجهة العلنية تزيد الأذى، والرد بالمثل يوسع العنف.","1ljrdfi":"الضحية تنسحب وتتجنب المدرسة وتتراجع درجاتها وقد تشكو آلاماً جسدية متكررة.","1t8y0as":"العقاب الجماعي يظلم الملتزمين ويهدم الثقة بالمعلم، وهو ممنوع تربوياً. البدائل الأخرى أركان البيئة الآمنة.","b2en59":"الخطر الفوري يُوقف أولاً قبل أي إجراء إداري. التسجيل والإبلاغ خطوات لاحقة، والحرمان الطويل عقوبة غير متناسبة.","7wyvsr":"فهم السبب أول خطوة في أي تعديل سلوك، ثم تُبنى خبرات نجاح صغيرة. التحويل والإبلاغ قبل محاولة المعلم تصعيد مبكر.","1pyfffd":"اللائحة تصنف المخالفات بدرجات وتتدرج في الإجراءات وتهدف إلى الانضباط الذاتي لا الردع فقط.","169ezef":"الإشارة المتفق عليها إجراء صفي يضبط الصوت دون قطع النشاط أو عقاب جماعي. رفع الصوت يرفع ضوضاء الصف.","y90rb1":"التشهير إهانة علنية ممنوعة وتولد العناد. التكرار يستدعي الثبات في العواقب والتصعيد المنظم.","1la0kr9":"إيقاف الموقف وإزالة الجمهور (المعزز للعدوان) أولاً، ثم التحقق الهادئ. التسجيل والإبلاغ بعد فهم ما حدث.","hs9zxz":"التنظيم الفيزيائي يتبع النشاط: صفوف للعرض ومجموعات للتعاون. الترتيب حسب الإنجاز أو الخلفية يوسم الطلاب ويضر بالبيئة الآمنة.","iqh0t2":"الاشتباه في إيذاء خارج صلاحية المعلم ويتطلب جهات مختصة بسرية. الاستجواب العلني يؤذي الطالب، والاتصال المباشر بالوالد قد يعرضه لخطر أكبر.","r7mkv":"الطلاب يتأثرون بسلوك المعلم أكثر من أقواله (النمذجة)؛ المعلم الذي يحترم القواعد يجعلها مقبولة.","l48lrv":"العقد السلوكي يشركه في المسؤولية ويحدد التوقعات والعواقب بوضوح. الإحالة تصعيد، والتجاهل لا يصلح مع المتكرر.","1orzgjn":"دراسات ماري رو: 3–5 ثوانٍ تكفي للتفكير دون أن يتحول الصمت إلى إحراج.","14fgfk2":"الرأي والتبرير يحتملان إجابات متعددة، وهذا السؤال المفتوح. المغلق يستدعي معلومة واحدة.","6vo2gu":"الإنصات المتقبل يوفر الأمن والانتماء، وهما شرط البوح. تحقيق الذات قمة الهرم ولا يتحقق بموقف استماع واحد.","1nh5x5y":"الوصفية تسمي ما أُنجز وما يُحسَّن وكيف. «ممتاز» تعزيز عام، والدرجة حكم بلا توجيه.","1xqw7zg":"نجمتان = إيجابيتان، أمنية = جانب تحسين بصيغة لطيفة؛ تحافظ على الدافعية مع توجيه التطوير.","d3l09d":"الإشارات غير اللفظية تشجع دون أن تضعه في بؤرة الاهتمام. التواصل العلني يزيد توتره.","13sgr4o":"المفتوح نمط التعلم التعاوني؛ وحيد الاتجاه محاضرة، وثنائي الاتجاه مناقشة بين المعلم وطالب.","1irbhvl":"الأمان النفسي يقتضي حماية الطالب من السخرية وإكمال فرصته. نقل السؤال أو إجلاسه يؤكد للجميع أن الضحك نجح.","qmzznz":"إعادة الصياغة والإيماء وعدم المقاطعة تُشعر الطالب أنه مسموع ومفهوم.","vx940y":"احترام التنوع يعني إشراك الجميع باحترام. التجميع حسب الخلفية والإعفاء يعزلان ويوسمان.","wm1mgx":"العلاقة الإيجابية تبدأ بالتحية والاسم؛ وهي أبسط إجراءات البيئة الداعمة في الابتدائية خاصة.","qimmsp":"الإنصات أولاً قاعدة التعامل مع ولي الأمر الغاضب، ثم الحقائق بهدوء. الرد الدفاعي يصعّد، والتجاهل والتحويل الفوري تخلٍّ عن التواصل.","9nrxp6":"أي سخرية تولد خوفاً من الخطأ، وهو أكبر معوقات التفاعل اللفظي.","ha3yjq":"مؤشر الهيئة: مجموعات افتراضية مع زملائهم تحت إشراف المعلم وتوجيهه. غياب الإشراف يفقدها هدفها التعليمي.","1o25a3v":"الاستماع مع الاحتفاظ بالرأي ليس تساهلاً؛ هو جوهر الثقافة الداعمة للتعلم التي يشعر فيها الطالب بالقبول.","77m124":"التوزيع العادل مع زمن الانتظار يرسل رسالة أن الجميع متوقع منهم المشاركة. الخصم يولد الخوف، والاكتفاء بالمتطوعين يهمّش البقية.","1ij78f9":"تعزيز الهوية يكون بالحوار الهادئ والشواهد التي تجمع لا تفرق. البدائل الأخرى تُسكت الطالب أو تسخر منه أو تنفي الانتماء للأمة، وكلها تناقض الوسطية.","95ao9e":"القدوة سلوك عملي يراه الطلاب، فالتوقف عن الشرح وترديد الأذان معهم نمذجة مباشرة للقيمة. أما تذكيرهم بواجب المسلم ثم إكمال الشرح فوعظ لفظي يخالفه الفعل، ورواية قصة عن فضل الأذان كلام لا فعل، والاستمرار في الشرح يضيّع الموقف التربوي.","e8kqva":"نظام مكافحة الجرائم المعلوماتية (1428هـ) هو المرجع الجزائي للجرائم الإلكترونية. لائحة السلوك تنظم سلوك الطلاب داخل المدرسة لا الجرائم العامة.","rdh5fr":"الحياد في القضايا الخلافية من أخلاقيات المهنة. فرض الرأي يخالف الحياد، والرفض يقمع السؤال، والتصويت يجعل الفتوى بالأغلبية.","d8ddqf":"الوسطية موقف بين طرفين: الغلو (الزيادة) والتفريط (التقصير). البديل «إرضاء الأغلبية» ميوعة لا وسطية، والامتناع عن الدين يناقض رسالة التعليم.","12iyg9v":"الميثاق يقدم الرقابة الذاتية على كل رقابة خارجية مهما تنوعت أساليبها. المشرف والمدير والتقويم رقابة خارجية.","x8zvns":"الهوية الوطنية الجامعة تُبنى بتحويل الموقف إلى درس في وحدة الوطن مع تنوعه. العقاب العلني يخالف الميثاق، وطلب تغيير اللهجة يحمّل الضحية المسؤولية.","cra8u6":"تعزيز الهوية يكون بالشواهد لا بالوعظ؛ الحقائق والمنجزات تقنع العقل وتحرك الوجدان. الموعظة والحفظ والصور وسائل شكلية أو تلقينية.","192v77t":"الغلو يُعالج بالحوار والدليل والقدوة، وهو دور المعلم أولاً. الثناء يعزز الغلو، والمنع قمع، والإحالة قبل الحوار تخطٍّ لدور المعلم.","xr8m21":"الرؤية تستهدف جودة المخرجات وربطها بسوق العمل وتنمية الشراكة المجتمعية والتعلم مدى الحياة. البدائل الأخرى لا علاقة لها بأهدافها.","18chi1t":"برنامج تنمية القدرات البشرية هو المعني بإعداد مواطن تنافسي عالمياً بالقيم والمعارف والمهارات. جودة الحياة والإسكان والتحول الوطني برامج بأهداف أخرى.","1hs3gtf":"ورد النص في مادة المعلم والمجتمع عند الحديث عن تنمية أهمية التفاعل الإيجابي مع الثقافات الأخرى لدى الطلاب.","3vkv5y":"التفاعل الإيجابي مع الثقافات مع الحفاظ على الثوابت هو جوهر التنوع الثقافي في المعيار. التأجيل دون عودة تجاهل، والنقد إساءة.","10hvt2e":"القدوة نص صريح في مادة المعلم وطلابه من الميثاق، وهي من القيم والأخلاقيات لا من اللوائح الإدارية.","1q1uj4r":"مادة «المعلم وأداؤه المهني» في الميثاق تنص على أن المعلم يغرس مبدأ الاعتدال والتسامح والتعايش بعيداً عن الغلو والتطرف. وقواعد السلوك والمواظبة 1447 تذكر الوسطية والاعتدال الفكري في دور المعلم أيضاً، لكن السؤال يصف بند الميثاق الأخلاقي.","1t37q4e":"العلم والنشيد ويوم التأسيس رموز وطنية جامعة، أما شعار المدرسة فرمز مؤسسي محلي لا وطني.","1gq8dme":"الحياد في القضايا الخلافية واجب مهني، والتوجيه للمصادر الرسمية يحمي الطلاب من التضليل. النقاش المفتوح في قضية خلافية يحوّل الصف إلى ساحة لغير ما يُعنى بتعليمهم.","1f9pz2m":"عرض الوثائق شاهد يقنع ويبني الهوية على المعرفة. الوعظ والتلقين لا يصححان مفهوماً خاطئاً راسخاً.","1o1gob8":"أول ما يفعله المعلم حماية الطالب المتضرر بإيقاف الانتشار فوراً مع توعيتهم بأن ذلك جريمة معلوماتية، ثم إبلاغ الموجه الطلابي (المرشد سابقاً) والإدارة. أما مصادرة ما بحوزة الطالب من مواد ممنوعة وإتلافها فليست قرار المعلم منفرداً، بل إجراء تتخذه لجنة التوجيه الطلابي بعد إحالة الطالب إلى إدارة المدرسة وبمحضر. والتجاهل يترك الضرر قائماً، والعقاب أمام الزملاء يمس الكرامة ويخالف الميثاق.","m6b43g":"هذا البند هو أول بنود مادة «المعلم والمجتمع». مادة «المعلم وطلابه» تتناول العدل والقدوة وتجنب العقاب.","13agsh4":"المشروع يجعل الطالب يبني المعرفة بنفسه ويربطها بالشواهد. الزي والحفظ والعرض الصامت مظاهر لا تبني الانتماء.","uexhuy":"التفريط هو التقصير والتهاون، وهو الطرف المقابل للغلو. الحياد مصطلح يخص القضايا الخلافية لا تطبيق القيم.","bwy1rh":"الازدراء يناقض الوسطية والتسامح المنصوص عليهما في الميثاق. أما لائحة الوظائف وقواعد الانضباط وتعليمات الأنشطة فلا تتناول هذا السلوك بنص مباشر.","119ec8y":"أعلى مستويات المجال الوجداني أن تصبح القيمة طابعاً للشخصية. التنظيم يسبقه (ترتيب القيم في نسق)، والاستقبال والاستجابة أدنى.","1nbmvic":"المراهق يحتاج حواراً بالشواهد وتوجيهاً إلى القنوات النظامية، وهذا جوهر تعزيز الهوية. التهديد يقطع الثقة، والمجاراة تخل بالحياد والقدوة.","tqz26h":"الوثيقة تنص على التربية الخاصة والعناية بالمعوقين جسمياً أو عقلياً (المادة 56)، وتُعنى الدولة بتعليمهم ذهنياً أو جسمياً بمناهج خاصة (المادة 188)، وتضع الجهات المختصة خطة مدروسة لكل فرع (المادة 191): أي رعاية شاملة بلا تفضيل فئة. تقديم الموهوبين أو المعاقين ذهنياً وحدهم أو ترك الرعاية للأهلي يخالف ذلك.","10m3w6l":"اعتُمدت وثيقة سياسة التعليم بقرار مجلس الوزراء رقم 779 وتاريخ 16/9/1389هـ، وتشتهر في المراجع التربوية بأنها صدرت عام 1390هـ، وهو الأقرب بين البدائل. 1427هـ عام الميثاق، و1440هـ عام لائحة الوظائف التعليمية، و1373هـ عام إنشاء وزارة المعارف.","2bduhh":"الميثاق صدر عام 1427هـ. 1428هـ عام نظام مكافحة الجرائم المعلوماتية، فلا تخلط بينهما.","7x9anv":"اللائحة تعرّف الرخصة بأنها وثيقة تصدرها الهيئة وفق معايير محددة. الوزارة جهة التوظيف لا جهة الترخيص.","133ivtl":"تشترط ضوابط الرخص المهنية الدرجة الأدنى في الاختبارين معاً: 50–69 ممارس، و70–79 متقدم، و80 فأكثر خبير، مع استيفاء سنوات الخبرة؛ فحامل البكالوريوس يحتاج 6 سنوات فأكثر لرخصة متقدم و11 سنة فأكثر لرخصة خبير.","4gyypv":"تسري الرخصة المهنية خمس سنوات تبدأ من تاريخ إصدارها أو ترقيتها أو تجديدها. وإذا أُصدرت بعد مرور سنة ميلادية من اجتياز أحدث اختبار فتُحسب السنوات الخمس من نهاية تلك السنة.","4qkynv":"الدرجة تُحسب بأدنى الاختبارين لأن المستوى مطلوب في كليهما؛ 74 تحقق متقدم (70 فأعلى) ولا تحقق خبير (80). لا يوجد تعويض أو درجة موزونة.","4yh5av":"تشترط المادة 10 من لائحة الوظائف التعليمية للترقية أربعة شروط مجتمعة: إمضاء المدة في الرتبة (6 سنوات للبكالوريوس، 5 للماجستير، 4 للدكتوراه)، والرخصة المهنية اللازمة، والحد الأدنى من نقاط التطوير المهني، وتقويم أداء لا يقل عن «جيد جداً» في السنوات الثلاث الأخيرة.","13072ny":"ممارس 24، متقدم 22، خبير 18؛ يقل النصاب بارتفاع الرتبة لإتاحة وقت لمهام التطوير والإسناد.","15mu7u5":"التعريف يربط التطوير بالمعايير المهنية ويجعله عملية منظمة مستمرة لا مجرد دورات أو شهادات.","1bm0xel":"مدة التجربة سنتان يُقوَّم خلالها مرة على الأقل، وإذا لم تثبت صلاحيته تنتهي خدمته.","yxvcd5":"تشترط المادة 10 من لائحة الوظائف التعليمية لحامل البكالوريوس ست سنوات في رتبته قبل ترقيته (5 للماجستير و4 للدكتوراه)، وتُخفض كل مدة سنة واحدة عند الترقية من متقدم إلى خبير. أما ثلاث سنوات فهي مدة تقويم الأداء المطلوبة لا سنوات الرتبة.","1lp9erq":"هذا تعريف «النصاب التعليمي» نصاً في المادة الأولى من لائحة الوظائف التعليمية (بتعديلات 1446)، ويختلف بالرتبة: 24 حصة للممارس، و22 للمتقدم، و18 للخبير (المادة 9). أما «الحصص الصفية» فهي الحصص التدريسية التي يُجمع منها النصاب، و«الحصص الزائدة» ما يُكلَّف به المعلم بعد استيفاء نصابه وبموافقته (المادة 9/3). والمشاركة في التخطيط والتقويم وإدارة الأنشطة والتطوير المهني التزام إضافي في المادة 9/4.","zw5zpu":"تنص قواعد السلوك والمواظبة على إطلاع الطلبة وأولياء أمورهم على القواعد وتسليمهم نسخة منها وأخذ توقيعهم بذلك وفق نموذج الالتزام المدرسي، ويُجدد في بداية كل عام دراسي. ومنسوبو المدرسة (المعلم والموجه والوكيل) يوقّعون بالاطلاع على أدوارهم في تطبيقها، أما تسليم النسخة ونموذج الالتزام فللطالب وولي أمره.","1xy87f4":"تنص المادة 28 من قواعد السلوك والمواظبة 1447 على تطبيقها على ما يقع داخل المدرسة، وفي التعليم الإلكتروني، والبرامج والأنشطة خارجها، وحافلات النقل المدرسي، وفي حدود المدرسة (الشوارع المحاذية لها) إذا رصده منسوبو المدرسة أو كاميراتها. وهذا النطاق لطلاب جميع المراحل في قواعد 1447، وذكر المتوسطة والثانوية في السؤال من صياغة الإصدارات السابقة. لذلك «داخل الأسوار فقط» و«الحافلة فقط» و«أي مكان» كلها خطأ.","1vqiww6":"تنص قواعد السلوك والمواظبة على أن مخالفة الطالب من ذوي الإعاقة في برامج الدمج تتعامل معها لجنة التوجيه الطلابي في المدرسة بالتنسيق مع قسم ذوي الإعاقة في إدارة التعليم، مراعاةً لخصائصه. انفراد المعلم أو المدير أو تركها للأسرة يخالف هذا الإجراء.","1u5bt2c":"الميثاق يلزم المعلم بأن يصون كرامة طلابه (المادة 5، البند 5)، ومدونة السلوك 1447 توجب التعامل مع المعلومات الشخصية للطلاب بسرية تامة وتحظر إفشاء ما فيه خصوصية. أما النمو المهني وروح الفريق والتعاون مع المجتمع فواجبات لا صلة لها بالسرية.","frw4vy":"نص المادة الخامسة صريح في استثمار وقت الطالب وعدم تحويل الدرس إلى منبر لغير التعليم.","5lg759":"الميثاق يرفض العقاب البدني والنفسي معاً. البديل «النفسي مقبول» فخ لأن النص يذكرهما معاً.","hfcux0":"المادة الثامنة (المعلم والأسرة) تجعل المعلم شريكاً للوالدين ويوطد الثقة بين البيت والمدرسة.","wij3bi":"مادة المعلم والمجتمع المدرسي تنص على الثقة وروح الفريق. المنافسة الفردية تناقض ثقافة التعاون.","12o00as":"المادة الرابعة تجعل النمو المهني واجباً أساسياً على المعلم نفسه، لا خياراً ولا مسؤولية الإدارة.","bzhfge":"الميثاق يعد احترام قواعد السلوك الوظيفي والالتزام بالأنظمة ركناً أساسياً. الاعتراض يكون عبر قنوات التظلم لا بالامتناع.","1xgg3bn":"الغاية في المادة 28 تبدأ بفهم الإسلام وغرس العقيدة ثم القيم والمعارف والمهارات. سوق العمل هدف من أهداف رؤية 2030 لا الغاية الأصلية للوثيقة.","1mrpk6q":"السلم التعليمي اثنا عشر صفاً: 6 + 3 + 3.","1ujkmi1":"أعلنت وزارة التعليم لعام 1448هـ قبول من أكمل ست سنوات حتى 24 أغسطس 2020م، وقبول مواليد 25 أغسطس إلى 22 نوفمبر 2020م (نحو تسعين يوماً أصغر) بشرط إتمام سنة في رياض الأطفال. فالشرط الروضة، لا اختبار قبول ولا موافقة ولي الأمر وحدها.","nu12sh":"المواظبة من قواعد السلوك الوظيفي التي عدها الميثاق ركناً في تحقيق أهداف المؤسسة.","ecv56p":"بيانات الطلاب لا تخرج إلا بإذن الإدارة ووفق النظام. حذف الأسماء لا يغني عن الإذن، والرفض المطلق يعطل التعاون البحثي المشروع.","g8syao":"التعديل (القرار الوزاري 63694 بتاريخ 5/5/1446هـ) جعل الرخصة شرطاً لمزاولة المهنة من 1 فبراير 2026 وألغى ربطها بالعلاوة، مع إعفاء من بلغ الخمسين من العمر قبل ذلك التاريخ.","z40tbj":"الأربعون يوماً داخل حد الاستثناء (90 يوماً)، فيجوز قبوله استثناءً لا مباشرةً مثل أقرانه، والأولوية لمن أتموا السادسة. وفي إعلان الوزارة لتسجيل 1448 يُشترط لهذا الاستثناء أن يكون الطفل قد أتم عاماً دراسياً كاملاً في رياض الأطفال. أما «لا يجوز بأي حال» فيتجاهل الاستثناء، ولا يوجد اختبار ذكاء للقبول.","1acq2ku":"مادة المعلم والمجتمع المدرسي تجعل المشاركة في نشاطات المدرسة ركناً أساسياً إلى جانب الالتزام بالأنظمة.","wy2uad":"الأسس العامة في الباب الأول من وثيقة السياسة، وأولها (المادة 2) الإيمان بالله رباً وبالإسلام ديناً وبمحمد صلى الله عليه وسلم نبياً ورسولاً، ثم التصور الإسلامي للكون والإنسان والحياة (المادة 3). أما فرض الرسوم فيناقض المادة 233 (التعليم مجاني)، والوثيقة لم تجعل الثانوي إلزامياً، ولغة التعليم فيها العربية.","1ethj1b":"اللائحة تنظم التظلم بإجراءات رسمية. الامتناع عن العمل أو التشهير مخالفة للسلوك الوظيفي.","15adu2v":"هذا تعريف المعايير المهنية الصادرة عن الهيئة. الرخصة وثيقة، والتطوير عملية، والنصاب حصص.","1a2hodp":"قواعد السلوك والمواظبة 1447 تشرك ولي الأمر في المتابعة: يُشعَر بالمشكلة ويُدعى للاتفاق على خطة تعديل السلوك، ويوقّع مع الطالب ومدير المدرسة نموذج «التعهد السلوكي» بعدم التكرار، ويُوثَّق رفضه إن رفض. أما شهادة حسن السيرة وطلب النقل وتقويم المعلم فلا صلة لها بإجراءات المخالفة.","csj2r":"المعلم قدوة؛ استهانته بالنظام تُعلّم الطلاب الاستهانة به. البدائل الأخرى آثار جانبية أقل خطورة.","r4l0hh":"الزيارات أسلوب مباشر لتطوير الأداء. «الافتراضية» خاطئة لأن الزيارة حضورية، والمدرسة المتعلمة مفهوم أوسع لا يقتصر على الزيارات.","1amaxa0":"الأسلوب الذاتي في التطوير المهني يقوم به المعلم وحده وبمبادرته وبحسب سرعته، مثل القراءة الحرة والتعليم المبرمج والحقائب التدريبية. أما الزيارات المتبادلة والاجتماعات المهنية والدروس النموذجية (التطبيقية) فمن الأساليب الإشرافية الجماعية التي تنظمها المدرسة أو المشرف ويشترك فيها أكثر من معلم.","mqdb9s":"سؤال من دليل الهيئة: المعلم الجديد يفتقر إلى الخبرة بالأساليب، وزيارة الخبراء تطلعه على الأساليب الناجحة. البدائل الأخرى فوائد ثانوية.","1iv4hvl":"السؤال مأخوذ من دليل الاختبار العام للمعلمين (قياس 1436، السؤال 2) ومفتاحه في الدليل: اجتماع يضم ولي الأمر والمختص في صعوبات التعلم بالمدرسة. فتحديد وجود صعوبة تعلم يحتاج تشخيصاً من مختص بعد موافقة ولي الأمر، وليس من صلاحية المعلم أن يجيب بنعم أو لا عبر البريد.","14wiz9m":"سؤال من دليل الهيئة (3.1): مجتمع التعلم يركز على تعلم الطلاب. إزالة الإحباط بديل يركز على المعلم لا على أثر اللقاء في الطالب.","qj1oij":"مجتمعات التعلم تتيح تجريب الاستراتيجيات في مواقف مختلفة وتبادل الخبرات باستمرار. المؤتمرات موسمية، والتنافس يناقض ثقافة التعاون.","j2kgpr":"الأطراف وشروط النجاح هي مقومات (أركان) الشراكة. الخصائص تصف طبيعتها، والمتطلبات إجراءات تفعيلها.","1lq6jkm":"فلسفة النشاط غير الصفي تقوم على الميول والطوعية والفروق الفردية. التوحيد والإلزام والحصر في الكتاب تناقضها.","3d9l1d":"المبادئ الأربعة: رؤية مشتركة، ثقافة تعاون، تركيز على تعلم الطلاب، تركيز على النتائج. التنافس والتقويم للترقية يناقضان ثقافة التعاون.","1j7exxu":"الأوعية هي صيغ عمل المجتمع المهني: التدريب المباشر، الورش، المؤتمرات، البحوث الإجرائية، التدريب بالأقران، التوأمة، الشبكات، مجموعات التخصص.","1gpdpma":"عوامل النجاح: نظام فاعل للتطبيق، قيادة داعمة، بنية تنظيمية داعمة. زيادة الحصص تحرم المعلم من وقت التعاون.","19viocb":"الشراكة أوسع من المال؛ تشمل الفكر والمشورة والموارد البشرية، والعلاقة تبادلية. التبرعات صورة واحدة منها.","4keg3u":"العلاقة التي تُبنى على المشكلات فقط تجعل ولي الأمر يتجنب المدرسة. التواصل الإيجابي المستمر والدعوة للفعاليات يبنيان الثقة.","zz7dsw":"الإنصات ثم الأدلة الموثقة مع الحفاظ على سرية اللقاء وعدم الحديث أمام الطفل. المواجهة أمام الوالد تحرج الطالب وتفقد الثقة.","sza88x":"الأدبيات تذكر الإسناد والبيئة الداعمة للمستجدين كمزية صريحة. الإعفاءات ليست من وظائف مجتمع التعلم.","rl9luf":"المجتمع المحيط يشمل كل من حول المدرسة من جهات وأفراد قادرين على الدعم، والعلاقة تبادلية.","1w9yv8x":"المعيار الفرعي 3.2 (التفاعل مع أولياء الأمور) يتضمن مؤشر توظيف التواصل الإيجابي في تحفيز أولياء الأمور على الإسهام بخبراتهم وعلمهم وقدراتهم في دعم برامج التعلم (من مؤشرات المعلم المتقدم). أما 1.3 فيخص الأخلاق المهنية واللوائح، والمعيار 2 التطوير المهني، والمعيار 10 التقويم.","u3soqh":"النتائج الموثقة: تحصيل أعلى، تسرب أقل، دعم أكبر من أولياء الأمور، معنويات أعلى. البدائل الأخرى آثار سلبية أو غير واردة.","m8l4b4":"تنص المادة 68 على أن النظام يُعمل به بعد 180 يوماً من تاريخ نشره في الجريدة الرسمية. والمدة تُحسب من تاريخ النشر، لا من تاريخ المرسوم. والسنة مدة أخرى تخص الفترة الانتقالية للوثائق الملغاة.","1tpj37f":"البند الثاني من قرار مجلس الوزراء رقم 103، ومثله البند الثاني من المرسوم م/36، ينص على أن مجلس شؤون التعليم العام يمارس اختصاصاته من تاريخ نشر النظام في الجريدة الرسمية. أما بقية أحكام النظام فيبدأ العمل بها بعد 180 يوماً (المادة 68).","xdtamu":"قرار مجلس الوزراء رقم 103 (البند 4) ألغى السياسة العامة للتعليم الصادرة بالقرار 779 وتاريخ 1389/9/16هـ. وفي البند 5 أبقى أحكامها سارية حتى يقر مجلس شؤون التعليم العام البديل، خلال مدة لا تتجاوز سنة من نفاذ النظام.","1ypp098":"عرّفت المادة 1 الطفولة المبكرة بأنها التعليم والرعاية من بداية الحضانة حتى نهاية الصف الثالث. والخيار الذي يقف عند نهاية الروضة خطأ شائع، لأن المرحلة في النظام تشمل الصفوف الثلاثة الأولى.","mt0241":"تنص المادة 4/1 على أن سن التعليم الإلزامي تبدأ من السنة السادسة حتى الخامسة عشرة. أما «حتى نهاية الصف الثاني عشر» فهو حد التعليم العام كله (المادة 1)، لا حد الإلزام.","kj1e09":"الطالب في سن الإلزام (من 6 إلى 15 سنة، المادة 4/1). والمادة 4/2 تنص على أن الوزارة، بالتنسيق مع الجهات المختصة، تتخذ الإجراءات النظامية تجاه من يتسبب في حرمان الطفل من التعليم أو انقطاعه عنه خلال سنوات الإلزام.","1tohmfc":"عرّفت المادة 1 المعلم بأنه «من يُرخَّص له بالعمل في مهنة التعليم العام»، فالتعريف مربوط بالترخيص. أما المؤهل والتعيين والتدريس الفعلي فلا تكفي وحدها بحسب نص التعريف.","p1zmrc":"في المادة 1: المقرر الدراسي هو المحتوى. أما المنهج التعليمي فهو أهداف مخطط لها تحقق نواتج مقصودة يُتأكد منها بالتقويم، والبرنامج التعليمي نشاط يُنظَّم في إطار المنهج لتحقيق أهداف محددة في مجال محدد.","1aqb0fb":"الفقرة 7 من المادة 2 تنص على تنمية الوعي الفكري، وتطوير مهارات التحصن من التيارات والتوجهات المنحرفة، والتعامل الواعي مع المحتوى الإعلامي بمختلف صوره. والنشاط يدرب الطلاب على ذلك مباشرة.","1oplepb":"تنص المادة 5 على أن اللغة العربية هي اللغة الأساس للتعليم العام، وأنه يجوز التعليم بلغة إضافية وفق ضوابط يقرها مجلس شؤون التعليم العام.","djy552":"تنص المادة 7 على إنشاء المجلس برئاسة الوزير، ويكون نائب الوزير للتعليم العام نائباً للرئيس، ورئيس هيئة تقويم التعليم والتدريب عضواً فيه.","1mf0ili":"الفقرة 2 من المادة 8 تجعل تحديد سن القبول من اختصاص المجلس، وكذلك اقتراح تعديل حدّي سنوات الإلزام (المادة 8/3).","2jdxue":"المادة 46 تجيز للوزارة تكليف معلمين في المؤسسات الحكومية بتدريس مقررات خارج تخصصاتهم وفق القواعد الواردة في الفقرة 4 من المادة 8. وهذه القواعد يقرها المجلس، وتتضمن المزايا المالية والمتطلبات المهنية اللازمة.","1dukz9m":"تنص المادة 24 على أن التعليم حضوري في جميع مراحل التعليم العام، وأن للوزارة الاستفادة من تقنيات التعليم بوصفها جزءاً من التعليم الحضوري وفق ضوابط استخدام التعليم الإلكتروني المعتمدة.","17errdz":"تنص المادة 20 على دمج الطلاب ذوي الإعاقة في المؤسسات التعليمية، وتوفير الوسائل المناسبة لهم، وتقويمهم بأساليب تراعي خصائصهم واحتياجاتهم وقدراتهم، مع توفير التقنيات المساعدة والتكيفية. أما المراكز المتخصصة فهي لمن يتعذر دمجه (المادة 21).","o1p7sq":"تنص المادة 23 على أن ضوابط التسريع تشمل معايير واضحة لتحديد الطلاب المؤهلين، وإجراءات تقويم شاملة، وتدريب المعلمين، وتعزيز التنسيق مع أولياء الأمور، بما يضمن استمرار التفوق والتكيف مع المرحلة الجديدة.","13vwaq4":"تنص المادة 27 على أن الوزارة وهيئة تقويم التعليم والتدريب تشتركان مع المركز الوطني للمناهج في إعداد الإطار الوطني لمناهج التعليم العام.","znm681":"تنص المادة 30/2 على أن المؤسسات التعليمية الخاصة ملزمة بالحصول على الاعتماد المدرسي من هيئة تقويم التعليم والتدريب، أو من إحدى الهيئات الدولية التي تعتمدها الهيئة. واعتماد الوزارة للبرنامج الدولي (المادة 28) أمر مستقل عن ذلك.","z5dzt3":"تنص المادة 31 على أن الوزارة تشرف على المؤسسات التعليمية الخاصة بما يضمن تحقيق أمور، منها (الفقرة 4) تدريس مواد الهوية الوطنية التي يعتمدها المركز الوطني للمناهج.","k8mg63":"تنص المادة 32/2 على أن الوزارة تبلغ طالب الترخيص بقرارها كتابةً خلال 30 يوماً من تقديم طلبه، وإذا صدر القرار بالرفض وجب أن يكون مسبباً، ولطالب الترخيص حق التظلم.","6y29mo":"تحدد المادة 60 جزاءات المؤسسات الخاصة بحسب تصنيف المجلس لجسامة المخالفة: الإنذار، وإيقاف تسجيل الطلاب، وغرامة من 5,000 إلى 50,000 ريال، وإلغاء الترخيص مع إكمال العام الدراسي للطلاب المقيدين على نفقة المالك.","3iirei":"من حقوق الطالب في المادة 38/1 (الفقرة ز) تسلّم شهادة النجاح بعد إتمام السنة الدراسية دون قيد أو شرط. وموضوع الكتاب تعالجه المدرسة بطريق آخر، ولا يُربط بالشهادة.","b87xhz":"تنص المادة 38/1 (الفقرة د) على حق الطالب في ألا يُكلَّف بأي عمل ناتج عن اجتهاد فردي من المعلم أو الكادر الإداري داخل المؤسسة التعليمية لا يتفق مع أحكام النظام واللوائح.","1yeyhvt":"من حقوق الطالب في المادة 38/1 (الفقرة ج): سماع شكواه، وقيدها، واتخاذ الإجراء اللازم حيالها. فالإجراء الكامل له ثلاث خطوات، والاكتفاء بالسماع أو التأجيل لا يحققه.","ehm2hv":"تنص المادة 38/2 على التزامات الطالب: احترام المعلمين والهيئة الإدارية وزملائه، والحضور والانصراف في الأوقات المحددة، وبذل الجهد والتعاون البنّاء، وعدم الإضرار بالمدرسة وتجهيزاتها، والالتزام بقواعد السلوك والمواظبة.","au3aav":"تنص المادة 49/3 على أن على المعلم تمثيل القدوة الحسنة للطلاب خُلقاً، والالتزام بقيم الهوية الوطنية، والابتعاد عن كل ما يمس شرف المهنة داخل المدرسة وخارجها، والالتزام بميثاق أخلاقيات مهنة التعليم.","7mvs4f":"تنص المادة 49/2 على أن يراعي المعلم طبيعة الطلاب واهتماماتهم واستعدادهم ومستويات تفكيرهم والفروق الفردية بينهم، وأن يحقق أعلى مستويات العدالة في التعامل معهم، ويعزز ثقتهم بأنفسهم.","1f3v5x":"تنص المادة 48 على أن توفر الوزارة للمعلم في المؤسسات الحكومية: البيئة التعليمية المناسبة، وبرامج التدريب والتطوير المهني ومنها تقنيات التعليم الحديثة وأساليب التعليم التفاعلي، وفرص الإسهام في تطوير التعليم، والجوائز والحوافز عند التميز.","1lsrnd7":"تنص المادة 65 على أن على إدارة المؤسسة التعليمية إبلاغ الجهة المختصة عن أي اعتداء أو إيذاء يقع داخل المؤسسة أو في محيطها على أي من طلابها أو منسوبيها، لاستكمال الإجراءات النظامية. ومحيط المدرسة داخل في النص.","19zbi2k":"المادة 65 تنص على الإبلاغ عن أي اعتداء أو إيذاء يقع على أي من طلاب المؤسسة أو منسوبيها، والمعلم من منسوبيها. والمُلزَم بالإبلاغ إدارة المؤسسة، دون أن يُعلَّق الواجب على طلب كتابي.","1n4b6ec":"تنص المادة 59/2 على أنه إذا ثبت ارتكاب مخالفة جسيمة تنهى خدمته، ولا يسمح له بالعودة للعمل في المجال التعليمي في القطاعين العام والخاص. أما الإنهاء عند التكرار فهو حكم المخالفة غير الجسيمة (المادة 59/1).","na72b1":"تنص المادة 58 على أنه إذا وُجدت قرائن تدل على ارتكاب ما يخل بالنظام العام أو اللحمة الوطنية، فللوزير أو من يفوضه اتخاذ تدابير عاجلة لحماية البيئة التعليمية إلى أن يُفصل في المخالفة، منها منعه من أي عمل داخل المؤسسة وتكليفه بعمل خارجها، أو كف يده مؤقتاً في المؤسسة الحكومية.","10mr4i2":"تنص المادة 63 على أنه يجوز لمن صدر في حقه قرار بالجزاء التظلم منه أمام الجهة القضائية المختصة خلال 60 يوماً من تاريخ العلم به.","jvnddj":"تنص المادة 50 على أن تضع الوزارة الضوابط اللازمة التي تعزز الشراكة بين المؤسسة التعليمية والأسرة، بما يمكّن أولياء الأمور من المشاركة والإسهام في تحقيق أهداف التعليم العام.","1rrqlv0":"تنص المادة 67 على أنه مع عدم الإخلال باختصاصات المجلس، تضع الوزارة بالتنسيق مع من تراه من الجهات ذات العلاقة ما يلزم من لوائح لتنفيذ أحكام النظام، وتصدر بقرار من الوزير. أما لوائح بعينها، كلوائح المؤسسات الخاصة والافتراضية وذوي الإعاقة والحضانة، فيقرها المجلس (المادة 8).","4pydv5":"الاستجابة الموضحة سؤال قصير يرد به المعلم على عبارة الطالب، فيدفعه إلى التفكير في قيمته بنفسه دون وعظ أو حكم، وهي من أساليب مدخل توضيح القيم (راث وهارمن وسايمون). المحاكمة العقلية مناقشة منظمة لأدلة طرفين، والتلقين يفرض القيمة من الخارج، ولعب الأدوار تمثيل لموقف لم يحدث هنا.","1xuirj2":"المحاكمة العقلية تعرض قضية قيمية، ويناقش الطلاب الأدلة المؤيدة والمعارضة حتى يصلوا إلى حكم مسبَّب، وتناسب المرحلة الثانوية لأنها تتطلب تفكيراً مجرداً. الاستجابة الموضحة سؤال فردي قصير، والقصة والقدوة أسلوبان غير مباشرين لا يقومان على موازنة الأدلة.","6s60n4":"قال جون لوك إن العقل يولد صفحة بيضاء تكتب عليها الخبرة، فأكد أثر البيئة والتعليم والحواس. روسو رأى الطفل خيّراً بطبعه وأن التربية الطبيعية تحفظه، وبياجيه رأى الطفل يبني معرفته بنشاطه في مراحل نمائية، وفرويد فسر الشخصية بالدوافع اللاشعورية.","toy7me":"الحبسة الكلامية (الأفازيا) اضطراب لغوي مكتسب بسبب إصابة في الدماغ. في الحبسة التعبيرية يبقى الفهم جيداً ويضطرب إنتاج الكلام، وفي الاستقبالية يضطرب فهم الكلام وقد يتكلم المصاب بطلاقة كلاماً بلا معنى. التأتأة اضطراب في انسياب الكلام لا في اللغة، وعسر القراءة صعوبة تعلم في القراءة.","1bcombd":"الإزاحة (النقل) توجيه الانفعال من مصدره الأصلي الذي يصعب مواجهته إلى هدف أضعف أو أكثر أماناً. الإسقاط نسبة المشاعر غير المقبولة إلى الآخرين، والتبرير اختلاق أسباب مقبولة للسلوك، والنكوص رجوع إلى سلوك مرحلة عمرية سابقة. وحيل الدفاع أساليب لا شعورية لخفض القلق وصفها فرويد وفصّلتها ابنته آنا فرويد.","2eozvz":"الإسقاط أن ينسب الفرد إلى غيره مشاعر أو عيوباً يرفض الاعتراف بها في نفسه، فالطالب نسب كراهيته إلى زميله. الإزاحة تحويل الانفعال إلى هدف آخر، والتعويض سد نقص في مجال بالتفوق في غيره، والتسامي تحويل الدافع غير المقبول إلى نشاط مقبول.","tqiuwo":"التعويض أن يغطي الفرد نقصاً يشعر به في مجال بالتفوق في مجال آخر. والتسامي قريب منه، لكنه تحويل دافع غير مقبول اجتماعياً كالعدوان إلى نشاط مقبول، ولا يوجد هنا دافع غير مقبول بل شعور بالنقص. الإسقاط والإزاحة يتعلقان بتوجيه المشاعر نحو الآخرين.","yxuxrx":"التسامي (ويسمى الإعلاء) تحويل دافع غير مقبول اجتماعياً كالعدوان إلى نشاط مقبول ومفيد، ويُعد من أنضج حيل الدفاع. الإزاحة قريبة، لكنها تنقل الانفعال إلى هدف أضعف دون أن يصير نشاطاً مقبولاً. والتعويض سد نقص بالتفوق في مجال آخر، والتبرير اختلاق أسباب مقبولة للسلوك.","1sdtta0":"الانتباه الموزع (ويسمى المنقسم) توجيه الانتباه إلى أكثر من مثير أو مهمة في الوقت نفسه. الانتقائي تركيز على مثير واحد وتجاهل غيره، والمتناوب تحويل الانتباه بين مهمتين واحدة بعد الأخرى، والقسري (اللاإرادي) انتباه يفرضه مثير قوي مفاجئ كصوت عالٍ.","jyqfsp":"هرم جانييه يبدأ بالتعلم الإشاري، ثم المثير والاستجابة، ثم التسلسل الحركي، ثم الترابط اللفظي، ثم التمييز، ثم المفاهيم، ثم المبادئ، وينتهي بحل المشكلات. فحل المشكلات يتطلب إتقان المبادئ، والمبادئ تتطلب المفاهيم، ولهذا يبدأ المعلم بالمتطلبات السابقة للدرس.","5p1gs2":"نموذج كيلر للدافعية (ARCS) أربعة عناصر: الانتباه، والصلة بحياة المتعلم، والثقة بقدرته على النجاح، والرضا عن نتائج تعلمه. المهام المتدرجة تبني الثقة لأنها تضمن نجاحاً مبكراً. أما ربط الدرس بالخصومات فيحقق الصلة، وإعلان الإنجاز يحقق الرضا، والانتباه يُثار بالمفاجأة والتنويع.","1iayk6a":"اتخاذ القرار من مهارات التفكير المركب، ويقوم على وضع بدائل وموازنتها وفق معايير ثم اختيار الأنسب وتبريره. والمقارنة والتصنيف والملاحظة مهارات تفكير أساسية قد تدخل في النشاط، لكنها ليست غايته، فالنشاط ينتهي باختيار مسبَّب. ومن مهارات التفكير المركب أيضاً التفكير الناقد والإبداعي وحل المشكلات.","184smdu":"التدريب الاستقصائي لسوشمان يبدأ بحدث متناقض يثير الحيرة، ثم يجمع الطلاب المعلومات بأسئلة إجابتها نعم أو لا، ثم يصوغون الفروض ويختبرونها حتى يفسروا الحدث. الاكتشاف الحر لا يقيد الأسئلة ولا يبدأ بتناقض مقصود، والعصف الذهني توليد أفكار دون تقييم، والمشروع مهمة ممتدة تنتهي بمنتج.","qx4izp":"نموذج آشور (ASSURE) لهاينك وموليندا ورسل ست خطوات: تحليل خصائص المتعلمين، ثم صياغة الأهداف، ثم اختيار الطرق والوسائط والمواد، ثم استخدامها، ثم إشراك المتعلمين، ثم التقويم والمراجعة. واسم النموذج مأخوذ من الحروف الأولى لهذه الخطوات بالإنجليزية.","1yj7z4":"أبعاد التعلم عند مارزانو خمسة: الاتجاهات والإدراكات الإيجابية نحو التعلم، واكتساب المعرفة وتكاملها، وتعميق المعرفة وصقلها، والاستخدام ذو المعنى للمعرفة، وعادات العقل المنتجة. والمقارنة والتصنيف والتجريد من عمليات بُعد التعميق والصقل، أما الاستخدام ذو المعنى فيكون بحل مشكلة أو اتخاذ قرار أو بحث.","27ho0d":"استراتيجية روبنسون خمس خطوات: المسح، والسؤال، والقراءة، والتسميع، والمراجعة، ويرمز لها بالحروف الأولى من أسمائها بالإنجليزية. أما جدول أعرف وأريد أن أعرف وتعلمت فينظم المعرفة السابقة والمكتسبة، والتدريس التبادلي حوار جماعي بأربع استراتيجيات، وفكر وزاوج وشارك نقاش ثنائي.","6cuywp":"مدخل ستيم يدمج العلوم والتقنية والهندسة والرياضيات في مشروع تطبيقي يصمم فيه الطلاب حلاً ويجربونه ويحسنونه، وهو ما في الموقف: تصميم هندسي وحساب رياضي وتجريب علمي. الاكتشاف الموجه يصل فيه الطالب إلى مفهوم بتوجيه المعلم، والمنهج المحوري تنظيم للمنهج كله، والتعلم بالأقران تعليم الطلاب بعضهم بعضاً.","cjsqcr":"نظام فلاندرز يصنف التفاعل اللفظي في عشر فئات. كلام المعلم غير المباشر: تقبل المشاعر، والمدح والتشجيع، وتقبل أفكار الطلاب والبناء عليها، وطرح الأسئلة. وكلامه المباشر: الشرح، وإعطاء التوجيهات، والنقد وتبرير السلطة. ثم فئتا كلام الطلاب، وفئة الصمت أو الفوضى.","vxq2zd":"مستويات القياس عند ستيفنز أربعة: الاسمي يصنف ويسمي فقط، والرتبي يرتب دون أن تتساوى المسافات بين المراتب، والفتري تتساوى مسافاته وصفره اعتباري، والنسبي له صفر حقيقي. والترتيب الأول والثاني والثالث لا يبين كم يزيد الأول على الثاني، فهو رتبي.","3o4sho":"لا تصح عبارة «ضعف» أو «نصف» إلا في المستوى النسبي، لأن له صفراً حقيقياً يعني انعدام الصفة، كالوزن والطول والزمن. والفتري مسافاته متساوية لكن صفره اعتباري، فلا نقول إن 40 درجة مئوية ضعف حرارة 20. والرتبي يرتب فقط، والاسمي يصنف فقط.","1e0h9s4":"درجات الاختبارات التحصيلية تعامل معاملة المستوى الفتري، وصفرها اعتباري: يعني أن الطالب لم ينجح في فقرات هذا الاختبار بعينه، لا انعدام المعرفة كلها. ولهذا لا نقول إن درجة 2 ضعف درجة 1 في التحصيل. والدرجة تقارن بغيرها، وليست اسمية لأنها ترتب وتجمع.","1vgak21":"الرقم هنا اسم يميز اللاعب، ولا يدل على مقدار ولا على تفوق؛ فاللاعب رقم 10 ليس أفضل من رقم 2، ولا معنى لجمع الأرقام. ومثله رقم الهوية ورقم الجوال. أما الرتبي فيرتب، والفتري والنسبي يقيسان مقداراً.","6u1q9m":"هي ما يحتاجه الفرد ليعمل ويعيش بنجاح في هذا العصر، مثل التفكير الناقد والتواصل والتعاون.","kedp79":"ضبط الانفعال والعلاقات الجيدة يساعدان على التركيز والمثابرة، والدراسات تشير إلى ارتباط إيجابي بينهما.","d8v201":"كلما رُبطت المعلومة بالمعنى وبما يعرفه الطالب زاد عمق معالجتها وبقيت أطول.","ye8tq":"انتشار الأثر يعني أن الأثر السار لا يقف عند الرابطة التي أحدثته، بل يمتد إلى ما يجاورها ويرتبط بها، وهنا امتدت متعة تجربة واحدة إلى العلوم ثم إلى التخصص.","l5y7wo":"ضبط الانفعال ومعالجة الموقف بهدوء وعلى انفراد من سمات الاتزان الانفعالي.","1f6dusy":"ربط مصير الأفراد ببعضهم هو الاعتماد المتبادل الإيجابي عند جونسون وجونسون.","1b6b53v":"عند أوزوبل تُقدَّم الأفكار العامة أولاً ثم تتفرع تدريجياً إلى تفاصيلها.","1nd3bc":"أثر التنمر الإلكتروني مكتوب أو مصور، فيمكن الاحتفاظ به دليلاً عند التعامل مع الحالة.","1b7w4s9":"الذاكرة العاملة محدودة السعة، فالتقسيم يخفف ما تعالجه في اللحظة الواحدة.","5pvtx9":"مراحل التصميم التعليمي تشمل التحليل والأهداف والاستراتيجيات والتقويم، أما تحديد صعوبات فردية بعد الاختبار فإجراء تشخيصي يعقب التدريس، وليس مرحلة في تصميمه.","fdcswv":"الاعتذار المختصر قدوة في تحمل المسؤولية، ولا يضيع وقت الحصة.","1w0qek9":"التفاعل والنقاش وتوزيع الأدوار سمات المدخل الاجتماعي، فالتعلم هنا يحدث مع الآخرين.","1wtl0p0":"المدخل البيئي يجعل البيئة المحلية للمتعلم ومشكلاتها منطلق التعلم ومجاله، فيرى الطالب المحتوى فيما حوله ويعمل فيه. ويخلط بعضهم بينه وبين المدخل الاجتماعي لأن في الموقف نقاشاً، لكن الاجتماعي (باندورا وفيجوتسكي) يقوم على التفاعل بين المتعلمين ونمذجة السلوك، والمحور هنا البيئة لا التفاعل.","1ior0l4":"مؤشر 1.2 للممارس يطلب توظيف خبرات ومواقف وأنشطة تعليمية تدعم الاعتزاز بالتراث؛ المقابلة والتوثيق والعرض خبرة نشطة يبني فيها الطالب الاعتزاز بنفسه، بينما الصور والمحاضرة والمطوية تعرض التراث دون إشراك فعلي.","1xwtdxv":"يوم التأسيس (22 فبراير) لذكرى تأسيس الدولة السعودية الأولى عام 1139هـ (1727م). ذكرى التوحيد هي اليوم الوطني (23 سبتمبر)، والعلم له يوم العلم (11 مارس).","13toup7":"مؤشر 3.2: يستخلص أبرز معوقات التواصل مع أولياء الأمور ويشارك في التغلب عليها. المعوق هنا الوقت، وعلاجه المرونة في القنوات والمواعيد.","m49vob":"ربط التواصل بالمشكلات فقط يولّد لدى الأسرة تجربة سلبية فتتجنب المدرسة. البدائل الأخرى حلول لا معوقات.","11847ml":"مؤشر 3.3: يتقصى القضايا المحلية ويوظفها في التدريس بصورة تعزز وظيفة المعرفة؛ أي يستخدم الطالب المعرفة الرياضية لفهم مشكلة واقعية واقتراح حل. البدائل الأخرى تفصل القضية عن هدف الدرس.","14bpf5b":"توظيف القضية يخدم الهدف التعليمي ويراعي المرحلة والقيم؛ الإثارة والجدل ليسا معياراً، والبعد عن بيئة الطالب يناقض فكرة القضية المحلية.","16uyigp":"مؤشر 5.1: يبين تأثير الأحداث اليومية الضاغطة على التعلم وكيفية التعامل معها؛ البداية احتواء فردي يحفظ السرية ثم الإحالة للمختص. التشهير والعقاب والتأجيل تفاقم المشكلة.","1l5au06":"العلامة التحذيرية هي التغير المفاجئ عن المعتاد؛ أما الميل للأقران في المراهقة وحب السؤال عند الصغار فسلوك نمائي طبيعي.","1422m6e":"الانتقال حدث ضاغط شائع؛ والدعم يكون بالتعريف والزميل المرافق والإشراك المتدرج. الإحالة المباشرة للجنة سابقة لأوانها، والعرض أمام الصف قد يزيد قلقه.","fi9lio":"الإهمال عدم توفير حاجات الطالب الأساسية أو التقصير فيها (الجسدية والصحية والعاطفية والتعليمية...) كما عرفته قواعد السلوك والمواظبة، وعلاماته تتعلق بهذه الحاجات؛ والبقية سلوكيات قد تكون نمائية.","1r7pvyq":"المادة 29: إبلاغ مركز بلاغات وزارة الموارد البشرية والتنمية الاجتماعية (رقم 1919) فوراً إذا تطلبت الحالة تدخلاً عاجلاً، إضافة إلى الجهات الأمنية إذا اقتضى الأمر.","1f06w3n":"نصت المادة 29 على أن إجراءات الإيذاء لا تتطلب التدرج بل تُتخذ وفقاً لخطورة الحالة، بشكل عاجل وسري يضمن سلامة الطالب ويمنع تفاقم الحالة.","1xdadf6":"مؤشر 5.2: يميز الاختلافات العائدة للخلفيات الاجتماعية والاقتصادية واحتياجاتها التعليمية التي ينبغي تلبيتها؛ وتلبيتها بتوفير البدائل والمصادر، لا بالعقاب ولا بإعفاء يحرم الطالب من التعلم.","1icbsx1":"التدريس المستجيب ثقافياً يجعل ثقافة الطالب وخبرته جسراً للتعلم مع الحفاظ على توقعات عالية؛ خفض التوقعات قالب نمطي، وتجاهل التنوع يحرم الطالب من الربط.","nd9hkm":"تكافؤ الفرص في الإطار الوطني: فرص متكافئة ومتنوعة تراعي الفروق الفردية والقدرات والخلفيات الثقافية والاجتماعية لجميع الفئات؛ والتطابق في المعاملة ليس تكافؤاً.","1d6utx1":"نص الدليل التنظيمي على أن القياس والتشخيص يتم بعد أخذ موافقة ولي الأمر خطياً وإشعاره رسمياً بالإجراءات؛ فالأسرة شريك أساسي.","1vli8ns":"تتكون لجنة الخطط التعليمية في الدليل التنظيمي للتربية الخاصة من: قائد المدرسة رئيساً، ووكيلها للشؤون التعليمية نائباً للرئيس، ومعلم التربية الخاصة، ومعلم التعليم العام، والمرشد الطلابي أو الأخصائي الاجتماعي، والمختصين حسب الحاجة، وولي الأمر أو من ينوب عنه، والطالب قدر الإمكان. ولم يرد فيها المشرف التربوي.","1d8fx5o":"الخطة الفردية تبدأ بوصف مستوى الأداء الحالي المستخلص من نتائج التشخيص، ومنه تُشتق الأهداف طويلة المدى ثم قصيرة المدى القابلة للقياس.","hkvoeo":"من مبادئ كين وكين: التعلم يتعزز بالتحدي ويُكبح بالتهديد، والانفعالات أساسية في التعلم، والدماغ يعالج الأجزاء والكل معاً؛ ومنها عنصر الاسترخاء اليقظ.","1bq0q5c":"العناصر الثلاثة: الاسترخاء اليقظ (بيئة آمنة متحدية)، والانغماس المنظم (خبرات حقيقية غنية)، والمعالجة النشطة (تأمل وتلخيص وتطبيق يثبت المعنى).","1hov45p":"المعتمد على المجال يدرك كلياً ويتأثر بالمحيط ويفضل التوجيه والعمل الجماعي، والمستقل يحلل ويفصل الجزء عن الكل ويفضل العمل الفردي. والتروي والاندفاع بُعد آخر (كاجان).","13vhk78":"الأسلوب المندفع يستجيب بسرعة وبأخطاء أكثر، ويُعالج بتعليم التوقف والتفكير وفحص البدائل وتمديد وقت الانتظار، لا بالعقاب أو التصنيف.","1wfhr8u":"نموذج دن ودن يربط أسلوب التعلم بعناصر بيئية (الصوت، الإضاءة) وانفعالية (المثابرة، الحاجة إلى التنظيم) واجتماعية وجسمية ونفسية؛ ومؤشر 5.3 يطلب بيان اعتماد أساليب التعلم على العوامل المعرفية والانفعالية والبيئية.","1jls3a4":"التحكم بالتهور من عادات العقل عند كوستا وكاليك: التأني والتفكير وفهم المهمة قبل البدء.","1k3nyaa":"المثابرة: الاستمرار في المهمة حتى إكمالها وعدم الاستسلام بسهولة وتجريب بدائل.","flsfij":"عادات العقل عند كوستا وكاليك ميل لتوظيف السلوك الذكي عند مواجهة مشكلة غير معروفة الحل، وهي قابلة للتعلم والتنمية بالنمذجة والممارسة.","1k50say":"مؤشر 5.3: يبين تأثير الاتجاهات والقيم على التعلم وكيفية استخدامها لدعمه؛ الاتجاه السلبي يُعدّل بخبرات نجاح وربط بالحياة، لا بالوعظ أو المقارنة أو خفض التوقعات.","ho36mt":"للاتجاه ثلاثة مكونات: معرفي (معتقدات وأفكار)، ووجداني (مشاعر)، وسلوكي (ميل للفعل).","1frzxcz":"مؤشرات 7.1 للممارس تتناول أسس المدخل السلوكي والمعرفي والإنساني أو الشخصي والاجتماعي؛ البقية طرق تدريس أو أنماط عمل أو أنواع تقويم.","1sb2pph":"نص مؤشر 7.1: يحدد الأسس والمبادئ النظرية للمداخل ويبرز أهميتها في تحفيز المتعلمين وتنمية مهاراتهم وقدراتهم وتعديل سلوكهم وتنمية مهاراتهم الاجتماعية.","chnpy6":"تحليل المهمة إلى خطوات صغيرة والتعزيز الفوري والتعلم للإتقان من أسس المدخل السلوكي الذي يركز على تعديل السلوك واستجابة المتعلم للمهام.","18ohill":"المدخل المعرفي يستند إلى أساليب تمكّن المتعلم من التفكير والبحث والاكتشاف ذاتياً والتوصل إلى المعارف بجهده (مؤشر 7.1).","1s31fgm":"المنظم المتقدم (أوزوبل) من نماذج المدخل المعرفي الذي يهتم بالعمليات العقلية وتنظيم المعرفة وربطها بالخبرة السابقة.","1q53c63":"المدخل الإنساني أو الشخصي يعنى بتأثير الجوانب الوجدانية والشخصية على التعلم، ويشجع الاستقلالية المنتجة والوعي بالذات والإحساس بالمسؤولية؛ ومن نماذجه التدريس غير الموجه لروجرز.","19is0iq":"روجرز رائد علم النفس الإنساني وصاحب التدريس غير الموجه. باندورا للتعلم الاجتماعي، وبلوم للتعلم للإتقان، وأوزوبل للتعلم ذي المعنى والمنظم المتقدم.","1v6djmz":"المدخل الاجتماعي يوظف نمذجة السلوك والتفاعل بين المتعلمين لدعم النظم التفاعلية وبناء ثقافة صفية إيجابية (مؤشر 7.1)، ويستند إلى التعلم الاجتماعي لباندورا.","owumpd":"العرض العملي يناسب التجارب الخطرة أو التي لا تتوفر أدواتها للجميع، ويجمع بين الأداء والشرح؛ وتنفيذ تجربة فيها مادة قابلة للاشتعال في المنزل أو في مجموعات يعرض الطلاب للخطر.","1aejwno":"نجاح العرض العملي يتطلب تجريبه مسبقاً، وتوضيح هدفه، وضمان رؤية الجميع، والأداء خطوة خطوة ببطء مع الشرح.","1p916v5":"شروط بوسنر وزملائه: عدم الرضا عن التصور الحالي، ثم أن يكون المفهوم الجديد واضحاً ومعقولاً ومثمراً.","1od94fg":"كشف التصور القبلي ثم تقديم حدث يخالف التوقع يولد عدم الرضا (التناقض المعرفي) الذي يمهد لتبني المفهوم العلمي؛ وهي استراتيجية توقع – لاحظ – فسر.","1c1w96v":"التصميم العكسي يبدأ بالنتائج المرغوبة ثم أدلة التقويم ثم خبرات التعلم؛ وهو تطبيق لمؤشر 8.1: ربط أهداف التعلم بمعايير المنهج في تسلسل منطقي.","rhz6qu":"الإطار الوطني: معايير المحتوى وصف عام لما ينبغي أن يتعلمه المتعلم في كل مجال، ومعايير الأداء تمثل نواتج التعلم المتوقعة بعد دراسته المجال في نهاية كل صف أو مستوى.","1meu2i5":"المحاذاة تعني أن الهدف والنشاط والتقويم تقيس الشيء نفسه وبالمستوى نفسه؛ «يقارن» أعلى من «يذكر» فلا يقيسه سؤال تذكر، و«يقارن» فعل قابل للقياس.","1x8gtve":"من شروط اختيار المصدر: الدقة العلمية والحداثة وموثوقية الناشر وخلوه من المحتوى غير المناسب؛ والجاذبية وحدها ليست معياراً (مؤشر 8.1).","1yfaftl":"المصدر وسيلة لتحقيق الهدف، فارتباطه بالهدف أول الشروط، ثم مناسبته للمتعلمين ودقته وإتاحته وأمانه وتكلفته.","n2387t":"من شروط اختيار المصادر الإتاحة وسهولة الوصول لجميع الطلاب وملاءمتها للإمكانات المتاحة؛ والتجريب المسبق والبديل يضمنان تحقيق الهدف للجميع.","1s6e6k5":"التعليم الشامل يغير النظام نفسه ليناسب الجميع ويعد التنوع أمراً طبيعياً، بينما الدمج يُلحق الطالب بالنظام القائم ويطلب منه التكيف.","10mghsq":"التصميم الشامل للتعلم من ممارسات التعليم الشامل: وسائل متعددة للتمثيل وللتعبير والأداء وللمشاركة والتحفيز، يُخطط لها من البداية لا بعد ظهور المشكلة.","u9dz7f":"مؤشر 8.4 الأول: خبرات تستهدف تنمية الأولويات المتصلة بالمواطنة المسؤولة ومكانة المملكة الريادية والتنمية المستدامة؛ البديل الثاني من القيم، والثالث من المهارات.","1sxgmme":"ترشيد الموارد والحفاظ عليها للأجيال القادمة من صور التنمية المستدامة، وهي إحدى الأولويات في مؤشر 8.4.","1ap36y5":"نص مؤشر 8.4: يراعي عند تطبيق الأنشطة تنمية قيم تقوى الله، والوسطية والاعتدال، وتقدير الذات، والشغف المعرفي، وتقدير العمل وإتقانه، والمسؤولية.","redn15":"الشغف المعرفي حب الاستطلاع والرغبة الذاتية في المعرفة والبحث، ويُنمّى بالأسئلة المفتوحة والمشروعات البحثية.","1yxqvc5":"تجويد العمل ومراجعته حتى يبلغ أفضل صورة تجسيد لقيمة تقدير العمل وإتقانه.","11p29bh":"الاعتماد على الذات ينمو حين يتولى الطالب التخطيط والتنفيذ والتقويم بنفسه، مع دعم يتلاشى تدريجياً.","i6zstu":"مؤشر 8.4: يقدم أنشطة ومهام تساعد المتعلمين على استخدام استراتيجيات تنمي المهارات المحددة في إطار المناهج، ومنها حل المشكلات بخطواته.","mfyauf":"مؤشر 9.2 للممارس: يتراجع عن الخطأ ويصححه عند حدوثه؛ والاعتراف يعزز الثقة ويعلّم الأمانة العلمية ولا ينقص من مكانة المعلم.","1i4l8w3":"مؤشر 9.2: يبقي علاقته مع المتعلمين ضمن حدود العلاقات المهنية؛ التوجيه للقنوات المعتمدة يحفظ الحدود دون جرح الطالب، والأمور الخاصة مجالها الموجه الطلابي.","cs1fz5":"من أدوار المعلم في القواعد: تمثيل القدوة الحسنة في القول والفعل وتعزيز الانضباط الذاتي؛ أما توثيق درجات السلوك وحسم المواظبة فمن أدوار إدارة المدرسة، وقرار النقل تصدره الجهة المختصة في إدارة التعليم.","x1ty6o":"التأخر في الدخول إلى الحصص من مشكلات الدرجة الأولى، والإجراء الأول فيها التنبيه الشفهي من المعلم بأسلوب تربوي؛ وللمعلم مباشرة الإجراءات الثلاثة الأولى منها.","spk3as":"الدخول أو الخروج من الفصل دون استئذان من مشكلات الدرجة الثانية، وعلى المعلم رصد مشكلات الدرجة الثانية فأعلى التي باشرها وتسليم الأسماء للإدارة التي تتخذ الإجراءات؛ وإقصاء الطالب خارج الصف ممارسة ممنوعة.","10aw4bc":"من الممارسات غير التربوية الممنوعة: الإيذاء الجسدي أو النفسي، التسبب في انقطاعه عن التعليم، حرمانه من الإفطار، تكليفه بنسخ الواجب عدة مرات كعقاب، استفزازه، السخرية منه، وإقصاؤه خارج الصف.","2e4yqx":"مؤشر 9.3: يتأكد من جاهزية مصادر التعلم وإمكانية وصول جميع المتعلمين إليها؛ والتناوب المنظم يحقق العدالة والإتاحة.","1tmfcmr":"جاهزية المصدر تعني التأكد منه قبل الحصة ووجود خطة بديلة تحفظ وقت التعلم.","je75hp":"عند الإنذار تُنفذ خطة الإخلاء فوراً بهدوء وعبر المسار المحدد دون الانشغال بالأغراض، ثم يُتحقق من عدد الطلاب في نقطة التجمع.","1a3rxw8":"مؤشر 9.3: يهيئ البيئة التعليمية بطريقة تحقق عوامل الأمن والسلامة؛ وفي المختبر تسبق التعليماتُ وأدواتُ الوقاية ووسمُ المواد والإشرافُ الدائم أيَّ تجربة.","4j2t88":"المادة 30: التعامل مع الحالة بهدوء وأخذ أقوالها بجدية، وتجنب الضغط عليها بكثرة الأسئلة، ووضعها في مكان آمن وعدم تركها بمفردها، ومراعاة خصوصيتها، وتبليغ الجهات المختصة فوراً.","94c039":"وفق قواعد السلوك والمواظبة (الإصدار الخامس 1447هـ، المادة 5) تُخصص 100 درجة لمادة السلوك من الصف الثالث الابتدائي إلى الثالث الثانوي: 80 للسلوك الإيجابي يستحقها الطالب تلقائياً بداية كل فصل وتُحسم منها المخالفات، و 20 للسلوك المتميز الذي يعكس القيم الإسلامية والهوية الوطنية. أما الصفان الأول والثاني الابتدائي فتقديرهما كيفي.","oaj6b3":"تُحسم درجة واحدة من درجات المواظبة عن غياب كل يوم دراسي بدون عذر؛ ويُحرم الطالب من الانتقال إذا تجاوز غيابه بدون عذر 10% من أيام العام.","1qwn5bm":"نصت الأحكام العامة على عدم إشراك الموجه الطلابي في رصد درجات السلوك ولا في تنفيذ الإجراءات أو حسم درجات المواظبة، والاكتفاء بدوره في دراسة الحالة وعلاجها.","gaptp4":"التقويم غير الرسمي يجري تلقائياً أثناء التدريس دون درجة وغرضه تعديل التدريس فوراً، وتعديل الشرح داخل الحصة دورة تقويم قصيرة المدى (مؤشر 10.1).","1gr3fcu":"التقويم الرسمي مخطط ومنظم وموثق بشروط محددة ويُبنى عليه حكم؛ البقية أساليب غير رسمية تجري ضمن التدريس.","1fui3dp":"نصت الإجراءات التنفيذية على 60 درجة للتقويمات التكوينية بحسب أدوات التقويم ووحدات المقرر، و40 درجة لاختبار نهاية كل فترة دراسية.","1a95zfw":"شرطا النجاح في المقرر بالمرحلة الثانوية: النهاية الصغرى (50%)، والنسبة الشرطية (20% من درجة الاختبار التحريري نهاية الفترة)؛ و20% من 40 = 8 درجات و6 أقل منها، فلا يُعد ناجحاً رغم تجاوز مجموعه 50، ويُختبر في الدور الثاني الذي لا تُطبق فيه النسبة الشرطية.","1cboklk":"نصت الإجراءات التنفيذية على أنه إذا كانت قراءة الأسئلة مشكلة لدى طالب صعوبات التعلم فيجب أن تُقرأ له بصوت عال؛ والتسهيل يغير طريقة الأداء لا المستوى المقيس.","wpah1f":"نصت القاعدة السابعة على ألا يُختبر الطالب ذو الإعاقة في أكثر من مادة تحريرية في اليوم الواحد مع إعطائه الزمن المناسب وتقديم الدعم، ويتولى معلم التربية الخاصة الإشراف على تقويمه بالتعاون مع معلم التعليم العام.","2yuh1e":"نصت الإجراءات على ألا يتأثر تقويم الطالب الأصم بالتركيب البنائي للغته المكتوبة، وعدم محاسبته على الأخطاء الإملائية أو النحوية في جميع المواد.","o7hsr3":"نصت القاعدة السابعة لذوي فرط الحركة وتشتت الانتباه على توزيع محتوى الاختبار على فترات قصيرة، والسماح بالتوقف والتحرك، والاختبار في ركن خاص بعيداً عن المشتتات.","1wxplow":"انخفاض الإتقان لدى أغلب الصف في معيار بعينه مؤشر على حاجة التدريس نفسه إلى التعديل؛ أما انخفاضه لدى قلة فتعالجه خطط فردية (مؤشر 10.3: استخلاص المؤشرات الأساسية للأداء وتوظيفها).","175zkek":"نصت الإجراءات على أن يدون المعلم تقويمه بشكل يومي في سجل متابعة تقويم الطالب، ثم يرصد خلاصة تقويمه وملحوظاته في النظام الرقمي نهاية الفترة موثقة بشواهد في ملف إنجاز الطالب.","1akwrxe":"التنسيق الشرطي يلوّن الخلايا وفق شرط محدد (مثل أقل من 75%)، فيستخلص المعلم بسرعة الطلاب والمعايير المحتاجة إلى علاج."};
